do
    local saved = U.readJson(C.SETTINGS) or {}
    if saved.shareChosen ~= true then saved.shareStats = nil end
    for k, v in pairs(C.DEFAULTS) do
        if saved[k] ~= nil and type(saved[k]) == type(v) then CFG[k] = saved[k] else CFG[k] = v end
    end
    CFG.seenVersion = type(saved.seenVersion) == "string" and saved.seenVersion or nil
    -- (Griffin Watch became Banner Snipe, Nov 2: a watch that was on carries on as a snipe for Griffin)
    if saved.griffinWatch == true and saved.snipeUnit == nil then CFG.snipeOn, CFG.snipeUnit = true, "griffith" end
    -- (the portal pick's old "off" became the Portals switch)
    if CFG.pickPortal == "off" then CFG.portals, CFG.pickPortal = false, "smart" end
    CFG.cfgv = 1
    -- the simple window has one switch for playing (Smart Farm) and shows no per-mode switches, so they all go back on
    -- once. A farm that wasn't playing stays stopped until you switch it on
    if not CFG.simpleGui then
        CFG.simpleGui = true
        if not CFG.play then CFG.master = false end
        CFG.play = true
        for _, k in ipairs({ "dailyChallenge", "challenge", "firstClears", "raids", "event", "farm", "infinite", "dungeon" }) do CFG[k] = true end
    end
end
