    B.spend = tbl(b.spend) or {}         -- spend history {at, what, cost, cur, why}
    B.totals = tbl(b.totals) or { wins = 0, losses = 0, gems = 0, coins = 0, matches = 0 }
    B.pending = tbl(b.pending)           -- mode the farm launched (the match reads it)
