    B.claims = tbl(b.claims) or {}       -- [questUuid / milestone] = time claimed (no double claims)
    B.portalPay = tbl(b.portalPay) or {} -- [portal item] = {n, per}: its item a portal run; ["drop:" .. portal item] = {n, per}: portals an Infinite run of the map that drops them
    B.watch = tbl(b.watch)               -- {key, portal, item, have, held, at}: what a launched portal or portal map run is measured against back in the lobby
    B.portalMods = type(b.portalMods) == "string" and b.portalMods or nil -- what the last opened portal had beyond its plain level (HUB.launchPortal), for the portal record
    B.cleared = tbl(b.cleared) or {}     -- ["level:diff"] = time won (the match's copy of the profile lags)
    B.simCal = tbl(b.simCal) or {}       -- [modeKey] = what matches measured: wave length, walk speed, HP vs formula, yen, base, HP alive per wave
    -- (once: the formula now has Hard's ×2 for Infinite maps, so their measured HP factor halves and the HP the sim plays stays the same — Nov 2)
    B.infHard = b.infHard
    if not B.infHard then
        for key, cal in pairs(B.simCal) do
            if type(cal) == "table" and tostring(key):match("^inf:") and tonumber(cal.hpCal) then cal.hpCal = cal.hpCal / 2 end
        end
        B.infHard = true
    end
    B.maps = tbl(b.maps) or {}           -- [map] = road coverage of the best spot per range (sim placement)
    -- sim results made by an older simulator model are dropped (the model changed, they would mislead)
    local simV = 3
    local fresh = tonumber(b.simVer) == simV
    B.simVer = simV
    B.simRes = fresh and tbl(b.simRes) or {}       -- [modeKey] = last sim of your team {won, wave, p, sig, at}
    B.simTeam = fresh and tbl(b.simTeam) or {}     -- [modeKey] = best team the planner found {uuids, wave, won, cur, at}
    B.simEvo = fresh and tbl(b.simEvo) or {}       -- evolutions with their simulated gain
    B.trainSim = fresh and tbl(b.trainSim) or {}   -- [modeKey] = training team the sim checked {sig, ok, why, uuids, out, tk, minutes, slow, at}
    -- takedown training: on = the training team equipped now {uuid, id, to, what, have, need, got, base, uuids, out, key},
    -- real = [modeKey] = {n, sum} takedowns measured per run, bad = [modeKey] = no training there until, log = last runs
    B.train = tbl(b.train) or {}
    B.train.real = tbl(B.train.real) or {}
    B.train.bad = tbl(B.train.bad) or {}
    B.train.log = tbl(B.train.log) or {}
    B.train.cal = tbl(B.train.cal) or { real = 0, sim = 0, n = 0 } -- real vs simulated takedowns over trained runs
    B.savedTeam = tbl(b.savedTeam)       -- your own team, kept while a planned team is equipped
    B.goals = tbl(b.goals) or {}         -- the path: evolution goals ranked {from, to, gain, plan, runs, ...}
    B.goalsTop = tbl(b.goalsTop) or {}   -- the Path tab's list: the 10 strongest evolutions, plus your focus (ADV.refresh)
    B.goalItems = tbl(b.goalItems) or {} -- [itemId] = gem value it has because a top goal needs it
    B.goalNeed = tbl(b.goalNeed) or {}   -- [itemId] = how many of it those goals still need
    B.raidShop = tbl(b.raidShop) or {}   -- [key] = {id, costItem, cost, stock} (lobby raid shop, cached)
    B.lb = tbl(b.lb)                     -- limit break requirement from the server {requirement, allowed}
    B.hidden = tbl(b.hidden) or {}       -- [unitId] = true: the lobby has no upgrade stats for it (UNIT.markHidden)
    B.unitData = tbl(b.unitData) or {}   -- [unitId] = {upgrade, spawn_cap, ...} the server sent in a match (UNIT.capture)
    B.codes = tbl(b.codes) or {}         -- [code] = last time the farm tried it (HUB.codes)
    B.stack = tbl(b.stack) or {}         -- [buffAttackId] = {stacks, cap, before, after, at}: does a 2nd copy's buff add up (MT.actives)
    B.ownSwap = tbl(b.ownSwap)           -- {out, into, at}: one change to your own team, on your word, waiting for the game to answer (HUB.ownSwap)
    B.snipe = tbl(b.snipe) or {}         -- Banner Snipe: {unit, pulls, got, featured, feat = {banner = ids}, seen = {id = {banner, at}}, lookAt, askAt, changedAt, clock = {next, at}, note, noteAt, compass} (HUB.bannerSnipe)
    B.snipe.seen = tbl(B.snipe.seen) or {}
    -- (a clock set by the hourly countdown is wrong: only a "banner changed" sets it now)
    if type(B.snipe.clock) == "table" and B.snipe.clock.src ~= "changed" then B.snipe.clock = nil end
    B.zoneRec = tbl(b.zoneRec) or {}     -- [mode key:map] = {style, zone, won, at, lost = {[style] = {at, sig}}}: how this map was last played (fast, balanced or box), how that went, and which ways lost here with which team (MT.planSpots, SIM.zoneChoice)
    B.fh = tbl(b.fh) or {}               -- dealt-team runs (Fool's Hunt): runs = last 20 {at, wave, coins, top}, units = [unitId] = {n, share}
    B.hunt = tbl(b.hunt) or {}           -- Summer Hunt: runs = last 20 {at, wave, won, pearls, mult, map, weather}, pmin = the strength floor for taking a hard card
    B.fh.runs = tbl(B.fh.runs) or {}
    B.fh.units = tbl(B.fh.units) or {}
    B.nextMode = type(b.nextMode) == "string" and b.nextMode or nil -- a mode key played next, once (MODE.pick)
    B.infResults = tonumber(b.infResults) or 0   -- Infinite runs whose result fields were logged (the first 3)
    B.infLive = b.infLive == true or nil         -- Infinite's daily gems were seen claimed during a run (not only at the end)
    -- dungeon: sim = [room seed] = {p, wave, sig}, depth = [band "1".."4"] = {runs, wins}, log = last actions,
    -- seen = [state signature] = time first logged, buyArg = how dungeon_buy_shop takes an item ("key" / "id"), runs = finished runs
    B.dg = tbl(b.dg) or {}
    B.dg.sim = tbl(B.dg.sim) or {}
    B.dg.depth = tbl(B.dg.depth) or {}
    B.dg.log = tbl(B.dg.log) or {}
    B.dg.seen = tbl(B.dg.seen) or {}
    B.dg.runs = tbl(B.dg.runs) or {}
    -- team strength: each unit's real share of a match's damage, the core units, what the Team tab does next, what it did
    B.str = tbl(b.str) or {}
    B.str.share = tbl(B.str.share) or {}
    B.str.core = tbl(B.str.core) or {}
    B.str.log = tbl(B.str.log) or {}
    B.str.noWork = tbl(B.str.noWork) or {} -- [kind or kind:uuid] = time: not asked again until then (refused, or it changed nothing)
    B.lastRun = tbl(b.lastRun)
    B.holdLobby = tbl(b.holdLobby)       -- {why, at}: the farm stops in the lobby and starts nothing until this is cleared
    B.relicOff = tbl(b.relicOff) or {}   -- [unit uuid] = relic uuid: taken off for a borrowed team (HUB.relicClash), back with your own team
    B.buyStorage = tbl(b.buyStorage)     -- {maxGold, at}: your go-ahead for one step of unit storage, tried once in the next lobby (HUB.buyStorage)
    B.buyOnce = tbl(b.buyOnce)           -- {item, cur, max, why}: your go-ahead for one shop item, bought once in the next lobby (HUB.buyOnce)
    B.toggles = tbl(b.toggles) or {}     -- [unitId] = {from, fill, drain, nf, nd, at}: switch abilities with a bar seen in matches (MT.learnToggle)
    B.unitSent = tbl(b.unitSent) or {}   -- [unitId] = when this farm sent the hidden stats it learned to the brain hive (REPORT.sendUnit; -1: too big for one post)
    B.startTeam = tbl(b.startTeam)       -- {home | uuids, why}: a team change to make in the next match, before its first wave (MT.startTeam)
    B.trial = tbl(b.trial)               -- {key, level, diff, label, list = unit ids, i, results}: one real run per unit, to read its real damage (MODE.trialRow)
    B.lastSuggest = tonumber(b.lastSuggest) or 0
    B.anonId = type(b.anonId) == "string" and b.anonId or Http:GenerateGUID(false):gsub("-", ""):sub(1, 10):lower()
    B.hiveQueue = tbl(b.hiveQueue) or {}
    B.hiveN = tonumber(b.hiveN) or 0     -- brain hive match records written (REPORT.match: 500 a file)
    B.aaHiveQ = tbl(b.aaHiveQ) or {}     -- match records waiting for the Brain Hive's Discord channel (JSON strings, REPORT.sendHive)
    B.hiveSent = tonumber(b.hiveSent) or 0
