-- (the Summer update took the difficulty math off the client. These are its last public numbers, and the real runs' calibration corrects whatever moved since)
C.LU = C.core("LevelUtil") or (function()
    local WORLD = { 1, 1.524259, 2.3760452, 3.7038265, 5.7735984, 9.9, 13.6269783, 16.313749, 21.4345692, 21.4345692, 56.325588, 84.488382, 84.488382, 168.976764, 253.465146, 337.953528, 375, 400, 450, 500, 550, 650 }
    local ACT = { 1, 1.0447, 1.09139809, 1.1401835846, 1.1911497909, 1.3366844723 }
    local MAP = { hxhant = 0.5, magnolia = 0.6, jjk = 0.7 }
    local LU = {}
    function LU.calculate_level_diff_scale(rank, gm, ld)
        if ld and (ld._use_max or ld._is_daily_challenge or ld._is_event_challenge) then return ACT[6] end
        if gm == "story" or gm == "challenge" then return ACT[rank or 6] or ACT[6] end
        return ACT[6]
    end
    function LU.calculate_world_diff_scale(rank, gm, _, map, ld)
        local top = WORLD[#WORLD] * 1.5
        if ld and ld._is_event_challenge then return 0.5 * top end
        if ld and (ld._use_max or ld._is_daily_challenge) then return top end
        local v = WORLD[rank or #WORLD] or WORLD[#WORLD]
        if gm == "story" or gm == "raid" then v = v * ((rank or #WORLD) < 12 and 0.6 or 0.7) end
        return v * 1.5 * (MAP[map] or 1)
    end
    function LU.calculate_world_resource_scale(rank, gm)
        local v = 1.7411011266
        if rank and rank <= 5 and (gm == "story" or gm == "infinite" or gm == "challenge") then v = ({ 1, 1.148698355, 1.3195079108, 1.5157165665, 1.7411011266 })[rank] end
        return v * 1.5
    end
    function LU.calculate_multiplayer_diff_scale(gm, n, ld)
        if ld._event_contract then return 1 end
        if ld._override_multiplayer_diff_scale then return 1 + (n - 1) * ld._override_multiplayer_diff_scale end
        if ld._is_daily_challenge then return 4 end
        if ld._is_event_challenge or ld._no_multiplayer_scale then return 1 end
        if gm == "story" or gm == "challenge" or gm == "infinite" or gm == "infinite_tower" then
            return 1 + (n - 1) * (ld.world == "bleach_legend" and 1 / 6 or (ld.world == "jojo_legend" and 0.3 or 0.6))
        end
        if gm == "raid" then
            if ld.id == "jojo_portal_pucci" then return 0.3 end
            if ld.portal_group or ld._raid_multiplayer_scale then return 1 + (n - 1) * 0.3 end
            return ld.id ~= "namek_anniversary" and 8 or 8 * (1 + (n - 1) * 0.5)
        end
        return 1
    end
    local SCALE = { opm_infinite = 0.8, jojo_infinite = 0.7, sao_infinite = 0.7, berserk_infinite = 0.7, overlord_infinite = 0.7, fate_infinite = 0.7 }
    LU.Infinite = {
        infinite_max_unit_wave = 100,
        initial_wave_template = { wave_reward = 1500, wave_diff_scale = 1 },
        infinite_diff_scale = function(w, id)
            local v
            if w <= 20 then v = math.exp(0.165 * w) * 0.257116 + 0.187431
            elseif w <= 50 then
                if id == "april2_event" then v = math.pow(w - 1, 2.9) / 500 + 2
                elseif id == "halloween2_event" or id == "christmas_event" then v = math.pow(w - 1, 2.4) / 400 + 4.2
                else v = math.pow(w - 1, 2.48) / 400 + 4.2 end
            else v = math.max(32, math.pow(w - 1, 2.8) / 400 - 92) end
            if SCALE[id] then return v * SCALE[id] end
            if id == "halloween2_event" or id == "christmas_event" or id == "april2_event" then
                v = v * 0.85
                if id == "christmas_event" then v = v * 0.75 end
            end
            return v
        end,
        infinite_amt_scale = function(w, ld)
            local v
            if w <= 1 then v = 3 elseif w < 9 then v = math.pow(w - 1, 2) / 5 + 5 else v = math.pow(w - 1, 1.4) / 5 + 15 end
            if ld and ld._tournament and ld._tournament.tournament_id == "3" then v = math.min(v / 3, 5) end
            return math.min(v, 60)
        end,
        infinite_get_normal_unit_chance = function(cfg, w)
            if cfg.min_inf_wave and w < cfg.min_inf_wave then return 0 end
            local tier = cfg.spawn_tier_normal
            if not tier then return 0 end
            local x = math.min(w - 1, 100) / 100
            local a, b
            if tier <= 2 then a, b = 5, 5 elseif tier == 3 then a, b = 3, 6 elseif tier == 4 then a, b = 1, 6 elseif tier <= 7 then a, b = 0, 5 else a, b = 0, 2 end
            return a + (b - a) * x
        end,
        infinite_get_boss_unit_chance = function(cfg, w)
            if cfg.min_inf_wave and w < cfg.min_inf_wave then return 0 end
            if w <= 10 then return cfg.spawn_tier_boss == 1 and 1 or 0 end
            return cfg.spawn_tier_boss and 1 or 0
        end,
    }
    local core = C.core("LevelUtilCore")
    LU.xp_items_order = core and core.xp_items_order
    return LU
end)()
