C.SaleEvent = C.data("ItemsForSaleEvent") or {} -- the AprilCoins shop (evolve items 5,000 each)
function C.session() return C.GUIS and C.GUIS.session end
function C.prof() local s = C.session(); return s and s.profile_data end
-- a currency right now: the server updates LocalPlayer._stats at once (gem_amount, gold_amount, _resource<Name>);
-- the profile's copy can lag until the next teleport, so spends never read that one
function C.cur(name)
    local st = LP:FindFirstChild("_stats")
    local v = st and ((name == "gems" and st:FindFirstChild("gem_amount")) or (name == "gold" and st:FindFirstChild("gold_amount")) or st:FindFirstChild("_resource" .. name))
    if v then return tonumber(v.Value) or 0 end
    local p = C.prof()
    if name == "gems" then return tonumber(p and p.gem_amount) or 0 end
    if name == "gold" then return tonumber(p and p.gold_amount) or 0 end
    return tonumber(p and p.resources and p.resources[name]) or 0
end
SF.where = (workspace:FindFirstChild("_MAP_CONFIG") and workspace._MAP_CONFIG:FindFirstChild("IsLobby") and workspace._MAP_CONFIG.IsLobby.Value) and "lobby" or "match"

-- ============================================================
--  REQUEST LAYER (one wrapper for every remote: timeout · budget · backoff · log)
-- ============================================================
SF.req = { back = {}, fails = {}, calls = {} }
SF.BUDGET = { upg = 30, place = 15 } -- calls per 10 s per key (default 8)
-- returns ok (the call ran), a, b. A RemoteFunction with no handler on this server never answers, so
-- every call has a timeout and a lobby-only remote is never used in a match.
function SF.request(key, name, ...)
    local r = SF.req
    local t = U.now()
    if r.back[key] and t < r.back[key] then return false, "waiting" end
    local q = r.calls[key] or {}
    r.calls[key] = q
    while q[1] and t - q[1] > 10 do table.remove(q, 1) end
    if #q >= (SF.BUDGET[key] or 8) then r.back[key] = t + 3; return false, "slowing down" end
    table.insert(q, t)
    if not (RS:FindFirstChild("endpoints") and RS.endpoints.client_to_server:FindFirstChild(name)) then return false, "no remote " .. name end
    local args = table.pack(...)
    local done, ok, a, b = false, false, nil, nil
    task.spawn(function()
        ok, a, b = pcall(function() return C.EP.invoke_server(name, table.unpack(args, 1, args.n)) end)
        done = true
    end)
    local t1 = U.now()
    while not done and U.now() - t1 < 15 do task.wait(0.05) end
    if not done then
        r.fails[key] = (r.fails[key] or 0) + 1
        r.back[key] = U.now() + 30
        SF.log(1, "NET", name .. " timeout (no answer in 15s)")
        return false, "timeout"
    end
    if not ok then
        r.fails[key] = (r.fails[key] or 0) + 1
        r.back[key] = U.now() + math.min(60, 2 ^ r.fails[key])
        SF.log(1, "NET", name .. " error: " .. tostring(a))
        return false, tostring(a)
    end
    r.fails[key] = 0
    return true, a, b
end
function SF.backoff(key, sec) SF.req.back[key] = U.now() + sec end
-- the game's red messages (its show_message): the reason behind a refusal that only returns false or nothing ("Your collection is full!", "unequip unit first")
function SF.listenGame()
    if SF.heard then return end
    local s2c = RS:FindFirstChild("endpoints") and RS.endpoints:FindFirstChild("server_to_client")
    local ev = s2c and s2c:FindFirstChild("show_message")
    if not ev then return end
    SF.heard = true
    table.insert(SF.conns, ev.OnClientEvent:Connect(function(msg, kind)
        if tostring(kind) == "Error" then SF.gameError = { msg = tostring(msg), at = U.now() } end
    end))
    -- the banners turning over (Banner Snipe), in a match too: the game's countdown and its "a banner changed"
    for _, name in ipairs({ "hatch_refresh_remaining_time_changed", "hatch_banner_changed" }) do
        local e2 = s2c:FindFirstChild(name)
        if e2 then table.insert(SF.conns, e2.OnClientEvent:Connect(function(...) pcall(HUB.snipeHeard, name, ...) end)) end
    end
end
function SF.gameSaid(since)
    local e = SF.gameError
    return e and e.at >= since and e.msg or nil
end

-- ============================================================
--  SPEND HISTORY ("where did my gold go?")
-- ============================================================
function SPEND.add(what, cost, cur, why)
    table.insert(B.spend, 1, { at = os.time(), what = what, cost = cost, cur = cur, why = why })
    while #B.spend > 60 do table.remove(B.spend) end
    SF.log(1, "SPEND", string.format("%s for %s %s — %s", what, U.fmt(cost), cur, why))
    SF.saveSoon()
end
function SPEND.text()
    if #B.spend == 0 then return "nothing spent yet" end
    local rows = {}
    for i = 1, math.min(15, #B.spend) do
        local e = B.spend[i]
        table.insert(rows, string.format("%s  %s — %s %s (%s)", os.date("%b %d %H:%M", e.at), e.what, U.fmt(e.cost), e.cur, e.why or ""))
    end
    return table.concat(rows, "\n")
end

-- ============================================================
--  UNITS: the game's formulas at full growth
-- ============================================================
UNIT._rows, UNIT._mult = {}, {}
-- hidden stats: the game ships about half its Mythic / Secret units without their upgrades (every April,
-- Sakamoto and current banner unit). The server sends them in a match, for the units in it
-- (UnitGameReplicatorClient patches Units[id]); the farm keeps a copy in the brain so the lobby knows them too.
-- A unit it has never seen in a match is "unknown", not weak: no goal value, no smart evolve, no summons for it.
UNIT.KEEP = { "upgrade", "spawn_cap", "primary_attack", "primary_attack_no_upgrades", "active_attack", "active_attack_stats", "farm_amount" }
-- (the game's own numbers first, then what this farm learned in a match, then what other players' farms learned in theirs (the brain hive: the game's numbers too), and the
-- community's data last)
function UNIT.field(id, k)
    local d = C.Units[id]
    if type(d) == "table" and d[k] ~= nil then return d[k] end
    local x = B.unitData[id]
    if x then return x[k] end
    local okH, hs = pcall(REPORT.hiveStat, id)
    if okH and hs and hs[k] ~= nil then return hs[k] end
    local y = C.FILL_UNITS[id]
    return y and y[k]
end
function UNIT.hidden(id)
    local d = C.Units[id]
    if not (type(d) == "table" and d.upgrade == nil and (tonumber(d.cost) or 0) > 0) then return false end
    if (B.unitData[id] and B.unitData[id].upgrade) or C.FILL_UNITS[id] then return false end
    local okH, hs = pcall(REPORT.hiveStat, id)
    return not (okH and hs and hs.upgrade)
end
-- lobby: which units the game shipped without stats (a match checks these for what the server sent)
function UNIT.markHidden()
    local n = 0
    for id, d in pairs(C.Units) do
        if type(d) == "table" and d.upgrade == nil and (tonumber(d.cost) or 0) > 0 then B.hidden[id] = true; n = n + 1 end
    end
    return n
end
-- match: keep the stats the server sent for units the lobby didn't have them for (fresh each match: a balance
-- change updates them)
function UNIT.capture()
    local got = {}
    for id in pairs(B.hidden) do
        local d = C.Units[id]
        if type(d) == "table" and type(d.upgrade) == "table" then
            local keep = {}
            for _, k in ipairs(UNIT.KEEP) do if d[k] ~= nil then keep[k] = U.plain(d[k]) end end
            if not B.unitData[id] then table.insert(got, UNIT.name(id)) end
            B.unitData[id] = keep
            UNIT._rows[id] = nil
        end
    end
    if #got > 0 then
        SF.log(1, "UNITS", "learned the hidden upgrade stats of " .. table.concat(got, ", ") .. " (the game only sends them in a match)")
        SF.saveSoon()
    end
end
-- every upgrade level as a full row (an upgrade only lists what changes)
-- units that don't attack themselves: their damage comes from what they summon (the user pointed at her page, Nov 1). Elyssia: a jelly on her SPA, 3 at most, which explodes on contact for her full damage across about her
-- range. rate: seconds between blasts, as a multiple of her SPA. reach: how far she gets, as a multiple of her range, since jellies walk up the road to meet enemies, so she hits them first. Both fitted to her first real run
-- (Nov 1, Legend Stage 1: 88% of 183.5M, 189 helpers, MT.watchHelpers): reading her page's 1.5x SPA wait as rate 2, reach 2.5 gave her 32% in the sim, and rate 1, reach 4 gives 83%. One run, on a stage weak to her water, so hold it
-- against more. atk: the blast's shape. The game's own attack for her reads as one enemy, and a match sends that name, so once she'd been played she read 91k against 314k
UNIT.SUMMONER = { elyssia = { rate = 1, reach = 4, atk = "elyssia_evolved|live" }, elyssia_evolved = { rate = 1, reach = 4, atk = "elyssia_evolved|live" } }
function UNIT.rows(id)
    if UNIT._rows[id] then return UNIT._rows[id] end
    local d = C.Units[id]
    if type(d) ~= "table" then return nil end
    local rate = UNIT.SUMMONER[id] and UNIT.SUMMONER[id].rate or 1
    local cur = { cost = d.cost or 0, damage = d.damage or 0, cd = (d.attack_cooldown or 0) * rate, range = d.range or 0,
        farm = UNIT.field(id, "farm_amount") or 0, atk = UNIT.field(id, "primary_attack_no_upgrades") or UNIT.field(id, "primary_attack"),
        active = UNIT.field(id, "active_attack") }
    local stats0 = UNIT.field(id, "active_attack_stats")
    cur.activeCd = type(stats0) == "table" and tonumber(stats0.attack_cooldown) or nil
    local rows = { [0] = table.clone(cur) }
    local ups = UNIT.field(id, "upgrade") or {}
    for i, up in ipairs(ups) do
        cur = table.clone(cur)
        cur.cost = up.cost or 0
        if up.damage then cur.damage = up.damage end
        if up.attack_cooldown then cur.cd = up.attack_cooldown * rate end
        if up.range then cur.range = up.range end
        if up.farm_amount then cur.farm = up.farm_amount end
        if up.primary_attack then cur.atk = up.primary_attack end
        if up.active_attack then cur.active = up.active_attack end
        if type(up.active_attack_stats) == "table" and tonumber(up.active_attack_stats.attack_cooldown) then cur.activeCd = tonumber(up.active_attack_stats.attack_cooldown) end
        rows[i] = cur
    end
    rows.max = #ups
    local blast = UNIT.SUMMONER[id] and UNIT.SUMMONER[id].atk
    if blast then for l = 0, rows.max do rows[l].atk = blast end end
    UNIT._rows[id] = rows
    return rows
end
function UNIT.isFarm(id) return C.USC and C.USC.unit_static_is_farm(id) or false end
-- everything one attack does, from Data.Attacks: how many enemies it hits (area shapes: single 1, circle by
-- radius, cone by angle, line by length, whole range 3; `aoe_dot` beams count every tick), damage over time
-- (fire / bleed / decay: damage_rate × seconds, as a share of the hit), crowd control seconds (slow × its %,
-- stun / freeze / knockback), damage-taken debuffs (cursed, hexed, dismember) and buffs for your own units
UNIT._atk = {}
UNIT.CC_COOLDOWN = { slow = 3, stun = 8, freeze = 10, haki_stun = 15, knockback = 30, walk_back = 10, walk_back_time = 10 } -- Data.Buffs buff_cooldown
-- an attack from C.FILL_ATTACKS, in the form the game's table has them
UNIT._fill = {}
-- (a match teaches an attack under the game's own name, "rukia_bankai:one", where the community data has "rukia_bankai|rukia_2:one": same unit, same attack.
-- Unmatched, Snow Reaper (Final)'s circle, cone and full-field attacks all read as hitting one enemy, Nov 2)
function UNIT.fillAlias(atkId)
    local pre, suf = tostring(atkId):match("^(.-):([^:]+)$")
    if not pre or pre:find("|", 1, true) then return nil end
    -- (its own name first; else a form that shares its script: the Final's full-field attack is only under "rukia_bankai_evolved|rukia_2:three")
    local near
    for k, x in pairs(C.FILL_ATTACKS) do
        if k:match(":([^:]+)$") == suf then
            if k:sub(1, #pre + 1) == pre .. "|" then return x end
            if k:sub(1, #pre + 1) == pre .. "_" and k:find("|", #pre + 2, true) then near = near or x end
        end
    end
    return near
end
function UNIT.fillAttack(atkId)
    if UNIT._fill[atkId] ~= nil then return UNIT._fill[atkId] end
    local x = C.FILL_ATTACKS[atkId] or UNIT.fillAlias(atkId)
    local a = false
    if x then
        local shape = x.k == "c" and { type = "circle", radius = x.r } or x.k == "n" and { type = "cone", angle = x.r } or x.k == "f" and { type = "full_aoe" } or x.k == "l" and { type = "straight" } or {}
        local buffs = {}
        if x.slow then table.insert(buffs, { name = "slow", time = x.t, params = { slow_percent = x.slow } }) end
        if x.stun then table.insert(buffs, { name = "stun", time = x.stun, params = {} }) end
        if x.freeze then table.insert(buffs, { name = "freeze", time = x.freeze, params = {} }) end
        if x.knock then table.insert(buffs, { name = "knockback", time = x.knock, params = {} }) end
        if x.amp then table.insert(buffs, { name = "amplify", time = 1, params = { amplification = x.amp, persistent = x.keep } }) end
        if x.dot then table.insert(buffs, { name = x.dot, time = x.ticks, params = { damage_rate = x.rate } }) end
        local hits = x.h or 1
        local list = {}
        -- (the damage shared out over the hits, the effect once)
        for i = 1, hits do list[i] = { aoe_type = shape, hit = { damage = 1 / hits, buffs = i == 1 and buffs or nil } } end
        a = { aoe = list }
    end
    UNIT._fill[atkId] = a
    return a
end
function UNIT.attackInfo(atkId, range)
    local key = tostring(atkId) .. ":" .. tostring(range and math.floor(range) or "")
    if UNIT._atk[key] then return UNIT._atk[key] end
    -- hits: hits one attack lands on a target (a shield loses a point per hit: "multi-hit units shred shields"). bleed: stops regen
    local info = { n = 1, dot = 0, slow = 0, stun = 0, amp = 0, ampPersist = false, hits = 0, bleed = false, slowPct = 0, slowTime = 0 }
    local a = atkId and (C.Attacks[atkId] or UNIT.fillAttack(atkId))
    if type(a) ~= "table" then info.hits = 1; UNIT._atk[key] = info; return info end
    local f = 0
    local function hit(e, ticks)
        if type(e) ~= "table" then return end
        local t = type(e.aoe_type) == "table" and e.aoe_type or {}
        local h = type(e.hit) == "table" and e.hit or {}
        local share = tonumber(h.damage) or 1
        if h.break_shields then info.breakShields = true end
        local n = 1
        if t.type == "target_aoe_circ" or t.type == "circle" or t.type == "circ" then n = 1 + (tonumber(t.radius) or 4) / 5
        elseif t.type == "cone" then n = 1 + (tonumber(t.angle) or 45) / 60
        elseif t.type == "full_aoe" or t.type == "full" then n = 3
        elseif t.type == "straight" or t.type == "line" then n = 1 + (tonumber(t.length) or tonumber(range) or 10) / 15 end
        if not e.hit_allies then
            f = f + share * ticks * math.min(n, 4)
            info.hits = info.hits + ticks
        end
        for _, b in pairs(h.buffs or {}) do
            if type(b) == "table" and type(b.name) == "string" then
                local p = type(b.params) == "table" and b.params or {}
                local time = tonumber(b.time) or 0
                if e.hit_allies then
                    if b.name:find("^damage_buff__") and type(p.damage_types) == "table" then
                        local kinds = {}
                        for k, v in pairs(p.damage_types) do kinds[k] = type(v) == "table" and tonumber(v.rate) or 0 end
                        info.ally = { types = kinds, time = time }
                    elseif b.name == "attack_cooldown_buff" then info.allyCd = { reduce = tonumber(p.attack_cooldown_reduce) or 0, time = time }
                    elseif b.name == "range_buff" then info.allyRange = { add = tonumber(p.range_add) or 0, time = time } end
                else
                    if tonumber(p.damage_rate) then info.dot = info.dot + tonumber(p.damage_rate) * math.max(1, time) end
                    if b.name:find("bleed") or b.name:find("wither") or b.name:find("decay") then info.bleed = true end
                    if b.name == "slow" then
                        info.slow = math.max(info.slow, (tonumber(p.slow_percent) or 0.3) * time)
                        info.slowPct, info.slowTime = math.max(info.slowPct, tonumber(p.slow_percent) or 0.3), math.max(info.slowTime, time)
                    elseif b.name == "stun" or b.name == "freeze" or b.name == "haki_stun" then info.stun = math.max(info.stun, time)
                    elseif b.name == "knockback" or b.name == "walk_back" or b.name == "walk_back_time" then info.stun = math.max(info.stun, time * 0.5)
                    elseif tonumber(p.amplification) then
                        info.amp = math.max(info.amp, tonumber(p.amplification))
                        if p.persistent then info.ampPersist = true end
                    end
                    if UNIT.CC_COOLDOWN[b.name] then info.ccCd = math.max(info.ccCd or 0, UNIT.CC_COOLDOWN[b.name]) end
                end
            end
        end
    end
    for _, e in pairs(type(a.aoe) == "table" and a.aoe or {}) do hit(e, 1) end
    for _, d in pairs(type(a.aoe_dot) == "table" and a.aoe_dot or {}) do
        if type(d) == "table" and type(d.aoe) == "table" then
            hit(d.aoe, (tonumber(d.time) or 1) / math.max(0.1, tonumber(d.interval) or 1))
            -- (a first tick can carry the effect: Shadow Garden's curse)
            if type(d.first_aoe) == "table" then hit(d.first_aoe, 0) end
        end
    end
    -- a plain list of hits on the target (a barrage, a drone's shots)
    for _, e in pairs(type(a.hit) == "table" and a.hit or {}) do
        if type(e) == "table" and e.damage then info.hits = info.hits + 1 end
    end
    -- the rest of what an active ability can do: on the whole map (Time Acceleration, Universal Reality), on itself, on the base
    info.globalCd = a.global_cooldown and true or false
    for _, g in pairs(type(a.global_hit) == "table" and a.global_hit or {}) do
        if type(g) == "table" then
            info.wholeMap = true
            hit({ hit = g, hit_allies = g.hit_allies, aoe_type = { type = "full_aoe" } }, 0)
        end
    end
    for _, group in pairs(type(a.buff) == "table" and a.buff or {}) do
        for _, one in pairs(type(group) == "table" and group or {}) do
            local bc = type(one) == "table" and one.buff_config
            local p = type(bc) == "table" and type(bc.params) == "table" and bc.params or {}
            -- (not Pale Sky's 10×: the unit is gone after its next attack)
            if tonumber(p.damage_add) and not p.persistent then info.selfDmg = { add = tonumber(p.damage_add), time = tonumber(bc.time) or 0 } end
        end
    end
    if type(a.on_base_hit) == "table" and a.on_base_hit.prevent_hit then info.baseSafe = tonumber(a.on_base_hit.time) or 0 end
    info.n = math.max(0.3, f > 0 and f or (info.ally and 0.3 or 1))
    info.dot = math.min(1.5, info.dot)
    info.hits = math.max(1, info.hits)
    UNIT._atk[key] = info
    return info
end
-- damage share an attack deals across enemies: targets hit × (1 + damage over time)
function UNIT.aoe(atkId, range)
    local i = UNIT.attackInfo(atkId, range)
    return i.n * (1 + i.dot)
end
-- crowd control and debuffs as a multiplier on the whole team's damage: slowed / stunned enemies stay in range
-- longer, cursed ones take more damage. Uptime = effect seconds ÷ max(attack cooldown, the enemy's immunity time)
function UNIT.teamEffect(atkId, range, cd, noCC)
    local i = UNIT.attackInfo(atkId, range)
    local spacing = math.max(cd or 1, i.ccCd or 0, 0.5)
    local reach = math.min(1, i.n / 4)
    -- (noCC: the simulator holds the enemies back itself)
    local cc = noCC and 0 or math.min(1, (i.slow + i.stun) / spacing) * reach
    local amp = i.amp * (i.ampPersist and 1 or math.min(1, 5 / spacing)) * reach
    return cc * 0.5 + amp
end
-- what a unit's passives do, read from their text: {mark = {amp, max, dot}} (Chuuni: the enemy she targets takes more magic damage,
-- and part of her damage every 0.5 s, the whole time she's on it)
UNIT._pas = {}
function UNIT.passive(id)
    if UNIT._pas[id] then return UNIT._pas[id] end
    local out = {}
    local d = C.Units[id]
    for _, p in pairs(type(d) == "table" and type(d.passives) == "table" and d.passives or {}) do
        if type(p) == "table" then
            local text = tostring(p.description or ""):gsub("<[^>]+>", "")
            if p.name == "Pact of Frailty" then
                out.mark = out.mark or { amp = 0, max = 1, dot = 0 }
                out.mark.amp = (tonumber(text:match("(%d+)%%")) or 0) / 100
                out.mark.max = tonumber(text:match("up to (%d+)")) or 1
            elseif p.name == "Pact of Relevation" or p.name == "Pact of Revelation" then
                out.mark = out.mark or { amp = 0, max = 1, dot = 0 }
                local pct, every = text:match("(%d+)%%.-every ([%d%.]+)")
                out.mark.dot = (tonumber(pct) or 0) / 100 / math.max(0.1, tonumber(every) or 1)
            end
        end
    end
    UNIT._pas[id] = out
    return out
end
-- helpers a unit spawns by its own script, so its data doesn't say how they fight. Read off real matches on Oct 31: Iron Sentinel (Arsenal) gets a
-- drone about every 20 takedowns, 3 at most at once, with about half its damage and a 4 s attack after upgrade 6 (before that, by the guides). 10 drones
-- dealt 34.5M in one room, as much as Iron Sentinel itself: about 3 hits of a third each, on one target
-- Elyssia (Abyssal)'s eels, from her page: one per 5 takedowns, 3 at most for a minute each, a quarter of her damage on 2x her SPA of 4
UNIT.DRONES = { metal_knight_evolved = { every = 20, max = 3, from = 6, share = 1, hits = 3,
    early = { dmg = 0.25, cd = 5.5, life = 30 }, late = { dmg = 0.5, cd = 4, life = 60 } },
    elyssia_evolved = { every = 5, max = 3, from = 0, share = 1, hits = 1,
    early = { dmg = 0.25, cd = 8, life = 60 }, late = { dmg = 0.25, cd = 8, life = 60 } } }
-- a unit's built-in crit chance (a crit does ×1.5)
function UNIT.critMul(id)
    local d = C.Units[id]
    return 1 + (tonumber(type(d) == "table" and d.physical_crit_chance) or 0) * 0.5
end
-- a unit's buff for your other units (its active ability): {types = {magic = 0.3}, uptime, cd, id} or nil
-- the upgrade from which a unit's attack bleeds, withers or decays (which stops an enemy's regen while it lasts); nil: never
UNIT._bleeds = {}
function UNIT.bleeds(id)
    local c = UNIT._bleeds[id]
    if c ~= nil then return c or nil end
    local rows = UNIT.rows(id)
    local from = false
    if rows then
        for l = 0, rows.max do
            local r = rows[l]
            if r and r.atk then
                local ok, ai = pcall(UNIT.attackInfo, r.atk, r.range)
                if ok and ai and ai.bleed then from = l; break end
            end
        end
    end
    UNIT._bleeds[id] = from
    return from or nil
end
-- your strongest unit that bleeds (level 50 up, not already in the list): for a run whose enemies regenerate
function UNIT.bestBleeder(exclude)
    local s = C.session()
    if not s then return nil end
    local skip = {}
    for _, u in ipairs(exclude or {}) do skip[u.unit_id] = true end
    local best, bs
    for uuid, u0 in pairs(s.profile_data.collection.owned_units) do
        local d = C.Units[u0.unit_id]
        if d and not skip[u0.unit_id] and UNIT.rows(u0.unit_id) and not UNIT.hidden(u0.unit_id) and UNIT.bleeds(u0.unit_id) then
            local okL, lvl = pcall(C.USC.calculate_level, u0.unit_id, tonumber(u0.xp) or 0)
            if okL and (tonumber(lvl) or 0) >= 50 then
                local u = s.collection:get_unit_by_uuid(uuid) or u0
                local okS, sc = pcall(UNIT.score, u)
                if okS and (not bs or sc > bs) then best, bs = u, sc end
            end
        end
    end
    return best
end
function UNIT.allyBuff(id)
    local d = C.Units[id]
    if type(d) ~= "table" or not d.active_attack then return nil end
    local i = UNIT.attackInfo(d.active_attack)
    if not i.ally then return nil end
    local cd = tonumber(d.active_attack_stats and d.active_attack_stats.attack_cooldown) or 60
    return { types = i.ally.types, time = i.ally.time, cd = cd, uptime = math.min(1, (i.ally.time or 0) / math.max(1, cd)), attack = d.active_attack }
end
-- how many copies of a buffer keep its buff up all the time, for the units in their reach. They take turns: Windsong lasts 30 s on a 60 s cooldown, so 2 for each group of attackers (MT.buffShort). A
-- match had 6 at the front and none with the force at the back (the user's point, Nov 1). A buff measured to add up (B.stack) is worth copies up to its cap
function UNIT.buffCopies(b)
    local need = math.max(1, math.ceil((tonumber(b.cd) or 60) / math.max(1, tonumber(b.time) or 30) - 0.001))
    local stk = B.stack[b.attack]
    if stk and stk.stacks then
        local top = 0
        for _, r in pairs(b.types or {}) do top = math.max(top, tonumber(r) or 0) end
        if top > 0 and b.uptime > 0 then need = math.max(need, math.ceil((tonumber(stk.cap) or 1) / (top * b.uptime) - 0.001)) end
    end
    return need
end
-- a unit that never attacks and buffs the whole team by its passive (Idol: "buffs all your other units damage, and
-- decreases upgrade and placement cost per upgrade") — its worth is the team's, not its own damage
function UNIT.idol(id)
    local d = C.Units[id]
    if type(d) ~= "table" or not (d._NO_ATTACKS_UNIT and d._show_as_buff_unit) then return false end
    for _, p in pairs(d.passives or {}) do
        local t = type(p) == "table" and tostring(p.description or ""):lower() or ""
        if t:find("upgrade") and t:find("cost") then return true end
    end
    return false
end
-- the game's own stat multiplier: level, trait, stat rolls, limit breaks, curses, level modifiers
function UNIT.mult(u, stat)
    local key = tostring(u.uuid) .. stat
    local c = UNIT._mult[key]
    if c and U.now() - c.t < 60 then return c.v end
    local ok, v = pcall(C.USC.calculate_static_stat_multiplier, u, u.xp, stat, C.session())
    v = ok and tonumber(v) or 1
    UNIT._mult[key] = { v = v, t = U.now() }
    return v
end
function UNIT.types(id)
    local d = C.Units[id] or {}
    local t = { [d._base_damage_type or "physical"] = true }
    for k in pairs(d._secondary_damage_types or {}) do t[k] = true end
    return t, d._base_damage_type or "physical"
end
-- the mode's weak / strong elements: weak ×amplification (×1.5 when the game gives none), strong ×0.5
function UNIT.elem(id, mod)
    if not mod then return 1 end
    local types, base = UNIT.types(id)
    local f = 1
    for t in pairs(types) do if mod.weak[t] then f = math.max(f, mod.weak[t]) end end
    if mod.strong[base] then f = f * 0.5 end
    if mod.res and mod.res[base] then f = f * mod.res[base] end
    return f
end
-- relic damage-type buffs for the unit's own damage types (crit / special effects are inside the live stats)
function UNIT.relic(u)
    local s = C.session()
    if not (s and u._equipped_relic) then return 1 end
    local ok, it = pcall(function() return s.inventory:get_item_by_uuid(u._equipped_relic) end)
    local rd = ok and it and it._unique_item_data and it._unique_item_data._unique_relic_data
    if not (rd and rd._core_damage_type_buffs) then return 1 end
    local types = UNIT.types(u.unit_id)
    local f = 1
    for _, b in pairs(rd._core_damage_type_buffs) do
        if type(b) == "table" and types[b.damage_type] and tonumber(b.mul) then f = f + b.mul end
    end
    return f
end
function UNIT.relicName(u)
    local s = C.session()
    if not (s and u._equipped_relic) then return nil end
    local ok, it = pcall(function() return s.inventory:get_item_by_uuid(u._equipped_relic) end)
    local d = ok and it and C.Items[it.item_id]
    return d and d.name or (ok and it and it.item_id) or nil
end
-- measured damage vs predicted, as a capped nudge (×0.8–×1.35). Your own runs first; before 3 of them, the brain hive's reading from other players'
-- farms (5 matches or 2 players at least: REPORT.hive)
function UNIT.nudge(id)
    local l = B.learn[id]
    if not (l and l.n and l.n >= 3) then
        local h = REPORT.hiveUnit(id)
        return h and U.clamp(math.sqrt(h.eff), 0.8, 1.35) or 1
    end
    return U.clamp(math.sqrt(l.eff or 1), 0.8, 1.35)
end
function UNIT.trait(u)
    for _, t in pairs(u.traits or {}) do if type(t) == "table" then return t.trait, t.tier end end
    return nil
end
-- how many copies may be on the field: the unit's spawn cap, 1 for the Unique trait ("There can only be
-- one"), lowered further by what the server really allowed
function UNIT.cap(u)
    local cap = tonumber(UNIT.field(u.unit_id, "spawn_cap")) or 1
    if UNIT.trait(u) == "unique" then cap = 1 end
    local learned = tonumber(B.caps[u.uuid])
    if learned then cap = math.min(cap, learned) end
    return math.max(1, cap)
end
-- damage per second at an upgrade level (stat multipliers + area + element + relic + measured nudge)
-- a switch ability with a bar that hurts every enemy in range while it's on (MT.gale plays it live). Snow Reaper (Final)'s Gale of the Moon, from upgrade 1: a sixth of her damage
-- every 0.5 s on each enemy in her range, Chilled, and at 6 Chilled a freeze with one more hit of her damage. Her bar fills 2.5 a second and drains 5 while on (read live, Nov 2), so a
-- copy runs a third of the time; copies take turns. The sim plays it as an aura (SIM.run); everything else counts its average: on about 3 enemies, a freeze each every ~13 s
UNIT.GALE = { rukia_bankai_evolved = { from = 1, tick = 1 / 3, duty = 1 / 3, targets = 3, freezeEvery = 13, freeze = 2, chill = 3, immune = 10 } }
-- a unit's Gale, with its share of the time on as this farm has measured it (B.toggles: a bar's fill and drain, 5 readings each) where it has
UNIT._galeOf = {}
function UNIT.galeOf(id)
    local g = UNIT.GALE[id]
    if not g then return nil end
    local T = B.toggles and B.toggles[id]
    if not (T and (T.nf or 0) >= 5 and (T.nd or 0) >= 5 and (T.fill or 0) > 0 and (T.drain or 0) > 0) then return g end
    local duty = T.fill / (T.fill + T.drain)
    local c = UNIT._galeOf[id]
    if not (c and math.abs(c.duty - duty) < 0.01) then
        c = table.clone(g)
        c.duty = duty
        UNIT._galeOf[id] = c
    end
    return c
end
-- a unit with a switch ability and a bar: one the farm knows (UNIT.GALE), one it has seen in a match (B.toggles), or one other players' farms have (the brain hive). Its copies take
-- turns (MT.gale) and it stands where your damage is (MT.holdSpot), whatever unit it is (the user, Nov 2: "farm needs to be able to detect that stuff so if other units learned it knows")
function UNIT.toggleOf(id)
    if UNIT.GALE[id] then return { from = UNIT.GALE[id].from, known = true } end
    local T = B.toggles and B.toggles[id]
    if T then return T end
    local okH, h = pcall(REPORT.hiveToggle, id)
    return okH and h or nil
end
-- what the Gale adds, as damage a second per point of her damage stat (0 for any other unit, or before it unlocks)
function UNIT.galeDps(id, lvl)
    local g = UNIT.galeOf(id)
    if not g or (lvl or 0) < g.from then return 0 end
    return g.duty * g.targets * (g.tick + 1 / g.freezeEvery)
end
-- (noGale: the attack alone, for the simulator, which plays the Gale itself)
function UNIT.dps(u, lvl, mod, noGale)
    local rows = UNIT.rows(u.unit_id)
    local r = rows and rows[math.min(lvl, rows.max)]
    if not r or (r.cd or 0) <= 0 then return 0 end
    local hit = r.damage * UNIT.mult(u, "damage")
    local gale = noGale and 0 or hit * UNIT.galeDps(u.unit_id, lvl)
    return (hit / (r.cd * math.max(0.1, UNIT.mult(u, "attack_cooldown"))) * UNIT.aoe(r.atk, r.range) * UNIT.critMul(u.unit_id) + gale)
        * UNIT.elem(u.unit_id, mod) * UNIT.relic(u) * UNIT.nudge(u.unit_id)
end
-- a skin of the event's own set, on the unit wearing it (HUNT.skinSet): +boost × 100% damage there, nothing anywhere else
function UNIT.skinMul(u, set)
    local id = set and u.skin and u.skin._skin_id
    local skin = id and (C.data("Skins") or {})[id]
    return skin and skin._skin_set == set and 1 + (tonumber(skin._damage_boost) or 0) or 1
end
function UNIT.range(u, lvl)
    local rows = UNIT.rows(u.unit_id)
    local r = rows and rows[math.min(lvl, rows.max)]
    return (r and r.range or 10) * UNIT.mult(u, "range")
end
function UNIT.farm(u, lvl)
    local rows = UNIT.rows(u.unit_id)
    local r = rows and rows[math.min(lvl, rows.max)]
    return (r and r.farm or 0) * UNIT.mult(u, "farm_amount")
end
-- the unit score: damage at full upgrade × √range × √copies (money limits how many copies get far)
function UNIT.score(u, mod)
    local rows = UNIT.rows(u.unit_id)
    if not rows then return 0 end
    local top = rows.max
    return UNIT.dps(u, top, mod) * math.sqrt(math.max(1, UNIT.range(u, top)) / 20) * math.sqrt(UNIT.cap(u))
end
function UNIT.name(id) local d = C.Units[id]; return d and d.name or tostring(id) end
-- a form some other unit evolves into (an evolved unit counts as 2 points of limit-break fuel)
function UNIT.isEvolvedForm(id)
    if not UNIT._evolvedForms then
        UNIT._evolvedForms = {}
        for _, d in pairs(C.Units) do
            if type(d) == "table" and type(d.evolve) == "table" and d.evolve.evolve_unit then UNIT._evolvedForms[d.evolve.evolve_unit] = true end
        end
    end
    return UNIT._evolvedForms[id] == true
end
function UNIT.equipped()
    local s = C.session()
    local out = {}
    if not s then return out end
    for slot, uuid in pairs(s.profile_data.collection.equipped_units or {}) do
        local u = s.collection:get_unit_by_uuid(uuid)
        if u and C.Units[u.unit_id] then table.insert(out, { slot = tonumber(slot) or 0, uuid = uuid, u = u, id = u.unit_id, data = C.Units[u.unit_id] }) end
    end
    table.sort(out, function(a, b) return a.slot < b.slot end)
    return out
end
function UNIT.owns(id)
    local s = C.session()
    if not s then return false end
    for _, u in pairs(s.profile_data.collection.owned_units or {}) do
        if u.unit_id == id or (C.Units[u.unit_id] and C.Units[u.unit_id].evolved and C.Units[u.unit_id].evolved.from == id) then return true end
    end
    return false
end

-- ============================================================
--  MODES: one ranking in gems per minute
-- ============================================================
MODE.PRIOR_MIN = { story = 4.5, challenge = 5, daily = 10, event = 28, raid = 6, infinite = 30, dungeon = 8 }
MODE.PRIOR_WIN = { story = 0.9, hard = 0.8, new = 0.65, challenge = 0.75, daily = 0.7, event = 0.75, raid = 0.6, infinite = 1, dungeon = 0.85 }
MODE.OVERHEAD = 0.7 -- minutes of lobby + teleport per run (less on a replay)
MODE.CHAIN_MIN = 0.6 -- an earlier act goes ahead of a later one down to this share of its score, since Next saves a lobby trip each act
-- a level's own weaknesses and resistances (the user spotted the gap on a Legend Stage, Nov 1: "Fire Weakness x2"). The game keeps them on each kind of enemy in the level's waves (_dmg_amp_<type>, _dmg_res_<type>), not on the
-- level, so _weak_against reads nothing and neither the team search nor the buying knew: Paradox went into a fire and ice stage for no bonus. A kind takes ×(1 + amp), checked on real enemies (_dmg_weak_fire_damage 2 is the game's x3),
-- and 100 / (100 + R) with a resistance. One number per damage type, weighted by each kind's HP since damage has to get through all of it. The tooltip shows the lowest kind's, so it reads lower than this
MODE._levelMod = {}
function MODE.levelMod(id)
    if id == nil then return nil end
    if MODE._levelMod[id] ~= nil then return MODE._levelMod[id] or nil end
    MODE._levelMod[id] = false
    local lv = C.Levels[id]
    local waves = type(lv) == "table" and C.Waves[lv.waves or id]
    local cfgs = type(waves) == "table" and waves.initial_unit_configs
    if type(cfgs) ~= "table" then return nil end
    local kinds, types, total = {}, {}, 0
    for _, c in pairs(cfgs) do
        local st = type(c) == "table" and type(c.override_stats) == "table" and (c.override_stats[1] or c.override_stats["1"]) or nil
        if type(st) == "table" then
            local hp = tonumber(st.health) or 20
            total = total + hp
            table.insert(kinds, { hp = hp, st = st })
            for k in pairs(st) do
                local t = tostring(k):match("^_dmg_amp_(.+)$") or tostring(k):match("^_dmg_res_(.+)$")
                if t then types[t] = true end
            end
        end
    end
    if not next(types) or total <= 0 then return nil end
    local mod = { weak = {}, strong = {}, res = {} }
    for t in pairs(types) do
        local left = 0
        for _, e in ipairs(kinds) do
            local k = (1 + (tonumber(e.st["_dmg_amp_" .. t]) or 0)) * 100 / (100 + math.max(0, tonumber(e.st["_dmg_res_" .. t]) or 0))
            left = left + e.hp / math.max(0.05, k)
        end
        local eff = total / math.max(1, left)
        if eff > 1.02 then mod.weak[t] = eff elseif eff < 0.98 then mod.res[t] = eff end
    end
    if not (next(mod.weak) or next(mod.res)) then return nil end
    MODE._levelMod[id] = mod
    return mod
end
function MODE.rec(key)
    local r = B.modes[key]
    if not r then r = { runs = 0, wins = 0, sec = 0, gems = 0, coins = 0, streak = 0 }; B.modes[key] = r end
    return r
end
function MODE.itemValue(id, amount)
    -- an item a top goal still needs is worth its share of that goal (the path to stronger units) — only up to
    -- what the goal still needs: the rest of a big drop is worth what the item is normally worth
    if B.goalItems[id] then
        local a = amount or 1
        local inGoal = math.min(a, tonumber(B.goalNeed[id]) or a)
        return B.goalItems[id] * inGoal + (C.ITEM_VALUE[id] or C.ITEM_DEFAULT) * math.max(0, a - inGoal)
    end
    -- (a Divine Wish is worth what it would do for your core units: STR.itemWorth, never below the table)
    if CFG.team and STR.itemWorth then
        local okW, w = pcall(STR.itemWorth, id)
        if okW and w then return w * (amount or 1) end
    end
    local cap = C.GS.ITEM_CAPS and C.GS.ITEM_CAPS[id]
    local s = C.session()
    local have = 0
    pcall(function() have = s.inventory:get_number_of_owned_item(id) end)
    if cap and have >= cap then return 0 end
    return (C.ITEM_VALUE[id] or C.ITEM_DEFAULT) * (amount or 1)
end
-- expected gem value of a challenge reward table (`_rewards`: gems + items, `_item_multichoice` = you get m of n)
function MODE.rewardValue(rw)
    local total = 0
    for _, r in pairs((rw and rw._rewards) or {}) do
        if type(r) == "table" then
            total = total + (tonumber(r.gem_reward) or 0) + (tonumber(r.gold_reward) or 0) * C.GOLD_VALUE
            local items = U.list(r.item)
            local share = 1
            if r._item_multichoice and #items > 0 then share = math.min(1, (tonumber(r._item_multichoice.min) or #items) / #items) end
            for _, it in ipairs(items) do
                local amt = tonumber(it.amount) or ((tonumber(it.min_amount) or 1) + (tonumber(it.max_amount) or tonumber(it.min_amount) or 1)) / 2
                local p = (tonumber(it.chance) or 1) * (1 - (tonumber(it._zero_chance) or 0))
                total = total + MODE.itemValue(it.item_id, amt) * p * share
            end
        end
    end
    return total
end
function MODE.done(ld, id, diff)
    if B.cleared[id .. ":" .. tostring(diff or "Normal")] then return true end
    local d = ld.completed_story_levels and ld.completed_story_levels[id]
    if not d then return false end
    if diff and d.difficulty_completed_data then
        local x = d.difficulty_completed_data[diff]
        return x and (x.times_completed or 0) > 0 or false
    end
    return (d.times_completed or 0) > 0
end
-- is this level or difficulty open? (the game's checks have taken the session and the level's own table since the Summer update: given the old arguments they said no to every level, and the farm sat waiting)
function MODE.open(id)
    local s, lv = C.session(), C.Levels[id]
    if not (s and lv) then return false end
    local ok, r = pcall(C.PSC.check_if_unlocked_level, s, lv)
    return ok and r and true or false
end
function MODE.diffOpen(id, diff)
    local s, lv = C.session(), C.Levels[id]
    if not (s and lv) then return false end
    local ok, r = pcall(C.PSC.check_if_unlocked_difficulty, s, lv, diff)
    return ok and r and true or false
end
function MODE.levelName(id)
    local lv = C.Levels[id]
    if not lv then return tostring(id) end
    local w = lv.world and C.Worlds[lv.world]
    return (w and w.name and (w.name .. " ") or "") .. (lv.name or id)
end
-- Infinite has no last wave: a run lasts until the base falls. Each map pays gems once a day when a run reaches
-- waves 10 / 25 / 50 (the game's DAILY_INFINITE_REWARDS, per map, reset DAILY_INFINITE_REWARD_PERIOD after the claim)
function MODE.isInf(key) return tostring(key):sub(1, 4) == "inf:" end
-- the wave the team reaches on an Infinite map: real runs there (their average), else the simulator, else 25
function MODE.infReach(key)
    local r = MODE.rec(key)
    if (tonumber(r.waveN) or 0) > 0 then return r.waveSum / r.waveN, true end
    local sr = B.simRes[key]
    if sr and tonumber(sr.wave) then return sr.wave, false end
    return 25, false
end
-- the daily gems still to claim on one map, up to the wave reached: gems, the last milestone among them
function MODE.infDaily(p, id, reach)
    local c = p.daily_infinite_reward_claims and p.daily_infinite_reward_claims[id]
    local period = tonumber(C.GS.DAILY_INFINITE_REWARD_PERIOD) or 82800
    local claimed = (type(c) == "table" and os.time() - (tonumber(c.highest_claim_time) or 0) < period) and (tonumber(c.highest_claimed_wave) or 0) or 0
    local gems, top = 0, 0
    for _, r in ipairs(U.list(C.GS.DAILY_INFINITE_REWARDS)) do
        local w = tonumber(r.wave) or 0
        if w > claimed and w <= (reach or 0) then gems, top = gems + (tonumber(r.gem_reward) or 0), math.max(top, w) end
    end
    return gems, top, claimed
end
-- the last daily milestone a wave has passed (0 below the first)
function MODE.infTier(wave)
    local top = 0
    for _, r in ipairs(U.list(C.GS.DAILY_INFINITE_REWARDS)) do if (tonumber(r.wave) or 0) <= wave then top = math.max(top, tonumber(r.wave) or 0) end end
    return top
end
-- every mode that can be played right now, with its value per run (gems) and its odds
-- the Farming tab's "only" switches: with any on, just those modes are played; story means acts never beaten
-- the event's currency in words: SummerPearls → Summer Pearls
function MODE.coinName() return (tostring(C.GS.CURRENT_EVENT_RESOURCE or "event coins"):gsub("(%l)(%u)", "%1 %2")) end
-- the event the game runs right now, by its own list, or nil. The panel shows only what's really on (the user, Nov 1: Fool's Hunt "is no longer in the game, it might come back later"): it left with Update 21, its
-- level still in the files and all its play kept here, so if an update switches it back on its switches return by themselves. Same for the Summer Hunt when it ends. (The list ships with the game, so it can't change during a session)
function MODE.eventNow()
    if MODE._event ~= nil then return MODE._event or nil end
    MODE._event = false
    for id in pairs(C.GS.ACTIVE_EVENT_CHALLENGES or {}) do
        local lv = C.Levels[id]
        local hunt, dealt = id == HUNT.ID, type(lv) == "table" and lv._randomequippedmode ~= nil
        MODE._event = { id = id, name = type(lv) == "table" and lv.name or tostring(id), hunt = hunt, dealt = dealt,
            about = hunt and "50 waves with cards and weather, for Summer Pearls. It never spends them"
                or dealt and "AprilCoins every wave, for the April banner"
                or string.format("The game's current event, for %s", MODE.coinName()) }
        break
    end
    return MODE._event or nil
end
-- (an event's Only switch left on after it ended is hidden with it, so it can't hold the farm waiting)
function MODE.onlyOn() return CFG.onlyRaids or CFG.onlyStory or CFG.onlyChallenges or (CFG.onlyCoins and MODE.eventNow() ~= nil) or CFG.onlyDungeons or CFG.onlyLegend or CFG.onlyInfinite end
function MODE.allowed(m)
    if CFG.dailyLoop and m.kind == "daily" then return true end
    if not MODE.onlyOn() then return true end
    -- (a mode asked for once: a test run, whatever the switches say. The switches stay as they are)
    if B.nextMode and B.nextMode == m.key then return true end
    -- (the Daily Challenge pays the Divine Wish, remnants and cubes the Team tab runs on: once a day whatever the switches say — the user's call)
    if m.kind == "daily" and CFG.team then return true end
    if m.kind == "raid" then return CFG.onlyRaids end
    if m.legend then return CFG.onlyLegend end
    -- (the user's call, Nov 1: story progress is maps you've never beaten. An act beaten on Normal isn't new, so its Hard run waits: 33 of those were being played ahead of the one new map.
    -- An act you picked on the Home tab plays whatever it is)
    if m.kind == "story" then return CFG.onlyStory and (m.picked or (m.first and m.diff == "Normal")) end
    if m.kind == "daily" or m.kind == "challenge" then return CFG.onlyChallenges end
    if m.kind == "event" then return CFG.onlyCoins end
    if m.kind == "dungeon" then return CFG.onlyDungeons end
    if m.kind == "infinite" then return CFG.onlyInfinite end
    -- (a portal goes with the Infinite map that drops it: Infinite Only on Shibuya District plays the portals it drops too)
    if m.kind == "portal" then
        -- (your portal pick plays whatever the Only switches say)
        if m.picked then return true end
        for _, pt in pairs(MODE.PORTALS) do
            if pt.level == m.level then return CFG.onlyInfinite and (CFG.pickInfinite == "" or CFG.pickInfinite == "inf:" .. pt.from) end
        end
    end
    return false
end
function MODE.onlyText()
    local on = {}
    local ev = MODE.eventNow()
    for _, x in ipairs({ { "onlyRaids", "raids" }, { "onlyStory", "story" }, { "onlyLegend", "legend stages" }, { "onlyInfinite", "Infinite" }, { "onlyChallenges", "challenges" }, { "onlyCoins", ev and (ev.hunt and "the Summer Hunt" or ev.name) }, { "onlyDungeons", "dungeons" } }) do
        if CFG[x[1]] and x[2] then table.insert(on, x[2]) end
    end
    return table.concat(on, ", ")
end
-- the challenge filter (Home tab): types on your skip list never play, and with Only Ones You Can Beat on, the Daily and challenges play only when the simulator gives your team the chance you set
-- (or the best team it found wins: the search's pick is what plays). Not yet simulated: it plays, and the gate before launch simulates it first
MODE.skipped = {}
function MODE.chName(id)
    local c = C.CAR.challenges and C.CAR.challenges[id]
    return c and c.name or tostring(id):gsub("_", " ")
end
function MODE.chOk(m)
    local id = m.kind == "daily" and B.live.daily and B.live.daily.challenge or m.challenge
    if id and table.find(CFG.chSkip or {}, id) then return false, MODE.chName(id) .. " is on your skip list" end
    if CFG.chSmart then
        local sr = MODE.sim(m)
        local best = B.simTeam and B.simTeam[m.key]
        local need = tonumber(CFG.chMinP) or 0.5
        if sr and sr.p and sr.p < need and not (best and best.better and best.won) then
            return false, string.format("the simulator gives your team %d%%, under the %d%% you set", math.floor(sr.p * 100 + 0.5), math.floor(need * 100 + 0.5))
        end
    end
    return true
end
-- the Infinite maps (some raids carry the infinite flag too: only the maps the story pads list as "Infinite Mode")
function MODE.infIds()
    local ids = {}
    for id, lv in pairs(C.Levels) do
        if type(lv) == "table" and lv.infinite and type(lv._MATCHMAKING) == "table" and lv._MATCHMAKING.gamemode == "infinite" and not lv._randomequippedmode then table.insert(ids, id) end
    end
    table.sort(ids)
    return ids
end
-- does this mode drop an item a goal is waiting on?
function MODE.dropsGoal(m)
    local lv = m.level and C.Levels[m.level]
    if not lv then return false end
    for _, x in ipairs(ADV.levelItems(lv)) do if B.goalItems[x.item] then return true end end
    return false
end
-- ============================================================
--  THE SUMMER HUNT (level summer2_event: one map and weather an hour, cards every few waves, Summer Pearls per wave)
-- ============================================================
-- Nothing here spends Summer Pearls or trades gems for them: it plays the mode, picks the cards and claims the free bingo lines. What to buy stays the user's call
HUNT.ID = "summer2_event"
HUNT.WEATHERS = 9
-- pearls come wave by wave, the level's table × the card multiplier (35 by wave 8 on the first real win, Nov 1). That win paid 1,362 in all where the waves add up to about 976, so a win seems to pay about 385 on top: one run so far.
-- MULT_GUESS: what a full run comes to over the table (435), before any real run on record
HUNT.MULT_GUESS = 3.1
-- a hard card's own worth, for the higher tier portal it leads to (they sell for 150-500 pearls), and what Starfall's Star Golems are worth: each drops a Limited Star Remnant, how many fall isn't known yet
HUNT.HARD_GEMS, HUNT.STARFALL_GEMS = 30, 150
-- a strength change in gems: +12% damage is worth about 34
HUNT.STRENGTH_GEMS = 300
function HUNT.is(id)
    return id == HUNT.ID or (id ~= nil and B.live.event ~= nil and B.live.event.board == HUNT.ID and B.live.event.level == id)
end
-- the weather on now: in a match the game knows it (a card can change it), in the lobby the board does
function HUNT.weatherNow()
    if SF.where == "match" then
        local s = C.svc("WeatherServiceClient")
        if s and s.current_weather then return s.current_weather end
    end
    return B.live.event and B.live.event.weather
end
-- each weather, as far as the simulator can play it (SIM.applyFx), from the game's own descriptions. Resistance is read as 100 / (100 + it), which isn't measured yet. Ice's size and the wind's average aren't given: estimates
function HUNT.fx(w)
    local fx = { dmg = 1, cd = 1, range = 1, cost = 1, hp = 1, speed = 1, regen = 0, crit = 0, kinds = {}, shield = 0, fly = 0 }
    if w == "rain" then fx.speed = 1.2
    elseif w == "windy" then fx.fly, fx.speed = 0.2, 1.25
    elseif w == "snow" then fx.hp, fx.fire = 1.5, 1.5
    elseif w == "downpour" then fx.range, fx.dmg = 0.7, 0.85
    elseif w == "mana" then fx.kinds.physical, fx.kinds.magic = 100 / 250 - 1, 0.25
    elseif w == "fire" then fx.speed, fx.noCC = 1.5, true
    elseif w == "underwater" then fx.speed = 1.25
    elseif w == "sandstorm" then fx.kinds.magic, fx.kinds.physical, fx.shroud = 100 / 175 - 1, 0.25, 0.2 end
    return fx
end
-- Summer Pearls a wave pays before the card multiplier (the level's table)
function HUNT.perWave(w)
    local lv = C.Levels[HUNT.ID]
    local rows = lv and lv.infinite_resource_rewards and lv.infinite_resource_rewards.SummerPearls
    for _, r in ipairs(rows or {}) do if w <= (tonumber(r.wave_up_to) or 0) then return tonumber(r.reward) or 0 end end
    return 0
end
function HUNT.pearlsFrom(w0, w1)
    local n = 0
    for w = w0, w1 do n = n + HUNT.perWave(w) end
    return n
end
-- the bingo board (6 × 6 maps, shuffled per player), the maps and weathers won, the lines done
function HUNT.board()
    local core = C.core("Summer2MapBoardCore")
    local p = C.prof()
    if not (core and p) then return nil end
    local board = core.get_board(LP.UserId)
    if not board then return nil end
    local wins = type(p._summer2_hunt_wins) == "table" and p._summer2_hunt_wins or {}
    local maps, weathers, claimed = wins.maps or {}, wins.weathers or {}, p._summer2_map_board_claimed_lines or {}
    local squares, lines, won = 0, 0, 0
    for _, id in ipairs(board) do if maps[id] then squares = squares + 1 end end
    for _ in pairs(core.get_completed_lines(board, maps)) do lines = lines + 1 end
    for _ in pairs(weathers) do won = won + 1 end
    return { core = core, board = board, maps = maps, weathers = weathers, claimed = claimed, squares = squares, lines = lines, weathersWon = won, total = #core.LINES,
        claimable = core.get_claimable_lines(board, maps, claimed) }
end
-- a bingo line: 2,000 Summer Pearls and 10 Limited Star Remnants (the level's map_board_line_reward)
function HUNT.lineGems() return 2000 * CFG.pearlValue + 10 * (C.ITEM_VALUE.star_remnant_limited or 25) end
-- what a first win here is worth on top of the pearls: its square on the board (a share of each line through it), its weather toward the Weather Report quest
-- (1,000 gems, 5,000 pearls, 50 Limited remnants for all nine), and the first Explosion Mage (500 gems, 4,500 pearls, 2 tokens). Empty once they're done
function HUNT.firstValue(map, weather)
    local b = HUNT.board()
    if not b then return 0, {} end
    local value, why = 0, {}
    local cell = map and table.find(b.board, map)
    if cell and not b.maps[map] then
        local n = 0
        for _, line in ipairs(b.core.LINES) do if table.find(line.cells, cell) then n = n + 1 end end
        value = value + n * HUNT.lineGems() / b.core.SIZE
        table.insert(why, "a new bingo square")
    end
    if weather and weather ~= "clear" and not b.weathers[weather] then
        value = value + (1000 + 5000 * CFG.pearlValue + 50 * (C.ITEM_VALUE.star_remnant_limited or 25)) / HUNT.WEATHERS
        table.insert(why, "a new weather for the quest")
    end
    if not next(b.maps) then
        value = value + 500 + 4500 * CFG.pearlValue + 200
        table.insert(why, "the first Explosion Mage")
    end
    return value, why
end
-- its row in the mode ranking: real runs' pearls once there are any, else the level's table up to the wave the simulator reaches
function HUNT.row(rec)
    local ev = B.live.event
    local sr = B.simRes["ev:" .. tostring(ev.level)]
    local reach = sr and (sr.won and 50 or tonumber(sr.wave)) or 50
    local pearls = rec.runs > 0 and rec.coins / rec.runs or HUNT.pearlsFrom(1, reach) * HUNT.MULT_GUESS
    local first, firstWhy = HUNT.firstValue(ev.map, ev.weather)
    local w = C.data("Weather") or {}
    return { key = "ev:" .. tostring(ev.level), kind = "event", level = ev.level, diff = "Hard", value = pearls * CFG.pearlValue + first, coins = pearls, p0 = 0.5,
        label = "Summer Hunt", why = string.format("≈%d Summer Pearls a run%s%s", math.floor(pearls), ev.weather and w[ev.weather] and (" · " .. w[ev.weather].name) or "",
            #firstWhy > 0 and (" · a win adds " .. table.concat(firstWhy, ", ")) or "") }
end
-- the strength floor for hard cards: up after a lost run, down after a won one, so it finds what your team can carry
function HUNT.floor() return tonumber(B.hunt.pmin) or 1 end
-- free: a finished bingo line pays when it's claimed
function HUNT.claim()
    local b = HUNT.board()
    if not (b and #b.claimable > 0) then return end
    local ok = SF.request("bingo", "claim_summer2_map_board_lines")
    if ok then SF.log(1, "LOBBY", string.format("Summer Bingo: claimed %d line%s, each 2,000 Summer Pearls and 10 Limited Star Remnants", #b.claimable, #b.claimable == 1 and "" or "s")) end
end
-- a line for one of the run's record files (appendfile won't start a new file: the first run's cards and rewards were lost that way)
function HUNT.write(name, line)
    local path = C.FOLDER .. "/" .. name
    local ok, old = pcall(readfile, path)
    pcall(writefile, path, (ok and type(old) == "string" and old or "") .. line .. "\n")
end
-- a game table as plain data for a log file: text keys, no Roblox values
function HUNT.plain(v, depth)
    depth = depth or 0
    if type(v) == "table" then
        if depth > 5 then return "..." end
        local o = {}
        for k, x in pairs(v) do o[tostring(k)] = HUNT.plain(x, depth + 1) end
        return o
    end
    if type(v) == "number" or type(v) == "string" or type(v) == "boolean" then return v end
    return tostring(v)
end
-- the Summer Merchant's stock and prices, and the board's forecast, for the record. Reads only
function HUNT.shopLook()
    local ok, shop = SF.request("bsd", "request_current_bsd_shop")
    if ok and type(shop) == "table" then
        local okJ, raw = pcall(Http.JSONEncode, Http, shop)
        if okJ then pcall(writefile, C.FOLDER .. "/hunt_shop.txt", os.date("%m-%d %H:%M ") .. raw) end
    end
    local okE, e = SF.request("live_e", "get_event_challenges")
    if okE and type(e) == "table" and type(e[HUNT.ID]) == "table" then
        local keep = {}
        for k, v in pairs(e[HUNT.ID]) do if k ~= "current_level_data" then keep[k] = v end end
        local okJ, raw = pcall(Http.JSONEncode, Http, keep)
        if okJ then pcall(writefile, C.FOLDER .. "/hunt_board.txt", os.date("%m-%d %H:%M ") .. raw) end
    end
end
-- how much stronger a weather leaves your team than the one on now (below 1: weaker), from the share of your damage each type does
function HUNT.weatherStrength(w)
    local fx = HUNT.fx(w)
    local k = fx.dmg / fx.cd / fx.hp / fx.speed * (1 + (fx.range - 1) / 2)
    for kind, a in pairs(fx.kinds) do k = k * (1 + MT.rogueShare(kind) * a) end
    if fx.fly > 0 then k = k * (1 - fx.fly * 0.5) end
    if fx.noCC then k = k * 0.95 end
    if fx.shroud then k = k * 0.9 end
    return k
end
-- what a card pays beyond your team's strength, in gems: its multiplier over the waves left, the rewards on it, a hard card's better portal, a weather still wanted
function HUNT.cardGems(o, wave)
    local gems = 0
    local left = HUNT.pearlsFrom(wave + 1, 50)
    for _, ef in pairs(type(o.effects) == "table" and o.effects or {}) do
        if type(ef) == "table" then
            local a = tonumber(ef.amount) or 0
            if ef.type == "candy_multiplier" then gems = gems + math.abs(a) * left * CFG.pearlValue
            elseif ef.type == "add_reward" then
                local okV, v = pcall(MODE.rewardValue, ef.reward)
                if okV then gems = gems + (tonumber(v) or 0) end
            elseif ef.type == "golem_chance" then gems = gems + a * HUNT.STARFALL_GEMS
            elseif ef.type == "secret_drop" then gems = gems + a * 100 end
        end
    end
    if o.option_type == "Bad" then gems = gems + HUNT.HARD_GEMS end
    if o.weather then
        -- (a card of the weather already on doesn't bring anything new: the hunt's cards come in the hour's weather)
        local changes = o.weather ~= HUNT.weatherNow()
        if changes and o.weather == "meteor_shower" then gems = gems + HUNT.STARFALL_GEMS end
        local b = HUNT.board()
        if changes and b and o.weather ~= "clear" and not b.weathers[o.weather] then gems = gems + (1000 + 5000 * CFG.pearlValue + 50 * (C.ITEM_VALUE.star_remnant_limited or 25)) / HUNT.WEATHERS end
    end
    return gems
end
-- the Lobby's words: what it would do, and that it spends nothing
function HUNT.text()
    local ev = B.live.event
    if not (ev and HUNT.is(ev.level)) then return "The Summer Hunt isn't on the board right now." end
    local w, maps = C.data("Weather") or {}, C.data("Maps") or {}
    local lines = {}
    local function mapName(id) return id and maps[id] and maps[id].name or id or "?" end
    table.insert(lines, string.format("This hour: %s, %s.", mapName(ev.map), ev.weather and w[ev.weather] and w[ev.weather].name or "weather unknown"))
    if type(ev.forecast) == "table" then
        table.insert(lines, string.format("Next hour: %s, %s.", ev.forecast.map and mapName(ev.forecast.map) or (ev.forecast.map_hint or "map hidden"),
            ev.forecast.weather and w[ev.forecast.weather] and w[ev.forecast.weather].name or (ev.forecast.weather_hint or "weather hidden")))
    end
    local rec = MODE.rec("ev:" .. tostring(ev.level))
    if rec.runs > 0 then table.insert(lines, string.format("%d runs so far, %d won, ≈%d Summer Pearls a run.", rec.runs, rec.wins, math.floor(rec.coins / rec.runs)))
    else table.insert(lines, string.format("Not played yet. A full run should pay about %d Summer Pearls.", math.floor(HUNT.pearlsFrom(1, 50) * HUNT.MULT_GUESS))) end
    local b = HUNT.board()
    if b then table.insert(lines, string.format("Bingo: %d of %d squares, %d of %d lines. Weathers won: %d of %d.", b.squares, #b.board, b.lines, b.total, b.weathersWon, HUNT.WEATHERS)) end
    table.insert(lines, string.format("You hold %s Summer Pearls. The farm never trades gems for them, and spends them only on Sunny Stars, only with Open Sunny Stars on.", U.fmt(tonumber(C.cur("SummerPearls")) or 0)))
    return table.concat(lines, "\n")
end
-- Summer skins, by the game's own code. A skin counts only in its event, on the unit wearing it: +boost × 100% damage, and each team unit in one adds to the Secret Portal drop by its rarity. It fits its own unit and
-- that unit's evolved form, so the +5000% one fits only the Rare Spirit Reaper: at level 1 it reads a score of 142 beside Iron Sentinel's 947k, and the sim sees no change. Selling pays pearls by rarity, only for this event's set
HUNT.SKIN_SET, HUNT.STAR = "summer2", "capsule_summer2"
HUNT.SKIN_PRICE = { Rare = 10, Epic = 40, Legendary = 75, Mythic = 300 }
HUNT.SKIN_DROP = { Rare = 0.02, Epic = 0.05, Legendary = 0.25, Mythic = 0.4 }
HUNT.STAR_COST = 150
function HUNT.skinSet(ld)
    local id = type(ld) == "table" and ld.id
    return (id == HUNT.ID or id == "summer2_portal_final" or (type(ld) == "table" and ld.portal_group == "summer2")) and HUNT.SKIN_SET or nil
end
function HUNT.skinFits(unitId, skin)
    local d = C.Units[unitId]
    local base = d and d.evolved and d.evolved.from or unitId
    return skin.for_unit == unitId or skin.for_unit == base or (skin.for_units ~= nil and (skin.for_units[unitId] or skin.for_units[base]) and true) or false
end
function HUNT.team()
    local plan = B.simTeam and B.simTeam["ev:" .. tostring(HUNT.ID)]
    local s = C.session()
    local out = {}
    for _, uuid in ipairs(plan and plan.uuids or B.savedTeam or {}) do
        local u = s.collection:get_unit_by_uuid(uuid)
        if u then table.insert(out, u) end
    end
    return out
end
-- what you hold of this event's set, and what Smart Skins would do with it. One of each stays if a unit of yours can wear it, and one of each Legendary or better stays whatever you own: it pays 75 pearls sold, and a new one is 0.4% a star
function HUNT.skinPlan()
    local s, p = C.session(), C.prof()
    local skins = C.data("Skins") or {}
    local uniq = (p.inventory and p.inventory.unique_items) or p.unique_items or {}
    local kinds, plan = {}, { kinds = {}, sell = {}, wear = {}, pearls = 0, missing = {} }
    for key, it in pairs(uniq) do
        local d = type(it) == "table" and C.Items[it.item_id]
        if d and d.item_group == "Skins" and d._skin_set == HUNT.SKIN_SET and d.usage and skins[d.usage.skin_id] then
            local k = kinds[it.item_id]
            if not k then
                k = { id = it.item_id, name = d.name, rarity = d.rarity, skinId = d.usage.skin_id, skin = skins[d.usage.skin_id], uuids = {} }
                kinds[it.item_id] = k
                table.insert(plan.kinds, k)
            end
            table.insert(k.uuids, it.uuid or key)
        end
    end
    table.sort(plan.kinds, function(a, b) return a.name < b.name end)
    local team = HUNT.team()
    local owned = s.profile_data.collection.owned_units
    for _, k in ipairs(plan.kinds) do
        for _, o in pairs(owned) do if HUNT.skinFits(o.unit_id, k.skin) then k.fits = true; break end end
        local high = k.rarity == "Legendary" or k.rarity == "Mythic"
        k.keep = (k.fits or high) and 1 or 0
        for i = k.keep + 1, #k.uuids do
            table.insert(plan.sell, { uuid = k.uuids[i], name = k.name, pearls = HUNT.SKIN_PRICE[k.rarity] or 0 })
            plan.pearls = plan.pearls + (HUNT.SKIN_PRICE[k.rarity] or 0)
        end
    end
    -- your Hunt team: who can wear what, and what's still missing. A skin of its own set on the unit already counts
    for _, u in ipairs(team) do
        local worn = u.skin and u.skin._skin_id and skins[u.skin._skin_id]
        if not (worn and worn._skin_set == HUNT.SKIN_SET) then
            for id, skin in pairs(skins) do
                if type(skin) == "table" and skin._skin_set == HUNT.SKIN_SET and HUNT.skinFits(u.unit_id, skin) then
                    local item = id .. "_skin"
                    if kinds[item] then table.insert(plan.wear, { uuid = kinds[item].uuids[1], unit = u.uuid, unitName = UNIT.name(u.unit_id), name = kinds[item].name })
                    else table.insert(plan.missing, { item = item, unitName = UNIT.name(u.unit_id), name = skin.name, boost = tonumber(skin._damage_boost) or 0, drop = HUNT.SKIN_DROP[skin._skin_rarity] or 0 }) end
                end
            end
        end
    end
    return plan
end
-- what Open Sunny Stars would open: a need first (a skin your Hunt team can wear, a Mythic unit of the event you don't have), and never below the pearls you keep. The game gives a Mythic unit by the 400th open at the latest
function HUNT.starPlan(plan)
    plan = plan or HUNT.skinPlan()
    local star = C.Items[HUNT.STAR] or {}
    local pity = tonumber(star._mythic_unit_pity) or 400
    local rec = (C.prof().capsule_pity_data or {})[HUNT.STAR] or {}
    local since = tonumber(rec.opens_since_mythic_unit) or 0
    local out = { opened = tonumber(rec.total_opens) or 0, left = math.max(1, pity - since), units = {} }
    local pearls = tonumber(C.cur("SummerPearls")) or 0
    out.can = math.max(0, math.floor((pearls - (tonumber(CFG.pearlFloor) or 0)) / HUNT.STAR_COST))
    local have = {}
    for _, o in pairs(C.session().profile_data.collection.owned_units) do
        have[o.unit_id] = true
        local d = C.Units[o.unit_id]
        if d and d.evolved and d.evolved.from then have[d.evolved.from] = true end
    end
    for _, r in pairs(star.usage and star.usage.possible_rewards or {}) do
        local id = r.unit or r.item
        if id and C.Units[id] and C.Units[id].rarity == "Mythic" and not have[id] then table.insert(out.units, UNIT.name(id)) end
    end
    table.sort(out.units)
    local why = {}
    if #plan.missing > 0 then
        local m = plan.missing[1]
        table.insert(why, string.format("%s to go on %s", m.name, m.unitName))
    end
    if #out.units > 0 then table.insert(why, string.format("a Mythic unit you don't have (%s)", table.concat(out.units, ", "))) end
    out.why = table.concat(why, " and ")
    out.open = #why > 0 and math.min(out.can, #out.units > 0 and out.left or 100) or 0
    return out
end
function HUNT.skinText()
    local okP, plan = pcall(HUNT.skinPlan)
    if not okP then return "Reading your skins: " .. tostring(plan) end
    local lines = {}
    local have = {}
    for _, k in ipairs(plan.kinds) do
        table.insert(have, string.format("%s%s (+%d%% damage%s)", k.name, #k.uuids > 1 and (" ×" .. #k.uuids) or "", (tonumber(k.skin._damage_boost) or 0) * 100, k.fits and "" or ", no unit of yours fits"))
    end
    table.insert(lines, "A skin counts only in the Hunt, on the unit wearing it. You hold: " .. (#have > 0 and table.concat(have, ", ") or "none") .. ".")
    if #plan.wear > 0 then
        local w = {}
        for _, x in ipairs(plan.wear) do table.insert(w, x.name .. " on " .. x.unitName) end
        table.insert(lines, "Would wear: " .. table.concat(w, ", ") .. ".")
    end
    for _, m in ipairs(plan.missing) do
        table.insert(lines, string.format("Your Hunt team could use %s on %s: +%d%% damage, +%d%% Secret Portal drop.", m.name, m.unitName, m.boost * 100, m.drop * 100))
    end
    if #plan.sell > 0 then
        local by = {}
        for _, x in ipairs(plan.sell) do by[x.name] = (by[x.name] or 0) + 1 end
        local t = {}
        for n, c in pairs(by) do table.insert(t, c .. "× " .. n) end
        table.sort(t)
        table.insert(lines, string.format("Would sell %s for %s pearls. It can't be undone.", table.concat(t, ", "), U.fmt(plan.pearls)))
    else table.insert(lines, "Nothing to sell.") end
    local okS, st = pcall(HUNT.starPlan, plan)
    if okS then
        table.insert(lines, string.format("Sunny Stars: %d opened. A sure Mythic unit in %d more (%s pearls).", st.opened, st.left, U.fmt(st.left * HUNT.STAR_COST)))
        if st.open > 0 then table.insert(lines, string.format("Would open %d (%s pearls) for %s, keeping %s pearls.", st.open, U.fmt(st.open * HUNT.STAR_COST), st.why, U.fmt(CFG.pearlFloor)))
        elseif st.why ~= "" then table.insert(lines, string.format("Wants %s, but that would go under the %s pearls you keep.", st.why, U.fmt(CFG.pearlFloor)))
        else table.insert(lines, "No need for more stars.") end
    end
    if HUB.pickNote.skins then table.insert(lines, HUB.pickNote.skins) end
    return table.concat(lines, "\n")
end
-- one action a pass, each checked against what really changed. Off until you switch it on, and the first refusal stops it for 30 min
function HUNT.skinTick()
    if not (CFG.skinSmart or CFG.starOpen) or not (B.live.event and HUNT.is(B.live.event.level)) then return end
    if (SF.req.back.skins or 0) > U.now() then return end
    local s = C.session()
    local function refused(what, t0, r)
        local said = SF.gameSaid(t0)
        HUB.pickNote.skins = string.format("%s: the game said no (%s). Trying again in 30 min.", what, tostring(said or r or "no answer"))
        SF.log(1, "LOBBY", HUB.pickNote.skins)
        SF.backoff("skins", 1800)
    end
    local plan = HUNT.skinPlan()
    if CFG.skinSmart then
        local w = plan.wear[1]
        if w and (SF.req.back.skinWear or 0) <= U.now() then
            -- (the game puts a skin only on a unit off the team, "Please unequip this unit first": it steps out for a moment and goes back into its slot, as a relic swap does)
            local slot = STR.slotOf(w.unit)
            if slot then
                B.str.reequip = { uuid = w.unit, slot = slot }
                SF.saveNow()
                SF.request("uneq", "unequip_unit", w.unit)
                local t1 = U.now()
                while U.now() - t1 < 4 and STR.slotOf(w.unit) do task.wait(0.25) end
            end
            local t0 = U.now()
            local _, r = SF.request("skinWear", "use_unique_item", w.uuid, { unit_uuid = w.unit })
            local function on() local u = s.collection:get_unit_by_uuid(w.unit); return u and u.skin ~= nil end
            while U.now() - t0 < 5 and not on() do task.wait(0.25) end
            if slot then STR.reequip() end
            if on() then
                SF.log(1, "LOBBY", string.format("Summer skins: %s on %s", w.name, w.unitName)); HUB.pickNote.skins = nil
                plan = HUNT.skinPlan()
            else
                -- (a refused skin doesn't hold up the selling: only wearing waits)
                local said = SF.gameSaid(t0)
                HUB.pickNote.skins = string.format("Wearing %s: the game said no (%s). Trying again in 30 min.", w.name, tostring(said or r or "no answer"))
                SF.log(1, "LOBBY", HUB.pickNote.skins)
                SF.backoff("skinWear", 1800)
            end
        end
        if #plan.sell > 0 then
            local list, pays = {}, 0
            for i = 1, math.min(50, #plan.sell) do table.insert(list, plan.sell[i].uuid); pays = pays + plan.sell[i].pearls end
            local before = tonumber(C.cur("SummerPearls")) or 0
            local t0 = U.now()
            local _, r = SF.request("skinSell", "delete_unique_items", list)
            while U.now() - t0 < 5 and (tonumber(C.cur("SummerPearls")) or 0) <= before do task.wait(0.25) end
            local got = (tonumber(C.cur("SummerPearls")) or 0) - before
            if got <= 0 then return refused("Selling skins", t0, r) end
            SPEND.add(string.format("sold %d spare Summer skins", #list), #list, "skins", string.format("Smart Skins: +%s pearls", U.fmt(got))); HUB.pickNote.skins = nil
        end
    end
    if CFG.starOpen then
        -- (a burst a pass, buy then open, for up to 15 s: a lobby visit often has room for one pass only, when a team search takes the rest)
        local inv = s.inventory
        local function held() local okN, n = pcall(inv.get_number_of_owned_item, inv, HUNT.STAR); return okN and tonumber(n) or 0 end
        local t1 = U.now()
        for _ = 1, 8 do
            if U.now() - t1 > 15 or not SF.alive or SF.where ~= "lobby" then break end
            local have = held()
            local st = HUNT.starPlan(HUNT.skinPlan())
            local t0 = U.now()
            if have > 0 then
                local _, r = SF.request("starOpen", "use_item", HUNT.STAR, { use10 = have >= 10, use_all = false })
                while U.now() - t0 < 6 and held() >= have do task.wait(0.25) end
                if held() >= have then return refused("Opening a Sunny Star", t0, r) end
                SF.log(1, "LOBBY", string.format("Sunny Stars: opened %d · %d opened in all", have - held(), (tonumber(((C.prof().capsule_pity_data or {})[HUNT.STAR] or {}).total_opens) or 0)))
                HUB.pickNote.skins = nil
            elseif st.open > 0 then
                local n = st.open >= 10 and 10 or 1
                local before = tonumber(C.cur("SummerPearls")) or 0
                local _, r = SF.request("starBuy", "buy_item_generic", HUNT.STAR, "event", "event_shop", tostring(n))
                while U.now() - t0 < 5 and held() <= 0 do task.wait(0.25) end
                if held() <= 0 then return refused("Buying a Sunny Star", t0, r) end
                SPEND.add(string.format("%d Sunny Stars", held()), before - (tonumber(C.cur("SummerPearls")) or 0), "Summer Pearls", "Open Sunny Stars: for " .. st.why)
                HUB.pickNote.skins = nil
            else break end
        end
    end
end
function MODE.list()
    local p = C.prof()
    if not p then return {} end
    local ld = p.level_data
    local out = {}
    local now = os.time()
    local function add(m)
        m.rec = MODE.rec(m.key)
        if (m.rec.restUntil or 0) > now or not MODE.allowed(m) then return end
        m.mod = m.mod or MODE.levelMod(m.level)
        if (m.kind == "daily" or m.kind == "challenge") and not (m.kind == "daily" and CFG.dailyLoop) then
            local okC, why = MODE.chOk(m)
            MODE.skipped[m.key] = not okC and (m.label .. ": " .. why) or nil
            if not okC then return end
        end
        table.insert(out, m)
    end
    -- daily challenge (once a day) and the half-hour challenge (once per rotation)
    local live = B.live or {}
    if (CFG.dailyChallenge or CFG.onlyChallenges or CFG.dailyLoop) and live.daily and live.daily.uuid and live.daily.uuid ~= p.last_completed_daily_challenge_uuid
        and live.daily.uuid ~= live.daily.doneUuid and ((live.daily.lost or 0) < 2 or CFG.dailyLoop) then
        add({ key = "dc", kind = "daily", level = "__DAILY_CHALLENGE", diff = "Hard", value = live.daily.value or 300,
            label = "Daily Challenge", why = string.format("daily reward ≈%s gems of gems + items", U.fmt(live.daily.value or 0)), mod = live.daily.mod })
    end
    if (CFG.challenge or CFG.onlyChallenges) and live.normal and live.normal.uuid and live.normal.uuid ~= p.last_completed_challenge_uuid
        and live.normal.uuid ~= live.normal.doneUuid and (live.normal.expires or 0) > now + 360 and (live.normal.lost or 0) < 2 then
        add({ key = "ch", kind = "challenge", level = live.normal.level, diff = "Hard", value = live.normal.value or 100,
            label = "Challenge · " .. MODE.levelName(live.normal.level), why = "new challenge every 30 min", challenge = live.normal.challenge })
    end
    -- story: first clears (Normal, then Hard on the same act) and farm runs on cleared acts. Your pick (Home tab): the next map you haven't beaten, or one act, again and again
    local order = U.list(C.WLO.WORLD_ORDER)
    local sp = CFG.pickStory or ""
    local function storyRow(id, diff, rank, picked)
        if not MODE.done(ld, id, diff) then
            return { key = "st:" .. id .. ":" .. diff, kind = "story", first = true, level = id, diff = diff, rank = rank, picked = picked,
                value = (C.GS.GEM_REWARD_STORY_FIRST or 60) + CFG.unlockValue,
                p0 = rank >= 16 and MODE.PRIOR_WIN.new or (diff == "Hard" and MODE.PRIOR_WIN.hard or MODE.PRIOR_WIN.story),
                label = MODE.levelName(id) .. " (" .. diff .. ")", why = (picked and "your pick · " or "") .. "first clear: " .. (C.GS.GEM_REWARD_STORY_FIRST or 60) .. " gems + unlocks the next act" }
        end
        return { key = "st:" .. id .. ":" .. diff, kind = "story", level = id, diff = diff, rank = rank, picked = picked,
            value = (C.GS.GEM_REWARD_STORY or 20), p0 = diff == "Hard" and MODE.PRIOR_WIN.hard or MODE.PRIOR_WIN.story,
            label = MODE.levelName(id) .. " (" .. (picked and diff or "farm") .. ")", why = (picked and "your pick · " or "") .. (C.GS.GEM_REWARD_STORY or 20) .. " gems a clear" }
    end
    local function eachAct(fn)
        for rank, w in ipairs(order) do
            local wd = C.Worlds[w]
            if wd and not wd.legend_stage and not wd.raid_world then
                for _, a in ipairs(U.list(wd.levels)) do
                    if MODE.open(a.id) and fn(a.id, rank) then return end
                end
            end
        end
    end
    if not (CFG.firstClears or CFG.farm or CFG.onlyStory) then
        -- (Story is Off on the Play tab: no story at all, your map pick neither. Off means never, the user's words, Nov 2)
    elseif sp == "progress" then
        -- the first map you haven't beaten on Normal, in the game's order; once they're all beaten, the first on Hard
        for _, diff in ipairs({ "Normal", "Hard" }) do
            local found
            eachAct(function(id, rank)
                if MODE.diffOpen(id, diff) and not MODE.done(ld, id, diff) then found = storyRow(id, diff, rank, true); return true end
            end)
            if found then add(found); break end
        end
    elseif sp ~= "" then
        local id, diff = sp:match("^st:(.+):(%a+)$")
        if id and MODE.open(id) and MODE.diffOpen(id, diff) then add(storyRow(id, diff, 1, true)) end
    else
        eachAct(function(id, rank)
            for _, diff in ipairs({ "Normal", "Hard" }) do
                if MODE.diffOpen(id, diff) and not MODE.done(ld, id, diff) and (CFG.firstClears or CFG.onlyStory) then
                    add(storyRow(id, diff, rank, false))
                    break -- Hard needs Normal first
                end
            end
            if CFG.farm and rank <= 3 and MODE.done(ld, id, "Normal") then add(storyRow(id, "Normal", rank, false)) end
        end)
    end
    -- raids: tries left today, gems + raid items. Your pick (Home tab): just that raid
    local rp = CFG.pickRaid or ""
    -- (Off means never: a pick only chooses which raid while raids are On)
    if CFG.raids or CFG.onlyRaids then
        for _, w in ipairs(U.list(C.WLO.RAID_WORLD_ORDER)) do
            local wd = C.Worlds[w]
            for _, a in ipairs(U.list(wd and wd.levels)) do
                local lv = C.Levels[a.id]
                if lv and MODE.open(a.id) and (rp == "" or rp == "rd:" .. a.id) then
                    local tries = tonumber(lv._raid_daily_tries)
                    local used = (p.raid_tries and p.raid_tries.levels and tonumber(p.raid_tries.levels[a.id])) or 0
                    if not tries or used < tries then
                        local items, goalTxt = 0, nil
                        for _, x in ipairs(ADV.levelItems(lv)) do
                            items = items + MODE.itemValue(x.item, x.per)
                            if B.goalItems[x.item] then goalTxt = string.format("≈%.0f %s a run toward your goal", x.per, (C.Items[x.item] or {}).name or x.item) end
                        end
                        local first = not MODE.done(ld, a.id)
                        local gems = tonumber(lv._override_gem_reward) or (C.GS.GEM_REWARD_RAID or 75)
                        add({ key = "rd:" .. a.id, kind = "raid", level = a.id, diff = "Hard", first = first, picked = rp ~= "",
                            value = gems + items + (first and CFG.unlockValue or 0), p0 = MODE.PRIOR_WIN.raid,
                            label = MODE.levelName(a.id), why = (rp ~= "" and "your pick · " or "") .. (goalTxt and (goalTxt .. " · ") or "") .. string.format("raid: %d gems + items%s", gems, tries and string.format(" · %d/%d tries left", tries - used, tries) or "") })
                    end
                end
            end
        end
    end
    -- legend stages, when they drop an item one of your goals needs. Legend Stages Only plays them all by what they drop, and your pick (Home tab) just that one.
    -- Progress (the user's call, Nov 2): the first legend stage you haven't beaten, in the game's order, as your pick; the ones that drop what a goal needs rank as Smart has them
    local lp = CFG.pickLegend or ""
    local lpKey = lp ~= "progress" and lp ~= "" and lp or nil
    if lp == "progress" then
        for _, w in ipairs(U.list(C.WLO.LEGEND_WORLD_ORDER)) do
            local wd = C.Worlds[w]
            for _, a in ipairs(U.list(wd and wd.levels)) do
                if not lpKey and C.Levels[a.id] and MODE.open(a.id) and not MODE.done(ld, a.id, "Hard") then lpKey = "st:" .. a.id .. ":Hard" end
            end
        end
    end
    if (CFG.goals and next(B.goalItems)) or CFG.onlyLegend or lp ~= "" then
        for _, w in ipairs(U.list(C.WLO.LEGEND_WORLD_ORDER)) do
            local wd = C.Worlds[w]
            for _, a in ipairs(U.list(wd and wd.levels)) do
                local lv = C.Levels[a.id]
                local key = "st:" .. a.id .. ":Hard"
                if lv and MODE.open(a.id) and (lp == "" or lp == "progress" or lp == key) then
                    local all = CFG.onlyLegend or (lp ~= "" and lp ~= "progress")
                    local items, goalTxt, any = 0, nil, 0
                    for _, x in ipairs(ADV.levelItems(lv)) do
                        if B.goalItems[x.item] then
                            items = items + MODE.itemValue(x.item, x.per)
                            goalTxt = string.format("≈%.1f %s a run toward your goal", x.per, (C.Items[x.item] or {}).name or x.item)
                        elseif all then
                            items = items + MODE.itemValue(x.item, x.per)
                            any = any + 1
                        end
                    end
                    if items > 0 or lpKey == key then
                        local first = not MODE.done(ld, a.id, "Hard")
                        add({ key = key, kind = "story", legend = true, picked = lpKey == key, level = a.id, diff = "Hard", first = first,
                            value = items + (first and ((C.GS.GEM_REWARD_STORY_FIRST or 60) + CFG.unlockValue) or 0), p0 = MODE.PRIOR_WIN.hard,
                            label = MODE.levelName(a.id), why = (lpKey == key and (lp == "progress" and "the next legend stage you haven't beaten · " or "your pick · ") or "") .. (goalTxt or string.format("legend stage: %d kinds of drops", any)) })
                    end
                end
            end
        end
    end
    -- Infinite: each map's daily gems up to the wave the team reaches there (every map spawns the same number of
    -- enemies, only their toughness differs, so the easy maps last longest); takedown training counts on top. Your pick (Home tab): just that map
    local ip = CFG.pickInfinite or ""
    -- (Off means never: a pick only chooses which map while Infinite is On)
    if CFG.infinite or CFG.onlyInfinite then
        for _, id in ipairs(MODE.infIds()) do
            if MODE.open(id) and (ip == "" or ip == "inf:" .. id) then
                local key = "inf:" .. id
                local reach, real = MODE.infReach(key)
                local gems, top, claimed = MODE.infDaily(p, id, reach)
                -- (a map that drops a portal a goal's item comes from, and a daily mission its enemies count toward: Shibuya District, Nov 2)
                local okB, pb, pbWhy = pcall(MODE.portalBonus, id)
                local okM, mv, mvWhy = pcall(MODE.missionValue, id)
                pb, mv = okB and pb or 0, okM and mv or 0
                local extra = (pb > 0 and pbWhy and (" · " .. pbWhy) or "") .. (mv > 0 and mvWhy and (" · " .. mvWhy) or "")
                add({ key = key, kind = "infinite", level = id, diff = "Hard", value = gems + pb + mv, p0 = 1, reach = reach, picked = ip ~= "", portalMap = pb > 0 or nil, extra = extra,
                    label = MODE.levelName(id), why = (ip ~= "" and "your pick · " or "") .. string.format("until the base falls (≈wave %d%s) · %s", math.floor(reach + 0.5), real and "" or ", not played yet",
                        gems > 0 and string.format("daily gems: %d up to wave %d", gems, top) or (claimed > 0 and "today's gems claimed" or "no daily gems in reach")) .. extra })
            end
        end
    end
    -- your portals (MODE.PORTALS), while a goal needs what their map drops
    local okPt, pts = pcall(MODE.portalRows)
    for _, m in ipairs(okPt and pts or {}) do add(m) end
    -- the dungeon: one room a run (its chests, coins, shops and shrines are worth CFG.dungeonValue a room); the
    -- win chance is the next room's (DG.pick: by depth, real results and the simulator)
    if CFG.dungeon or CFG.onlyDungeons then
        local dd = DG.data()
        if dd and (dd._started or CFG.dungeonStart or CFG.onlyDungeons) then
            local okP, x = pcall(DG.pick, dd)
            x = okP and x or nil
            local money, n, g = DG.res(dd)
            local okV, payV = pcall(DG.payValue)
            add({ key = "dg", kind = "dungeon", level = "dungeon", diff = "Hard", value = (okV and payV) or CFG.dungeonValue, p0 = x and x.p or MODE.PRIOR_WIN.dungeon, started = dd._started or nil,
                label = dd._started and string.format("Dungeon room %d/%d", x and x.d or (DG.depth(dd) or 1), DG.ROOMS) or "Dungeon (new run)",
                why = dd._started and string.format("%s · %d lives · %d coins · chests %d + %d rare", x and DG.roomName(x) or "between rooms", DG.lives(dd), money, n, g)
                    or "a new run: 20 rooms with chests, shops and shrines" })
        end
    end
    -- the current event: Fool's Hunt pays AprilCoins per wave (measured per run, so an event boost counts while
    -- it lasts); while the pull goal still needs coins they're worth more (ADV.pullGoal)
    if (CFG.event or CFG.onlyCoins or B.nextMode) and live.event and HUNT.is(live.event.level) then
        add(HUNT.row(MODE.rec("ev:" .. tostring(live.event.level))))
    elseif (CFG.event or CFG.onlyCoins) and live.event and live.event.level then
        local r = MODE.rec("ev:" .. live.event.level)
        local coins = r.runs > 0 and (r.coins / r.runs) or 400
        local goal = ADV.pullGoal()
        local per = goal and goal.needCoins > 0 and math.max(CFG.aprilValue, CFG.goalCoinValue) or CFG.aprilValue
        add({ key = "ev:" .. live.event.level, kind = "event", level = live.event.level, diff = "Hard",
            value = coins * per, coins = coins, p0 = MODE.PRIOR_WIN.event,
            label = live.event.name or "Event", why = string.format("≈%d %s a run (×%.2f gems each%s)", math.floor(coins), MODE.coinName(), per,
                goal and goal.needCoins > 0 and (", for " .. UNIT.name(goal.to)) or "") })
    end
    return out
end
function MODE.teamSig()
    if MODE._sigAt and U.now() - MODE._sigAt < 20 then return MODE._sig end
    local units = {}
    for _, e in ipairs(UNIT.equipped()) do table.insert(units, e.u) end
    MODE._sig, MODE._sigAt = SIM.sig(units), U.now()
    return MODE._sig
end
-- a simulation of this mode with the team you have equipped now (nil when there is none or it's stale)
function MODE.sim(m)
    local sr = CFG.sim and B.simRes[m.key]
    -- (or with your own team, when training or a planned team has borrowed the slots. Modes are simulated with your own team in the lobby, so on a results screen every simulation read as out of date: the Daily Challenge fell back on its hopeful guess, came out on top,
    -- and the run went to the lobby "for" it, where your team came back, the simulation counted again, and something else was launched. 6 runs of Nov 1's evening)
    if sr and sr.p and os.time() - (sr.at or 0) < 6 * 3600 and (sr.sig == MODE.teamSig() or sr.sig == MODE.ownSig()) then return sr end
    return nil
end
-- your own team's signature, whatever a run has borrowed its slots for
function MODE.ownSig()
    -- (B.savedTeam first: a training run's base is the team the search picked for that mode, not yours, and it's yours the lobby simulates with)
    local list = (type(B.savedTeam) == "table" and #B.savedTeam > 0 and B.savedTeam) or (B.train.on and B.train.on.base)
    if type(list) ~= "table" or #list == 0 then return nil end
    if MODE._ownAt and U.now() - MODE._ownAt < 20 then return MODE._own end
    local s = C.session()
    local units = {}
    for _, uuid in ipairs(list) do
        local u = s and s.collection:get_unit_by_uuid(uuid)
        if u then table.insert(units, u) end
    end
    MODE._own, MODE._ownAt = #units > 0 and SIM.sig(units) or nil, U.now()
    return MODE._own
end
-- the act the game's Next button goes to from a level
function MODE.nextAct(level)
    MODE._next = MODE._next or {}
    local v = MODE._next[level]
    if v == nil then
        local ok, n = pcall(C.PSC.get_next_story_level, level)
        v = ok and n or false
        MODE._next[level] = v
    end
    return v or nil
end
function MODE.winP(m)
    local r = m.rec
    local p0 = m.p0 or MODE.PRIOR_WIN[m.kind] or 0.7
    local sr = MODE.sim(m)
    -- the sim's weight is earned per mode: 1.5 runs of evidence before the mode has any real run (the prior
    -- still counts, so one calibration run can happen), 3 once calibrated, 6 once it matched real runs with
    -- this team — and none where it failed that check (real runs decide there)
    if sr and not (sr.trust and not sr.trust.ok) then
        local calibrated = sr.calibrated or r.runs > 0
        local w = (sr.trust and sr.trust.ok) and 6 or (calibrated and 3 or 1.5)
        local pw = calibrated and 0 or 2
        return (r.wins + p0 * pw + sr.p * w) / (r.runs + pw + w)
    end
    return (r.wins + p0 * 2) / (r.runs + 2)
end
function MODE.minutes(m)
    local r = m.rec
    local timed = tonumber(r.timed) or 0
    local sr = m.kind == "infinite" and B.simRes[m.key]
    local mins = (timed > 0 and r.sec > 0) and (r.sec / timed / 60) or (sr and tonumber(sr.minutes)) or MODE.PRIOR_MIN[m.kind] or 6
    return mins + MODE.OVERHEAD
end
function MODE.score(m)
    -- (an event that pays per wave pays on a loss too: its measured coins a run already count every outcome;
    -- an Infinite run always ends with the base falling: its value already counts only the waves it reaches)
    -- (a dungeon room's chance is the next room's own: DG.winP already counts the real results by depth)
    local p, mins = ((m.kind == "event" and m.rec.runs > 0) or m.kind == "infinite") and 1 or (m.kind == "dungeon" and m.p0) or MODE.winP(m), MODE.minutes(m)
    -- the Team tab: the XP this run gives your core units, in gems (STR.modeBonus; measured per mode, else the game's formula)
    local okB, bonus, bonusWhy = pcall(STR.modeBonus, m)
    if okB and (bonus or 0) > 0 then
        m.teamBonus = bonus
        if not tostring(m.why):find("for your team", 1, true) then m.why = (m.why or "") .. " · " .. bonusWhy end
    end
    local s = p * (m.value + (m.teamBonus or 0)) / mins
    m.baseScore = s
    -- takedown training: the trainee's progress counts too, on a run that may be a bit slower (TRAIN.valueFor)
    local okT, tv, slow = pcall(TRAIN.valueFor, m)
    if okT and tv > 0 then
        local s2 = p * (m.value + tv) / (mins * slow)
        if s2 > s then s, m.train = s2, tv end
    end
    if m.rec.runs < 2 then s = s * (1 + CFG.exploreBonus) end
    return s
end
-- real runs for units the simulator can't read (the user's go-ahead, Nov 1, after Elyssia read 32% in the sim and did 88%): one run each on an easy map. The unit on trial gets the yen, so the damage it shows is its own (MT.econ), and the
-- rest of your team only stands by for when enemies get far. Your own team goes back after the last one (HUB.teamFor, from B.savedTeam). Each run's line goes in the log as TRIAL and in AA_SmartFarm/trials.txt
function MODE.trialRow()
    local t = B.trial
    if type(t) ~= "table" or type(t.list) ~= "table" then return nil end
    local id = t.list[tonumber(t.i) or 1]
    if not id then return nil end
    -- (t.kind: a trial on the Daily Challenge, "daily" on key "dc" — the user's call, Nov 2, for Snow Reaper's Gale on a harder map)
    return { key = t.key, kind = t.kind or "story", level = t.level, diff = t.diff, label = t.label, rec = MODE.rec(t.key), value = 0, p0 = 1, p = 1, score = 0,
        why = string.format("trial %d of %d: %s", tonumber(t.i) or 1, #t.list, UNIT.name(id)) }
end
-- right before a launch: your team with the unit on trial in your weakest attacker's slot
function MODE.trialTeam()
    local t = B.trial
    local id = t.list[tonumber(t.i) or 1]
    if B.train.on then TRAIN.home() end
    local s = C.session()
    local best, top
    for _, o in pairs(s.profile_data.collection.owned_units) do
        if o.unit_id == id then
            local u = s.collection:get_unit_by_uuid(o.uuid) or o
            local okS, sc = pcall(UNIT.score, u)
            sc = okS and sc or 0
            if not top or sc > top then best, top = u, sc end
        end
    end
    if not best then
        SF.log(1, "TRIAL", UNIT.name(id) .. ": no copy of it any more, skipped")
        t.i = (tonumber(t.i) or 1) + 1
        return false
    end
    local own = table.clone(B.savedTeam or TRAIN.team())
    local has = table.find(own, best.uuid) ~= nil
    if not has then
        local slot, low
        for i, uuid in ipairs(own) do
            local u = s.collection:get_unit_by_uuid(uuid)
            if u and not UNIT.isFarm(u.unit_id) and not UNIT.allyBuff(u.unit_id) then
                local okS, sc = pcall(UNIT.score, u)
                sc = okS and sc or 0
                if not low or sc < low then slot, low = i, sc end
            end
        end
        if slot then own[slot] = best.uuid else table.insert(own, best.uuid) end
    end
    if not TRAIN.same(TRAIN.team(), own) then HUB.equipTeam(own, "trial run for " .. UNIT.name(id)) end
    return true
end
-- a trial's result, for the log and the file
function MT.trialDone(won, sec)
    local t = B.trial
    local id = MT.trialId
    if type(t) ~= "table" or not id then return end
    local shares, sum = MT.damageShares()
    sum = sum or 0
    local dealt = shares and (shares[id] or 0) * sum or 0
    local rows = UNIT.rows(id)
    local copies, topLvl, yen = 0, 0, 0
    for _, o in pairs(MT.ownDealt or {}) do
        if o.id == id then
            copies = copies + 1
            topLvl = math.max(topLvl, o.lvl or 0)
            yen = yen + (tonumber(rows and rows[0] and rows[0].cost) or 0)
            for l = 1, o.lvl or 0 do yen = yen + (tonumber(rows and rows[l] and rows[l].cost) or 0) end
        end
    end
    local others = {}
    for k, v in pairs(shares or {}) do if k ~= id and v >= 0.005 then table.insert(others, { n = k == "helpers" and k or UNIT.name(k), v = v }) end end
    table.sort(others, function(a, b) return a.v > b.v end)
    local words = {}
    for _, o in ipairs(others) do table.insert(words, string.format("%s %d%%", (o.n:gsub(" %(.+%)", "")), math.floor(o.v * 100 + 0.5))) end
    local sim = MT.trialSim
    local simText = sim and string.format("the sim expected %s alone: %s at wave %d, %s damage, upgrade %s", (UNIT.name(id):gsub(" %(.+%)", "")), sim.won and "wins" or "falls", sim.wave, U.fmt(sim.dealt or 0), tostring(sim.lvl or "?")) or "no sim reading"
    local line = string.format("%s · %s at wave %d of %d in %.1f min · dealt %s, %d%% of %s · %d copies, top upgrade %d of %d, about ¥%s · ability cast %d times · stood by: %s · %s",
        UNIT.name(id), won and "won" or "lost", MT.wave(), MT.total or 0, (sec or 0) / 60, U.fmt(dealt), math.floor((shares and shares[id] or 0) * 100 + 0.5), U.fmt(sum), copies, topLvl, rows and rows.max or 0,
        U.fmt(yen), MT.casts and MT.casts[id] or 0, #words > 0 and table.concat(words, ", ") or "nobody", simText)
    SF.log(1, "TRIAL", line)
    local file = "AA_SmartFarm/trials.txt"
    local okR, old = pcall(readfile, file)
    pcall(writefile, file, (okR and type(old) == "string" and old or "") .. os.date("%H:%M ") .. line .. "\n")
    do
        local r = MT.calRun or {}
        local words = {}
        if (r.potSum or 0) > 0 then table.insert(words, string.format("real/listed damage %.2f", (r.dealtSum or 0) / r.potSum)) end
        local traceFile = "AA_SmartFarm/trial_trace.txt"
        local okT, oldT = pcall(readfile, traceFile)
        pcall(writefile, traceFile, (okT and type(oldT) == "string" and oldT or "") .. os.date("%H:%M ") .. UNIT.name(id) .. " " .. table.concat(words, " ") .. "\n" .. table.concat(MT.trialTrace or {}, "\n") .. "\n\n")
    end
    t.results = type(t.results) == "table" and t.results or {}
    table.insert(t.results, { id = id, won = won and true or false, wave = MT.wave(), sec = sec, dealt = dealt, share = shares and shares[id] or 0, sum = sum, copies = copies, lvl = topLvl, yen = yen, casts = MT.casts and MT.casts[id] or 0, sim = sim })
    t.i = (tonumber(t.i) or 1) + 1
    if not t.list[t.i] then
        SF.log(1, "TRIAL", "all trial runs done: your own team goes back in")
        B.trial = nil
    end
    SF.saveNow()
end
function MODE.pick()
    local trial = MODE.trialRow()
    if trial then MODE.lastScored = { trial }; return trial end
    local list = MODE.list()
    for _, m in ipairs(list) do
        m.score = MODE.score(m); m.p = MODE.winP(m)
        local sr = MODE.sim(m)
        if sr and not tostring(m.why):find("sim:") then
            local untrusted = sr.trust and not sr.trust.ok
            m.why = (m.why or "") .. " · sim: " .. (untrusted and string.format("not trusted here (off ×%.1f vs real runs)", sr.trust.ratio) or tostring(sr.playing or sr.margin))
        end
        if m.train then m.why = (m.why or "") .. string.format(" · takedown training ≈%d gems of progress", math.floor(m.train + 0.5)) end
    end
    table.sort(list, function(a, b) return a.score > b.score end)
    -- a dungeon run that's going is played to its end (its chests pay out at floor 20, and rooms chain from the
    -- results screen with no lobby in between): it goes first, except for the once-a-day Daily Challenge
    for i, m in ipairs(list) do
        if m.kind == "dungeon" and m.started then
            if i > 1 and list[1].kind ~= "daily" then
                table.remove(list, i); table.insert(list, 1, m)
                m.why = "finishing the run · " .. (m.why or "")
            end
            break
        end
    end
    -- Auto Evolve: what the picked unit still needs goes first, ahead of a dungeon run (a Daily Challenge on top stays on top)
    if CFG.autoEvolve and CFG.evolveUnit ~= "" then
        local daily = list[1] and list[1].kind == "daily" and list[1] or nil
        local hits, rest = {}, {}
        for _, m in ipairs(list) do
            if m ~= daily then
                if MODE.dropsGoal(m) or m.train then
                    m.why = "for your focus unit · " .. (m.why or "")
                    table.insert(hits, m)
                else table.insert(rest, m) end
            end
        end
        if #hits > 0 then
            list = {}
            if daily then table.insert(list, daily) end
            for _, m in ipairs(hits) do table.insert(list, m) end
            for _, m in ipairs(rest) do table.insert(list, m) end
        end
    end
    -- a portal you hold goes first (its rows only exist while a goal needs what it drops): the user's loop, Nov 2, is to farm Shibuya Infinite for portals and then play them. Ranked by
    -- gems a minute, the map that drops them read 61 against the portal's 33 and would have been replayed while the portals piled up. A Daily Challenge or a dungeon run that's going stays on top
    for i, m in ipairs(list) do
        if m.kind == "portal" then
            local top = list[1]
            if i > 1 and top.kind ~= "daily" and not (top.kind == "dungeon" and top.started) then
                table.remove(list, i); table.insert(list, 1, m)
                m.why = "your portal first · " .. (m.why or "")
            end
            break
        end
    end
    -- acts in a row: the game's Next only goes up an act, at about 10 s against 40-60 through the lobby, and the ranking's own order went down them, since a later act pays a little more XP: Haunted Academy Act 4 then Act 3, a lobby trip each. So a run of first clears starts at its earliest act
    local head = list[1]
    if head and head.kind == "story" and head.first then
        -- (by the run's own pay: only the few modes with a training check carry that value, and the unit trains on whichever act plays, TRAIN.apply)
        local cur, floor = head, (head.baseScore or head.score) * MODE.CHAIN_MIN
        for _ = 1, 6 do
            local prev
            for _, m in ipairs(list) do
                if m.kind == "story" and m.first and m.diff == cur.diff and (m.baseScore or m.score) >= floor and MODE.nextAct(m.level) == cur.level then prev = m; break end
            end
            if not prev then break end
            cur = prev
        end
        if cur ~= head then
            table.remove(list, table.find(list, cur))
            table.insert(list, 1, cur)
            cur.why = "the first of these acts in a row · " .. (cur.why or "")
        end
    end
    -- a mode asked for once (B.nextMode: a test run) goes first while it can be played
    if B.nextMode then
        for i, m in ipairs(list) do
            if m.key == B.nextMode then table.remove(list, i); table.insert(list, 1, m); m.why = "asked for once · " .. (m.why or ""); break end
        end
    end
    -- Keep Playing Daily (the Farming tab): ahead of everything, whatever the simulator thinks of it
    if CFG.dailyLoop then
        for i, m in ipairs(list) do
            if m.kind == "daily" then table.remove(list, i); table.insert(list, 1, m); m.why = "you asked to keep playing it · " .. (m.why or ""); break end
        end
    end
    MODE.lastScored = list
    return list[1]
end
-- the mode being played in this match, as a key the ranking uses
function MODE.fromLevelData(ld)
    if not ld then return nil end
    local id = ld.id
    if id == "__DAILY_CHALLENGE" then return "dc", "daily" end
    if ld._dungeon then return "dg", "dungeon" end
    if ld._challenge then return "ch", "challenge" end
    -- (a portal's map: before Infinite, since a portal can be an Infinite map bound to a number of waves)
    if C.Levels[id] and C.Levels[id]._portal_only_level then return "pt:" .. id, "portal" end
    if ld._gamemode == "infinite" or ld.infinite then return "inf:" .. id, "infinite" end
    if ld._gamemode == "raid" and B.live.event and B.live.event.level == id then return "ev:" .. id, "event" end
    if ld._gamemode == "raid" or (C.Levels[id] and C.Levels[id].is_raid) then return "rd:" .. id, "raid" end
    if ld._gamemode == "story" then return "st:" .. id .. ":" .. tostring(ld._difficulty or "Normal"), "story" end
    return tostring(ld._gamemode) .. ":" .. tostring(id), tostring(ld._gamemode)
end

-- ============================================================
--  THE PATH TO STRONGER UNITS (goals → items → where to farm them)
-- ============================================================
-- what a level pays in items per run: {item, per} from its reward table (amount × chance; a "pick m of n"
-- group counts m/n of each), else 1 of each item it shows
function ADV.levelItems(lv, id)
    local out = {}
    if type(lv) ~= "table" then return out end
    id = id or lv.id
    local groups = lv.rewards
    if type(groups) == "table" and groups.item then groups = { groups } end
    local any = false
    for _, g in pairs(type(groups) == "table" and groups or {}) do
        if type(g) == "table" then
            local items = U.list(g.item)
            local share = 1
            if g._item_multichoice and #items > 0 then share = math.min(1, (tonumber(g._item_multichoice.min) or #items) / #items) end
            for _, x in ipairs(items) do
                if type(x) == "table" and x.item_id then
                    local amt = tonumber(x.amount) or ((tonumber(x.min_amount) or 1) + (tonumber(x.max_amount) or tonumber(x.min_amount) or 1)) / 2
                    table.insert(out, { item = x.item_id, per = amt * (tonumber(x.chance) or 1) * share })
                    any = true
                end
            end
        end
    end
    if not any then
        for _, r in pairs(type(lv._show_rewards) == "table" and lv._show_rewards or {}) do
            if type(r) == "table" and r.type == "item" and r.params and r.params.item_id then table.insert(out, { item = r.params.item_id, per = 1 }) end
        end
    end
    -- what runs there really dropped, from every farm's results screens (the brain hive, 3 runs at least): it replaces the listed odds, and adds what no list shows, the drops
    -- the server keeps to itself (a Shibuya Portal's Sacred Treasures)
    local okH, real = pcall(REPORT.hiveDrops, id)
    if okH and real then
        local at = {}
        for i, x in ipairs(out) do at[x.item] = i end
        for item, per in pairs(real) do
            if at[item] then out[at[item]].per = per else table.insert(out, { item = item, per = per }) end
        end
    end
    return out
end
function ADV.sources()
    if ADV._src then return ADV._src end
    local src = {}
    for id, lv in pairs(C.Levels) do
        for _, x in ipairs(ADV.levelItems(lv, id)) do
            src[x.item] = src[x.item] or {}
            table.insert(src[x.item], { level = id, per = x.per })
        end
    end
    for _, l in pairs(src) do table.sort(l, function(a, b) return a.per > b.per end) end
    ADV._src = src
    return src
end
function ADV.have(id) local s = C.session(); local n = 0; pcall(function() n = s.inventory:get_number_of_owned_item(id) end); return n end
-- kills / takedowns the unit still needs for its evolution (the game: _kill_requirement vs total_kills,
-- _takedown_requirement vs total_takedowns — Tamiki needs 5,000 takedowns); nil when it has them
function ADV.killsShort(u, req)
    if not req then return nil end
    local tk = tonumber(req._takedown_requirement)
    if tk and (tonumber(u.total_takedowns) or 0) < tk then return { what = "takedowns", have = tonumber(u.total_takedowns) or 0, need = tk } end
    local kl = tonumber(req._kill_requirement)
    if kl and (tonumber(u.total_kills) or 0) < kl then return { what = "kills", have = tonumber(u.total_kills) or 0, need = kl } end
    return nil
end
-- community tiers (C.TIERS): unit id → {overall, story, infinite} letters, built once from the game's names
ADV.TIER_RANK = { SS = 6, S = 5, A = 4, B = 3, C = 2, D = 1 }
function ADV.tiers()
    if ADV._tiers then return ADV._tiers end
    local byName = {}
    for id, d in pairs(C.Units) do
        -- (a unit you can own over a boss of the same name: "Hex" also names an enemy, fate_medea)
        if type(d) == "table" and type(d.name) == "string" then
            local k = d.name:lower()
            if not byName[k] or (d.rarity and not C.Units[byName[k]].rarity) then byName[k] = id end
        end
    end
    local out = {}
    -- (t.base keeps the first list's letters: gem-banner pulls use only those)
    local function higher(a, b) return not b or (ADV.TIER_RANK[a] or 0) > (ADV.TIER_RANK[b] or 0) end
    local function put(id, mode, tier, base)
        out[id] = out[id] or { base = {} }
        if higher(tier, out[id][mode]) then out[id][mode] = tier end
        if base and higher(tier, out[id].base[mode]) then out[id].base[mode] = tier end
    end
    for _, src in ipairs({ { C.TIERS, true }, { C.TIERS_USER, true }, { C.TIERS_EXTRA, false } }) do
        for mode, list in pairs(src[1]) do
            for tier, str in pairs(list) do
                for nm in str:gmatch("[^|]+") do
                    local id = C.TIER_ALIAS[nm] or byName[nm:lower()]
                    if id and C.Units[id] then put(id, mode, tier, src[2]) end
                end
            end
        end
    end
    ADV._tiers = out
    return out
end
-- a unit's rating: its best of the Story and overall lists (the farm plays story and raids), and all of them;
-- baseOnly: the first list's letters only (gem-banner pulls)
function ADV.tier(id, baseOnly)
    if not CFG.community then return nil, nil, 0 end
    local t = ADV.tiers()[id]
    if baseOnly and t then t = t.base end
    if not t then return nil, nil, 0 end
    local s, o = ADV.TIER_RANK[t.story or ""] or 0, ADV.TIER_RANK[t.overall or ""] or 0
    local main = s >= o and t.story or t.overall
    if not main then return nil, nil, 0 end
    return main, t, math.max(s, o)
end
function ADV.tierText(id)
    local main, t = ADV.tier(id)
    if not main then return nil end
    local parts = {}
    if t.story then table.insert(parts, "Story " .. t.story) end
    if t.overall then table.insert(parts, "overall " .. t.overall) end
    if t.infinite then table.insert(parts, "Infinite " .. t.infinite) end
    if t.castle then table.insert(parts, "Infinity Castle " .. t.castle) end
    return "tier " .. table.concat(parts, ", ")
end
-- the best rating a unit leads to: itself or its evolved form
function ADV.tierBest(id, baseOnly)
    local d = C.Units[id]
    local ev = d and d.evolve and d.evolve.evolve_unit
    local _, _, a = ADV.tier(id, baseOnly)
    local _, _, b = ADV.tier(ev, baseOnly)
    if ev and b > a then return ev, b end
    return id, a
end
-- a unit's role on the user's list (C.KEEP_ROLES), or nil
function ADV.role(id)
    if not ADV._roles then
        ADV._roles = {}
        for role, ids in pairs(C.KEEP_ROLES) do for _, x in ipairs(ids) do ADV._roles[x] = role end end
    end
    return ADV._roles[id]
end
-- a fuse's line (lower goes first), or nil to keep the unit. First the overall list's D tier, "Fusion Fodder", and the forms that lead only to it, then units with no rating, then C and B. Kept: anything rated
-- A or higher, the supports, control units and farm, and whatever leads to one of those, however many evolutions away (Shadow Sorcerer (Hybrid Shadow) is on the D tier and evolves into an S)
function ADV.fodderOrder(id)
    local best, seen, f = 0, {}, id
    while f and C.Units[f] and not seen[f] do
        seen[f] = true
        if ADV.role(f) then return nil end
        local _, _, r = ADV.tier(f)
        best = math.max(best, r)
        local d = C.Units[f]
        f = d.evolve and d.evolve.evolve_unit
    end
    if best >= ADV.TIER_RANK.A then return nil end
    local _, t = ADV.tier(id)
    if (t and t.overall == "D") or best == ADV.TIER_RANK.D then return 1 end
    return 2 + best
end
-- your n strongest units by the farm's score, worked out at most once a minute (the fuse lists ask often)
function ADV.strongest(n)
    if ADV._strong and ADV._strongN == n and U.now() - ADV._strongAt < 60 then return ADV._strong end
    local s = C.session()
    local list = {}
    for uuid, u0 in pairs(s.profile_data.collection.owned_units) do
        local ok, sc = pcall(UNIT.score, s.collection:get_unit_by_uuid(uuid) or u0)
        if ok and tonumber(sc) then table.insert(list, { uuid = uuid, sc = sc }) end
    end
    table.sort(list, function(a, b) return a.sc > b.sc end)
    local out = {}
    for i = 1, math.min(n, #list) do out[list[i].uuid] = true end
    ADV._strong, ADV._strongN, ADV._strongAt = out, n, U.now()
    return out
end
-- the Path tab's community paragraph: what the guides say about the banners and about your own units
function ADV.communityText()
    if not CFG.community then return "Off (Settings → Community tips)." end
    local p = C.prof()
    if not p then return "…" end
    local lines = {}
    local function bannerLine(label, banner, cost)
        local b = C.Banners[banner]
        local ids = {}
        for _, slot in pairs(b and b.rateup_units or {}) do
            if type(slot) == "table" and type(slot.possible_units_set) == "table" then for id in pairs(slot.possible_units_set) do table.insert(ids, id) end end
        end
        local rows = {}
        for _, id in ipairs(ids) do
            local ev, r = ADV.tierBest(id)
            table.insert(rows, { r = r, text = string.format("%s %s%s", UNIT.name(ev), (ADV.tier(ev)) or "unrated", UNIT.owns(id) and " (you have it)" or "") })
        end
        table.sort(rows, function(x, y) return x.r > y.r end)
        local parts = {}
        for _, x in ipairs(rows) do table.insert(parts, x.text) end
        if #parts > 0 then table.insert(lines, string.format("%s (%s): %s", label, cost, table.concat(parts, " · "))) end
    end
    bannerLine("April banner", "April2025", "150 AprilCoins a pull")
    bannerLine("Sakamoto banner", "SakamotoEvent", "10 Assassin Tokens a pull")
    bannerLine("Gem banner", "EventClover", "50 gems a pull")
    -- your units the guides rate A or better (a buffer is only worth it for units of its damage type)
    local teamTypes = {}
    for _, e in ipairs(UNIT.equipped()) do
        if not UNIT.isFarm(e.id) and not UNIT.allyBuff(e.id) then local _, base = UNIT.types(e.id); if base then teamTypes[base] = true end end
    end
    local mine, seen = {}, {}
    for _, u0 in pairs(p.collection.owned_units) do
        local ev, r = ADV.tierBest(u0.unit_id)
        if r >= 4 and not seen[ev] then
            seen[ev] = true
            local note = ""
            local bf = UNIT.allyBuff(ev)
            if bf then
                local hits = false
                for k in pairs(bf.types or {}) do if teamTypes[k] then hits = true end end
                if not hits then for k in pairs(bf.types or {}) do note = string.format(" (buffs %s units: your damage dealers aren't)", k) end end
            end
            if ev ~= u0.unit_id then note = note .. " (evolve " .. UNIT.name(u0.unit_id) .. ")" end
            table.insert(mine, { r = r, text = UNIT.name(ev) .. " " .. ((ADV.tier(ev)) or "") .. note })
        end
    end
    table.sort(mine, function(x, y) return x.r > y.r end)
    local parts = {}
    for i, x in ipairs(mine) do if i <= 8 then table.insert(parts, x.text) end end
    if #parts > 0 then table.insert(lines, "Yours rated A or better: " .. table.concat(parts, " · ")) end
    table.insert(lines, "The guides rank evolved, fully upgraded units and ignore traits (a strong trait can move a unit a whole tier). "
        .. "Their advice: save gems and commit to one banner.")
    return table.concat(lines, "\n")
end
-- the pull goal (Settings: pullGoal, e.g. "rikka" = Chuuni, SS once evolved): which step it's on and whether it
-- still needs AprilCoins — 1 pull it from the April banner · 2 buy its evolve item in the AprilCoins shop ·
-- 3 its takedowns (training) and evolve (smart evolve) · done
function ADV.pullGoal()
    local id = CFG.pullGoal
    if type(id) ~= "string" or id == "" or type(C.Units[id]) ~= "table" then return nil end
    local p = C.prof()
    if not p then return nil end
    local d = C.Units[id]
    local to = d.evolve and d.evolve.evolve_unit or id
    local g = { id = id, to = to, coins = C.cur("AprilCoins"), itemCost = 0, needCoins = 0 }
    for _, it in pairs(d.evolve and d.evolve.normal and d.evolve.normal.item_requirement or {}) do
        local sale = C.SaleEvent[it.item_id]
        if sale and type(sale.resource_cost) == "table" and sale.resource_cost.id == "AprilCoins" then g.item, g.itemCost = it.item_id, tonumber(sale.resource_cost.amount) or 0 end
    end
    g.haveItem = g.item ~= nil and ADV.have(g.item) > 0
    local base, evolved = HUB.hatched[id] or false, false
    for _, u0 in pairs(p.collection.owned_units) do
        if u0.unit_id == id then base = true end
        if u0.unit_id == to then evolved = true end
    end
    if evolved then g.step = "done"
    elseif not base then g.step, g.needCoins = "pull", 1 -- every 1,500 AprilCoins is another 10-pull
    elseif g.item and not g.haveItem then g.step, g.needCoins = "item", math.max(0, g.itemCost - g.coins)
    else g.step = "evolve" end
    return g
end
-- the Path tab's main-goal paragraph
function ADV.goalText()
    local g = ADV.pullGoal()
    if not g then return "No main goal set (Settings: pull goal)." end
    local p = C.prof()
    local head = string.format("%s%s · ", UNIT.name(g.to), (ADV.tier(g.to)) and (" (tier " .. ADV.tier(g.to) .. ")") or "")
    if g.step == "pull" then
        -- (the April banner left the game with Update 21)
        if not C.Banners.April2025 then return head .. string.format("the April banner isn't in the game right now, so there's nothing to pull %s from. This waits until it comes back.", UNIT.name(g.id)) end
        local floor = math.max(CFG.aprilFloor, g.haveItem and 0 or g.itemCost)
        local pity = p and p.pity_data and p.pity_data.April2025
        local since = pity and tonumber(pity.opens_since_mythic)
        return head .. string.format("step 1 of 3: pull %s from the April banner. You have %s AprilCoins: %d ten-pulls above the %s kept for its evolve item. "
            .. "Each Mythic from this banner is one of 3 limited units (1 in 3 is %s), and one is guaranteed every 200 pulls%s. "
            .. "The farm plays Fool's Hunt for AprilCoins (worth %.2f gems each to the ranking while this goal needs them)%s.",
            UNIT.name(g.id), U.fmt(g.coins), math.max(0, math.floor((g.coins - floor) / 1500)), U.fmt(floor), UNIT.name(g.id),
            since and string.format(" (%d pulls since the last Mythic)", since) or "", math.max(CFG.aprilValue, CFG.goalCoinValue),
            CFG.summonApril and " and pulls 10 at a time" or "; April pulls are off (Summon tab)")
    elseif g.step == "item" then
        return head .. string.format("step 2 of 3: you have %s! Its evolve item costs %s AprilCoins in the event shop; you have %s. The farm buys it when the coins are in.",
            UNIT.name(g.id), U.fmt(g.itemCost), U.fmt(g.coins))
    elseif g.step == "evolve" then
        return head .. "step 3 of 3: its takedowns come from training (it joins easy runs), then smart evolve evolves it."
    end
    return head .. "done, it's yours!"
end
-- spend: the pull goal's evolve item, once it's pulled and the coins are in (AprilCoins shop)
function HUB.eventShop()
    local g = ADV.pullGoal()
    if not (CFG.summonApril and g and g.step == "item" and g.coins >= g.itemCost and g.itemCost > 0) then return end
    if SF.req.back.eshop and U.now() < SF.req.back.eshop then return end
    local ok, r = SF.request("eshop", "buy_item_generic", g.item, "event", "event_shop", "1")
    local t0 = U.now()
    while U.now() - t0 < 4 and ADV.have(g.item) < 1 do task.wait(0.25) end
    local name = (C.Items[g.item] or {}).name or g.item
    if ADV.have(g.item) > 0 then
        SPEND.add(name, g.itemCost, "AprilCoins", "evolve item for " .. UNIT.name(g.to))
        if SF.notify then SF.notify("Main goal", "Bought " .. name .. " for " .. UNIT.name(g.id), "success") end
        pcall(ADV.refresh)
    else
        SF.log(1, "SHOP", "event shop refused " .. tostring(g.item) .. " (" .. tostring(ok and r or "no answer") .. ")")
        SF.backoff("eshop", 900)
    end
end
-- promo codes (lobby): each one your account hasn't used, sent at most once a day. Your profile here only shows a
-- code as used after the next teleport, so a sent code is confirmed on a later visit (redeemed_codes)
function HUB.codes()
    if not CFG.codes then return SF.status("Codes", "off (Settings)") end
    local p = C.prof()
    if not p then return end
    local used = p.redeemed_codes or {}
    local sent, confirmed = {}, {}
    for _, code in ipairs(C.CODES) do
        local last = tonumber(B.codes[code])
        if used[code] then
            if last and last > 0 then table.insert(confirmed, code); B.codes[code] = -1 end -- -1: confirmed, never again
        elseif os.time() - (last or 0) > 86400 and (last or 0) >= 0 then
            B.codes[code] = os.time()
            local ok = SF.request("code", "redeem_code", code)
            if ok then table.insert(sent, code) end
            task.wait(1)
        end
    end
    if #confirmed > 0 then SF.log(1, "CODES", "the game confirms " .. table.concat(confirmed, ", ")) end
    if #sent > 0 then SF.log(1, "CODES", "sent " .. table.concat(sent, ", ") .. " (the game confirms a code after the next teleport; one it refuses is tried again tomorrow)") end
    SF.saveSoon()
    local left = 0
    for _, code in ipairs(C.CODES) do if not used[code] then left = left + 1 end end
    SF.status("Codes", #sent > 0 and ("sent " .. table.concat(sent, ", ")) or (left == 0 and "every known code is redeemed ✓" or (left .. " codes not taken yet, trying again tomorrow")))
end
-- your copies of a unit an evolution could use up: unlocked (the game never takes a locked unit), shiny if it
-- must be, and not the unit being evolved
function ADV.copies(id, shiny, exclude)
    local s = C.session()
    local list = {}
    for _, o in pairs(s and s.profile_data.collection.owned_units or {}) do
        if o.unit_id == id and o.uuid ~= exclude and not o._locked and (not shiny or o.shiny) then table.insert(list, o) end
    end
    return list
end
-- where to farm an item: the most of it per minute, counting your win chance there (a big drop in a mode you
-- lose pays nothing) — from the farm's own ranking; levels it can't play now count at half odds and 10 min
function ADV.bestSource(levels)
    if not (MODE.lastScored and MODE.lastScored[1]) then pcall(MODE.pick) end
    local scored = {}
    for _, m in ipairs(MODE.lastScored or {}) do if m.level then scored[m.level] = m end end
    local best, bv
    for _, l in ipairs(levels or {}) do
        local m = scored[l.level]
        local okM, mins = pcall(function() return m and MODE.minutes(m) or 10 end)
        local v = l.per * (m and (m.p or 0.5) or 0.5) / math.max(1, okM and mins or 10)
        if not bv or v > bv then best, bv = l, v end
    end
    return best
end
-- how to get `need` of an item: drop it, or buy it in the raid shop with another item that drops
function ADV.planItem(id, need)
    local have = ADV.have(id)
    if have >= need then return { item = id, done = true } end
    local src = ADV.sources()[id]
    if src and src[1] then
        return { item = id, need = need, have = have, farm = id, farmNeed = need - have, levels = src }
    end
    -- the event shop sells it for the event currency (Chuuni's evolve item: 5,000 AprilCoins)
    local sale = C.SaleEvent[id]
    if sale and type(sale.resource_cost) == "table" then
        return { item = id, need = need, have = have, eventShop = true, cost = tonumber(sale.resource_cost.amount) or 0,
            currency = sale.resource_cost.id, farmNeed = 0 }
    end
    for key, s in pairs(B.raidShop) do
        if s.id == id and s.costItem and (s.stock == "inf" or (tonumber(s.stock) or 0) > 0) then
            local cs = ADV.sources()[s.costItem]
            local costNeed = s.cost * (need - have)
            local costHave = ADV.have(s.costItem)
            return { item = id, need = need, have = have, shopKey = key, costItem = s.costItem, cost = s.cost,
                farm = s.costItem, farmNeed = math.max(0, costNeed - costHave), levels = cs or {} }
        end
    end
    -- a portal's map drops it (MODE.PORTALS): the item gets its goal value, and the portal and the map that drops portals are ranked by it
    for pid, pt in pairs(MODE.PORTALS) do
        if pt.item == id then
            return { item = id, need = need, have = have, farm = id, farmNeed = need - have, portal = pid, levels = { { level = pt.level, per = MODE.portalPer(pid) } } }
        end
    end
    return { item = id, need = need, have = have, unknown = true }
end
-- portals that pay an item (the user, Nov 2): Shibuya District Infinite drops Shibuya Portals, and a portal's map drops Sacred Treasures. per (items a portal run)
-- and drops (portals an Infinite run) are guesses until real runs measure them: B.portalPay
MODE.PORTALS = { portal_item__shibuya = { level = "shibuya_portal", item = "shibuya_wheel", from = "shibuya_infinite", per = 10, drops = 1 } }
-- (your own measured runs first, then every farm's (the brain hive: what a portal's runs dropped, what its map's Infinite runs dropped), then the guess)
function MODE.portalPer(pid)
    local r = B.portalPay[pid]
    if r and (tonumber(r.n) or 0) > 0 then return tonumber(r.per), true end
    local pt = MODE.PORTALS[pid]
    local okH, d = pcall(REPORT.hiveDrops, pt.level)
    if okH and d and d[pt.item] then return d[pt.item], true end
    return pt.per, false
end
function MODE.portalDrops(pid)
    local r = B.portalPay["drop:" .. pid]
    if r and (tonumber(r.n) or 0) > 0 then return tonumber(r.per), true end
    local pt = MODE.PORTALS[pid]
    local okH, d = pcall(REPORT.hiveDrops, pt.from)
    if okH and d and d[pid] then return d[pid], true end
    return pt.drops, false
end
function MODE.portalsHeld(pid)
    local p = C.prof()
    local uniq = (p.inventory and p.inventory.unique_items) or p.unique_items or {}
    local out = {}
    for key, it in pairs(uniq) do if type(it) == "table" and it.item_id == pid then table.insert(out, it.uuid or key) end end
    table.sort(out)
    return out
end
-- a daily "defeat N of these enemies" mission (Shibuya's: 2,500 of its enemies for 35 Sacred Treasures and 500 gems): what one run of this level adds to it, in gems.
-- The reward comes once the count is full, so a run is worth its share of what's left. HUB.rewards claims it, and the game takes the next one by itself
MODE._spawns = {}
function MODE.levelSpawns(id, set)
    local key = tostring(id)
    local c = MODE._spawns[key]
    if c and os.time() - c.at < 3600 then return c.n end
    local n = 0
    pcall(function()
        local lv = C.Levels[id]
        local info = SIM.info(SIM.slim and SIM.slim(lv) or lv, "count:" .. key)
        local any = false
        for k, cfg in pairs(info.configs or {}) do if set[k] or (type(cfg) == "table" and set[cfg.unit_id or ""]) then any = true; break end end
        if not any then return end
        local last = info.infinite and math.floor(MODE.infReach("inf:" .. key) + 0.5) or info.total
        local function counts(k) local cfg = info.configs[k]; return set[k] or (type(cfg) == "table" and set[cfg.unit_id or ""]) end
        for w = 1, math.min(last or 30, 200) do
            if info.infinite then
                -- (the spawn tiers SIM.wave draws from: a wave's count, shared by each kind's chance)
                local okN, amt = pcall(C.LU.Infinite.infinite_amt_scale, w, info.ld)
                local tot, hit = 0, 0
                for k, cfg in pairs(info.configs) do
                    if type(cfg) == "table" and cfg.spawn_tier_normal then
                        local okC, ch = pcall(C.LU.Infinite.infinite_get_normal_unit_chance, cfg, w)
                        ch = okC and tonumber(ch) or 0
                        tot = tot + ch
                        if counts(k) then hit = hit + ch end
                    end
                end
                if tot > 0 then n = n + (okN and tonumber(amt) or 10) * hit / tot end
            else
                local wd = info.list[w]
                for _, g in ipairs(U.list(wd and wd.wave)) do if counts(g.unit) then n = n + (tonumber(g.amount) or 1) end end
            end
        end
        n = math.floor(n + 0.5)
    end)
    MODE._spawns[key] = { n = n, at = os.time() }
    return n
end
function MODE.missionValue(id)
    local s = C.session()
    local total, why = 0, nil
    for _, q in pairs(s and s.quest_handler.quest_profile_data.quests or {}) do
        local qi = q.quest_info
        local qc = qi and qi.quest_class
        if qc and qc.class == "kill_unit_multi" and type(qc.unit_ids) == "table" then
            local need = tonumber(qc.amount) or 0
            local left = need - (tonumber(q.quest_progress and q.quest_progress.amount) or 0)
            if left > 0 then
                local per = MODE.levelSpawns(id, qc.unit_ids)
                if per > 0 then
                    local reward = tonumber(qi.quest_reward and qi.quest_reward.gem_reward) or 0
                    for _, it in pairs(qi.quest_reward and qi.quest_reward.item or {}) do
                        if type(it) == "table" and it.item_id then reward = reward + MODE.itemValue(it.item_id, tonumber(it.max_amount or it.amount or it.min_amount) or 1) end
                    end
                    total = total + reward * math.min(1, per / left)
                    why = string.format("%s: %s/%s, ≈%s a run", tostring(qi.quest_name), U.fmt(need - left), U.fmt(need), U.fmt(math.min(per, left)))
                end
            end
        end
    end
    return total, why
end
-- every portal the game has (an item that opens one): the levels it can open, and the items those levels drop (their rewards, and MODE.PORTALS for what the server drops on its own)
function MODE.portalKinds()
    if MODE._kinds then return MODE._kinds end
    local out = {}
    for pid, it in pairs(C.Items) do
        if type(it) == "table" and type(it.usage) == "table" and it.usage.type == "open_portal" then
            local levels = {}
            if it.usage.level_id then table.insert(levels, it.usage.level_id) end
            if type(it._unique_portal_levels) == "table" then for lv in pairs(it._unique_portal_levels) do table.insert(levels, lv) end end
            table.sort(levels)
            local drops = {}
            local function walk(t, d)
                if type(t) ~= "table" or d > 4 then return end
                if type(t.item_id) == "string" then drops[t.item_id] = true end
                for _, v in pairs(t) do walk(v, d + 1) end
            end
            for _, lv in ipairs(levels) do walk((C.Levels[lv] or {}).rewards, 0) end
            if MODE.PORTALS[pid] then drops[MODE.PORTALS[pid].item] = true end
            table.insert(out, { pid = pid, name = it.name or pid, rarity = it.rarity, levels = levels, drops = drops })
        end
    end
    table.sort(out, function(a, b) if a.name ~= b.name then return a.name < b.name end; return a.pid < b.pid end)
    MODE._kinds = out
    return out
end
-- the level one portal you hold opens (a portal kind can open several: Devil Portals, the Summer Portal)
function MODE.portalLevel(uuid)
    local p = C.prof()
    local uniq = (p.inventory and p.inventory.unique_items) or p.unique_items or {}
    for key, it in pairs(uniq) do
        if type(it) == "table" and (it.uuid or key) == uuid then
            local d = type(it._unique_item_data) == "table" and it._unique_item_data._unique_portal_data
            return type(d) == "table" and d.level_id or nil
        end
    end
end
-- your portals as modes (Home tab, Portal To Play): Smart plays a kind you hold while its map drops what your evolutions need; your pick plays that kind whenever you hold one (the user's
-- call, Nov 2); Off never opens one. Each run uses up one try of one portal
function MODE.portalRows()
    local out = {}
    local pick = CFG.pickPortal or "smart"
    if pick == "off" or CFG.portals == false then return out end
    -- (a portal that wouldn't start waits an hour: the next one goes first)
    local bad = HUB.badPortal or {}
    for _, k in ipairs(MODE.portalKinds()) do
        local picked = pick == k.pid
        if picked or pick == "smart" then
            local held = MODE.portalsHeld(k.pid)
            local need = {}
            for item in pairs(k.drops) do if (B.goalNeed[item] or 0) > 0 then table.insert(need, item) end end
            table.sort(need)
            if #held > 0 and (picked or #need > 0) then
                table.sort(held, function(a, b) return (bad[a] or 0) < (bad[b] or 0) end)
                local level = MODE.portalLevel(held[1]) or k.levels[1]
                if level and C.Levels[level] and MODE.open(level) then
                    local gems = tonumber(C.Levels[level]._override_gem_reward) or 0
                    local value, words = gems, {}
                    local pt = MODE.PORTALS[k.pid]
                    for _, item in ipairs(need) do
                        local per, real = 1, true
                        if pt and pt.item == item then per, real = MODE.portalPer(k.pid) end
                        value = value + MODE.itemValue(item, per)
                        table.insert(words, string.format("≈%s %s a run%s", U.fmt(per), (C.Items[item] or {}).name or item, real and "" or " (a guess until one is played)"))
                    end
                    table.insert(out, { key = "pt:" .. level, kind = "portal", level = level, diff = "Hard", portal = held[1], first = false, picked = picked or nil,
                        value = value, p0 = MODE.PRIOR_WIN.hard, label = MODE.levelName(level),
                        why = string.format("%s%s: %s · you hold %d", picked and "your pick · " or "", k.name, #words > 0 and table.concat(words, ", ") or (gems .. " gems a run"), #held) })
                end
            end
        end
    end
    return out
end
-- what a map that drops portals adds to an Infinite run while a goal needs the portal's item (nothing with portals Off)
function MODE.portalBonus(id)
    if CFG.pickPortal == "off" or CFG.portals == false then return 0, nil end
    for pid, pt in pairs(MODE.PORTALS) do
        if pt.from == id and (B.goalNeed[pt.item] or 0) > 0 then
            local drops, real = MODE.portalDrops(pid)
            local per = MODE.portalPer(pid)
            return drops * MODE.itemValue(pt.item, per), string.format("≈%s %s a run%s, for %s", U.fmt(drops), (C.Items[pid] or {}).name or pid, real and "" or " (a guess)", (C.Items[pt.item] or {}).name or pt.item)
        end
    end
    return 0, nil
end
-- every evolution you're close to: what it gives (the game's formula at full upgrade) and how to finish it
function ADV.goals()
    local s = C.session()
    if not s then return {} end
    local team = UNIT.equipped()
    -- "joins your team" = beats your weakest damage dealer (farm units and buffers are valued for their role)
    local weakest = math.huge
    for _, e in ipairs(team) do
        if not UNIT.isFarm(e.id) and not UNIT.allyBuff(e.id) then local ok, sc = pcall(UNIT.score, e.u); if ok then weakest = math.min(weakest, sc) end end
    end
    -- the copy to evolve: your best one of each unit (score at full upgrade; the equipped one on a tie)
    local onTeam = {}
    for _, e in ipairs(team) do onTeam[e.uuid] = true end
    -- your Auto Evolve pick: this copy, first, and whether or not the score says it gets stronger
    local pin = CFG.autoEvolve and CFG.evolveUnit ~= "" and CFG.evolveUnit or nil
    local bestCopy = {}
    for _, u0 in pairs(s.profile_data.collection.owned_units) do
        local d = C.Units[u0.unit_id]
        if d and d.evolve and d.evolve.evolve_unit and not d.evolve.hide_from_ui and C.Units[d.evolve.evolve_unit] then
            local okS, sc = pcall(UNIT.score, s.collection:get_unit_by_uuid(u0.uuid) or u0)
            sc = (okS and sc or 0) + (onTeam[u0.uuid] and 0.5 or 0) + (u0.uuid == pin and 1e30 or 0)
            if not bestCopy[u0.unit_id] or sc > bestCopy[u0.unit_id].sc then bestCopy[u0.unit_id] = { u0 = u0, sc = sc } end
        end
    end
    local out = {}
    -- (a spare copy of a unit you already have evolved isn't a goal: a level-1 Chuuni kept "Chuuni → Chuuni (Delusion), takedowns 0/7500" on the list beside a level-100 Chuuni (Delusion). Your own pick still counts)
    local ownedIds = {}
    for _, u0 in pairs(s.profile_data.collection.owned_units) do ownedIds[u0.unit_id] = true end
    for _, bc in pairs(bestCopy) do
        local u0 = bc.u0
        local d = C.Units[u0.unit_id]
        if not ownedIds[d.evolve.evolve_unit] or u0.uuid == pin then
            local req = u0.shiny and d.evolve.shiny or d.evolve.normal
            -- other copies it uses up, counted like the game's evolve window: your unlocked copies, not this one
            -- (the unit itself counts as one of a requirement for its own kind)
            local unitsOk, eats, copiesShort = true, {}, {}
            for _, ur in pairs(req and req.unit_requirement or {}) do
                local want = (tonumber(ur.amount) or 1) - (ur.unit_id == u0.unit_id and 1 or 0)
                if want > 0 then
                    local have = #ADV.copies(ur.unit_id, ur.shiny, u0.uuid)
                    if have < want then unitsOk = false; table.insert(copiesShort, { copies = ur.unit_id, have = have, need = want }) end
                    table.insert(eats, { id = ur.unit_id, amount = want, shiny = ur.shiny and true or nil })
                end
            end
            local items = {}
            for _, it in pairs(req and req.item_requirement or {}) do table.insert(items, { id = it.item_id, amount = tonumber(it.amount) or 1 }) end
            local pinned = u0.uuid == pin or nil
            if req and (unitsOk or pinned) then
                local u = s.collection:get_unit_by_uuid(u0.uuid) or u0
                local evolved = { unit_id = d.evolve.evolve_unit, uuid = "evo:" .. tostring(u.uuid), xp = u.xp, traits = u.traits, trait_stats = u.trait_stats, further_modifiers = u.further_modifiers }
                local okA, a = pcall(UNIT.score, u)
                local okB, b = pcall(UNIT.score, evolved)
                a, b = okA and a or 0, okB and b or 0
                -- (what it comes to at level 100: a level-1 copy of a great unit scores low today. For the Path tab's "strongest")
                local okX, xp100 = pcall(C.USC.calculate_xp, d.evolve.evolve_unit, 100)
                local okF, full = pcall(UNIT.score, { unit_id = d.evolve.evolve_unit, uuid = "evo100:" .. tostring(u.uuid), xp = math.max(tonumber(u.xp) or 0, okX and tonumber(xp100) or 0), traits = u.traits, trait_stats = u.trait_stats, further_modifiers = u.further_modifiers })
                full = okF and tonumber(full) or b
                -- the game hides one of the two forms' upgrades: its strength is unknown (UNIT.hidden), not low
                local hidden = UNIT.hidden(u0.unit_id) or UNIT.hidden(d.evolve.evolve_unit)
                local plans, runs, unknown, ready = {}, 0, false, true
                -- kills / takedowns come from playing the unit, not from farming items
                local short = ADV.killsShort(u, req)
                if short then ready = false; table.insert(plans, { takedown = true, what = short.what, have = short.have, need = short.need }) end
                for _, c in ipairs(copiesShort) do ready = false; table.insert(plans, c) end
                for _, it in pairs(req.item_requirement or {}) do
                    local p = ADV.planItem(it.item_id, it.amount or 1)
                    if not p.done then
                        ready = false
                        table.insert(plans, p)
                        if p.unknown then unknown = true
                        elseif p.farmNeed > 0 then
                            p.best = ADV.bestSource(p.levels)
                            runs = runs + p.farmNeed / math.max(0.1, p.best and p.best.per or 1)
                        end
                    end
                end
                -- the guides' rating of the evolved form: an S/SS one the game hides counts as joining your team
                local _, _, tr = ADV.tier(d.evolve.evolve_unit)
                if b > a or hidden or pinned then
                    table.insert(out, { uuid = u0.uuid, from = u0.unit_id, to = d.evolve.evolve_unit, scoreFrom = a, scoreTo = b, scoreFull = full, gain = hidden and 0 or b - a, pinned = pinned,
                        intoTeam = pinned or (not hidden and b > weakest) or (hidden and tr >= ADV.TIER_RANK.S), ready = ready, unknown = unknown, hidden = hidden or nil,
                        rating = ADV.tierText(d.evolve.evolve_unit), tierRank = tr, plans = plans, runs = runs, items = items, eats = eats })
                end
            end
        end
    end
    -- best first: ready ones, then what joins your team, by strength gained per run of farming (unknown
    -- strength last, unless the guides rate it S or better)
    table.sort(out, function(x, y)
        if (x.pinned or false) ~= (y.pinned or false) then return x.pinned or false end
        local xu, yu = (x.hidden and not x.intoTeam) or false, (y.hidden and not y.intoTeam) or false
        if xu ~= yu then return not xu end
        if x.ready ~= y.ready then return x.ready end
        if x.unknown ~= y.unknown then return not x.unknown end
        if x.intoTeam ~= y.intoTeam then return x.intoTeam end
        return x.gain / math.max(1, x.runs) > y.gain / math.max(1, y.runs)
    end)
    return out
end
-- a goal in plain words: "Shinobi (Hood) → Shinobi (Storm) · 35k → 96k · 84 more Storm Hideout items (≈6 runs)"
function ADV.text(g)
    local parts = {}
    for _, p in ipairs(g.plans) do
        local name = (C.Items[p.item] or {}).name or p.item
        if p.takedown then table.insert(parts, string.format("%s %s/%s (it earns them on your team)", p.what, U.fmt(p.have), U.fmt(p.need)))
        elseif p.copies then table.insert(parts, string.format("spare copies of %s %d/%d (unlocked, from summons)", UNIT.name(p.copies), p.have, p.need))
        elseif p.unknown then table.insert(parts, name .. ": source unknown (event/portal)")
        elseif p.portal then
            local pt = MODE.PORTALS[p.portal]
            table.insert(parts, string.format("%s %d/%d from %s (you hold %d; %s drops them)", name, p.have, p.need, (C.Items[p.portal] or {}).name or p.portal, #MODE.portalsHeld(p.portal), MODE.levelName(pt.from)))
        elseif p.eventShop then
            table.insert(parts, string.format("%s from the event shop: %s/%s %s", name, U.fmt(C.cur(p.currency)), U.fmt(p.cost), tostring(p.currency)))
        elseif p.shopKey then
            table.insert(parts, string.format("%s from the raid shop: %d/%d %s", name, ADV.have(p.costItem), p.cost * (p.need - p.have), (C.Items[p.costItem] or {}).name or p.costItem))
        else table.insert(parts, string.format("%s %d/%d", name, p.have, p.need)) end
    end
    local where = ""
    local p1
    for _, p in ipairs(g.plans) do if p.levels and p.levels[1] then p1 = p; break end end
    local src = p1 and (p1.best or p1.levels[1])
    if src then where = string.format(" · farm %s (≈%.0f a run, ≈%d runs)", MODE.levelName(src.level), src.per, math.ceil(g.runs)) end
    local score = g.hidden and "strength unknown (the game shows its upgrades only in a match)"
        or string.format("score %s → %s", U.fmt(g.scoreFrom), U.fmt(g.scoreTo))
    return string.format("%s → %s · %s%s%s · %s%s", UNIT.name(g.from), UNIT.name(g.to), score,
        g.intoTeam and " (joins your team)" or "", g.rating and (" · " .. g.rating) or "", g.ready and "ready to evolve" or table.concat(parts, "; "), g.ready and "" or where)
end
-- refresh the goals, and give the items of the top goals their value (they're what makes you stronger)
function ADV.refresh()
    local goals = ADV.goals()
    -- the Path tab's list: the strongest you could evolve, whatever order the farm works in. The guides' rating first, since the game hides many evolved forms' numbers until they're
    -- played, then the score at level 100. Your focus always shows
    local strong = table.clone(goals)
    table.sort(strong, function(x, y)
        local xr, yr = tonumber(x.tierRank) or 0, tonumber(y.tierRank) or 0
        if xr ~= yr then return xr > yr end
        local xs, ys = tonumber(x.scoreFull) or 0, tonumber(y.scoreFull) or 0
        if xs ~= ys then return xs > ys end
        return tostring(x.uuid) < tostring(y.uuid)
    end)
    B.goalsTop = {}
    for i, g in ipairs(strong) do
        if i <= 10 or g.pinned then
            table.insert(B.goalsTop, { uuid = g.uuid, from = g.from, to = g.to, ready = g.ready, intoTeam = g.intoTeam, unknown = g.unknown, hidden = g.hidden, pinned = g.pinned, text = ADV.text(g) })
        end
    end
    B.goals = {}
    table.clear(B.goalItems)
    table.clear(B.goalNeed)
    local valued = 0
    -- with an Auto Evolve pick, only its items get a value (it sorts first)
    local pinned = goals[1] and goals[1].pinned
    for _, g in ipairs(goals) do
        table.insert(B.goals, { uuid = g.uuid, from = g.from, to = g.to, ready = g.ready, intoTeam = g.intoTeam, unknown = g.unknown, hidden = g.hidden, tierRank = g.tierRank, text = ADV.text(g),
            gain = g.gain, runs = g.runs, plans = g.plans, items = g.items, eats = g.eats, scoreFrom = g.scoreFrom, scoreTo = g.scoreTo, pinned = g.pinned })
        if not g.ready and (g.pinned or (not pinned and CFG.goals and not g.unknown and (not g.hidden or g.intoTeam) and (g.intoTeam or valued == 0) and valued < 2)) then
            valued = valued + 1
            for _, p in ipairs(g.plans) do
                if p.farm and p.farmNeed > 0 then
                    local v = CFG.goalValue * (g.intoTeam and 1 or 0.4) / (valued == 1 and 1 or 2) / math.max(1, p.farmNeed)
                    B.goalItems[p.farm] = math.max(B.goalItems[p.farm] or 0, v)
                    B.goalNeed[p.farm] = math.max(B.goalNeed[p.farm] or 0, p.farmNeed)
                end
            end
        end
        if #B.goals >= 12 then break end
    end
    SF.saveSoon()
    return goals
end
-- spend: a goal's item from the raid shop, once the raid items are in (raid items buy nothing else you need)
function ADV.buyShopGoals()
    if not CFG.raidShopGoals then return end
    for _, g in ipairs(B.goals) do
        for _, p in ipairs(g.plans or {}) do
            if p.shopKey and p.costItem and ADV.have(p.item) < p.need and ADV.have(p.costItem) >= p.cost then
                local before = ADV.have(p.costItem)
                local ok, r = SF.request("rshop", "buy_raidshop_shop_item", p.shopKey, "1")
                local t1 = U.now()
                while U.now() - t1 < 3 and ADV.have(p.costItem) >= before do task.wait(0.2) end
                if ok and ADV.have(p.costItem) < before then
                    SPEND.add((C.Items[p.item] or {}).name or p.item, p.cost, (C.Items[p.costItem] or {}).name or p.costItem, "for " .. UNIT.name(g.to))
                    if SF.notify then SF.notify("Goals", string.format("Bought %s for %s (Goals tab)", (C.Items[p.item] or {}).name or p.item, UNIT.name(g.from)), "success") end
                    return true
                else
                    SF.log(1, "SHOP", "raid shop refused " .. tostring(p.shopKey) .. " (" .. tostring(r) .. ")")
                    SF.backoff("rshop", 900)
                end
                return
            end
        end
    end
end

-- limit break in plain words: once per unit (level cap 100 → 110, and +5% damage for the whole team while
-- it's on the field), needs a Divine Wish + Mythic/Secret units destroyed as fuel (evolved ones count 2)
function ADV.lbText()
    local s = C.session()
    if not s then return "…" end
    local lb = B.lb
    local wish = ADV.have("divine_wish")
    local eq = {}
    for _, e in ipairs(UNIT.equipped()) do eq[e.uuid] = true end
    local fuel, locked = 0, 0
    for uuid, u in pairs(s.profile_data.collection.owned_units) do
        local d = C.Units[u.unit_id]
        if d and (d.rarity == "Mythic" or d.rarity == "Secret") and not d._event_unit and not eq[uuid] then
            local ok, good, pts = pcall(C.USC.is_unit_good_for_fusion, { uuid = "x" }, u)
            pts = (ok and good) and (tonumber(pts) or 1) or 0
            if u._locked then locked = locked + pts else fuel = fuel + pts end
        end
    end
    local best, bs
    for _, e in ipairs(UNIT.equipped()) do
        local cur = e.u.further_modifiers and e.u.further_modifiers.limit_break and e.u.further_modifiers.limit_break.current_limit_break or 0
        if cur < 1 and not UNIT.isFarm(e.id) then local ok, sc = pcall(UNIT.score, e.u); if ok and (not bs or sc > bs) then best, bs = e, sc end end
    end
    local need = lb and tonumber(lb.requirement) or 12
    return string.format("Best target: %s (your strongest unit; level cap 100 → 110 ≈ +20%% damage after levelling, and +5%% damage for your whole team). "
        .. "Needs %d fuel points: you have %d in unlocked Mythic/Secret units (+%d in locked ones) and %d Divine Wish. "
        .. "It destroys the fuel units, so the farm never does it — the Unit Fusion NPC does it when you choose.",
        best and UNIT.name(best.id) or "—", need, fuel, locked, wish)
end
-- ============================================================
--  TEAM STRENGTH (the Team tab): one scale for everything that makes your core units stronger, and the lobby actions that buy it
-- ============================================================
-- Every lever is judged the same way: a copy of the unit with the change made (more XP, a limit break, a
-- relic) goes through UNIT.score, the game's own unit maths, and the difference is weighed by the unit's real share of a match's damage
-- (the DAMAGE lines). That gives "% of the team's damage", so a Divine Wish and 1,000 XP can be compared,
-- and turned into gems for the mode ranker at CFG.strengthValue gems per 1%
STR.LOG = "POWER"
function STR.traitName(tr, tier)
    if not tr then return "no trait" end
    local t = C.traitInfo(tr)
    local name = t and t.name or tostring(tr)
    return name .. ((tier and tostring(tier) ~= "1") and (" " .. tostring(tier)) or "")
end
function STR.role(id) if UNIT.isFarm(id) then return "farm" elseif UNIT.allyBuff(id) then return "buffer" end return "carry" end
STR._salt = 0
-- a copy of a unit with a change made, for UNIT.score: every field (the game's multiplier reads equipped_slot too, for the +5% a
-- limit-broken team-mate gives), under its own uuid (UNIT.mult caches by uuid; STR.plan clears those). Gains always compare two
-- copies (STR.base), never a copy against the real unit: the real one's field cap is remembered by uuid
function STR.whatIf(u, patch)
    STR._salt = STR._salt + 1
    local w = {}
    for k, v in pairs(u) do w[k] = v end
    w.uuid = "what:" .. STR._salt .. ":" .. tostring(u.uuid)
    for k, v in pairs(patch or {}) do w[k] = v end
    return w
end
function STR.base(u) return STR.score(STR.whatIf(u, {})) end
function STR.score(u) local ok, s = pcall(UNIT.score, u); return (ok and tonumber(s)) or 0 end
function STR.level(u) local ok, l = pcall(C.USC.calculate_level, u.unit_id, tonumber(u.xp) or 0); return (ok and tonumber(l)) or 1 end
function STR.cap(u) local ok, m = pcall(C.USC.get_max_level, u); return (ok and tonumber(m)) or 100 end
function STR.xpFor(id, L) local ok, x = pcall(C.USC.calculate_xp, id, L); return (ok and tonumber(x)) or 0 end
function STR.lb(u) local fm = u.further_modifiers; return (fm and fm.limit_break and tonumber(fm.limit_break.current_limit_break)) or 0 end
-- the share of the team's damage a unit really deals (DAMAGE lines, STR.learn), else its share of the team's scores. Never under 5%:
-- a slow or a buffer deals little and still matters
function STR.share(id)
    local s = B.str.share[id]
    if s and (B.str.shareN or 0) >= 3 then return math.max(0.05, s) end
    local total, mine = 0, 0
    for _, e in ipairs(UNIT.equipped()) do
        if not UNIT.isFarm(e.id) then local sc = STR.score(e.u); total = total + sc; if e.id == id then mine = sc end end
    end
    return math.max(0.05, total > 0 and mine / total or 0.1)
end
function STR.learn(shares, team)
    B.str.shareN = (B.str.shareN or 0) + 1
    local rate = math.max(0.1, 1 / B.str.shareN)
    for _, e in ipairs(team or {}) do
        if e.id and not UNIT.isFarm(e.id) then
            local sh = shares[e.id] or 0
            local o = B.str.share[e.id]
            B.str.share[e.id] = o and (o + (sh - o) * rate) or sh
        end
    end
    SF.saveSoon()
end
-- the 8 core units: the 6 equipped, your Lobby-tab picks, then the attackers the planner picked most this week (else your strongest).
-- Re-picked weekly, or when the team changes
function STR.core(force)
    local s = C.session()
    if not s then return B.str.core or {} end
    -- (your own team, not the one a dungeon room or takedown training borrowed: the farm keeps yours in B.savedTeam while a swap is on)
    local own = {}
    if type(B.savedTeam) == "table" and #B.savedTeam > 0 then
        for _, uuid in ipairs(B.savedTeam) do local u = s.collection:get_unit_by_uuid(uuid); if u then table.insert(own, { uuid = uuid, id = u.unit_id }) end end
    end
    if #own == 0 then for _, e in ipairs(UNIT.equipped()) do table.insert(own, { uuid = e.uuid, id = e.id }) end end
    local sigParts = {}
    for _, e in ipairs(own) do table.insert(sigParts, e.uuid) end
    table.sort(sigParts)
    local sig = table.concat(sigParts, ",")
    if not force and #(B.str.core or {}) >= 6 and os.time() - (tonumber(B.str.coreAt) or 0) < (CFG.teamCoreDays or 7) * 86400 then
        if B.str.teamSig == sig then return B.str.core end
        -- (a changed team has to stay 10 minutes before the core follows it: a room swap and its undo pass through here in seconds)
        if B.str.pendingSig ~= sig then B.str.pendingSig, B.str.pendingAt = sig, os.time(); return B.str.core end
        if os.time() - (tonumber(B.str.pendingAt) or 0) < 600 then return B.str.core end
    end
    B.str.pendingSig, B.str.pendingAt = nil, nil
    local core, have = {}, {}
    for _, e in ipairs(own) do table.insert(core, e.uuid); have[e.id] = true end
    -- (focusDone: the last Focus, just evolved, stays looked after when the next one takes over)
    for _, k in ipairs({ "evolveUnit", "fuseUnit", "focusDone" }) do
        local v = CFG[k]
        local u = v ~= "" and s.collection:get_unit_by_uuid(v)
        if u and not table.find(core, v) then table.insert(core, v); have[u.unit_id] = true end
    end
    local picked = {}
    for _, plan in pairs(B.simTeam or {}) do
        if type(plan) == "table" and os.time() - (tonumber(plan.at) or 0) < 7 * 86400 then
            for _, n in ipairs(plan.names or {}) do picked[n] = (picked[n] or 0) + 1 end
        end
    end
    local cands = {}
    for uuid, u0 in pairs(s.profile_data.collection.owned_units) do
        local d = C.Units[u0.unit_id]
        if d and (d.rarity == "Mythic" or d.rarity == "Secret") and not have[u0.unit_id] and UNIT.rows(u0.unit_id) and not UNIT.hidden(u0.unit_id)
            and not UNIT.isFarm(u0.unit_id) and not UNIT.allyBuff(u0.unit_id) then
            local u = s.collection:get_unit_by_uuid(uuid) or u0
            table.insert(cands, { uuid = uuid, id = u0.unit_id, k = (picked[UNIT.name(u0.unit_id)] or 0) * 1e12 + STR.score(u) })
        end
    end
    table.sort(cands, function(a, b) if a.k ~= b.k then return a.k > b.k end return a.uuid < b.uuid end)
    for _, c in ipairs(cands) do
        if #core >= 8 then break end
        if not have[c.id] then table.insert(core, c.uuid); have[c.id] = true end
    end
    B.str.core, B.str.coreAt, B.str.teamSig = core, os.time(), sig
    local names = {}
    for _, uuid in ipairs(core) do local u = s.collection:get_unit_by_uuid(uuid); if u then table.insert(names, UNIT.name(u.unit_id)) end end
    SF.log(1, STR.LOG, "core units: " .. table.concat(names, ", "))
    SF.saveSoon()
    return core
end
-- % of the team's damage that `xp` more XP would add (up to the unit's cap), and the XP it can take
function STR.gainXp(u, xp)
    local now, capXp = tonumber(u.xp) or 0, STR.xpFor(u.unit_id, STR.cap(u))
    local room = math.max(0, capXp - now)
    if room <= 0 or (xp or 0) <= 0 then return 0, 0 end
    local add = math.min(xp, room)
    local base = STR.base(u)
    if base <= 0 then return 0, add end
    return STR.share(u.unit_id) * (STR.score(STR.whatIf(u, { xp = now + add })) / base - 1) * 100, add
end
-- a limit break: level cap 110 on this unit, and 5% more damage for the whole team while it's equipped
function STR.gainFuse(u)
    if STR.lb(u) >= 1 then return 0 end
    local base = STR.base(u)
    if base <= 0 then return 0 end
    local w = STR.whatIf(u, { xp = math.max(tonumber(u.xp) or 0, STR.xpFor(u.unit_id, 110)), further_modifiers = { limit_break = { current_limit_break = 1 } } })
    return STR.share(u.unit_id) * (STR.score(w) / base - 1) * 100 + 5
end
-- SMART RELICS. The game allows 6 relics on all your units ("You cannot equip more than 6 relics!") and one Miracle Timepiece on a team (unique_equip), and each copy
-- rolls its own numbers. So relics go where they add the most to the team that's playing, taken from units off the team when needed
STR.MAX_RELICS = 6
STR.RELIC_MOVE_GAIN = 0.5 -- % of the team's damage a change of relics has to add on a team new to them (the run is in the lobby for that swap anyway)
-- and on the team already wearing them. Each unit's share of the damage swings from room to room (Chuuni 69%, then Iron Sentinel 100%, then Chuuni 57%), which moved the Timepiece to Iron
-- Sentinel at 01:09 on Nov 1 for +0.8% and back to Chuuni at 01:21 for +0.5%, a lobby stop each. The moves that mattered have been +2.8% and up
STR.RELIC_SETTLED_GAIN = 2
function STR.relicBar()
    if B.str.relicTeam == nil or B.str.relicTeam == MODE.teamSig() then return STR.RELIC_SETTLED_GAIN end
    return STR.RELIC_MOVE_GAIN
end
-- the share of a unit's damage a relic copy adds. Sure parts: mul on the unit's damage types, and the Timepiece's extra hit (the slower the attacks, the more it adds: Chuuni
-- about 25%, Gene about 50%). Estimates where the game's formula is on the server: PWR 1% a point, PEN 0.1% a point, a quarter of enemies flying, crit hits at ×1.5
function STR.relicWorth(u, it)
    local rd = it._unique_item_data and it._unique_item_data._unique_relic_data
    if not rd then return 0 end
    local d = C.Items[it.item_id] or {}
    local types, base = UNIT.types(u.unit_id)
    if d.main_damage_type and d.main_damage_type ~= "both" and d.main_damage_type ~= base then return 0 end
    local v, crit = 0, 0
    for _, b in pairs(rd._core_damage_type_buffs or {}) do
        if types[b.damage_type] then
            v = v + (tonumber(b.mul) or 0) + (tonumber(b.add_upg) or 0) * 0.01 + (tonumber(b.pen) or 0) * 0.001
            crit = crit + (tonumber(b.crit) or 0)
        end
    end
    v = v + crit * 0.5
    local rows = UNIT.rows(u.unit_id)
    local top = rows and rows[rows.max]
    local cd = (top and tonumber(top.cd) or 0) * UNIT.mult(u, "attack_cooldown")
    for _, fx in pairs(rd._unique_relic_effects or {}) do
        local p = type(fx.params) == "table" and fx.params or {}
        if fx.id == "hourglass_relic" then
            local hit = math.min(1, (tonumber(p.extra_damage) or 0) * cd / math.max(1, tonumber(p.time_interval) or 40))
            -- (it lands on the unit's own attack: most of Iron Sentinel's damage is its drones')
            local dr = UNIT.DRONES and UNIT.DRONES[u.unit_id]
            if dr and dr.late and cd > 0 then
                local own = 1 / cd
                hit = hit * own / (own + (tonumber(dr.max) or 0) * (tonumber(dr.late.dmg) or 0) * (tonumber(dr.hits) or 1) / math.max(0.1, tonumber(dr.late.cd) or 4))
            end
            v = v + hit
        elseif fx.id == "yuno_clover" then v = v + (tonumber(p.dmg_buff) or 0) * 0.25
        elseif fx.id == "nail" then v = v + (tonumber(p.dmg_buff) or 0) * crit
        elseif fx.id == "asta_clover" then if types.magic then v = 0 else v = v + (tonumber(p.dmg_buff) or 0) * 0.3 end
        elseif fx.id == "noelle_crown" then if types.water_damage then v = v + 0.05 end end
    end
    return v
end
-- the best relics for the team on the field: every spread of each attacker's best copies is tried (a Timepiece once). Returns wanted = {unit uuid = relic uuid}, the gain over
-- what they wear now in % of the team's damage, and lines to show
function STR.relicPlan()
    local s = C.session()
    if not s then return nil end
    local inv = s.inventory and s.inventory.inventory_profile_data or {}
    local relics = {}
    for _, it in ipairs(inv.unique_items or {}) do
        if type(it) == "table" and it.uuid and (C.Items[it.item_id] or {}).item_group == "Relics" then table.insert(relics, it) end
    end
    local units = {}
    for _, e in ipairs(UNIT.equipped()) do
        local rarity = e.data and e.data.rarity
        if not UNIT.isFarm(e.id) and (rarity == "Legendary" or rarity == "Mythic" or rarity == "Secret" or rarity == "Exclusive") then
            local share = STR.share(e.id)
            -- (no match to go on yet: a paper guess doesn't take a relic from a unit with a real record. Illusionist took Chuuni's Timepiece on one. A room fills it in)
            if not B.str.share[e.id] then share = math.min(share, 0.15) end
            local opts = {}
            for _, it in ipairs(relics) do
                local w = STR.relicWorth(e.u, it) * share * 100
                if w > 0.01 then table.insert(opts, { it = it, w = w }) end
            end
            table.sort(opts, function(a, b) if a.w ~= b.w then return a.w > b.w end return a.it.uuid < b.it.uuid end)
            -- (its best copies of each kind, not its best copies: 10 Timepieces filled every shortlist, a team can hold one, and Chuuni was left with nothing)
            local short, perKind = {}, {}
            for _, o in ipairs(opts) do
                local n = perKind[o.it.item_id] or 0
                if #short < 6 and n < ((C.Items[o.it.item_id] or {}).unique_equip and 1 or 2) then
                    perKind[o.it.item_id] = n + 1
                    table.insert(short, o)
                end
            end
            -- (what it wears now stays in the running)
            if e.u._equipped_relic then
                local isIn = false
                for _, o in ipairs(short) do if o.it.uuid == e.u._equipped_relic then isIn = true end end
                local cur = not isIn and s.inventory:get_item_by_uuid(e.u._equipped_relic)
                if cur then table.insert(short, { it = cur, w = STR.relicWorth(e.u, cur) * share * 100 }) end
            end
            table.insert(units, { e = e, share = share, opts = short })
        end
    end
    local best, bestV = {}, -1
    local now, used, kinds = {}, {}, {}
    local function walk(i, total)
        if i > #units then
            if total > bestV then bestV = total; best = table.clone(now) end
            return
        end
        local x = units[i]
        now[x.e.uuid] = nil
        walk(i + 1, total)
        for _, o in ipairs(x.opts) do
            local unique = (C.Items[o.it.item_id] or {}).unique_equip
            if not used[o.it.uuid] and not (unique and kinds[o.it.item_id]) then
                used[o.it.uuid] = true
                if unique then kinds[o.it.item_id] = true end
                now[x.e.uuid] = o.it.uuid
                -- (a hair for what it already wears: no move over a rounding error)
                walk(i + 1, total + o.w + (o.it.uuid == x.e.u._equipped_relic and 0.01 or 0))
                now[x.e.uuid] = nil
                used[o.it.uuid] = nil
                if unique then kinds[o.it.item_id] = nil end
            end
        end
    end
    walk(1, 0)
    local curV, lines = 0, {}
    for _, x in ipairs(units) do
        local cur = x.e.u._equipped_relic and s.inventory:get_item_by_uuid(x.e.u._equipped_relic)
        local curW = cur and STR.relicWorth(x.e.u, cur) * x.share * 100 or 0
        curV = curV + curW
        local want = best[x.e.uuid] and s.inventory:get_item_by_uuid(best[x.e.uuid])
        local wantW = want and STR.relicWorth(x.e.u, want) * x.share * 100 or 0
        table.insert(lines, string.format("%s: %s (%+.1f%%) → %s (%+.1f%%)", UNIT.name(x.e.id), cur and (C.Items[cur.item_id] or {}).name or "none", curW, want and (C.Items[want.item_id] or {}).name or "none", wantW))
    end
    return best, bestV - curV, lines, units
end
-- puts the plan on, in the lobby, when it adds enough: off first, a unit off the team gives way when the 6 are on, then on, each read back. Spaced out: fast swaps get "Sending requests too fast"
function STR.relicsApply(force)
    if not (CFG.team and CFG.teamRelics) or CFG.strDry then return false end
    local sig = MODE.teamSig()
    if not force and B.str.relicSig == sig and os.time() - (tonumber(B.str.relicAt) or 0) < 600 then return false end
    if SF.req.back.relicMove and U.now() < SF.req.back.relicMove then return false end
    B.str.relicSig, B.str.relicAt = sig, os.time()
    local wanted, gain, lines, units = STR.relicPlan()
    if not wanted then return false end
    B.str.relicNote = string.format("relics now on the best spread for this team (a change would add %.1f%%)", math.max(0, gain))
    if gain < STR.relicBar() then
        -- (this team's relics have been looked at: from here on it takes a real change)
        B.str.relicTeam = sig
        return false
    end
    local s = C.session()
    local owned = s.profile_data.collection.owned_units
    local function unitOf(relic) for uuid, o in pairs(owned) do if o._equipped_relic == relic then return uuid, o end end end
    local function say(t0) return SF.gameSaid(t0) or "no answer" end
    local function off(relic)
        local uuid, o = unitOf(relic)
        if not uuid then return true end
        local t0 = U.now()
        SF.request("relicMove", "request_unequip_relic", relic)
        while U.now() - t0 < 4 and o._equipped_relic == relic do task.wait(0.25) end
        task.wait(1.2)
        if o._equipped_relic == relic then
            SF.log(1, "POWER", string.format("%s's %s wouldn't come off (%s): relics stay as they are for now", UNIT.name(o.unit_id), tostring(UNIT.relicName(o)), say(t0)))
            SF.backoff("relicMove", 300)
            return false
        end
        return true
    end
    SF.log(1, "POWER", string.format("moving relics for +%.1f%% team damage: %s", gain, table.concat(lines, " · ")))
    -- what has to come off: a team unit's that isn't staying on it, and a wanted relic worn by someone else
    for _, x in ipairs(units) do
        local cur = x.e.u._equipped_relic
        if cur and cur ~= wanted[x.e.uuid] and not off(cur) then return false end
    end
    for uuid, relic in pairs(wanted) do
        local holder = unitOf(relic)
        if holder and holder ~= uuid and not off(relic) then return false end
    end
    -- on, biggest share first
    table.sort(units, function(a, b) return a.share > b.share end)
    local moved = 0
    for _, x in ipairs(units) do
        local relic = wanted[x.e.uuid]
        if relic and x.e.u._equipped_relic ~= relic then
            local worn, spare = 0, nil
            local onTeam = {}
            for _, e in ipairs(UNIT.equipped()) do onTeam[e.uuid] = true end
            for uuid, o in pairs(owned) do
                if o._equipped_relic then
                    worn = worn + 1
                    if not onTeam[uuid] and (not spare or not table.find(B.str.core or {}, uuid)) then spare = o._equipped_relic end
                end
            end
            if worn >= STR.MAX_RELICS and spare and not off(spare) then return false end
            local t0 = U.now()
            SF.request("relicMove", "use_unique_item", relic, { unit_uuid = x.e.uuid })
            while U.now() - t0 < 4 and x.e.u._equipped_relic ~= relic do task.wait(0.25) end
            task.wait(1.2)
            if x.e.u._equipped_relic ~= relic then
                SF.log(1, "POWER", string.format("the game didn't put %s on %s (%s): trying again in 5 min", (C.Items[(s.inventory:get_item_by_uuid(relic) or {}).item_id] or {}).name or "that relic", UNIT.name(x.e.id), say(t0)))
                SF.backoff("relicMove", 300)
                B.str.relicAt = 0
                return false
            end
            moved = moved + 1
        end
    end
    MODE._sigAt = nil
    B.str.relicSig = MODE.teamSig()
    B.str.relicTeam = B.str.relicSig
    B.str.relicNote = string.format("relics moved for +%.1f%% team damage", gain)
    STR.note(string.format("moved %d relics for +%.1f%% team damage", moved, gain))
    return true
end
-- the XP food held: {id, n, xp}, the biggest first
function STR.foodHeld()
    local s = C.session()
    local out = {}
    local inv = s and s.inventory and s.inventory.inventory_profile_data or {}
    for id, n in pairs(inv.normal_items or {}) do
        local d = C.Items[id]
        if type(d) == "table" and type(d.usage) == "table" and d.usage.type == "xp_feed" and (tonumber(n) or 0) > 0 then
            table.insert(out, { id = id, n = tonumber(n), xp = tonumber(d.usage.xp_amount) or 0 })
        end
    end
    table.sort(out, function(a, b) return a.xp > b.xp end)
    return out
end
-- the XP every core unit can still take
function STR.xpRoom()
    local s, total = C.session(), 0
    for _, uuid in ipairs(s and STR.core() or {}) do
        local u = s.collection:get_unit_by_uuid(uuid)
        if u then total = total + math.max(0, STR.xpFor(u.unit_id, STR.cap(u)) - (tonumber(u.xp) or 0)) end
    end
    return total
end
-- every action the Team tab could take now, best first: {kind, uuid, name, gain, text, blocked}
function STR.plan()
    local s = C.session()
    if not s then return {} end
    local acts = {}
    local core = STR.core()
    local food = STR.foodHeld()
    local foodXp = 0
    for _, f in ipairs(food) do foodXp = foodXp + f.n * f.xp end
    local manualFuse = CFG.autoFuse and CFG.fuseUnit ~= "" and CFG.fuseUnit or nil
    local need = (B.fuseInfo and tonumber(B.fuseInfo.requirement)) or (B.lb and tonumber(B.lb.requirement)) or 12
    local wish = ADV.have("divine_wish")
    for _, uuid in ipairs(core) do
        local u = s.collection:get_unit_by_uuid(uuid)
        if u then
            local id, name = u.unit_id, UNIT.name(u.unit_id)
            local role = STR.role(id)
            if CFG.teamXp and foodXp > 0 then
                local _, add = STR.gainXp(u, foodXp)
                -- (judged on the worth of 500k XP, a few levels: levels are steps, so 85k XP showed nothing on Iron Sentinel at 2 million a stretch and went to Mochi, worth a quarter as much per XP)
                local gLong, addLong = STR.gainXp(u, 500000)
                local g = addLong > 0 and gLong / addLong * add or 0
                if add > 0 and g > 0 then
                    table.insert(acts, { kind = "feed", uuid = uuid, name = name, gain = g, add = add, text = string.format("feed %s %s XP: level %d → %d (+%.1f%% team damage)", name, U.fmt(add), STR.level(u), STR.level({ unit_id = id, xp = (tonumber(u.xp) or 0) + add }), g) })
                end
            end
            local fuseNo = B.str.fuseNo and tonumber(B.str.fuseNo[uuid])
            if CFG.teamFuse and STR.lb(u) == 0 and role ~= "farm" and uuid ~= manualFuse and not (fuseNo and os.time() - fuseNo < 86400) then
                local g = STR.gainFuse(u)
                local atCap = STR.xpFor(id, STR.cap(u)) <= (tonumber(u.xp) or 0)
                local okF, _, got = pcall(HUB.fuseFuel, u, need)
                got = okF and got or 0
                local blocked = (not atCap and "not at its level cap yet") or (wish < 1 and "no Divine Wish (the Daily Challenge pays one)")
                    or (got < need and string.format("spare units it may use are worth %d of %d points", math.floor(got), math.floor(need))) or nil
                table.insert(acts, { kind = "fuse", uuid = uuid, name = name, gain = g, blocked = blocked, text = string.format("limit break %s (+%.1f%% team damage once it reaches level 110)", name, g) })
            end
        end
    end
    table.sort(acts, function(a, b) if a.gain ~= b.gain then return a.gain > b.gain end return a.text < b.text end)
    -- (the what-if copies' cached multipliers go)
    for k in pairs(UNIT._mult) do if type(k) == "string" and k:sub(1, 5) == "what:" then UNIT._mult[k] = nil end end
    B.str.acts, B.str.actsAt = {}, os.time()
    for i = 1, math.min(12, #acts) do
        local a = acts[i]
        table.insert(B.str.acts, { kind = a.kind, uuid = a.uuid, name = a.name, gain = a.gain, text = a.text, blocked = a.blocked })
    end
    return acts
end
-- a Divine Wish is worth what it would do for your core units (the mode ranker's gems), never below the table
function STR.itemWorth(id)
    if not (B.str.acts and os.time() - (tonumber(B.str.actsAt) or 0) < 900) then return nil end
    local best = {}
    for _, a in ipairs(B.str.acts) do if a.gain and (not best[a.kind] or a.gain > best[a.kind]) then best[a.kind] = a.gain end end
    local v = CFG.strengthValue or 300
    if id == "divine_wish" then return best.fuse and math.max(C.ITEM_VALUE.divine_wish or 400, best.fuse * v) or nil end
    return nil
end
-- gems per XP for the mode ranker: the best core unit's gain for 500,000 XP (a few levels: a level is a step, so a small probe
-- shows nothing), never more than the food price while gold lasts
function STR.xpRate()
    local s = C.session()
    if not s then return 0 end
    local best = 0
    for _, uuid in ipairs(STR.core()) do
        local u = s.collection:get_unit_by_uuid(uuid)
        if u then local g, add = STR.gainXp(u, 500000); if add > 0 then best = math.max(best, g / add) end end
    end
    local gems = best * (CFG.strengthValue or 300)
    if (tonumber(C.cur("gold")) or 0) > (CFG.xpGoldFloor or 100000) then gems = math.min(gems, (C.GOLD_VALUE or 0.02) / 14) end
    return gems
end
-- the XP a run of a mode gives your units: measured (B.modes[key].xp, STR.xpSettle), else a rough guess by world and act until a run
-- of it has been measured (it only ever adds a few gems to a mode's value while gold lasts, since food is cheaper)
function STR.xpGuess(m)
    local lv = m.level and C.Levels[m.level]
    if not lv then return 0 end
    local w = math.min(9, tonumber(lv.story_world_rank) or tonumber(m.rank) or 9)
    local act = tonumber(lv.story_level_rank) or 6
    local d = (m.kind == "raid" and 1.5 or 1) * (w > 5 and 2 or 1)
    local base = 2.1564 ^ (w - 1) * (40 + 10 * act) / d
    if m.kind == "infinite" then base = 3 * 30 * 2.1564 ^ (w - 1) / d end
    local damp = w >= 9 and 0.3 or (w >= 7 and 0.5 or 1)
    return base * damp * 6
end
function STR.modeBonus(m)
    if not (CFG.team and CFG.teamXp) or m.kind == "dungeon" or m.kind == "event" then return 0 end
    local rate = STR._xpRate and os.time() - (STR._xpRateAt or 0) < 300 and STR._xpRate or nil
    if not rate then rate = STR.xpRate(); STR._xpRate, STR._xpRateAt = rate, os.time() end
    if rate <= 0 then return 0 end
    local rec = B.modes and B.modes[m.key]
    local xp = tonumber(rec and rec.xp) or STR.xpGuess(m)
    local gems = xp * rate
    if gems < 1 then return 0 end
    return gems, string.format("≈%s XP for your team (≈%d gems)", U.fmt(xp), math.floor(gems + 0.5))
end
-- back in the lobby: what the last run paid in XP, per mode
function STR.xpSettle()
    local r = B.lastRun
    if not (r and type(r.xp0) == "table" and r.key) then return end
    local s = C.session()
    if not s then return end
    local sum, n = 0, 0
    for uuid, x0 in pairs(r.xp0) do
        local u = s.collection:get_unit_by_uuid(uuid)
        if u then sum = sum + math.max(0, (tonumber(u.xp) or 0) - (tonumber(x0) or 0)); n = n + 1 end
    end
    B.lastRun = nil
    if n == 0 then return end
    local rec = MODE.rec(r.key)
    rec.xp = rec.xp and (rec.xp + (sum - rec.xp) * 0.3) or sum
    if sum > 0 then SF.log(2, STR.LOG, string.format("%s paid your units %s XP", r.key, U.fmt(sum))) end
    SF.saveSoon()
end
function STR.note(msg)
    SF.log(1, STR.LOG, msg)
    table.insert(B.str.log, 1, { at = os.time(), msg = msg })
    while #B.str.log > 20 do table.remove(B.str.log) end
    SF.saveSoon()
end
-- one action, for real: reads the game's answer back before it counts
function STR.run(a)
    local s = C.session()
    local u = s and s.collection:get_unit_by_uuid(a.uuid)
    if not u then return end
    if a.kind == "feed" then
        -- (the largest food first, never past the cap; the Adept trait makes each item worth half more)
        local tr = UNIT.trait(u)
        local mul = tr == "neuroplasticity" and 1.5 or 1
        local room = math.max(0, STR.xpFor(u.unit_id, STR.cap(u)) - (tonumber(u.xp) or 0))
        local feed, planned, n = {}, 0, 0
        for _, f in ipairs(STR.foodHeld()) do
            local per = f.xp * mul
            local count = math.min(f.n, math.floor((room - planned) / math.max(1, per)))
            if count > 0 then feed[f.id] = count; planned = planned + count * per; n = n + count end
        end
        if n == 0 then B.str.feedNote = a.name .. ": no food small enough for the XP it has left"; return end
        local before, lvl0 = tonumber(u.xp) or 0, STR.level(u)
        local ok, r = SF.request("feed", "level_up_feed", a.uuid, feed)
        local t0 = U.now()
        while U.now() - t0 < 4 and (tonumber((s.collection:get_unit_by_uuid(a.uuid) or u).xp) or 0) <= before do task.wait(0.25) end
        local after = s.collection:get_unit_by_uuid(a.uuid) or u
        local got = (tonumber(after.xp) or 0) - before
        if got > 0 then
            SPEND.add(string.format("%d XP food on %s", n, a.name), n, "items", string.format("Team tab: +%s XP, level %d → %d", U.fmt(got), lvl0, STR.level(after)))
            STR.note(string.format("fed %s %d items: +%s XP, level %d → %d%s", a.name, n, U.fmt(got), lvl0, STR.level(after), math.abs(got - planned) > planned * 0.1 and string.format(" (planned %s)", U.fmt(planned)) or ""))
        else
            STR.note(string.format("the game didn't take the food for %s (%s): trying again in 10 min", a.name, tostring(ok and r or "no answer")))
            SF.backoff("feed", 600)
        end
    elseif a.kind == "fuse" then
        HUB.fuseInto(a.uuid, false)
    end
end
-- the slot a unit is equipped in (nil: not on the team)
function STR.slotOf(uuid)
    local s = C.session()
    for slot, v in pairs(s and s.profile_data.collection.equipped_units or {}) do if v == uuid then return tonumber(slot) or slot end end
    return nil
end
-- a unit taken out for a moment, back in its slot. Kept for the next pass when the game doesn't take it; a room isn't entered short of a unit (DG.enter)
function STR.reequip()
    local r = B.str.reequip
    if not r then return true end
    local s = C.session()
    local u = s and s.collection:get_unit_by_uuid(r.uuid)
    if not u then B.str.reequip = nil; return true end
    for _ = 1, 3 do
        if STR.slotOf(r.uuid) then break end
        -- (no slot named: it takes the free one. A named slot only replaces whoever is in it: on an empty one the game does nothing, without a word)
        SF.request("eq", "equip_unit", r.uuid)
        local t0 = U.now()
        while U.now() - t0 < 3 and not STR.slotOf(r.uuid) do task.wait(0.25) end
    end
    MODE._sigAt = nil
    if STR.slotOf(r.uuid) then B.str.reequip = nil; SF.saveSoon(); return true end
    SF.log(1, "TEAM", string.format("%s didn't go back into slot %s: trying again", UNIT.name(u.unit_id), tostring(r.slot)))
    return false
end
-- which request each action uses, so one the game just refused doesn't hold up the ones after it
STR.REMOTE = { feed = "feed", fuse = "fuse" }
STR.WORK_MAX = 300 -- seconds a lobby stop may take: what's left waits for the next one
-- the first action that can really run now
function STR.nextAct(acts)
    local now = os.time()
    for _, a in ipairs(acts or {}) do
        local back = SF.req.back[STR.REMOTE[a.kind] or ""]
        if not a.blocked and not (back and U.now() < back)
            and (tonumber(B.str.noWork[a.kind]) or 0) <= now and (tonumber(B.str.noWork[a.kind .. ":" .. tostring(a.uuid)]) or 0) <= now then return a end
    end
end
-- what the Team tab spends: when one of these moves, an action really did something
function STR.workSig()
    local food = 0
    for _, f in ipairs(STR.foodHeld()) do food = food + f.n end
    return table.concat({ food, ADV.have("divine_wish") }, ",")
end
-- is there something the Team tab can do? Its words and its kind, or nil. Works in a match too (the results screen asks, to go through the lobby: your call, Oct 31).
-- Going through the lobby costs no door: after a won room nothing is selected and any room on offer enters from there (rooms 11 and 12, Oct 31)
STR.FEED_STOP_GAIN = 0.5 -- % of the team's damage held XP food has to add before it's a reason to stop at the lobby. Any lobby visit feeds it all the same
-- your Focus unit has all it needs and nothing stands in its way: it evolves in the lobby (HUB.autoEvolve), so the run stops there instead of pressing Next past it. Goals are only worked out every 5 min, so they're asked again here
function STR.focusReady()
    if not (CFG.autoEvolve and CFG.evolveUnit ~= "") then return nil end
    pcall(ADV.refresh)
    for _, g in ipairs(B.goals or {}) do
        if g.pinned and g.uuid == CFG.evolveUnit and g.ready and (HUB.evoBlocked[g.uuid] or 0) < os.time() then
            local onTeam = {}
            for _, e in ipairs(UNIT.equipped()) do onTeam[e.uuid] = true end
            if not HUB.evoEats(g, onTeam) then return g end
        end
    end
end
function STR.hasWork(inLobby)
    if not inLobby then
        local focus = STR.focusReady()
        if focus then return "evolve " .. UNIT.name(focus.from) .. ", your focus", "evolve" end
        if HUB.snipeWanted() then return "pull " .. UNIT.name(CFG.snipeUnit) .. " while it's featured (Banner Snipe)", "snipe" end
        if HUB.snipeDue() then return "look at the banners for " .. UNIT.name(CFG.snipeUnit) .. ": they've turned over (Banner Snipe)", "snipe" end
        if B.ownSwap then return "put " .. UNIT.name(B.ownSwap.into) .. " on your team", "ownSwap" end
    end
    if not CFG.team or CFG.strDry then return nil end
    STR.acts = STR.plan()
    HUB.last.teamPlan = U.now()
    local list = STR.acts
    -- (from a results screen. Story runs drop a couple of XP food each, so there was always a feed to do, worth +0.0%, and the Next button never got pressed: it waits until it adds up)
    if not inLobby then
        list = {}
        for _, x in ipairs(STR.acts) do
            if not (x.kind == "feed" and (tonumber(x.gain) or 0) < STR.FEED_STOP_GAIN) then table.insert(list, x) end
        end
    end
    local a = STR.nextAct(list)
    if a then return a.text, a.kind end
    -- relics go on after the team is settled: HUB.launch, once the team search and training are done (the user's call, Nov 1: they moved for the old team, then again 24 s later for the new one). In the lobby
    -- that's the only time, unless nothing will change the team. From a results screen a lobby stop has to be worth it, on any team (a move of +0.8% cost a Next)
    if CFG.teamRelics and (tonumber(B.str.noWork.relic) or 0) <= os.time() and (not inLobby or not (CFG.autoTeam and CFG.play)) then
        local _, gain = STR.relicPlan()
        if gain and gain >= (inLobby and STR.relicBar() or STR.RELIC_SETTLED_GAIN) then return string.format("move relics for +%.1f%% team damage", gain), "relic" end
    end
    -- (the gold shop restocks daily and is only reached from the lobby: a look every 6 hours while your units can take more)
    if not inLobby and CFG.teamXp and CFG.teamBuyXp and CFG.goldShop and os.time() - (tonumber(B.str.shopAt) or 0) > 21600 and STR.xpRoom() > 0
        and (tonumber(C.cur("gold")) or 0) > (CFG.xpGoldFloor or 100000) then return "look for XP food in the gold shop", "shop" end
    return nil
end
-- in the lobby, before anything starts: the Team tab goes until it has nothing more it can do
function STR.finishWork()
    local t0 = U.now()
    local done = 0
    while SF.alive and CFG.master and not B.holdLobby and U.now() - t0 < STR.WORK_MAX do
        local work, kind = STR.hasWork(true)
        if not work then break end
        SF.status("Mode", "Team tab first: " .. tostring(work))
        if kind == "relic" then
            local okR, moved = pcall(STR.relicsApply, true)
            if not (okR and moved) then B.str.noWork.relic = os.time() + 1800 end
        else
            STR.tick()
        end
        done = done + 1
        -- (the game answers fast swaps with "Sending requests too fast")
        task.wait(4)
    end
    if done > 0 then
        SF.log(1, STR.LOG, string.format("Team tab finished for now: %d actions in %ds", done, math.floor(U.now() - t0)))
        MODE._sigAt, MODE.lastScored = nil, nil
        SF.saveSoon()
    end
end
-- the Team tab's loop: a plan every minute, one action every 20 s (dry run: it only says what it would do)
function STR.tick()
    if not CFG.team then B.str.next = "Off."; return end
    if B.str.reequip then STR.reequip() end
    local acts
    if HUB.every("teamPlan", 60) or not B.str.acts then acts = STR.plan() else acts = STR.acts end
    STR.acts = acts or STR.acts or {}
    local run = STR.nextAct(STR.acts)
    if not run then
        local top = STR.acts[1]
        B.str.next = top and (top.text .. " — waiting: " .. tostring(top.blocked)) or "Nothing to do: every core unit is as strong as what you have allows."
        return
    end
    if CFG.strDry then
        B.str.next = "Would " .. run.text .. ". Dry Run is on: nothing is spent."
        if B.str.dryLast ~= run.text then B.str.dryLast = run.text; SF.log(1, STR.LOG, "dry run: would " .. run.text) end
        return
    end
    B.str.next = run.text
    local sig0 = STR.workSig()
    local ok, err = pcall(STR.run, run)
    if not ok then SF.log(1, "ERROR", "team: " .. tostring(err)) end
    -- (nothing spent, nothing changed: not asked again for half an hour, so an action that does nothing can't hold up a room. A limit break listed for its 30 s is on its way)
    local armed = run.kind == "fuse" and os.time() - (tonumber(CFG.fuseArmAt) or 0) < 45
    if STR.workSig() == sig0 and not armed then B.str.noWork[run.kind .. ":" .. tostring(run.uuid)] = os.time() + 1800 end
    -- (a refusal's wait outlasts the teleport)
    local back = SF.req.back[STR.REMOTE[run.kind] or ""]
    if back and back > U.now() then B.str.noWork[run.kind] = os.time() + math.ceil(back - U.now()) end
    HUB.last.teamPlan = nil
end
-- the Team tab's rows: one line per core unit
function STR.rows()
    local s = C.session()
    local out = {}
    if not s then return out end
    for _, uuid in ipairs(B.str.core or {}) do
        local u = s.collection:get_unit_by_uuid(uuid)
        if u then
            local tr, tier = UNIT.trait(u)
            local parts = { string.format("level %d/%d", STR.level(u), STR.cap(u)), STR.traitName(tr, tier) }
            if u.trait_stats then table.insert(parts, (HUB.statRanks(u):gsub(" · ", " / "))) end
            table.insert(parts, UNIT.relicName(u) and ("relic: " .. UNIT.relicName(u)) or "no relic")
            if STR.lb(u) >= 1 then table.insert(parts, "limit broken ✓") end
            local nx
            for _, a in ipairs(B.str.acts or {}) do if a.uuid == uuid then nx = a; break end end
            if nx then table.insert(parts, "next: " .. (nx.text:gsub("^%l", string.upper)) .. (nx.blocked and (" (waiting: " .. nx.blocked .. ")") or "")) end
            table.insert(out, { name = UNIT.name(u.unit_id), text = table.concat(parts, " · ") })
        end
    end
    return out
end
function STR.text()
    if not CFG.team then return "Off. Switch it on and the farm makes your core units stronger with what you already have." end
    local lines = { B.str.next or "Working it out in the lobby…" }
    if B.str.fuseNote then table.insert(lines, "Limit break: " .. B.str.fuseNote) end
    if B.str.relicNote then table.insert(lines, "Relics: " .. B.str.relicNote) end
    for i = 1, math.min(4, #(B.str.log or {})) do table.insert(lines, os.date("%H:%M", B.str.log[i].at) .. " " .. B.str.log[i].msg) end
    return table.concat(lines, "\n")
end

-- ============================================================
--  LOBBY
-- ============================================================
HUB.last = {}
HUB.hatched = {} -- [unitId] = true: pulled this lobby visit (from units_hatched_through_banner, which never lags)
-- evolve a ready goal (only when you press the Path button twice): checks it really happened
function HUB.evolve(g, why)
    local s = C.session()
    local before = s.collection:get_unit_by_uuid(g.uuid)
    if not before then return false, "unit not found" end
    local had, seen = 0, {}
    for uuid, u in pairs(s.profile_data.collection.owned_units) do if u.unit_id == g.to then had = had + 1; seen[uuid] = true end end
    local ok, r = SF.request("evolve", "evolve_unit", g.uuid)
    task.wait(2)
    local after = s.collection:get_unit_by_uuid(g.uuid)
    local now = 0
    for uuid, u in pairs(s.profile_data.collection.owned_units) do
        if u.unit_id == g.to then
            now = now + 1
            -- (evolving gives the unit a new id: your Lobby-tab picks on it follow)
            if not seen[uuid] then
                if CFG.fuseXpUnit == g.uuid then CFG.fuseXpUnit, CFG.fuseXpId = uuid, g.to; SF.saveSoon() end
                if CFG.fuseUnit == g.uuid then CFG.fuseUnit = uuid; SF.saveSoon() end
            end
        end
    end
    if now > had then
        local used = {}
        for _, it in ipairs(g.items or {}) do table.insert(used, string.format("%s ×%d", (C.Items[it.id] or {}).name or it.id, it.amount)) end
        for _, e in ipairs(g.eats or {}) do table.insert(used, string.format("%d× %s", e.amount, UNIT.name(e.id))) end
        local text = string.format("%s → %s (score %s → %s)", UNIT.name(g.from), UNIT.name(g.to), U.fmt(g.scoreFrom or 0), U.fmt(g.scoreTo or 0))
        SPEND.add("evolved " .. text, 1, "evolution", (why or "your choice") .. (#used > 0 and (" · used " .. table.concat(used, ", ")) or ""))
        SF.log(1, "EVOLVE", text .. " — " .. (why or "your choice") .. (#used > 0 and (" · used " .. table.concat(used, ", ")) or ""))
        MODE._sigAt = nil
        pcall(ADV.refresh)
        return true, UNIT.name(g.to) .. " is yours!"
    end
    SF.log(1, "EVOLVE", "evolve refused for " .. UNIT.name(g.from) .. " (" .. tostring(r) .. "), unit now " .. tostring(after and after.unit_id))
    return false, "the game said no (" .. tostring(r) .. ")"
end
-- smart evolve (lobby): evolves a ready unit when
--   · the game's own requirements are met and it's your best copy of that unit,
--   · the evolved form scores higher at full upgrade (the game's formulas: level, trait, rolls carry over),
--   · every item it uses still leaves enough for the bigger evolution goals that need the same item,
--   · the other copies it would use up are all spare: not on your team, no trait, weaker than the one evolving
--     (the game picks which unlocked copies go — lock a copy in the game to keep it out)
-- biggest gain first, at most 2 a lobby visit; each one goes in the log and the Spending tab
HUB.evoBlocked = {}
-- would this evolution use up a copy you may want? (the game picks which unlocked copies go)
function HUB.evoEats(g, onTeam)
    local s = C.session()
    local okM, myScore = pcall(UNIT.score, s.collection:get_unit_by_uuid(g.uuid))
    for _, e in ipairs(g.eats or {}) do
        for _, o in ipairs(ADV.copies(e.id, e.shiny, g.uuid)) do
            local u = s.collection:get_unit_by_uuid(o.uuid) or o
            local okS, sc = pcall(UNIT.score, u)
            if onTeam[o.uuid] or UNIT.trait(u) or (okM and okS and sc >= myScore) then
                return string.format("would use up a %s you may want (on your team, a trait, or stronger) — lock it in the game to keep it", UNIT.name(e.id))
            end
        end
    end
end
-- your Lobby tab picks. Each runs in the lobby only while its switch is on, and switches itself off when it's done
HUB.pickNote = {}
function HUB.pickDone(key, title, msg, kind)
    CFG[key] = false
    pcall(function() GUI.UI[key].Set(false, true) end)
    HUB.pickNote[key] = msg
    SF.log(1, "LOBBY", title .. ": " .. msg)
    if SF.notify then SF.notify(title, msg, kind or "success") end
    SF.saveSoon()
end
-- the next Focus, once this one is done (CFG.focusNext is a unit id: the copy furthest along when its turn comes). Choosing a Focus by hand clears it (HUB.setFocus)
function HUB.focusNextUp()
    if CFG.focusNext == "" or GUI.focusNow() ~= "" then return end
    local id = CFG.focusNext
    local s = C.session()
    local best, bestXp
    for uuid, o in pairs(s.profile_data.collection.owned_units) do
        if o.unit_id == id and (not best or (tonumber(o.xp) or 0) > bestXp) then best, bestXp = uuid, tonumber(o.xp) or 0 end
    end
    if not best then
        CFG.focusNext = ""
        SF.log(1, "LOBBY", "Focus: next up was " .. UNIT.name(id) .. ", and you don't have one any more")
        return SF.saveSoon()
    end
    CFG.focusDone = CFG.evolveUnit
    SF.log(1, "LOBBY", "Focus: next up is " .. UNIT.name(id))
    HUB.setFocus(best)
    GUI.focusSig = nil
    if SF.notify then SF.notify("Focus", "now focusing on " .. UNIT.name(id), "success") end
end
-- Auto Evolve: ADV.goals puts your pick first and values its items, TRAIN trains it, this evolves it once it's ready
function HUB.autoEvolve()
    if not CFG.autoEvolve or CFG.evolveUnit == "" then return end
    local s = C.session()
    if not (s and s.collection:get_unit_by_uuid(CFG.evolveUnit)) then return HUB.pickDone("autoEvolve", "Focus", "that unit is gone", "warning") end
    local g
    for _, x in ipairs(B.goals or {}) do if x.pinned and x.uuid == CFG.evolveUnit then g = x; break end end
    if not g then
        -- (goals are only worked out every 5 min: give a fresh pick the chance before saying it has no evolution)
        local u = s.collection:get_unit_by_uuid(CFG.evolveUnit)
        local d = C.Units[u.unit_id]
        if not (d and d.evolve and d.evolve.evolve_unit) then HUB.pickDone("autoEvolve", "Focus", UNIT.name(u.unit_id) .. " has no evolution left", "warning") end
        return
    end
    HUB.pickNote.autoEvolve = nil
    if not g.ready then return end
    local onTeam = {}
    for _, e in ipairs(UNIT.equipped()) do onTeam[e.uuid] = true end
    local why = HUB.evoEats(g, onTeam)
    if why then HUB.pickNote.autoEvolve = why; return end
    if (HUB.evoBlocked[g.uuid] or 0) >= os.time() then return end
    local ok, msg = HUB.evolve(g, "your focus (Goals tab)")
    if ok then HUB.pickDone("autoEvolve", "Focus", msg)
    else HUB.evoBlocked[g.uuid] = os.time() + 3600; HUB.pickNote.autoEvolve = msg end
end
function HUB.evolveText()
    if CFG.evolveUnit == "" then return "Pick a unit. The farm goes after the items and takedowns it needs, and evolves it once it's ready (evolving can't be undone)." end
    local note = HUB.pickNote.autoEvolve and ("\n" .. HUB.pickNote.autoEvolve) or ""
    if not CFG.autoEvolve then return "Switch it on to start." .. note end
    for _, g in ipairs(B.goals or {}) do
        if g.pinned and g.uuid == CFG.evolveUnit then
            return g.text .. ((MODE.onlyOn() and not g.ready) and ("\nOnly " .. MODE.onlyText() .. " is on (Play tab), so it can only farm there.") or "") .. note
        end
    end
    return "Works out what it needs in the lobby…" .. note
end
-- Auto Fuse (the game's Unit Fusion, its Limit Break): uses up spare Mythic and Secret units for good, and a Divine Wish.
-- It may use a unit only if it's unlocked, off your team, has no trait, relic or limit break, isn't shiny, isn't a goal or
-- another of your picks, and the guides don't rate it S or better. Weakest first. Lock a unit in the game to keep it safe
function HUB.fuseFuel(target, need)
    local s = C.session()
    local keep = { [target.uuid] = true, [CFG.evolveUnit] = true, [CFG.fuseXpUnit] = true }
    local keepId = {}
    for _, e in ipairs(UNIT.equipped()) do keep[e.uuid] = true end
    for _, u in ipairs(B.savedTeam or {}) do keep[u] = true end
    for _, u in ipairs(B.train and B.train.on and B.train.on.base or {}) do keep[u] = true end
    for _, g in ipairs(B.goals or {}) do
        keep[g.uuid] = true
        for _, e in ipairs(g.eats or {}) do keepId[e.id] = true end
    end
    -- (never a core unit of the Team tab)
    for _, uuid in ipairs(B.str and B.str.core or {}) do keep[uuid] = true end
    local strongest = ADV.strongest(10)
    local rows, total = {}, 0
    for uuid, u0 in pairs(s.profile_data.collection.owned_units) do
        local u = s.collection:get_unit_by_uuid(uuid) or u0
        local okF, good, pts = pcall(C.USC.is_unit_good_for_fusion, target, u)
        if okF and good and not (u0._locked or u._locked) and not keep[uuid] and not keepId[u.unit_id] and not (u0._equipped_relic or u._equipped_relic) and not (u0.shiny or u.shiny)
            and not UNIT.trait(u) and not (u0.further_modifiers and u0.further_modifiers.limit_break) then
            local order = ADV.fodderOrder(u.unit_id)
            if order and not strongest[uuid] then
                local okS, sc = pcall(UNIT.score, u)
                table.insert(rows, { uuid = uuid, id = u.unit_id, pts = tonumber(pts) or 1, sc = okS and sc or 0, order = order })
                total = total + (tonumber(pts) or 1)
            end
        end
    end
    table.sort(rows, function(a, b)
        if a.order ~= b.order then return a.order < b.order end
        if a.sc ~= b.sc then return a.sc < b.sc end
        return a.uuid < b.uuid
    end)
    local pick, got = {}, 0
    for _, x in ipairs(rows) do
        if got >= need then break end
        table.insert(pick, x)
        got = got + x.pts
    end
    return pick, got, total
end
-- every unit the game would take as fuel for a limit break, with what's worth knowing before it's destroyed (the user, Nov 2: "give more details for fodder units and
-- multi select too cause you need ten"). Locked and equipped units never show: lock one in the game to keep it out. safe = the farm's own rule would take it too (HUB.fuseFuel)
function HUB.fodderRows(target)
    local s = C.session()
    if not (s and target) then return {} end
    local equipped, core, goal, goalId = {}, {}, {}, {}
    for _, e in ipairs(UNIT.equipped()) do equipped[e.uuid] = true end
    for _, uuid in ipairs(B.str and B.str.core or {}) do core[uuid] = true end
    for _, g in ipairs(B.goals or {}) do
        goal[g.uuid] = true
        for _, e in ipairs(g.eats or {}) do goalId[e.id] = true end
    end
    local safe = {}
    local okF, pick = pcall(HUB.fuseFuel, target, math.huge)
    for _, x in ipairs(okF and pick or {}) do safe[x.uuid] = true end
    local rows = {}
    for uuid, u0 in pairs(s.profile_data.collection.owned_units) do
        if uuid ~= target.uuid and not equipped[uuid] and not u0._locked then
            local u = s.collection:get_unit_by_uuid(uuid) or u0
            local okG, good, pts = pcall(C.USC.is_unit_good_for_fusion, target, u)
            if okG and good and not u._locked then
                local d = C.Units[u.unit_id] or {}
                local flags = {}
                local tr, tier = UNIT.trait(u)
                if tr then table.insert(flags, "trait " .. tostring((C.traitInfo(tr) or {}).name or tr) .. (tier and tier ~= "1" and (" " .. tier) or "")) end
                if u._equipped_relic or u0._equipped_relic then table.insert(flags, "relic " .. tostring(UNIT.relicName(u) or "")) end
                if u.shiny or u0.shiny then table.insert(flags, "shiny") end
                if u.further_modifiers and u.further_modifiers.limit_break then table.insert(flags, "limit broken") end
                if core[uuid] then table.insert(flags, "a core unit") end
                if goal[uuid] or goalId[u.unit_id] then table.insert(flags, "part of a goal") end
                local okS, sc = pcall(UNIT.score, u)
                table.insert(rows, { uuid = uuid, id = u.unit_id, name = UNIT.name(u.unit_id), rarity = d.rarity or "?", lvl = STR.level(u), pts = tonumber(pts) or 1,
                    evolved = UNIT.isEvolvedForm(u.unit_id), flags = flags, safe = safe[uuid] or false, sc = okS and sc or 0 })
            end
        end
    end
    -- (the ones the farm's rule would take first, weakest first; then the rest, with what makes them worth keeping)
    table.sort(rows, function(a, b)
        if a.safe ~= b.safe then return a.safe end
        if a.sc ~= b.sc then return a.sc < b.sc end
        return a.uuid < b.uuid
    end)
    return rows
end
-- your ticked fodder, as the game sees it now: what's still there and fit, their points, and the ones that dropped out
function HUB.fodderPicked(target)
    local s = C.session()
    local pick, got, gone = {}, 0, 0
    local equipped = {}
    for _, e in ipairs(UNIT.equipped()) do equipped[e.uuid] = true end
    for _, uuid in ipairs(CFG.fuseFodder or {}) do
        local u = s and s.collection:get_unit_by_uuid(uuid)
        local okG, good, pts = false, false, 0
        if u and target and uuid ~= target.uuid and not u._locked and not equipped[uuid] then okG, good, pts = pcall(C.USC.is_unit_good_for_fusion, target, u) end
        if okG and good then table.insert(pick, { uuid = uuid, id = u.unit_id, pts = tonumber(pts) or 1 }); got = got + (tonumber(pts) or 1)
        else gone = gone + 1 end
    end
    return pick, got, gone
end
function HUB.fuseText()
    if CFG.fuseUnit == "" then return "Pick a unit. Fusing limit breaks it (level cap 100 → 110), and destroys the units it uses." end
    local s = C.session()
    local u = s and s.collection:get_unit_by_uuid(CFG.fuseUnit)
    if not u then return "That unit is gone." end
    local need = (B.fuseInfo and B.fuseInfo.uuid == u.uuid) and tonumber(B.fuseInfo.requirement) or 12
    local text
    if #(CFG.fuseFodder or {}) > 0 then
        local pick, got, gone = HUB.fodderPicked(u)
        local names = {}
        for _, x in ipairs(pick) do table.insert(names, UNIT.name(x.id)) end
        text = string.format("Your picks: %d units worth %d of %d points%s.", #pick, got, need, gone > 0 and string.format(" (%d of them can't be used any more)", gone) or "")
        if got >= need then text = text .. "\nIt would destroy: " .. table.concat(names, ", ") .. "." end
    else
        local pick, got, total = HUB.fuseFuel(u, need)
        local names = {}
        for _, x in ipairs(pick) do table.insert(names, UNIT.name(x.id)) end
        text = string.format("No picks yet, so the farm chooses: units it may use are worth %d of %d points.", total, need)
        if got >= need then text = text .. "\nIt would destroy: " .. table.concat(names, ", ") .. "."
        else text = text .. "\nIt only takes units that are unlocked, off your team, not part of a goal, with no trait, relic or shine, and that the guides don't rate S or better. Tick units below to choose yourself." end
    end
    return text .. (HUB.pickNote.autoFuse and ("\n" .. HUB.pickNote.autoFuse) or "")
end
function HUB.autoFuse()
    if not CFG.autoFuse or CFG.fuseUnit == "" then return end
    HUB.fuseInto(CFG.fuseUnit, true)
end
-- the game's other fuse: spare units fused into one for its XP (feed_units; UnitServiceCore.calculate_xp_gain_from_fuse: here a Rare is worth 842 XP, an Epic 4.2k, a Legendary 56k, a Mythic
-- 175k). It can't be undone, so it goes by the rule the limit break's fuel goes by, only takes level-1 units, and never a Mythic or better: those are that fuel
HUB.FUSE_RANK = { Rare = 1, Epic = 2, Legendary = 3 }
function HUB.xpFodder(target)
    local s = C.session()
    local most = HUB.FUSE_RANK[CFG.fuseXpRarity] or 2
    local keep = { [target.uuid] = true, [CFG.evolveUnit] = true, [CFG.fuseUnit] = true }
    local keepId = { [tostring(CFG.pullGoal)] = true }
    for _, e in ipairs(UNIT.equipped()) do keep[e.uuid] = true end
    for _, u in ipairs(B.savedTeam or {}) do keep[u] = true end
    for _, u in ipairs(B.train and B.train.on and B.train.on.base or {}) do keep[u] = true end
    for _, g in ipairs(B.goals or {}) do
        keep[g.uuid] = true
        for _, e in ipairs(g.eats or {}) do keepId[e.id] = true end
    end
    for _, g in ipairs(B.goalsTop or {}) do keep[g.uuid] = true end
    for _, uuid in ipairs(B.str and B.str.core or {}) do keep[uuid] = true end
    local rows, total = {}, 0
    for uuid, u0 in pairs(s.profile_data.collection.owned_units) do
        local d = C.Units[u0.unit_id]
        local rank = d and HUB.FUSE_RANK[d.rarity]
        if rank and rank <= most and not keep[uuid] and not keepId[u0.unit_id] and not UNIT.isFarm(u0.unit_id) and not UNIT.allyBuff(u0.unit_id) then
            local u = s.collection:get_unit_by_uuid(uuid) or u0
            if not (u0._locked or u._locked) and not (u0._equipped_relic or u._equipped_relic) and not (u0.shiny or u.shiny) and not UNIT.trait(u)
                and not (u0.further_modifiers and u0.further_modifiers.limit_break) and STR.level(u) <= 1 then
                if ADV.fodderOrder(u0.unit_id) then
                    local okX, xp = pcall(C.USC.calculate_xp_gain_from_fuse, target, { u }, s)
                    xp = okX and tonumber(xp) or 0
                    if xp > 0 then table.insert(rows, { uuid = uuid, id = u0.unit_id, xp = xp, rarity = d.rarity }); total = total + xp end
                end
            end
        end
    end
    table.sort(rows, function(a, b) if a.xp ~= b.xp then return a.xp < b.xp end; return a.uuid < b.uuid end)
    -- (XP over the level cap is lost: no more than it can take)
    local room = math.max(0, STR.xpFor(target.unit_id, STR.cap(target)) - (tonumber(target.xp) or 0))
    local pick, got = {}, 0
    for _, x in ipairs(rows) do
        if got >= room then break end
        table.insert(pick, x)
        got = got + x.xp
    end
    return pick, got, room, total
end
-- your pick, even after it evolved outside the farm (a new id: found by what it was). Nothing here turns your switch off
function HUB.fuseXpTarget(s)
    local u = s and s.collection:get_unit_by_uuid(CFG.fuseXpUnit)
    if u then
        if CFG.fuseXpId ~= u.unit_id then CFG.fuseXpId = u.unit_id; SF.saveSoon() end
        return u
    end
    local d = s and C.Units[CFG.fuseXpId]
    local to = d and d.evolve and d.evolve.evolve_unit
    local best, bestXp
    for uuid, o in pairs(to and s.profile_data.collection.owned_units or {}) do
        if o.unit_id == to and (not best or (tonumber(o.xp) or 0) > bestXp) then best, bestXp = uuid, tonumber(o.xp) or 0 end
    end
    if not best then return nil end
    SF.log(1, "LOBBY", string.format("Fuse For XP: %s evolved, it now feeds %s", UNIT.name(CFG.fuseXpId), UNIT.name(to)))
    CFG.fuseXpUnit, CFG.fuseXpId = best, to
    SF.saveSoon()
    return s.collection:get_unit_by_uuid(best)
end
function HUB.fuseXpText()
    if CFG.fuseXpUnit == "" then return "Pick a unit. It gets the XP of the spare units fused into it, and those units are destroyed." end
    local s = C.session()
    local u = HUB.fuseXpTarget(s)
    if not u then return "That unit is gone, so nothing is fused. Pick another: your switch stays as you set it." end
    local pick, got, room = HUB.xpFodder(u)
    local by = {}
    for _, x in ipairs(pick) do by[x.rarity] = (by[x.rarity] or 0) + 1 end
    local words = {}
    for _, r in ipairs({ "Rare", "Epic", "Legendary" }) do if by[r] then table.insert(words, by[r] .. " " .. r) end end
    local lvl, cap = STR.level(u), STR.cap(u)
    local text
    if room <= 0 then text = string.format("%s: level %d/%d, at its level cap.", UNIT.name(u.unit_id), lvl, cap)
    elseif #pick == 0 then text = string.format("%s: level %d/%d. No spare units to fuse yet.", UNIT.name(u.unit_id), lvl, cap)
    else text = string.format("%s: level %d/%d. It would destroy %s, for %s XP (level %d).", UNIT.name(u.unit_id), lvl, cap, table.concat(words, ", "), U.fmt(got), STR.level({ unit_id = u.unit_id, xp = (tonumber(u.xp) or 0) + math.min(got, room) })) end
    text = text .. "\nOnly level-1 units that are unlocked, off your team, not part of a goal, with no trait, relic or shine, and that the guides don't rate S or better. Lock a unit in the game to keep it out."
    return text .. (HUB.pickNote.autoFuseXp and ("\n" .. HUB.pickNote.autoFuseXp) or "")
end
function HUB.autoFuseXp()
    if not CFG.autoFuseXp or CFG.fuseXpUnit == "" then return end
    local s = C.session()
    local u = HUB.fuseXpTarget(s)
    if not u then return end
    local name = UNIT.name(u.unit_id)
    local pick, got, room = HUB.xpFodder(u)
    if room <= 0 then HUB.pickNote.autoFuseXp = nil; return end
    if #pick == 0 then HUB.pickNote.autoFuseXp = "Waiting: no spare units to fuse."; return end
    -- it can't be undone: what it would destroy is on the window for at least 30 s after you switch it on
    if os.time() - (tonumber(CFG.fuseXpOnAt) or 0) < 30 then HUB.pickNote.autoFuseXp = "Fusing in a moment: switch it off to cancel."; return end
    HUB.pickNote.autoFuseXp = nil
    local uuids = {}
    for i = 1, math.min(20, #pick) do table.insert(uuids, pick[i].uuid) end
    local before = tonumber(u.xp) or 0
    local t0 = U.now()
    local ok, r = SF.request("fuseXp", "feed_units", CFG.fuseXpUnit, uuids)
    while U.now() - t0 < 5 and (tonumber((s.collection:get_unit_by_uuid(CFG.fuseXpUnit) or u).xp) or 0) <= before do task.wait(0.25) end
    local after = tonumber((s.collection:get_unit_by_uuid(CFG.fuseXpUnit) or u).xp) or 0
    if after > before then
        SPEND.add(string.format("%d units fused into %s", #uuids, name), #uuids, "units", string.format("Fuse For XP: your pick (Fuse tab): +%s XP", U.fmt(after - before)))
        SF.log(1, "LOBBY", string.format("Fuse For XP: %d units into %s, +%s XP, level %d", #uuids, name, U.fmt(after - before), STR.level(s.collection:get_unit_by_uuid(CFG.fuseXpUnit) or u)))
    else
        local said = SF.gameSaid(t0)
        HUB.pickNote.autoFuseXp = "The game said no (" .. tostring(said or (ok and r) or "no answer") .. "): trying again in 30 min."
        SF.log(1, "LOBBY", "Fuse For XP refused: " .. tostring(said or (ok and r) or "no answer"))
        SF.backoff("fuseXp", 1800)
    end
end
-- the limit break itself: your Lobby-tab pick (manual) or the Team tab's target. What it would destroy is listed for 30 s first
function HUB.fuseInto(uuid, manual)
    local s = C.session()
    local u = s and s.collection:get_unit_by_uuid(uuid)
    local function done(msg, kind)
        if manual then HUB.pickDone("autoFuse", "Auto Fuse", msg, kind) else B.str.fuseNote = msg; SF.log(1, STR.LOG, "limit break: " .. msg) end
    end
    local function note(msg) if manual then HUB.pickNote.autoFuse = msg else B.str.fuseNote = msg end end
    if not u then return done("that unit is gone", "warning") end
    local name = UNIT.name(u.unit_id)
    local function lb(x) return x.further_modifiers and x.further_modifiers.limit_break and tonumber(x.further_modifiers.limit_break.current_limit_break) or 0 end
    if lb(u) >= (tonumber(C.USC.get_max_limit_break(u)) or 1) then return done(name .. " is already limit broken") end
    local okI, info = SF.request("fuseInfo", "request_fusion_information", uuid)
    if not (okI and type(info) == "table") then return end
    B.fuseInfo = { requirement = info.requirement, divine_wish = info.divine_wish, allowed = info.allowed, uuid = uuid }
    if not info.allowed then
        -- (the Team tab leaves this unit alone for a day)
        if not manual then B.str.fuseNo = B.str.fuseNo or {}; B.str.fuseNo[uuid] = os.time(); HUB.last.teamPlan = nil end
        return done("the game says " .. name .. " can't be limit broken", "warning")
    end
    note(nil)
    if C.USC.calculate_xp(u.unit_id, C.USC.get_max_level(u)) > (tonumber(u.xp) or 0) then return note("Waiting: " .. name .. " has to reach its level cap first.") end
    local wish = tonumber(info.divine_wish) or 1
    if ADV.have("divine_wish") < wish then return note("Waiting: it needs a Divine Wish.") end
    local need = tonumber(info.requirement) or 12
    -- (the units you ticked on the Fuse tab, if any: only as many of them as it needs, in the order they're listed. Else the farm's safe rule)
    local mine = manual and #(CFG.fuseFodder or {}) > 0
    local pick, got
    if mine then
        local all
        all, got = HUB.fodderPicked(u)
        if got < need then return note(string.format("Waiting: the units you ticked are worth %d of %d points. Tick more on the Fuse tab.", math.floor(got), math.floor(need))) end
        pick, got = {}, 0
        for _, x in ipairs(all) do
            if got >= need then break end
            table.insert(pick, x)
            got = got + x.pts
        end
    else
        pick, got = HUB.fuseFuel(u, need)
        if got < need then return note(string.format("Waiting: spare units it may use are worth %d of %d points.", math.floor(got), math.floor(need))) end
    end
    local uuids, names = {}, {}
    for _, x in ipairs(pick) do table.insert(uuids, x.uuid); table.insert(names, UNIT.name(x.id)) end
    -- it can't be undone: what it would destroy is on the window for at least 30 s first, and a new list starts over
    local sig = uuid .. "|" .. table.concat(uuids, ",")
    if CFG.fuseArmSig ~= sig then
        CFG.fuseArmSig, CFG.fuseArmAt = sig, os.time()
        SF.saveSoon()
        SF.log(1, manual and "LOBBY" or STR.LOG, string.format("%s: %s will use %s (switch it off to cancel)", manual and "Auto Fuse" or "Limit break", name, table.concat(names, ", ")))
    end
    if os.time() - CFG.fuseArmAt < 30 then return note("Fusing " .. name .. " in a moment: switch it off to cancel. It uses " .. table.concat(names, ", ") .. ".") end
    local before = lb(u)
    local ok, r = SF.request("fuse", "fusion_units", uuid, uuids)
    local t0 = U.now()
    while U.now() - t0 < 5 and lb(s.collection:get_unit_by_uuid(uuid) or u) <= before do task.wait(0.25) end
    CFG.fuseArmSig, CFG.fuseArmAt = "", 0
    if lb(s.collection:get_unit_by_uuid(uuid) or u) > before then
        SPEND.add("limit broke " .. name, #uuids, "units", (manual and ("Auto Limit Break: your pick (Fuse tab)" .. (mine and ", your fodder" or "")) or "Team tab") .. " · used " .. table.concat(names, ", ") .. " and a Divine Wish")
        -- (the ticked units that went are gone: the rest stay ticked)
        if mine then
            local left = {}
            for _, x in ipairs(CFG.fuseFodder or {}) do if not table.find(uuids, x) then table.insert(left, x) end end
            CFG.fuseFodder = left
            SF.saveSoon()
        end
        done(name .. " is limit broken!")
        MODE._sigAt = nil
    else
        done("the game said no to limit breaking " .. name .. " (" .. tostring(ok and r or "no answer") .. ")", "error")
    end
end
-- a unit's stat grades, for the Team tab
HUB.GRADES = { "C-", "C", "C+", "B-", "B", "B+", "A-", "A", "A+", "S-", "S", "S+", "SS", "SSS" }
HUB.STATS = { { id = "potency_stat", name = "Attack" }, { id = "speed_stat", name = "Speed" }, { id = "range_stat", name = "Range" } }
function HUB.statRank(u, stat)
    local r = C.core("TraitServiceCore").calculate_stat_rank(u.unit_id, u.trait_stats, stat, u.trait_stats[stat])
    return r, table.find(HUB.GRADES, r) or 0
end
function HUB.statRanks(u)
    local t = {}
    for _, st in ipairs(HUB.STATS) do table.insert(t, st.name .. " " .. (HUB.statRank(u, st.id))) end
    return table.concat(t, " · ")
end
-- the Lobby tab's banners: the currency a banner takes, and which Keep At Least line applies
HUB.BANNER_NAME = { EventClover = "Newest Units", Legacy = "Legacy Units", April2025 = "April (limited)", SakamotoEvent = "Assassin (limited)", Summer2026 = "Summer (Sunny Stars)" }
function HUB.bannerCost(id)
    local b = C.Banners[id]
    if not b then return nil end
    if b.item_cost then
        local it = b.item_cost.item_id
        return { cost = tonumber(b.item_cost.amount) or 10, have = function() return ADV.have(it) end, name = (C.Items[it] or {}).name or it, floor = "tokenFloor" }
    end
    local rc = b.resource_cost
    -- (the Summer banner: only when you pick it for Auto Summon, and never below the pearls Open Sunny Stars keeps too — the user's call, Nov 2)
    if rc and rc.id == "SummerPearls" then
        return { cost = tonumber(rc.amount) or 150, have = function() return C.cur("SummerPearls") end, name = "Summer Pearls", floor = "pearlFloor" }
    end
    if rc and rc.id then
        return { cost = tonumber(rc.amount) or 50, have = function() return C.cur(rc.id) end, name = rc.id == "GemsLegacy" and "Legacy Gems" or rc.id, floor = rc.id == "AprilCoins" and "aprilFloor" or "tokenFloor" }
    end
    return { cost = tonumber(b.gem_cost) or 50, have = function() return C.cur("gems") end, name = "gems", floor = "gemFloor" }
end
-- Skip Summon Animations: the star reveal ends at once. Its callback fires a frame later, so the game's own reward code (auto-sell of units and skins and all) runs as before;
-- the windows the reveal opens after it (your collection) and the drop pop-ups stay shut. restore puts the game's own back (the farm unloading)
function HUB.quietFx(restore)
    local on = CFG.skipSummonFx and not restore
    -- (the game's own is kept on its table, not in this copy: a copy loaded over another must not take the skip for the original)
    local fx = C.svc("SummonFX")
    if fx and type(fx.open_star_new) == "function" then
        if rawget(fx, "__aaOrig") == nil then rawset(fx, "__aaOrig", fx.open_star_new) end
        fx.open_star_new = on and function(_, _, _, _, done) if type(done) == "function" then task.defer(done) end end or rawget(fx, "__aaOrig")
    end
    local drop = C.GUIS and C.GUIS.drop_obtained_ui
    if type(drop) == "table" then
        for _, name in ipairs({ "show_message", "show_message_custom" }) do
            rawset(drop, name, on and function() end or nil)
        end
    end
end
function HUB.summonText()
    local bc = CFG.summonBanner ~= "" and HUB.bannerCost(CFG.summonBanner)
    if not bc then return "Pick a banner. It stops at the line below, or when your unit storage is full." end
    return string.format("You have %s %s. 10 summons cost %s, and it keeps %s.%s", U.fmt(bc.have()), bc.name, U.fmt(bc.cost * 10), U.fmt(CFG[bc.floor]),
        ST.Summon and ("\n" .. tostring(ST.Summon)) or "")
end
function HUB.smartEvolve()
    if not CFG.smartEvolve then return SF.status("Evolve", "smart evolve is off (Goals tab)") end
    local s = C.session()
    if not s then return end
    local goals = {}
    for _, g in ipairs(B.goals or {}) do table.insert(goals, g) end
    table.sort(goals, function(a, b) return (a.gain or 0) > (b.gain or 0) end)
    local onTeam = {}
    for _, e in ipairs(UNIT.equipped()) do onTeam[e.uuid] = true end
    local reserved, done, notes = {}, 0, {}
    -- your Auto Evolve pick's items are spoken for
    for _, g in ipairs(goals) do
        if g.pinned then for _, it in ipairs(g.items or {}) do reserved[it.id] = (reserved[it.id] or 0) + it.amount end end
    end
    for _, g in ipairs(goals) do
        local why, evolved
        if g.ready and not g.pinned and done < 2 and (HUB.evoBlocked[g.uuid] or 0) < os.time() then
            if g.hidden and (g.tierRank or 0) < ADV.TIER_RANK.S then why = "its strength is unknown (the game hides its upgrades until it's in a match), so this one is your call" end
            for _, it in ipairs(why and {} or g.items or {}) do
                if ADV.have(it.id) - it.amount < (reserved[it.id] or 0) then
                    why = string.format("keeps %s for a bigger evolution", (C.Items[it.id] or {}).name or it.id)
                    break
                end
            end
            why = why or HUB.evoEats(g, onTeam)
            if not why then
                local ok, msg = HUB.evolve(g, "smart evolve: ready, stronger at full upgrade, uses only spare items" .. (#(g.eats or {}) > 0 and " and spare copies" or ""))
                if ok then
                    done, evolved = done + 1, true
                    table.insert(notes, "evolved " .. UNIT.name(g.from) .. " → " .. UNIT.name(g.to))
                else
                    HUB.evoBlocked[g.uuid] = os.time() + 3600
                    why = msg
                end
            end
            if why then table.insert(notes, UNIT.name(g.from) .. ": " .. why) end
        end
        -- a goal still waiting keeps its items for itself (one that just evolved already used them up)
        if not evolved then
            for _, it in ipairs(g.items or {}) do reserved[it.id] = (reserved[it.id] or 0) + it.amount end
        end
    end
    SF.status("Evolve", #notes > 0 and table.concat(notes, " · ") or "nothing ready to evolve")
end

-- ============================================================
--  TAKEDOWN TRAINING (Shinobi (Hood) → Storm needs 7,500 of its own takedowns: it earns them by fighting)
-- ============================================================
-- the game counts a takedown for every unit that hit an enemy that died (Windsong: 4,651 takedowns, 277 kills),
-- so the trainee only has to fight where enemies die. Only an evolution that joins your team is trained. It goes
-- into your team in place of your weakest unit that passes the checks (TRAIN.plan), only for a mode where
--   · the sim still wins with 30% tougher enemies (twice as tough where no real run has checked the sim yet, and
--     never where it doesn't match real runs),
--   · your farm wins it at least 80% of the time and it isn't a limited reward (the challenges),
--   · the clear is at most 40% slower than with your own team;
-- your own team goes back before every lobby decision, and a lost training run stops training there for 6 h
TRAIN.BONUS = 1.5 -- the trainee's buys count this much more (live and in the sim, so the sim checks the run with it)
TRAIN.SLOW = 1.4  -- at most this much slower than your own team
-- the trainee only earns takedowns while it's fighting: once 2 attackers are down and the defense isn't in danger
-- (ECON's danger line: enemies near the end of what your units cover), its first copy is the next buy; its other
-- copies (more of them = more enemies hit) once the defense is safe (live and in the sim alike, so the sim's
-- margin check covers it)
function TRAIN.boost(opts, attackers, pressure, cover)
    if attackers < 2 or pressure >= math.min(CFG.dangerReach, (cover or 1) * 0.9) then return end
    local safe = pressure < math.min(CFG.safeReach, (cover or 1) * 0.75)
    local best = 0
    for _, o in ipairs(opts) do if not o.farm and not o.train and o.cost > 0 then best = math.max(best, o.gain / o.cost) end end
    for _, o in ipairs(opts) do
        if o.train == "first" or (o.train == "more" and safe) then o.gain = math.max(o.gain, best * o.cost * 1.05) end
    end
end
-- Infinite training: a takedown needs a hit before the enemy dies, and a strong unit that kills everything as it
-- comes leaves the trainee nothing to hit (a run where Iron Sentinel reached level 9 by wave 11 one-shot every enemy
-- 37 studs out and Chuuni never attacked). So while enemies die in the first TRAIN.HOLD_REACH of the road, the other
-- attackers aren't upgraded or placed: enemies that live a little longer reach the trainee. There's no last wave to
-- lose, and the yen saved meanwhile is spent as soon as enemies get past that line
TRAIN.HOLD_REACH = 0.3
TRAIN.ZONE = 0.25 -- the share of the road (from where enemies come in) left to the trainee in Infinite (MT.bestSpot)
-- (once holding, it holds until enemies get 10% further, so it doesn't flip with every enemy)
function TRAIN.hold(pressure, attackers, holding)
    if attackers < 2 or pressure >= TRAIN.HOLD_REACH + (holding and 0.1 or 0) then return false end
    return true, string.format("holding your other units back so enemies reach the trainee (they die at %d%% of the road)", math.floor(pressure * 100 + 0.5))
end
function TRAIN.same(a, b)
    if #a ~= #b then return false end
    local set = {}
    for _, x in ipairs(a) do set[x] = true end
    for _, x in ipairs(b) do if not set[x] then return false end end
    return true
end
function TRAIN.team() local l = {}; for _, e in ipairs(UNIT.equipped()) do table.insert(l, e.uuid) end; return l end
-- the unit to train: a goal that joins your team once evolved — one that waits only on takedowns first, then the
-- higher tier rating (Chuuni SS before an unrated one), then the goal order. An evolution that stays weaker than
-- your team isn't worth a swap
function TRAIN.target()
    local s = C.session()
    if not s then return nil end
    local best, bestKey
    local pin = CFG.autoEvolve and CFG.evolveUnit ~= "" and CFG.evolveUnit or nil
    for i, g in ipairs(B.goals or {}) do
        local tp, other = nil, 0
        for _, p in ipairs(g.plans or {}) do if p.takedown then tp = p else other = other + 1 end end
        -- with an Auto Evolve pick, only that unit trains
        local u = tp and g.intoTeam and (g.pinned or not g.unknown) and (not pin or g.uuid == pin) and s.collection:get_unit_by_uuid(g.uuid)
        if u then
            local have = tonumber(tp.what == "kills" and u.total_kills or u.total_takedowns) or 0
            if have < tp.need then
                local key = (other == 0 and 1000 or 0) + (tonumber(g.tierRank) or 0) * 10 - i * 0.01
                if not best or key > bestKey then
                    best, bestKey = { uuid = g.uuid, id = g.from, to = g.to, what = tp.what, have = have, need = tp.need }, key
                end
            end
        end
    end
    return best
end
-- what a trainee really has: the game's own count. A run's count only sees the copies still on the field, so a copy sold or merged takes its takedowns with it (Elyssia was sold and placed again
-- for the boss: the log said 2283 of 2500 when the game said 2520, and the farm pressed Next past her evolution)
function TRAIN.realHave(on)
    local s = C.session()
    local u = s and s.collection:get_unit_by_uuid(on.uuid)
    local real = u and tonumber(on.what == "kills" and u.total_kills or u.total_takedowns) or 0
    return math.max(real, on.have + (on.got or 0))
end
-- the target and your own team's signature, looked up at most every 10 s (the ranking asks for every mode)
function TRAIN.now()
    if TRAIN._at and U.now() - TRAIN._at < 10 then return TRAIN._t, TRAIN._base end
    local base = (B.train.on and B.train.on.base) or TRAIN.team()
    local sorted = table.clone(base)
    table.sort(sorted)
    TRAIN._t, TRAIN._base, TRAIN._at = TRAIN.target(), table.concat(sorted, ","), U.now()
    return TRAIN._t, TRAIN._base
end
-- what a training run is worth on top of the mode's own reward: the trainee's takedowns as their share of the
-- goal's value (Goal Value, spread over the takedowns it still needs, like a goal's items), and how much slower
function TRAIN.valueFor(m)
    if not (CFG.trainTakedowns and CFG.goals) then return 0, 1 end
    local c = B.trainSim[m.key]
    if not (c and c.ok and os.time() - (c.at or 0) < 6 * 3600) then return 0, 1 end
    local t, baseSig = TRAIN.now()
    -- (or against your own team: the lobby checks with it, while on a results screen the base is the team the search picked for that run. No mode trained there, so a Challenge came out on top, the vote read "lobby for: Challenge", and the lobby launched a first clear. Nov 2)
    local own = {}
    for i, uuid in ipairs(B.savedTeam or {}) do own[i] = uuid end
    table.sort(own)
    if not (t and c.uuid == t.uuid and (c.base == baseSig or c.base == table.concat(own, ","))) or not TRAIN.eligible(m) then return 0, 1 end
    local per = TRAIN.perRun(m.key, t.id) or 0
    local left = math.max(1, t.need - t.have)
    return CFG.goalValue * math.min(per, left) / left, c.slow or 1
end
-- lobby planner (every 10 min): the training team checked in the best modes it may train in, so the ranking
-- knows what training there is worth (at most 2 new simulations a time)
function TRAIN.scan()
    local t = CFG.trainTakedowns and CFG.sim and TRAIN.now()
    if not t then return end
    local base = (B.train.on and B.train.on.base) or TRAIN.team()
    for _, uuid in ipairs(base) do if uuid == t.uuid then return end end
    local ok, fresh = 0, 0
    for _, m in ipairs(MODE.lastScored or {}) do
        if ok >= 3 or fresh >= 2 then break end
        if TRAIN.eligible(m) then
            local c = B.trainSim[m.key]
            local cached = c and c.uuid == t.uuid and os.time() - (c.at or 0) < 6 * 3600
            local p = TRAIN.plan(m, t, base)
            if not cached then fresh = fresh + 1 end
            if p.ok then ok = ok + 1 end
        end
    end
    -- (a mode only earns its training value after this check, and the check only went down the ranking from the top: Infinite, far down on its daily gems alone, got none after Oct 30, though it had paid 48 and 100 takedowns a minute against 7-78 on story maps. The user spotted it, Nov 1)
    local inf = TRAIN.bestInfinite()
    if inf then TRAIN.plan(inf, t, base) end
end
-- the Infinite map that trains fastest by real runs: takedowns a minute there (a map not played yet has no number to go by: a run there would count the takedowns of a full run against a guess of 25 minutes).
-- A map you haven't trained on goes by other players' trainees there (the brain hive), so the first try lands on the fast one
function TRAIN.bestInfinite()
    local best, top
    for _, m in ipairs(MODE.lastScored or {}) do
        if m.kind == "infinite" and TRAIN.eligible(m) then
            local r, rec = B.train.real[m.key], m.rec or MODE.rec(m.key)
            local mins = (tonumber(rec.timed) or 0) > 0 and rec.sec / rec.timed / 60 or 0
            local rate = (r and r.n > 0 and mins > 0) and (r.sum / r.n) / mins or 0
            if rate <= 0 then rate = REPORT.hiveTrainRate(m.key) or 0 end
            if rate > (top or 0) then best, top = m, rate end
        end
    end
    return best
end
-- takedowns a run in a mode: measured in real runs there, else the sim's count corrected by how real runs
-- elsewhere compared with it (the sim lets every unit hit for a while; in a real match your strongest unit
-- often kills before the trainee lands a hit)
function TRAIN.ratio()
    local c = B.train.cal
    if not (c and (c.n or 0) > 0 and (c.sim or 0) > 0) then return 1 end
    return U.clamp(c.real / c.sim, 0.05, 2)
end
-- (the sim's count is far off for a unit your strongest one out-kills: real runs got 36–268 where it said 0–6,
-- so real runs elsewhere come before it)
-- (an Infinite run lasts many times longer than a story run: each kind only goes by runs of its own kind)
-- (then the brain hive: other players' trainees there, 3 runs at least, the unit's own count when it has one: REPORT.hive)
function TRAIN.perRun(key, id)
    local r = B.train.real[key]
    if r and r.n > 0 then return r.sum / r.n, true end
    local h = REPORT.hiveTrain(key, id)
    if h then return h, true end
    local sum, n = 0, 0
    local inf = MODE.isInf(key)
    for k, x in pairs(B.train.real) do if MODE.isInf(k) == inf then sum, n = sum + x.sum, n + x.n end end
    if n > 0 then return sum / n, true end
    local c = B.trainSim[key]
    return c and c.tk and c.tk * TRAIN.ratio() or nil, false
end
function TRAIN.eligible(m)
    -- (a lost first clear can be played again, so it may train there: no real run there yet = the strict margin;
    -- Fool's Hunt pays per wave and can be replayed, so it may too)
    if m.kind == "daily" or m.kind == "challenge" then return false, "a limited reward, played with your own team" end
    if m.kind == "dungeon" then return false, "a lost dungeon room costs a life: played with your own team" end
    if C.Levels[m.level] and C.Levels[m.level]._randomequippedmode then return false, "this mode deals you a random team" end
    if (B.train.bad[m.key] or 0) > os.time() then return false, "a training run lost there, so not before " .. os.date("%H:%M", B.train.bad[m.key]) end
    local r = m.rec or MODE.rec(m.key)
    if r.runs >= 3 and r.wins / r.runs < 0.8 then return false, "your farm wins it less than 80% of the time" end
    local sr = B.simRes[m.key]
    if sr and sr.trust and not sr.trust.ok then return false, "the simulator doesn't match real runs there yet" end
    return true
end
-- the training team for a mode: the sim tries the trainee in place of each of your 3 weakest units (farm units
-- stay), weakest first; a swap must still win with 30% tougher enemies (twice as tough where no real run has
-- checked the sim yet). The weakest one that passes goes out, a stronger one only when that trains 1.5× faster
function TRAIN.plan(m, t, base)
    local s = C.session()
    local sorted = table.clone(base)
    table.sort(sorted)
    local baseSig = table.concat(sorted, ",")
    local calibrated = (tonumber((B.simCal[m.key] or {}).n) or 0) > 0
    local margin = calibrated and 1.3 or 2
    local sig = baseSig .. "+" .. t.uuid .. (calibrated and "#c" or "#n") .. "#r3" -- r3: weakest unit first, real takedowns over the sim's count
    local c = B.trainSim[m.key]
    if c and c.sig == sig and not c.pending and os.time() - (c.at or 0) < 6 * 3600 then return c end
    -- (pending until the check is done: one cut short by a teleport is checked again, not kept as a failed one)
    local res = { sig = sig, base = baseSig, uuid = t.uuid, at = os.time(), ok = false, margin = margin, pending = true }
    B.trainSim[m.key] = res
    local ld, ch = SIM.levelFor(m)
    if not ld then res.why, res.pending = "the simulator can't play this mode", nil; return res end
    local info = SIM.info(ld, m.key, ch, m.mod)
    local units = {}
    for _, uuid in ipairs(base) do local u = s.collection:get_unit_by_uuid(uuid); if u then table.insert(units, u) end end
    local trainee = s.collection:get_unit_by_uuid(t.uuid)
    if not trainee or #units == 0 then res.why, res.pending = "the unit wasn't found", nil; return res end
    local own = SIM.run(info, SIM.teamFrom(units, info.map), { hpMul = 1 })
    -- Infinite has no win: a swap passes when, against the same tougher enemies, it still reaches every daily
    -- milestone your own team reaches (and a longer run there is more takedowns, not a slower clear)
    local inf = info.infinite and SIM.unbound(ld)
    local ownTier = inf and MODE.infTier(SIM.run(info, SIM.teamFrom(units, info.map), { hpMul = margin }).wave) or nil
    local cands = {}
    for i, u in ipairs(units) do
        if not UNIT.isFarm(u.unit_id) then local okS, sc = pcall(UNIT.score, u, m.mod); table.insert(cands, { i = i, sc = okS and sc or 0 }) end
    end
    table.sort(cands, function(a, b) return a.sc < b.sc end)
    local best
    for k = 1, math.min(3, #cands) do
        local trial = table.clone(units)
        trial[cands[k].i] = trainee
        local team = SIM.teamFrom(trial, info.map)
        local hard = SIM.run(info, team, { hpMul = margin, train = t.uuid })
        if (inf and MODE.infTier(hard.wave) >= ownTier) or (not inf and hard.won) then
            local r = SIM.run(info, team, { hpMul = 1, train = t.uuid })
            local rate = (r.tk or 0) / math.max(0.5, r.t / 60)
            if (r.won or inf) and (not best or rate > math.max(best.rate * 1.5, best.rate + 1)) then best = { out = units[cands[k].i].unit_id, r = r, rate = rate, trial = trial } end
        end
    end
    res.ownMin = own.t / 60
    if not best then
        res.why = inf and string.format("every swap loses a daily milestone (wave %d) against %s enemies in the simulator", ownTier, calibrated and "30% tougher" or "twice as tough")
            or calibrated and "no swap still wins with 30% tougher enemies in the simulator"
            or "no swap still wins against twice as tough enemies in the simulator (no real run there yet)"
    else
        res.out, res.tk, res.minutes = best.out, best.r.tk or 0, best.r.t / 60
        res.uuids = {}
        for _, u in ipairs(best.trial) do table.insert(res.uuids, u.uuid) end
        res.slow = (own.won and not inf) and res.minutes / math.max(0.1, res.ownMin) or 1
        if res.tk <= 0 and next(B.train.real) == nil then res.why = "the simulator says it would hit nothing there"
        elseif res.slow > TRAIN.SLOW then res.why = string.format("the clear would be %d%% slower", math.floor((res.slow - 1) * 100 + 0.5))
        else res.ok = true end
    end
    res.pending = nil
    SF.log(1, "TRAIN", string.format("%s: %s%s → %s", m.label, UNIT.name(t.id), res.out and (" in for " .. UNIT.name(res.out)) or "",
        res.ok and string.format("trains here (≈%d %s a run, %.1f min vs %.1f with your team)", math.floor((TRAIN.perRun(m.key, t.id) or 0) + 0.5), t.what, res.minutes, res.ownMin) or tostring(res.why)))
    SF.saveSoon()
    return res
end
-- your own team back (before every lobby decision, so the ranking and the sim see your real team)
function TRAIN.home()
    local on = B.train.on
    if not on then return end
    B.train.on = nil
    SF.saveSoon()
    if not TRAIN.same(TRAIN.team(), on.uuids or {}) then
        SF.log(1, "TRAIN", "your team was changed outside the farm, so it stays as it is")
        if not CFG.autoTeam then B.savedTeam = nil end
        return
    end
    if B.savedTeam and TRAIN.same(B.savedTeam, on.base) then HUB.restoreTeam() else HUB.equipTeam(on.base, "back from takedown training") end
    SF.log(1, "TRAIN", UNIT.name(on.out or "?") .. " is back in your team")
end
-- right before a launch: the training team when this mode qualifies, else your own team
function TRAIN.apply(m)
    local t = CFG.trainTakedowns and TRAIN.target() or nil
    if not t then
        TRAIN.home()
        return SF.status("Training", CFG.trainTakedowns and "no evolution is waiting on takedowns" or "off (Goals tab)")
    end
    local name = UNIT.name(t.id)
    local prog = string.format("%s %s/%s", t.what, U.fmt(t.have), U.fmt(t.need))
    local on = B.train.on
    local base = on and on.base or TRAIN.team()
    for _, uuid in ipairs(base) do
        if uuid == t.uuid then return SF.status("Training", string.format("%s is on your team (%s)", name, prog)) end
    end
    local ok, why = TRAIN.eligible(m)
    local p
    if ok then
        SF.status("Training", string.format("checking %s in %s with the simulator…", name, m.label))
        p = TRAIN.plan(m, t, base)
        ok, why = p.ok, p.why
    end
    if not ok then
        TRAIN.home()
        return SF.status("Training", string.format("%s · %s · not in %s: %s", name, prog, m.label, tostring(why)))
    end
    if not (on and TRAIN.same(TRAIN.team(), p.uuids)) then
        HUB.equipTeam(p.uuids, string.format("takedown training: %s in for %s (%s)", name, UNIT.name(p.out), m.label))
        local t0 = U.now()
        while U.now() - t0 < 4 and not TRAIN.same(TRAIN.team(), p.uuids) do task.wait(0.25) end
        if not TRAIN.same(TRAIN.team(), p.uuids) then
            -- the game didn't take the swap: your own team back, and no training in this mode for an hour
            if B.savedTeam and TRAIN.same(B.savedTeam, base) then HUB.restoreTeam() else HUB.equipTeam(base, "takedown training swap didn't work") end
            B.train.bad[m.key] = os.time() + 3600
            SF.log(1, "TRAIN", "the game didn't take the training team for " .. m.label .. ": your own team is back")
            return SF.status("Training", name .. ": the swap didn't work, trying again in an hour")
        end
        B.train.on = { uuid = t.uuid, id = t.id, to = t.to, what = t.what, have = t.have, need = t.need, got = 0,
            base = base, uuids = p.uuids, out = p.out, key = m.key, at = os.time() }
        SF.log(1, "TRAIN", string.format("%s in for %s for %s (%s)", name, UNIT.name(p.out), m.label, prog))
    end
    B.train.on.key = m.key
    local per, real = TRAIN.perRun(m.key, t.id)
    SF.status("Training", string.format("%s in for %s in %s · %s · ≈%d a run%s", name, UNIT.name(p.out), m.label, prog, math.floor((per or 0) + 0.5), real and "" or " (simulated)"))
end
-- the Path tab's training paragraph
function TRAIN.text()
    if not CFG.trainTakedowns then return "Off. A unit whose evolution needs takedowns only earns them while you keep it on your team." end
    local t = TRAIN.target()
    if not t then return "No evolution that would join your team is waiting on takedowns." end
    local sum, n = 0, 0
    for _, r in pairs(B.train.real) do sum = sum + r.sum; n = n + r.n end
    local avg = n > 0 and sum / n or nil
    local runs = {}
    for _, x in ipairs(B.train.log) do
        if #runs < 5 then table.insert(runs, string.format("+%d (%s, %s)", x.got, GUI.keyName and GUI.keyName(x.key) or x.key, x.won and "won" or "lost")) end
    end
    return string.format("%s needs %s %s for %s and has %s.%s%s\n"
        .. "It joins your team only where the simulator says you still win with 30%% tougher enemies (twice as tough where the farm has no real run yet), in place of your weakest unit that passes that test (a stronger one of your 3 weakest only if it trains 1.5× faster). "
        .. "Never in the challenges, where your farm wins under 80%% of runs, or where clearing gets more than 40%% slower. "
        .. "Its progress counts in the mode ranking (Goal Value, spread over the takedowns it still needs). "
        .. "Your own team goes back after every run, and a lost run stops training in that mode for 6 hours.",
        UNIT.name(t.id), U.fmt(t.need), t.what, UNIT.name(t.to), U.fmt(t.have),
        avg and string.format(" It gets about %d a run, so ≈%d more runs.", math.floor(avg + 0.5), math.ceil((t.need - t.have) / math.max(1, avg))) or "",
        #runs > 0 and (" Last runs: " .. table.concat(runs, " · ") .. ".") or "")
end
function HUB.every(name, sec)
    local t = U.now()
    if HUB.last[name] and t - HUB.last[name] < sec then return false end
    HUB.last[name] = t
    return true
end
-- lobby-only info the match also needs (challenge rotation, daily challenge, event) is cached in the brain
function HUB.refreshLive()
    local live = B.live
    local ok, n = SF.request("live_n", "get_normal_challenge")
    if ok and type(n) == "table" and n.current_uuid then
        local prevLost = (live.normal and live.normal.uuid == n.current_uuid) and live.normal.lost or 0
        local prevDoneN = (live.normal and live.normal.uuid == n.current_uuid) and live.normal.doneUuid or nil
        local remaining = C.GS.CHALLENGE_DURATION or 1800
        -- the rotation is every 30 min on the clock (the pads show the time left)
        local ends = (math.floor(os.time() / remaining) + 1) * remaining
        live.normal = { uuid = n.current_uuid, level = n.current_level_id, challenge = n.current_challenge,
            value = MODE.rewardValue(n.current_reward), expires = ends, lost = prevLost, doneUuid = prevDoneN }
    end
    local ok2, d = SF.request("live_d", "get_daily_challenge")
    if ok2 and type(d) == "table" and d.current_uuid then
        local mod = { weak = {}, strong = {} }
        for _, t in pairs(d.weak_against or {}) do mod.weak[t] = 1.5 end
        for _, t in pairs(d.strong_against or {}) do mod.strong[t] = true end
        local prevLost = (live.daily and live.daily.uuid == d.current_uuid) and live.daily.lost or 0
        local prevDone = (live.daily and live.daily.uuid == d.current_uuid) and live.daily.doneUuid or nil
        local dld = type(d.current_level) == "table" and SIM.slim(d.current_level) or nil
        if dld then dld._challenge = d.current_challenge end
        live.daily = { uuid = d.current_uuid, value = MODE.rewardValue(d.current_reward), challenge = d.current_challenge, mod = mod, lost = prevLost, doneUuid = prevDone, ld = dld }
    end
    local ok3, e = SF.request("live_e", "get_event_challenges")
    if ok3 and type(e) == "table" then
        -- (an event that ended goes from the ranking too: a saved one would keep ranking a pad that's gone)
        live.event = nil
        for id, v in pairs(e) do
            local lv = type(v) == "table" and v.current_level_data
            if type(lv) == "string" then lv = C.Levels[lv] end
            if lv then
                local slim = SIM.slim(lv)
                slim._difficulty = slim._difficulty or "Hard"
                live.event = { level = lv.id or id, name = lv.name, pad = C.GS.ACTIVE_EVENT_CHALLENGES and C.GS.ACTIVE_EVENT_CHALLENGES[id], board = id, map = lv.map, weather = v.current_weather, ld = slim,
                    forecast = type(v.forecast) == "table" and { map = v.forecast.map, weather = v.forecast.weather, map_hint = v.forecast.map_hint, weather_hint = v.forecast.weather_hint } or nil }
            end
        end
    end
    live.at = os.time()
    SF.saveSoon()
end

-- free rewards: daily login, finished quests, battle pass, first-clear milestones
function HUB.rewards()
    if not CFG.rewards then return SF.status("Rewards", "off") end
    local s = C.session()
    local p = C.prof()
    if not (s and p) then return end
    local got = {}
    if (os.time() - (tonumber(p.last_daily_reward_claimed_time) or 0)) >= (C.GS.DAILY_REWARD_WAIT or 82800) then
        local ok, r = SF.request("daily", "claim_daily_reward")
        if ok and r then table.insert(got, "daily login") end
    end
    for uuid, q in pairs(s.quest_handler.quest_profile_data.quests or {}) do
        local okC, done = pcall(C.QCC.is_quest_complete, s, q)
        if okC and done and not B.claims[uuid] then
            local ok, r = SF.request("quest", "redeem_quest", uuid)
            if ok and r then
                B.claims[uuid] = os.time()
                table.insert(got, "quest " .. tostring(q.quest_info and (q.quest_info.name or q.quest_info.id) or ""))
            else
                B.claims[uuid] = os.time() - 259200 + 3600 -- not claimable right now: try again in an hour
            end
            task.wait(0.3)
        end
    end
    if HUB.every("bp", 600) then SF.request("bp", "claim_battlepass_rewards") end
    if HUB.every("bingo", 120) then pcall(HUNT.claim) end
    -- first-clear milestones (Levels[id].clear_rewards[diff] = {clears, _id})
    if HUB.every("clr", 300) then
        for id, d in pairs(p.level_data.completed_story_levels or {}) do
            local lv = C.Levels[id]
            if lv and lv.clear_rewards and d.difficulty_completed_data then
                for diff, list in pairs(lv.clear_rewards) do
                    local n = d.difficulty_completed_data[diff] and d.difficulty_completed_data[diff].times_completed or 0
                    for _, rw in pairs(list) do
                        local claimed = p.clear_rewards[id] and p.clear_rewards[id][diff] and p.clear_rewards[id][diff][rw._id]
                        local ck = id .. diff .. tostring(rw._id)
                        if not claimed and n >= (rw.clears or 1e9) and not B.claims[ck] then
                            local ok, r = SF.request("clr", "claim_first_clear_rewards", id, diff, rw._id)
                            B.claims[ck] = os.time()
                            if ok and r then table.insert(got, "milestone " .. MODE.levelName(id)) end
                        end
                    end
                end
            end
        end
    end
    -- forget claim marks older than 3 days (quest uuids are not reused)
    for k, t in pairs(B.claims) do if os.time() - t > 259200 then B.claims[k] = nil end end
    if #got > 0 then SF.log(1, "REWARD", "claimed " .. table.concat(got, ", ")) end
    SF.status("Rewards", #got > 0 and ("claimed " .. table.concat(got, ", ")) or "nothing waiting")
end

-- spend: Star Fruits from the daily gold shop with spare gold (floor, item cap, stock)
function HUB.goldShop()
    if not CFG.goldShop then return SF.status("Gold Shop", "off") end
    B.str.shopAt = os.time()
    local p = C.prof()
    local s = C.session()
    if not (p and s) then return end
    local ok, shop = SF.request("gshop", "request_current_gold_shop")
    if not (ok and type(shop) == "table") then return SF.status("Gold Shop", "shop not answering") end
    local bought = 0
    -- what's left of an item = its stock minus what you already bought this rotation (like the shop window shows)
    local done = (type(p.gold_shop_data) == "table" and type(p.gold_shop_data.bought_items) == "table") and p.gold_shop_data.bought_items or {}
    local function left(key, it)
        if it.stock == "inf" then return math.huge end
        return math.max(0, (tonumber(it.stock) or 0) - (tonumber(done[key]) or 0))
    end
    for key, it in pairs(shop) do
        if type(it) == "table" and tostring(it.id or key):find("^StarFruit") and left(key, it) > 0 then
            local cap = C.GS.ITEM_CAPS and C.GS.ITEM_CAPS[it.id] or 1e9
            local have = 0
            pcall(function() have = s.inventory:get_number_of_owned_item(it.id) end)
            local cost = tonumber(it.gold_cost) or 1e12
            local stock = left(key, it)
            while stock > 0 and have < cap and (tonumber(p.gold_amount) or 0) - cost >= CFG.goldFloor and bought < 10 do
                local before = tonumber(p.gold_amount) or 0
                local buyAt = U.now()
                local okB, r = SF.request("gbuy", "buy_gold_shop_item", key, "1")
                local t1 = U.now()
                while U.now() - t1 < 3 and (tonumber(p.gold_amount) or 0) >= before do task.wait(0.2) end
                if not okB or (tonumber(p.gold_amount) or 0) >= before then
                    SF.log(1, "SHOP", "gold shop refused " .. tostring(key) .. " (" .. tostring(SF.gameSaid(buyAt) or r) .. ")")
                    SF.backoff("gbuy", 600)
                    break
                end
                bought = bought + 1
                stock = stock - 1
                have = have + 1
                SPEND.add((C.Items[it.id] and C.Items[it.id].name or it.id), cost, "gold", string.format("evolve material, %d/%d held · gold floor %s", have, cap, U.fmt(CFG.goldFloor)))
            end
        end
    end
    -- XP food for the Team tab: the most XP per gold first, while gold stays above the floor and your core units can still take it
    local food, foodXp = 0, 0
    if CFG.team and CFG.teamXp and CFG.teamBuyXp then
        -- (each food is locked until its world is reached, like the shop's grey overlay: GoldShopUI._on_make_item_frame; the server refuses a locked one)
        local PSC, WLO
        pcall(function() PSC = C.core("ProgressionServiceCore"); WLO = C.data("WorldLevelOrder") end)
        local function unlocked(id)
            local order = C.LU and type(C.LU.xp_items_order) == "table" and C.LU.xp_items_order[id]
            local world = order and WLO and type(WLO.WORLD_ORDER) == "table" and WLO.WORLD_ORDER[order]
            if not (world and PSC and PSC.check_if_unlocked_story_world) then return true end
            local okU, r = pcall(PSC.check_if_unlocked_story_world, C.session(), world)
            return okU and r == true
        end
        local offers, lockedN = {}, 0
        for key, it in pairs(shop) do
            local d = type(it) == "table" and C.Items[it.id or key]
            -- (3 XP a gold at least: the 3,450-XP food gives 14, and the bottom of the shop as little as half an XP a gold)
            if d and type(d.usage) == "table" and d.usage.type == "xp_feed" and left(key, it) > 0 and tonumber(it.gold_cost) and (tonumber(d.usage.xp_amount) or 0) / math.max(1, tonumber(it.gold_cost)) >= 3 then
                if unlocked(it.id or key) then
                    table.insert(offers, { key = key, id = it.id or key, it = it, xp = tonumber(d.usage.xp_amount) or 0, cost = tonumber(it.gold_cost) })
                else
                    lockedN = lockedN + 1
                end
            end
        end
        table.sort(offers, function(a, b) return a.xp / a.cost > b.xp / b.cost end)
        local room = STR.xpRoom()
        for _, f in ipairs(STR.foodHeld()) do room = room - f.n * f.xp end
        if CFG.strDry then
            -- (dry run: what it would buy, once per rotation)
            local would, gold, n = {}, tonumber(p.gold_amount) or 0, 0
            for _, o in ipairs(offers) do
                local lots = math.min(left(o.key, o.it), math.floor(math.max(0, gold - CFG.xpGoldFloor) / o.cost), o.xp > 0 and math.floor(room / o.xp) or 0)
                if lots > 0 then table.insert(would, string.format("%d %s", lots, (C.Items[o.id] or {}).name or o.id)); gold, room, n = gold - lots * o.cost, room - lots * o.xp, n + lots end
            end
            local line = (n > 0 and string.format("dry run: would buy %s for %s gold", table.concat(would, ", "), U.fmt((tonumber(p.gold_amount) or 0) - gold)) or "dry run: no XP food worth buying (your core units are full, or gold is at the line)")
                .. (lockedN > 0 and string.format(" · %d kinds locked behind later worlds", lockedN) or "")
            if B.str.dryShop ~= line then B.str.dryShop = line; SF.log(1, STR.LOG, line) end
        else
            local refused
            -- (gold is read live, C.cur: the profile's copy can lag behind a purchase)
            local function gold() return tonumber(C.cur("gold")) or tonumber(p.gold_amount) or 0 end
            for _, o in ipairs(offers) do
                if refused then break end
                local stock = left(o.key, o.it)
                while stock > 0 and room > 0 and o.xp > 0 and gold() - o.cost >= CFG.xpGoldFloor and food < 80 do
                    local lot = (stock >= 10 and gold() - o.cost * 10 >= CFG.xpGoldFloor and room >= o.xp * 10) and 10 or 1
                    local before, had = gold(), ADV.have(o.id)
                    -- (its own key: a refused Star Fruit just above backed off the shared one, and the 3,450-XP food never got asked for)
                    local buyAt = U.now()
                    local okB, r = SF.request("xpbuy", "buy_gold_shop_item", o.key, tostring(lot))
                    -- (the farm's own pacing, not a refusal: a moment, then the rest of the food)
                    if not okB and (r == "slowing down" or r == "waiting") then task.wait(3.5); continue end
                    local t1 = U.now()
                    while U.now() - t1 < 3 and gold() >= before and ADV.have(o.id) <= had do task.wait(0.2) end
                    if not okB or (gold() >= before and ADV.have(o.id) <= had) then
                        -- (one refusal ends the pass: the shop answers the same to the rest, and it tries again next time)
                        SF.log(1, "SHOP", "gold shop refused " .. tostring(o.key) .. " ×" .. lot .. " (" .. tostring(SF.gameSaid(buyAt) or r) .. "): XP food waits for the next pass")
                        SF.backoff("xpbuy", 600)
                        refused = true
                        break
                    end
                    food, stock, room, foodXp = food + lot, stock - lot, room - o.xp * lot, foodXp + o.xp * lot
                    SPEND.add((C.Items[o.id] or {}).name or o.id, o.cost * lot, "gold", string.format("XP food for your team: %s XP · gold kept %s", U.fmt(o.xp * lot), U.fmt(CFG.xpGoldFloor)))
                end
            end
            if food > 0 then SF.log(1, STR.LOG, string.format("bought %d XP food (%s XP) in the gold shop · gold %s", food, U.fmt(foodXp), U.fmt(p.gold_amount))) end
        end
    end
    SF.status("Gold Shop", (bought > 0 or food > 0) and string.format("bought %d Star Fruit(s), %d XP food", bought, food) or string.format("nothing to buy (gold %s, floor %s)", U.fmt(p.gold_amount), U.fmt(CFG.goldFloor)))
end

-- spend: summons — only while the banner can give a unit you don't have (April) or one that beats your team (gems)
-- Banner Snipe (the user's call, Nov 2, in place of the Griffin watch): your pick of any unit a banner can feature. Each lobby visit reads every banner's featured units; while one features
-- your pick, it's pulled 10 at a time on that banner until it (or a form it evolves into) drops, that banner's currency reaches your Keep line, or unit storage is nearly full. A match can't
-- read banners (the game answers nil there), but the rotating ones turn over on a clock (every 4 h) and the game says so: a results screen after a turnover goes through the lobby to look (STR.hasWork)
HUB.SNIPE_KEEP = { gems = "snipeGemFloor", SummerPearls = "snipePearlFloor", GemsLegacy = "snipeLegacyFloor" }
HUB.SNIPE_ALSO = { griffith = { "griffith_reincarnation" } } -- forms reached some other way than an evolve (Griffin's Ascension)
-- a unit and every form it evolves into
function HUB.snipeForms(id)
    local out, seen = {}, {}
    while id and C.Units[id] and not seen[id] do
        seen[id] = true
        table.insert(out, id)
        local ev = C.Units[id].evolve
        id = type(ev) == "table" and ev.evolve_unit or nil
    end
    for _, f in ipairs(HUB.SNIPE_ALSO[out[1]] or {}) do table.insert(out, f) end
    return out
end
function HUB.snipeHas(id)
    id = id or CFG.snipeUnit
    if not id or id == "" then return false end
    for _, f in ipairs(HUB.snipeForms(id)) do if HUB.hatched[f] or UNIT.owns(f) then return true end end
    return false
end
-- a banner's price, and the Keep line for its currency (Banner Snipe's own for gems, pearls and Legacy Gems)
function HUB.snipeCost(bid)
    local bc = HUB.bannerCost(bid)
    local b = C.Banners[bid]
    if not (bc and b) then return nil end
    bc.cur = (b.item_cost and b.item_cost.item_id) or (b.resource_cost and b.resource_cost.id) or "gems"
    bc.keep = tonumber(CFG[HUB.SNIPE_KEEP[bc.cur] or bc.floor]) or 0
    bc.label = HUB.BANNER_NAME[bid] or bid
    return bc
end
-- (the same 10 free slots as Auto Summon: a full collection refuses every pad)
function HUB.watchRoom()
    local p = C.prof()
    local n = 0
    for _ in pairs(p.collection.owned_units) do n = n + 1 end
    return n + 20 <= (tonumber(p.collection.capacity) or math.huge)
end
-- in the log, as a notice, and on the Lobby tab
function HUB.snipeSay(msg, kind)
    B.snipe.note, B.snipe.noteAt = msg, os.time()
    SF.log(1, "SUMMON", "Banner Snipe: " .. msg)
    if SF.notify then SF.notify("Banner Snipe", msg, kind or "success") end
    SF.saveSoon()
end
-- when the rotating banners next turn over after time t: by the game's own countdown once it has said (B.snipe.clock), else on the 4-hour marks
function HUB.snipeRate()
    local r
    for _, b in pairs(C.Banners or {}) do
        if type(b) == "table" and b.active and not b._does_not_rotate and tonumber(b.HATCH_REFRESH_RATE) then r = math.min(r or math.huge, tonumber(b.HATCH_REFRESH_RATE)) end
    end
    return r or 14400
end
function HUB.snipeTurnAfter(t)
    local rate = HUB.snipeRate()
    local ck = B.snipe.clock
    local phase = (ck and tonumber(ck.next) or 0) % rate
    return math.floor((t - phase) / rate + 1) * rate + phase
end
-- the last look is out of date: a turnover since, or the game said a banner changed
function HUB.snipeStale()
    local S = B.snipe
    if not S.lookAt then return true end
    return os.time() >= HUB.snipeTurnAfter(S.lookAt) or (tonumber(S.changedAt) or 0) > S.lookAt
end
-- what the game says about banners, in the lobby and in a match (SF.listenGame): its countdown, and "a banner changed"
function HUB.snipeHeard(name, ...)
    local S = B.snipe
    local args = table.pack(...)
    local function text()
        local t = {}
        for i = 1, math.min(args.n, 4) do
            local a = args[i]
            if type(a) == "table" then
                local ks = {}
                for k in pairs(a) do if #ks < 8 then table.insert(ks, tostring(k)) end end
                table.insert(t, "{" .. table.concat(ks, ",") .. "}")
            else
                table.insert(t, tostring(a):sub(1, 40))
            end
        end
        return table.concat(t, ", ")
    end
    -- (the countdown is the game's hourly refresh, GameplaySettings' 3600, not the rotating banners' 4 hours: it set the turnover to :59 on odd hours, Nov 2. Logged once, not used.
    -- "A banner changed" came only at the real turnover, 10:59:57, and its time sets the clock below)
    if name == "hatch_refresh_remaining_time_changed" then
        if not S.clockSeen then S.clockSeen = true; SF.log(1, "SUMMON", "Banner Snipe: the game's hourly countdown says " .. text()) end
        return
    end
    S.clock = { next = math.floor((os.time() + 30) / 60) * 60 + HUB.snipeRate(), at = os.time(), src = "changed" }
    -- (it came at 10:59:57 on Nov 2 with every banner in a table, {Legacy, Summer2026, EventClover}, and the hour count, 498232 × 3600 = 11:00. If those carry each banner's featured
    -- units, that's a look without the lobby, in a match too; otherwise the lobby looks)
    local feat, shape = {}, nil
    for i = 1, args.n do
        if type(args[i]) == "table" then
            for bid, b in pairs(args[i]) do
                if type(b) == "table" and C.Banners[bid] then
                    if not shape then
                        local ks = {}
                        for k, v in pairs(b) do if #ks < 10 then table.insert(ks, tostring(k) .. ":" .. type(v)) end end
                        shape = tostring(bid) .. " {" .. table.concat(ks, ",") .. "}"
                    end
                    local list = type(b.rateup_units) == "table" and b.rateup_units or nil
                    if list then
                        local ids = {}
                        for _, id in pairs(list) do if type(id) == "string" and C.Units[id] then table.insert(ids, id) end end
                        table.sort(ids)
                        if #ids > 0 then feat[bid] = ids end
                    end
                end
            end
        end
    end
    if next(feat) then
        for bid, ids in pairs(S.feat or {}) do if not feat[bid] then feat[bid] = ids end end
        S.feat, S.lookAt, S.changedAt = feat, os.time(), os.time()
        local parts = {}
        for bid, ids in pairs(feat) do
            local names = {}
            for _, id in ipairs(ids) do table.insert(names, UNIT.name(id)); S.seen[id] = { banner = bid, at = os.time() } end
            table.insert(parts, (HUB.BANNER_NAME[bid] or bid) .. ": " .. table.concat(names, ", "))
        end
        table.sort(parts)
        SF.log(1, "SUMMON", "Banner Snipe: the banners changed: " .. table.concat(parts, " · "))
        local bid = CFG.snipeOn and CFG.snipeUnit ~= "" and not HUB.snipeHas() and HUB.snipeWhere(CFG.snipeUnit)
        if bid and S.featured ~= bid then S.featured = bid; HUB.snipeSay(string.format("%s is featured on %s right now%s", UNIT.name(CFG.snipeUnit), HUB.BANNER_NAME[bid] or bid, SF.where == "match" and ": the lobby pulls after this match" or "")) end
    else
        S.changedAt = os.time()
        SF.log(1, "SUMMON", "Banner Snipe: the game says a banner changed (" .. text() .. (shape and ("; " .. shape) or "") .. ")" .. (SF.where == "match" and ": the lobby looks after this match" or ""))
    end
    HUB.last.snipe = nil
    SF.saveSoon()
end
-- every banner's featured units, from the lobby (nil when the game doesn't answer: in a match it never does)
function HUB.snipeLook()
    local S = B.snipe
    local ok, setup = SF.request("hatch", "get_hatch_setup_data")
    if not (ok and type(setup) == "table") then return nil end
    local feat, keys = {}, {}
    for bid, b in pairs(setup) do
        if type(b) == "table" then
            for k in pairs(b) do keys[tostring(k)] = true end
            if type(b.rateup_units) == "table" and C.Banners[bid] then
                local ids = {}
                for _, id in pairs(b.rateup_units) do if type(id) == "string" and C.Units[id] then table.insert(ids, id) end end
                table.sort(ids)
                feat[bid] = ids
                for _, id in ipairs(ids) do S.seen[id] = { banner = bid, at = os.time() } end
            end
        end
    end
    -- (once: what else a banner carries, in case one is a countdown)
    if not S.keysSeen then
        local list = {}
        for k in pairs(keys) do table.insert(list, k) end
        table.sort(list)
        S.keysSeen = true
        SF.log(1, "SUMMON", "Banner Snipe: a banner from the game carries " .. table.concat(list, ", "))
    end
    S.feat, S.lookAt = feat, os.time()
    return feat
end
-- the banner featuring a unit at the last look, the cheapest to pull on first: Legacy Gems, then event currencies, gems last
function HUB.snipeWhere(id)
    local best, bestK
    for bid, ids in pairs(B.snipe.feat or {}) do
        local b = C.Banners[bid]
        if b and b.active and table.find(ids, id) then
            local bc = HUB.snipeCost(bid)
            local k = not bc and 9 or bc.cur == "GemsLegacy" and 1 or bc.cur == "gems" and 3 or 2
            if not bestK or k < bestK then best, bestK = bid, k end
        end
    end
    return best
end
function HUB.bannerSnipe()
    if not (CFG.snipeOn and CFG.snipeUnit ~= "") then return end
    local S = B.snipe
    local id = CFG.snipeUnit
    local name = UNIT.name(id)
    if S.unit ~= id then S.unit, S.pulls, S.got, S.featured, S.note, S.saidAt = id, 0, nil, nil, nil, nil end
    -- the Celestial Compass picks your next Special banner Mythic from its own list: is your pick on it? A look once per pick, and the pick stays yours
    if ADV.have("celestial_compass_u21") > 0 and not (S.compass and S.compass.unit == id) then
        local okC, ids = SF.request("hatch", "get_celestial_compass_units", "celestial_compass_u21")
        if okC and type(ids) == "table" then
            local on, n = false, 0
            for _, x in pairs(ids) do
                n = n + 1
                if x == id then on = true end
            end
            S.compass = { unit = id, at = os.time(), n = n, on = on }
            SF.log(1, "SUMMON", string.format("Celestial Compass: it can pick %d units, %s", n, on and (name .. " among them") or ("not " .. name)))
            if on then HUB.snipeSay("your Celestial Compass can pick " .. name .. ". It's still in your bag: that pick is yours to make") end
        end
    end
    if HUB.snipeHas(id) then
        if not S.got then
            S.got = os.time()
            HUB.snipeSay("you have " .. name .. "!")
        end
        return
    end
    if not HUB.snipeLook() then return end
    local bid = HUB.snipeWhere(id)
    if not bid then
        if S.featured then HUB.snipeSay(string.format("%s isn't featured any more. It waits for the next turnover (%s)", name, os.date("%H:%M", HUB.snipeTurnAfter(os.time()))), "warning") end
        S.featured = nil
        return
    end
    local bc = HUB.snipeCost(bid)
    if not bc then return end
    if S.featured ~= bid then
        S.featured = bid
        HUB.snipeSay(string.format("%s is featured on %s right now", name, bc.label))
    end
    -- (only this banner's currency may go down: if any other does, the snipe switches itself off)
    local others = {}
    for _, cur in ipairs({ "gems", "GemsLegacy", "SummerPearls" }) do if cur ~= bc.cur then others[cur] = tonumber(C.cur(cur)) or 0 end end
    local n, slow = 0, 0
    while SF.alive and CFG.snipeOn and CFG.snipeUnit == id and bc.have() - bc.cost * 10 >= bc.keep and HUB.watchRoom() and not HUB.snipeHas(id) do
        local before, askedAt = bc.have(), U.now()
        local ok, r = SF.request("snipe", "buy_from_banner", bid, "gems10")
        -- (the farm's own pacing, not the game's answer: a moment, then on)
        if not ok and (r == "slowing down" or r == "waiting") and slow < 3 then slow = slow + 1; task.wait(3.5); continue end
        local t1 = U.now()
        while U.now() - t1 < 4 and bc.have() >= before do task.wait(0.25) end
        for cur, v in pairs(others) do
            if (tonumber(C.cur(cur)) or 0) < v then
                CFG.snipeOn = false
                pcall(function() GUI.UI.snipeOn.Set(false, true) end)
                SF.saveSoon()
                return HUB.snipeSay(string.format("%s went down during a pull on %s, so Banner Snipe switched itself off", cur == "gems" and "Gems" or cur, bc.label), "warning")
            end
        end
        if bc.have() >= before then
            local said = SF.gameSaid(askedAt) or r
            -- (the game refuses a pull that comes a few seconds after the last one: a moment, then on)
            if tostring(said):lower():find("too fast") and slow < 3 then slow = slow + 1; task.wait(6); continue end
            SF.log(1, "SUMMON", "Banner Snipe: " .. bc.label .. " refused (" .. tostring(said) .. ")")
            SF.backoff("snipe", 600)
            break
        end
        slow = 0
        n = n + 10
        S.pulls = (tonumber(S.pulls) or 0) + 10
        SPEND.add("10 summons on " .. bc.label, before - bc.have(), bc.name, "Banner Snipe: " .. name .. " is featured")
        -- (the game says what dropped just after the pull, and refuses the next one if it comes too soon)
        task.wait(5)
    end
    -- (a stop is told once per turnover, not on every lobby visit)
    local turn = HUB.snipeTurnAfter(os.time())
    if HUB.snipeHas(id) then
        S.got = os.time()
        HUB.snipeSay(string.format("you have %s! It dropped after %d pulls", name, tonumber(S.pulls) or 0))
    elseif S.saidAt ~= turn and not HUB.watchRoom() then
        S.saidAt = turn
        HUB.snipeSay(name .. " is featured, but your unit storage is nearly full. Sell some units and it carries on", "warning")
    elseif S.saidAt ~= turn and bc.have() - bc.cost * 10 < bc.keep then
        S.saidAt = turn
        HUB.snipeSay(string.format("%s is featured, but %s is at your Keep line (%s, keeping %s) after %d pulls", name, bc.name, U.fmt(bc.have()), U.fmt(bc.keep), tonumber(S.pulls) or 0), "warning")
    end
end
-- a results screen: your pick is featured and there's something to pull with, so the run stops at the lobby instead of pressing Next past it
function HUB.snipeWanted()
    if not (CFG.snipeOn and CFG.snipeUnit ~= "") or HUB.snipeHas() or HUB.snipeStale() then return false end
    -- (a refused pull waits 10 min: results screens don't keep going to the lobby for it meanwhile)
    if SF.req.back.snipe and U.now() < SF.req.back.snipe then return false end
    local bid = HUB.snipeWhere(CFG.snipeUnit)
    local bc = bid and HUB.snipeCost(bid)
    return bc ~= nil and bc.have() - bc.cost * 10 >= bc.keep and HUB.watchRoom()
end
-- the banners turned over since the lobby last looked (by the clock, or the game said so during the match), and Replay and Next can go for hours without passing the lobby. So a results
-- screen goes there once per turnover to look. Not while no banner has anything to pull with above your Keep lines, or storage is full
function HUB.snipeDue()
    if not (CFG.snipeOn and CFG.snipeUnit ~= "") or HUB.snipeHas() or not HUB.snipeStale() then return false end
    local S = B.snipe
    local turn = HUB.snipeTurnAfter(os.time()) - HUB.snipeRate()
    if (tonumber(S.askAt) or 0) >= math.max(turn, tonumber(S.changedAt) or 0) or not HUB.watchRoom() then return false end
    local can = false
    for bid, b in pairs(C.Banners or {}) do
        local bc = type(b) == "table" and b.active and HUB.snipeCost(bid)
        if bc and bc.have() - bc.cost * 10 >= bc.keep then can = true end
    end
    if not can then return false end
    S.askAt = os.time()
    return true
end
function HUB.snipeText()
    local S = B.snipe
    local id = CFG.snipeUnit
    local lines = {}
    if id == "" then
        table.insert(lines, "Pick a unit below. It's pulled on whichever banner features it, until it drops or a Keep line below is reached.")
    elseif HUB.snipeHas(id) then
        table.insert(lines, "You have " .. UNIT.name(id) .. ".")
    elseif not CFG.snipeOn then
        table.insert(lines, UNIT.name(id) .. " is picked. Switch Banner Snipe on to pull for it.")
    else
        local bid = not HUB.snipeStale() and HUB.snipeWhere(id)
        table.insert(lines, bid and (UNIT.name(id) .. " is featured on " .. (HUB.BANNER_NAME[bid] or bid) .. " right now.") or ("Waiting for " .. UNIT.name(id) .. " to be featured."))
    end
    if S.lookAt then
        local parts = {}
        for bid, ids in pairs(S.feat or {}) do
            local names = {}
            for _, x in ipairs(ids) do table.insert(names, UNIT.name(x)) end
            if #names > 0 then table.insert(parts, (HUB.BANNER_NAME[bid] or bid) .. ": " .. table.concat(names, ", ")) end
        end
        table.sort(parts)
        table.insert(lines, "Featured at " .. os.date("%H:%M", S.lookAt) .. " · " .. table.concat(parts, " · "))
    end
    table.insert(lines, string.format("Banners turn over next at %s%s", os.date("%H:%M", HUB.snipeTurnAfter(os.time())), S.clock and "" or " (expected)"))
    table.insert(lines, string.format("Gems %s · Pearls %s · Legacy Gems %s · pulled so far: %d", U.fmt(tonumber(C.cur("gems")) or 0), U.fmt(tonumber(C.cur("SummerPearls")) or 0),
        U.fmt(tonumber(C.cur("GemsLegacy")) or 0), tonumber(S.pulls) or 0))
    if S.note then table.insert(lines, os.date("%H:%M", S.noteAt or os.time()) .. " " .. S.note) end
    return table.concat(lines, "\n")
end
function HUB.summon()
    local p = C.prof()
    if not p then return end
    local msgs = {}
    local function pull(banner, cur, have, floor, unitCost, why, curName, stop)
        local n, slow = 0, 0
        while n < CFG.summonsPerVisit and have() - unitCost * 10 >= floor and not (stop and stop()) do
            local before = have()
            local askedAt = U.now()
            local ok, r = SF.request("summon", "buy_from_banner", banner, "gems10")
            local t1 = U.now()
            while U.now() - t1 < 4 and have() >= before do task.wait(0.25) end
            if not ok or have() >= before then
                local said = SF.gameSaid(askedAt) or r
                -- (the game refuses a pull a few seconds after the last one: a moment, then on. It used to wait 10 minutes, so each visit got 10 of its 20)
                if tostring(said):lower():find("too fast") and slow < 3 then slow = slow + 1; task.wait(6); continue end
                SF.log(1, "SUMMON", banner .. " refused (" .. tostring(said) .. ")")
                SF.backoff("summon", 600)
                break
            end
            slow = 0
            n = n + 10
            SPEND.add("10 summons on " .. banner, before - have(), curName, why)
            task.wait(5)
        end
        return n
    end
    if CFG.summonApril and C.Banners.April2025 then
        -- a missing limited unit — with the guides on, only one they rate S or better once evolved (Chuuni SS,
        -- Vengeful Swordsman S; Violentine B and Kansai D aren't worth the coins)
        -- with a pull goal (Chuuni): only until it drops, keeping its evolve item's price
        local goal = ADV.pullGoal()
        local want, wantIds = {}, {}
        local function add(id) if not table.find(wantIds, id) then table.insert(want, UNIT.name(id)); table.insert(wantIds, id) end end
        if goal then
            if goal.step == "pull" then add(goal.id) end
        else
            for _, id in ipairs({ "osaka", "dokuro", "rikka", "chihiro" }) do
                local _, r = ADV.tierBest(id)
                if not UNIT.owns(id) and (not CFG.community or r >= ADV.TIER_RANK.S) then add(id) end
            end
        end
        -- units the player picked by name, whatever the guides rate them (Violentine — tier B — on Oct 30)
        for _, id in ipairs(CFG.aprilTargets or {}) do
            if C.Units[id] and not UNIT.owns(id) and not HUB.hatched[id] then add(id) end
        end
        local floor = CFG.aprilFloor
        if goal and goal.item and not goal.haveItem then floor = math.max(floor, goal.itemCost) end
        local coins = function() return C.cur("AprilCoins") end
        if #want == 0 then
            table.insert(msgs, goal and ("April banner: " .. UNIT.name(goal.id) .. " is yours ✓")
                or (CFG.community and "April banner: you have every limited unit worth the coins ✓" or "April banner: all limited units owned ✓"))
        else
            -- (stops once every wanted unit has dropped)
            local function got(id) return HUB.hatched[id] or UNIT.owns(id) end
            local stop = function()
                for _, id in ipairs(wantIds) do if not got(id) then return false end end
                return true
            end
            local n = pull("April2025", "AprilCoins", coins, floor, 150, "for " .. table.concat(want, ", "), "AprilCoins", stop)
            for _, id in ipairs(wantIds) do
                if got(id) then
                    SF.log(1, "SUMMON", UNIT.name(id) .. " dropped from the April banner!")
                    if goal and id == goal.id then
                        if SF.notify then SF.notify("Main goal", UNIT.name(goal.id) .. " is yours! Next: its evolve item (" .. U.fmt(goal.itemCost) .. " AprilCoins)", "success") end
                        pcall(ADV.refresh)
                    elseif SF.notify then SF.notify("April banner", UNIT.name(id) .. " is yours!", "success") end
                end
            end
            table.insert(msgs, string.format("April banner: %s (%s coins, keeping %s)", n > 0 and (n .. " summons") or "saving", U.fmt(coins()), U.fmt(floor)))
        end
    end
    if CFG.summonGems then
        -- the gem banner's featured units vs your team at full growth
        local team = UNIT.equipped()
        local weakest = math.huge
        for _, e in ipairs(team) do if not UNIT.isFarm(e.id) then weakest = math.min(weakest, UNIT.score(e.u)) end end
        local ok, setup = SF.request("hatch", "get_hatch_setup_data")
        local better, unknown = {}, 0
        if ok and type(setup) == "table" and setup.EventClover and setup.EventClover.rateup_units then
            for _, id in pairs(setup.EventClover.rateup_units) do
                -- a unit whose upgrades the game hides can't be judged: no summons on a guess, unless the guides rate
                -- it (or its evolved form) S or better — the first list only (the second one's higher ratings don't
                -- start gem spending: the user's condition)
                local ev, tr = ADV.tierBest(id, true)
                if C.Units[id] and not UNIT.owns(id) and UNIT.hidden(id) and tr >= ADV.TIER_RANK.S then
                    table.insert(better, UNIT.name(ev) .. " (tier " .. tostring((ADV.tier(ev, true))) .. ")")
                elseif C.Units[id] and not UNIT.owns(id) and UNIT.hidden(id) then unknown = unknown + 1
                elseif C.Units[id] and not UNIT.owns(id) then
                    -- a level-1, traitless copy at full upgrade (what a fresh pull would be)
                    local fake = { unit_id = id, uuid = "sim:" .. id, xp = 0, traits = {}, trait_stats = { potency_stat = 1, speed_stat = 1, range_stat = 1 } }
                    local okS, sc = pcall(UNIT.score, fake)
                    if okS and sc > weakest then table.insert(better, UNIT.name(id)) end
                end
            end
        end
        if #better == 0 then table.insert(msgs, "gem banner: nothing that beats your team" .. (unknown > 0 and string.format(" (%d featured units can't be judged: the game hides their upgrades)", unknown) or ""))
        else
            local gems = function() return C.cur("gems") end
            local n = pull("EventClover", "gems", gems, CFG.gemFloor, 50, "would beat your weakest unit: " .. table.concat(better, ", "), "gems")
            table.insert(msgs, string.format("gem banner: %s", n > 0 and (n .. " summons") or "saving"))
        end
    end
    -- your pick on the Lobby tab: down to the Keep At Least line, while your unit storage has room
    if CFG.autoSummon and CFG.summonBanner ~= "" and not (SF.req.back.summon and U.now() < SF.req.back.summon) then
        local bc = HUB.bannerCost(CFG.summonBanner)
        if bc then
            local function full()
                local n = 0
                for _ in pairs(p.collection.owned_units) do n = n + 1 end
                -- (10 slots stay free: a full collection refuses every pad, and summoning right up to the limit shut out the Daily Challenge)
                return n + 20 > (tonumber(p.collection.capacity) or math.huge)
            end
            local n = pull(CFG.summonBanner, bc.name, bc.have, CFG[bc.floor], bc.cost, "Auto Summon: your pick (Summon tab)", bc.name, full)
            local label = HUB.BANNER_NAME[CFG.summonBanner] or CFG.summonBanner
            table.insert(msgs, n > 0 and string.format("%s: %d summons", label, n)
                or (full() and (label .. ": your unit storage is full") or (label .. ": at your Keep At Least line")))
        end
    end
    SF.status("Summon", #msgs > 0 and table.concat(msgs, " · ") or "off")
end

-- one step of unit storage, on your go-ahead only (B.buyStorage): a full collection refuses every pad. Once, whatever the answer, and never above the price you agreed
function HUB.buyStorage()
    local want = B.buyStorage
    if not want then return end
    B.buyStorage = nil
    SF.saveNow()
    local p = C.prof()
    local steps = C.GS.CAPACITY_INCREASES and C.GS.CAPACITY_INCREASES.units
    local done = p.inventory_capacity_increases and tonumber(p.inventory_capacity_increases.unit_capacity_increase) or 0
    local step = steps and steps[done + 1]
    if not step then return SF.log(1, "SHOP", "unit storage: no more steps to buy") end
    local cost = tonumber(step.gold_cost) or math.huge
    if cost > (tonumber(want.maxGold) or 0) then return SF.log(1, "SHOP", string.format("unit storage: the next step costs %s gold, more than the %s you agreed: not bought", U.fmt(cost), U.fmt(want.maxGold))) end
    local gold0, cap0 = tonumber(C.cur("gold")) or 0, p.collection.capacity
    local t0 = U.now()
    local ok, r = SF.request("storage", "try_purchase_unit_capacity")
    while U.now() - t0 < 5 and (tonumber(C.cur("gold")) or 0) >= gold0 do task.wait(0.25) end
    local paid = gold0 - (tonumber(C.cur("gold")) or 0)
    if paid > 0 then
        SPEND.add("+" .. tostring(step.increase) .. " unit storage", paid, "gold", "your go-ahead: the collection was full, which refuses every pad")
        SF.log(1, "SHOP", string.format("bought +%s unit storage for %s gold (storage was %s) · gold %s", tostring(step.increase), U.fmt(paid), tostring(cap0), U.fmt(C.cur("gold"))))
        -- (what the full collection was holding back goes next)
        MODE.rec("dc").restUntil = nil
        MODE.lastScored, HUB.last.pick = nil, nil
    else
        task.wait(0.5)
        SF.log(1, "SHOP", string.format("the game didn't sell unit storage (%s): not trying again", tostring(SF.gameSaid(t0) or (ok and r) or "no answer")))
    end
    SF.saveSoon()
end
-- one shop item on your go-ahead only (B.buyOnce = {item, cur, max, why}): once, whatever the answer, and only while that currency has the price (Nov 2: Fishi's Captain's Hat,
-- 5,000 Summer Pearls, below the pearls Open Sunny Stars keeps). The event shop only sells in the lobby: a match's call got no answer. What it pays is checked after
function HUB.buyOnce()
    local w = B.buyOnce
    if not w then return end
    local name = (C.Items[w.item] or {}).name or w.item
    B.buyOnce = nil
    SF.saveNow()
    if ADV.have(w.item) >= 1 then return SF.log(1, "SHOP", name .. ": you have one already, so nothing was bought") end
    local before = tonumber(C.cur(w.cur)) or 0
    if before < (tonumber(w.max) or 0) then return SF.log(1, "SHOP", string.format("%s: %s short of its %s %s, so nothing was bought", name, U.fmt(before), U.fmt(w.max), tostring(w.cur))) end
    local t0 = U.now()
    local ok, r = SF.request("eshop", "buy_item_generic", w.item, w.shop or "event", w.gui or "event_shop", "1")
    while U.now() - t0 < 5 and ADV.have(w.item) < 1 do task.wait(0.25) end
    local spent = before - (tonumber(C.cur(w.cur)) or 0)
    if ADV.have(w.item) >= 1 then
        SPEND.add(name, spent, tostring(w.cur), tostring(w.why or "your go-ahead"))
        pcall(ADV.refresh)
        HUB.last.goals = nil
        if SF.notify then SF.notify("Shop", "Bought " .. name, "success") end
    else
        task.wait(0.5)
        SF.log(1, "SHOP", string.format("the shop didn't sell %s (%s): not trying again", name, tostring(SF.gameSaid(t0) or (ok and r) or "no answer")))
    end
end
-- the pads: Story / Raid (owner pads), Challenges, Daily Challenge, Event (shared pads)
function HUB.pad(kind, m)
    local function free(folder)
        for _, p in ipairs(folder:GetChildren()) do
            local o = p:FindFirstChild("Owner")
            local a = p:FindFirstChild("Active")
            if o and o.Value == nil and not (a and a.Value) then return p end
        end
    end
    if kind == "story" or kind == "infinite" then return free(workspace._LOBBIES.Story) end
    if kind == "raid" then return free(workspace._RAID.Raid) end
    if kind == "challenge" then return workspace._CHALLENGES.Challenges:GetChildren()[1] end
    if kind == "daily" then return workspace._CHALLENGES.DailyChallenge:GetChildren()[1] end
    if kind == "event" then
        local name = B.live.event and B.live.event.pad
        return name and workspace._EVENT_CHALLENGES.Lobbies:FindFirstChild(name) or nil
    end
end
function HUB.launch(m)
    if m.kind == "dungeon" then return DG.launch(m) end
    local okRl, eRl = pcall(STR.relicsApply)
    if not okRl then SF.log(1, "ERROR", "relics: " .. tostring(eRl)) end
    -- (a portal run, or a run on the map that drops portals: measured against back in the lobby, HUB.watchDone)
    B.watch = nil
    for pid, pt in pairs(MODE.PORTALS) do
        if (m.kind == "portal" and m.level == pt.level) or (m.portalMap and m.level == pt.from) then
            B.watch = { key = m.key, portal = pid, item = pt.item, have = ADV.have(pt.item), held = #MODE.portalsHeld(pid), used = m.kind == "portal", at = os.time() }
        end
    end
    if m.kind == "portal" then return HUB.launchPortal(m) end
    local pad = HUB.pad(m.kind, m)
    if not pad then SF.log(1, "MODE", "no free pad for " .. m.label); SF.backoff("launch", 20); return false end
    B.pending = { key = m.key, kind = m.kind, level = m.level, diff = m.diff, label = m.label, at = os.time(), value = m.value }
    if B.nextMode == m.key then B.nextMode = nil end
    SF.log(1, "MODE", string.format("launching %s on %s — %s (≈%.0f gems/min)", m.label, pad.Name, m.why or "", m.score or 0))
    SF.saveNow() -- the teleport kills this script: the match reads what we launched from the brain (and the log is flushed)
    SF.status("Mode", "starting " .. m.label)
    local joinAt = U.now()
    local ok, r = SF.request("join", "request_join_lobby", pad.Name)
    if not (ok and r) then
        task.wait(0.5)
        local said = SF.gameSaid(joinAt)
        SF.log(1, "MODE", "join refused on " .. pad.Name .. " (" .. tostring(said or r) .. ")" .. (said and (": " .. m.label .. " rests for half an hour") or ""))
        B.pending = nil
        -- (the game gave a reason, so asking again won't help, and the next mode shouldn't wait: "Your collection is full!" looped the Daily Challenge every 16 s, with the dungeon behind it)
        if said then MODE.rec(m.key).restUntil = os.time() + 1800; MODE.lastScored = nil end
        SF.backoff("launch", said and 5 or 15)
        return false
    end
    if m.kind == "story" or m.kind == "raid" or m.kind == "infinite" then
        local okL, rl = SF.request("lock", "request_lock_level", pad.Name, m.level, false, m.diff)
        if not (okL and rl) then
            SF.log(1, "MODE", "lock refused for " .. m.label .. " (" .. tostring(rl) .. ")")
            SF.request("leave", "request_leave_lobby", pad.Name)
            local rec = MODE.rec(m.key)
            rec.restUntil = os.time() + 1800
            B.pending = nil
            SF.backoff("launch", 10)
            return false
        end
    end
    task.wait(0.5)
    SF.request("start", "request_start_game", pad.Name)
    -- teleport within ~40 s, else give the pad back and try something else
    local t0 = U.now()
    while SF.alive and U.now() - t0 < 45 do task.wait(1) end
    if SF.alive then
        SF.log(1, "MODE", "no teleport after 45s for " .. m.label .. " — leaving the pad")
        SF.request("leave", "request_leave_lobby", pad.Name)
        local rec = MODE.rec(m.key)
        rec.restUntil = os.time() + 900
        B.pending = nil
        SF.backoff("launch", 10)
    end
    return false
end
-- a portal: using it opens your own portal lobby (the game's own Start button then sends request_start_game for it), so no pad is needed
function HUB.launchPortal(m)
    B.pending = { key = m.key, kind = m.kind, level = m.level, diff = m.diff, label = m.label, at = os.time(), value = m.value }
    SF.log(1, "MODE", string.format("launching %s with a %s — %s (≈%.0f gems/min)", m.label, (C.Items[(B.watch or {}).portal or ""] or {}).name or "portal", m.why or "", m.score or 0))
    SF.saveNow()
    SF.status("Mode", "opening " .. m.label)
    local t0 = U.now()
    local _, r = SF.request("portal", "use_portal", m.portal)
    local LSC = C.svc("LobbyServiceClient")
    local lobby
    while SF.alive and U.now() - t0 < 10 and not lobby do
        lobby = LSC and LSC.current_lobby
        if not lobby then
            local f = workspace:FindFirstChild("_PORTALS") and workspace._PORTALS:FindFirstChild("Lobbies")
            for _, p in ipairs(f and f:GetChildren() or {}) do
                local o = p:FindFirstChild("Owner")
                if o and o.Value == LP then lobby = p.Name end
            end
        end
        if not lobby then task.wait(0.5) end
    end
    if not lobby then
        local said = SF.gameSaid(t0)
        SF.log(1, "MODE", string.format("the portal didn't open (%s): %s rests for half an hour", tostring(said or r or "no answer"), m.label))
        MODE.rec(m.key).restUntil = os.time() + 1800
        B.pending, B.watch = nil, nil
        SF.backoff("launch", 10)
        return false
    end
    task.wait(0.5)
    -- what this portal is, now it's open: its own level data, with the modifiers the game's portal screen shows (weaknesses, scales, challenge). What differs from the plain level is
    -- logged, kept for the portal record (HUB.portalLine), and when it changes how the fight goes, the team is planned again on it before Start
    pcall(function()
        local lp = LSC and LSC.more_lobby_params and LSC.more_lobby_params[lobby]
        local ld = lp and lp._level_data
        if type(ld) ~= "table" then return end
        local base = C.Levels[m.level] or {}
        local diffs = {}
        for k, v in pairs(ld) do
            local b = base[k]
            if type(v) ~= "table" and type(v) ~= "function" and v ~= b then table.insert(diffs, tostring(k) .. "=" .. tostring(v))
            elseif type(v) == "table" and type(b) ~= "table" then
                local okJ, j = pcall(Http.JSONEncode, Http, v)
                table.insert(diffs, tostring(k) .. "=" .. (okJ and j:sub(1, 120) or "{…}"))
            end
        end
        table.sort(diffs)
        local text = #diffs > 0 and table.concat(diffs, " · ") or "none beyond the plain level"
        B.portalMods = text
        SF.saveNow()
        SF.log(1, "PORTAL", string.format("%s opened: %s", m.label, text:sub(1, 400)))
        local fight = text:find("weak") or text:find("challenge") or text:find("difficulty") or text:find("resist") or text:find("health")
        if fight and CFG.autoTeam then
            m.ldOverride = ld
            local okT, eT = pcall(HUB.teamFor, m, 10)
            if not okT then SF.log(1, "ERROR", "portal team: " .. tostring(eT)) end
            m.ldOverride = nil
        end
    end)
    -- (Start again if nothing happens: the third portal on Nov 2 opened, took one Start and stood still for 45 s, where the two before it went at once)
    local t1 = U.now()
    local answers = {}
    for try = 1, 3 do
        local okS, rs = SF.request("start", "request_start_game", lobby)
        table.insert(answers, tostring(okS and rs))
        local t2 = U.now()
        while SF.alive and U.now() - t2 < 12 do task.wait(1) end
        if not SF.alive then return false end
        lobby = (LSC and LSC.current_lobby) or lobby
    end
    if SF.alive then
        local said = SF.gameSaid(t1)
        SF.log(1, "MODE", string.format("no teleport after 3 Starts (%s%s) for %s — leaving the portal lobby, next try with another portal", table.concat(answers, ", "), said and (", the game said: " .. said) or "", m.label))
        SF.request("leave", "request_leave_lobby", lobby)
        HUB.badPortal = HUB.badPortal or {}
        HUB.badPortal[m.portal] = os.time() + 3600
        MODE.rec(m.key).restUntil = os.time() + 300
        B.pending, B.watch = nil, nil
        SF.backoff("launch", 10)
    end
    return false
end
function HUB.portalLine(text)
    local f = C.FOLDER .. "/portal_runs.txt"
    local okR, old = pcall(readfile, f)
    pcall(writefile, f, (okR and old or "") .. text .. "\n")
end
-- back in the lobby: what a portal run paid in its item, and how many portals a run of their map dropped (EMA; the guesses in MODE.PORTALS give way to these)
function HUB.watchDone()
    local w = B.watch
    if not w then return end
    B.watch = nil
    if os.time() - (tonumber(w.at) or 0) > 3 * 3600 then return end
    local got = ADV.have(w.item) - (tonumber(w.have) or 0)
    local held = #MODE.portalsHeld(w.portal)
    local function blend(k, v)
        local r = B.portalPay[k] or { n = 0 }
        r.n = (tonumber(r.n) or 0) + 1
        r.per = r.per and (r.per + (v - r.per) * math.max(0.25, 1 / r.n)) or v
        B.portalPay[k] = r
    end
    local item, portal = (C.Items[w.item] or {}).name or w.item, (C.Items[w.portal] or {}).name or w.portal
    if w.used then
        HUB.portalLine(string.format("%s · paid +%d %s (now %d) · %d portals left", os.date("%m-%d %H:%M"), got, item, ADV.have(w.item), held))
        if w.won == false then
            SF.log(1, "PORTAL", string.format("%s: lost, so +%d %s (now %d) · %d portals left · not counted as what a portal pays", MODE.levelName(MODE.PORTALS[w.portal].level), got, item, ADV.have(w.item), held))
        else
            blend(w.portal, math.max(0, got))
            SF.log(1, "PORTAL", string.format("%s: +%d %s (now %d) · %d portals left", MODE.levelName(MODE.PORTALS[w.portal].level), got, item, ADV.have(w.item), held))
        end
    else
        local drops = held - (tonumber(w.held) or 0)
        blend("drop:" .. w.portal, math.max(0, drops))
        SF.log(1, "PORTAL", string.format("%s dropped %d %s (now %d)%s", MODE.levelName(MODE.PORTALS[w.portal].from), drops, portal, held, got > 0 and string.format(" · +%d %s", got, item) or ""))
    end
    MODE.lastScored = nil
    SF.saveSoon()
end
-- a simulation exists for this mode with the team equipped now (or the mode can't be simulated)
function HUB.simFresh(m)
    local sr = B.simRes[m.key]
    return sr and sr.sig == MODE.teamSig() and os.time() - (sr.at or 0) < 6 * 3600 or false
end
-- a team can hold one of each relic kind ("only one of each Unique Relic to a team"), and the game turns away the second unit: Illusionist
-- and Chuuni both carry a Miracle Timepiece, so every planned team with both came out a unit short. The unit that keeps it: one of your own team, else
-- the stronger. The other's goes back when your own team does (HUB.relicBack)
function HUB.relicClash(uuids)
    local s = C.session()
    local own = {}
    for _, uuid in ipairs(B.savedTeam or {}) do own[uuid] = true end
    local rows = {}
    for _, uuid in ipairs(uuids) do
        local u = s.collection:get_unit_by_uuid(uuid)
        local it = u and u._equipped_relic and s.inventory:get_item_by_uuid(u._equipped_relic)
        -- (the game's own flag: of your kinds only the Miracle Timepiece has it)
        if it and it.item_id and (C.Items[it.item_id] or {}).unique_equip then table.insert(rows, { uuid = uuid, u = u, kind = it.item_id, relic = u._equipped_relic, k = (own[uuid] and 1e12 or 0) + STR.score(u) }) end
    end
    table.sort(rows, function(a, b) if a.k ~= b.k then return a.k > b.k end return a.uuid < b.uuid end)
    local seen = {}
    for _, r in ipairs(rows) do
        if seen[r.kind] then
            local name = (C.Items[r.kind] or {}).name or r.kind
            local _, ans = SF.request("relicOff", "request_unequip_relic", r.relic)
            local t0 = U.now()
            while U.now() - t0 < 3 and r.u._equipped_relic == r.relic do task.wait(0.25) end
            if r.u._equipped_relic ~= r.relic then
                B.relicOff[r.uuid] = r.relic
                SF.log(1, "TEAM", string.format("%s took off its %s for this team: %s has one, and a team can hold one of each", UNIT.name(r.u.unit_id), name, UNIT.name(seen[r.kind])))
            else
                SF.log(1, "TEAM", string.format("%s's %s wouldn't come off (%s): the game won't take both on a team", UNIT.name(r.u.unit_id), name, tostring(ans)))
            end
        else
            seen[r.kind] = r.u.unit_id
        end
    end
end
-- the relics a borrowed team took off, back on their units (while those are off the team, as they were)
function HUB.relicBack()
    -- (with smart relics on, a relic isn't owed to anyone: it goes where the team needs it)
    if CFG.team and CFG.teamRelics then table.clear(B.relicOff); return end
    local s = C.session()
    for uuid, relic in pairs(B.relicOff) do
        local u = s.collection:get_unit_by_uuid(uuid)
        local it = s.inventory:get_item_by_uuid(relic)
        local rd = it and it._unique_item_data and it._unique_item_data._unique_relic_data
        if u and rd and not u._equipped_relic and not rd._equipped_unit_uuid and not STR.slotOf(uuid) then
            -- (the game won't put a relic on anyone while a unit on the team holds that kind, "Cannot equip more than one unit with Relic": the holder
            -- steps out for a moment, and can go back with the other unit holding the same kind off the team)
            local holder
            for _, e in ipairs(UNIT.equipped()) do
                local hit = e.u._equipped_relic and s.inventory:get_item_by_uuid(e.u._equipped_relic)
                if hit and hit.item_id == it.item_id then holder = e end
            end
            if holder then
                B.str.reequip = { uuid = holder.uuid, slot = holder.slot }
                SF.saveNow()
                SF.request("uneq", "unequip_unit", holder.uuid)
                local t1 = U.now()
                while U.now() - t1 < 4 and STR.slotOf(holder.uuid) do task.wait(0.25) end
            end
            SF.request("relicOff", "use_unique_item", relic, { unit_uuid = uuid })
            local t0 = U.now()
            while U.now() - t0 < 3 and u._equipped_relic ~= relic do task.wait(0.25) end
            if holder then STR.reequip() end
            SF.log(1, "TEAM", string.format("%s has its %s back%s", UNIT.name(u.unit_id), (C.Items[it.item_id] or {}).name or tostring(it.item_id), u._equipped_relic == relic and "" or ": the game didn't take it"))
        end
        B.relicOff[uuid] = nil
    end
end
-- equip a team (by unit uuid); your own team is saved first and can be put back
function HUB.equipTeam(uuids, why)
    local cur = {}
    for _, e in ipairs(UNIT.equipped()) do cur[e.uuid] = true end
    if not B.savedTeam then
        local l = {}
        for _, e in ipairs(UNIT.equipped()) do table.insert(l, e.uuid) end
        B.savedTeam = l
    end
    local okC, eC = pcall(HUB.relicClash, uuids)
    if not okC then SF.log(1, "ERROR", "relic clash: " .. tostring(eC)) end
    local want = {}
    for _, u in ipairs(uuids) do want[u] = true end
    -- read back and tried again: with two units to swap, a call can fail without a word (Oct 31, 0.35 s apart: "your own
    -- team back" left C.E.O. in Sora's place, then left Windsong's slot empty), so more time between calls too
    local took, said = false, {}
    for try = 1, 4 do
        for uuid in pairs(cur) do
            if not want[uuid] then
                local _, r = SF.request("uneq", "unequip_unit", uuid)
                table.insert(said, string.format("out %s: %s", UNIT.name((C.session().collection:get_unit_by_uuid(uuid) or {}).unit_id or "?"), tostring(r)))
                task.wait(0.8)
            end
        end
        for _, uuid in ipairs(uuids) do
            if not cur[uuid] then
                -- (no slot named takes the free one. A named slot only replaces whoever is in it, and does nothing on an empty one: the last resort, tries 3 and 4)
                local free
                if try > 2 then
                    local used = {}
                    for _, e in ipairs(UNIT.equipped()) do used[e.slot] = true end
                    for i = 1, 6 do if not used[i] then free = i; break end end
                end
                local okE, r
                if free then okE, r = SF.request("eq", "equip_unit", uuid, free) else okE, r = SF.request("eq", "equip_unit", uuid) end
                table.insert(said, string.format("in %s%s: %s %s", UNIT.name((C.session().collection:get_unit_by_uuid(uuid) or {}).unit_id or "?"), free and (" slot " .. free) or "", tostring(okE), tostring(r)))
                task.wait(0.8)
            end
        end
        local t0 = U.now()
        while U.now() - t0 < 3 and not TRAIN.same(TRAIN.team(), uuids) do task.wait(0.25) end
        took = TRAIN.same(TRAIN.team(), uuids)
        if took then break end
        cur = {}
        for _, e in ipairs(UNIT.equipped()) do cur[e.uuid] = true end
    end
    MODE._sigAt = nil
    if took then
        SF.log(1, "TEAM", "equipped " .. #uuids .. " units — " .. tostring(why))
    else
        local names = {}
        for _, e in ipairs(UNIT.equipped()) do table.insert(names, UNIT.name(e.id)) end
        SF.log(1, "TEAM", "the team swap didn't take (" .. tostring(why) .. "): the game has " .. table.concat(names, ", ") .. " · calls: " .. table.concat(said, " · "))
        -- a half-made team was never simulated and may have an empty slot (room 18, Oct 31: Illusionist wouldn't equip, and two level-1
        -- units and five slots went in). The units taken out go back in, so the team is at least the one that was there
        if not HUB.refilling and #UNIT.equipped() < 6 then
            HUB.refilling = true
            local back, have = {}, {}
            for _, e in ipairs(UNIT.equipped()) do have[e.uuid] = true end
            for _, uuid in ipairs(B.savedTeam or {}) do if not have[uuid] and C.session().collection:get_unit_by_uuid(uuid) then table.insert(back, uuid) end end
            local put = 0
            for _, uuid in ipairs(back) do
                if #UNIT.equipped() >= 6 then break end
                SF.request("eq", "equip_unit", uuid)
                task.wait(0.8)
                local t1 = U.now()
                while U.now() - t1 < 3 and #UNIT.equipped() < math.min(6, put + 1 + (6 - #back)) do task.wait(0.25) end
                for _, e in ipairs(UNIT.equipped()) do if e.uuid == uuid then put = put + 1 end end
            end
            local now = {}
            for _, e in ipairs(UNIT.equipped()) do table.insert(now, UNIT.name(e.id)) end
            SF.log(1, "TEAM", string.format("filled the empty slots with %d of your own units back: the team is %s", put, table.concat(now, ", ")))
            MODE._sigAt = nil
            HUB.refilling = nil
        end
    end
    SF.saveSoon()
    return took
end
-- one change to your own team, on your word: B.ownSwap = {out = unit id, into = unit id}. It waits until the game answers, so it can be asked for while the servers are down (Priest (Heaven) for Mochi
-- (Rage), Nov 1). After that it's simply your team: the searches and training build on it
function HUB.ownSwap()
    local w = B.ownSwap
    if not w then return end
    -- (no answer: nothing is touched, and it asks again later. Taking a unit out on a dead line could leave an empty slot)
    local okA = SF.request("hatch", "get_hatch_setup_data")
    if not okA then return end
    if B.train.on then TRAIN.home() end
    local s = C.session()
    local own = table.clone(B.savedTeam or TRAIN.team())
    local slot, has
    for i, uuid in ipairs(own) do
        local u = s.collection:get_unit_by_uuid(uuid)
        if u and u.unit_id == w.out then slot = i end
        if u and u.unit_id == w.into then has = true end
    end
    local best, bestXp
    for uuid, o in pairs(s.profile_data.collection.owned_units) do
        if o.unit_id == w.into and (not best or (tonumber(o.xp) or 0) > bestXp) then best, bestXp = uuid, tonumber(o.xp) or 0 end
    end
    if has or not slot or not best then
        B.ownSwap = nil
        SF.log(1, "TEAM", string.format("your own team: %s for %s wasn't needed (%s), nothing changed", UNIT.name(w.into), UNIT.name(w.out), has and "it's already on" or not slot and "that unit isn't on your team" or "you don't have that unit"))
        return SF.saveSoon()
    end
    own[slot] = best
    local had = B.savedTeam
    B.savedTeam = nil
    if HUB.equipTeam(own, string.format("your own team: %s in for %s", UNIT.name(w.into), UNIT.name(w.out))) then
        B.savedTeam, B.ownSwap = nil, nil
        MODE.lastScored = nil
        if SF.notify then SF.notify("Team", string.format("%s is on your team, in for %s", UNIT.name(w.into), UNIT.name(w.out)), "success") end
    else
        B.savedTeam = had or B.savedTeam
    end
    SF.saveSoon()
end
function HUB.restoreTeam()
    if not B.savedTeam then return false end
    local saved = {}
    for _, uuid in ipairs(B.savedTeam) do
        if C.session() and C.session().collection:get_unit_by_uuid(uuid) then table.insert(saved, uuid) end
    end
    B.savedTeam = nil
    -- kept when the game didn't take it, so the next lobby tries again
    B.savedTeam = not HUB.equipTeam(saved, "your own team back") and saved or nil
    if not B.savedTeam then local okR, eR = pcall(HUB.relicBack); if not okR then SF.log(1, "ERROR", "relic back: " .. tostring(eR)) end end
    SF.saveSoon()
    return true
end
-- auto team (Battle tab): a fresh search before every run, from the units and levels you have now, and the team that does better than your own. Never a saved answer (the user's call, Nov 1: a plan
-- from 7 hours earlier put a team on the Daily Challenge that had never been held against the Illusionist they'd added since). The two minutes are only so a launch the game refuses doesn't search again
function HUB.teamFor(m, budget)
    -- (a dungeon room gets its own search: DG.planTeam)
    if m.key == "dg" then
        if B.savedTeam then HUB.restoreTeam() end
        return
    end
    local s = C.session()
    -- (Keep Playing Daily with a team you chose: no search. One you no longer own hands it back to the search)
    if CFG.dailyLoop and m.kind == "daily" and type(CFG.dailyTeam) == "table" and #CFG.dailyTeam > 0 then
        local list, mine = {}, {}
        -- (the copy on your own team, else your best one, by what a farm pays if it's a farm: the score of a Bulby says nothing, and a level-1 spare went in for your own)
        for _, uuid in ipairs(B.savedTeam or TRAIN.team()) do
            local u = s.collection:get_unit_by_uuid(uuid)
            if u then mine[u.unit_id] = uuid end
        end
        for _, id in ipairs(CFG.dailyTeam) do
            local best, top = mine[id], nil
            if not best then
                local isFarm, rows = UNIT.isFarm(id), UNIT.rows(id)
                for _, o in pairs(s.profile_data.collection.owned_units) do
                    if o.unit_id == id then
                        local u = s.collection:get_unit_by_uuid(o.uuid) or o
                        local okS, sc
                        if isFarm then okS, sc = pcall(UNIT.farm, u, rows and rows.max or 0) else okS, sc = pcall(UNIT.score, u) end
                        sc = okS and sc or 0
                        if not top or sc > top then best, top = o.uuid, sc end
                    end
                end
            end
            if best then table.insert(list, best) end
        end
        if #list == #CFG.dailyTeam then
            if B.train.on then TRAIN.home() end
            if not TRAIN.same(TRAIN.team(), list) then HUB.equipTeam(list, "your team for the Daily Challenge") end
            return
        end
        SF.log(1, "TEAM", "your Daily Challenge team has a unit you no longer own: the search picks instead")
    end
    local ownIds = B.savedTeam or TRAIN.team()
    local own = {}
    for _, uuid in ipairs(ownIds) do
        local u = s.collection:get_unit_by_uuid(uuid)
        if u then table.insert(own, u) end
    end
    if #own == 0 then return end
    local sig = SIM.sig(own)
    local was = B.simTeam[m.key]
    if not (was and was.base == sig and os.time() - (tonumber(was.at) or 0) < 120) then
        SF.status("Mode", "looking for the best team for " .. tostring(m.label))
        local okP, eP = pcall(SIM.plan, m, true, budget or 20, own)
        if not okP then SF.log(1, "ERROR", "team search: " .. tostring(eP)) end
    end
    local plan = B.simTeam[m.key]
    -- (only an answer to the team you have now counts)
    local fresh = plan and plan.base == sig and os.time() - (tonumber(plan.at) or 0) < 120
    local base = (fresh and plan.better and type(plan.uuids) == "table" and #plan.uuids > 0) and plan.uuids or ownIds
    -- a training team stays on while it's built on the right team: TRAIN.apply looks at it next
    local on = B.train.on
    if on and not TRAIN.same(on.base or {}, base) then
        TRAIN.home()
        on = nil
    end
    if not on and not TRAIN.same(TRAIN.team(), base) then
        if base == ownIds and B.savedTeam then HUB.restoreTeam()
        else HUB.equipTeam(base, "the simulator's best team for " .. tostring(m.label)) end
    end
end
function HUB.run()
    SF.status("Mode", "in the lobby")
    local arrived = U.now()
    -- units the game ships without their upgrades (a match records them when the server sends them)
    pcall(UNIT.markHidden)
    -- what a summon gave, the moment it lands (a pull goal stops pulling as soon as its unit drops)
    pcall(function()
        local ev = RS.endpoints.server_to_client:FindFirstChild("units_hatched_through_banner")
        if not ev then return end
        table.insert(SF.conns, ev.OnClientEvent:Connect(function(list)
            for _, uuid in pairs(type(list) == "table" and list or {}) do
                local u = C.session() and C.session().collection:get_unit_by_uuid(uuid)
                if u and u.unit_id then HUB.hatched[u.unit_id] = true; SF.log(2, "SUMMON", "pulled " .. UNIT.name(u.unit_id)) end
            end
        end))
    end)
    SF.listenGame()
    -- what the last run paid your units in XP (the profile has it once the lobby loads)
    task.delay(6, function() local okX, eX = pcall(STR.xpSettle); if not okX then SF.log(1, "ERROR", "xp settle: " .. tostring(eX)) end end)
    task.delay(8, function() local okW, eW = pcall(HUB.watchDone); if not okW then SF.log(1, "ERROR", "portal count: " .. tostring(eW)) end end)
    while SF.alive do
        if CFG.master and not B.holdLobby then
            -- (a unit stepped out of the team goes back first)
            if B.str.reequip then pcall(STR.reequip) end
            if B.buyStorage then local okB, eB = pcall(HUB.buyStorage); if not okB then SF.log(1, "ERROR", "unit storage: " .. tostring(eB)) end end
            if B.buyOnce then local okB, eB = pcall(HUB.buyOnce); if not okB then SF.log(1, "ERROR", "shop item: " .. tostring(eB)) end end
            if B.ownSwap and HUB.every("ownSwap", 60) then local okO, eO = pcall(HUB.ownSwap); if not okO then SF.log(1, "ERROR", "team change: " .. tostring(eO)) end end
            -- takedown training: your own team is back before anything is ranked or simulated
            if B.train.on then local okH, eH = pcall(TRAIN.home); if not okH then SF.log(1, "ERROR", "training: " .. tostring(eH)) end end
            if HUB.every("live", 60) then pcall(HUB.refreshLive) end
            if HUB.every("huntShop", 3600) then pcall(HUNT.shopLook) end
            if HUB.every("hive", 60) then pcall(REPORT.sendHive) end
            if HUB.every("hiveUnit", 60) then task.delay(20, function() pcall(REPORT.sendUnit) end) end
            if CFG.useHive and HUB.every("hiveGet", 6 * 3600) then task.spawn(function() local okH, eH = pcall(REPORT.hiveFetch); if not okH then SF.log(1, "ERROR", "brain hive read: " .. tostring(eH)) end end) end
            if HUB.every("rewards", 45) then local ok, e = pcall(HUB.rewards); if not ok then SF.log(1, "ERROR", "rewards: " .. tostring(e)) end end
            if HUB.every("gold", 600) then local ok, e = pcall(HUB.goldShop); if not ok then SF.log(1, "ERROR", "gold shop: " .. tostring(e)) end end
            -- (before Auto Summon, which fills the same storage)
            -- (every 10 min, and at once after a turnover: a look that fails waits 30 s, not every pass)
            if CFG.snipeOn and (HUB.every("snipe", 600) or (HUB.snipeStale() and HUB.every("snipeStale", 30))) then
                local ok, e = pcall(HUB.bannerSnipe); if not ok then SF.log(1, "ERROR", "Banner Snipe: " .. tostring(e)) end
            end
            if HUB.every("summon", 120) then
                local ok, e = pcall(HUB.summon); if not ok then SF.log(1, "ERROR", "summon: " .. tostring(e)) end
                local okE, eE = pcall(HUB.eventShop); if not okE then SF.log(1, "ERROR", "event shop: " .. tostring(eE)) end
            end
            if HUB.every("codes", 21600) then local ok, e = pcall(HUB.codes); if not ok then SF.log(1, "ERROR", "codes: " .. tostring(e)) end end
            -- the path: raid shop prices, goals and their item values, buying a goal's shop item
            if HUB.every("rshopCache", 1800) then
                local okS, shop = SF.request("rshopList", "request_current_raidshop_shop")
                if okS and type(shop) == "table" then
                    table.clear(B.raidShop)
                    for key, v in pairs(shop) do
                        if type(v) == "table" and v.id and v.item_cost then
                            B.raidShop[key] = { id = v.id, costItem = v.item_cost.item_id, cost = tonumber(v.item_cost.amount) or 0, stock = v.stock }
                        end
                    end
                end
            end
            if HUB.every("lbInfo", 1800) then
                local t = UNIT.equipped()[1]
                if t then
                    local okL, info = SF.request("lbInfo", "request_fusion_information", t.uuid)
                    if okL and type(info) == "table" then B.lb = { requirement = info.requirement, allowed = info.allowed } end
                end
            end
            if HUB.every("goals", 300) then
                local ok, e = pcall(ADV.refresh)
                if not ok then SF.log(1, "ERROR", "goals: " .. tostring(e)) else
                    -- a goal item just bought can make its evolution ready right now
                    local okS, bought = pcall(ADV.buyShopGoals)
                    if okS and bought then pcall(ADV.refresh) end
                    local okE, eE = pcall(HUB.smartEvolve)
                    if not okE then SF.log(1, "ERROR", "smart evolve: " .. tostring(eE)) end
                end
                MODE.lastScored = nil
            end
            -- your picks on the Lobby tab, then the Team tab (one action a pass)
            if HUB.every("picks", 20) then
                for _, f in ipairs({ HUB.focusNextUp, HUB.autoEvolve, HUB.autoFuse, HUB.autoFuseXp, HUNT.skinTick }) do
                    local ok, e = pcall(f)
                    if not ok then SF.log(1, "ERROR", "lobby picks: " .. tostring(e)) end
                end
                local okS, eS = pcall(STR.tick)
                if not okS then SF.log(1, "ERROR", "team: " .. tostring(eS)) end
            end
            -- (your call: the Team tab finishes what it can before anything starts)
            local okF, eF = pcall(STR.finishWork)
            if not okF then SF.log(1, "ERROR", "team work: " .. tostring(eF)) end
            local top = MODE.lastScored and MODE.lastScored[1]
            if HUB.every("pick", 5) or not top then
                local okP, t = pcall(MODE.pick)
                if not okP then SF.log(1, "ERROR", "ranking: " .. tostring(t)); t = nil end
                top = t
            end
            -- background planner: best team + evolutions for the most valuable non-farm modes (one per 10 min)
            -- (not while a launch is about to search anyway: HUB.teamFor. The Battle tab's Simulate Now still asks for one)
            if CFG.sim and CFG.simTeams and (HUB.planNow or not (CFG.autoTeam and CFG.play)) and HUB.every("simTeam", 600) then
                HUB.planNow = nil
                task.spawn(function()
                    for _, m in ipairs(MODE.lastScored or {}) do
                        if m.kind == "daily" or m.kind == "challenge" or m.first then
                            local ok, e = pcall(SIM.plan, m, true)
                            if not ok then SF.log(1, "ERROR", "planner: " .. tostring(e)) end
                            break
                        end
                    end
                end)
            end
            -- takedown training: what training is worth in the best modes it may train in (one check per 10 min)
            -- (the launch waits for it, then ranks again: the check for Infinite came a few seconds after the farm had settled on Summer Hunt, so what it found never counted)
            if CFG.trainTakedowns and CFG.sim and MODE.lastScored and HUB.every("trainScan", 600) then
                HUB.scanning = U.now()
                task.spawn(function()
                    local ok, e = pcall(TRAIN.scan)
                    if not ok then SF.log(1, "ERROR", "training planner: " .. tostring(e)) end
                    HUB.scanning = nil
                    MODE.lastScored = nil
                end)
                top = nil
            end
            if HUB.scanning and U.now() - HUB.scanning < 30 then top = nil end
            -- gate: simulate the mode with your team before spending a run on it
            -- (a dungeon room is simulated on its own, per room: DG.sim)
            if CFG.play and CFG.sim and top and not HUB.simFresh(top) and top.kind ~= "event" and top.kind ~= "dungeon" then
                SF.status("Mode", "simulating " .. top.label .. " with your team…")
                local ok, e = pcall(SIM.plan, top, false)
                if not ok then SF.log(1, "ERROR", "sim: " .. tostring(e)) end
                if not (ok and e) then B.simRes[top.key] = { none = true, sig = MODE.teamSig(), at = os.time() } end
                MODE.lastScored = nil
                top = nil
            end
            if CFG.play and top and U.now() - arrived > 8 and not (SF.req.back.launch and U.now() < SF.req.back.launch) then
                local inLobby = LP:FindFirstChild("AlreadyInLobby")
                if B.trial then
                    local okTr, ready = pcall(MODE.trialTeam)
                    if not okTr then SF.log(1, "ERROR", "trial team: " .. tostring(ready)); B.trial = nil end
                    if okTr and ready and not (inLobby and inLobby.Value) then pcall(HUB.launch, top) end
                else
                    if CFG.autoTeam then pcall(HUB.teamFor, top) end
                    local okT, eT = pcall(TRAIN.apply, top)
                    if not okT then SF.log(1, "ERROR", "training: " .. tostring(eT)); pcall(TRAIN.home) end
                    if not (inLobby and inLobby.Value) then pcall(HUB.launch, top) end
                end
            elseif not CFG.play then
                SF.status("Mode", "Auto Play is off")
            elseif not top then
                SF.status("Mode", MODE.onlyOn() and string.format("only %s is on and none can be played right now: waiting", MODE.onlyText()) or "nothing to play (all modes off or resting)")
            end
        else
            SF.status("Mode", B.holdLobby and ("held in the lobby: " .. tostring(B.holdLobby.why)) or "paused")
            -- (the user's call, Nov 2: with the Smart Farm off, your Lobby-tab summons and fuses and the Summer stars still run. Each has its own switch, off until you turn it on)
            if not CFG.master and not B.holdLobby then
                if HUB.every("summon", 120) then local ok, e = pcall(HUB.summon); if not ok then SF.log(1, "ERROR", "summon: " .. tostring(e)) end end
                if CFG.snipeOn and (HUB.every("snipe", 600) or (HUB.snipeStale() and HUB.every("snipeStale", 30))) then
                    local ok, e = pcall(HUB.bannerSnipe); if not ok then SF.log(1, "ERROR", "Banner Snipe: " .. tostring(e)) end
                end
                if HUB.every("picks", 20) then
                    for _, f in ipairs({ HUB.autoFuse, HUB.autoFuseXp, HUNT.skinTick }) do
                        local ok, e = pcall(f)
                        if not ok then SF.log(1, "ERROR", "lobby picks: " .. tostring(e)) end
                    end
                end
            end
        end
        task.wait(2)
    end
end

-- ============================================================
--  ECONOMY DECISION (one function for the live match and the simulator: the sim plays like the farm)
-- ============================================================
-- damage gained by the next upgrade of a unit dealing `live` damage/s at `lvl` (one level of lookahead: a weak
-- step before a big one counts half of the next; more range counts too)
function ECON.upgradeGain(live, rows, lvl, cost, upMult, fallback)
    local cur, nxt = rows[lvl], rows[lvl + 1]
    local ratioNow = (cur.cd > 0 and cur.damage / cur.cd or 0)
    local ratioNext = (nxt.cd > 0 and nxt.damage / nxt.cd or 0) * UNIT.aoe(nxt.atk, nxt.range) / math.max(0.3, UNIT.aoe(cur.atk, cur.range))
    local gain = ratioNow > 0 and live * (ratioNext / ratioNow - 1) or (fallback or 0)
    local nn = rows[lvl + 2]
    if nn and lvl + 1 < rows.max and nn.cd > 0 and nxt.cd > 0 and ratioNow > 0 then
        local g2 = live * ((nn.damage / nn.cd) / ratioNow - 1)
        local c2 = cost + nn.cost * upMult
        if g2 / c2 > gain / cost then gain = gain + (g2 / c2 * cost - gain) * 0.5 end
    end
    local rangeGain = (nxt.range or 0) > (cur.range or 0) and (1 + ((nxt.range - cur.range) / math.max(1, cur.range))) or 1
    return math.max(0, gain) * rangeGain
end
-- opts: {cost, gain, farm?, place?, what}; ctx: {money, left, attackers, pressure, piling, clearSec, enemies, future, wantLeft}
-- 1) opening: an attacker first, so the first waves never leak
-- 2) farm while it pays back with waves to spare, the defense holds (enemies die early, nothing piles up,
--    everything alive dies within clearSec) and the yen is still needed
-- 3) otherwise the best damage per yen (save for it unless a nearly-as-good buy is affordable)
-- returns choice, why — or nil, nil, "saving …"
-- damage you could buy with `yen` right now: the attack options best-first (each unit's next step), then
-- 70% of the last ratio for anything beyond (deeper upgrades get dearer)
function ECON.dpsFor(opts, yen)
    if yen <= 0 then return 0 end
    local list = {}
    for _, o in ipairs(opts) do if not o.farm and o.gain > 0 then table.insert(list, o) end end
    table.sort(list, function(a, b) return a.gain / a.cost > b.gain / b.cost end)
    local d, last = 0, 0
    for _, o in ipairs(list) do
        if yen <= 0 then break end
        last = o.gain / o.cost
        local take = math.min(1, yen / o.cost)
        d = d + o.gain * take
        yen = yen - o.cost * take
    end
    return d + math.max(0, yen) * last * 0.7
end
-- can the defense keep up over the coming waves if we spend `cost` on something that adds `addDps` / `addFarm`?
-- A backlog model: each wave adds its HP (formula, calibrated), the team removes damage/s × wave length; what's
-- left over must be killable before the oldest of it walks out of your units' reach (road time × the share of
-- the road they cover). Yen arriving each wave (reward + farm) buys the best damage per yen. Returns ok, the
-- first wave that falls short, the ratio.
-- a unit's real damage against shields: they count hits, not HP, so H HP behind S shield takes S more hits than the hits to
-- kill, however hard each one lands. dps = its damage across the aoe enemies it hits, every cd seconds. A slow, hard hitter
-- loses most of it (3 shield: a one-hit kill now takes 4 hits), and more damage per hit then buys nothing: more attacks do
function ECON.shieldDps(dps, cd, aoe, S, H, eff, hits)
    if (S or 0) <= 0 or (dps or 0) <= 0 or (H or 0) <= 0 then return dps or 0 end
    cd, aoe, eff = math.max(0.3, cd or 2), math.max(1, aoe or 1), eff or 1
    -- (eff: the share of a unit's damage that really lands, the sim's and the live forecast's own measure. A multi-hit attack
    -- takes that many points off a shield)
    local perHit = dps * eff * cd / aoe
    return H * aoe / ((S / math.max(1, hits or 1) + math.max(1, H / perHit)) * cd) / eff
end
-- what an upgrade adds against shields: real damage (a new cooldown or area counts, a bigger hit often doesn't), and range,
-- since a unit that reaches more road gets more attacks on each enemy
function ECON.shieldGain(dps, r, dpsNext, rNext, S, H, cdMul, eff)
    local ia, ib = UNIT.attackInfo(r.atk, r.range), UNIT.attackInfo(rNext.atk, rNext.range)
    local a = ECON.shieldDps(dps, (tonumber(r.cd) or 2) * (cdMul or 1), ia.n, S, H, eff, ia.hits)
    local b = ECON.shieldDps(dpsNext, (tonumber(rNext.cd) or 2) * (cdMul or 1), ib.n, S, H, eff, ib.hits)
    local more = math.max(0, ((tonumber(rNext.range) or 0) - (tonumber(r.range) or 0)) / math.max(1, tonumber(r.range) or 1))
    return math.max(0, b - a) + a * more
end
-- what a cheap, quick unit is worth against shields besides its own damage: every hit it lands on a shield saves your hardest
-- hitter a wasted one (a level 0 Captain does 2 damage a second, ¥300, a hit every 3 s, and 6 of them strip a shield for Iron
-- Sentinel's 90k hits). Up to `need` hits a second: 3 times the shields a wave brings, what got through on Oct 31
function ECON.shieldWork(aoe, cd, have, S, n, waveSec, heavyHit, H, hits)
    if (S or 0) <= 0 then return 0 end
    local need = 3 * S * (n or 1) / math.max(1, waveSec or 20)
    if (have or 0) >= need then return 0 end
    return math.max(1, aoe or 1) * math.max(1, hits or 1) / math.max(0.3, cd or 2) * math.min(heavyHit or 0, H or 0)
end
-- what a slow or a stun is worth when buying: a held enemy stays longer under all your other units, so their damage counts for more on the stretch it covers. Damage per yen
-- alone hardly ever bought Mochi: 0 copies in about half the dungeon rooms on Oct 31, room 17's two lost tries among them. share: the part of your covered road it reaches,
-- n: enemies it hits at once, have: units already doing this, since an enemy can't be held again while its immunity runs
function ECON.holdGain(ai, teamDps, share, have)
    if not ai or (teamDps or 0) <= 0 then return 0 end
    local stun, slow = tonumber(ai.stun) or 0, tonumber(ai.slowTime) or 0
    if stun <= 0 and slow <= 0 then return 0 end
    local time, power = stun > 0 and stun or slow, stun > 0 and 1 or (tonumber(ai.slowPct) or 0.3)
    local held = power * time / (time + (tonumber(ai.ccCd) or 8))
    local extra = held / math.max(0.1, 1 - held)
    return teamDps * extra * U.clamp(share or 0.5, 0, 1) * math.min(1, (tonumber(ai.n) or 1) / 2) / (1 + (have or 0))
end
-- a bleed stops regen on what it hits (the game's Effects page): on a run whose enemies regenerate it's worth the HP they'd heal a
-- second — what's alive now, or half a coming wave (the last wave's boss above all) — counted as damage a second. Half once a unit
-- on the field already bleeds. Spread over the upgrades still needed to reach the bleeding level (ECON.bleedShare)
function ECON.bleedGain(regen, hpAlive, coming, already)
    if (regen or 0) <= 0 then return 0 end
    local hp = hpAlive or 0
    for _, w in ipairs(coming or {}) do hp = math.max(hp, (tonumber(w.hp) or 0) * 0.5) end
    return regen * hp * (already and 0.5 or 1)
end
function ECON.bleedShare(g, bleedAt, lvl, place)
    if g <= 0 or not bleedAt then return 0 end
    if place then return bleedAt == 0 and g or g / (bleedAt + 1) end
    return lvl < bleedAt and g / (bleedAt - lvl) or 0
end
function ECON.keepsUp(ctx, opts, cost, addDps, addFarm)
    local waves = ctx.coming
    if not (waves and #waves > 0 and ctx.waveSec) then return true end
    local eff = ctx.eff or 1
    local money = ctx.money - cost
    -- (the options' gains already count the shields on the way: the team's damage so far has to as well)
    local dps = (ctx.teamDps or 0) * (ctx.shieldK or 1) + (addDps or 0) * eff + ECON.dpsFor(opts, math.max(0, money)) * eff
    local farm = (ctx.farmNow or 0) + (addFarm or 0)
    local road = (ctx.roadSec or 130) * U.clamp(ctx.cover or 0.6, 0.1, 1)
    local backlog = ctx.hpAlive or 0
    for k, w in ipairs(waves) do
        backlog = math.max(0, backlog + w.hp - dps * ctx.waveSec)
        local canClear = dps * road
        if backlog > canClear then return false, k, canClear / math.max(1, backlog) end
        if k < #waves then dps = dps + ECON.dpsFor(opts, (w.reward or 0) + farm) * eff * (0.85 ^ k) end
    end
    return true
end
function ECON.decide(opts, ctx)
    -- the backlog forecast (ECON.keepsUp) is the judge; these quick checks only catch what it can't see yet.
    -- cover: the share of the road your units reach (enemies past it can't be hit any more)
    -- "slow" = what's alive takes longer to kill than 70% of the walk through the covered road (or the Safe Kill Time)
    local cover = U.clamp(ctx.cover or 0.6, 0.1, 1)
    local slowLimit = math.max(CFG.clearSec, 0.7 * (ctx.roadSec or 50) * cover)
    local slow = (ctx.clearSec or 0) > slowLimit
    -- a crowd only counts as piling up when the team couldn't kill it in time either
    ctx.piling = ctx.piling and slow
    -- safe / danger: how far enemies get, against the end of your coverage (or the settings, if those are lower)
    local safe = ctx.attackers > 0 and ctx.pressure < math.min(CFG.safeReach, cover * 0.75) and not ctx.piling and not slow
    local danger = ctx.pressure >= math.min(CFG.dangerReach, cover * 0.9) or (ctx.piling and ctx.enemies >= 18)
    local bestFarm, bestAtk
    for _, o in ipairs(opts) do
        if o.farm then
            if CFG.farmUnits and o.gain > 0 then
                o.payback = o.cost / o.gain
                if ctx.left - 1 >= o.payback + CFG.farmSpare and (not bestFarm or o.payback < bestFarm.payback) then bestFarm = o end
            end
        else
            o.ratio = o.gain / math.max(1, o.cost)
            if not bestAtk or o.ratio > bestAtk.ratio then bestAtk = o end
        end
    end
    -- a leak: an enemy walked past every unit's range and nothing can hit it before the base — only a new unit
    -- placed in its way can (an upgrade of a unit it already passed can't); the strongest one affordable
    if ctx.leak and ctx.attackers > 0 then
        local pick
        for _, o in ipairs(opts) do
            -- (a flyer got through: only a unit that hits flyers helps)
            local fits = not ctx.airLeak or (o.e and MT.cardAir(o.e.id))
            if o.place and not o.farm and fits and o.cost <= ctx.money and not (o.e and UNIT.allyBuff(o.e.id)) and (not pick or o.gain > pick.gain) then pick = o end
        end
        if pick then return pick, string.format("an enemy got past all your units (%d%% of the road): a unit in its way", math.floor(ctx.leak * 100)) end
    end
    local needYen = ctx.future < ctx.wantLeft * 1.1
    -- the forecast: would the defense keep up over the next waves if the farm buy happened now?
    local farmOk, shortK, shortR = true, nil, nil
    if bestFarm then farmOk, shortK, shortR = ECON.keepsUp(ctx, opts, bestFarm.cost, 0, bestFarm.gain) end
    -- and even spending everything on damage now — if not, nothing gets saved for later
    local behind = ctx.coming and not ECON.keepsUp(ctx, opts, 0, 0, 0)
    -- a dealt-team run (Fool's Hunt): a farm pays back in ~3 of its 30 waves, but its random, growing waves made
    -- the forecast say "defense first" all run (1 farm → lost at wave 15; 3–4 farms → waves 23–24). There a farm
    -- (up to 4 placed, upgrades any time) goes in when it pays back within a third of the waves left and nothing is
    -- in danger on the road right now
    local fhFarm = false
    if MT.random and bestFarm and not danger and ctx.attackers >= 2 and bestFarm.payback <= ctx.left / 3 then
        local nFarms = 0
        for _, m in ipairs(MT.mine or {}) do if UNIT.isFarm(m._stats.id.Value) then nFarms = nFarms + 1 end end
        fhFarm = not bestFarm.place or nFarms < 4
    end
    if behind and ctx.attackers > 0 then danger = true end
    -- the time value of damage: over a horizon, buying B now and A later vs waiting for A — whichever deals more
    -- damage (yen arrives at the measured income rate). Horizon: 2 waves near the base, 4 at the start, else 6
    local rate = math.max(1, ctx.incomeRate or 20)
    local wsec = ctx.waveSec or 20
    local function planDmg(first, second, H)
        local t1 = math.max(0, (first.cost - ctx.money) / rate)
        local d = first.gain * math.max(0, H - t1)
        if second then
            local left = math.max(0, ctx.money - first.cost) -- yen left right after the first buy
            local t2 = t1 + math.max(0, (second.cost - left) / rate)
            d = d + second.gain * math.max(0, H - t2)
        end
        return d
    end
    local choice, why
    if ctx.attackers == 0 and bestAtk then
        -- opening: the attacker that deals the most damage over the next 4 waves, counting the wait for its price
        local H = 4 * wsec
        local pick, pv
        for _, o in ipairs(opts) do
            if o.place and not o.farm then
                local v = planDmg(o, nil, H)
                if not pv or v > pv then pick, pv = o, v end
            end
        end
        choice, why = pick or bestAtk, "opening: the unit that does the most damage over the first waves"
    elseif bestFarm and safe and needYen and not danger and farmOk then
        choice = bestFarm
        why = string.format("farm pays back in %.1f waves (%d left) and the defense still keeps up with the next %d waves", bestFarm.payback, ctx.left, ctx.coming and #ctx.coming or 0)
    elseif fhFarm then
        choice = bestFarm
        why = string.format("farm pays back in %.1f waves (%d left) and nothing is close to the base", bestFarm.payback, ctx.left)
    elseif bestAtk then
        choice = bestAtk
        if behind then why = string.format("the next waves bring more HP than your units can kill: damage now")
        elseif danger then why = string.format("enemies reach %d%% of the road (your units cover %d%%): damage now", math.floor(ctx.pressure * 100), math.floor(cover * 100))
        elseif bestFarm and not farmOk then why = string.format("defense first: after that farm buy, wave +%d would only be %d%% covered", shortK or 1, math.floor((shortR or 0) * 100))
        elseif bestFarm and slow then why = string.format("defense first: killing what's alive takes %ds (farm only under %ds)", math.min(999, math.floor(ctx.clearSec)), math.floor(slowLimit))
        elseif bestFarm and ctx.piling then why = string.format("defense first: %d enemies piling up", ctx.enemies)
        elseif bestFarm and not safe then why = "defense first (enemies get too far to farm)"
        elseif bestFarm and not needYen then why = "farm not needed: coming yen already covers every upgrade"
        else why = "most damage per yen" end
    end
    if not choice then return nil end
    if choice.cost > ctx.money then
        local alt
        if not choice.farm then
            -- (enemies at 95%+ of the road: half a wave — a run saved 36 s for a ¥12k Flamefeather upgrade with enemies
            -- at 99% and five unit cards in hand, and lost at wave 13)
            local H = ((ctx.pressure or 0) >= 0.95 and 0.5 or danger and 2 or 6) * wsec
            local altV
            for _, o in ipairs(opts) do
                if not o.farm and o ~= choice and o.cost <= ctx.money then
                    local now = planDmg(o, choice, H)      -- buy it now, the best one after
                    local later = planDmg(choice, o, H)    -- save for the best one, this one after
                    if now > later and (not altV or now > altV) then alt, altV = o, now end
                end
            end
        end
        if not alt then
            return nil, nil, string.format("saving ¥%s for: %s (≈%ds at ¥%d/s) — %s", U.fmt(choice.cost), choice.what or "?",
                math.ceil((choice.cost - ctx.money) / rate), math.floor(rate), why)
        end
        choice, why = alt, why .. " (worth buying while saving)"
    end
    return choice, why
end

-- ============================================================
--  SIMULATOR (the game's own enemy formulas + the farm's own buy rules; earns trust per mode)
-- ============================================================
SIM.DT = 1
SIM.BINS = 20
-- priors until a mode has real runs (walk: share of the road per second at speed 1, for a map never played: the middle of 25 maps measured, SIM.mapWalk has the rest; base: HP lost per second per enemy at the base, a guess until measured)
-- eff: share of a unit's listed damage that really lands (overkill, range gaps, targeting) — measured per mode
-- waves: enemies come out spawnGap seconds apart (raid: 1.04 s), the wave's timer is measured per wave (the level's
-- wave_max_time until then; big raid waves run longer: 56 enemies → 89 s), skipDelay: cleared wave → next wave (5.2 s)
-- base: an enemy at the base takes baseRel × its max HP off the base every second (measured 0.1–0.5: a leak loses)
-- skip vote (auto-skip on), whatever is still alive: SIM.voteSec. It used to go by the wave's enemy count, which the old measurements fitted (2 enemies → 5.8 s, 11 → 21 s, 22+ → 30 s)
SIM.PRIOR = { waveSec = 20, walk = 0.0054, spawnGap = 1, baseHp = 100, baseRel = 0.3, start = 600, eff = 0.7, waveTimer = 60, skipDelay = 5,
    voteAt = 30, voteBase = 2, votePer = 1.9 }
-- seconds into a wave when the skip vote opens. Read off a live match on Nov 1 it goes by the wave's number, not its size: waves 1-2 at 5 s (2 and 4 enemies), 3-5 at 10 s (4, 3 and 11), then half the wave's timer (12 enemies or 23). The enemy-count
-- formula ran 15 waves about 25% too fast (wave 10 at 150 s against a real 190 s), which is part of why units that start slowly read as falling at wave 11. A mode's own real runs go first (cal.voteWave)
function SIM.voteSec(info, w)
    local seen = info.voteWave and tonumber(info.voteWave[tostring(w)])
    if seen then return seen end
    if w <= 2 then return 5 elseif w <= 5 then return 10 end
    return info.voteAt
end
-- the most of an area attack's listed damage that lands when it doesn't overkill (SIM.run's attack). eff, measured per mode, says what lands of a whole team's listed damage, and on most maps that's your big hitters overkilling small enemies. More than all of it,
-- since a crowd puts more enemies in the area than the listed count: three real runs measured ×1.12, ×1.15 and ×1.36 on Nov 1, and against their wave records 1.3 fits best (Spirit Reaper 9.6M by wave 15 against a real 10.06M; at 0.8 it was 6.3M). A single target can't take more than one hit's worth
SIM.LAND_CAP = 1.3
-- the player's own "Auto-Skip Waves" setting: the game votes the skip as soon as a wave is cleared
function SIM.autoskip()
    local ok, v = pcall(function() return LP._settings.autoskip_waves.Value end)
    if ok and type(v) == "boolean" then return v end
    return true
end
function SIM.cal(key) local c = B.simCal[key]; if not c then c = {}; B.simCal[key] = c end; return c end
-- hit efficiency for a mode: its own measurement, leaning on the average of all measured runs while it has few
-- (one run's reading swings ×3 on the same map with the same team)
function SIM.effFor(cal)
    local sw, sn = 0, 0
    for _, c in pairs(B.simCal) do
        local e, n = tonumber(c.eff), tonumber(c.n) or 0
        if e and n > 0 then sw = sw + e * n; sn = sn + n end
    end
    local g = sn > 0 and sw / sn or SIM.PRIOR.eff
    local e, n = tonumber(cal and cal.eff), tonumber(cal and cal.n) or 0
    if not e then return g end
    return (e * n + g * 3) / (n + 3)
end
-- the level fields the sim needs, kept in the brain so the lobby can plan modes it isn't in
SIM.LD_FIELDS = { "id", "map", "waves", "world", "story_world_rank", "story_level_rank", "_gamemode", "_OVERRIDE_GAMEMODE", "_difficulty",
    "_challenge", "infinite", "_use_max", "_override_infinite_bound_waves", "_override_infinite_boss_interval", "_override_multiplayer_diff_scale",
    "_no_multiplayer_scale", "_raid_multiplayer_scale", "portal_group", "_infinite_bound_level", "_lobby_difficulty_scale", "_location_name", "name", "boss" }
-- an Infinite level with no last wave (a dungeon room makes its waves infinite-style but keeps the template's count)
function SIM.unbound(ld) return not tonumber(ld._override_infinite_bound_waves) and not ld._infinite_bound_level end
function SIM.slim(ld)
    local o = {}
    for _, k in ipairs(SIM.LD_FIELDS) do local v = ld[k]; if type(v) ~= "table" and type(v) ~= "function" then o[k] = v end end
    if type(ld._override_waves) == "table" then o._override_waves = { infinite = ld._override_waves.infinite, template = ld._override_waves.template } end
    if type(ld._dungeon) == "table" then o._dungeon = { depth = ld._dungeon.depth, choice_str = ld._dungeon.choice_str } end
    if type(ld._override_infinite_final_boss_wave) == "table" then
        o._final = { wave = ld._override_infinite_final_boss_wave.wave, cfg = ld._override_infinite_final_boss_wave.final_boss_config_id }
    end
    if type(ld._override_infinite_boss_interval__skip_waves) == "table" then
        o._skip = {}
        for k in pairs(ld._override_infinite_boss_interval__skip_waves) do o._skip[tostring(k)] = true end
    end
    return o
end
local function simCall(f, ...) local ok, v = pcall(f, ...); return ok and tonumber(v) or nil end
-- everything about a mode: enemy HP scale (world × act × players × difficulty × challenge), waves, timing
function SIM.info(ld, key, chId, mod)
    local cal = B.simCal[key] or {}
    local gm = ld._OVERRIDE_GAMEMODE or ld._gamemode or (ld.infinite and "infinite") or "story"
    local daily = ld.id == "__DAILY_CHALLENGE"
    local event = (B.live.event and ld.id == B.live.event.level) and true or false
    local probe = { _is_daily_challenge = daily or nil, _is_event_challenge = event or nil, _use_max = ld._use_max, world = ld.world, id = ld.id,
        _override_multiplayer_diff_scale = ld._override_multiplayer_diff_scale, _no_multiplayer_scale = ld._no_multiplayer_scale,
        portal_group = ld.portal_group, _raid_multiplayer_scale = ld._raid_multiplayer_scale }
    local rank = tonumber(ld.story_world_rank) or #U.list(C.WLO.WORLD_ORDER)
    local gmW = (gm == "infinite") and "challenge" or gm
    local ws = simCall(C.LU.calculate_world_diff_scale, rank, gmW, nil, ld.map, probe) or 1
    local ls = simCall(C.LU.calculate_level_diff_scale, tonumber(ld.story_level_rank) or 6, (gm == "infinite" or gm == "raid") and gm or (gm == "challenge" and "challenge" or "story"), probe) or 1
    local ms = simCall(C.LU.calculate_multiplayer_diff_scale, gm, 1, probe) or 1
    local ow = ld._override_waves
    local wdef = C.Waves[(ow and ow.template) or ld.waves or ld.id]
    local base = wdef
    if wdef and wdef.template and C.Waves[wdef.template] then base = C.Waves[wdef.template] end
    local infinite = (ow and ow.infinite) or ld.infinite or (wdef and wdef.infinite) or false
    local configs = (wdef and wdef.initial_unit_configs) or (base and base.initial_unit_configs) or {}
    -- (a dungeon room's template is a story act: with no infinite spawn tiers in it, the sim plays its listed waves,
    -- and the real rooms calibrate the HP)
    if infinite and ld._infinite_bound_level then
        local tiers = false
        for _, cfg in pairs(configs) do if type(cfg) == "table" and cfg.spawn_tier_normal then tiers = true end end
        if not tiers then infinite = false end
    end
    local list = U.list((wdef and (wdef.override_waves or wdef.waves)) or (base and base.waves))
    local ch = C.CAR.challenges and C.CAR.challenges[chId or ld._challenge or ""] or nil
    local red, regen = 0, 0
    for _, bf in pairs(ch and ch.enemy_buffs or {}) do
        if type(bf) == "table" and bf.name == "damage_reduction" then red = red + (tonumber(bf.params and bf.params.reduction) or 0) end
        if type(bf) == "table" and bf.name == "healing" then regen = regen + (tonumber(bf.params and bf.params.percent) or 0) end
    end
    -- (Infinite too: the farm plays it on Hard, and Hard doubles HP there as anywhere. Without it every Infinite map read half its HP until a run calibrated it: Naruto's and
    -- Shibuya's both measured exactly ×2.00, and Shibuya's first prediction said wave 59 for a real 43. A dungeon room keeps its own scale, calibrated over 151 rooms)
    local diffName = ld._difficulty or ((infinite and not ld._dungeon and not ld._infinite_bound_level) and "Hard") or "Normal"
    local diff = ((not infinite) or (not ld._dungeon and not ld._infinite_bound_level)) and (C.GS.DIFFICULTY_HEALTH_SCALES and C.GS.DIFFICULTY_HEALTH_SCALES[diffName]) or 1
    -- (a dungeon room's depth scale: 0.35 at depth 1, rising — taken as enemy HP until real rooms calibrate it)
    local hpRaw = ws * ls * ms * diff * (ch and tonumber(ch.enemy_health_scale) or 1) * (tonumber(ld._lobby_difficulty_scale) or 1)
    -- the world's money scale: kill bounties AND the wave's listed yen are both paid × this (measured ×2.61 in a raid)
    local res = simCall(C.LU.calculate_world_resource_scale, rank, gmW) or 2.6
    local maxT = (wdef and tonumber(wdef.wave_max_time)) or (base and tonumber(base.wave_max_time)) or SIM.PRIOR.waveTimer
    local info = {
        key = key, ld = ld, map = ld.map, infinite = infinite and true or false, list = list, configs = configs, gm = gm,
        -- (Infinite: played until the base falls, so the sim plays on up to SIM.INF_CAP waves)
        -- (a dungeon room whose template lists no waves: 15, the count most rooms have — Spirit Town was simulated
        -- for 80 waves and called a loss)
        -- (every dungeon room ends at wave 15, whatever its template lists: 11 of 11 rooms listed at 20 were won at wave 15)
        total = (type(ld._dungeon) == "table" and 15) or tonumber(ld._override_infinite_bound_waves) or (((not infinite) or ld._infinite_bound_level) and #list > 0 and #list)
            or (ld._infinite_bound_level and 15) or (infinite and SIM.INF_CAP) or 30,
        -- (a map this farm hasn't calibrated yet starts from what other farms measured there: REPORT.hiveHp)
        hpRaw = hpRaw, hpScale = hpRaw * (tonumber(cal.hpCal) or (function() local okH, v = pcall(REPORT.hiveHp, key); return okH and v or nil end)() or 1),
        speedScale = ch and tonumber(ch.enemy_speed_scale) or 1, costScale = ch and tonumber(ch.player_cost_scale) or 1,
        rangeScale = ch and tonumber(ch.player_range_scale) or 1, red = math.min(0.75, red), regen = regen,
        shield = ch and tonumber(ch.enemy_additional_shield) or 0, flyChance = 0,
        bounty = res * (tonumber(cal.bountyCal) or 1), payBase = res, pay = res * (tonumber(cal.yenCal) or 1),
        waveSec = tonumber(cal.waveSec) or SIM.PRIOR.waveSec, walk = SIM.mapWalk(ld.map) or tonumber(cal.walk) or SIM.PRIOR.walk,
        waveTimer = maxT, skipDelay = tonumber(cal.skipDelay) or SIM.PRIOR.skipDelay, autoskip = SIM.autoskip(),
        voteAt = tonumber(cal.voteAt) or maxT / 2, votePer = tonumber(cal.votePer) or SIM.PRIOR.votePer, eff = SIM.effFor(cal), voteWave = type(cal.voteWave) == "table" and cal.voteWave or nil,
        spawnGap = tonumber(cal.spawnGap) or SIM.PRIOR.spawnGap,
        baseHp = tonumber(cal.baseHp) or (wdef and tonumber(wdef.base_health)) or (base and tonumber(base.base_health)) or SIM.PRIOR.baseHp,
        baseRel = tonumber(cal.baseRel) or SIM.PRIOR.baseRel, timerAt = type(cal.timerAt) == "table" and cal.timerAt or {},
        start = tonumber(cal.start) or (ld._dungeon and 2500) or (wdef and tonumber(wdef.initial_resource)) or (base and tonumber(base.initial_resource)) or SIM.PRIOR.start,
        mod = mod, cal = cal, skinSet = HUNT.skinSet(ld), laneList = (B.maps[ld.map] or {}).lanes,
        bossEvery = tonumber(ld._override_infinite_boss_interval) or 10, final = ld._final, skip = ld._skip or {},
        -- (from the lobby every dungeon room reads as a kill box: SIM.run plays it, and that reading was checked against real rooms. In the room the spot search picks the way to stand: MT.planSpots)
        zone = type(ld._dungeon) == "table" and CFG.killZone ~= false,
    }
    info.cfgById = {}
    for k, cfg in pairs(configs) do if type(cfg) == "table" and cfg.unit_id then info.cfgById[cfg.unit_id] = k end end
    if HUNT.is(ld.id) then SIM.applyFx(info, HUNT.fx(HUNT.weatherNow())) end
    return info
end
-- what a dungeon run's items and curses do to a room (DG.fx): your damage, cooldown and range, unit prices, enemy HP,
-- speed and regen. Units in the sim are read from your collection, so without this a team carrying two bows
-- (range ×1.70), a Dagger and a Mage Coat was simulated as if it had bought nothing
function SIM.applyFx(info, fx)
    if not fx then return info end
    info.fx = fx
    info.rangeScale = info.rangeScale * fx.range
    info.costScale = info.costScale * fx.cost
    info.speedScale = info.speedScale * fx.speed
    info.regen = (info.regen or 0) + fx.regen
    info.shield = (info.shield or 0) + (fx.shield or 0)
    info.flyChance = (info.flyChance or 0) + (fx.fly or 0)
    info.noCC, info.shroud = fx.noCC, fx.shroud
    -- (hpRaw too: the real-vs-formula HP reading mustn't take a Curse of Health for a wrong formula)
    info.hpRaw, info.hpScale = info.hpRaw * fx.hp, info.hpScale * fx.hp
    return info
end
-- a unit's damage per second with those: damage ÷ cooldown, its damage type's bonus, a physical unit's added crit
function SIM.fxDps(info, id)
    local fx = info.fx
    if not fx then return 1 end
    local types, base = UNIT.types(id)
    local k = fx.dmg / fx.cd * (1 + (fx.kinds[base] or 0))
    if base == "physical" and fx.crit > 0 then k = k * (1 + fx.crit * 0.5) end
    -- (Blizzard: enemies in Ice shrug off everything but Fire, and fx.hp already counts that for everyone else)
    if fx.fire and (types.fire or types.fire_damage) then k = k * fx.fire end
    return k
end
-- the yen a wave pays when it ends: its listed wave_reward × the world's money scale (the farm units pay on top)
function SIM.waveYen(info, w, scale)
    local raw
    if info.infinite then raw = (C.LU.Infinite and C.LU.Infinite.initial_wave_template and C.LU.Infinite.initial_wave_template.wave_reward) or 1000
    else raw = info.list[w] and tonumber(info.list[w].wave_reward) or 0 end
    return raw * (scale or info.pay or 1)
end
function SIM.waveScale(info, w, waveDef)
    if info.infinite then return simCall(C.LU.Infinite.infinite_diff_scale, w, info.ld.id) or 1 end
    return waveDef and tonumber(waveDef.wave_diff_scale) or 1
end
function SIM.baseStats(info, cfgKey)
    local cfg = info.configs[cfgKey]
    if type(cfg) ~= "table" then return nil end
    local os1 = cfg.override_stats and (cfg.override_stats[1] or cfg.override_stats["1"]) or {}
    return tonumber(os1.health) or 20, tonumber(os1.speed) or 1, tonumber(os1.resource_reward) or 30
end
function SIM.enemy(info, cfgKey, w, waveDef)
    local hp, sp, bounty = SIM.baseStats(info, cfgKey)
    if not hp then return nil end
    hp = hp * info.hpScale * SIM.waveScale(info, w, waveDef)
    -- sh: hits its shield takes (the unit's own, plus a Curse of Shielding or a challenge's). fly: only units that hit flyers reach it
    local d = C.Units[info.configs[cfgKey].unit_id] or {}
    local e = { hp = hp, max = hp, speed = sp * info.speedScale, bounty = bounty * info.bounty, boss = tostring(cfgKey):find("boss") ~= nil, p = 0,
        sh = (tonumber(d.shield) or 0) + (info.shield or 0), fly = type(d.passives) == "table" and d.passives.Flying and true or false }
    SIM.enemyTraits(e, d, hp)
    return e
end
-- what an enemy brings besides its HP (Units[id]). Room 17 on Oct 31 was lost 3 times to these with the sim blind to them: nakime heals 2% of its max HP every second, a hantengu that dies
-- leaves 2 clones with half its HP, and a sakamoto2 has a barrier worth half its HP, taking 25% less while that's up
function SIM.enemyTraits(e, d, hp)
    for _, b in pairs(type(d.buffs) == "table" and d.buffs or {}) do
        if type(b) == "table" and b.name == "healing" and type(b.params) == "table" then
            e.regen = (e.regen or 0) + (tonumber(b.params.percent) or 0) / math.max(0.1, tonumber(b.params.healing_rate) or 1)
        end
    end
    if type(d.barrier) == "table" and tonumber(d.barrier.health_ratio) then
        local red = 0
        for _, b in pairs(type(d.barrier.buffs) == "table" and d.barrier.buffs or {}) do
            if type(b) == "table" and b.name == "damage_reduction" and type(b.params) == "table" then red = red + (tonumber(b.params.reduction) or 0) end
        end
        e.bar = hp * tonumber(d.barrier.health_ratio) / math.max(0.1, 1 - red)
    end
    local ds = d.death_spawn
    if type(ds) == "table" and type(ds.units) == "table" then
        for _, u in pairs(ds.units) do
            if type(u) == "table" and tonumber(u.health_ratio) then
                e.split = { n = tonumber(ds.amount) or 1, ratio = tonumber(u.health_ratio), unit = u.unit }
                break
            end
        end
    end
end
-- the enemies of wave w: the level's own list, or the infinite curves (count, mix by spawn tier, a boss every N waves)
function SIM.wave(info, w, raw)
    local out = {}
    if not info.infinite then
        local wd = info.list[w]
        if not wd then return out, 0 end
        for _, g in ipairs(U.list(wd.wave)) do
            for _ = 1, tonumber(g.amount) or 1 do
                local e = SIM.enemy(info, g.unit, w, wd)
                if e then table.insert(out, e) end
            end
        end
    else
        local n = simCall(C.LU.Infinite.infinite_amt_scale, w, info.ld) or 10
        local weights, tot = {}, 0
        for k, cfg in pairs(info.configs) do
            if type(cfg) == "table" and cfg.spawn_tier_normal then
                local c = simCall(C.LU.Infinite.infinite_get_normal_unit_chance, cfg, w) or 0
                if c > 0 then table.insert(weights, { k = k, c = c }); tot = tot + c end
            end
        end
        table.sort(weights, function(a, b) return a.k < b.k end)
        local want, made = math.floor(n + 0.5), 0
        for i, wt in ipairs(weights) do
            local cnt = (i == #weights) and math.max(0, want - made) or math.floor(want * wt.c / tot + 0.5)
            for _ = 1, cnt do local e = SIM.enemy(info, wt.k, w); if e then table.insert(out, e) end end
            made = made + cnt
        end
        -- a dungeon room's last wave brings a boss, which the sim never played: it called a final boss easy that real
        -- runs couldn't kill. The final room's is the highest tier (seen: boss_puppet, 36.64M HP, exactly this formula). Other
        -- rooms' bosses are drawn from the tiers: the one nearest their average HP stands in until real rooms say more
        local lastBoss = info.ld._infinite_bound_level and w == info.total
        if lastBoss then
            local list, sum = {}, 0
            for k, cfg in pairs(info.configs) do
                if type(cfg) == "table" and tonumber(cfg.spawn_tier_boss) and (simCall(C.LU.Infinite.infinite_get_boss_unit_chance, cfg, w) or 0) > 0 then
                    local hp = SIM.baseStats(info, k)
                    if hp then table.insert(list, { k = k, hp = hp, tier = tonumber(cfg.spawn_tier_boss) }); sum = sum + hp end
                end
            end
            table.sort(list, function(a, b) return a.tier > b.tier end)
            local final = type(info.ld._dungeon) == "table" and (tonumber(info.ld._dungeon.depth) or 0) >= 20
            local pick = list[1]
            if pick and not final then
                local mean = sum / #list
                for _, x in ipairs(list) do if math.abs(x.hp - mean) < math.abs(pick.hp - mean) then pick = x end end
            end
            if pick then
                local e = SIM.enemy(info, pick.k, w)
                if e then e.boss = true; table.insert(out, e) end
            end
        elseif w % info.bossEvery == 0 and not info.skip[tostring(w)] then
            local tier = math.max(1, math.min(6, math.floor(w / info.bossEvery)))
            for k, cfg in pairs(info.configs) do
                if type(cfg) == "table" and tonumber(cfg.spawn_tier_boss) == tier then
                    local e = SIM.enemy(info, k, w); if e then e.boss = true; table.insert(out, e) end
                    break
                end
            end
        end
        if info.final and tonumber(info.final.wave) == w and info.final.cfg then
            local e = SIM.enemy(info, info.final.cfg, w); if e then e.boss = true; table.insert(out, e) end
        end
    end
    -- measured enemies-per-wave correction (real count / formula count), applied by copying enemies
    local cc = tonumber(info.cal and info.cal.countCal)
    if cc and not raw and math.abs(cc - 1) > 0.05 and #out > 0 then
        local want = math.max(1, math.floor(#out * cc + 0.5))
        local n0 = #out
        if want > n0 then
            for i = 1, want - n0 do local src = out[((i - 1) % n0) + 1]; table.insert(out, table.clone(src)) end
        else
            for _ = 1, n0 - want do table.remove(out) end
        end
    end
    return out, SIM.waveYen(info, w)
end
-- which part of the road the best spot covers at a range (measured per map; a generic guess until then)
SIM._masks = {}
-- how fast enemies walk on a map: the share of its road a second at speed ×1. It goes with the road's length, so it belongs to the map, not the mode: across 25 maps 355 s for the whole road (Overlord's Tomb) down to 83 s (Attack on Titan), and within a map mostly the same to 5%.
-- Dungeon rooms blended all their maps into one, 215 s, so on Attack on Titan's road enemies reached the base 2.6× sooner than the simulator read. The map's own record, kept up by every run there, else what its story acts and raids measured, else nil
SIM._walk = {}
function SIM.mapWalk(map)
    if not map then return nil end
    if SIM._walk[map] ~= nil then return SIM._walk[map] or nil end
    local v = B.maps[map] and tonumber(B.maps[map].walk)
    if not v then
        local l = {}
        for key, cal in pairs(B.simCal) do
            local id = type(cal) == "table" and tonumber(cal.walk) and (tostring(key):match("^st:([^:]+)") or tostring(key):match("^rd:([^:]+)") or tostring(key):match("^inf:([^:]+)"))
            local lv = id and C.Levels[id]
            if lv and lv.map == map then table.insert(l, tonumber(cal.walk)) end
        end
        if #l > 0 then
            table.sort(l)
            v = l[math.ceil(#l / 2)]
        end
    end
    SIM._walk[map] = v or false
    return v
end
function SIM.mask(map, range)
    local rb = math.max(5, math.min(60, math.floor((range or 10) / 5 + 0.5) * 5))
    local key = tostring(map) .. ":" .. rb
    if SIM._masks[key] then return SIM._masks[key] end
    local m = B.maps[map]
    local s = m and m.bins and m.bins[tostring(rb)]
    local mask = {}
    if type(s) == "string" and #s == SIM.BINS then
        for i = 1, SIM.BINS do mask[i] = s:sub(i, i) == "1" end
        -- (and each lane's own, on a map with more than one)
        local per = m.binsL and m.binsL[tostring(rb)]
        if type(per) == "table" then
            mask.lanes = {}
            for l, str in pairs(per) do
                local lm = {}
                for i = 1, SIM.BINS do lm[i] = str:sub(i, i) == "1" end
                mask.lanes[l] = lm
            end
        end
    else
        local f = math.min(0.7, rb / 70)
        for i = 1, SIM.BINS do local p = (i - 0.5) / SIM.BINS; mask[i] = p >= 0.1 and p <= 0.1 + f end
    end
    SIM._masks[key] = mask
    return mask
end
-- a map's lanes, by name, when it has more than one (the road samples carry them, MT.buildPath)
function SIM.laneList(samples)
    local seen, list = {}, {}
    for _, s in ipairs(samples or {}) do
        local l = tostring(s.lane)
        if s.lane ~= nil and not seen[l] then seen[l] = true; table.insert(list, l) end
    end
    table.sort(list)
    return #list >= 2 and list or nil
end
-- the road a unit reaches from one real spot (MT.planSpots: the map's samples are at hand in a match), kept per spot and
-- range. SIM.mask above gives every unit the best road for its range, so it can't tell one spot from another
function SIM.spotMask(layout, spot, range)
    local r = math.floor(range + 0.5)
    local key = string.format("%d,%d,%d", spot.X, spot.Z, r)
    local m = layout.cache[key]
    if m then return m end
    m = {}
    local r2 = r * r
    local multi = SIM.laneList(layout.samples) ~= nil
    if multi then m.lanes = {} end
    for _, s in ipairs(layout.samples) do
        local dx, dz = s.pos.X - spot.X, s.pos.Z - spot.Z
        if dx * dx + dz * dz <= r2 then
            local bin = math.min(SIM.BINS, math.floor(s.prog * SIM.BINS) + 1)
            m[bin] = true
            if multi then
                local l = tostring(s.lane)
                m.lanes[l] = m.lanes[l] or {}
                m.lanes[l][bin] = true
            end
        end
    end
    layout.cache[key] = m
    return m
end
function SIM.teamFrom(units, map)
    local team = {}
    local hillOk = not (B.maps[map] and B.maps[map].hill == false)
    for _, u in ipairs(units) do
        local d = C.Units[u.unit_id]
        local rows = d and UNIT.rows(u.unit_id)
        if rows then
            table.insert(team, { u = u, id = u.unit_id, data = d, rows = rows, cap = UNIT.cap(u), farm = UNIT.isFarm(u.unit_id),
                placeable = (not d.hill_unit) or hillOk })
        end
    end
    return team
end
function SIM.sig(units)
    local ids = {}
    for _, u in ipairs(units) do table.insert(ids, tostring(u.unit_id)) end
    table.sort(ids)
    return table.concat(ids, ",")
end
-- one simulated run: a wave ends on its timer or (auto-skip) once cleared, enemies walk the road, each unit hits
-- the furthest enemy on the part of the road it covers (area attacks spill onto the next ones), yen from waves
-- (× the world's money scale), kills and farm units, buys made by ECON.decide like the live farm.
-- opt.train = a unit uuid: count its takedowns (enemies it hit that died) and buy for it like the live farm does.
-- Returns {won, wave, t, aliveAt, dpsAt, spentAt, money, tk}
-- how much road a unit stacked in a kill box really reaches: a straight stretch through its circle, 2 × range. SIM.mask is the map's best spot for that range, often a bend, which on the Daily read 15-25% where real spots in the box reach 7-15%: twice the time under fire, so 7 enemies of 16.9M
-- HP that really walked to the base died on the way (Nov 2). The road's length comes from how fast enemies cross it (about 1.9 studs a second at speed ×1)
SIM.WALK_STUDS = 1.9
function SIM.boxBins(info, reach, width)
    local frac = 2 * (reach or 0) * (tonumber(info.walk) or SIM.PRIOR.walk) / SIM.WALK_STUDS
    return math.max(1, math.min(width, math.floor(frac * SIM.BINS + 0.5)))
end
-- a unit that holds enemies: a stun, a freeze or a slow at any upgrade (some only get one from a later upgrade, which counted for nothing before), or a switch ability with a bar
-- (UNIT.toggleOf: Snow Reaper (Final)'s Gale, and any unit this farm or the brain hive has seen with one). Second value: the upgrade it starts at
SIM._holds, SIM._holdsFrom = {}, {}
function SIM.holds(id)
    local v = SIM._holds[id]
    if v == nil then
        v = false
        local okT, tg = pcall(UNIT.toggleOf, id)
        if okT and tg then v, SIM._holdsFrom[id] = true, tonumber(tg.from) or 1 end
        local rows = not v and UNIT.rows(id)
        for l = 0, rows and rows.max or -1 do
            local r = rows[l]
            local okA, a = false, nil
            if r then okA, a = pcall(UNIT.attackInfo, r.atk, r.range) end
            if okA and a and ((a.stun or 0) > 0 or (a.slowTime or 0) > 0) then v, SIM._holdsFrom[id] = true, l; break end
        end
        SIM._holds[id] = v
    end
    return v, SIM._holdsFrom[id]
end
-- how much a Gale (UNIT.GALE) slows the enemies under it, at full cover: the game doesn't say. Set from the Daily Challenge trial, Nov 2 (_test_galesim.lua)
SIM.GALE_SLOW = 0.3
function SIM.run(info, team, opt)
    opt = opt or {}
    local hpMul = opt.hpMul or 1
    local dt = SIM.DT
    local tk = 0
    -- lanes: on a map with more than one, each enemy walks one of them (in turn: Shibuya's split 13 and 16 as they came out), and a unit hits it only where its circle
    -- reaches that lane. Its road by progress alone credited a unit on one lane with the other's enemies too (opt.noLanes: the old way, for comparing)
    if opt.layout and opt.layout.laneList == nil then opt.layout.laneList = SIM.laneList(opt.layout.samples) or false end
    local laneList = not opt.noLanes and ((opt.layout and opt.layout.laneList) or info.laneList) or nil
    local nLanes, laneN = laneList and #laneList or 0, 0
    local function reaches(c, e, bin)
        local lm = nLanes >= 2 and e.lane and c.mask.lanes
        if lm then local l = lm[e.lane]; return l ~= nil and l[bin] == true end
        return c.mask[bin] and true or false
    end
    local money, t, wave, nextWave = info.start, 0, 0, 3
    local queue, alive, copies, hist, aliveAt, maxProg, incomeLog = {}, {}, {}, {}, {}, {}, {}
    local dpsAt, spentAt = {}, {}
    local baseHp = info.baseHp
    local rewards = {}
    for i = 1, info.total do rewards[i] = SIM.waveYen(info, i) end
    local paid = true -- the current wave already paid (wave 0 pays nothing)
    local firstWave = SIM.wave(info, 1, true)
    local function unitDps(e, lvl, noGale) return UNIT.dps(e.u, lvl, info.mod, noGale) * (1 - info.red) * SIM.fxDps(info, e.id) * UNIT.skinMul(e.u, info.skinSet) end
    -- the team's hardest single hit at placement
    local heavyId, heavyHit = nil, 0
    for _, e in ipairs(team) do
        local r0 = e.rows[0]
        if not e.farm and r0 then
            local h = unitDps(e, 0) * (tonumber(r0.cd) or 2) / math.max(1, UNIT.attackInfo(r0.atk, r0.range).n)
            if h > heavyHit then heavyId, heavyHit = e.id, h end
        end
    end
    local curS = 0
    for _, e in ipairs(firstWave) do curS = curS + (e.sh or 0) end
    curS = #firstWave > 0 and curS / #firstWave or 0
    local eff = info.eff or SIM.PRIOR.eff
    local waveHp = {}
    local function hpOf(w)
        if w > info.total then return nil end
        if not waveHp[w] then
            local h = 0
            for _, e in ipairs((SIM.wave(info, w))) do h = h + e.hp + (e.bar or 0) end
            waveHp[w] = h * hpMul
        end
        return waveHp[w]
    end
    -- takedown training: the trainee stands where enemies come before your other attackers reach them (live:
    -- MT.bestSpot), so its stretch of road ends at the first bin they cover
    local upstream
    if opt.train then
        upstream = SIM.BINS
        for _, e in ipairs(team) do
            if not e.farm and e.u.uuid ~= opt.train then
                local mk = SIM.mask(info.map, UNIT.range(e.u, 0) * info.rangeScale)
                for i = 1, SIM.BINS do if mk[i] then upstream = math.min(upstream, i); break end end
            end
        end
    end
    -- abilities: Chuuni's marks, Iron Sentinel's drones, actives with their own timers
    local marking, markAmp, markMax, galeOn = false, 0, 1, false
    local drones, actNext = {}, {}
    local cdBuffTo, cdBuffR, safeTo = 0, 0, 0
    -- a stacked room (MT.bestSpot's kill zone): each attacker reaches back from the road's end as far as its range goes, measured on the road
    -- on Nov 1: Iron Sentinel 73-99% of the road, Chuuni 82-99%, a level-0 Mochi 84-95%. SIM.mask's stretch at the road's start has the same
    -- length but the wrong place: enemies got there at once, before the waves had paid for anything, and whatever got past walked to the base
    -- unhurt, so rooms 18 and 20 read "0 of 15" and were won. (Later copies stand a little further back, the best spots being taken)
    local stacked = info.zone and not opt.noZone and not opt.layout
    -- (a layout under test plays its first copies on their spots, and the later ones follow its style: a kill box's stack up behind them, a fast clear's stand at the road's start, MT.bestSpot)
    local layStyle = opt.layout and opt.layout.style
    local stackLater = stacked or layStyle == "box"
    local function refresh(c)
        -- (a Gale is played below as an aura: the attack alone hits. dpsAll, with its average, is what an upgrade's gain is weighed against)
        c.dps = c.e.farm and 0 or unitDps(c.e, c.lvl, true)
        c.dpsAll = c.e.farm and 0 or unitDps(c.e, c.lvl)
        local g = UNIT.galeOf(c.e.id)
        c.gale = g and c.lvl >= g.from and g or nil
        if c.gale then galeOn = true end
        -- (a layout under test: a unit's first copy stands on its spot; opt.layout = {samples, cache, spots = [id] = spot})
        local spot = opt.layout and not c.later and opt.layout.spots[c.e.id]
        local reachNow = UNIT.range(c.e.u, c.lvl) * info.rangeScale * (UNIT.SUMMONER[c.e.id] and UNIT.SUMMONER[c.e.id].reach or 1)
        c.mask = spot and SIM.spotMask(opt.layout, spot, reachNow) or SIM.mask(info.map, reachNow)
        if (stacked or (layStyle == "box" and c.later)) and not c.e.farm and c.e.u.uuid ~= opt.train then
            local width = 0
            for i = 1, SIM.BINS do if c.mask[i] then width = width + 1 end end
            width = SIM.boxBins(info, reachNow, width)
            local hi = c.later and SIM.BINS - 1 or SIM.BINS
            local m2 = {}
            for i = 1, SIM.BINS do m2[i] = i > hi - width and i <= hi end
            c.mask = m2
        end
        if layStyle == "fast" and c.later and not c.e.farm and c.e.u.uuid ~= opt.train then
            local width = 0
            for i = 1, SIM.BINS do if c.mask[i] then width = width + 1 end end
            local m2 = {}
            for i = 1, SIM.BINS do m2[i] = i <= width end
            c.mask = m2
        end
        -- a control unit in a kill box stands along it, each copy on its own part, as live (MT.controlSpot). Stacked on the road's last stretch it reached nobody: enemies die before they get there, so 4 real Frost Navy had dealt nothing by wave 18 and this read 0.2 of 82 enemies held,
        -- where spread along the box a real run holds 0.5-1 with Frost Navy and 1-2 with Ice Lily
        if stackLater and c.ctlN and c.e.u.uuid ~= opt.train then
            local width = 0
            for i = 1, SIM.BINS do if c.mask[i] then width = width + 1 end end
            width = math.max(1, width)
            local lo, hi
            for _, o in ipairs(copies) do
                if o ~= c and not o.ctlN and not o.e.farm and not o.buff and o.mask then
                    for i = 1, SIM.BINS do if o.mask[i] then lo, hi = math.min(lo or i, i), math.max(hi or i, i) end end
                end
            end
            lo, hi = lo or 16, hi or SIM.BINS
            local target = ({ lo, hi, (lo + hi) / 2, lo - (hi - lo) / 2 })[c.ctlN]
            if target then
                local from = math.max(1, math.min(SIM.BINS - width + 1, math.floor(target - (width - 1) / 2 + 0.5)))
                local m2 = {}
                for i = 1, SIM.BINS do m2[i] = i >= from and i <= from + width - 1 end
                c.mask = m2
            end
        end
        if upstream and c.e.u.uuid == opt.train then
            local width = 0
            for i = 1, SIM.BINS do if c.mask[i] then width = width + 1 end end
            local lo = math.max(1, upstream - width + 1)
            local m2 = {}
            for i = 1, SIM.BINS do m2[i] = i >= lo and i <= math.min(SIM.BINS, lo + width - 1) end
            c.mask = m2
        end
        -- (shields, and no map's spots to go by: the hardest hitter stands right behind the others' stretch, so it isn't wasting
        -- its hits on shields they could break first. The spot search finds that layout in a match: Iron at 111,25, the rest before it)
        if not stacked and not opt.layout and not c.later and not c.lo and c.e.id == heavyId and curS > 0 then
            local width = 0
            for i = 1, SIM.BINS do if c.mask[i] then width = width + 1 end end
            c.lo = width + 1
        end
        -- (bought while an enemy was past every unit's reach: it stands further down the road, ahead of that enemy)
        if c.lo then
            local width = 0
            for i = 1, SIM.BINS do if c.mask[i] then width = width + 1 end end
            local lo = math.max(1, math.min(c.lo, SIM.BINS - width + 1))
            local m2 = {}
            for i = 1, SIM.BINS do m2[i] = i >= lo and i <= lo + width - 1 end
            c.mask = m2
        end
        c.width = 0
        for i = 1, SIM.BINS do if c.mask[i] then c.width = c.width + 1 end end
        local r = c.e.rows[math.min(c.lvl, c.e.rows.max)]
        -- (enemies hit, not UNIT.aoe: damage over time stays on the enemy that was hit. Counted as spill onto other
        -- enemies it vanished against a lone boss, so no DoT unit could ever look good there)
        local ai = UNIT.attackInfo(r.atk, r.range)
        c.aoe, c.hits, c.bleed = ai.n, ai.hits, ai.bleed
        c.stun, c.slowP, c.slowT, c.ccCd = ai.stun, ai.slowPct, ai.slowTime, ai.ccCd or 8
        local _, base = UNIT.types(c.e.id)
        c.base = base
        c.buff = UNIT.allyBuff(c.e.id)
        c.fx = c.e.farm and 0 or UNIT.teamEffect(r.atk, r.range, r.cd, true)
        c.breaks = ai.breakShields
        c.mark = UNIT.passive(c.e.id).mark
        if c.mark then marking = true end
        c.drone = UNIT.DRONES[c.e.id]
        c.droneNow = c.drone and (c.lvl >= c.drone.from and c.drone.late or c.drone.early) or nil
        -- its active ability, once an upgrade gives it one (damage buffs for the team go by c.buff; summons aren't played)
        local act = r.active and UNIT.attackInfo(r.active)
        c.act = act and not c.buff and (act.stun > 0 or act.allyCd or act.selfDmg or act.baseSafe) and act or nil
        c.actId, c.actCd = r.active, tonumber(r.activeCd) or 60
        c.train = opt.train ~= nil and c.e.u.uuid == opt.train
        c.cd = (tonumber(r.cd) or 2) * (info.fx and info.fx.cd or 1)
        local from = UNIT.airFrom(c.e.id)
        c.air = from ~= nil and c.lvl >= from
    end
    -- flyers: the live farm weighs units that hit them once they come (MT.airWeight, MT.airBoost, MT.airNeed). Shields: what's
    -- on the way, for what a hit is worth against them (ECON.shieldDps)
    local flySeen, flyAcc = (info.flyChance or 0) > 0, opt.flyAcc or 0
    local curH, curN = 1, 1
    local function waveShield(list)
        local s, h = 0, 0
        for _, e in ipairs(list) do s = s + (e.sh or 0); h = h + e.hp end
        if #list > 0 then curS, curH, curN = s / #list, h / #list, #list end
    end
    waveShield(firstWave)
    local cdMul = info.fx and info.fx.cd or 1
    -- the team's buffs (by damage type) and its crowd control / debuffs, from what's on the field
    -- (a buff measured to add up with a 2nd copy (B.stack) is summed up to its cap; others count once)
    local typeMult, teamMult, cover = {}, 1, nil
    local function stackCap(b) local s = B.stack[b.attack]; return s and s.stacks and (s.cap or 1) or nil end
    local function teamFx()
        table.clear(typeMult)
        local fx, last = 0, 0
        local summed = {}
        -- (copies take turns: two Windsongs at 30 s on a 60 s cooldown keep it up all the time)
        local turns = {}
        for _, c in ipairs(copies) do if c.buff then turns[c.buff.attack] = (turns[c.buff.attack] or 0) + 1 end end
        for _, c in ipairs(copies) do
            if c.buff then
                local cap = stackCap(c.buff)
                for k, rate in pairs(c.buff.types) do
                    if cap then
                        summed[k] = math.min(cap, (summed[k] or 0) + rate * c.buff.uptime)
                        typeMult[k] = math.max(typeMult[k] or 0, summed[k])
                    else typeMult[k] = math.max(typeMult[k] or 0, rate * math.min(1, turns[c.buff.attack] * c.buff.uptime)) end
                end
            end
            fx = fx + (c.fx or 0)
            -- the furthest part of the road any attacker reaches
            if c.dps > 0 then for i = SIM.BINS, last + 1, -1 do if c.mask[i] then last = i; break end end end
        end
        teamMult = 1 + math.min(0.6, fx)
        cover = last > 0 and last / SIM.BINS or nil
    end
    local function realDps(c)
        local v = c.dps * teamMult * (1 + (typeMult[c.base] or 0))
        if t < cdBuffTo then v = v / (1 - cdBuffR) end
        if t < (c.selfTo or 0) then v = v * (1 + c.selfAdd) end
        return v
    end
    -- the share of your damage that hits flyers, and the weight a unit that hits them gets from it
    local function airW(id, lvl, placing)
        if not flySeen then return 1 end
        local from = UNIT.airFrom(id)
        if not from then return 1 end
        local tot, air = 0, 0
        for _, c in ipairs(copies) do
            local v = realDps(c)
            tot = tot + v
            if c.air then air = air + v end
        end
        local w = (tot > 0 and air / tot or 0) < 0.5 and 2.5 or 1.5
        if placing then return from == 0 and w or 1 + (w - 1) * 0.4 end
        return lvl >= from and w or 1 + (w - 1) * math.min(1, (lvl + 1) / math.max(1, from))
    end
    -- the share of the team's damage that's left once the shields on the way have taken their hits
    local function teamShield()
        local tot, left = 0, 0
        for _, c in ipairs(copies) do
            local v = realDps(c)
            tot = tot + v
            left = left + ECON.shieldDps(v, c.cd, c.aoe, curS, curH, eff, c.hits)
        end
        return tot > 0 and math.max(0.05, left / tot) or 1
    end
    local function buffGain(e)
        local b = UNIT.allyBuff(e.id)
        if not b then return 0 end
        local n = 0
        for _, c in ipairs(copies) do if c.buff and c.buff.attack == b.attack then n = n + 1 end end
        local cap = stackCap(b)
        if n >= UNIT.buffCopies(b) and not cap then return 0 end
        local g = 0
        for _, c in ipairs(copies) do
            local rate = b.types[c.base]
            if rate then
                local add = cap and math.max(0, math.min(cap, (n + 1) * rate * b.uptime) - math.min(cap, n * rate * b.uptime)) or rate * b.uptime
                g = g + c.dps * add
            end
        end
        return g
    end
    -- a wave pays its yen and the farm units when it ends: cleared (auto-skip → the next wave a few seconds
    -- later) or out of time
    local function pay()
        if paid then return end
        paid = true
        local got = rewards[wave] or 0
        for _, c in ipairs(copies) do if c.e.farm then got = got + UNIT.farm(c.e.u, c.lvl) end end
        money = money + got
        table.insert(incomeLog, { t = t, y = got })
    end
    -- what the live farm weighs an upgrade by, beside its damage: how much road the unit reaches against your other attackers (MT.reach: Gene got
    -- level 6 here and level 1 in the real room, Iron Sentinel level 7 and level 10), and on the last wave whether it can hit the boss (MT.focusGain)
    local function reachOf(c)
        if opt.oldBuy then return 1 end
        local sum, n = 0, 0
        for _, o in ipairs(copies) do
            if not o.e.farm then sum, n = sum + (o.width or 0), n + 1 end
        end
        if n == 0 or sum <= 0 then return 1 end
        return U.clamp((c.width or 0) / (sum / n), 0.4, 1.6)
    end
    -- (ECON.holdGain, the same as MT.holdGain live. A unit that can't hit flyers holds only the rest)
    local function holdOf(e, ai)
        if opt.oldBuy or opt.noHold or ((ai.stun or 0) <= 0 and (ai.slowTime or 0) <= 0) then return 0 end
        local have, total, width = 0, 0, 0
        for _, o in ipairs(copies) do
            if (o.stun or 0) > 0 or (o.slowT or 0) > 0 then have = have + 1 end
            total = total + realDps(o)
        end
        local mask = SIM.mask(info.map, UNIT.range(e.u, 0) * info.rangeScale)
        for i = 1, SIM.BINS do if mask[i] then width = width + 1 end end
        local share = width / (math.max(0.1, cover or 1) * SIM.BINS)
        local from = UNIT.airFrom(e.id)
        local ground = (from == 0) and 1 or (1 - (1 - C.FLY_GROUND) * math.min(1, info.flyChance or 0))
        return ECON.holdGain(ai, total, share * ground, have)
    end
    local function focusOf(c)
        if opt.oldBuy or wave < info.total or #alive == 0 or #alive > 2 then return 1 end
        local boss = alive[1]
        for _, e in ipairs(alive) do if e.hp > boss.hp then boss = e end end
        if boss.fly and not c.air then return C.FLY_GROUND end
        local bin = math.min(SIM.BINS, math.floor(boss.p * SIM.BINS) + 1)
        if c.mask[bin] then return 1 end
        return (c.mask[math.max(1, bin - 2)] or c.mask[math.min(SIM.BINS, bin + 2)]) and 0.3 or 0.02
    end
    -- one unit (or drone) hitting for a moment of the fight
    local airOrder
    local function attack(c, d)
        -- (eff is the share that lands across a crowd: overkill, gaps between targets. Against a boss left alone
        -- every hit lands — measured: Iron Sentinel's 475k a second on paper, about 550k with the team really taken off
        -- the boss, where 49% would have left it under the 366k regen and the fight unwinnable)
        local landed = (wave >= info.total and #alive <= 2) and math.max(eff, 0.95) or eff
        -- (hits count one by one: a hit lands whole unless the enemy has less HP than it does. eff's average would have Iron Sentinel's 120k hit take 3 attacks to kill a 92k enemy with shields around, and it
        -- cut a 3k hit on a 30k enemy to 50% too, on a share measured from units that overkill: why Spirit Reaper (Final Dusk) read as falling at wave 11, when real runs have him through wave 14 on his own)
        if alive[1] and not opt.oldBuy then
            local perHit = d * math.max(0.3, c.cd) / math.max(1, c.aoe)
            landed = math.max(landed, math.min(opt.landCap or ((curS > 0 or c.aoe <= 1.01) and 0.95 or SIM.LAND_CAP), curH / math.max(1, perHit)))
        end
        local one = d * landed * dt / c.aoe
        local spill = d * landed * dt - one
        local hit = 0
        -- the trainee tags enemies at its real attack rate (one attack every cd seconds, up to its area)
        local swing = false
        if c.train then c.tag = (c.tag or 0) + dt / math.max(0.3, c.cd); swing = c.tag >= 1 end
        local ccNow = (c.stun > 0 or c.slowT > 0) and t >= (c.ccAt or 0) and not info.noCC
        local magic = c.base == "magic"
        for _, e in ipairs(c.air and airOrder or alive) do
            if e.hp > 0 and reaches(c, e, math.min(SIM.BINS, math.floor(e.p * SIM.BINS) + 1)) and not (info.shroud and e.p < info.shroud) then
                local half = e.fly and not c.air
                if c.bleed then e.noRegen = t + 5 end
                if c.drone then e.droneBy = c end
                -- (not on a boss, and an enemy can't be held again until its immunity runs out. A ground attack doesn't stun or slow a flyer)
                if ccNow and not e.boss and not half and t >= (e.ccFree or 0) then
                    if c.stun > 0 then e.stunTo, e.ccFree = t + c.stun, t + c.stun + c.ccCd
                    else e.slowTo, e.slowP, e.ccFree = t + c.slowT, c.slowP, t + c.slowT + c.ccCd end
                end
                -- a shield counts hits, not HP: each hit takes one off and does no damage, whatever its size. True damage
                -- goes through it, a multi-hit attack takes several off, and Crush (Ace) breaks it whole
                if (e.sh or 0) > 0 and c.base ~= "true" then
                    if c.breaks then e.sh = 0
                    elseif hit < math.ceil(c.aoe) then e.sh = e.sh - c.hits * dt / math.max(0.3, c.cd) end
                else
                    local k = (magic and e.marks) and 1 + markAmp * math.min(markMax, e.marks) or 1
                    local part = hit == 0 and one or math.min(one, spill)
                    if opt.dealt then
                        local who = c.owner and "drones" or UNIT.name(c.e.id)
                        opt.dealt[who] = (opt.dealt[who] or 0) + math.min(part * k, math.max(0, e.hp) + (e.bar or 0))
                    end
                    -- (a barrier takes the damage first)
                    local lands = part * k * (half and C.FLY_GROUND or 1)
                    if e.bar then
                        local into = math.min(e.bar, lands)
                        e.bar, lands = e.bar - into, lands - into
                        if e.bar <= 0 then e.bar = nil end
                    end
                    e.hp = e.hp - lands
                    if hit > 0 then spill = spill - part end
                end
                if swing and hit < math.ceil(c.aoe) then e.tr = true end
                hit = hit + 1
                if hit > math.ceil(c.aoe) or (hit > 1 and spill <= 0) then break end
            end
        end
        if swing and hit > 0 then c.tag = c.tag - 1 end
        if ccNow and hit > 0 then c.ccAt = t + math.max(0.3, c.cd) end
    end
    -- active abilities, by the live farm's rules (MT.actives): at a boss or a crowd, or after holding a while for one
    local function fireActives(front)
        if CFG.actives == false then return end
        for _, c in ipairs(copies) do
            local a = c.act
            local key = a and (a.globalCd and c.actId or c)
            if a and t >= (actNext[key] or 0) then
                c.actReady = c.actReady or t
                local near, boss = 0, false
                for _, e in ipairs(alive) do
                    if a.wholeMap or reaches(c, e, math.min(SIM.BINS, math.floor(e.p * SIM.BINS) + 1)) then
                        near = near + 1
                        if e.boss then boss = true end
                    end
                end
                local hold = math.min((tonumber(CFG.abilityHold) or 20) * math.max(1, c.actCd / 60), c.actCd * 0.3)
                local fire
                if a.baseSafe then fire = front >= 0.98
                elseif a.allyCd then fire = #alive > 0
                else fire = (near > 0 and boss) or near >= math.max(3, math.floor(#alive * 0.3)) or (near >= 3 and t - c.actReady >= hold * 0.5) or (near >= 1 and t - c.actReady >= hold) end
                if fire then
                    actNext[key], c.actReady = t + c.actCd, nil
                    if a.baseSafe then safeTo = t + a.baseSafe end
                    if a.allyCd then
                        cdBuffR = t < cdBuffTo and math.max(cdBuffR, a.allyCd.reduce) or a.allyCd.reduce
                        cdBuffTo = t + a.allyCd.time
                    end
                    if a.selfDmg then c.selfTo, c.selfAdd = t + a.selfDmg.time, a.selfDmg.add end
                    if a.stun > 0 then
                        for _, e in ipairs(alive) do
                            if (a.wholeMap or reaches(c, e, math.min(SIM.BINS, math.floor(e.p * SIM.BINS) + 1))) and not e.boss and t >= (e.ccFree or 0) then
                                e.stunTo, e.ccFree = t + a.stun, t + a.stun + (a.ccCd or 8)
                            end
                        end
                    end
                end
            end
        end
    end
    local steps, voteT, lastCash = 0, math.huge, false
    while t < 3600 do
        -- the wave ends early: cleared, or (auto-skip) the skip vote passes
        if not paid and wave > 0 and ((#queue == 0 and #alive == 0) or (info.autoskip and t >= voteT)) then
            pay()
            nextWave = math.min(nextWave, t + info.skipDelay)
        end
        if wave < info.total and t >= nextWave then
            pay()
            wave = wave + 1
            local a = 0
            for _, e in ipairs(alive) do a = a + e.hp end
            aliveAt[wave] = a
            local d = 0
            for _, c in ipairs(copies) do d = d + realDps(c) end
            dpsAt[wave] = d
            local list = SIM.wave(info, wave)
            -- enemies come out one after another; the wave's timer runs its spawning time + the level's wave time
            for i, e in ipairs(list) do
                e.hp = e.hp * hpMul; e.max = e.hp
                if e.bar then e.bar = e.bar * hpMul end
                e.at = t + (i - 1) * info.spawnGap
                -- (a Curse of Flight turns a share of them into flyers)
                if not e.fly and (info.flyChance or 0) > 0 then
                    flyAcc = flyAcc + info.flyChance
                    if flyAcc >= 1 then flyAcc = flyAcc - 1; e.fly = true end
                end
                if e.fly then
                    flySeen = true
                    -- (the Summer update's flyers: more HP in these modes)
                    local more = (C.GS.FLYING_HEALTH_MUL or {})[(C.Worlds[info.ld.world or ""] or {}).legend_stage and "legend_stage" or (info.ld._event_contract and "event_contract") or (info.gm == "story" and "story") or ""]
                    if more then e.hp = e.hp * (1 + more); e.max = e.hp end
                end
                if nLanes >= 2 then laneN = laneN + 1; e.lane = laneList[(laneN - 1) % nLanes + 1] end
                table.insert(queue, e)
            end
            waveShield(list)
            paid = false
            nextWave = t + math.max(tonumber(info.timerAt[tostring(wave)]) or info.waveTimer, #list * info.spawnGap + 5)
            voteT = t + SIM.voteSec(info, wave)
        end
        for i = #queue, 1, -1 do if queue[i].at <= t then table.insert(alive, table.remove(queue, i)) end end
        local front = 0
        for _, e in ipairs(alive) do
            -- (stunned stands still, slowed walks slower: why a slow unit like Mochi holds a road a stronger unit can't)
            local pace = e.speed
            if (e.stunTo or 0) > t then pace = 0
            else
                local s = (e.slowTo or 0) > t and (e.slowP or 0) or 0
                pace = pace * (1 - math.max(s, e.galeSlow or 0))
            end
            if e.p < 1 then e.p = math.min(1, e.p + info.walk * pace * dt) elseif t >= safeTo then baseHp = baseHp - info.baseRel * e.max * dt end
            -- (bleed and wither stop regen while they last, the game's own Effects page; hits don't, measured on a boss)
            local heal = info.regen + (e.regen or 0)
            if heal > 0 and (e.noRegen or 0) <= t then e.hp = math.min(e.max, e.hp + e.max * heal * dt) end
            if e.p > front then front = e.p end
        end
        maxProg[wave] = math.max(maxProg[wave] or 0, front)
        table.sort(alive, function(a, b) return a.p > b.p end)
        -- flyers on the road: units that can hit them go for them first (live: their targeting goes to "flying"), and
        -- the others can't touch them
        airOrder = nil
        for _, e in ipairs(alive) do if e.fly then airOrder = airOrder or {}; table.insert(airOrder, e) end end
        if airOrder then for _, e in ipairs(alive) do if not e.fly then table.insert(airOrder, e) end end end
        fireActives(front)
        -- Chuuni's marks: the enemy each copy targets takes more magic damage while it's on it (stacking), and part of her damage
        -- every 0.5 s. (Not through a shield: it isn't a hit that could break one)
        if marking then
            for _, e in ipairs(alive) do e.marks = nil end
            for _, c in ipairs(copies) do
                if c.mark and c.dps > 0 then
                    for _, e in ipairs(c.air and airOrder or alive) do
                        if reaches(c, e, math.min(SIM.BINS, math.floor(e.p * SIM.BINS) + 1)) then
                            e.marks = (e.marks or 0) + 1
                            markAmp, markMax = c.mark.amp, c.mark.max
                            if (e.sh or 0) <= 0 then
                                local tick = c.mark.dot * realDps(c) * math.max(0.3, c.cd) / math.max(1, c.aoe) * dt
                                if opt.dealt then opt.dealt[UNIT.name(c.e.id)] = (opt.dealt[UNIT.name(c.e.id)] or 0) + math.min(tick, math.max(0, e.hp)) end
                                e.hp = e.hp - tick
                            end
                            break
                        end
                    end
                end
            end
        end
        -- a Gale (UNIT.GALE: Snow Reaper (Final)): each copy's aura on every enemy in her reach, a third of the time each since the bars take turns (MT.gale). An enemy under it
        -- long enough freezes (not a boss, not a flyer she can't hit) and takes one more hit of hers, then can't freeze again for a while; while covered it's slowed (opt.galeSlow)
        if galeOn then
            for _, e in ipairs(alive) do e.galeCov, e.galeBy = nil, nil end
            for _, c in ipairs(copies) do
                local g = c.gale
                if g and c.dps > 0 then
                    local hit = realDps(c) * math.max(0.3, c.cd) / math.max(1, c.aoe)
                    for _, e in ipairs(c.air and airOrder or alive) do
                        if e.hp > 0 and reaches(c, e, math.min(SIM.BINS, math.floor(e.p * SIM.BINS) + 1)) then
                            local half = e.fly and not c.air
                            e.galeCov = math.min(1, (e.galeCov or 0) + g.duty)
                            if not half then e.galeBy = c end
                            if (e.sh or 0) <= 0 then
                                local tick = hit * g.tick * g.duty * dt * (half and C.FLY_GROUND or 1)
                                if opt.dealt then opt.dealt[UNIT.name(c.e.id)] = (opt.dealt[UNIT.name(c.e.id)] or 0) + math.min(tick, math.max(0, e.hp)) end
                                e.hp = e.hp - tick
                            end
                        end
                    end
                end
            end
            for _, e in ipairs(alive) do
                local c = e.galeBy
                e.galeSlow = (c and not e.boss and not info.noCC) and (opt.galeSlow or SIM.GALE_SLOW) * e.galeCov or nil
                if c then
                    e.chill = (e.chill or 0) + dt * e.galeCov
                    if e.chill >= c.gale.chill and t >= (e.galeFree or 0) then
                        e.chill, e.galeFree = 0, t + c.gale.freeze + c.gale.immune
                        if not e.boss and not info.noCC then e.stunTo = math.max(e.stunTo or 0, t + c.gale.freeze) end
                        if (e.sh or 0) <= 0 then
                            local extra = realDps(c) * math.max(0.3, c.cd) / math.max(1, c.aoe)
                            if opt.dealt then opt.dealt[UNIT.name(c.e.id)] = (opt.dealt[UNIT.name(c.e.id)] or 0) + math.min(extra, math.max(0, e.hp)) end
                            e.hp = e.hp - extra
                        end
                    end
                else
                    e.chill = nil
                end
            end
        end
        for _, c in ipairs(copies) do
            if c.dps > 0 then attack(c, realDps(c)) end
        end
        for i = #drones, 1, -1 do
            local dr = drones[i]
            if t >= dr.till then table.remove(drones, i)
            else attack(dr, realDps(dr.owner) * math.max(0.3, dr.owner.cd) / math.max(1, dr.owner.aoe) * dr.dmg * dr.share / dr.cd) end
        end
        for i = #alive, 1, -1 do
            local e = alive[i]
            if e.hp <= 0 then
                money = money + e.bounty; table.insert(incomeLog, { t = t, y = e.bounty }); table.remove(alive, i)
                if e.tr then tk = tk + 1 end
                -- (a splitter leaves its clones where it fell; they can be flyers too, and pay nothing)
                if e.split then
                    local du = C.Units[e.split.unit] or {}
                    for _ = 1, e.split.n do
                        local x = { hp = e.max * e.split.ratio, max = e.max * e.split.ratio, speed = e.speed, bounty = 0, boss = false, p = e.p, at = t, sh = (tonumber(du.shield) or 0) + (info.shield or 0), fly = false, lane = e.lane }
                        if (info.flyChance or 0) > 0 then
                            flyAcc = flyAcc + info.flyChance
                            if flyAcc >= 1 then flyAcc = flyAcc - 1; x.fly = true end
                        end
                        SIM.enemyTraits(x, du, x.hp)
                        table.insert(alive, x)
                    end
                end
                -- Iron Sentinel's takedowns bring its drones
                local o = e.droneBy
                if o and o.owner then o = o.owner end
                if o and o.drone then
                    o.takes = (o.takes or 0) + 1
                    if o.takes >= o.drone.every then
                        o.takes = o.takes - o.drone.every
                        local n = 0
                        for _, x in ipairs(drones) do if x.owner == o then n = n + 1 end end
                        if n < o.drone.max then
                            local f = o.droneNow
                            table.insert(drones, { owner = o, till = t + f.life, dmg = f.dmg, share = o.drone.share, cd = f.cd, hits = o.drone.hits, aoe = 1, base = o.base, mask = o.mask, air = o.air, stun = 0, slowT = 0, ccCd = 8, drone = o.drone })
                        end
                    end
                end
            end
        end
        while incomeLog[1] and t - incomeLog[1].t > 30 do table.remove(incomeLog, 1) end
        local inc = 0
        for _, x in ipairs(incomeLog) do inc = inc + x.y end
        local incomeRate = t >= 8 and inc / math.min(30, t) or ((rewards[wave + 1] or rewards[wave] or 500) / info.waveSec)
        if baseHp <= 0 then
            -- (how much of what was on the road was left: two teams falling on the same wave still aren't equal)
            local leftHp, maxHp = 0, 0
            for _, e in ipairs(alive) do leftHp = leftHp + math.max(0, e.hp); maxHp = maxHp + e.max end
            for _, e in ipairs(queue) do leftHp = leftHp + e.hp; maxHp = maxHp + e.max end
            local lv = {}
            for _, c in ipairs(copies) do lv[c.e.id] = math.max(lv[c.e.id] or 0, c.lvl) end
            return { won = false, wave = wave, t = t, aliveAt = aliveAt, dpsAt = dpsAt, spentAt = spentAt, money = money, tk = tk, left = maxHp > 0 and leftHp / maxHp or 1, levels = lv }
        end
        if wave >= info.total and #queue == 0 and #alive == 0 then
            -- (the level each unit got to: a side unit rarely gets maxed, and its spot should suit the range it really has)
            local lv = {}
            for _, c in ipairs(copies) do lv[c.e.id] = math.max(lv[c.e.id] or 0, c.lvl) end
            return { won = true, wave = wave, t = t, aliveAt = aliveAt, dpsAt = dpsAt, spentAt = spentAt, money = money, tk = tk, levels = lv }
        end
        -- the farm's own buy rules, up to 3 buys a second (the live loop runs every 0.3 s)
        local hpAll, dpsAll = 0, 0
        for _, e in ipairs(alive) do hpAll = hpAll + e.hp end
        for _, c in ipairs(copies) do dpsAll = dpsAll + realDps(c) end
        table.insert(hist, #alive)
        local old = hist[#hist - math.floor(12 / dt)]
        local piling = (#alive >= 8 and old and #alive > old + 1) or #alive >= 18
        local pressure = math.max(maxProg[wave] or 0, maxProg[wave - 1] or 0)
        -- the last wave: farms won't pay again, so each one goes for a quarter of what it cost (SELL_RATIO; Bulby can't be sold) and the yen goes into damage (MT.lastWaveCash)
        if wave >= info.total and not lastCash and not info.infinite and not opt.oldBuy then
            lastCash = true
            for i = #copies, 1, -1 do
                local c = copies[i]
                if c.e.farm and not c.e.data.unsellable then
                    money = money + 0.25 * (c.spent or 0)
                    table.remove(copies, i)
                end
            end
            teamFx()
        end
        -- (enemies that regenerate: the bleed unit's upgrades to its bleeding level, and its placement, carry the heal they stop)
        local function bleedOf(e, lvl, place)
            if (info.regen or 0) <= 0 then return 0 end
            local at = UNIT.bleeds(e.id)
            if not at then return 0 end
            local already = false
            for _, o in ipairs(copies) do if (UNIT.bleeds(o.e.id) or 99) <= o.lvl then already = true; break end end
            local coming = {}
            for k = 1, 5 do local h = hpOf(wave + k); if not h then break end; table.insert(coming, { hp = h }) end
            return ECON.bleedShare(ECON.bleedGain(info.regen, hpAll, coming, already), at, lvl, place)
        end
        for _ = 1, 3 do
            local opts, wantLeft, farmNow, kinds = {}, 0, 0, 0
            for _, e in ipairs(team) do
                local mine = {}
                -- (a trial run, as the live farm plays it: MT.econ. opt.trial = the unit's id, opt.trialAt = how far enemies get before the others may buy)
                local standBy = opt.trial and e.id ~= opt.trial and not e.farm and (not UNIT.allyBuff(e.id)) and pressure < (opt.trialAt or 0.6)
                for _, c in ipairs(copies) do if c.e == e then table.insert(mine, c) end end
                if not e.farm and #mine > 0 then kinds = kinds + 1 end
                if standBy then mine = nil end
                for _, c in ipairs(mine or {}) do
                    if e.farm then farmNow = farmNow + UNIT.farm(e.u, c.lvl) end
                    local nxt = e.rows[c.lvl + 1]
                    if nxt and c.lvl < e.rows.max then
                        local cost = nxt.cost * info.costScale
                        if e.farm then
                            table.insert(opts, { farm = true, cost = cost, gain = UNIT.farm(e.u, c.lvl + 1) - UNIT.farm(e.u, c.lvl), c = c })
                        else
                            local g = curS > 0 and not opt.oldBuy and ECON.shieldGain(c.dpsAll or c.dps, e.rows[c.lvl], unitDps(e, c.lvl + 1), nxt, curS, curH, cdMul, eff)
                                or ECON.upgradeGain(c.dpsAll or c.dps, e.rows, c.lvl, cost, info.costScale, unitDps(e, c.lvl + 1))
                            table.insert(opts, { cost = cost, gain = g * (c.train and TRAIN.BONUS or 1) * airW(e.id, c.lvl) * reachOf(c) * focusOf(c) + bleedOf(e, c.lvl, false), c = c })
                            for l = c.lvl + 1, e.rows.max do wantLeft = wantLeft + e.rows[l].cost * info.costScale end
                        end
                    end
                end
                -- (the sim has no map to split the team on: it plays one group, so one pair. The live farm counts groups: MT.buffShort)
                local myBuff = UNIT.allyBuff(e.id)
                -- (a buffer nobody on the team can use isn't bought, as live: MT.buffWanted. The sim bought Windsong for Spirit Reaper, who's physical, with the yen the real run put into him)
                local useless = false
                if myBuff and not opt.oldBuy then
                    useless = true
                    for _, o in ipairs(team) do
                        if not o.farm and not UNIT.allyBuff(o.id) and not (opt.trial and o.id ~= opt.trial and pressure < (opt.trialAt or 0.6)) then
                            local _, base = UNIT.types(o.id)
                            if myBuff.types[base] then useless = false; break end
                        end
                    end
                end
                if mine and not useless and #mine < (myBuff and math.min(e.cap, UNIT.buffCopies(myBuff)) or e.cap) and e.placeable then
                    local cost = (e.data.cost or 0) * info.costScale
                    if e.farm then table.insert(opts, { farm = true, place = true, cost = cost, gain = UNIT.farm(e.u, 0), e = e })
                    else
                        local tr = opt.train ~= nil and e.u.uuid == opt.train
                        local bonus = (#mine == 0 and 2.5 or 1) * (kinds < 3 and 1.3 or 1) * (tr and TRAIN.BONUS or 1) * airW(e.id, 0, true)
                        local r0 = e.rows[0]
                        local i0 = r0 and UNIT.attackInfo(r0.atk, r0.range) or { n = 1, hits = 1 }
                        local cd0 = (tonumber(r0 and r0.cd) or 2) * cdMul
                        local base = opt.oldBuy and unitDps(e, 0) or ECON.shieldDps(unitDps(e, 0), cd0, i0.n, curS, curH, eff, i0.hits)
                        if unitDps(e, 0) > 0 and not opt.oldBuy then
                            local rate = 0
                            for _, o in ipairs(copies) do if o.dps > 0 then rate = rate + o.aoe * o.hits / math.max(0.3, o.cd) end end
                            base = base + ECON.shieldWork(i0.n, cd0, rate, curS, curN, info.waveSec, heavyHit * eff, curH, i0.hits)
                        end
                        table.insert(opts, { place = true, cost = cost, gain = base * bonus + buffGain(e) + holdOf(e, i0) + bleedOf(e, 0, true), e = e, train = tr and (#mine == 0 and "first" or "more") or nil })
                        for l = 0, e.rows.max do wantLeft = wantLeft + e.rows[l].cost * info.costScale end
                    end
                end
            end
            if #opts == 0 then break end
            if opt.train then TRAIN.boost(opts, kinds, pressure, cover) end
            local left = math.max(0, info.total - wave)
            local future = money + farmNow * left
            for i = wave + 1, info.total do future = future + (rewards[i] or 0) end
            local coming = {}
            for k = 1, 5 do
                local h = hpOf(wave + k)
                if not h then break end
                table.insert(coming, { hp = h, reward = rewards[wave + k] or 0 })
            end
            local shieldK = opt.oldBuy and 1 or teamShield()
            local choice = ECON.decide(opts, { money = money, left = left, attackers = kinds, pressure = pressure, piling = piling,
                -- (paper damage, as in the live farm: with eff in it the road never looked safe enough to farm, Bulby stayed at level 3 where the real farm took it to 6)
                clearSec = hpAll > 0 and (dpsAll > 0 and hpAll / (dpsAll * (opt.oldBuy and eff or 1) * shieldK) or math.huge) or 0, enemies = #alive, future = future, wantLeft = wantLeft,
                coming = coming, waveSec = info.waveSec, eff = eff, teamDps = dpsAll * eff, shieldK = shieldK, farmNow = farmNow, hpAlive = hpAll, incomeRate = incomeRate,
                roadSec = 1 / math.max(0.001, info.walk * (info.speedScale or 1)), cover = cover,
                leak = (cover and front > cover + 0.02) and front or nil })
            if not choice or choice.cost > money then break end
            money = money - choice.cost
            spentAt[wave] = (spentAt[wave] or 0) + choice.cost
            if choice.place then
                local c = { e = choice.e, lvl = 0, spent = choice.cost }
                for _, o in ipairs(copies) do if o.e == choice.e then c.later = true; break end end
                if stackLater and SIM.holds(choice.e.id) then
                    c.ctlN = 1
                    for _, o in ipairs(copies) do if o.ctlN then c.ctlN = c.ctlN + 1 end end
                end
                if not stackLater and not choice.e.farm and cover and front > cover then c.lo = math.floor(front * SIM.BINS) + 2 end
                refresh(c)
                table.insert(copies, c)
                if opt.buys then table.insert(opt.buys, string.format("%.0fs w%d place %s", t, wave, UNIT.name(c.e.id))) end
            else
                choice.c.lvl = choice.c.lvl + 1
                choice.c.spent = (choice.c.spent or 0) + choice.cost
                refresh(choice.c)
                if opt.buys then table.insert(opt.buys, string.format("%.0fs w%d up %s L%d", t, wave, UNIT.name(choice.c.e.id), choice.c.lvl)) end
            end
            teamFx()
            dpsAll = 0
            for _, c in ipairs(copies) do dpsAll = dpsAll + realDps(c) end
        end
        if opt.trace then opt.trace(t, wave, money, copies, alive, baseHp) end
        t = t + dt
        steps = steps + 1
        if steps % 120 == 0 then task.wait() end
    end
    return { won = false, wave = wave, t = t, aliveAt = aliveAt, dpsAt = dpsAt, spentAt = spentAt, money = money, timeout = true, tk = tk }
end
-- win chance from the sim: wins with 30% tougher enemies → 0.92 · wins → 0.7 · wins only vs 25% weaker → 0.25 · else 0.05
SIM.INF_CAP = 80
function SIM.evaluate(info, team)
    local r1 = SIM.run(info, team, { hpMul = 1 })
    local res = { won = r1.won, wave = r1.wave, minutes = r1.t / 60, aliveAt = r1.aliveAt, total = info.total, at = os.time() }
    -- Infinite: no win or loss, only how far the team gets (and how long that takes)
    if info.infinite and SIM.unbound(info.ld) then
        res.p = 1
        res.margin = r1.won and string.format("lasts past wave %d", info.total) or string.format("lasts to wave %d (%.0f min)", r1.wave, r1.t / 60)
    elseif r1.won then
        local r2 = SIM.run(info, team, { hpMul = 1.3 })
        res.p = r2.won and 0.92 or 0.7
        res.margin = r2.won and "wins with room to spare" or "wins, but only just"
    else
        local r3 = SIM.run(info, team, { hpMul = 0.75 })
        res.p = r3.won and 0.25 or 0.05
        res.margin = r3.won and string.format("loses at wave %d (would win vs 25%% weaker enemies)", r1.wave) or string.format("loses at wave %d of %d", r1.wave, info.total)
    end
    return res
end
-- how well the sim matched real runs with the same team: HP alive at each wave start (waves 3+), real / sim
function SIM.trust(info, team)
    local cal = info.cal or {}
    if type(cal.alive) ~= "table" or cal.teamSig ~= SIM.sig((function() local l = {} for _, e in ipairs(team) do table.insert(l, e.u) end return l end)()) then return nil end
    -- real runs on another map (the half-hour challenge rotates) say nothing about this one
    if info.key == "ch" and not cal.aliveLvl then return nil end
    if cal.aliveLvl and info.ld and info.ld.id and cal.aliveLvl ~= tostring(info.ld.id) then return nil end
    local r = SIM.run(info, team, { hpMul = 1 })
    local sumR, sumS, n = 0, 0, 0
    for w = 3, math.min(r.wave, tonumber(cal.lastWave) or 99) do
        local real = tonumber(cal.alive[tostring(w)])
        local sim = r.aliveAt[w]
        if real and sim and real > 0 then sumR = sumR + real; sumS = sumS + sim; n = n + 1 end
    end
    if n < 2 or sumS <= 0 then return nil end
    local ratio = sumR / sumS
    return { ratio = ratio, ok = ratio >= 0.75 and ratio <= 1.33, waves = n }
end
-- the planner: your team vs the mode, the best team from your units, and what ready evolutions would change
function SIM.pool(mod, info)
    local s = C.session()
    local best, farms = {}, {}
    for _, u0 in pairs(s.profile_data.collection.owned_units) do
        local u = s.collection:get_unit_by_uuid(u0.uuid) or u0
        -- (a unit whose upgrades the game hides can't be simulated: it would play at level 0)
        -- (and nothing under level 50 but a farm: the user's call after room 18 went in with two level-1 units the search liked)
        local okL, lvl = pcall(C.USC.calculate_level, u.unit_id, tonumber(u.xp) or 0)
        local grown = UNIT.isFarm(u.unit_id) or (okL and (tonumber(lvl) or 0) >= 50)
        if C.Units[u.unit_id] and UNIT.rows(u.unit_id) and not UNIT.hidden(u.unit_id) and grown then
            local farm = UNIT.isFarm(u.unit_id)
            local okS, sc = pcall(farm and function() return UNIT.farm(u, UNIT.rows(u.unit_id).max) end or UNIT.score, u, mod)
            sc = (okS and sc or 0) * (farm and 1 or UNIT.skinMul(u, info and info.skinSet))
            local bucket = farm and farms or best
            if not bucket[u.unit_id] or sc > bucket[u.unit_id].sc then bucket[u.unit_id] = { u = u, sc = sc } end
        end
    end
    local list, flist = {}, {}
    for _, v in pairs(best) do table.insert(list, v) end
    for _, v in pairs(farms) do table.insert(flist, v) end
    table.sort(list, function(a, b) return a.sc > b.sc end)
    table.sort(flist, function(a, b) return a.sc > b.sc end)
    local pool = {}
    for i = 1, math.min(10, #list) do table.insert(pool, list[i].u) end
    -- (the user's calls: damage-over-time units against a boss that heals, burn and bleed alike, those that have it from
    -- placement first since a side unit rarely gets deep upgrades; and every farm, so a team with two gets tried)
    local atPlace, later = {}, {}
    for i = 11, #list do
        local rows = UNIT.rows(list[i].u.unit_id)
        for l = 0, rows.max do
            if rows[l] and rows[l].atk and UNIT.attackInfo(rows[l].atk, rows[l].range).dot > 0 then
                table.insert(l == 0 and atPlace or later, list[i].u)
                break
            end
        end
    end
    for i = 1, math.min(4, #atPlace) do table.insert(pool, atPlace[i]) end
    for i = 1, math.min(2, #later) do table.insert(pool, later[i]) end
    for i = 1, math.min(3, #flist) do table.insert(pool, flist[i].u) end
    -- (a slow or a stun holds the road for everyone else, whatever its own damage)
    local hold = {}
    for i = 11, #list do
        local r0 = UNIT.rows(list[i].u.unit_id)[0]
        local ai = r0 and r0.atk and UNIT.attackInfo(r0.atk, r0.range)
        if ai and (ai.slowTime > 0 or ai.stun > 0) then table.insert(hold, list[i].u) end
    end
    for i = 1, math.min(3, #hold) do table.insert(pool, hold[i]) end
    -- (flyers or shields in the way: the units that hit flyers from placement, and the cheap ones that land the most hits for
    -- their price, whatever their damage: a shield only counts hits. A Rare can be the best unit you own here)
    if info and ((info.flyChance or 0) > 0 or (info.shield or 0) > 0) then
        local air, fast = {}, {}
        for i = 11, #list do
            local u = list[i].u
            local r0 = UNIT.rows(u.unit_id)[0]
            if UNIT.airFrom(u.unit_id) == 0 then table.insert(air, u) end
            local cd, cost = tonumber(r0 and r0.cd) or 0, tonumber((C.Units[u.unit_id] or {}).cost) or 0
            if cd > 0 and cost > 0 and UNIT.range(u, 0) >= 15 then
                local ai = UNIT.attackInfo(r0.atk, r0.range)
                table.insert(fast, { u = u, v = ai.n * ai.hits / cd / cost * math.min(6, UNIT.cap(u)) })
            end
        end
        table.sort(fast, function(a, b) return a.v > b.v end)
        for i = 1, math.min(4, #air) do table.insert(pool, air[i]) end
        for i = 1, math.min(6, #fast) do table.insert(pool, fast[i].u) end
    end
    local seen, once = {}, {}
    for _, u in ipairs(pool) do
        if not seen[u] then seen[u] = true; table.insert(once, u) end
    end
    -- (the rest get one real try in SIM.bestTeam)
    once.rest = {}
    for _, v in ipairs(list) do if not seen[v.u] then table.insert(once.rest, v.u) end end
    return once
end
-- (two teams that fall on the same wave: the one that lasted longer and left less)
function SIM.objective(r) return (r.won and 1000 or 0) + r.wave * 10 - (r.won and r.t / 60 or ((r.left or 1) * 9 - math.min(9, r.t / 60))) end
-- the toughest test the current team doesn't pass: enemies ×1, ×1.3 ... until it loses (a difference between two teams only
-- shows near the cliff: at ×1 both just win). Returns the level and that run
-- (it stopped at ×4 until the user asked, Nov 1, what ×8 and ×10 would show. With Chuuni at Unique every team won at ×4 on an easy map, so they were told apart by seconds: Iron Sentinel's team won 6 of 7 tries at ×8 and the two it could swap for won none)
SIM.LADDER = { 1, 1.3, 1.7, 2.2, 3, 4, 6, 8, 12, 16, 24 }
function SIM.cliff(info, team, layout)
    local last
    for _, hp in ipairs(SIM.LADDER) do
        last = SIM.run(info, team, { hpMul = hp, layout = layout })
        if not last.won then return hp, last end
    end
    return SIM.LADDER[#SIM.LADDER], last
end
-- how far a team really goes: 3 close tries at each step of the ladder until it wins none. Returns the tries won, and the wave it got to on the step it broke at
function SIM.exam(info, units)
    local team, wins, reach = SIM.teamFrom(units, info.map), 0, 0
    for _, hp in ipairs(SIM.LADDER) do
        local w, wave = 0, 0
        for _, k in ipairs({ 0.92, 1, 1.08 }) do
            local r = SIM.run(info, team, { hpMul = hp * k })
            if r.won then w = w + 1 end
            wave = wave + r.wave
        end
        wins, reach = wins + w, wave / 3
        task.wait()
        if w == 0 then break end
    end
    return wins, reach
end
-- the lobby's guess at whether a map will play as a kill box, for the mode's chances and the team search (the match decides, with the map's real spots: MT.planSpots). hard = the toughest enemies this
-- team was tested against spread out, won = whether it won there. Real runs go first, since the sim reads spread-out units too low on maps that were really won, and stacked ones too high.
-- Then the sim: close to losing (falls to enemies ×1.3 or less) and stacked gets at least 2 waves further, over 3 tries around that strength (one run swings on the order of its buys).
-- Returns whether to stack, why in plain words, and the sim's gain
SIM.ZONE_CLOSE, SIM.ZONE_GAIN = 1.3, 20 -- (20: the objective's points for 2 waves)
function SIM.zoneKey(info) return tostring(info.key) .. ":" .. tostring(info.map) end
function SIM.zoneChoice(info, team, hard, won)
    if CFG.killZone == false or info.zone or (info.infinite and SIM.unbound(info.ld)) then return false end
    local rec = B.zoneRec[SIM.zoneKey(info)]
    local box = rec and (rec.style == "box" or (rec.style == nil and rec.zone == true))
    if rec and rec.won then return box == true, box and "the kill box won here last time" or nil end
    if rec and box then return false, "the kill box lost here last time" end
    local mode = B.modes[info.key]
    local streak = mode and tonumber(mode.streak) or 0
    -- (a mode whose map stays the same and whose last run won, from before these records: leave it. The challenges' maps change)
    if not rec and mode and (tonumber(mode.wins) or 0) > 0 and streak == 0 and info.key ~= "ch" and info.key ~= "dc" then return false end
    local lost = rec ~= nil or streak > 0
    local close = won and hard <= 1 or (not won and hard <= SIM.ZONE_CLOSE)
    if not (lost or close) then return false end
    local stacked = table.clone(info)
    stacked.zone = true
    local function tries(i)
        local v = 0
        for _, k in ipairs({ 0.92, 1, 1.08 }) do v = v + SIM.objective(SIM.run(i, team, { hpMul = hard * k })) end
        return v / 3
    end
    local gain = tries(stacked) - tries(info)
    if lost and gain > -SIM.ZONE_GAIN then return true, "spread-out units lost here last time", gain end
    if close and gain > SIM.ZONE_GAIN then return true, string.format("the simulator says your team is close to losing here (enemies ×%.1f), and it plays better stacked", hard), gain end
    return false, nil, gain
end
-- how a dungeon team holds up: the rising test of SIM.exam (close tries up SIM.LADDER until a step wins none; it stopped at ×3 until the user asked for the same test here, Nov 1, so strong teams in
-- shallow rooms couldn't be told apart). Returns the tries won, those at ×1 (of 3), the wave it gets to at ×1 (for a room nothing wins), and the wave at its last step (for a tie)
function SIM.strength(info, units)
    local team, wins, atOne, reach, far = SIM.teamFrom(units, info.map), 0, 0, 0, 0
    for _, hp in ipairs(SIM.LADDER) do
        local w, wave = 0, 0
        for _, k in ipairs({ 0.92, 1, 1.08 }) do
            local r = SIM.run(info, team, { hpMul = hp * k })
            if r.won then w = w + 1 end
            wave = wave + r.wave
        end
        wins, far = wins + w, wave / 3
        if hp == 1 then atOne, reach = w, wave / 3 end
        task.wait()
        if w == 0 then break end
    end
    return wins, atOne, reach, far
end
-- every slot tries every unit in the pool (no two of the same unit), judged at the current team's cliff. Stops at
-- `budget` seconds. Returns the team, its run, the level, and the current team's run at that level
function SIM.bestTeam(info, current, pool, budget)
    local t0 = U.now()
    budget = budget or 25
    local team = table.clone(current)
    local hard, curR = SIM.cliff(info, SIM.teamFrom(team, info.map))
    -- always a farm unit on the team (the user's rule: room 13's last life went in with none, ¥35k by wave 8)
    local function farms(t)
        local n = 0
        for _, u in ipairs(t) do if UNIT.isFarm(u.unit_id) then n = n + 1 end end
        return n
    end
    local anyFarm = farms(pool) > 0
    -- and enough copies of attackers to spread down the road: the sim's stretch of road doesn't show how thin 3 single-copy units are
    local function copies(t)
        local n = 0
        for _, u in ipairs(t) do if not UNIT.isFarm(u.unit_id) and not UNIT.allyBuff(u.unit_id) then n = n + UNIT.cap(u) end end
        return n
    end
    -- (a team with an empty slot gets it filled first: swaps alone kept a team on 5 units all through a room and into the next run)
    local fullR
    while #team < 6 do
        local bestU, bestV
        local needFarm = anyFarm and farms(team) == 0
        for _, cand in ipairs(pool) do
            local dup = false
            for _, u in ipairs(team) do if u.unit_id == cand.unit_id then dup = true end end
            if not dup and (not needFarm or UNIT.isFarm(cand.unit_id)) then
                local trial = table.clone(team)
                table.insert(trial, cand)
                local r = SIM.run(info, SIM.teamFrom(trial, info.map), { hpMul = hard })
                local o = SIM.objective(r)
                if not bestV or o > bestV then bestU, bestV, fullR = cand, o, r end
            end
        end
        if not bestU then break end
        table.insert(team, bestU)
    end
    -- (a full team with no farm: the swap that costs least)
    if anyFarm and farms(team) == 0 then
        local bestT, bestV
        for slot = 1, #team do
            for _, cand in ipairs(pool) do
                if UNIT.isFarm(cand.unit_id) then
                    local trial = table.clone(team)
                    trial[slot] = cand
                    local r = SIM.run(info, SIM.teamFrom(trial, info.map), { hpMul = hard })
                    local o = SIM.objective(r)
                    if not bestV or o > bestV then bestT, bestV, fullR = trial, o, r end
                end
            end
        end
        if bestT then team = bestT end
    end
    -- (a swap has to hold on close tries too, or one lucky run walks the whole search away from a good team)
    local function steady(t, first)
        local tt = SIM.teamFrom(t, info.map)
        return (SIM.objective(first) + SIM.objective(SIM.run(info, tt, { hpMul = hard * 0.92 })) + SIM.objective(SIM.run(info, tt, { hpMul = hard * 1.08 }))) / 3
    end
    local bestR, bestO = fullR or curR, steady(team, fullR or curR)
    -- every grown unit the pool left out gets one real try at this strength, in your weakest attacker's slot, and the best few go first in the swaps below. The pool goes by a paper score, which can't see what a unit does besides
    -- hitting: 33 of your 68 units never got tried (the user asked what else it couldn't see, Nov 1, the day Elyssia read 6k and then did 88% of a real room)
    if type(pool.rest) == "table" and #pool.rest > 0 then
        local slot, low
        for i, u in ipairs(team) do
            if not UNIT.isFarm(u.unit_id) and not UNIT.allyBuff(u.unit_id) then
                local okS, sc = pcall(UNIT.score, u, info.mod)
                sc = (okS and sc or 0) * UNIT.skinMul(u, info.skinSet)
                if not low or sc < low then slot, low = i, sc end
            end
        end
        if slot then
            local tried, t1 = {}, U.now()
            for _, cand in ipairs(pool.rest) do
                if U.now() - t1 > 5 then break end
                local dup = false
                for _, u in ipairs(team) do if u.unit_id == cand.unit_id then dup = true end end
                if not dup then
                    local trial = table.clone(team)
                    trial[slot] = cand
                    table.insert(tried, { u = cand, o = SIM.objective(SIM.run(info, SIM.teamFrom(trial, info.map), { hpMul = hard })) })
                end
            end
            table.sort(tried, function(a, b) return a.o > b.o end)
            pool = table.clone(pool)
            for i = 1, math.min(4, #tried) do table.insert(pool, 1, tried[i].u) end
            -- (the swaps keep their full time)
            t0 = t0 + (U.now() - t1)
        end
    end
    for _ = 1, 2 do
        local improved = false
        for slot = 1, #team do
            for _, cand in ipairs(pool) do
                if U.now() - t0 > budget then return team, bestR, hard, curR end
                local dup = false
                for _, u in ipairs(team) do if u.unit_id == cand.unit_id then dup = true end end
                if not dup then
                    local trial = table.clone(team)
                    trial[slot] = cand
                    if (not anyFarm or farms(trial) > 0) and copies(trial) >= math.min(8, copies(team)) then
                        local r = SIM.run(info, SIM.teamFrom(trial, info.map), { hpMul = hard })
                        local o = SIM.objective(r)
                        if o > bestO + 1 then
                            o = steady(trial, r)
                            if o > bestO + 1 then team, bestO, bestR, improved = trial, o, r, true end
                        end
                    end
                end
            end
        end
        if not improved then break end
    end
    return team, bestR, hard, curR
end
-- evolutions the inventory already covers (and the ones missing a few items)
function SIM.evolutions()
    local s = C.session()
    local out, seen = {}, {}
    local inv = s.inventory
    local function have(id) local n = 0; pcall(function() n = inv:get_number_of_owned_item(id) end); return n end
    for _, u0 in pairs(s.profile_data.collection.owned_units) do
        local d = C.Units[u0.unit_id]
        if d and d.evolve and d.evolve.evolve_unit and not d.evolve.hide_from_ui and not seen[u0.unit_id] and C.Units[d.evolve.evolve_unit] then
            seen[u0.unit_id] = true
            local req = u0.shiny and d.evolve.shiny or d.evolve.normal
            if req then
                local missing = {}
                for _, it in pairs(req.item_requirement or {}) do
                    if have(it.item_id) < (it.amount or 1) then table.insert(missing, string.format("%s %d/%d", (C.Items[it.item_id] or {}).name or it.item_id, have(it.item_id), it.amount)) end
                end
                for _, ur in pairs(req.unit_requirement or {}) do
                    local n = 0
                    for _, o in pairs(s.profile_data.collection.owned_units) do if o.unit_id == ur.unit_id and (not ur.shiny or o.shiny) then n = n + 1 end end
                    if n < (ur.amount or 1) then table.insert(missing, string.format("%s %d/%d", UNIT.name(ur.unit_id), n, ur.amount)) end
                end
                local short = ADV.killsShort(s.collection:get_unit_by_uuid(u0.uuid) or u0, req)
                if short then table.insert(missing, string.format("%s %s/%s", short.what, U.fmt(short.have), U.fmt(short.need))) end
                if #missing <= 1 then
                    local u = s.collection:get_unit_by_uuid(u0.uuid) or u0
                    table.insert(out, { u = u, from = u0.unit_id, to = d.evolve.evolve_unit, missing = missing,
                        evolved = { unit_id = d.evolve.evolve_unit, uuid = "evo:" .. tostring(u.uuid), xp = u.xp, traits = u.traits, trait_stats = u.trait_stats, further_modifiers = u.further_modifiers } })
                end
            end
        end
    end
    return out
end
-- a mode's level data the sim can use: from the match (Loader.LevelData, saved per mode) or the lobby's tables
function SIM.levelFor(m)
    local cal = B.simCal[m.key]
    -- the daily and the half-hour challenge change map: the saved level only counts while it's the same one
    if m.kind == "daily" and B.live.daily and B.live.daily.ld then return B.live.daily.ld, B.live.daily.challenge end
    -- (the Summer Hunt changes map every hour)
    if HUNT.is(m.level) and B.live.event and B.live.event.ld then return B.live.event.ld, nil end
    local same = m.kind ~= "challenge" or (cal and type(cal.ld) == "table" and cal.ld.id == m.level and cal.ch == m.challenge)
    if cal and type(cal.ld) == "table" and same then return cal.ld, cal.ch end
    if m.kind == "challenge" and C.Levels[m.level] then
        local ld = SIM.slim(C.Levels[m.level]); ld._difficulty = "Hard"; ld._gamemode = "challenge"; ld._challenge = m.challenge
        return ld, m.challenge
    end
    if C.Levels[m.level] then
        local ld = SIM.slim(C.Levels[m.level]); ld._difficulty = m.diff
        ld._gamemode = ld._OVERRIDE_GAMEMODE or (m.kind == "raid" and "raid") or (ld.infinite and "infinite") or "story"
        return ld, nil
    end
end
function SIM.plan(m, withTeam, budget, own)
    local ld, ch = SIM.levelFor(m)
    -- (an opened portal's own level data, with its modifiers: HUB.launchPortal)
    if m.ldOverride then ld = m.ldOverride end
    if not ld then return nil end
    local mod = m.mod or (m.kind == "daily" and B.live.daily and B.live.daily.mod) or MODE.levelMod(m.level)
    local info = SIM.info(ld, m.key, ch, mod)
    local units = own
    if not units then
        units = {}
        for _, e in ipairs(UNIT.equipped()) do table.insert(units, e.u) end
    end
    local team = SIM.teamFrom(units, info.map)
    local res = SIM.evaluate(info, team)
    -- close to losing, or lost here: with the kill box? The team search and the mode's chances then go by that (MT.planSpots decides again on the real map, with real spots)
    local okZ, zone = pcall(SIM.zoneChoice, info, team, res.p >= 0.92 and 1.7 or res.p >= 0.7 and 1.3 or 1, false)
    if okZ and zone then
        info.zone = true
        res = SIM.evaluate(info, team)
        res.zone = true
        res.margin = res.margin .. " with the kill box"
    end
    res.sig = SIM.sig(units)
    res.trust = SIM.trust(info, team)
    res.label = m.label
    res.calibrated = (tonumber(info.cal.n) or 0) > 0
    B.simRes[m.key] = res
    res.aliveAt = nil
    SF.log(1, "SIM", string.format("%s: your team %s (%s, %s)", m.label, res.margin, res.calibrated and "calibrated on real runs" or "not calibrated yet",
        res.trust and string.format("real/sim HP %.2f", res.trust.ratio) or "no same-team run to compare"))
    -- the team that won here last run plays again when the simulator calls it a loss: real runs decide. Shibuya's portal was won 4 times in a row with Elyssia, Iron Sentinel and
    -- Chuuni carrying it, while the sim read your saved team as falling at wave 10 and put in Dragonslayer and Gene (???), who did 0-2% (Nov 2). A loss clears it (MT.finish)
    local rec = MODE.rec(m.key)
    if CFG.simTeams and withTeam and type(rec.winTeam) == "table" and #rec.winTeam > 0 then
        local s = C.session()
        local wt = {}
        for _, uuid in ipairs(rec.winTeam) do local u = s.collection:get_unit_by_uuid(uuid); if u then table.insert(wt, u) end end
        if #wt == #rec.winTeam then
            local wteam = SIM.teamFrom(wt, info.map)
            local wr = SIM.run(info, wteam, { hpMul = 1 })
            -- (or when the simulator is far off real runs here, whatever it says: on the portal it read real HP alive ×25 off, called the team that had just won a win, and the search then put Gene (???) in on that same reading)
            local tr = SIM.trust(info, wteam)
            local off = tr and not tr.ok
            if not wr.won or off then
                local names = {}
                for _, u in ipairs(wt) do table.insert(names, UNIT.name(u.unit_id)) end
                B.simTeam[m.key] = { uuids = rec.winTeam, names = names, won = true, wave = info.total, better = SIM.sig(wt) ~= res.sig, cur = { won = res.won, wave = res.wave }, at = os.time(), label = m.label, base = res.sig }
                SF.log(1, "SIM", string.format("%s: the team that won here last run plays again (%s): %s, and real runs won %d in a row", m.label, table.concat(names, ", "),
                    off and string.format("the simulator is off ×%.1f against real runs here", tr.ratio or 0) or string.format("the simulator calls it a loss at wave %d", wr.wave), rec.winTeamN or 1))
                return res
            end
        end
    end
    if CFG.simTeams and withTeam then
        local okB, bestUnits, brHard, hard, curHard = pcall(SIM.bestTeam, info, units, SIM.pool(mod, info), budget)
        if okB and bestUnits then
            -- the search's top pick plays, whatever the margin (the user's call, Nov 1: "search team should always be number 1". Dungeon rooms likewise: DG.planTeam)
            local better = SIM.sig(bestUnits) ~= res.sig
            -- (unless your own team already wins with room to spare: then it stays. When every team wins, the search can only compare them at a strength no real run sees, where the
            -- differences are noise: on Shibuya's portal it put in Mochi, Elf Spirit (Wind) and Crush (Ace), and the Mochi team lost at wave 8 where the sim had said a win. The user
            -- found the picks odd, Nov 2. A team at risk still gets the search's pick, by the Nov 1 rule)
            if better and res.won and (res.p or 0) >= 0.92 then
                local tried = {}
                for _, u in ipairs(bestUnits) do table.insert(tried, UNIT.name(u.unit_id)) end
                SF.log(1, "SIM", string.format("%s: your team already wins with room to spare, so it stays (the search had %s)", m.label, table.concat(tried, ", ")))
                bestUnits, better = units, false
            end
            -- (the search judges at one strength, where your team breaks, so its answer can be worse everywhere else: on Snowy Kingdom Act 6 Hard it took a team that lost at normal strength. So both go up the whole
            -- ladder before anything is swapped: the top pick is what really goes further, and a tie leaves your team on)
            local examText = ""
            if better then
                local mineW, mineR = SIM.exam(info, units)
                local newW, newR = SIM.exam(info, bestUnits)
                if newW > mineW or (newW == mineW and newR > mineR) then
                    examText = string.format(" · up the rising test it won %d tries, yours %d", newW, mineW)
                else
                    local tried = {}
                    for _, u in ipairs(bestUnits) do table.insert(tried, UNIT.name(u.unit_id)) end
                    SF.log(1, "SIM", string.format("%s: the search tried %s, but it doesn't go further than your team up the rising test (it won %d tries, yours %d): yours stays", m.label, table.concat(tried, ", "), newW, mineW))
                    bestUnits, better = units, false
                end
            end
            local br = SIM.run(info, SIM.teamFrom(bestUnits, info.map), { hpMul = 1 })
            -- (what the windows show for this mode is the team that plays: "loses at wave 46" was the team before the swap, in a run the new team was at wave 48 of)
            if better then res.playing = br.won and "the best team wins" or string.format("the best team reaches wave %d of %d", br.wave, info.total) end
            local uuids, names = {}, {}
            for _, u in ipairs(bestUnits) do table.insert(uuids, u.uuid); table.insert(names, UNIT.name(u.unit_id)) end
            B.simTeam[m.key] = { uuids = uuids, names = names, won = br.won, wave = br.wave, better = better, cur = { won = res.won, wave = res.wave }, at = os.time(), label = m.label, base = res.sig }
            SF.log(1, "SIM", string.format("%s: best team from your units %s (%s)%s", m.label, br.won and "wins" or ("reaches wave " .. br.wave), table.concat(names, ", "),
                better and (string.format(" · it plays · against enemies ×%.1f: %s at wave %d, yours %s at wave %d", hard, brHard.won and "wins" or "falls", brHard.wave, curHard.won and "wins" or "falls", curHard.wave) .. examText) or " · the same as yours"))
            -- ready evolutions: what each one does to that best team here
            local evo = {}
            for _, ev in ipairs(SIM.evolutions()) do
                local gain
                if UNIT.hidden(ev.from) or UNIT.hidden(ev.to) then
                    gain = "strength unknown (the game shows its upgrades only in a match)"
                else
                    local trial = table.clone(bestUnits)
                    local swapped = false
                    for i, u in ipairs(trial) do if u.unit_id == ev.from then trial[i] = ev.evolved; swapped = true end end
                    if not swapped then
                        -- not in the team: would the evolved unit replace the weakest attacker?
                        local wi, ws = nil, math.huge
                        for i, u in ipairs(trial) do
                            if not UNIT.isFarm(u.unit_id) then local okS, sc = pcall(UNIT.score, u, mod); if okS and sc < ws then wi, ws = i, sc end end
                        end
                        if wi then trial[wi] = ev.evolved end
                    end
                    local r = SIM.run(info, SIM.teamFrom(trial, info.map), { hpMul = 1 })
                    if r.won and not br.won then gain = "turns " .. m.label .. " into a win"
                    elseif r.wave > br.wave then gain = string.format("%s: reaches wave %d instead of %d", m.label, r.wave, br.wave)
                    elseif r.won and br.won and r.t < br.t - 6 then gain = string.format("clears %s %.1f min faster", m.label, (br.t - r.t) / 60)
                    else gain = br.won and ("no difference in " .. m.label .. " (already a win)") or ("doesn't help in " .. m.label) end
                end
                table.insert(evo, { from = UNIT.name(ev.from), to = UNIT.name(ev.to), ready = #ev.missing == 0, missing = ev.missing[1], gain = gain, mode = m.label })
            end
            B.simEvo = evo
        end
    end
    SF.saveSoon()
    return res
end

-- ============================================================
--  DUNGEON (profile dungeon_data · DungeonServiceCore)
-- ============================================================
-- A run is 20 rooms. dungeon_data.next holds this depth's rooms ("1".."3": {_d = depth, _l = the room's level,
-- _t = its tags, _r = seed}) and next1..next3 the rooms each of them leads to; _resources = {money (hoard coins),
-- treasure (chests), treasure_gold (rare chests)}; _items = what the run carries ({id}: relics and curses);
-- selected_next.lives = lives left (4 at the start). Room tags (TYPES): CURSE 0, SHOP 1, MONEY 2, TREASURE_GOLD 3,
-- TREASURE 4, BOSS_FINAL 5, OPEN_CHEST 6 (every 5 depths), SHRINE 7. A room is a raid-mode match: ¥2,500 to
-- start, no gems, a map's waves made infinite-style and bound to its template's 15–20 waves, enemies weak to 2–3
-- elements (×2–3.8). Remotes: dungeon_start, dungeon_enter_room(choice), dungeon_buy_shop(item),
-- dungeon_continue_shop (leaves a shop / shrine / chest screen), dungeon_open_chest, dungeon_shrine_accept,
-- dungeon_continue_death. dungeon_quit throws every reward away: never called.
-- The user's rules: Rare Chests first and kept for floor 20, coins kept for the shops at floors 10–15 (chest-luck items are
-- bought in every shop), a curse is judged by what it does and skipped only if the simulator says your team can't beat
-- rooms with it (Oct 31; "avoid stacking curses" before that, which also avoided the rare chests)
DG.T = { CURSE = 0, SHOP = 1, MONEY = 2, GOLD = 3, CHEST = 4, BOSS = 5, OPEN = 6, SHRINE = 7 }
DG.TAG_NAMES = { [0] = "curse", [1] = "shop", [2] = "coins", [3] = "rare chest", [4] = "chest", [5] = "final boss", [6] = "chest opening", [7] = "shrine" }
DG.KNOWN = { _started = true, _items = true, selected_next = true, next = true, _resources = true }
DG.ROOMS = 20
function DG.core()
    if not DG._core then DG._core = C.core("DungeonServiceCore") end
    return DG._core
end
function DG.data() local p = C.prof(); return p and type(p.dungeon_data) == "table" and p.dungeon_data or nil end
function DG.item(id) local c = DG.core(); return id and c and type(c.ITEMS) == "table" and c.ITEMS[id] or nil end
function DG.isCurse(id) return tostring(id):sub(1, 7) == "_curse_" end
function DG.tags(r)
    local t = {}
    for k, v in pairs(type(r) == "table" and type(r._t) == "table" and r._t or {}) do if v then t[tonumber(k) or -1] = true end end
    return t
end
-- rooms in a "next" table ("1".."3"), by choice
function DG.list(t)
    local out = {}
    for k, r in pairs(type(t) == "table" and t or {}) do
        local n = tonumber(k)
        if n and type(r) == "table" then table.insert(out, { choice = n, key = k, r = r, tags = DG.tags(r), d = tonumber(r._d) or 1 }) end
    end
    table.sort(out, function(a, b) return a.choice < b.choice end)
    return out
end
function DG.rooms(dd) return DG.list(dd and dd.next) end
function DG.after(dd, choice) return DG.list(dd and type(dd.next) == "table" and dd.next["next" .. tostring(choice)] or nil) end
function DG.depth(dd) local x = DG.rooms(dd)[1]; return x and x.d or nil end
function DG.items(dd)
    local out = {}
    for _, v in pairs(dd and type(dd._items) == "table" and dd._items or {}) do
        local id = type(v) == "table" and v.id or (type(v) == "string" and v) or nil
        if id then out[id] = (out[id] or 0) + 1 end
    end
    return out
end
function DG.curses(dd) local n = 0; for id, c in pairs(DG.items(dd)) do if DG.isCurse(id) then n = n + c end end; return n end
-- coins, chests, rare chests
function DG.res(dd)
    local r = dd and type(dd._resources) == "table" and dd._resources or {}
    return tonumber(r.money) or 0, tonumber(r.treasure) or 0, tonumber(r.treasure_gold) or 0
end
-- tries left at the room (5; a lost try 5 → 4, the next room back to 5). The game shows them only while a room is
-- selected — selected_next {choice_str, lives}, gone once a room ends — so the last count seen is kept
function DG.lives(dd)
    local n = tonumber(dd and dd.lives) or tonumber(dd and type(dd.selected_next) == "table" and dd.selected_next.lives)
    if n then
        if n ~= B.dg.lives then B.dg.lives = n; SF.saveSoon() end
        return n
    end
    -- (a run that died leaves 0 here, and the next run's first room isn't selected yet, so it doesn't say: rooms start on 5. It held a fresh room 1 as "the last life" on Oct 31)
    local known = tonumber(B.dg.lives)
    return (known and known > 0) and known or 5
end
function DG.luck(dd)
    local c = DG.core()
    local ok, v = pcall(function() return c.calculate_luck_multiplier(dd) end)
    return ok and tonumber(v) or 1
end
function DG.tagText(tags)
    local l = {}
    for k = 0, 7 do if tags[k] then table.insert(l, DG.TAG_NAMES[k]) end end
    return #l > 0 and table.concat(l, " + ") or "fight only"
end
-- your attackers' share of damage of a type, by damage and not by heads: counted by heads, Mochi made a magic team 20% physical, and a shop at
-- depth 15 spent 880 coins on Headsplitter (+75% physical) and Reaper Scythe for a team whose physical damage is Mochi's 2% (Oct 31)
function DG.share(kind)
    local total, hit = 0, 0
    for _, e in ipairs(UNIT.equipped()) do
        local id = e.id or (e.u and e.u.unit_id)
        if id and e.u and not UNIT.isFarm(id) and not UNIT.allyBuff(id) then
            local rows = UNIT.rows(id)
            local okD, d = pcall(UNIT.dps, e.u, rows and rows.max or 0, nil)
            d = okD and tonumber(d) or 0
            local _, base = UNIT.types(id)
            total = total + d
            if base == kind or base == kind .. "_damage" then hit = hit + d end
        end
    end
    return total > 0 and hit / total or 0.5
end
-- what a shop or shrine item does for the run, on one scale (+100% damage for the whole team ≈ 100)
function DG.itemValue(id, dd)
    local it = DG.item(id)
    if not it or DG.isCurse(id) then return 0 end
    local v = 0
    if tonumber(it.luck_increase) then v = v + 300 * it.luck_increase end
    if tonumber(it.star_remnant_chest_add) then v = v + 150 * it.star_remnant_chest_add end
    if id == "philospher_stone" then local _, n = DG.res(dd); v = v + 60 + 25 * n end
    if id == "chest_mock_item" then v = v + 120 end
    for _, ef in pairs(type(it.wave_modifier_effects) == "table" and it.wave_modifier_effects or {}) do
        local a = math.abs(tonumber(ef.amount) or 0)
        if ef.type == "stat_mul" and ef.stat == "damage" then v = v + 100 * a
        elseif ef.type == "stat_mul" and ef.stat == "attack_cooldown" then v = v + 100 * a / math.max(0.2, 1 - a)
        elseif ef.type == "stat_mul" and ef.stat == "range" then v = v + 50 * a
        elseif ef.type == "stat_attr_add" and ef.stat == "_dmg_mul_physical" then v = v + 100 * a * DG.share("physical")
        elseif ef.type == "stat_attr_add" and ef.stat == "_dmg_mul_magic" then v = v + 100 * a * DG.share("magic")
        elseif ef.type == "stat_attr_add" and ef.stat == "_dmg_mul_true_damage" then v = v + 100 * a * DG.share("true")
        elseif ef.type == "stat_add" and ef.stat == "physical_crit_chance" then v = v + 60 * a * DG.share("physical")
        elseif ef.type == "boss_damage" then v = v + 40 * a
        elseif ef.type == "enemy_speedup" then v = v + 80 * a
        elseif ef.type == "unit_cost" then v = v + 80 * a end
    end
    return v
end
-- what a curse costs on the path, by what it does, on the scale of DG.roomValue (a rare chest = 12). Its enemy HP, speed and
-- regen are played by the simulator, so those count mostly in the win chance and in DG.curseGate; the rest it can't play
DG.CURSE_COST = { _curse_money = 0.5, _curse_shop = 0.5, _curse_health = 0.5, _curse_speed = 0.5, _curse_regen = 0.5,
    _curse_shield = 1, _curse_explode = 1.5, _curse_random = 2, _curse_super_health = 1, _curse_super_speed = 1, _curse_super_regen = 1,
    _curse_super_armored = 3, _curse_super_burst = 3, _curse_super_explode = 3, _curse_super_chaos = 3 }
function DG.curseCost(id)
    -- (more flyers cost by how much of your team can't hit them)
    if id == "_curse_fly" then
        local n, air = 0, 0
        for _, e in ipairs(UNIT.equipped()) do
            local uid = e.id or (e.u and e.u.unit_id)
            if uid and not UNIT.isFarm(uid) then
                n = n + 1
                local okA, from = pcall(UNIT.airFrom, uid)
                if okA and from then air = air + (from == 0 and 1 or 0.5) end
            end
        end
        return 1 + 2 * (n > 0 and 1 - air / n or 0.5)
    end
    return DG.CURSE_COST[id] or 1.5
end
-- a room's worth on the path, from its tags: rare chests first (the user's call: only they can drop secret units, and
-- every one seen comes with a curse, so "no curse on top of a curse" had walked past them: 3 in a run, where players
-- average 7–13), chests, coins while the shops at 10–15 are ahead, a shop at 10–15 when there are coins to spend there
function DG.roomValue(x, money)
    local t, d = x.tags, x.d
    local v = 0
    if t[DG.T.GOLD] then v = v + 12 end
    if t[DG.T.CHEST] then v = v + 4 end
    if t[DG.T.MONEY] then v = v + (d <= 15 and 2 or 0.5) end
    if t[DG.T.SHOP] then
        if d >= 10 and d <= 15 then v = v + (money >= 300 and 5 or 1)
        else v = v + (money >= 300 and (d > 15 and 3 or 1) or 0.3) end
    end
    if t[DG.T.SHRINE] then v = v + 1.5 end
    if t[DG.T.CURSE] then v = v - DG.curseCost(DG.roomCurse(x.r)) end
    return v
end
-- the room's weak / strong elements, the way the match reads them
function DG.mod(l)
    local mod = { weak = {}, strong = {} }
    for _, w in pairs(type(l) == "table" and type(l._weak_against) == "table" and l._weak_against or {}) do
        if type(w) == "table" and w.damage_type then mod.weak[w.damage_type] = tonumber(w.amplification) or 1.5 end
    end
    for _, s in pairs(type(l) == "table" and type(l._strong_against) == "table" and l._strong_against or {}) do mod.strong[type(s) == "table" and s.damage_type or s] = true end
    return (next(mod.weak) or next(mod.strong)) and mod or nil
end
-- the curse a room brings: its tag holds it (_t["0"] = {id = "_curse_fly"})
function DG.roomCurse(r)
    local t = type(r) == "table" and type(r._t) == "table" and r._t or {}
    local c = t[0] or t["0"]
    return type(c) == "table" and c.id or nil
end
-- what the run's items and curses add up to (wave_modifier_effects; the game adds them, measured: two bows = range
-- ×1.70, not ×1.80), with a curse a room would bring on top. Not modelled: explosions
function DG.fx(dd, curseId, curseId2)
    local fx = { dmg = 1, cd = 1, range = 1, cost = 1, hp = 1, speed = 1, regen = 0, crit = 0, kinds = {}, shield = 0, fly = 0 }
    local items = DG.items(dd)
    if curseId and DG.item(curseId) then items[curseId] = (items[curseId] or 0) + 1 end
    if curseId2 and DG.item(curseId2) then items[curseId2] = (items[curseId2] or 0) + 1 end
    for id, n in pairs(items) do
        local it = DG.item(id)
        for _, ef in pairs(type(it and it.wave_modifier_effects) == "table" and it.wave_modifier_effects or {}) do
            local a = (tonumber(ef.amount) or 0) * n
            if ef.type == "stat_mul" and ef.stat == "damage" then fx.dmg = fx.dmg + a
            elseif ef.type == "stat_mul" and ef.stat == "attack_cooldown" then fx.cd = fx.cd + a
            elseif ef.type == "stat_mul" and ef.stat == "range" then fx.range = fx.range + a
            elseif ef.type == "stat_attr_add" and tostring(ef.stat):sub(1, 9) == "_dmg_mul_" then
                local k = tostring(ef.stat):sub(10)
                fx.kinds[k] = (fx.kinds[k] or 0) + a
            elseif ef.type == "stat_add" and ef.stat == "physical_crit_chance" then fx.crit = fx.crit + a
            elseif ef.type == "unit_cost" then fx.cost = fx.cost + a
            elseif ef.type == "enemy_stat_mul" and ef.stat == "health" then fx.hp = fx.hp + a
            elseif ef.type == "enemy_speedup" then fx.speed = fx.speed + a
            elseif ef.type == "enemy_regen" then fx.regen = fx.regen + a
            elseif ef.type == "enemy_shield" then fx.shield = fx.shield + a
            elseif ef.type == "enemy_passive_chance" and ef.passive == "Flying" then fx.fly = fx.fly + a end
        end
    end
    fx.cd, fx.cost, fx.speed = math.max(0.1, fx.cd), math.max(0.1, fx.cost), math.max(0.1, fx.speed)
    return fx
end
-- the same in words, for the log and the Modes tab
function DG.fxText(fx)
    local l = {}
    local function mul(name, v) if math.abs(v - 1) > 0.001 then table.insert(l, string.format("%s ×%.2f", name, v)) end end
    mul("damage", fx.dmg); mul("cooldown", fx.cd); mul("range", fx.range); mul("unit prices", fx.cost)
    for k, v in pairs(fx.kinds) do table.insert(l, string.format("%s +%d%%", k, math.floor(v * 100 + 0.5))) end
    if fx.crit > 0 then table.insert(l, string.format("physical crit +%d%%", math.floor(fx.crit * 100 + 0.5))) end
    mul("enemy HP", fx.hp); mul("enemy speed", fx.speed)
    if fx.regen > 0 then table.insert(l, string.format("enemy regen %d%%", math.floor(fx.regen * 100 + 0.5))) end
    if fx.shield > 0 then table.insert(l, string.format("enemy shield +%d", math.floor(fx.shield + 0.5))) end
    if fx.fly > 0 then table.insert(l, string.format("flyers +%d%%", math.floor(fx.fly * 100 + 0.5))) end
    return #l > 0 and table.concat(l, ", ") or "none"
end
-- the simulator on one room with your team and the run's items, plus a curse you'd pick up on the way (kept per room
-- seed while they're the same; nil when it can't play the room)
-- (spread = true: played the old way, attackers at the road's start. Only the curse check asks for that. Its bars were set against that reading, which stays on the
-- cautious side; the stacked reading is too hopeful for them: replayed on Nov 1 it gave room 12 "wins with room to spare" even with +80% enemy HP, and that room had
-- needed a bail-out without it)
function DG.sim(x, carried, spread)
    if not CFG.sim or type(x.r._l) ~= "table" then return nil end
    local key = tostring(x.r._r or (x.d .. ":" .. x.choice)) .. (carried and ("+" .. tostring(carried)) or "") .. (spread and "#spread" or "")
    local dd = DG.data()
    local fx = DG.fx(dd, DG.roomCurse(x.r), carried)
    -- (#stack: readings from before the simulator played stacked rooms don't carry over)
    local sig = MODE.teamSig() .. "#" .. DG.fxText(fx) .. (CFG.killZone ~= false and "#stack" or "")
    local c = B.dg.sim[key]
    if c and c.sig == sig then return not c.none and c or nil end
    local units = {}
    for _, e in ipairs(UNIT.equipped()) do table.insert(units, e.u) end
    if #units == 0 then return nil end
    local info = SIM.applyFx(SIM.info(SIM.slim(x.r._l), "dg", nil, DG.mod(x.r._l)), fx)
    if spread then info.zone = false end
    local w1 = SIM.wave(info, 1, true)
    if #w1 == 0 then
        c = { none = true, sig = sig, at = os.time() }
    else
        local res = SIM.evaluate(info, SIM.teamFrom(units, info.map))
        c = { p = res.p, wave = res.wave, won = res.won, total = info.total, margin = res.margin, sig = sig, at = os.time() }
    end
    B.dg.sim[key] = c
    -- (only the newest rooms are kept)
    if U.count(B.dg.sim) > 60 then
        local old, oldAt
        for k, v in pairs(B.dg.sim) do if not oldAt or (v.at or 0) < oldAt then old, oldAt = k, v.at or 0 end end
        B.dg.sim[old] = nil
    end
    SF.saveSoon()
    return not c.none and c or nil
end
-- a room's win chance: real results by depth (rooms get tougher deeper in; prior 94% at depth 1 down to 65% at
-- 20), and the simulator's guess where it can play the room
function DG.winP(x)
    local band = tostring(math.min(4, math.max(1, math.ceil(x.d / 5))))
    local r = B.dg.depth[band] or { runs = 0, wins = 0 }
    local p0 = U.clamp(0.95 - 0.015 * x.d, 0.5, 0.95)
    local p = ((tonumber(r.wins) or 0) + p0 * 2) / ((tonumber(r.runs) or 0) + 2)
    local okS, s = pcall(DG.sim, x)
    if okS and s and s.p then p = (p * 2 + s.p) / 3 end
    return p, okS and s or nil
end
-- "can't be beaten": the simulator loses even with enemies 25% weaker. A close loss isn't that: a room gives 5 tries, and
-- the simulator has called rooms losses that were then won
function DG.hopeless(s) return s ~= nil and s.won == false and (tonumber(s.p) or 1) <= 0.05 end
-- what a death would cost: the chests riding on the run (a rare chest pays about 3 times a chest)
function DG.stake(dd) local _, n, g = DG.res(dd); return n + 2 * g end
-- how sure the simulator has to be before the run takes a curse, by how deep it is and what's riding on it. A curse stays to room 20, and
-- rooms 15-20 are where enemy HP outgrows a team: both runs that died on Oct 31 took a curse at rooms 12-16 that the old rule ("not
-- hopeless") let through, and lost every chest a few rooms later (7, then 11). SIM.evaluate's p: 0.92 wins against 30% tougher enemies,
-- 0.7 wins, 0.25 wins only against 25% weaker, 0.05 hopeless
function DG.curseBar(dd, depth)
    local stake = DG.stake(dd)
    if depth >= 15 or stake >= 8 then return 0.9, "beat them against 30% tougher enemies", stake end
    if depth >= 10 or stake >= 4 then return 0.6, "beat them", stake end
    return 0.1, "have a chance at them", stake
end
-- a curse the simulator can't play (Chaos, Eruption, Armor, Burst): it changes nothing the simulator reads
function DG.blindCurse(dd, id) return DG.fxText(DG.fx(dd, id)) == DG.fxText(DG.fx(dd)) end
-- can the run take this curse? `here` is the curse's own room (simulated with it), `rooms` the rooms it leads to (with the curse carried):
-- one of them has to meet the bar, since the run picks one. A room the simulator can't play passes, as it always did. Returns true,
-- or false and the reason
function DG.curseOk(id, dd, depth, here, rooms)
    local name = tostring((DG.item(id) or {}).name or id)
    local bar, said, stake = DG.curseBar(dd, depth)
    if bar > 0.2 and DG.blindCurse(dd, id) then
        return false, string.format("the simulator can't play %s, and %d chests are riding on the run", name, stake)
    end
    local function meets(s) return s == nil or (tonumber(s.p) or 1) >= bar end
    if here then
        local okS, s = pcall(DG.sim, here, nil, true)
        if okS and not meets(s) then
            return false, string.format("with %s your team wouldn't %s (this room: %s)", name, (said:gsub("them", "this room")), tostring(s.margin or "?"))
        end
    end
    if #rooms == 0 then return true end
    local best
    for _, y in ipairs(rooms) do
        local okY, sy = pcall(DG.sim, y, id, true)
        if not okY or meets(sy) then return true end
        if not best or (tonumber(sy.p) or 0) > (tonumber(best.p) or 0) then best = sy end
    end
    return false, string.format("with %s your team wouldn't %s (the rooms after it, at best: %s)", name, said, tostring(best and best.margin or "?"))
end
-- a curse room: its curse has to pass DG.curseOk for the room itself and the rooms it leads to
function DG.curseGate(x, dd)
    local id = DG.roomCurse(x.r)
    if not id then return true end
    return DG.curseOk(id, dd, x.d, x, DG.after(dd, x.choice))
end
-- the next room: what it holds plus the best room it leads to (×0.6). Lives are tries at the room (5, a cleared room
-- refills them; a lost try showed 5 → 4, the next room back to 5), so a lost try costs time and the room is judged by the
-- chance to clear it within the tries left; the last one costs more (a guide: a restart after that takes a key). Kept while
-- the rooms on offer and the run's state are the same
-- what a dungeon room is worth by what its chests really paid (B.dg.pay with item counts, at the mode ranker's values; about 0.7 chests a room),
-- once 5 chests have been opened; nil before that
function DG.payValue()
    local sum, n = 0, 0
    for _, p in ipairs(B.dg.pay or {}) do
        if type(p.items) == "table" then
            local v = tonumber(p.gems) or 0
            for id, c in pairs(p.items) do if (tonumber(c) or 0) > 0 then v = v + MODE.itemValue(id, c) end end
            sum, n = sum + v, n + 1
        end
    end
    if n < 5 then return nil end
    return sum / n * 0.7
end
function DG.pick(dd)
    local curses, lives = DG.curses(dd), DG.lives(dd)
    local money = DG.res(dd)
    local rooms = DG.rooms(dd)
    local seeds = {}
    for _, x in ipairs(rooms) do table.insert(seeds, tostring(x.r._r)) end
    local sig = table.concat(seeds, ",") .. string.format("|%d|%d|%d|%s", lives, money, curses, MODE.teamSig())
    if DG._pick and DG._pick.sig == sig then return DG._pick.x end
    local best, bestAny
    for _, x in ipairs(rooms) do
        local v = DG.roomValue(x, money)
        local nv, ny
        for _, y in ipairs(DG.after(dd, x.choice)) do
            local w = DG.roomValue(y, money)
            if not nv or w > nv then nv, ny = w, y end
        end
        local p, s = DG.winP(x)
        local clear = 1 - (1 - p) ^ math.max(1, lives)
        local lossCost = lives >= 3 and 1 or (lives == 2 and 2 or 6)
        x.p, x.sim, x.value, x.nextValue, x.nextRoom = p, s, v, nv or 0, ny
        x.score = clear * (v + 0.6 * (nv or 0)) - (1 - p) * lossCost
        local okG, pass, why = pcall(DG.curseGate, x, dd)
        if okG and not pass then x.blocked = why end
        if not x.blocked and (not best or x.score > best.score) then best = x end
        if not bestAny or x.score > bestAny.score then bestAny = x end
    end
    -- (every room fails the check: the best of them, there's no other way on)
    best = best or bestAny
    DG._pick = { sig = sig, x = best, rooms = rooms }
    return best
end
function DG.roomName(x)
    local l = type(x.r._l) == "table" and x.r._l or {}
    return string.format("%s (%s)", tostring(l._location_name or l.map or "?"), DG.tagText(x.tags))
end
-- the screens a cleared room leaves, in order: current_shops = a list of {_t = the room tag as a string, data}
-- (seen Oct 30 after room 5, "shop + chest opening": {_t "1", data = {{id = "sword2"}, {id = "belt"}, {id = "bow1"}}},
-- {_t "6", data = true}); dungeon_continue_shop closes the first one. {} after a room with none
function DG.screens(dd)
    local out = {}
    for i, s in pairs(type(dd.current_shops) == "table" and dd.current_shops or {}) do
        if type(s) == "table" then table.insert(out, { i = tonumber(i) or 0, t = tonumber(s._t), data = s.data }) end
    end
    table.sort(out, function(a, b) return a.i < b.i end)
    return out
end
-- the depth of the room just cleared (the rooms on offer are one deeper)
function DG.cleared(dd) return math.max(1, (DG.depth(dd) or (DG.ROOMS + 1)) - 1) end
-- the screen the run is on: "rooms" (pick the next one), "dead", "finished", or the first screen a cleared room left
-- (shop / chest opening / shrine; another kind is logged in full once and closed, so it can be learned)
function DG.state(dd)
    if dd._dead then return "dead" end
    if dd._finished then return "finished" end
    local sc = DG.screens(dd)[1]
    if sc then
        if sc.t == DG.T.SHOP then return "shop", sc end
        if sc.t == DG.T.OPEN then return "chests", sc end
        if sc.t == DG.T.SHRINE then return "shrine", sc end
        return "screen", sc
    end
    return "rooms"
end
function DG.logState(dd, why)
    local keys = {}
    for k, v in pairs(dd) do if not DG.KNOWN[k] and not (type(v) == "table" and next(v) == nil) then table.insert(keys, tostring(k)) end end
    table.sort(keys)
    -- (each kind of screen counts as new: a shrine after a shop is logged too)
    local kinds = {}
    for _, sc in ipairs(DG.screens(dd)) do table.insert(kinds, tostring(sc.t)) end
    local sig = table.concat(keys, ",") .. (#kinds > 0 and ("|" .. table.concat(kinds, ",")) or "")
    if sig == "" or B.dg.seen[sig] then return end
    B.dg.seen[sig] = os.time()
    local parts = {}
    for _, k in ipairs(keys) do
        local v = dd[k]
        table.insert(parts, k .. "=" .. (type(v) == "table" and U.json(U.plain(v)):sub(1, 500) or tostring(v)))
    end
    SF.log(1, "DUNGEON", "new screen (" .. tostring(why) .. "): " .. table.concat(parts, " · "))
    SF.saveSoon()
end
function DG.note(msg)
    SF.log(1, "DUNGEON", msg)
    table.insert(B.dg.log, 1, { at = os.time(), msg = msg })
    while #B.dg.log > 15 do table.remove(B.dg.log) end
    SF.saveSoon()
end
-- the items a shop or shrine shows: {key, id, cost} from a list of ids, of {id, cost, ...}, or a map id → cost
-- (one level deeper when the screen wraps them)
function DG.offers(t, deep)
    local out = {}
    if type(t) ~= "table" then return out end
    for k, v in pairs(t) do
        local id, cost
        if type(v) == "table" then id = v.id or v.item_id or v.item; cost = tonumber(v.cost) or tonumber(v.price)
        elseif type(v) == "string" then id = v
        elseif DG.item(k) then id = k; cost = tonumber(v) end
        if type(id) == "string" and DG.item(id) then
            table.insert(out, { key = k, id = id, cost = cost or tonumber(DG.item(id).cost) or 0,
                bought = type(v) == "table" and (v.bought or v.sold or v.purchased) or nil })
        end
    end
    if #out == 0 and not deep then
        for _, v in pairs(t) do if type(v) == "table" then out = DG.offers(v, true); if #out > 0 then break end end end
    end
    return out
end
-- one purchase; the coins that drop say it went through (which argument form the game takes is remembered)
function DG.buy(o)
    local before = DG.res(DG.data())
    local tries = {}
    if B.dg.buyArg == "id" then tries = { o.id, o.key } else tries = { o.key, o.id } end
    if tries[1] == tries[2] then tries[2] = nil end
    for _, arg in ipairs(tries) do
        local ok, r = SF.request("dgBuy", "dungeon_buy_shop", arg)
        local t0 = U.now()
        while U.now() - t0 < 3 and DG.res(DG.data()) >= before do task.wait(0.25) end
        if DG.res(DG.data()) < before then
            B.dg.buyArg = (arg == o.id and o.id ~= o.key) and "id" or "key"
            return true
        end
        if not ok then break end
    end
    return false
end
-- a shop room in reach: among the rooms on offer, or the ones they lead to (all the game shows ahead)
function DG.shopAhead(dd)
    for _, x in ipairs(DG.rooms(dd)) do
        if x.tags[DG.T.SHOP] then return true end
        for _, y in ipairs(DG.after(dd, x.choice)) do if y.tags[DG.T.SHOP] then return true end end
    end
    return false
end
-- coins kept back from other items while a shop room is ahead: a Golden Fishhook's price, which covers a Fishhook too
-- (the user's rule. A run spent 660 on a Mage Coat and an Axe, and the very next shop sold a Golden Fishhook it couldn't
-- pay for; a Genie Lamp at 1000 comes up about 1 time in 15 as often as a Fishhook, too rare to hold everything back for)
DG.LUCK_RESERVE = 500
-- the least run value a coin has to buy (DG.itemValue ÷ price): a Sword is 0.10, a Longbow 0.05; Headsplitter for a magic team 0.003
DG.MIN_WORTH = 0.02
-- an item this good goes at any depth (not only from floor 10): Sword 0.10, Scimitar 0.15, Mage Coat 0.16, Magic Tome 0.20, Stormbringer 0.10. The
-- run that finished 20 rooms on Oct 31 carried damage ×1.75 and magic +250%; the two that died carried little, and one had walked past a Stormbringer at depth 6
DG.TOP_WORTH = 0.08
-- a shop: chest-luck items whenever they're affordable (the user's rule), everything else only from floor 10 on (coins
-- are kept for those shops), the most run value per coin first. Prices: the item's cost, +10% per Curse of Shopping
function DG.shop(dd, sc)
    local depth = DG.cleared(dd)
    local money = DG.res(dd)
    local priceMul = 1 + 0.1 * (DG.items(dd)._curse_shop or 0)
    local reserve = DG.shopAhead(dd) and math.ceil(DG.LUCK_RESERVE * priceMul) or 0
    local want = {}
    local seen, junk = {}, 0
    for _, o in ipairs(DG.offers(sc and sc.data)) do
        o.cost = math.ceil(o.cost * priceMul)
        table.insert(seen, tostring(DG.item(o.id).name or o.id))
        if not o.bought and not DG.isCurse(o.id) then
            o.luck = tonumber(DG.item(o.id).luck_increase) ~= nil
            o.v = DG.itemValue(o.id, dd)
            -- (an item that does nothing for this team isn't bought at any price: a damage-type item for a type your units don't deal)
            if not o.luck and o.v / math.max(1, o.cost) < DG.MIN_WORTH then junk = junk + 1
            elseif o.v > 0 and (o.luck or depth >= 10 or o.v / math.max(1, o.cost) >= DG.TOP_WORTH) then table.insert(want, o) end
        end
    end
    table.sort(want, function(a, b)
        if a.luck ~= b.luck then return a.luck end
        return a.v / math.max(1, a.cost) > b.v / math.max(1, b.cost)
    end)
    local got, skipped, held = {}, 0, 0
    for _, o in ipairs(want) do
        -- (chest luck may use every coin; anything else only what leaves the reserve)
        if o.cost <= money - (o.luck and 0 or reserve) then
            if DG.buy(o) then
                money = DG.res(DG.data())
                table.insert(got, string.format("%s (%d coins)", tostring(DG.item(o.id).name or o.id), o.cost))
            end
        elseif o.cost <= money then held = held + 1
        else skipped = skipped + 1 end
    end
    DG.note(string.format("shop at depth %d (%s): %s · %d coins left%s%s%s", depth, #seen > 0 and table.concat(seen, ", ") or "offer not read",
        #got > 0 and ("bought " .. table.concat(got, ", ")) or
        (depth < 10 and "no chest luck on sale: coins kept for the shops at floors 10–15" or (held > 0 and "nothing bought" or "nothing worth buying")), money,
        skipped > 0 and string.format(" (%d too dear)", skipped) or "",
        held > 0 and string.format(" (%d left on the shelf: %d coins kept for chest luck, a shop room is ahead)", held, reserve) or "",
        junk > 0 and string.format(" (%d would do nothing for this team's damage type)", junk) or ""))
    SF.request("dgCont", "dungeon_continue_shop")
end
-- a shrine: its offer is taken unless a curse in it would leave your team unable to beat the rooms ahead, the same test
-- as a curse room (DG.curseGate)
function DG.shrine(dd, sc)
    local offers = DG.offers(sc and sc.data)
    local good, names = 0, {}
    local blocked
    for _, o in ipairs(offers) do
        local it = DG.item(o.id)
        table.insert(names, tostring(it and it.name or o.id))
        if DG.isCurse(o.id) then
            -- (the same bar as a curse room: deep in the run, or with chests riding, the simulator has to see the rooms ahead won with it)
            local okC, pass, why = pcall(DG.curseOk, o.id, dd, DG.cleared(dd) + 1, nil, DG.rooms(dd))
            if okC and not pass then blocked = why end
        else good = good + DG.itemValue(o.id, dd) end
    end
    local take = #offers > 0 and good > 0 and not blocked
    if take then SF.request("dgShrine", "dungeon_shrine_accept") else SF.request("dgCont", "dungeon_continue_shop") end
    DG.note(string.format("shrine (%s): %s", #names > 0 and table.concat(names, ", ") or "offer not read",
        take and "taken" or (blocked and ("passed: " .. blocked) or "passed")))
end
-- chests: kept for floor 20 (Rare Chests by the user's rule; chests too, so every luck item bought on the way counts),
-- unless one life is left (a run that ends could take them along); at the last room everything is opened.
-- One at a time: the counter that drops says which kind a call opened
-- everything a chest could pay, to compare before and after (the open call itself answers nothing)
function DG.wallet()
    local pd = C.session() and C.session().profile_data or {}
    local inv = pd.inventory or {}
    local w = { gems = tonumber(C.cur("gems")) or 0, gold = tonumber(C.cur("gold")) or 0, items = {}, units = {}, unique = 0 }
    for id, n in pairs(inv.normal_items or {}) do w.items[id] = tonumber(n) or 0 end
    for uuid, u in pairs(pd.collection and pd.collection.owned_units or {}) do w.units[uuid] = u.unit_id end
    for _ in pairs(inv.unique_items or {}) do w.unique = w.unique + 1 end
    return w
end
function DG.walletDiff(a, b)
    local t = {}
    if b.gems ~= a.gems then table.insert(t, string.format("%+d gems", b.gems - a.gems)) end
    if b.gold ~= a.gold then table.insert(t, string.format("%+d gold", b.gold - a.gold)) end
    for id, n in pairs(b.items) do
        if n ~= (a.items[id] or 0) then table.insert(t, string.format("%+d %s", n - (a.items[id] or 0), tostring(id))) end
    end
    for uuid, id in pairs(b.units) do if not a.units[uuid] then table.insert(t, "new unit " .. UNIT.name(id)) end end
    if b.unique ~= a.unique then table.insert(t, string.format("%+d relics", b.unique - a.unique)) end
    return #t > 0 and table.concat(t, ", ") or "nothing seen"
end
function DG.openChests(dd, final)
    local _, n, g = DG.res(dd)
    local lives = DG.lives(dd)
    local depth = DG.cleared(dd)
    if not (final or depth >= DG.ROOMS or lives <= 1) then
        DG.note(string.format("chest room at depth %d: keeping %d chests and %d rare chests for floor 20 (luck ×%.1f now)", depth, n, g, DG.luck(dd)))
        SF.request("dgCont", "dungeon_continue_shop")
        return
    end
    local opened, rare, stuck = 0, 0, 0
    local gems0 = tonumber(C.cur("gems")) or 0
    local wallet = DG.wallet()
    for _ = 1, n + g + 4 do
        local _, n0, g0 = DG.res(DG.data())
        if n0 + g0 <= 0 or stuck >= 2 then break end
        local okC, got
        if n0 > 0 then okC, got = SF.request("dgChest", "dungeon_open_chest") else okC, got = SF.request("dgChest", "dungeon_open_chest", true) end
        -- (what a chest pays, to learn what a dungeon run is really worth)
        if okC and got ~= nil then SF.log(1, "DUNGEON", "chest: " .. (type(got) == "table" and U.json(U.plain(got)):sub(1, 300) or tostring(got))) end
        local t0 = U.now()
        while U.now() - t0 < 4 do
            local _, n1, g1 = DG.res(DG.data())
            if n1 < n0 or g1 < g0 then break end
            task.wait(0.25)
        end
        local _, n1, g1 = DG.res(DG.data())
        if n1 < n0 then opened = opened + (n0 - n1); stuck = 0
        elseif g1 < g0 then rare = rare + (g0 - g1); stuck = 0
        else stuck = stuck + 1 end
        task.wait(1)
        if n1 < n0 or g1 < g0 then
            local now = DG.wallet()
            local paid = DG.walletDiff(wallet, now)
            SF.log(1, "DUNGEON", (g1 < g0 and "rare chest: " or "chest: ") .. paid)
            B.dg.pay = B.dg.pay or {}
            -- (the items as counts too: the mode ranker values a dungeon run by what its chests really paid)
            local items = {}
            for id, n in pairs(now.items) do if n ~= (wallet.items[id] or 0) then items[id] = n - (wallet.items[id] or 0) end end
            table.insert(B.dg.pay, { at = os.time(), rare = g1 < g0, gems = now.gems - wallet.gems, luck = DG.luck(dd), paid = paid, items = items })
            while #B.dg.pay > 60 do table.remove(B.dg.pay, 1) end
            wallet = now
        end
    end
    DG.note(string.format("opened %d chests and %d rare chests (%s, luck ×%.1f) · gems %+d", opened, rare,
        final and "last room" or (lives <= 1 and "one life left" or "floor 20"), DG.luck(dd), (tonumber(C.cur("gems")) or 0) - gems0))
    local _, nL, gL = DG.res(DG.data())
    -- chests that didn't open stay in the run: leaving the last room would lose them (the game warns about it too)
    if (final or depth >= DG.ROOMS) and nL + gL > 0 then
        DG.note(string.format("%d chests and %d rare chests didn't open: the last room stays open, trying again in 30 min", nL, gL))
        MODE.rec("dg").restUntil = os.time() + 1800
        return "hold"
    end
    if not final then SF.request("dgCont", "dungeon_continue_shop") end
end
-- whatever screen the run is on, handled; false when it's the room choice
function DG.act(dd)
    local st, sc = DG.state(dd)
    DG.logState(dd, st)
    if st == "rooms" then return false end
    if st == "screen" then
        DG.note(string.format("a screen of a kind not known yet (tag %s): closed with Continue", tostring(sc and sc.t)))
        SF.request("dgCont", "dungeon_continue_shop")
        return true
    end
    if st == "dead" then
        SF.request("dgDeath", "dungeon_continue_death")
        DG.note("the run is over: that was the last life, and its unopened chests went with it")
        B.dg.lives, B.dg.lost = 5, {}
    elseif st == "finished" then
        if DG.openChests(dd, true) == "hold" then return "hold" end
        SF.request("dgCont", "dungeon_continue_shop")
        local money, n, g = DG.res(DG.data())
        table.insert(B.dg.runs, 1, { at = os.time(), depth = DG.ROOMS, items = U.count(DG.items(dd)), left = n + g })
        while #B.dg.runs > 10 do table.remove(B.dg.runs) end
        DG.note("dungeon finished: all 20 rooms")
    elseif st == "shop" then DG.shop(dd, sc)
    elseif st == "shrine" then DG.shrine(dd, sc)
    elseif st == "chests" then
        if DG.openChests(dd, false) == "hold" then return "hold" end
    end
    return true
end
-- lobby: the dungeon as a mode — screens between rooms first, then the best room (a new run when none is going)
function DG.launch(m)
    local dd = DG.data()
    if not dd then SF.backoff("launch", 30); return false end
    if not dd._started then
        if not (CFG.dungeonStart or CFG.onlyDungeons) then return false end
        local ok, r = SF.request("dgStart", "dungeon_start")
        task.wait(2.5)
        dd = DG.data()
        if not (ok and dd and dd._started) then
            SF.log(1, "DUNGEON", "the game didn't start a dungeon run (" .. tostring(r) .. "): trying again in 30 min")
            MODE.rec("dg").restUntil = os.time() + 1800
            SF.backoff("launch", 10)
            return false
        end
        B.dg.lost = {}
        DG.note("new dungeon run started (4 lives)")
    end
    if DG.enter(dd, m.value, false) then return true end
    SF.backoff("launch", 10)
    return false
end
-- in the lobby, before a room: the simulator tries your other units (damage-over-time ones and every farm included:
-- SIM.pool) against this room with the run's items and curses; with Auto-Equip Best Team on, the better team goes in. Your
-- team can only change in the lobby, so this comes at a run's first room and after a lost try
-- the user's own call to play the last life with the team they picked, whatever the simulator says: one try, gone after that room's result or half an hour
function DG.playLast()
    local p = B.dg.playLast
    return type(p) == "table" and os.time() - (tonumber(p.at) or 0) < 1800 and p or nil
end
function DG.forced(x)
    local f = B.dg.force
    if type(f) ~= "table" or type(f.uuids) ~= "table" or f.seed ~= tostring(x.r._r) then return nil end
    if os.time() - (tonumber(f.at) or 0) > 3600 then B.dg.force = nil; return nil end
    return f
end
-- the team for a room entered from a results screen: changed as the room starts, before its first wave (MT.startTeam, your call Nov 1). If it doesn't take, no wave starts and the run
-- goes to the lobby, which costs no try
function DG.startTeam(uuids, x, why, own)
    B.startTeam = { uuids = table.clone(uuids), must = true, own = own or nil, seed = tostring(x.r._r), why = why }
end
function DG.planTeam(x, dd, fromMatch)
    if not (CFG.sim and CFG.simTeams) or type(x.r._l) ~= "table" then return end
    if DG.playLast() then
        SF.log(1, "SIM", string.format("dungeon room %d: your own pick stays, no search", x.d))
        return
    end
    -- the user's own team for one room (B.dg.force: uuids, seed, label, at), whatever the simulator says; an hour, then forgotten
    local force = DG.forced(x)
    if force then
        if fromMatch then
            SF.log(1, "SIM", string.format("dungeon room %d: your call — %s goes in as the room starts, no search", x.d, tostring(force.label)))
            if not TRAIN.same(TRAIN.team(), force.uuids) then DG.startTeam(force.uuids, x, tostring(force.label)) end
            return
        end
        SF.log(1, "SIM", string.format("dungeon room %d: your call — %s goes in, no search", x.d, tostring(force.label)))
        HUB.equipTeam(force.uuids, tostring(force.label))
        task.wait(0.5)
        return
    end
    -- (with Auto-Equip Best Team off, your team stays: nothing to work out)
    if fromMatch and not CFG.autoTeam then return end
    -- (it looked a moment ago for this same room: no second search)
    local was = B.simTeam.dg
    if not fromMatch and CFG.autoTeam and was and was.better and was.seed == tostring(x.r._r) and os.time() - (tonumber(was.at) or 0) < 300 then
        HUB.equipTeam(was.uuids, "the best team found for dungeon room " .. x.d)
        task.wait(0.5)
        return
    end
    local fx = DG.fx(dd, DG.roomCurse(x.r))
    local units = {}
    -- (on a results screen a planned team may still be on: "your team" is the one kept in B.savedTeam)
    if fromMatch and type(B.savedTeam) == "table" and #B.savedTeam > 0 then
        local s = C.session()
        for _, uuid in ipairs(B.savedTeam) do local u = s.collection:get_unit_by_uuid(uuid); if u then table.insert(units, u) end end
    else
        for _, e in ipairs(UNIT.equipped()) do table.insert(units, e.u) end
    end
    if #units == 0 then return end
    local mod = DG.mod(x.r._l)
    local info = SIM.applyFx(SIM.info(SIM.slim(x.r._l), "dg", nil, mod), fx)
    SF.status("Mode", "looking for the best team for dungeon room " .. x.d)
    -- (the last life gets a longer search)
    local pool = SIM.pool(mod, info)
    local team, r, hard, cur = SIM.bestTeam(info, units, pool, DG.lives(dd) <= 1 and 45 or 20)
    -- how each team stands, real wins and losses counted: for the log, and for what a bleeder swap has to beat below
    local function standing(list)
        local sig = SIM.sig(list)
        local rec = type(B.dg.teams) == "table" and B.dg.teams[sig] or {}
        local lostHere = type(B.dg.lost) == "table" and B.dg.lost[tostring(x.r._r)] and B.dg.lost[tostring(x.r._r)][sig] or 0
        -- (a bail-out in the last half hour counts as a loss here for the team that bailed)
        if type(B.dg.bail) == "table" and B.dg.bail.sig == sig and os.time() - (tonumber(B.dg.bail.at) or 0) < 1800 then lostHere = lostHere + 1 end
        local wins, atOne, reach, far = SIM.strength(info, list)
        local real = math.clamp((tonumber(rec.w) or 0) - 2 * (tonumber(rec.l) or 0), -6, 3)
        -- (from room 13 on, wins in the shallow rooms say little: the record counts for one at most. Room 15 kept the team with 52 wins
        -- at 5 of 15 over a team at 9 of 15 with no record, and lost at wave 9)
        if x.d >= 13 then real = math.min(real, 1) end
        real = real - 3 * lostHere
        return { score = wins + real, wins = wins, atOne = atOne, reach = reach, far = far, lostHere = lostHere, w = tonumber(rec.w) or 0, l = tonumber(rec.l) or 0 }
    end
    local same = SIM.sig(team) == SIM.sig(units)
    local mine = standing(units)
    local best = same and mine or standing(team)
    -- enemies that regenerate (a Curse of Regen on the run, or the room's): a bleed stops it while it lasts (the game's Effects page; the
    -- simulator plays it), and the search's samples can miss that one swap. So your strongest bleeder is tried in every attacker's slot,
    -- and the best of those stands beside the search's team. Room 17, Oct 31: your team 1 of 15 and Cursed Lord in for Gene 6 of 15
    if (info.regen or 0) > 0 then
        local hasBleed = false
        for _, u in ipairs(units) do if UNIT.bleeds(u.unit_id) then hasBleed = true end end
        for _, u in ipairs(team) do if UNIT.bleeds(u.unit_id) then hasBleed = true end end
        local bleeder = not hasBleed and UNIT.bestBleeder(units) or nil
        if bleeder then
            local tried = {}
            for i, u in ipairs(units) do
                if not UNIT.isFarm(u.unit_id) and not UNIT.allyBuff(u.unit_id) then
                    local alt = table.clone(units)
                    alt[i] = bleeder
                    local st = standing(alt)
                    table.insert(tried, string.format("%s out: %d tries", UNIT.name(u.unit_id), st.wins))
                    if st.score > best.score then team, best, same = alt, st, false; r = { won = st.wins > 0, wave = st.reach } end
                    task.wait()
                end
            end
            SF.log(1, "SIM", string.format("dungeon room %d: enemies regenerate, so %s (bleeds from upgrade %d) was tried in each slot: %s", x.d, UNIT.name(bleeder.unit_id), UNIT.bleeds(bleeder.unit_id) or 0, table.concat(tried, " · ")))
        end
    end
    -- the search's top pick plays, here too (the user's call, Nov 1: "top picks for dungeon too"), as long as it really goes further up the rising test than your team, the same test as every other mode
    -- (SIM.plan); a tie keeps your team. One more exception: a pick that has really lost this room more often than your team gives way, or a search that finds the same team every time would spend all 5 tries on it
    local further = best.wins > mine.wins or (best.wins == mine.wins and (best.far or 0) > (mine.far or 0))
    local better = not same and further and best.lostHere <= mine.lostHere
    local uuids, names = {}, {}
    for _, u in ipairs(team) do table.insert(uuids, u.uuid); table.insert(names, UNIT.name(u.unit_id)) end
    B.simTeam.dg = { uuids = uuids, names = names, won = r.won, wave = r.wave, better = better, cur = { won = cur.won, wave = cur.wave }, at = os.time(), label = "Dungeon", seed = tostring(x.r._r) }
    local function said(s) return string.format("wins %d simulated tries up the rising test, gets to wave %d at normal strength, real rooms %d won and %d lost", s.wins, math.floor(s.reach + 0.5), s.w, s.l) end
    if not better then
        if same then SF.log(1, "SIM", string.format("dungeon room %d: tried %d units, none beats your team (%s)", x.d, #pool, said(mine)))
        elseif not further then SF.log(1, "SIM", string.format("dungeon room %d: your team goes in (%s): the search's pick, %s, doesn't go further up the rising test (%s)", x.d, said(mine), table.concat(names, ", "), said(best)))
        else SF.log(1, "SIM", string.format("dungeon room %d: your team goes in (%s): the search's pick, %s, already lost here %d times (%s)", x.d, said(mine), table.concat(names, ", "), best.lostHere, said(best))) end
        -- (a planned team from the last room is still on, and this one doesn't want it)
        if fromMatch and type(B.savedTeam) == "table" and not TRAIN.same(TRAIN.team(), B.savedTeam) then DG.startTeam(B.savedTeam, x, "your own team back for dungeon room " .. x.d, true) end
        return
    end
    SF.log(1, "SIM", string.format("dungeon room %d: the search's top pick: %s (%s; yours: %s)", x.d, table.concat(names, ", "), said(best), said(mine)))
    if fromMatch then
        if not TRAIN.same(TRAIN.team(), uuids) then DG.startTeam(uuids, x, "the simulator's best team for dungeon room " .. x.d) end
        return
    end
    if CFG.autoTeam then
        HUB.equipTeam(uuids, "the simulator's best team for dungeon room " .. x.d)
        task.wait(0.5)
    else
        SF.log(1, "SIM", "Auto-Equip Best Team is off, so your team stays as it is")
    end
end
-- the screens between rooms, then the best room, entered (true = teleporting). From a room's results screen the
-- game takes any room on offer; from the lobby only the one its own selection holds (selected_next.choice_str, a
-- string) and it ignores the others without a word — Oct 30 its "1" teleported, "3" and 3 didn't. So in the lobby
-- the farm's pick goes first (in case the selection follows it), then the game's
function DG.enter(dd, value, fromMatch)
    for _ = 1, 5 do
        local okA, acted = pcall(DG.act, dd)
        if not okA then SF.log(1, "ERROR", "dungeon screen: " .. tostring(acted)); break end
        if acted == "hold" then return false end
        if not acted then break end
        task.wait(2)
        dd = DG.data()
        if not (dd and dd._started) then return false end
    end
    DG._pick = nil
    local x = DG.pick(dd)
    if not x then
        DG.logState(dd, "no rooms on offer")
        -- (never Continue with chests still in the run: on the last room that would lose them)
        local _, nL, gL = DG.res(dd)
        if nL + gL > 0 then
            SF.log(1, "DUNGEON", string.format("no room on offer and %d + %d chests unopened: nothing pressed, trying again in 30 min", nL, gL))
            MODE.rec("dg").restUntil = os.time() + 1800
            return false
        end
        SF.log(1, "DUNGEON", "no room on offer: leaving the screen it's on")
        SF.request("dgCont", "dungeon_continue_shop")
        return false
    end
    -- (before every room. Found on a results screen, a better team goes on as the room starts: MT.startTeam)
    local okT, eT = pcall(DG.planTeam, x, dd, fromMatch)
    if not okT then SF.log(1, "ERROR", "dungeon team: " .. tostring(eT)) end
    -- the room isn't entered until the team it was planned for is really equipped, all six (the user's rule: "get the right swap before
    -- going to the next map"). A swap the game won't take twice gives way to your own team, and the run waits for that one too
    if not fromMatch then
        local plan = B.simTeam.dg
        local seed = tostring(x.r._r)
        B.dg.swapFail = type(B.dg.swapFail) == "table" and B.dg.swapFail or {}
        local fails = tonumber(B.dg.swapFail[seed]) or 0
        local force = DG.forced(x)
        local want = (force and force.uuids) or ((plan and plan.better and plan.seed == seed and fails < 2) and plan.uuids) or B.savedTeam
        local have = TRAIN.team()
        local right = #have == 6 and (not want or TRAIN.same(have, want))
        if not right then
            B.dg.swapFail[seed] = fails + 1
            local names = {}
            for _, e in ipairs(UNIT.equipped()) do table.insert(names, UNIT.name(e.id)) end
            if fails + 1 >= 2 and plan and plan.better and plan.seed == seed then
                plan.better = false
                SF.log(1, "TEAM", string.format("the planned team for room %d wouldn't equip twice: your own team goes in instead", x.d))
                pcall(HUB.restoreTeam)
            end
            SF.log(1, "DUNGEON", string.format("room %d not entered: the team isn't right yet (%d units: %s). Trying the swap again in a moment", x.d, #have, table.concat(names, ", ")))
            SF.status("Mode", "waiting for the right team before dungeon room " .. x.d)
            MODE.rec("dg").restUntil = os.time() + 45
            B.pending = nil
            SF.saveSoon()
            return false
        end
        B.dg.swapFail[seed] = nil
        -- (the team is right: now the relics that suit it)
        local okRl, eRl = pcall(STR.relicsApply)
        if not okRl then SF.log(1, "ERROR", "relics: " .. tostring(eRl)) end
    end
    -- the last life: losing it can end the run and its chests with it. A team that already lost here twice doesn't get it (the
    -- simulator's "win" 4 times on Oct 31, with no flyers or shields in it, cost 4 lives). The simulator's last word comes in the
    -- room, with the map's real spots, before a wave starts: MT.planSpots
    if DG.lives(dd) <= 1 then
        B.dg.lost = B.dg.lost or {}
        local s = DG.sim(x)
        local tried = (B.dg.lost[tostring(x.r._r)] or {})[MODE.teamSig()] or 0
        -- (nor a team with an empty slot: room 13's last life went in on 5 units on Oct 31, and nothing looked)
        local short = #UNIT.equipped() < 6
        if (not s or tried >= 2 or short) and not (DG.playLast() and not short) then
            local why = short and string.format("the team has only %d units", #UNIT.equipped()) or tried >= 2 and string.format("this team already lost here %d times", tried) or "the simulator can't play this room"
            DG.note(string.format("last life on room %d: holding it (%s). Looks again in an hour", x.d, why))
            MODE.rec("dg").restUntil = os.time() + 3600
            B.pending = nil
            SF.saveSoon()
            return false
        end
    end
    B.dg.room = { seed = x.r._r, d = x.d }
    B.pending = { key = "dg", kind = "dungeon", level = "dungeon", diff = "Hard", label = "Dungeon room " .. x.d, at = os.time(), value = value, depth = x.d }
    if B.nextMode == "dg" then B.nextMode = nil end
    local money, n, g = DG.res(dd)
    local why = string.format("win ≈%d%%%s · leads to %s · %d lives · %d coins · chests %d + %d rare", math.floor(x.p * 100 + 0.5),
        x.sim and (" (sim: " .. tostring(x.sim.margin) .. ")") or "", x.nextRoom and DG.roomName(x.nextRoom) or "the last room", DG.lives(dd), money, n, g)
    SF.log(1, "MODE", string.format("entering dungeon room %d/%d%s: %s — %s", x.d, DG.ROOMS, fromMatch and " from the results screen" or "", DG.roomName(x), why))
    -- (what it was chosen over: was a curse avoidable?)
    local others = {}
    for _, r in ipairs(DG._pick and DG._pick.rooms or {}) do
        if r ~= x then table.insert(others, string.format("%s, win ≈%d%%%s", DG.roomName(r), math.floor((r.p or 0) * 100 + 0.5), r.blocked and (" (skipped: " .. r.blocked .. ")") or "")) end
    end
    if #others > 0 then SF.log(1, "DUNGEON", "chosen over: " .. table.concat(others, " · ")) end
    SF.saveNow() -- the teleport kills this script: the match reads what we launched from the brain
    SF.status("Mode", "entering dungeon room " .. x.d)
    local sel = type(dd.selected_next) == "table" and dd.selected_next.choice_str and tostring(dd.selected_next.choice_str) or nil
    local tries = { tostring(x.key) }
    if sel and sel ~= tostring(x.key) and not fromMatch then table.insert(tries, sel) end
    for i, arg in ipairs(tries) do
        if i == 2 then
            local y
            for _, r in ipairs(DG.rooms(dd)) do if tostring(r.key) == arg then y = r end end
            SF.log(1, "DUNGEON", string.format("the game only lets the run enter its selected room %s: %s", arg, y and DG.roomName(y) or "?"))
        end
        local ok, r = SF.request("dgEnter", "dungeon_enter_room", arg)
        local t0 = U.now()
        while SF.alive and U.now() - t0 < 15 do task.wait(1) end
        if not SF.alive then return true end
        SF.log(1, "DUNGEON", string.format("no teleport after entering room %s (answer %s)", arg, tostring(r)))
    end
    DG.logState(dd, "enter didn't teleport")
    B.pending = nil
    if not fromMatch then MODE.rec("dg").restUntil = os.time() + 900 end
    SF.saveSoon()
    return false
end
-- a room's results screen: the next room straight from here while the run goes on (no lobby in between)
function DG.chain()
    -- (the server updates dungeon_data a moment after the result: the rooms ahead, coins, the selection gone)
    task.wait(4)
    local dd = DG.data()
    if not (dd and dd._started) then return false end
    return DG.enter(dd, CFG.dungeonValue, true)
end
-- match: a room's result counts for its depth (the win chances of the rooms ahead)
function DG.roomDone(won)
    B.dg.playLast = nil
    local d = tonumber(type(MT.ld._dungeon) == "table" and MT.ld._dungeon.depth) or (B.pending and tonumber(B.pending.depth)) or 1
    local band = tostring(math.min(4, math.max(1, math.ceil(d / 5))))
    local r = B.dg.depth[band] or { runs = 0, wins = 0 }
    r.runs, r.wins = (tonumber(r.runs) or 0) + 1, (tonumber(r.wins) or 0) + (won and 1 or 0)
    B.dg.depth[band] = r
    local dd = DG.data()
    local money, n, g = DG.res(dd)
    DG.note(string.format("room %d/%d %s · %d coins · chests %d + %d rare · %d lives", d, DG.ROOMS, won and "cleared" or "lost", money, n, g, DG.lives(dd)))
    -- how this team really did (DG.planTeam weighs it beside the simulator)
    B.dg.teams = type(B.dg.teams) == "table" and B.dg.teams or {}
    local rec = B.dg.teams[MODE.teamSig()] or { w = 0, l = 0 }
    if won then rec.w = (tonumber(rec.w) or 0) + 1 else rec.l = (tonumber(rec.l) or 0) + 1 end
    B.dg.teams[MODE.teamSig()] = rec
    if won then
        -- (the next room starts on 5 lives; the game only shows them once it's selected)
        B.dg.lives = 5
    elseif B.dg.room and B.dg.room.d == d then
        -- which team lost in which room (the last-life rule in DG.enter)
        B.dg.lost = B.dg.lost or {}
        local seed, sig = tostring(B.dg.room.seed), MODE.teamSig()
        B.dg.lost[seed] = B.dg.lost[seed] or {}
        B.dg.lost[seed][sig] = (B.dg.lost[seed][sig] or 0) + 1
    end
end
-- the Modes tab's dungeon paragraph
function DG.text()
    if not CFG.dungeon then return "Off." end
    local dd = DG.data()
    if not dd then return "No dungeon data yet (shows in the lobby)." end
    if not dd._started then return CFG.dungeonStart and "No run going: the farm starts one when the dungeon ranks first." or "No run going (starting new runs is off)." end
    local money, n, g = DG.res(dd)
    local items, curses = {}, {}
    for id, c in pairs(DG.items(dd)) do
        local nm = tostring((DG.item(id) or {}).name or id) .. (c > 1 and (" ×" .. c) or "")
        table.insert(DG.isCurse(id) and curses or items, nm)
    end
    local lines = { string.format("Room %s/%d · %d lives · %d coins · chests %d + %d rare · luck ×%.1f", tostring(DG.depth(dd) or "?"), DG.ROOMS, DG.lives(dd), money, n, g, DG.luck(dd)) }
    table.insert(lines, "Items: " .. (#items > 0 and table.concat(items, ", ") or "none") .. " · Curses: " .. (#curses > 0 and table.concat(curses, ", ") or "none"))
    table.insert(lines, "They add up to: " .. DG.fxText(DG.fx(dd)))
    local x = DG._pick and DG._pick.x
    if x then table.insert(lines, string.format("Next: %s, win ≈%d%%", DG.roomName(x), math.floor(x.p * 100 + 0.5))) end
    for i, e in ipairs(B.dg.log) do if i <= 4 then table.insert(lines, os.date("%H:%M ", e.at) .. e.msg) end end
    return table.concat(lines, "\n")
end

-- ============================================================
--  MATCH
-- ============================================================
MT.refused, MT.spent, MT.actions = {}, 0, {}
MT.waveMax = {}
function MT.mapKey() return tostring(MT.ld and MT.ld.map or "?") end
function MT.label()
    if MT.kind == "dungeon" then
        local d = type(MT.ld._dungeon) == "table" and MT.ld._dungeon.depth or "?"
        return string.format("Dungeon room %s/%d · %s", tostring(d), DG.ROOMS, tostring(MT.ld._location_name or MT.ld.map or "?"))
    end
    return MODE.levelName(MT.ld.id or "?") .. (MT.ld._difficulty and (" (" .. MT.ld._difficulty .. ")") or "")
end
function MT.money() local s = LP:FindFirstChild("_stats"); return s and s.resource.Value or 0 end
function MT.wave() return workspace:FindFirstChild("_wave_num") and workspace._wave_num.Value or 0 end
-- road samples every 2 studs on every lane, with how far along the road they are (0 = spawn, 1 = base)
function MT.buildPath()
    MT.samples = {}
    local cache = C.PATH and C.PATH.PATH_CACHE and C.PATH.PATH_CACHE[workspace._BASES.pve]
    if not cache then return end
    for lane, v in pairs(cache) do
        if not (C.PATH.HIDDEN_MOCK_LANES and C.PATH.HIDDEN_MOCK_LANES[lane.Name]) then
            local pts = {}
            for _, p in ipairs(v.points or {}) do table.insert(pts, p.part.Position) end
            local total = 0
            for i = 2, #pts do total = total + (pts[i] - pts[i - 1]).Magnitude end
            local walked = 0
            for i = 2, #pts do
                local a, b = pts[i - 1], pts[i]
                local len = (b - a).Magnitude
                local steps = math.max(1, math.floor(len / 2))
                for k = 0, steps - 1 do
                    local pos = a:Lerp(b, k / steps)
                    table.insert(MT.samples, { pos = pos, prog = (walked + len * k / steps) / math.max(1, total), lane = lane.Name })
                end
                walked = walked + len
            end
            if pts[#pts] then table.insert(MT.samples, { pos = pts[#pts], prog = 1, lane = lane.Name }) end
        end
    end
    -- the lanes, by name and length (more than one: placement weighs each, MT.coverage)
    local by, n, sum = {}, 0, 0
    for _, s in ipairs(MT.samples) do local l = tostring(s.lane); if not by[l] then n = n + 1 end; by[l] = (by[l] or 0) + 1; sum = sum + 1 end
    MT.laneCount = { n = n, by = by, avg = n > 0 and sum / n or 1 }
end
-- the waves of this level (Data.Waves, following templates / overrides)
function MT.buildWaves()
    local ld = MT.ld
    -- (a dungeon room plays a story act's waves: _override_waves.template, the same source the sim reads)
    local ow = ld and ld._dungeon and type(ld._override_waves) == "table" and ld._override_waves or nil
    local w = ld and C.Waves[(ow and ow.template) or ld.waves or ld.id]
    local list
    if type(w) == "table" then
        list = w.override_waves or w.waves
        if not list and w.template and C.Waves[w.template] then list = C.Waves[w.template].waves or C.Waves[w.template].override_waves end
    end
    MT.waveList = U.list(list)
    -- Infinite: no last wave; the waves the team is expected to last stand in for one (MT.infExtend moves it on)
    MT.infinite = ld and (ld._gamemode == "infinite" or ld.infinite) and SIM.unbound(ld) or false
    if MT.infinite then
        MT.waveList = {}
        MT.total = math.max(30, math.floor(MODE.infReach(MT.key) + 0.5))
        return
    end
    MT.total = (ld and type(ld._dungeon) == "table" and 15) or tonumber(ld and ld._override_infinite_bound_waves) or (#MT.waveList > 0 and #MT.waveList) or 15
end
-- (a team that outlasts the expected wave keeps buying as if 10 more waves come)
function MT.infExtend()
    if MT.infinite and MT.wave() + 5 > MT.total then MT.total = MT.wave() + 10 end
end
-- each new Infinite wave: the expected last wave moves on, and right after a daily milestone the profile is checked
-- for the claim (learns whether the game pays it during the run or only at the end)
function MT.infWave(w)
    MT.infExtend()
    if CFG.trainLeave and not MT.stopping then local okT, eT = pcall(MT.trainLeave, w); if not okT then SF.log(1, "ERROR", "leave when trained: " .. tostring(eT)) end end
    if CFG.infiniteStop and not MT.stopping then local okS, eS = pcall(MT.infStop, w); if not okS then SF.log(1, "ERROR", "Infinite stop: " .. tostring(eS)) end end
    local tier = MODE.infTier(w - 1)
    if tier <= 0 or tier == MT.infTierSeen then return end
    MT.infTierSeen = tier
    task.delay(5, function()
        if not SF.alive then return end
        local p = C.prof()
        local c = p and p.daily_infinite_reward_claims and p.daily_infinite_reward_claims[MT.ld.id]
        local live = type(c) == "table" and (tonumber(c.highest_claimed_wave) or 0) >= tier and os.time() - (tonumber(c.highest_claim_time) or 0) < 900
        if live then B.infLive = true end
        SF.log(1, "MATCH", string.format("Infinite: wave %d passed — daily gems %s", tier, live and "claimed now" or "not in your profile yet (paid at the end?)"))
    end)
end
-- past its last daily milestone, an Infinite run with no unit training in it pays only a few gems a wave (Sand
-- Village: 497 gems for 136 waves in 126 min, 200 of them the daily ones), so it ends there when another mode pays
-- more a minute: your units are sold, the base falls and the run pays out like any other
function MT.infStop(w)
    local last = 0
    for _, r in ipairs(U.list(C.GS.DAILY_INFINITE_REWARDS)) do last = math.max(last, tonumber(r.wave) or 0) end
    if last <= 0 or w <= last + 1 then return end
    local on = B.train.on
    if MT.trainee and on and on.have + (on.got or 0) + (MT.trainTk or 0) < on.need then return end
    if not HUB.every("infStop", 60) then return end
    -- the gems a minute this run still makes: what Infinite runs paid beyond the daily gems, per minute played
    local rec = MODE.rec(MT.key)
    local runs = tonumber(rec.timed) or 0
    local perMin = (runs > 0 and (rec.sec or 0) > 0) and math.max(0.5, ((rec.gems or 0) - 200 * runs) / (rec.sec / 60)) or 2.5
    local okP = pcall(MODE.pick)
    local alt
    for _, m in ipairs(okP and MODE.lastScored or {}) do if m.kind ~= "infinite" and (not alt or (m.score or 0) > (alt.score or 0)) then alt = m end end
    if not alt or (alt.score or 0) <= perMin then return end
    MT.stopping = true
    SF.log(1, "MATCH", string.format("Infinite: wave %d, the daily gems are in and no unit trains here — ending the run (≈%.1f gems/min from here, %.1f in %s): selling your units", w, perMin, alt.score, alt.label))
    MT.sellAll()
end
-- takedown training: the unit in training has all its takedowns, so the run ends and the lobby evolves it (the user's call, Nov 2: Snow Reaper (War) needed 7,500 and made 21,128 in one Infinite run
-- that went on past wave 170). A daily-gem wave still ahead in reach is played to first. Selling, like End Infinite Early: the base falls, and the run pays and counts as usual
function MT.trainLeave(w)
    local on = B.train.on
    if not (MT.infinite and MT.trainee and on) then return end
    MT.trainCount()
    local total = on.have + (on.got or 0) + (MT.trainTk or 0)
    if total < on.need then return end
    local okD, gems, top = pcall(MODE.infDaily, C.prof(), MT.ld.id, (MODE.infReach(MT.key)))
    if okD and (gems or 0) > 0 and top > 0 and w <= top then
        SF.status("Training", string.format("%s has its %s: playing to wave %d for the daily gems, then ending the run", UNIT.name(on.id), on.what, top))
        return
    end
    MT.stopping = true
    SF.log(1, "MATCH", string.format("Infinite: %s has its %s (%s of %s) — ending the run at wave %d so it can evolve: selling your units", UNIT.name(on.id), on.what, U.fmt(total), U.fmt(on.need), w))
    MT.sellAll()
end
-- the run ends: every unit sold, so the base falls
function MT.sellAll()
    -- every unit once, farms last (the game wouldn't sell a golden Bulby mid-run: a loop on the first unit left
    -- stood still for 14 min); one the game refuses is tried once more at the end, then left
    task.spawn(function()
        -- (Bulby is `unsellable` in the game's own data: left out from the start)
        local list = {}
        for _, m in ipairs(MT.mine or {}) do
            local s = m:FindFirstChild("_stats")
            local d = s and s:FindFirstChild("id") and C.Units[s.id.Value]
            if not (d and d.unsellable) then table.insert(list, m) end
        end
        local function farm(m) local s = m:FindFirstChild("_stats"); return s and s:FindFirstChild("id") and UNIT.isFarm(s.id.Value) or false end
        table.sort(list, function(a, b) return (farm(a) and 1 or 0) < (farm(b) and 1 or 0) end)
        local kept = {}
        for pass = 1, 2 do
            local again = {}
            for _, m in ipairs(pass == 1 and list or kept) do
                if not SF.alive or MT.finished then return end
                if m.Parent and m.Parent.Name == "_UNITS" then
                    local _, sold = SF.request("sell", "sell_unit_ingame", m)
                    if sold ~= true then table.insert(again, m) end
                    task.wait(1.3)
                end
            end
            kept = again
        end
        if #kept > 0 then
            local names = {}
            for _, m in ipairs(kept) do table.insert(names, m.Name) end
            SF.log(1, "MATCH", "the game didn't sell " .. table.concat(names, ", ") .. " (the run still ends: nothing else is defending)")
        end
    end)
end
-- the yen wave i pays when it ends (listed reward × the world's money scale)
function MT.waveReward(i)
    if MT.info then return SIM.waveYen(MT.info, i) end
    local w = MT.waveList and MT.waveList[i]
    return (w and tonumber(w.wave_reward) or 0) * 2.6
end
function MT.progressAt(pos)
    local best, bd, lane = 0, math.huge, nil
    local fp = U.flat(pos)
    for _, s in ipairs(MT.samples) do
        local d = (U.flat(s.pos) - fp).Magnitude
        if d < bd then bd, best, lane = d, s.prog, s.lane end
    end
    return best, bd, lane ~= nil and tostring(lane) or nil
end
function MT.scan()
    local list, mine = {}, {}
    for _, folder in ipairs({ workspace._UNITS }) do
        for _, m in ipairs(folder:GetChildren()) do
            local st = m:FindFirstChild("_stats")
            if st and st:FindFirstChild("player") then
                -- summons (Metal Knight's drones…) have a parent unit and no stats of their own: not your units.
                -- A Clone spell's copy has a parent unit too, but it's a real unit: the same id as its parent (when that
                -- is still alive) and a real price (summons cost ¥0–1) — it was left out, never upgraded or merged,
                -- though it keeps a Merge's gain (an Elf Mage clone did 525k of the original's 625k)
                local pu = st:FindFirstChild("parent_unit")
                local pv = pu and pu.Value
                local pst = pv and pv:FindFirstChild("_stats")
                local d = C.Units[st.id.Value]
                local clone = pv ~= nil and d ~= nil and (tonumber(d.cost) or 0) >= 100 and (not pst or (pst:FindFirstChild("id") and pst.id.Value == st.id.Value))
                -- (the Ritual's Divine General — "Holy Warlord", id mahoraga, ¥0 and unsellable — is yours too)
                if st.id.Value == "mahoraga" then clone = true end
                -- (and one with no range of its own: Elyssia's eel, once the copy that made it is gone, has no parent left and broke the targeting pass)
                local summon = (pv ~= nil and not clone) or not st:FindFirstChild("attack_cooldown") or not st:FindFirstChild("upgrade") or not st:FindFirstChild("range")
                if st.player.Value == LP then
                    if not summon then table.insert(mine, m) end
                elseif st.player.Value == nil and m:FindFirstChild("HumanoidRootPart") then
                    local prog, _, lane = MT.progressAt(m.HumanoidRootPart.Position)
                    local hum = m:FindFirstChildOfClass("Humanoid")
                    local hp = hum and hum.Health or (st:FindFirstChild("health") and st.health.Value) or 0
                    local red = st:FindFirstChild("damage_reduction") and tonumber(st.damage_reduction.Value) or 0
                    local ck = MT.info and MT.info.cfgById[st.id.Value]
                    -- (flying is an enemy passive: _stats.Flying > 0; hill units and anti-air attacks hit it in full, the rest for half: MT.canAir)
                    local fly = st:FindFirstChild("Flying") and (tonumber(st.Flying.Value) or 0) > 0 or false
                    local sh = st:FindFirstChild("shield") and tonumber(st.shield.Value) or 0
                    table.insert(list, { m = m, pos = m.HumanoidRootPart.Position, prog = prog, lane = lane, hp = hp, red = red, fly = fly, sh = sh, boss = ck and tostring(ck):find("boss") ~= nil or false })
                end
            end
        end
    end
    MT.enemies, MT.mine = list, mine
    -- the first flyers of the match (your own team's modes weigh flyer-hitters only once flyers come: MT.flyMode)
    if not MT.flyerSeen then
        for _, e in ipairs(list) do
            if e.fly then
                MT.flyerSeen = math.max(1, MT.wave())
                if not MT.random then SF.log(1, "MATCH", string.format("flyers from wave %d: units that hit them get more of the yen now", MT.flyerSeen)) end
                break
            end
        end
    end
    -- (what the shields really are, against what the simulator took them for: the first one seen in a match)
    if not MT.shieldSeen then
        for _, e in ipairs(list) do
            if (e.sh or 0) > 0 then
                MT.shieldSeen = true
                local st = e.m._stats
                SF.log(1, "MATCH", string.format("enemy shield seen at wave %d: %s (its most %s), %s, %.3g HP · the simulator has +%s on every enemy", MT.wave(), tostring(e.sh),
                    tostring(st:FindFirstChild("max_shield") and st.max_shield.Value), tostring(st:FindFirstChild("id") and st.id.Value), e.hp, tostring(MT.info and MT.info.shield)))
                break
            end
        end
    end
    local w = MT.wave()
    local mx = 0
    -- seconds the team needs to kill everything alive: enemy HP (after their damage reduction) ÷ live damage
    local hp, dps, raw = 0, 0, 0
    for _, e in ipairs(list) do mx = math.max(mx, e.prog); hp = hp + e.hp / math.max(0.1, 1 - e.red); raw = raw + e.hp end
    MT.hpAliveRaw = raw
    for _, m in ipairs(mine) do
        local id = m._stats.id.Value
        if not UNIT.isFarm(id) and m._stats:FindFirstChild("damage") then
            local ok, v = pcall(MT.liveDps, m, id)
            if ok and v then dps = dps + v end
        end
    end
    MT.hpAlive, MT.teamDps = hp, dps
    MT.clearSec = hp > 0 and (dps > 0 and hp / dps or math.huge) or 0
    MT.waveMax[w] = math.max(MT.waveMax[w] or 0, mx)
    MT.front = mx
    MT.pressure = math.max(MT.waveMax[w] or 0, MT.waveMax[w - 1] or 0)
    MT.depth = MT.coverage(mine, list)
    -- enemies piling up: more alive than 12 s ago and a crowd on the road (tanky waves that don't walk far
    -- but don't die either: waves and farm yen only pay when they end)
    local t = U.now()
    MT.aliveHist = MT.aliveHist or {}
    table.insert(MT.aliveHist, { t = t, n = #list })
    while MT.aliveHist[1] and t - MT.aliveHist[1].t > 12 do table.remove(MT.aliveHist, 1) end
    local old = MT.aliveHist[1]
    MT.piling = #list >= 8 and old and t - old.t >= 8 and #list > old.n + 1 or false
    if #list >= 18 then MT.piling = true end
end
-- --- placement -------------------------------------------------
function MT.setupChecks()
    MT.probe = Instance.new("Part")
    MT.probe.Name = "_aa_probe"; MT.probe.Anchored = true; MT.probe.CanCollide = false
    MT.probe.CanTouch = false; MT.probe.CanQuery = false; MT.probe.Transparency = 1
    MT.probe.Parent = workspace:FindFirstChild("ignore") or workspace
    -- the map's no-place volumes (the game parents them into the world only while you place by hand)
    local src = RS:FindFirstChild("_bounds")
    MT.bounds = Instance.new("Folder")
    MT.bounds.Name = "_aa_bounds"
    if src then
        for _, d in ipairs(src:GetDescendants()) do
            if d:IsA("BasePart") then
                local c = d:Clone()
                for _, ch in ipairs(c:GetChildren()) do ch:Destroy() end
                c.Anchored = true; c.CanCollide = false; c.CanTouch = false; c.CanQuery = true; c.Transparency = 1
                c.CFrame = d.CFrame
                c.Parent = MT.bounds
            end
        end
    end
    MT.bounds.Parent = workspace:FindFirstChild("ignore") or workspace
    MT.overlap = OverlapParams.new()
    MT.overlap.FilterType = Enum.RaycastFilterType.Include
    MT.overlap.FilterDescendantsInstances = { workspace._road, MT.bounds }
end
function MT.spotKey(p) return string.format("%d,%d", math.floor(p.X + 0.5), math.floor(p.Z + 0.5)) end
-- a dungeon room: attackers stack on the road's last stretch (MT.bestSpot). Every room, not only with a Curse of Regen: the last wave's boss regenerates anyway (_stats.Regen; the user's
-- point, and room 12 on Oct 31 had a boss down to 2.36M with no curse on the run, spread-out units, and bailed at 4.7M). Any other mode when SIM.zoneChoice says so (MT.planSpots)
-- (since Nov 1 the spot search picks one of three ways to stand, MT.style. A dungeon room it never got to look at, joined late or with no spots, still stacks)
function MT.killZone() return CFG.killZone ~= false and (MT.style == "box" or (MT.style == nil and MT.kind == "dungeon")) end
function MT.blockedSpot(p)
    local k = MT.spotKey(p)
    if MT.refused[k] then return true end
    local mb = B.blocked[MT.mapKey()]
    return mb and (tonumber(mb[k]) or 0) >= 2
end
-- the same checks the game's placement preview makes: ground (or hill) under the spot, not "_donotplace",
-- the unit's footprint clear of the road, the map's no-place volumes and your other units
function MT.valid(pos, data)
    local hit = C.PC.raycast(pos + Vector3.new(0, 40, 0), Vector3.new(0, -120, 0))
    if not hit then return nil end
    if not C.PC.is_valid_raycast_hit(hit.Instance, data) then return nil end
    local p = hit.Position
    if MT.blockedSpot(p) then return nil end
    local r = (tonumber(data.override_hitbox_radius) or 1.5) + 0.25
    MT.probe.Size = Vector3.new(r * 2, 2.5, r * 2)
    MT.probe.CFrame = CFrame.new(p + Vector3.new(0, 1.35, 0))
    if #workspace:GetPartsInPart(MT.probe, MT.overlap) > 0 then return nil end
    for _, m in ipairs(MT.mine or {}) do
        local hb = m:FindFirstChild("_hitbox")
        local q = hb and hb.Position or m:GetPivot().Position
        local rr = hb and math.max(hb.Size.X, hb.Size.Z) / 2 or 1.5
        if (U.flat(p) - U.flat(q)).Magnitude < r + rr then return nil end
    end
    return p
end
-- candidate spots: both sides of the road at several distances, every 6 studs along it
function MT.buildCandidates()
    MT.cands = {}
    local seen = {}
    for i = 1, #MT.samples, 3 do
        local s = MT.samples[i]
        local nxt = MT.samples[math.min(#MT.samples, i + 1)]
        local dir = U.flat(nxt.pos - s.pos)
        if dir.Magnitude < 0.01 then dir = Vector3.new(1, 0, 0) end
        dir = dir.Unit
        local side = Vector3.new(-dir.Z, 0, dir.X)
        for _, d in ipairs({ 3, 4.5, 6, 8, 10.5, 13.5, 17 }) do
            for _, sgn in ipairs({ 1, -1 }) do
                local pos = s.pos + side * d * sgn
                local k = string.format("%d,%d", math.floor(pos.X / 1.5), math.floor(pos.Z / 1.5))
                if not seen[k] then seen[k] = true; table.insert(MT.cands, pos) end
            end
        end
    end
end
-- defense in depth: how far along the road your attackers reach, and the furthest enemy already past all of
-- them (a leak: nothing can hit it any more before the base, and one leaked enemy takes the base down)
function MT.coverage(mine, enemies)
    local units = {}
    for _, m in ipairs(mine) do
        local st = m._stats
        -- (a summoner reaches as far as its summons do, as in the simulator: by her own small circle an enemy "got past all your units" seconds after Elyssia (Abyssal) opened, at 4% of the road)
        if not UNIT.isFarm(st.id.Value) and st:FindFirstChild("range") then table.insert(units, { p = U.flat(m:GetPivot().Position), r = st.range.Value * (UNIT.SUMMONER[st.id.Value] and UNIT.SUMMONER[st.id.Value].reach or 1), air = MT.canAir(m) }) end
    end
    -- how far down the road your units reach, and how far the ones that can hit flyers reach
    local covEnd, airEnd = 0, 0
    if #units > 0 then
        for _, s in ipairs(MT.samples) do
            if s.prog > airEnd then
                local fp = U.flat(s.pos)
                for _, u in ipairs(units) do
                    if (fp - u.p).Magnitude <= u.r then
                        if s.prog > covEnd then covEnd = s.prog end
                        if u.air then airEnd = s.prog; break end
                    end
                end
            end
        end
    end
    -- lanes (a map with more than one): how far your units reach on each, and how much of each. A lane they barely reach counts for more when the next spot is
    -- picked (MT.laneW, MT.cover), and an enemy past the end of its own lane's cover is a leak even where the other lane is covered further. On Shibuya, Chuuni
    -- and all 3 Priests stood on lane 1 alone, and at wave 42 lane 2 held 48 enemies against lane 1's 7
    local covL, lc = {}, MT.laneCount
    if lc and lc.n >= 2 and #units > 0 then
        local got = {}
        for _, s in ipairs(MT.samples) do
            local fp = U.flat(s.pos)
            for _, u in ipairs(units) do
                if (fp - u.p).Magnitude <= u.r then
                    local l = tostring(s.lane)
                    got[l] = (got[l] or 0) + 1
                    if s.prog > (covL[l] or 0) then covL[l] = s.prog end
                    break
                end
            end
        end
        local frac, top = {}, 0
        for l, n in pairs(lc.by) do frac[l] = (got[l] or 0) / math.max(1, n); top = math.max(top, frac[l]) end
        MT.laneW = {}
        for l, n in pairs(lc.by) do MT.laneW[l] = (lc.avg / math.max(1, n)) * (1 + 1.5 * (top > 0 and (1 - frac[l] / top) or 0)) end
        MT.laneFrac = frac
    else
        MT.laneW, MT.laneFrac = nil, nil
    end
    -- a leak: past everything that can hit it (a flyer past the units that hit it in full: every unit still reaches it, for half)
    local leak, airLeak, leakLane
    if #units > 0 then
        for _, e in ipairs(enemies) do
            local ce = (MT.laneW and e.lane and covL[e.lane]) or covEnd
            if e.hp > 0 and e.prog > ce + 0.02 and e.prog > (leak or 0) then leak, leakLane = e.prog, MT.laneW and e.lane or nil end
            if e.hp > 0 and e.fly and e.prog > airEnd + 0.02 then airLeak = true end
        end
    end
    -- enemies already reach the end of the covered road: the next unit should extend it
    local push = #units > 0 and (MT.pressure or 0) >= covEnd - 0.08
    return { covEnd = covEnd, airEnd = airEnd, leak = leak, leakLane = leakLane, covL = covL, airLeak = airLeak, push = push, units = #units }
end
-- the last line (dealt-team runs lost at waves 12, 21 and 22 to one enemy that got past everything): once 5 units
-- are down, at least 2 damage dealers cover the last 15% of the road before the base, one of them able to hit flyers.
-- Every mode, since v1.5 (one enemy at the base ends any run)
function MT.needLastLine(e)
    if UNIT.isFarm(e.id) or UNIT.allyBuff(e.id) or MT.fieldCount() < 5 then return false end
    local n, air = 0, 0
    for _, m in ipairs(MT.mine or {}) do
        local st = m._stats
        if not UNIT.isFarm(st.id.Value) and st:FindFirstChild("range") then
            local mp, r = U.flat(m:GetPivot().Position), st.range.Value
            for _, s in ipairs(MT.samples) do
                if s.prog >= 0.85 and (U.flat(s.pos) - mp).Magnitude <= r then
                    n = n + 1
                    if MT.canAir(m) then air = air + 1 end
                    break
                end
            end
        end
    end
    -- (the flyer-hitter at the line only where flyers come: MT.flyMode)
    return n < 2 or (air < 1 and MT.flyMode() and MT.cardAir(e.id))
end
-- does this placed unit hit flyers in full (the game's upgrade panel: standing on a hill or an anti-air attack; the game's unit_can_target_air says yes for every unit since the Summer update);
-- asked again after each upgrade, since some units get an anti-air attack from an upgrade (UNIT.airFrom)
MT.airCache = setmetatable({}, { __mode = "k" })
function MT.canAir(m)
    local lvl = m._stats:FindFirstChild("upgrade") and m._stats.upgrade.Value or 0
    local c = MT.airCache[m]
    if not c or c.lvl ~= lvl then
        local v = m:GetAttribute("_on_hill") == true or m:GetAttribute("_anti_air") == true
        c = { lvl = lvl, v = v }
        MT.airCache[m] = c
    end
    return c.v
end
-- the first upgrade level whose attack hits flyers (0: from placement), nil: never — Tango (Flash God) from 8,
-- Tamiki (Tornado) 6, Hubris (The One) 8, Crush (Ace) 9 (the user: "some upgrades give hybrid later")
UNIT._airFrom = {}
function UNIT.airFrom(id)
    local c = UNIT._airFrom[id]
    if c ~= nil then return c or nil end
    local d = C.Units[id]
    -- (a summoner's jellies walk the road and hit flyers, by her page)
    if d and (d.hill_unit or d.hybrid_placement or UNIT.SUMMONER[id]) then UNIT._airFrom[id] = 0; return 0 end
    local rows = UNIT.rows(id)
    if not (rows and rows.max) then return MT.cardAir(id) and 0 or nil end -- (hidden stats not learned yet: not cached)
    local v = false
    for l = 0, rows.max do
        local atk = rows[l] and rows[l].atk
        if atk and C.Attacks[atk] and C.Attacks[atk].targets_flying then v = l; break end
    end
    if v == false and MT.cardAir(id) then v = 0 end
    UNIT._airFrom[id] = v
    return v or nil
end
-- the same for a card in hand (from its data: hill / hybrid, or a primary attack that targets flyers)
function MT.cardAir(id)
    local d = C.Units[id]
    if not d then return false end
    if d.hill_unit or d.hybrid_placement then return true end
    local atk = UNIT.field(id, "primary_attack_no_upgrades") or UNIT.field(id, "primary_attack")
    return atk and C.Attacks[atk] and C.Attacks[atk].targets_flying and true or false
end
-- the share of your damage that can hit flyers
function MT.airShare()
    local tot, air = 0, 0
    for _, m in ipairs(MT.mine or {}) do
        local id = m._stats.id.Value
        if not UNIT.isFarm(id) then
            local ok, v = pcall(MT.liveDps, m, id)
            v = ok and v or 0
            tot = tot + v
            if MT.canAir(m) then air = air + v end
        end
    end
    return tot > 0 and air / tot or 0
end
-- road samples within range of a spot; weighted: each sample counts by how much time enemies really spend
-- there on this map (measured; 0.15 floor so a quiet stretch still counts a little). depth: road past your
-- coverage counts extra once enemies get there, and the road ahead of a leaked enemy counts most
function MT.cover(pos, range, weighted, depth)
    local n = 0
    local fp = U.flat(pos)
    local dens = weighted and B.maps[MT.mapKey()] and B.maps[MT.mapKey()].dens
    local lw = MT.laneW
    for _, s in ipairs(MT.samples) do
        if (U.flat(s.pos) - fp).Magnitude <= range then
            local w = 1
            if dens then w = 0.15 + 0.85 * (tonumber(dens[math.min(SIM.BINS, math.floor(s.prog * SIM.BINS) + 1)]) or 0) end
            -- (a lane your units barely reach counts for more, each lane by its length: MT.coverage)
            if lw then w = w * (lw[tostring(s.lane)] or 1) end
            if depth then
                -- (the road ahead of a leaked enemy: on its own lane)
                if depth.leak and s.prog >= depth.leak - 0.01 and (not depth.leakLane or tostring(s.lane) == depth.leakLane) then w = w + 3
                elseif depth.push and s.prog > depth.covEnd then w = w + 0.6 end
            end
            n = n + w
        end
    end
    return n
end
-- enemies that regenerate (the run's curse, MT.info.regen): what a bleed unit's placement or next upgrade is worth, by the healing it
-- stops (ECON.bleedGain), spread over the upgrades it still needs to bleed. Half once something on the field bleeds already
function MT.bleedGain(id, lvl, place)
    local regen = MT.info and tonumber(MT.info.regen) or 0
    if regen <= 0 then return 0 end
    local at = UNIT.bleeds(id)
    if not at then return 0 end
    local already = false
    for _, m in ipairs(MT.mine or {}) do
        local st = m:FindFirstChild("_stats")
        local bid = st and st:FindFirstChild("id") and st.id.Value
        local up = st and st:FindFirstChild("upgrade") and tonumber(st.upgrade.Value) or 0
        if bid and (UNIT.bleeds(bid) or 99) <= up then already = true; break end
    end
    return ECON.bleedShare(ECON.bleedGain(regen, MT.hpAlive or 0, MT.coming, already), at, lvl, place)
end
-- synergy: buffers on the field (pos, range, what they buff) and your units' damage by position
function MT.fieldBuffers()
    local list = {}
    for _, m in ipairs(MT.mine or {}) do
        local b = UNIT.allyBuff(m._stats.id.Value)
        if b then table.insert(list, { pos = m:GetPivot().Position, range = m._stats.range.Value, b = b }) end
    end
    return list
end
-- the attackers a buffer's next copy would still help: fewer copies in reach than keep the buff up on them. It goes by reach, so a force out of reach of the others counts by itself and gets its own
-- copies however many stand elsewhere. (Not other buffers: Windsongs counted each other, one more always looked useful)
function MT.buffShort(b)
    local same = {}
    for _, bf in ipairs(MT.fieldBuffers()) do if bf.b.attack == b.attack then table.insert(same, bf) end end
    local need = UNIT.buffCopies(b)
    local list = {}
    for _, m in ipairs(MT.mine or {}) do
        local id = m._stats.id.Value
        local _, base = UNIT.types(id)
        if not UNIT.isFarm(id) and not UNIT.allyBuff(id) and b.types[base] then
            local mp = U.flat(m:GetPivot().Position)
            local n = 0
            for _, bf in ipairs(same) do if (U.flat(bf.pos) - mp).Magnitude <= bf.range then n = n + 1 end end
            if n < need then
                local ok, v = pcall(MT.liveDps, m, id)
                table.insert(list, { pos = mp, base = base, n = n, dps = math.max(1, ok and tonumber(v) or 1) })
            end
        end
    end
    return list
end
-- the simulator's job on a map (the user's call: "the whole point of the sim was to find the best spots"): which spot for
-- each attacker's first copy. Each gets a shortlist: the spots that reach the most road at its full range with the run's
-- bonuses, and the ones the old formula likes (so the search can only do better by the sim's own count). The hardest
-- enemies the old spots still survive are found first, because a difference only shows near the cliff; then one unit at a time
-- tries its shortlist, others fixed, and keeps what gets furthest. Real runs correct it: a spot that lost on this map
-- counts as 1.5 waves worse, so a lost room tries something else unless the sim is sure
function MT.spotRec(id, p, make)
    local mk = MT.mapKey()
    B.maps[mk] = B.maps[mk] or {}
    local lay = B.maps[mk].lay
    if not lay then
        if not make then return nil end
        lay = {}
        B.maps[mk].lay = lay
    end
    local byId = lay[id]
    if not byId then
        if not make then return nil end
        byId = {}
        lay[id] = byId
    end
    local k = MT.spotKey(p)
    if not byId[k] and make then byId[k] = { runs = 0, wins = 0 } end
    return byId[k]
end
-- a dungeon room's last life: with what's really played on this map the simulator has the last word, before a wave has started. If this
-- team falls here, back to the lobby: leaving a room has never cost a life
function MT.lastLife(hard, final)
    if MT.kind ~= "dungeon" then return end
    local okL, lives = pcall(DG.lives, DG.data())
    if not (okL and lives <= 1) then return end
    local wins = hard > 1 or final.won
    DG.note(string.format("last life, on this map: the simulator says your team %s", wins and "wins" or ("falls at wave " .. final.wave)))
    if not wins and DG.playLast() then
        DG.note("last life: played all the same, the user's call")
    elseif not wins then
        MT.noBuy = true
        MODE.rec("dg").restUntil = os.time() + 3600
        B.pending = nil
        DG.note("last life kept: back to the lobby before a wave starts. Looks again in an hour")
        SF.saveNow()
        task.wait(1)
        SF.request("lobby", "teleport_back_to_lobby")
    end
end
-- the three ways to stand (the user's call, Nov 1: "have three different placements that it can choose smart"). Each gets its own search for the best spots on this map, then has to pass at its own
-- strength, on that layout, in 2 of 3 close tries (one run swings on the order of its buys):
-- fast: at the road's start, so waves end early. Only if it beats enemies ×1.5; among layouts that do, the quickest (SIM.objective counts the time)
-- balanced: spread over the road. If it beats more than ×1 (tested at ×1.1: "×1 or lower" is the kill box's)
-- box: on the road's last stretch, for the rest, with the best spots there
-- Real runs go first, since the sim reads spread-out units too low and stacked ones too high: a way that lost here with this team isn't tried again for a week, so a lost try steps down to a safer way, and a
-- way that won here isn't given up for a lower reading. A dungeon room goes by its own lost tries, and its last life is always a kill box (Oct 31: 29 rooms won and none lost that way, 85 won and 23 lost spread out)
MT.STYLE_FAST, MT.STYLE_BALANCED, MT.FAST_ROAD, MT.PLAN_TOTAL = 1.5, 1.1, 0.35, 14
MT.STYLE_WORDS = { fast = "fast clear, at the road's start", balanced = "balanced, spread over the road", box = "kill box, on the road's last stretch" }
function MT.styleRec(make)
    local store, k
    if MT.kind == "dungeon" then
        B.dg.styles = type(B.dg.styles) == "table" and B.dg.styles or {}
        store, k = B.dg.styles, tostring(B.dg.room and B.dg.room.seed)
    else
        store, k = B.zoneRec, SIM.zoneKey(MT.info)
    end
    if not store[k] and make then
        store[k] = { at = os.time() }
        -- (only the newest dungeon rooms are kept)
        if store ~= B.zoneRec and U.count(store) > 40 then
            local old, oldAt
            for key, v in pairs(store) do if not oldAt or (tonumber(v.at) or 0) < oldAt then old, oldAt = key, tonumber(v.at) or 0 end end
            store[old] = nil
        end
    end
    return store[k]
end
function MT.styleRecord(won)
    if not MT.style or not MT.info then return end
    local rec = MT.styleRec(true)
    rec.style, rec.zone, rec.won, rec.at = MT.style, MT.style == "box", won and true or false, os.time()
    rec.lost = type(rec.lost) == "table" and rec.lost or {}
    rec.lost[MT.style] = (not won) and { at = os.time(), sig = MT.styleSig } or nil
    -- (how far each way got here: Keep Playing Daily goes by it, MT.planSpots)
    rec.far = type(rec.far) == "table" and rec.far or {}
    rec.far[MT.style] = math.max(tonumber(rec.far[MT.style]) or 0, MT.wave())
end
function MT.planSpots()
    local t0 = U.now()
    local info = MT.info
    local scale = tonumber(info.rangeScale) or 1
    local units, attackers = {}, {}
    for _, e in ipairs(MT.team or {}) do
        table.insert(units, e.u)
        if not UNIT.isFarm(e.id) and not UNIT.allyBuff(e.id) and e.uuid ~= MT.trainee and UNIT.rows(e.id) then
            local okS, sc = pcall(UNIT.score, e.u, MT.mod)
            table.insert(attackers, { e = e, id = e.id, sc = okS and sc or 0 })
        end
    end
    if #attackers == 0 then return end
    table.sort(attackers, function(a, b) return a.sc > b.sc end)
    -- the free spots, once per kind of ground (hill units stand elsewhere) and body size (Sora's hitbox of 4 fits almost nowhere:
    -- shared, its short list left Icy Dragon and Mochi with one spot, the one Bulby takes)
    local free = {}
    local function spotsFor(data)
        local kind = (data.hill_unit and "hill" or "ground") .. ":" .. tostring(data.override_hitbox_radius or "")
        if free[kind] then return free[kind] end
        local l = {}
        for i, pos in ipairs(MT.cands) do
            local p = MT.valid(pos, data)
            if p then table.insert(l, p) end
            if i % 40 == 0 then task.wait() end
        end
        free[kind] = l
        return l
    end
    -- the road a spot reaches, and how much of its start (the earlier the better) and of its last stretch (the later the better)
    local function reach(p, r)
        local n, start, finish, r2 = 0, 0, 0, r * r
        for _, s in ipairs(MT.samples) do
            local dx, dz = s.pos.X - p.X, s.pos.Z - p.Z
            if dx * dx + dz * dz <= r2 then
                n = n + 1
                if s.prog <= MT.FAST_ROAD then start = start + 1.5 - s.prog end
                if s.prog >= 0.6 then finish = finish + s.prog - 0.5 end
            end
        end
        return n, start, finish
    end
    local function take(list, n, into)
        for _, c in ipairs(list) do
            if n <= 0 then break end
            local far = true
            for _, o in ipairs(into) do if (U.flat(o) - U.flat(c.p)).Magnitude < 6 then far = false; break end end
            if far then table.insert(into, c.p); n = n - 1 end
        end
    end
    -- each attacker's shortlists, one per way to stand
    for _, a in ipairs(attackers) do
        local rows = UNIT.rows(a.id)
        local rFull = UNIT.range(a.e.u, rows.max) * scale
        local rEarly = UNIT.range(a.e.u, math.min(3, rows.max)) * scale
        local byFull, byOld, byStart, byEnd = {}, {}, {}, {}
        for i, p in ipairs(spotsFor(a.e.data)) do
            local nF, sF, fF = reach(p, rFull)
            local nE, sE = reach(p, rEarly)
            table.insert(byFull, { p = p, v = nF + 0.25 * nE })
            table.insert(byOld, { p = p, v = MT.cover(p, rEarly, true) })
            table.insert(byStart, { p = p, v = sF + 0.5 * sE })
            table.insert(byEnd, { p = p, v = fF })
            if i % 60 == 0 then task.wait() end
        end
        for _, l in ipairs({ byFull, byOld, byStart, byEnd }) do table.sort(l, function(x, y) return x.v > y.v end) end
        a.cands = {}
        take(byOld, 1, a.cands)
        a.old = a.cands[1]
        take(byFull, 4, a.cands)
        take(byOld, 2, a.cands)
        -- (a style's list holds only spots that really reach its stretch of road, 70% of the best spot's reach at least. A hill unit has few spots near the road's end, and its list of five
        -- was filled with mid-road ones: on the Summer Hunt, Nov 2, two of Iron Sentinel's five reached 30-64% of the road and nothing of the kill box, and the search put it on one,
        -- 100 studs from the other three. The user: "fix this". A list where nothing reaches keeps the old five)
        local function near(l)
            local top, out = l[1] and l[1].v or 0, {}
            for _, c in ipairs(l) do
                if top <= 0 or c.v < top * 0.7 then break end
                table.insert(out, c)
            end
            return #out > 0 and out or l
        end
        a.fast, a.box = {}, {}
        take(near(byStart), 5, a.fast)
        take(near(byEnd), 5, a.box)
    end
    local team = SIM.teamFrom(units, info.map)
    local cache, runs = {}, 0
    local function run(lay, hp)
        runs = runs + 1
        local r = SIM.run(info, team, { hpMul = hp, layout = lay })
        task.wait()
        return r
    end
    local function real(lay)
        local v = 0
        for id, p in pairs(lay.spots) do
            local r = MT.spotRec(id, p)
            if r then v = v + (tonumber(r.wins) or 0) * 200 - ((tonumber(r.runs) or 0) - (tonumber(r.wins) or 0)) * 1500 end
        end
        return v
    end
    local function score(lay, r) return SIM.objective(r) * 100 + real(lay) end
    local function clash(lay, id, c)
        for other, o in pairs(lay.spots) do
            if other ~= id and (U.flat(o) - U.flat(c)).Magnitude < 4.5 then return true end
        end
        return false
    end
    -- a way's first layout: each unit on its shortlist's best free spot (two units can't share one)
    local function layoutFor(style, list)
        local lay = { samples = MT.samples, cache = cache, spots = {}, style = style, list = list }
        for _, a in ipairs(attackers) do
            local pick
            for _, c in ipairs(a[list]) do
                if not clash(lay, a.id, c) then pick = c; break end
            end
            lay.spots[a.id] = pick or a[list][1] or a.old
        end
        return lay
    end
    -- how tough the enemies get before a layout loses (a difference only shows near the cliff)
    local function climb(lay)
        local hard, last = 4, nil
        for _, hp in ipairs({ 1, 1.3, 1.7, 2.2, 3, 4 }) do
            last = run(lay, hp)
            if not last.won then hard = hp; break end
        end
        return hard, last
    end
    -- one unit at a time, strongest first, twice over, keeping what gets furthest at that strength
    local function search(lay, hp, seconds, maxRuns, first)
        local t1, n0 = U.now(), runs
        local best = score(lay, first or run(lay, hp))
        for _ = 1, 2 do
            local changed = false
            for _, a in ipairs(attackers) do
                local keep = lay.spots[a.id]
                local bestP = keep
                for _, c in ipairs(a[lay.list]) do
                    if U.now() - t1 > seconds or runs - n0 >= maxRuns or U.now() - t0 > MT.PLAN_TOTAL then break end
                    if c ~= keep and not clash(lay, a.id, c) then
                        lay.spots[a.id] = c
                        local v = score(lay, run(lay, hp))
                        if v > best + 1 then best, bestP = v, c; changed = true end
                    end
                end
                lay.spots[a.id] = bestP
            end
            if not changed then break end
        end
    end
    local function passes(lay, hp)
        local w = 0
        for _, k in ipairs({ 0.92, 1, 1.08 }) do if run(lay, hp * k).won then w = w + 1 end end
        return w
    end
    -- what real runs say about this map or room
    local rec = MT.styleRec()
    local sig = SIM.sig(units)
    MT.styleSig = sig
    local mode = MT.kind ~= "dungeon" and B.modes[info.key] or nil
    local streak = mode and tonumber(mode.streak) or 0
    -- (Keep Playing Daily loses until it wins, so a lost way isn't ruled out there: the way that got furthest plays. On Nov 1 spread out reached wave 30 of 30 and the kill box 26, then it flipped back to the kill box because both had lost)
    local looping = CFG.dailyLoop and MT.kind == "daily"
    local farSpread = looping and rec and type(rec.far) == "table" and (tonumber(rec.far.balanced) or 0) > 0 and (tonumber(rec.far.balanced) or 0) >= (tonumber(rec.far.box) or 0) and tonumber(rec.far.balanced) or nil
    local function lostHere(style)
        if looping then return false end
        local l = rec and type(rec.lost) == "table" and rec.lost[style]
        if l then return l.sig == sig and os.time() - (tonumber(l.at) or 0) < 7 * 86400 end
        -- (a record from before the three ways, and a map lost before there were records)
        if rec and not rec.style and rec.won == false then return style == (rec.zone and "box" or "balanced") end
        return not rec and streak > 0 and style == "balanced"
    end
    local function wonHere(style)
        if rec and rec.won then return (rec.style or (rec.zone and "box" or "balanced")) == style end
        -- (a mode whose map stays the same and whose last run won, from before these records. The challenges' maps change)
        return not rec and style == "balanced" and mode ~= nil and (tonumber(mode.wins) or 0) > 0 and streak == 0 and info.key ~= "ch" and info.key ~= "dc"
    end
    local boxOk = CFG.killZone ~= false
    local okL, lives = pcall(DG.lives, DG.data())
    local lastLife = boxOk and MT.kind == "dungeon" and okL and lives <= 1
    local forceBox = looping and CFG.dailyBox and boxOk
    local chosen, why, balanced
    -- 1. fast, if it holds at ×1.5
    -- (a mode with no real run yet: its ×1.5 is only the sim's word. Shibuya Act 1's first run, Nov 1: the sim won up to ×3 and the real run fell at wave 10. And a first clear only has to win once; speed pays on maps played again)
    local fastOff = (forceBox and "you asked for the kill box here") or (lastLife and "it's this room's last life") or (MT.trainee and "a unit is training here and needs enemies left to hit")
        or (lostHere("fast") and "it lost here") or (lostHere("balanced") and "spread-out units already lost here")
        or ((tonumber(info.cal and info.cal.n) or 0) == 0 and "no real run here yet to check the simulator against") or nil
    if not fastOff then
        -- (the quick look: if the team can't win this strength with every unit on its best stretch of road, there's nothing to search for)
        runs = runs + 1
        if not SIM.run(info, team, { hpMul = MT.STYLE_FAST * 0.92, noZone = true }).won then fastOff = string.format("your team doesn't beat enemies ×%.1f", MT.STYLE_FAST) end
    end
    if fastOff then
        SF.log(1, "SPOTS", "no fast clear: " .. fastOff)
    else
        local t1, n0 = U.now(), runs
        local lay = layoutFor("fast", "fast")
        search(lay, MT.STYLE_FAST, 4, 40)
        local w = passes(lay, MT.STYLE_FAST)
        SF.log(1, "SPOTS", string.format("fast clear: tried %d layouts in %.1f s, the best wins %d of 3 tries against enemies ×%.1f", runs - n0, U.now() - t1, w, MT.STYLE_FAST))
        if w >= 2 then chosen, why = lay, string.format("your team beats enemies ×%.1f from there", MT.STYLE_FAST) end
    end
    -- 2. balanced, if it holds above ×1
    if not chosen and not lastLife and not forceBox and (boxOk == false or not lostHere("balanced")) then
        local t1, n0 = U.now(), runs
        local lay = layoutFor("balanced", "cands")
        local hard, oldLast = climb(lay)
        -- the shortlists so far assume every unit gets maxed, which sent Mochi (level 3, range 41) far down the road: its spot
        -- reached 70% of the road at a range it never had, and a boss only reached it two minutes in. Against a regen boss damage
        -- must land together from the start, so each unit also gets the spots that reach the most of the road's first half at the
        -- range it really reaches in this simulated run. They go first, so the time limit can't cut them. Not the strongest
        -- unit: it does get maxed, and whole-road reach is what killed the boss (given these spots, it left the one that did)
        for k, a in ipairs(attackers) do if k > 1 then
            local rows = UNIT.rows(a.id)
            local lvl = math.min(rows.max, math.max(tonumber(oldLast.levels and oldLast.levels[a.id]) or 0, 1))
            local r = UNIT.range(a.e.u, lvl) * scale
            local r2, byFront = r * r, {}
            for i, p in ipairs(spotsFor(a.e.data)) do
                local n = 0
                for _, s in ipairs(MT.samples) do
                    if s.prog <= 0.5 then
                        local dx, dz = s.pos.X - p.X, s.pos.Z - p.Z
                        if dx * dx + dz * dz <= r2 then n = n + 1 end
                    end
                end
                table.insert(byFront, { p = p, v = n })
                if i % 60 == 0 then task.wait() end
            end
            table.sort(byFront, function(x, y) return x.v > y.v end)
            local rest = a.cands
            a.cands = {}
            take(byFront, 3, a.cands)
            for _, c in ipairs(rest) do table.insert(a.cands, c) end
        end end
        search(lay, hard, 5, 50, oldLast)
        local w = passes(lay, MT.STYLE_BALANCED)
        SF.log(1, "SPOTS", string.format("balanced: tried %d layouts in %.1f s, the best wins %d of 3 tries against enemies ×%.1f", runs - n0, U.now() - t1, w, MT.STYLE_BALANCED))
        balanced = lay
        if w >= 2 then chosen, why = lay, string.format("your team beats enemies ×%.1f spread out%s", MT.STYLE_BALANCED, fastOff and "" or string.format(", not ×%.1f from the road's start", MT.STYLE_FAST))
        elseif wonHere("balanced") then chosen, why = lay, "it won here last time, and the simulator reads spread-out units low"
        elseif not boxOk then chosen, why = lay, "the kill box is switched off"
        elseif farSpread then chosen, why = lay, string.format("it got furthest here, to wave %d", farSpread)
        elseif lostHere("box") then chosen, why = lay, "the kill box lost here" end
    end
    -- 3. the kill box, for ×1 or lower, with the best spots on the road's last stretch
    if not chosen then
        local t1, n0 = U.now(), runs
        local lay = layoutFor("box", "box")
        local hard, last = climb(lay)
        search(lay, hard, 4, 40, last)
        local w = passes(lay, 1)
        SF.log(1, "SPOTS", string.format("kill box: tried %d layouts in %.1f s, the best wins %d of 3 tries against normal enemies", runs - n0, U.now() - t1, w))
        -- (the sim reads a kill box high, so one that loses every try at normal strength where spread-out units win really is the worse way)
        if w == 0 and balanced and passes(balanced, 1) >= 2 then
            chosen, why = balanced, "the kill box loses at normal strength, spread-out units win"
        else
            chosen, why = lay, forceBox and "you asked for it: a control unit works best in one" or lastLife and "it's this room's last life" or (not balanced and "spread-out units lost here") or string.format("your team doesn't beat enemies ×%.1f spread out", MT.STYLE_BALANCED)
        end
    end
    MT.style = chosen.style
    MT.styleWhy = why
    info.zone = chosen.style == "box"
    -- what's used in the match: the chosen spot, then the rest of the shortlist if the game refuses it
    MT.layout = {}
    local words = {}
    for _, a in ipairs(attackers) do
        local spot = chosen.spots[a.id]
        local list = { spot }
        for _, c in ipairs(a[chosen.list]) do if c ~= spot then table.insert(list, c) end end
        MT.layout[a.id] = list
        if spot then
            table.insert(words, string.format("%s %s (%d%% of the road at full range)", UNIT.name(a.id), MT.spotKey(spot),
                math.floor((reach(spot, UNIT.range(a.e.u, UNIT.rows(a.id).max) * scale)) / math.max(1, #MT.samples) * 100 + 0.5)))
        end
    end
    MT.layoutSim = chosen
    local hard, final = climb(chosen)
    SF.log(1, "SPOTS", string.format("placement: %s, because %s · %s · against enemies ×%.1f the simulator %s at wave %d · %d runs in %.1f s",
        MT.STYLE_WORDS[chosen.style], why, table.concat(words, " · "), hard, final.won and "wins" or "falls", final.wave, runs, U.now() - t0))
    SF.status("Placement", MT.STYLE_WORDS[chosen.style])
    MT.lastLife(hard, final)
end
-- a run's result for the spots it really used (first copies): what the search goes by next time
function MT.spotResult(won)
    for id, p in pairs(MT.layoutUsed or {}) do
        local r = MT.spotRec(id, p, true)
        r.runs, r.wins = (tonumber(r.runs) or 0) + 1, (tonumber(r.wins) or 0) + (won and 1 or 0)
    end
    -- (how this map or room was played, for the next time: MT.planSpots)
    if not MT.infinite then MT.styleRecord(won) end
end
-- a kill box's control units: along the box, not stacked at its end with everyone else. Stacked, all 4 Frost Navy (Blue Pigeon) reached the same 90-98% of the road, enemies died before they got there, and they had dealt nothing by wave 18. The user's eye, Nov 2: "it needs one in front and
-- the back and middle". The box is the road your other attackers reach; each copy goes on its own part of it: the front where enemies come in, the back, the middle, then ahead of the front. nth: which copy, for a test. SIM.run plays the same
MT.CONTROL_WORDS = { "at the front of", "at the back of", "in the middle of", "ahead of" }
-- (not a switch ability like Snow Reaper (Final)'s Gale: its copies take turns only where their circles overlap, and what it freezes counts only under your damage, so it stacks
-- with the damage instead, MT.holdSpot. Spread front, middle and back, her three copies froze in three places on the Summer Hunt, Nov 2, one of them where nothing else hit)
function MT.controlSpot(e, nth)
    if not MT.killZone() then return nil end
    local holds = SIM.holds
    if not holds(e.id) or UNIT.toggleOf(e.id) then return nil end
    local lo, hi, n, mine = 1, 0, 0, {}
    for _, m in ipairs(MT.mine or {}) do
        local st = m._stats
        local id = st.id.Value
        if st:FindFirstChild("range") and not UNIT.isFarm(id) and not UNIT.allyBuff(id) then
            local mp, r = U.flat(m:GetPivot().Position), st.range.Value
            if holds(id) and not UNIT.toggleOf(id) then
                n = n + 1
                table.insert(mine, { p = mp, r = r })
            else
                for _, s in ipairs(MT.samples) do
                    if (U.flat(s.pos) - mp).Magnitude <= r then lo, hi = math.min(lo, s.prog), math.max(hi, s.prog) end
                end
            end
        end
    end
    if hi <= lo then lo, hi = 0.75, 0.98 end
    local slot = (nth or n) + 1
    local target = ({ lo, hi, (lo + hi) / 2, lo - (hi - lo) / 2 })[slot]
    if not target then return nil end
    local r = UNIT.range(e.u, 0) * ((MT.info and tonumber(MT.info.rangeScale)) or 1)
    -- the spots by how much of that part of the road they reach, less what another control unit already does; the game's own check only for the ones that could win
    local rows = {}
    for i, pos in ipairs(MT.cands) do
        local fp, sc, cov = U.flat(pos), 0, 0
        for _, s in ipairs(MT.samples) do
            if (U.flat(s.pos) - fp).Magnitude <= r then
                cov = cov + 1
                if math.abs(s.prog - target) <= 0.05 then
                    sc = sc + 1
                    local sp = U.flat(s.pos)
                    for _, o in ipairs(mine) do if (sp - o.p).Magnitude <= o.r then sc = sc - 0.5; break end end
                end
            end
        end
        if sc > 0 then table.insert(rows, { pos = pos, sc = sc, cov = cov }) end
        if i % 60 == 0 then task.wait() end
    end
    table.sort(rows, function(a, b) return a.sc > b.sc end)
    for i, x in ipairs(rows) do
        local p = MT.valid(x.pos, e.data)
        if p then
            SF.log(1, "PLACE", string.format("%s goes %s the kill box (%d%% of the road)", UNIT.name(e.id), MT.CONTROL_WORDS[slot], math.floor(target * 100 + 0.5)))
            return p, x.cov, target
        end
        if i % 20 == 0 then task.wait() end
    end
    return nil
end
-- a unit that holds enemies (SIM.holds: a freeze, stun or slow at any upgrade, or a switch ability like Snow Reaper (Final)'s Gale) holds what's in its own range, so it stands where
-- your other attackers' damage is: the stretch of road the most of it reaches, and what it holds there stays under all of them. Gale copies stack there and take turns (MT.gale).
-- The user's point, Nov 2: "why is Snow Reaper not freezing enemies within range of all dps units" — her copies had gone where the road was longest or a leak was, 60-110 studs from
-- Chuuni, Iron Sentinel and Priest. A kill box spreads them along it instead (MT.controlSpot). Not before an attacker is down, nor for a leak
function MT.holdSpot(e)
    local holds, from = SIM.holds(e.id)
    if not holds then return nil end
    local others, total = {}, 0
    for _, m in ipairs(MT.mine or {}) do
        local st = m._stats
        local id = st.id.Value
        if st:FindFirstChild("range") and not UNIT.isFarm(id) and not UNIT.allyBuff(id) and id ~= e.id then
            local okD, d = pcall(MT.liveDps, m, id)
            d = okD and tonumber(d) or 0
            if d > 0 then table.insert(others, { p = U.flat(m:GetPivot().Position), r = st.range.Value, d = d }); total = total + d end
        end
    end
    if #others == 0 or total <= 0 then return nil end
    -- the share of your attackers' damage that reaches each road sample
    local dmg = {}
    for i, s in ipairs(MT.samples) do
        local sp, v = U.flat(s.pos), 0
        for _, o in ipairs(others) do if (sp - o.p).Magnitude <= o.r then v = v + o.d end end
        dmg[i] = v / total
    end
    -- (its range once its hold has come: the upgrade it starts at, at most 3)
    local r = UNIT.range(e.u, math.min(tonumber(from) or 0, 3, UNIT.rows(e.id).max)) * ((MT.info and tonumber(MT.info.rangeScale)) or 1)
    local best, bestSc, bestN
    for i, pos in ipairs(MT.cands) do
        local fp, sc, n = U.flat(pos), 0, 0
        for k, s in ipairs(MT.samples) do
            if (U.flat(s.pos) - fp).Magnitude <= r then sc = sc + dmg[k]; n = n + 1 end
        end
        -- (the game's own check only for the spots that could win)
        if sc > 0 and (not bestSc or sc > bestSc) then
            local p = MT.valid(pos, e.data)
            if p then best, bestSc, bestN = p, sc, n end
        end
        if i % 40 == 0 then task.wait() end
    end
    if not best then return nil end
    MT.holdSaid = MT.holdSaid or {}
    if not MT.holdSaid[e.id] then
        MT.holdSaid[e.id] = true
        SF.log(1, "PLACE", string.format("%s holds enemies, so it stands where your attackers' damage is: what it holds stays under all of them", UNIT.name(e.id)))
    end
    return best, bestN or 0
end
function MT.bestSpot(e, wantLow, train)
    -- (a boss left alone on the last wave: where it is now, MT.bossStep)
    if MT.focus and not wantLow and not train and not UNIT.allyBuff(e.id) then
        local fp, fn = MT.focusSpot(e)
        if fp then return fp, fn end
    end
    if not wantLow and not train and not (MT.depth and MT.depth.leak) then
        local okC, cp, cn = pcall(MT.controlSpot, e)
        if okC and cp then return cp, cn end
        local okG, gp, gn = pcall(MT.holdSpot, e)
        if okG and gp then return gp, gn end
    end
    -- a unit's first copy: the spot the simulator chose (to answer a leak only if that spot is in the enemy's way too: it can still reach the road ahead of it. A leak moved Chuuni (Delusion) off her planned spot in 5 of 22 runs on Nov 1, she did 0% in all 5, against 12-56%
    -- on her spot with Elyssia (Abyssal) on the team, and the simulator had scored a layout that wasn't being played. Found in a recorded room 19, where enemies then reached 61% of the road against the 12% it read)
    local leakNow = MT.depth and MT.depth.leak
    if MT.layout and MT.layout[e.id] and not wantLow and not train then
        local placed = false
        for _, m in ipairs(MT.mine or {}) do
            local u = m._stats:FindFirstChild("uuid")
            if u and u.Value == e.uuid then placed = true; break end
        end
        if not placed then
            for _, sp in ipairs(MT.layout[e.id]) do
                local q = MT.valid(sp, e.data)
                if q and leakNow then
                    local ahead, fq, r = false, U.flat(q), UNIT.range(e.u, 0) * ((MT.info and tonumber(MT.info.rangeScale)) or 1)
                    for _, s in ipairs(MT.samples) do
                        if s.prog >= leakNow + 0.02 and (U.flat(s.pos) - fq).Magnitude <= r then ahead = true; break end
                    end
                    if not ahead then q = nil end
                end
                if q then
                    MT.layoutUsed = MT.layoutUsed or {}
                    MT.layoutUsed[e.id] = q
                    return q, MT.cover(q, UNIT.range(e.u, math.min(3, UNIT.rows(e.id).max)) * ((MT.info and tonumber(MT.info.rangeScale)) or 1))
                end
            end
        end
    end
    local data = e.data
    local depth = MT.depth
    -- takedown training: a takedown needs a hit before the enemy dies, so the trainee stands where enemies come
    -- before your other attackers reach them (their earliest road, + a little overlap)
    local entry
    if train then
        entry = 1
        for _, m in ipairs(MT.mine or {}) do
            local st = m._stats
            if not UNIT.isFarm(st.id.Value) and not (st:FindFirstChild("uuid") and st.uuid.Value == e.uuid) then
                local mp, r = U.flat(m:GetPivot().Position), st.range.Value
                for _, s in ipairs(MT.samples) do if s.prog < entry and (U.flat(s.pos) - mp).Magnitude <= r then entry = s.prog end end
            end
        end
    end
    -- against a leak the unit's range right now counts (it has to hit that enemy before it gets upgraded). The mode's
    -- range bonus counts too (a dungeon's bows: ×1.70), and for your own attackers so does the range they'll have
    -- once maxed, which leads the score. Iron Sentinel chose its spot by range 27.7 when its real range was 70.7 — 89 of
    -- 124 road samples; the spot the user pointed out reaches all 124, so a boss never walks out of it
    local rangeScale = (MT.info and tonumber(MT.info.rangeScale)) or 1
    local range = UNIT.range(e.u, (depth and depth.leak) and 0 or math.min(3, UNIT.rows(e.id).max)) * rangeScale
    -- (dungeon rooms and kill boxes only so far: a room's yen maxes the carry and its bows stretch the range; other modes keep the spots
    -- that have been winning there until a run shows otherwise)
    local rangeFull = (MT.kind == "dungeon" or MT.style == "box" or MT.style == "fast") and not wantLow and not (depth and depth.leak) and not UNIT.isFarm(e.id) and UNIT.range(e.u, UNIT.rows(e.id).max) * rangeScale or nil
    local myBuff = UNIT.allyBuff(e.id)
    -- a boss that regenerates: damage only counts while it lands together (the user's point: "it does no good on a regen boss if they
    -- aren't all hitting it at the same time"). So every attacker stands where its full range covers the road's last stretch, on top of
    -- the others' ranges: one kill zone the boss walks through under all of them, instead of a line it walks past one unit at a time
    if MT.killZone() and not wantLow and not train and not myBuff and not (depth and depth.leak) and not UNIT.isFarm(e.id) then
        local rangeZ = rangeFull or range
        local others = {}
        for _, m in ipairs(MT.mine or {}) do
            local st = m._stats
            local id = st.id.Value
            if not UNIT.isFarm(id) and not UNIT.allyBuff(id) and st:FindFirstChild("range") then table.insert(others, { p = U.flat(m:GetPivot().Position), r = st.range.Value }) end
        end
        -- (how many placed attackers already reach each road sample, once)
        local shared = {}
        for i, s in ipairs(MT.samples) do
            local n = 0
            local sp = U.flat(s.pos)
            for _, o in ipairs(others) do if (sp - o.p).Magnitude <= o.r then n = n + 1 end end
            shared[i] = n
        end
        local best, bestSc, bestN
        local checked = 0
        for _, pos in ipairs(MT.cands) do
            local p = MT.valid(pos, data)
            checked = checked + 1
            if checked % 40 == 0 then task.wait() end
            if p then
                local fp, sc, n = U.flat(p), 0, 0
                for i, s in ipairs(MT.samples) do
                    if (U.flat(s.pos) - fp).Magnitude <= rangeZ then
                        n = n + 1
                        -- (the last 40% of the road counts, the later the better, and more where others already reach)
                        if s.prog >= 0.6 then sc = sc + (s.prog - 0.5) * (1 + shared[i]) end
                    end
                end
                if not bestSc or sc > bestSc then best, bestSc, bestN = p, sc, n end
            end
        end
        if best and bestSc > 0 then
            if not MT.zoneSaid then MT.zoneSaid = true; SF.log(1, "PLACE", "attackers stack on the road's last stretch, so what walks in takes everyone's damage at once") end
            return best, bestN or 0
        end
    end
    -- a fast clear: later copies at the road's start too, the earlier the better, so waves end early (MT.planSpots only picks it for a team that beats enemies ×1.5 from there)
    if MT.style == "fast" and not wantLow and not train and not myBuff and not (depth and depth.leak) and not UNIT.isFarm(e.id) then
        local rangeF = rangeFull or range
        local best, bestSc, bestN
        local checked = 0
        for _, pos in ipairs(MT.cands) do
            local p = MT.valid(pos, data)
            checked = checked + 1
            if checked % 40 == 0 then task.wait() end
            if p then
                local fp, sc, n = U.flat(p), 0, 0
                for _, s in ipairs(MT.samples) do
                    if (U.flat(s.pos) - fp).Magnitude <= rangeF then
                        n = n + 1
                        if s.prog <= MT.FAST_ROAD then sc = sc + 1.5 - s.prog end
                    end
                end
                if not bestSc or sc > bestSc then best, bestSc, bestN = p, sc, n end
            end
        end
        if best and bestSc > 0 then return best, bestN or 0 end
    end
    -- Infinite training: the road's first stretch (TRAIN.ZONE) is left to the trainee, so enemies walk past it before
    -- your other attackers can reach them (their range at full upgrades counts: Iron Sentinel's 37 studs covered the
    -- spawn and Chuuni never got a hit). Not while enemies get far (then every unit goes where it covers most)
    local zone = MT.infinite and MT.trainee and not train and e.uuid ~= MT.trainee and not UNIT.isFarm(e.id) and not myBuff and not wantLow
        and not (depth and depth.leak) and (MT.pressure or 0) < CFG.dangerReach and TRAIN.ZONE or nil
    local rangeMax = zone and UNIT.range(e.u, UNIT.rows(e.id).max) or nil
    local _, myBase = UNIT.types(e.id)
    local buffers = myBuff and {} or MT.fieldBuffers()
    -- for a buffer: the units still short of it, with their live damage (it goes to them, not on top of the copies already at the strongest group)
    local allies, allyTotal = {}, 0
    if myBuff then
        allies = MT.buffShort(myBuff)
        for _, a in ipairs(allies) do allyTotal = allyTotal + a.dps end
    end
    -- the guides' spot for units that have one (C.TIPS: Legendary Assassin near the exit, where leakers end up);
    -- and a dealt-team run's last line (MT.needLastLine): one enemy past every unit takes the base at once
    local tip = CFG.community and not entry and C.TIPS[e.id]
    local exit = ((tip and tip.spot == "exit") or (not entry and MT.needLastLine(e))) and not (depth and depth.leak)
    -- a second copy of a unit the farm grows by Merge stands where the copy already placed is inside its range at
    -- level 0 (Merge only takes the copies in the merged unit's range)
    local mergeAt = not (entry or wantLow or myBuff) and MT.mergeSpot(e)
    -- (70% of its level-0 range: at 90% a Switchblade copy landed just outside its own reach of the strong one)
    local range0 = mergeAt and UNIT.range(e.u, 0) * 0.7
    -- (a farm card next to its placed copy, so the pair can merge: MT.farmMergeOk)
    local farmAt, farmR
    if wantLow and UNIT.isFarm(e.id) then farmAt, farmR = MT.farmMergeSpot(e); farmR = farmAt and farmR * 0.8 end
    -- the road-side grid rarely has a free spot within a few studs of a unit: a ring of extra spots around the copy
    -- (2 C.E.O.s landed 24 studs apart with a ~10-stud reach)
    local roomy = wantLow and not farmAt and MT.random and UNIT.isFarm(e.id) and MT.farmMergeOk() and {} or nil
    local cands = MT.cands
    local near, nearR = farmAt or mergeAt, farmAt and farmR or range0
    if near and nearR and nearR > 0 then
        cands = table.clone(MT.cands)
        for _, d in ipairs({ 0.5, 0.7, 0.9 }) do
            for k = 0, 11 do
                local a = k * math.pi / 6
                table.insert(cands, near + Vector3.new(math.cos(a), 0, math.sin(a)) * nearR * d)
            end
        end
    end
    local best, bestScore, bestN
    local checked = 0
    local measured = B.maps[MT.mapKey()] and B.maps[MT.mapKey()].dens
    for _, pos in ipairs(cands) do
        local p = MT.valid(pos, data)
        checked = checked + 1
        if checked % 40 == 0 then task.wait() end
        if p then
            local sc
            if wantLow then
                sc = -MT.cover(p, range)
            elseif entry then
                sc = 0
                local fp = U.flat(p)
                for _, s in ipairs(MT.samples) do
                    if (U.flat(s.pos) - fp).Magnitude <= range then sc = sc + (s.prog <= entry + 0.05 and 1 or 0.1) end
                end
            elseif zone then
                -- (each sample of the trainee's stretch in reach at full range costs 2 samples of the rest)
                sc = 0
                local fp = U.flat(p)
                for _, s in ipairs(MT.samples) do
                    local d = (U.flat(s.pos) - fp).Magnitude
                    if s.prog < zone then if d <= rangeMax then sc = sc - 2 end
                    elseif d <= range then sc = sc + 1 end
                end
            elseif exit then
                sc = 0
                local fp = U.flat(p)
                for _, s in ipairs(MT.samples) do
                    if (U.flat(s.pos) - fp).Magnitude <= range then sc = sc + s.prog * s.prog end
                end
            elseif myBuff and allyTotal > 0 then
                -- a buffer stands where its range holds the most damage of the units it buffs, near them rather than at the edge of its reach (the road still counts a bit)
                local inRange = 0
                for _, a in ipairs(allies) do
                    local d = (U.flat(a.pos) - U.flat(p)).Magnitude
                    if d <= range then inRange = inRange + a.dps * (1.1 - 0.1 * d / math.max(1, range)) end
                end
                sc = inRange / allyTotal * 100 + MT.cover(p, range, true) * 0.05
            else
                local n = MT.cover(p, range, true, depth)
                -- (road reached at full range first, every sample counting the same: weighted by where enemies spend
                -- their time, the start of the road wins only because enemies have been dying there)
                if rangeFull then n = MT.cover(p, rangeFull) + n * 0.25 end
                sc = n + (measured and 0 or (1 - MT.progressAt(p)) * 0.5)
                -- inside a buffer's range that buffs this unit: worth the buff × its uptime (copies in reach take turns, up to the whole buff)
                local boost = 0
                for _, bf in ipairs(buffers) do
                    local rate = bf.b.types[myBase]
                    if rate and (U.flat(bf.pos) - U.flat(p)).Magnitude <= bf.range then boost = math.max(boost, math.min(rate, boost + rate * bf.b.uptime)) end
                end
                sc = sc * (1 + boost)
            end
            if mergeAt and (U.flat(mergeAt) - U.flat(p)).Magnitude <= range0 then sc = sc + 1e6 end
            if farmAt and (U.flat(farmAt) - U.flat(p)).Magnitude <= farmR then sc = sc + 1e6 end
            if roomy then table.insert(roomy, { p = p, sc = sc }) end
            if not bestScore or sc > bestScore then best, bestScore, bestN = p, sc, MT.cover(p, range) end
        end
    end
    -- (a buffer where nobody short of it stands in reach: no spot, not a copy that buffs no one)
    if myBuff and #allies > 0 and best then
        local reaches = false
        for _, a in ipairs(allies) do if (U.flat(a.pos) - U.flat(best)).Magnitude <= range then reaches = true; break end end
        if not reaches then return nil, 0 end
    end
    -- a farm's first copy: of the 15 best spots, the first with room for a second copy within 5 studs (2+ free
    -- spots on a ring), so the pair can merge later — the first C.E.O. stood boxed in by houses and no-place zones
    if roomy and #roomy > 0 then
        table.sort(roomy, function(a, b) return a.sc > b.sc end)
        for i = 1, math.min(15, #roomy) do
            local c, free = roomy[i].p, 0
            for k = 0, 7 do
                local a = k * math.pi / 4
                if MT.valid(c + Vector3.new(math.cos(a), 0, math.sin(a)) * 5, data) then free = free + 1 end
                if free >= 2 then break end
            end
            if free >= 2 then return c, MT.cover(c, range) end
        end
    end
    return best, bestN or 0
end
function MT.lookAt(p)
    local bd, target = math.huge, nil
    for _, s in ipairs(MT.samples) do
        local d = (U.flat(s.pos) - U.flat(p)).Magnitude
        if d < bd then bd, target = d, s.pos end
    end
    local dir = target and U.flat(target - p) or Vector3.new(0, 0, -1)
    return dir.Magnitude > 0.01 and dir.Unit or Vector3.new(0, 0, -1)
end
function MT.place(e, why)
    local farm = UNIT.isFarm(e.id)
    -- (an Idol buffs every unit wherever it stands: it takes a spot off the road, like a farm)
    local p, n = MT.bestSpot(e, farm or (MT.random and UNIT.idol(e.id)), MT.trainee ~= nil and e.uuid == MT.trainee)
    if not p then
        MT.noSpot[e.uuid] = (MT.noSpot[e.uuid] or 0) + 1
        SF.status("Placement", "no free spot for " .. UNIT.name(e.id))
        return false
    end
    local before = MT.money()
    local ok, r = SF.request("place", "spawn_unit", e.uuid, C.Util.CFramePLV(p, MT.lookAt(p)))
    if ok and r then
        MT.spent = MT.spent + (e.data.cost or 0)
        table.insert(MT.actions, string.format("placed %s", UNIT.name(e.id)))
        SF.log(1, "PLACE", string.format("%s at %s (covers %d road samples) — %s", UNIT.name(e.id), MT.spotKey(p), n, why))
        -- (the brain hive's record of where each copy went, when and why: REPORT.match)
        MT.placeLog = MT.placeLog or {}
        table.insert(MT.placeLog, { t = math.floor(U.now() - (MT.startT or U.now())), w = MT.wave(), id = e.id, x = math.floor(p.X), z = math.floor(p.Z), cover = math.floor((n or 0) + 0.5), why = tostring(why):sub(1, 90) })
        SF.status("Placement", string.format("placed %s — %s", UNIT.name(e.id), why))
        MT.placedAt = MT.placedAt or {}
        MT.placedAt[e.uuid] = (MT.placedAt[e.uuid] or 0) + 1
        return true
    end
    -- a dealt team: 2 refusals for one card and the economy stops choosing it (a full field it didn't count — 2
    -- clones — had it retry "place Captain (God)" from wave 23 to 27 while ¥191k sat unspent)
    if before >= (e.data.cost or 0) and MT.random then
        MT.placeFail = MT.placeFail or {}
        MT.placeFail[e.uuid] = (MT.placeFail[e.uuid] or 0) + 1
        if MT.placeFail[e.uuid] >= 2 then
            MT.noSpot[e.uuid] = 3
            SF.log(1, "PLACE", string.format("the game refused %s twice (%d/%d units counted) — buying something else", UNIT.name(e.id), MT.fieldCount(), MT.FIELD_MAX))
        end
    end
    -- refused: remember the spot (2 refusals in separate runs = skipped on this map for good) — not with a dealt
    -- team, where a refusal says nothing about the spot or the unit's limit
    -- (only when the server really answered no: during a 25-minute outage on Oct 31 every unanswered call counted, and "learned" Gene's limit as 1 copy)
    if ok and before >= (e.data.cost or 0) and not MT.random then
        local k = MT.spotKey(p)
        MT.refused[k] = true
        local mk = MT.mapKey()
        B.blocked[mk] = B.blocked[mk] or {}
        if not MT.refusedRun[k] then B.blocked[mk][k] = (tonumber(B.blocked[mk][k]) or 0) + 1; MT.refusedRun[k] = true end
        MT.refusals = (MT.refusals or 0) + 1
        MT.unitRefusals[e.uuid] = (MT.unitRefusals[e.uuid] or 0) + 1
        -- 3 refusals for one unit on different good spots with the money in hand: it's at its limit
        if MT.unitRefusals[e.uuid] >= 3 then
            -- (said once: this line once filled the log at one a second)
            local learned = math.max(1, MT.count(e.uuid))
            if B.caps[e.uuid] ~= learned then
                B.caps[e.uuid] = learned
                SF.log(1, "PLACE", string.format("%s: the server allows %d on the field (learned)", UNIT.name(e.id), learned))
            end
        end
        SF.log(2, "PLACE", "refused spot " .. k .. " for " .. UNIT.name(e.id))
        SF.saveSoon()
    end
    return false
end
function MT.count(uuid)
    local n = 0
    for _, folder in ipairs({ workspace._UNITS, workspace:FindFirstChild("_DEAD_UNITS") }) do
        if folder then
            for _, m in ipairs(folder:GetChildren()) do
                local st = m:FindFirstChild("_stats")
                if st and st:FindFirstChild("uuid") and st.player.Value == LP and st.uuid.Value == uuid then n = n + 1 end
            end
        end
    end
    return n
end
-- --- what the simulator learns from every match ------------------
function MT.measure()
    local cal, info = MT.calRun, MT.info
    if not (cal and info) then return end
    pcall(MT.sampleHelpers)
    local t = U.now()
    local w = MT.wave()
    local money = MT.money()
    if not cal.start and money > 0 and #MT.mine == 0 then cal.start = money end
    -- wave length, and the yen paid as a wave starts (minus what the farm units pay)
    if w ~= cal.lastW then
        -- (a trial run keeps a wave-by-wave record, to hold the simulator against: MT.trialDone)
        if MT.trialId and w > 0 then
            MT.trialTrace = MT.trialTrace or {}
            local copies, lv, dealt, others = 0, {}, 0, 0
            for _, m in ipairs(MT.mine) do
                local st = m._stats
                if st.id.Value == MT.trialId then copies = copies + 1; table.insert(lv, tostring(st.upgrade.Value))
                elseif not UNIT.isFarm(st.id.Value) then others = others + 1 end
            end
            pcall(MT.sampleHelpers, true)
            for _, o in pairs(MT.ownDealt) do if o.id == MT.trialId then dealt = dealt + o.v end end
            local helper = 0
            for _, h in pairs(MT.helperDealt) do if h.owner == MT.trialId then helper = helper + h.v end end
            table.insert(MT.trialTrace, string.format("w%d t=%.0f ¥%d copies[%s] others %d dealt %.0f alive %d hp %.0f front %.2f dps %.0f", w, t - (MT.startT or t), money, table.concat(lv, ","), others, dealt + helper, #(MT.enemies or {}), MT.hpAliveRaw or 0, MT.waveMax[w - 1] or 0, MT.teamDps or 0))
        end
        if cal.lastW and cal.lastW > 0 and cal.lastWT then table.insert(cal.waveSec, t - cal.lastWT) end
        -- wave paid (cleared) → next wave: the auto-skip's wait
        if cal.paidT and w > 0 and t - cal.paidT < 15 then table.insert(cal.skip, t - cal.paidT) end
        cal.paidT = nil
        if w > 0 then cal.alive[tostring(w)] = MT.hpAliveRaw or 0 end
        cal.lastW, cal.lastWT = w, t
    end
    -- the wave's timer: the longest value seen during the wave
    local wt = workspace:FindFirstChild("_wave_time")
    if wt and w > 0 then cal.timer[tostring(w)] = math.max(cal.timer[tostring(w)] or 0, tonumber(wt.Value) or 0) end
    -- yen income per second over the last 30 s (waves, kills, farm) — what saving for a buy costs in time
    local dm = money - (MT.lastMoneyR or money)
    MT.lastMoneyR = money
    MT.incomeLog = MT.incomeLog or {}
    if dm > 0 then table.insert(MT.incomeLog, { t = t, y = dm }) end
    while MT.incomeLog[1] and t - MT.incomeLog[1].t > 30 do table.remove(MT.incomeLog, 1) end
    local sum = 0
    for _, x in ipairs(MT.incomeLog) do sum = sum + x.y end
    local span = math.min(30, t - (MT.startT or t))
    MT.incomeRate = span >= 8 and sum / span or nil
    -- enemies: real HP vs the formula, walking speed
    for _, e in ipairs(MT.enemies) do
        local m = e.m
        local tr = MT.track[m]
        if not tr then
            local st = m._stats
            local hum = m:FindFirstChildOfClass("Humanoid")
            local key = info.cfgById[st.id.Value]
            local base = key and SIM.baseStats(info, key)
            if hum and base and w > 0 then
                local pred = base * info.hpRaw * SIM.waveScale(info, w, info.list[w])
                if pred > 0 and hum.MaxHealth > 0 then table.insert(cal.hp, hum.MaxHealth / pred) end
            end
            MT.track[m] = { t = t, p = e.prog, sp = (st:FindFirstChild("speed") and tonumber(st.speed.Value)) or 1 }
            if w > 0 then
                cal.spawn[tostring(w)] = (cal.spawn[tostring(w)] or 0) + 1
                cal.spawnLast[tostring(w)] = t - (cal.lastWT or t) -- the wave's last enemy so far came out this long after it started
            end
        -- (over 15 s: 4 s is about 3 road samples, so the median sat on the lower step. It held the Daily's road at 0.00472 a second where 448 real enemies walked 0.00496, and enemies reach the base about 10 s sooner than that)
        elseif not tr.done and t - tr.t >= 15 then
            tr.done = true
            local rate = (e.prog - tr.p) / (t - tr.t) / math.max(0.1, tr.sp)
            if rate > 0.001 and e.prog < 0.95 then table.insert(cal.walk, rate) end
        end
    end
    -- kill efficiency: damage that really landed (units' total_damage) ÷ the listed damage of units that had a
    -- target, over 5-second windows; and team damage at each wave start (to compare the sim's buying)
    local dealt = 0
    for _, m in ipairs(MT.mine) do
        local td = m._stats:FindFirstChild("total_damage")
        if td then dealt = dealt + td.Value end
    end
    cal.potSum = cal.potSum or 0
    if cal.lastDealtT then
        local dt = t - cal.lastDealtT
        local pot = 0
        for _, m in ipairs(MT.mine) do
            local st = m._stats
            local id = st.id.Value
            if not UNIT.isFarm(id) and st:FindFirstChild("target") and st.target.Value ~= nil then
                local okD, v = pcall(MT.liveDps, m, id)
                if okD and v then pot = pot + v * dt end
            end
        end
        cal.potWin = (cal.potWin or 0) + pot
        if t - (cal.winT or t) >= 5 then
            local d = dealt - (cal.winDealt or dealt)
            if cal.potWin > 0 and d >= 0 then cal.dealtSum = (cal.dealtSum or 0) + d; cal.potSum = cal.potSum + cal.potWin end
            cal.winT, cal.winDealt, cal.potWin = t, dealt, 0
        end
    end
    if not cal.winT then cal.winT, cal.winDealt = t, dealt end
    cal.lastDealtT = t
    if w ~= cal.dpsW and w > 0 then cal.dpsAt[tostring(w)] = MT.teamDps or 0; cal.dpsW = w end
    -- where enemies spend their time on the road (20 bins): placement weights the road by it
    local dt2 = math.min(1, t - (cal.densT or t))
    cal.densT = t
    for _, e in ipairs(MT.enemies) do
        local b = math.min(SIM.BINS, math.floor(e.prog * SIM.BINS) + 1)
        cal.dens[b] = (cal.dens[b] or 0) + dt2
    end
    -- base: HP lost per second ÷ the max HP of the enemies standing at the end of the road
    local base = workspace._BASES.player:FindFirstChild("base")
    local fu = base and base:FindFirstChild("fake_unit")
    local hum = fu and fu:FindFirstChildOfClass("Humanoid")
    if hum then
        cal.baseHp = math.max(cal.baseHp or 0, hum.MaxHealth)
        local atEnd = 0
        for _, e in ipairs(MT.enemies) do
            if e.prog >= 0.97 then
                local eh = e.m:FindFirstChildOfClass("Humanoid")
                atEnd = atEnd + (eh and eh.MaxHealth or e.hp)
            end
        end
        if cal.lastBase and hum.Health < cal.lastBase and atEnd > 0 and cal.lastBaseT then
            table.insert(cal.baseRel, (cal.lastBase - hum.Health) / math.max(0.1, t - cal.lastBaseT) / atEnd)
        end
        cal.lastBase, cal.lastBaseT = hum.Health, t
    end
end
-- the road coverage of the best spot at each range on this map (the simulator's placement)
function MT.recordMap()
    local map = MT.mapKey()
    local old = B.maps[map]
    -- re-record while the enemy-density data is still new (the best spot moves to where enemies really are). A map recorded before lanes were (laneV) is recorded once more
    if old and old.v == 1 and old.laneV and (old.densN or 0) == (old.binsDensN or 0) then return end
    if old and old.v == 1 and old.laneV and (old.densN or 0) > 5 and (old.binsDensN or 0) >= 5 then return end
    local ground = { override_hitbox_radius = 1.75 }
    local hill = { hill_unit = true, override_hitbox_radius = 1.75 }
    local spots, hillOk = {}, false
    for i, pos in ipairs(MT.cands) do
        local p = MT.valid(pos, ground)
        if p then table.insert(spots, p) end
        if not hillOk and MT.valid(pos, hill) then hillOk = true end
        if i % 30 == 0 then task.wait() end
    end
    local bins, binsL = {}, {}
    local lanes = SIM.laneList(MT.samples)
    for rb = 5, 60, 5 do
        local best, bestN
        for _, p in ipairs(spots) do local n = MT.cover(p, rb, true); if not bestN or n > bestN then best, bestN = p, n end end
        if best then
            local mask, perLane = {}, {}
            for i = 1, SIM.BINS do mask[i] = "0" end
            for _, l in ipairs(lanes or {}) do perLane[l] = {}; for i = 1, SIM.BINS do perLane[l][i] = "0" end end
            local fp = U.flat(best)
            for _, s in ipairs(MT.samples) do
                if (U.flat(s.pos) - fp).Magnitude <= rb then
                    local bin = math.min(SIM.BINS, math.floor(s.prog * SIM.BINS) + 1)
                    mask[bin] = "1"
                    if perLane[tostring(s.lane)] then perLane[tostring(s.lane)][bin] = "1" end
                end
            end
            bins[tostring(rb)] = table.concat(mask)
            if lanes then
                binsL[tostring(rb)] = {}
                for l, m in pairs(perLane) do binsL[tostring(rb)][l] = table.concat(m) end
            end
        end
        task.wait()
    end
    local keep = B.maps[map] or {}
    -- (lanes: each lane's own road from that spot, so the simulator can tell a spot on one lane from one on both: Shibuya's two lanes run apart for 20-49 studs at the start and at 70-80%, and Chuuni stood on one of them in both runs)
    B.maps[map] = { v = 1, laneV = 1, bins = bins, binsL = lanes and binsL or nil, lanes = lanes, hill = hillOk, spots = #spots, dens = keep.dens, densN = keep.densN, binsDensN = keep.densN or 0, lay = keep.lay, walk = keep.walk, walkN = keep.walkN }
    SIM._masks = {}
    SF.log(1, "SIM", string.format("mapped %s: %d free spots%s", map, #spots, hillOk and ", hill spots too" or ", no hill spots"))
    SF.saveSoon()
end
-- who really dealt what, helpers too (they aren't in MT.mine and vanish when their time is up): the log's DAMAGE line after a match, to hold the simulator
-- against. Iron Sentinel's drones dealt 47% of one room, and Chuuni 64% of another and nothing at all in the next
MT.helperDealt, MT.helperAt, MT.ownDealt = {}, 0, {}
function MT.sampleHelpers(now)
    if not now and U.now() - MT.helperAt < 3 then return end
    MT.helperAt = U.now()
    local folder = workspace:FindFirstChild("_UNITS")
    local mine = {}
    for _, m in ipairs(MT.mine or {}) do
        mine[m] = true
        -- (a unit's count as last seen, so one that's sold or removed keeps what it dealt: only the units still standing were counted, and a sold unit's damage vanished from the line)
        local st = m:FindFirstChild("_stats")
        local td = st and st:FindFirstChild("total_damage")
        if td and st:FindFirstChild("id") then
            local o = MT.ownDealt[m] or { id = st.id.Value, v = 0, lvl = 0 }
            o.v = math.max(o.v, td.Value)
            o.lvl = math.max(o.lvl, st:FindFirstChild("upgrade") and tonumber(st.upgrade.Value) or 0)
            MT.ownDealt[m] = o
        end
    end
    for _, m in ipairs(folder and folder:GetChildren() or {}) do
        local st = m:FindFirstChild("_stats")
        local par = st and st:FindFirstChild("parent_unit")
        local td = st and st:FindFirstChild("total_damage")
        if par and td and par.Value ~= nil and mine[par.Value] then
            local ost = par.Value:FindFirstChild("_stats")
            local h = MT.helperDealt[m] or { id = st.id.Value, owner = ost and ost:FindFirstChild("id") and ost.id.Value or nil, v = 0 }
            h.v = math.max(h.v, td.Value)
            MT.helperDealt[m] = h
        end
    end
end
-- (a jelly lives a moment and its damage lands as it dies, between those looks: Elyssia read 0% with 99 helpers, and 88% once her helpers reported their own count as it changed. So every unit's helpers do, since the same could hide
-- anyone's real share. Enemies have no parent_unit, so they're dropped after a moment)
function MT.watchHelpers()
    local folder = workspace:FindFirstChild("_UNITS")
    if not folder then return end
    table.insert(SF.conns, folder.ChildAdded:Connect(function(m)
        task.spawn(function()
            local st = m:WaitForChild("_stats", 3)
            task.wait(0.1)
            local par = st and st:FindFirstChild("parent_unit")
            local td = st and st:FindFirstChild("total_damage")
            if not (td and par and par.Value) then return end
            local ost = par.Value:FindFirstChild("_stats")
            local owner = ost and ost:FindFirstChild("id") and ost.id.Value or nil
            if not owner then return end
            local mine = false
            for _, o in ipairs(MT.mine or {}) do if o == par.Value then mine = true; break end end
            if not mine then return end
            local function note()
                local h = MT.helperDealt[m] or { id = st.id.Value, owner = owner, v = 0 }
                h.v = math.max(h.v, td.Value)
                MT.helperDealt[m] = h
            end
            note()
            table.insert(SF.conns, td.Changed:Connect(note))
        end)
    end))
end
-- each unit's share of this match's damage, by unit id, a helper's damage counted for the unit that spawned it (the Team tab's weights)
function MT.damageShares()
    pcall(MT.sampleHelpers, true)
    local by, sum = {}, 0
    local function add(id, v) by[id] = (by[id] or 0) + v; sum = sum + v end
    for _, o in pairs(MT.ownDealt) do if not UNIT.isFarm(o.id) then add(o.id, o.v) end end
    local n = 0
    for _, h in pairs(MT.helperDealt) do add(h.owner or "helpers", h.v); n = n + 1 end
    if sum <= 0 then return nil end
    for id, v in pairs(by) do by[id] = v / sum end
    return by, sum, n
end
function MT.damageLine()
    local shares, sum, n = MT.damageShares()
    if not shares then return nil end
    local list = {}
    for id, sh in pairs(shares) do table.insert(list, { name = id == "helpers" and "helpers" or UNIT.name(id), v = sh }) end
    table.sort(list, function(a, b) return a.v > b.v end)
    local parts = {}
    for _, x in ipairs(list) do table.insert(parts, string.format("%s %d%%", x.name, math.floor(x.v * 100 + 0.5))) end
    return string.format("%s dealt: %s%s", U.fmt(sum), table.concat(parts, " · "), n > 0 and string.format(" (%d helpers)", n) or "")
end
-- after a run: fold what was measured into the mode's calibration (rate slows as runs add up)
function MT.calMerge(won)
    local r = MT.calRun
    if not (r and MT.key) then return end
    local cal = SIM.cal(MT.key)
    cal.n = (tonumber(cal.n) or 0) + 1
    local rate = math.max(0.2, 1 / cal.n)
    local function med(list) if #list == 0 then return nil end table.sort(list) return list[math.ceil(#list / 2)] end
    local function blend(name, v) if v then cal[name] = cal[name] and (cal[name] + (v - cal[name]) * rate) or v end end
    -- (this run's own reading goes in its brain hive record too: other farms start from it on a map they haven't played, REPORT.hiveHp)
    MT.hpRun = med(r.hp)
    blend("hpCal", MT.hpRun)
    blend("walk", med(r.walk))
    -- (and the map's own, which is what the simulator goes by: SIM.mapWalk)
    do
        local seen, mk = med(r.walk), MT.mapKey()
        if seen then
            local old = SIM.mapWalk(mk)
            B.maps[mk] = B.maps[mk] or {}
            local rec = B.maps[mk]
            rec.walkN = (tonumber(rec.walkN) or 0) + 1
            rec.walk = old and (old + (seen - old) * math.max(0.2, 1 / (rec.walkN + 1))) or seen
            SIM._walk[mk] = rec.walk
        end
    end
    if (r.potSum or 0) > 0 and (r.dealtSum or 0) > 0 then blend("eff", U.clamp(r.dealtSum / r.potSum, 0.1, 2)) end
    -- road density per map (EMA, scaled so the busiest bin is 1)
    local mk = MT.mapKey()
    local mx = 0
    for _, v in pairs(r.dens) do mx = math.max(mx, v) end
    if mx > 0 then
        B.maps[mk] = B.maps[mk] or {}
        local dens = type(B.maps[mk].dens) == "table" and B.maps[mk].dens or {}
        local dn = (tonumber(B.maps[mk].densN) or 0) + 1
        for b = 1, SIM.BINS do
            local v = (r.dens[b] or 0) / mx
            local o = tonumber(dens[b])
            dens[b] = o and (o + (v - o) * math.max(0.2, 1 / dn)) or v
        end
        B.maps[mk].dens, B.maps[mk].densN = dens, dn
    end
    -- wave pay vs listed yen × money scale (1 = the formula is right)
    if #r.pay >= 2 then blend("yenCal", U.clamp(med(r.pay), 0.5, 2)) end
    if not MT.joinedMid then
        blend("waveSec", med(r.waveSec))
        blend("baseRel", med(r.baseRel))
        cal.baseDps = nil -- old absolute reading (base damage scales with the enemy's HP)
        blend("skipDelay", med(r.skip))
        -- the gap between enemies coming out: the wave's last enemy ÷ its count (waves fully seen)
        local gp = {}
        for w = 2, MT.wave() - 1 do
            local n, last = tonumber(r.spawn[tostring(w)]), tonumber(r.spawnLast[tostring(w)])
            if n and last and n >= 3 then table.insert(gp, last / (n - 1)) end
        end
        if #gp >= 3 then blend("spawnGap", U.clamp(med(gp), 0.05, 5)) end
        -- the skip vote: its cap (waves big enough to reach it) and the seconds it adds per enemy in smaller waves
        local cap = tonumber(cal.voteAt) or (MT.info and MT.info.voteAt) or SIM.PRIOR.voteAt
        local vt, vp = {}, {}
        for _, v in ipairs(r.votes) do
            local n = tonumber(v.n) or 0
            if n > 0 and SIM.PRIOR.voteBase + SIM.PRIOR.votePer * n >= cap + 3 then table.insert(vt, v.t)
            elseif n > 0 and v.t < cap - 2 then table.insert(vp, (v.t - SIM.PRIOR.voteBase) / n) end
        end
        blend("voteAt", med(vt))
        blend("votePer", vp[1] and U.clamp(med(vp), 0.2, 6) or nil)
        -- (when each wave's vote really opened, for SIM.voteSec)
        cal.voteWave = type(cal.voteWave) == "table" and cal.voteWave or {}
        for _, v in ipairs(r.votes) do
            if v.w and v.t then
                local k, o = tostring(v.w), tonumber(cal.voteWave[tostring(v.w)])
                cal.voteWave[k] = o and (o + (v.t - o) * rate) or v.t
            end
        end
        -- each wave's timer (the longest value seen + the second it had already ticked)
        cal.timerAt = type(cal.timerAt) == "table" and cal.timerAt or {}
        for k, v in pairs(r.timer) do
            if v > 5 then local o = tonumber(cal.timerAt[k]); cal.timerAt[k] = o and (o + (v + 1 - o) * rate) or (v + 1) end
        end
        if r.start then cal.start = r.start end
        if r.baseHp then cal.baseHp = r.baseHp end
        cal.yen = nil -- old per-wave yen readings (taken at the wrong moment)
        -- enemies per wave: real count vs the sim's count (waves fully seen: not the last one)
        if MT.info then
            local real, sim = 0, 0
            for w = 2, MT.wave() - 1 do
                local n = tonumber(r.spawn[tostring(w)])
                if n then real = real + n; sim = sim + #(SIM.wave(MT.info, w, true)) end
            end
            if real > 0 and sim > 0 then blend("countCal", U.clamp(real / sim, 0.25, 6)) end
        end
        -- HP alive per wave, kept per team (the trust check compares the same team only)
        local units = {}
        for _, e in ipairs(MT.team or {}) do table.insert(units, e.u) end
        local sig = SIM.sig(units)
        -- (and per level: the half-hour challenge shares one key across different maps)
        local lvl = tostring(MT.ld.id or "?")
        if cal.teamSig ~= sig or cal.aliveLvl ~= lvl then cal.alive = {}; cal.teamSig = sig; cal.aliveLvl = lvl; cal.aliveN = 0; cal.lastWave = 0; cal.dpsAt = {} end
        cal.aliveN = (tonumber(cal.aliveN) or 0) + 1
        local ar = 1 / cal.aliveN
        cal.alive = type(cal.alive) == "table" and cal.alive or {}
        for w, v in pairs(r.alive) do local o = tonumber(cal.alive[w]); cal.alive[w] = o and (o + (v - o) * ar) or v end
        cal.lastWave = math.max(tonumber(cal.lastWave) or 0, MT.wave())
        cal.dpsAt = type(cal.dpsAt) == "table" and cal.dpsAt or {}
        for w, v in pairs(r.dpsAt) do local o = tonumber(cal.dpsAt[w]); cal.dpsAt[w] = o and (o + (v - o) * ar) or v end
    end
    cal.ld = SIM.slim(MT.ld)
    cal.ch = MT.ld._challenge
    -- the calibration changed: this mode's old simulation is stale, the lobby re-simulates it
    B.simRes[MT.key] = nil
    SIM._masks = {}
    -- predicted vs real (rule: every planned run logs both)
    if MT.pred and MT.infinite then
        SF.log(1, "SIM", string.format("predicted the base falls at wave %d%s · real wave %d", MT.pred.wave, MT.pred.won and "+" or "", MT.wave()))
        cal.lastPred = { won = MT.pred.won, wave = MT.pred.wave, realWon = won, realWave = MT.wave(), at = os.time() }
    elseif MT.pred then
        SF.log(1, "SIM", string.format("predicted %s at wave %d · real %s at wave %d", MT.pred.won and "a win" or "a loss", MT.pred.wave, won and "a win" or "a loss", MT.wave()))
        cal.lastPred = { won = MT.pred.won, wave = MT.pred.wave, realWon = won, realWave = MT.wave(), at = os.time() }
    end
end
-- what placing a slow or a stun adds (ECON.holdGain): a Fool's Hunt card goes by its own rules
function MT.holdGain(e, r0)
    if MT.random or not r0 or not MT.info then return 0 end
    local ai = UNIT.attackInfo(r0.atk, r0.range)
    if (ai.stun or 0) <= 0 and (ai.slowTime or 0) <= 0 then return 0 end
    local have = 0
    for _, m in ipairs(MT.mine or {}) do
        local st = m._stats
        local rows = UNIT.rows(st.id.Value)
        local r = rows and rows[math.min(st.upgrade.Value, rows.max)]
        local i = r and r.atk and UNIT.attackInfo(r.atk, r.range)
        if i and ((i.stun or 0) > 0 or (i.slowTime or 0) > 0) then have = have + 1 end
    end
    local mask, width = SIM.mask(MT.info.map, UNIT.range(e.u, 0) * (MT.info.rangeScale or 1)), 0
    for i = 1, SIM.BINS do if mask[i] then width = width + 1 end end
    local cover = MT.depth and MT.depth.units > 0 and MT.depth.covEnd or 1
    local ground = (UNIT.airFrom(e.id) == 0) and 1 or (1 - (1 - C.FLY_GROUND) * math.min(1, MT.info.flyChance or 0))
    return ECON.holdGain(ai, MT.teamDps or 0, width / (math.max(0.1, cover) * SIM.BINS) * ground, have)
end
-- what placing a buffer adds: its buff × uptime × the damage of the units still short of it, in the one group a new copy can reach
function MT.buffGain(e)
    local b = UNIT.allyBuff(e.id)
    if not b then return 0 end
    local short = MT.buffShort(b)
    -- a buff measured to add up (B.stack, MT.actives) is worth another copy until the cap; otherwise the next turn of the buff
    local stk = B.stack[b.attack]
    local cap = stk and stk.stacks and (stk.cap or 1) or nil
    local okR, reach = pcall(UNIT.range, e.u, 0)
    reach = (okR and tonumber(reach) or 15) * ((MT.info and tonumber(MT.info.rangeScale)) or 1)
    local best = 0
    for _, c in ipairs(short) do
        local g = 0
        for _, o in ipairs(short) do
            if (o.pos - c.pos).Magnitude <= reach then
                local rate = b.types[o.base]
                local add = rate * b.uptime
                if cap then add = math.max(0, math.min(cap, (o.n + 1) * rate * b.uptime) - math.min(cap, o.n * rate * b.uptime)) end
                g = g + o.dps * add
            end
        end
        best = math.max(best, g)
    end
    return best * 0.7
end
-- worth another copy? Only for a group with about a tenth of your damage or more: a small unit standing alone doesn't get a pair of its own
function MT.buffWanted(e)
    return MT.buffGain(e) > 0.01 * (MT.teamDps or 0)
end
-- --- economy: farm or damage? ----------------------------------
-- live damage of a placed unit (the game's own stats: level, trait, rolls, curse, relic crit already in)
function MT.liveDps(m, id)
    local st = m:FindFirstChild("_stats")
    if not (st and st:FindFirstChild("attack_cooldown") and st:FindFirstChild("damage") and st:FindFirstChild("range")) then return 0 end
    local cd = math.max(0.1, st.attack_cooldown.Value)
    local atk = st:FindFirstChild("primary_attack") and st.primary_attack.Value or nil
    local crit = 0
    for _, n in ipairs({ "physical_crit_chance", "magic_crit_chance" }) do
        local v = st:FindFirstChild(n)
        if v then crit = math.max(crit, tonumber(v.Value) or 0) end
    end
    -- (a bonus for one damage type stays outside the stats: a dungeon's Mage Coat is the attribute _dmg_mul_magic = 0.5)
    local _, base = UNIT.types(id)
    local key = "_dmg_mul_" .. tostring(base)
    local typed = 1 + (tonumber(m:GetAttribute(key)) or tonumber(st:GetAttribute(key)) or 0)
    -- (a crit does ×1.5: a 50% chance is +25%, not +50%. A Gale counts its average, UNIT.galeDps, as UNIT.dps does: an upgrade's gain is next level against this)
    local gale = st.damage.Value * UNIT.galeDps(id, st:FindFirstChild("upgrade") and tonumber(st.upgrade.Value) or 0)
    return (st.damage.Value / cd * UNIT.aoe(atk, st.range.Value) * (1 + crit * 0.5) + gale) * UNIT.elem(id, MT.mod) * UNIT.nudge(id) * typed
end
MT.upFail, MT.upFailAt = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }) -- placed unit → upgrades refused
-- a unit on trial too dear to place early: the others may spend this much keeping the run alive, then the yen is saved for it
MT.TRIAL_DEAR, MT.TRIAL_KEEP_ALIVE = 30000, 20000
function MT.trialSaving()
    local d = C.Units[MT.trialId]
    if (tonumber(d and d.cost) or 0) < MT.TRIAL_DEAR or (MT.spent or 0) < MT.TRIAL_KEEP_ALIVE then return false end
    for _, m in ipairs(MT.mine or {}) do if m._stats.id.Value == MT.trialId then return false end end
    return true
end
function MT.econ()
    -- (a dungeon room's last life, kept: nothing goes down on the way out)
    if MT.noBuy then return SF.status("Economy", "keeping the last life: back to the lobby") end
    -- (the simulator is choosing spots: a moment before the first unit goes down, never more than 12 s)
    if MT.planning and U.now() - MT.planning < 20 then return SF.status("Economy", "the simulator is choosing spots on this map…") end
    local money = MT.money()
    local wave = MT.wave()
    local left = math.max(0, MT.total - wave)
    local team = MT.team
    local upMult = 1
    local spawnMult = 1
    pcall(function() spawnMult = C.USC.calculate_spawn_cost_multiplier(C.session()) end)
    local opts = {}
    local attackers, farmNow, wantLeft = 0, 0, 0
    -- attackers on the field before this pass (the loop below counts them card by card)
    local onField = 0
    for _, m in ipairs(MT.mine) do if not UNIT.isFarm(m._stats.id.Value) then onField = onField + 1 end end
    local byUuid = {}
    for _, m in ipairs(MT.mine) do
        local st = m._stats
        local uuid = st:FindFirstChild("uuid") and st.uuid.Value
        if uuid then byUuid[uuid] = byUuid[uuid] or {}; table.insert(byUuid[uuid], m) end
    end
    for _, e in ipairs(team) do
        -- (a trial run: the yen goes to the unit on trial. The others stand by until enemies get 60% of the way down the road, so a slow starter still lives to reach its later upgrades, and the yen comes back to it once they're pushed back: MODE.trialRow.
        -- At 75% a Jackal (Alpha) run was lost at wave 9 with only ¥9,300 on him)
        if MT.trialId and e.id ~= MT.trialId and not UNIT.isFarm(e.id) and (MT.trialSaving() or (not UNIT.allyBuff(e.id) and (MT.pressure or 0) < 0.6)) then continue end
        -- (and one too dear to come up by damage per yen goes down the moment the yen is there: Usurper (Founder) has no attack of his own, ¥100,000 to place, and a first run that never placed him said nothing)
        if MT.trialId == e.id and (tonumber(e.data.cost) or 0) >= MT.TRIAL_DEAR and #(byUuid[e.uuid] or {}) == 0 and money >= (tonumber(e.data.cost) or 0) * spawnMult then
            MT.place(e, "on trial")
            return
        end
        local rows = UNIT.rows(e.id)
        local farm = UNIT.isFarm(e.id)
        local placed = byUuid[e.uuid] or {}
        local trainee = MT.trainee == e.uuid and TRAIN.BONUS or 1 -- takedown training: it gets bought for, like in the sim
        if not farm and #placed > 0 then attackers = attackers + 1 end
        -- upgrades of placed copies (not a unit that only shares the card's uuid — the Ritual's Divine General took
        -- the sacrificed Sword Queen's: "upgrade Sword Queen to level 1" was refused over and over while ¥53k piled
        -- up — and not one the game refused 3 times in the last minute)
        for _, m in ipairs(placed) do
          if m._stats.id.Value == e.id and not ((MT.upFail[m] or 0) >= 3 and U.now() - (MT.upFailAt[m] or 0) < 60) then
            local lvl = m._stats.upgrade.Value
            if farm then farmNow = farmNow + (tonumber(m._stats.farm_amount and m._stats.farm_amount.Value) or UNIT.farm(e.u, lvl)) end
            local nxt = rows[lvl + 1]
            if nxt and lvl < rows.max then
                pcall(function() upMult = C.USC.calculate_upgrade_cost_multiplier(m, C.session()) end)
                local cost = nxt.cost * upMult
                if farm then
                    local gain = UNIT.farm(e.u, lvl + 1) - UNIT.farm(e.u, lvl)
                    table.insert(opts, { farm = true, cost = cost, gain = gain, m = m, e = e, what = string.format("upgrade %s to level %d", UNIT.name(e.id), lvl + 1) })
                elseif MT.random and UNIT.idol(e.id) then
                    -- Idol: every level buffs the whole team and makes later upgrades cheaper (a guide's tip: max her first)
                    table.insert(opts, { cost = cost, gain = (MT.teamDps or 0) * MT.idolStep(), m = m, e = e, idol = true, what = string.format("upgrade %s to level %d", UNIT.name(e.id), lvl + 1) })
                elseif MT.mergeHold(m) then
                    -- kept at its level for a Merge (MT.mergeScan): what it absorbs then gets every upgrade on top
                else
                    local S, H = MT.shieldNow()
                    local gain = (S > 0 and ECON.shieldGain(MT.liveDps(m, e.id), rows[lvl], UNIT.dps(e.u, lvl + 1, MT.mod), nxt, S, H, 1, MT.info and MT.info.eff)
                        or ECON.upgradeGain(MT.liveDps(m, e.id), rows, lvl, cost, upMult, UNIT.dps(e.u, lvl + 1, MT.mod))) * trainee * MT.mergeBoost(m) * MT.airBoost(m) * MT.reach(m) * MT.focusGain(m)
                    local bleed = MT.bleedGain(e.id, lvl, false)
                    gain = gain + bleed
                    table.insert(opts, { cost = cost, gain = gain, m = m, e = e, what = string.format("upgrade %s to level %d%s", UNIT.name(e.id), lvl + 1, bleed > 0 and " (towards its bleed, which stops regen)" or "") })
                    MT.upRate[m] = gain / math.max(1, cost)
                    for l = lvl + 1, rows.max do wantLeft = wantLeft + rows[l].cost * upMult end
                end
            end
          end
        end
        -- a new copy (a dealt unit: once, while it's in the hand)
        local cap = UNIT.cap(e.u)
        if MT.random then cap = e.hand and 1 or 0
        -- (a buffer: only while a group of attackers is short of it. The rest of the yen goes to the attackers)
        elseif UNIT.allyBuff(e.id) and trainee == 1 and not MT.buffWanted(e) then cap = 0 end
        if #placed < cap and (MT.noSpot[e.uuid] or 0) < 3 then
            local cost = (e.data.cost or 0) * spawnMult
            if farm then
                table.insert(opts, { farm = true, place = true, cost = cost, gain = UNIT.farm(e.u, 0), e = e, what = "place " .. UNIT.name(e.id) })
            else
                local bonus = (#placed == 0 and 2.5 or 1) * trainee
                if attackers < 3 then bonus = bonus * 1.3 end
                -- a dealt unit that carried past runs goes down first (its share of the damage, MT.fhRecord)
                if MT.random then bonus = bonus * (1 + 2 * MT.carry(e.id)) * (1 - MT.resistOf(e.id)) * MT.airNeed(e.id) * (MT.mergeIds[e.id] and 2 or 1)
                elseif MT.flyMode() then bonus = bonus * MT.airNeed(e.id) end -- (your own team: flyer-hitters once flyers come)
                -- a thin field (under 8 attackers) can't cover the road however strong one unit gets: a run merged Hex
                -- to 209k (94% of its damage) with 3–7 units placed and lost at wave 12 to an enemy that walked past
                -- all of them — a new unit counts ×1.25 per missing attacker
                if MT.random and onField < 8 then bonus = bonus * (1 + (8 - onField) * 0.25) end
                local idol = MT.random and UNIT.idol(e.id) and (MT.teamDps or 0) * MT.idolStep() * 2 or 0
                local base = MT.shieldOf(MT.random and MT.cardDps(e) or UNIT.dps(e.u, 0, MT.mod), rows[0]) + MT.shieldWork(e.id, rows[0])
                table.insert(opts, { place = true, cost = cost, gain = base * bonus + MT.buffGain(e) + idol + MT.holdGain(e, rows[0]) + MT.bleedGain(e.id, 0, true), e = e, what = "place " .. UNIT.name(e.id),
                    train = trainee ~= 1 and (#placed == 0 and "first" or "more") or nil })
                for l = 0, rows.max do wantLeft = wantLeft + rows[l].cost * (l == 0 and spawnMult or upMult) end
            end
        end
    end
    -- a full field (20 units): nothing more can be placed, the yen goes to upgrades (MT.makeRoom frees a spot)
    -- Astral Summon in hand: one of your own units (far better traits than a dealt card) — save the ¥10,000 for it
    -- while the defense isn't in danger
    if MT.random and HUB.every("summonCheck", 1) then
        MT.summonWait = false
        for _, spell in pairs(C.session().ingame_spells or {}) do if spell == "summon" and MT.summonWorth() then MT.summonWait = true end end
    end
    do
        local cover = MT.depth and MT.depth.units > 0 and MT.depth.covEnd or 1
        if MT.summonWait and money < 10000 and (MT.pressure or 0) < math.min(CFG.dangerReach, cover * 0.9) then
            return SF.status("Economy", string.format("saving ¥10k for Astral Summon (a unit from your own team): ¥%s", U.fmt(money)))
        end
        -- a Clone or Merge worth casting (MT.spells): its price first
        local want = MT.random and MT.spellWant
        -- (in danger only when it beats the best upgrade per yen: a Clone of the strongest unit usually does)
        if want and money < want.cost and ((MT.pressure or 0) < math.min(CFG.dangerReach, cover * 0.9) or (want.rate or 0) > (MT.bestRate or 0)) then
            return SF.status("Economy", string.format("saving ¥%s for %s: ¥%s", U.fmt(want.cost), want.why, U.fmt(money)))
        end
    end
    if MT.fieldCount() >= MT.FIELD_MAX then
        local kept = {}
        for _, o in ipairs(opts) do if not o.place then table.insert(kept, o) end end
        opts = kept
        -- a much stronger unit waits in the hand: save for the swap while the defense isn't in danger
        local cover = MT.depth and MT.depth.units > 0 and MT.depth.covEnd or 1
        if MT.roomPlan and money < MT.roomPlan.need and (MT.pressure or 0) < math.min(CFG.dangerReach, cover * 0.9) then
            return SF.status("Economy", string.format("saving ¥%s to swap %s for %s (the field is full)", U.fmt(MT.roomPlan.need), MT.roomPlan.out, MT.roomPlan.name))
        end
    end
    -- Infinite training: while enemies die early on the road, the other attackers wait and the yen goes to the trainee
    -- (TRAIN.hold); the saved yen goes in at once when enemies get further
    if MT.infinite and MT.trainee then
        local hold, why = TRAIN.hold(MT.pressure or 0, attackers, MT.holding)
        if hold then
            local kept = {}
            for _, o in ipairs(opts) do if o.farm or (o.e and o.e.uuid == MT.trainee) then table.insert(kept, o) end end
            opts = kept
            if #opts == 0 then return SF.status("Economy", why .. " · everything for the trainee is bought: saving ¥" .. U.fmt(money)) end
        end
        if hold ~= (MT.holding or false) then
            MT.holding = hold
            if HUB.every("holdLog", 60) then SF.log(1, "TRAIN", hold and why or "enemies get further now: your other units are bought for again") end
        end
    end
    -- the best damage per yen on offer (MT.refund: what a refunded unit's yen would buy)
    MT.bestRate = 0
    for _, o in ipairs(opts) do if not o.farm and not o.place and o.cost > 0 then MT.bestRate = math.max(MT.bestRate, o.gain / o.cost) end end
    if #opts == 0 then return SF.status("Economy", "everything is placed and fully upgraded ✓") end
    if MT.trainee then TRAIN.boost(opts, attackers, MT.pressure or 0, MT.depth and MT.depth.units > 0 and MT.depth.covEnd or nil) end
    -- future yen: wave rewards still to come + what the farm units pay every wave
    local future = money + farmNow * left
    for i = wave + 1, MT.total do future = future + MT.waveReward(i) end
    MT.farmNow, MT.future, MT.wantLeft = farmNow, future, wantLeft
    -- the next 3 waves' HP from the game's formula (this mode's simulator description, calibrated by real runs);
    -- enemy damage reduction counts as extra HP, like the live HP alive
    if MT.info and MT.comingW ~= wave then
        local coming = {}
        local red = math.min(0.9, MT.info.red or 0)
        for k = 1, 5 do
            local w2 = wave + k
            if w2 > MT.total then break end
            local okW, list, rew = pcall(SIM.wave, MT.info, w2)
            local h = 0
            for _, e in ipairs(okW and list or {}) do h = h + e.hp + (e.bar or 0) end
            table.insert(coming, { hp = h / (1 - red), reward = (okW and tonumber(rew)) or MT.waveReward(w2) })
        end
        MT.comingW, MT.coming = wave, coming
    end
    local eff = MT.info and MT.info.eff or SIM.PRIOR.eff
    local shieldK = MT.teamShield()
    -- the last wave's boss near the base: a new unit it walks past in seconds is money lost, so while something still reaches it
    -- the yen goes to upgrades on those units only (a passed unit's sale pays for them, MT.bossStep)
    if MT.focus and (MT.focusInRange or 0) > 0 then
        local kept = {}
        for _, o in ipairs(opts) do if not o.place then table.insert(kept, o) end end
        if #kept > 0 then opts = kept end
    end
    local choice, why, waitMsg = ECON.decide(opts, { money = money, left = left, attackers = attackers, pressure = MT.pressure or 0,
        piling = MT.piling, clearSec = (MT.clearSec or 0) / shieldK, enemies = #MT.enemies, future = future, wantLeft = wantLeft,
        coming = MT.coming, waveSec = MT.info and MT.info.waveSec, eff = eff, teamDps = (MT.teamDps or 0) * eff, shieldK = shieldK,
        farmNow = farmNow, hpAlive = MT.hpAlive or 0, roadSec = 1 / math.max(0.001, ((MT.info and MT.info.walk) or SIM.PRIOR.walk) * ((MT.info and MT.info.speedScale) or 1)),
        leak = MT.depth and MT.depth.leak, airLeak = MT.depth and MT.depth.airLeak, cover = MT.depth and MT.depth.units > 0 and MT.depth.covEnd or nil,
        incomeRate = MT.incomeRate or (((MT.coming and MT.coming[1] and MT.coming[1].reward) or 500) + farmNow) / ((MT.info and MT.info.waveSec) or 20) })
    if waitMsg then return SF.status("Economy", waitMsg) end
    if not choice then return end
    if not CFG.upgrade and not choice.place then return end
    if not CFG.place and choice.place then return end
    SF.status("Economy", string.format("%s — %s", choice.what, why))
    if choice.place then
        MT.place(choice.e, why)
    else
        local before = money
        local ok, r = SF.request("upg", "upgrade_unit_ingame", choice.m)
        if ok and r then
            MT.spent = MT.spent + choice.cost
            table.insert(MT.actions, choice.what)
            if choice.idol then pcall(MT.idolMeasure) end
            SF.log(2, "UPGRADE", choice.what .. " for ¥" .. U.fmt(choice.cost) .. " — " .. why)
            SF.status("Upgrade", choice.what)
        elseif ok then
            -- the server answered no: wait a moment (a call skipped by a running backoff must not re-arm it)
            SF.backoff("upg", 1.5)
            if before >= choice.cost then
                SF.log(2, "UPGRADE", "refused: " .. choice.what)
                MT.upFail[choice.m] = (MT.upFail[choice.m] or 0) + 1
                MT.upFailAt[choice.m] = U.now()
                if MT.upFail[choice.m] == 3 then SF.log(1, "UPGRADE", "the game refused " .. choice.what .. " 3 times — buying something else for a minute") end
            end
        end
    end
end
-- --- abilities -------------------------------------------------
-- abilities: buffs (Wendy's +30% magic damage for 30 s) go up as soon as the units they help are fighting and
-- never overlap; damage abilities wait for a boss in range or a crowd of 3+, and fire anyway after abilityHold
MT.readySince, MT.buffedTill = setmetatable({}, { __mode = "k" }), {}
-- the strongest damage buff on your units of these damage types right now (the game's _stats.buff_damage_multiplier)
MT.buffSeen = {}
function MT.buffOn(st, base)
    if (tonumber(st:GetAttribute("_dmg_buff_" .. tostring(base))) or 0) > 0 then return true end
    local v = st:FindFirstChild("buff_damage_multiplier")
    return v ~= nil and (tonumber(v.Value) or 0) > 0
end
function MT.buffLevel(types)
    local best = 0
    for _, m in ipairs(MT.mine) do
        local st = m._stats
        local id = st.id.Value
        if not UNIT.isFarm(id) and not UNIT.allyBuff(id) then
            local _, base = UNIT.types(id)
            local v = st:FindFirstChild("buff_damage_multiplier")
            if v and (not types or types[base]) then best = math.max(best, tonumber(v.Value) or 0) end
            -- (a buff for one damage type sits in an attribute of its own: _dmg_buff_magic reads 0.3 under Windsong while buff_damage_multiplier stays 0, measured Nov 1)
            if not types or types[base] then best = math.max(best, tonumber(st:GetAttribute("_dmg_buff_" .. tostring(base))) or 0) end
        end
    end
    return best
end
-- a switch ability with a bar: Snow Reaper (Final)'s Gale of the Moon (the user, Nov 2: "crowd control can be chained like Windsong but to freeze enemies"). Read live on Nov 2: from
-- upgrade 1 active_attack reads "<id>:active" while it's off (a press switches it on) and "<id>:off" while it runs; unit_bar fills 2.5 a second to 100 while off and drains 5 a second
-- while on (20 s from full), 4 s between presses. While on, enemies in her range are slowed, take a sixth of her damage every 0.5 s and gain Chilled; 6 Chilled freeze them.
-- Copies near each other take turns, so the slow and the freezes never stop: the next one goes on when the one running is nearly empty, the fullest bar first. A copy with nothing in
-- range switches off to keep its bar. A boss too: while one copy running has the boss in its range, the others wait with theirs full (the user's call, Nov 2: all on at once
-- wasted them). (The plain damage rule pressed it whenever a crowd came: on at a 1.25 bar, off again 4 s later)
MT.galeIdle = setmetatable({}, { __mode = "k" })
function MT.isGale(st, act)
    return st:FindFirstChild("unit_bar") ~= nil and (act:match(":active$") or act:match(":off$")) ~= nil
end
-- any unit with such a switch ability is learned the first time it shows one in a match, so the farm knows it from then on, and so do other players' farms through the brain
-- hive (REPORT.match: rec.toggles): the upgrade it comes at, and how fast its bar fills while off and drains while on, measured between readings in the same state
MT.barSeen = setmetatable({}, { __mode = "k" })
function MT.learnToggle(m, st, act, now)
    local id = st.id.Value
    local T = B.toggles[id]
    local lvl = tonumber(st:FindFirstChild("upgrade") and st.upgrade.Value) or 0
    local fresh = T == nil
    if not T then
        T = { from = lvl, fill = 0, drain = 0, nf = 0, nd = 0, at = os.time() }
        B.toggles[id] = T
        SIM._holds[id] = nil
    end
    if lvl < (tonumber(T.from) or lvl) then T.from = lvl end
    MT.togglesSeen = MT.togglesSeen or {}
    MT.togglesSeen[id] = true
    local bar, on = tonumber(st.unit_bar.Value) or 0, act:match(":off$") ~= nil
    local last = MT.barSeen[m]
    if last and last.on == on and now - last.t >= 1.5 then
        -- (a full or an empty bar stands still: no reading there)
        if bar > 0.5 and bar < 99.5 and last.bar > 0.5 and last.bar < 99.5 then
            local rate = (bar - last.bar) / (now - last.t)
            if on and rate < 0 then T.drain = (T.drain * T.nd - rate) / (T.nd + 1); T.nd = math.min(T.nd + 1, 50)
            elseif not on and rate > 0 then T.fill = (T.fill * T.nf + rate) / (T.nf + 1); T.nf = math.min(T.nf + 1, 50) end
        end
        MT.barSeen[m] = { bar = bar, t = now, on = on }
    elseif not last or last.on ~= on then
        MT.barSeen[m] = { bar = bar, t = now, on = on }
    end
    if fresh then
        SF.log(1, "UNITS", string.format("%s has a switch ability with a bar (from upgrade %d): learned, so its copies take turns and it stands where your damage is", UNIT.name(id), lvl))
        SF.saveSoon()
    end
end
function MT.gale(m, st, act, now)
    local kind = act:match("^(.+):")
    local function near(o)
        local p, r = U.flat(o:GetPivot().Position), o._stats.range.Value
        local n, bosses = 0, {}
        for _, e in ipairs(MT.enemies) do
            if (U.flat(e.pos) - p).Magnitude <= r then n = n + 1; if e.boss then table.insert(bosses, e) end end
        end
        return n, bosses
    end
    local bar = tonumber(st.unit_bar.Value) or 0
    local n, bosses = near(m)
    local boss = #bosses > 0
    if act:match(":off$") then
        if n > 0 then MT.galeIdle[m] = nil; return nil end
        MT.galeIdle[m] = MT.galeIdle[m] or now
        if now - MT.galeIdle[m] >= 3 and bar >= 15 then return true, string.format("Gale off: nothing in range, keeping its bar (%d)", math.floor(bar)) end
        return nil
    end
    MT.galeIdle[m] = nil
    if n == 0 or bar < 20 then return nil end
    -- its group: the other copies whose circles overlap this one's. One running with bar to spare covers it; one with a fuller bar and enemies in range goes first. With a boss in
    -- range, a copy running anywhere that reaches the same boss covers it
    local pos = U.flat(m:GetPivot().Position)
    for _, o in ipairs(MT.mine) do
        local os_ = o._stats
        local oa = os_:FindFirstChild("active_attack")
        local ov = oa and tostring(oa.Value) or ""
        if o ~= m and os_:FindFirstChild("unit_bar") and ov:match("^(.+):") == kind then
            local op, ob = U.flat(o:GetPivot().Position), tonumber(os_.unit_bar.Value) or 0
            local group = (op - pos).Magnitude <= math.max(st.range.Value, os_.range.Value)
            local onBoss = false
            for _, e in ipairs(bosses) do if (U.flat(e.pos) - op).Magnitude <= os_.range.Value then onBoss = true end end
            if ov:match(":off$") then
                if ob > 5 and (onBoss or (group and not boss)) then return nil end
            elseif group and ob > bar + 10 and ob >= 20 and near(o) > 0 then
                return nil
            end
        end
    end
    if not MT.galeSaid then
        MT.galeSaid = true
        SF.log(1, "ABILITY", string.format("%s: %s in use, copies take turns so enemies stay slowed and freezing", UNIT.name(st.id.Value), kind == "rukia_bankai" and "Gale of the Moon" or kind))
    end
    return true, string.format("Gale on: %d enemies in range%s, bar %d (copies take turns)", n, boss and ", a boss" or "", math.floor(bar))
end
function MT.actives()
    if not CFG.actives or MT.activeBusy then return end
    local t = tick()
    local now = U.now()
    for _, m in ipairs(MT.mine) do
        local st = m._stats
        local act, cdv, last = st:FindFirstChild("active_attack"), st:FindFirstChild("active_attack_cooldown"), st:FindFirstChild("last_active_cast")
        if act and cdv and last and act.Value ~= "nil" and act.Value ~= "" then
            if MT.isGale(st, tostring(act.Value)) then pcall(MT.learnToggle, m, st, tostring(act.Value), now) end
            if cdv.Value - (t - last.Value) > 0 then
                MT.readySince[m] = nil
            else
                MT.readySince[m] = MT.readySince[m] or now
                local info = UNIT.attackInfo(act.Value)
                local pos = m:GetPivot().Position
                local range = st.range.Value
                local fire, why, test
                if MT.isGale(st, tostring(act.Value)) then
                    fire, why = MT.gale(m, st, tostring(act.Value), now)
                elseif info.ally or info.allyCd or info.allyRange then
                    local bt = (info.ally and info.ally.time) or (info.allyCd and info.allyCd.time) or (info.allyRange and info.allyRange.time) or 30
                    -- each copy looks after the units around it: they're fighting without the buff, so it fires. Copies in one group take turns, and a group elsewhere keeps its own
                    -- going (one timer for the whole map held the back group's copies while the front's buff ran). A unit just placed in a buffed group waits for the next turn
                    local till = MT.buffedTill[act.Value]
                    if not till then till = setmetatable({}, { __mode = "k" }); MT.buffedTill[act.Value] = till end
                    local around, waiting, covered, longest = {}, 0, 0, 0
                    for _, o in ipairs(MT.mine) do
                        local os_ = o._stats
                        local oid = os_.id.Value
                        if o ~= m and not UNIT.isFarm(oid) and not UNIT.allyBuff(oid) and (U.flat(o:GetPivot().Position) - U.flat(pos)).Magnitude <= range then
                            local _, base = UNIT.types(oid)
                            if not info.ally or info.ally.types[base] then
                                table.insert(around, o)
                                if os_:FindFirstChild("target") and os_.target.Value ~= nil then
                                    -- (a cast on a unit still under the buff does nothing, not even renew it: measured Nov 1, Iron Sentinel's ended 30 s after the first of two casts. So the buff on the unit itself decides, not this
                                    -- clock, which fired a moment early, wasted a turn and left it bare for 57 s. Cast in the last 2 s: the game hasn't shown it yet)
                                    local on = (till[o] or 0) >= now
                                    if info.ally then
                                        on = MT.buffOn(os_, base) or (till[o] or 0) - bt + 2 >= now
                                    end
                                    if on then covered = covered + 1; longest = math.max(longest, till[o] or 0) else waiting = waiting + 1 end
                                end
                            end
                        end
                    end
                    -- another copy's buff while one is up: once as a test (the guides say Windsong / Commander buffs
                    -- chain to 100%), then whenever it's measured to add up, until the cap
                    local stk = B.stack[act.Value]
                    if stk and not stk.stacks and os.time() - (stk.at or 0) > 3 * 86400 then stk = nil end -- re-test now and then
                    local level = info.ally and covered > 0 and MT.buffLevel(info.ally.types) or 0
                    -- (a test needs the first buff to last past the 2 s check)
                    local chain = covered > 0 and info.ally and CFG.community and level > 0
                        and ((stk == nil and longest - now > 5) or (stk and stk.stacks and level < (stk.cap or 1) - 0.02))
                    if waiting > covered or chain then
                        fire, why = true, string.format("buffs %d of your units that are fighting", waiting + covered)
                        if chain and stk == nil then
                            test = { key = act.Value, types = info.ally.types, before = level }
                            why = why .. string.format(" (testing whether a 2nd buff adds up: now +%d%%)", math.floor(level * 100 + 0.5))
                        elseif chain then
                            why = why .. string.format(" (chaining: now +%d%%)", math.floor(level * 100 + 0.5))
                        end
                        for _, o in ipairs(around) do till[o] = now + bt end
                    end
                elseif info.baseSafe then
                    -- (it guards the base for 10 s and throws back what touches it, on a 6-minute cooldown: for the moment an enemy gets there. Fired at 90% of the road it was
                    -- nearly spent on arrival: at the run's enemy speed that last 10% takes about 9 s)
                    for _, e in ipairs(MT.enemies) do
                        if e.prog >= 0.98 then fire, why = true, "an enemy is at the base"; break end
                    end
                else
                    local near, boss = 0, false
                    for _, e in ipairs(MT.enemies) do
                        if (U.flat(e.pos) - U.flat(pos)).Magnitude <= range then
                            near = near + 1
                            if e.boss then boss = true end
                        end
                    end
                    local held = now - MT.readySince[m]
                    -- a long cooldown is worth waiting longer for: hold scales with it (6-min cooldown → up to ~2 min)
                    local hold = math.min(CFG.abilityHold * math.max(1, cdv.Value / 60), cdv.Value * 0.3)
                    local crowd = math.max(3, math.floor(#MT.enemies * 0.3))
                    -- (on trial with no attack of its own, its ability is all there is to measure)
                    if MT.trialId == st.id.Value and (tonumber((C.Units[MT.trialId] or {}).damage) or 0) <= 0 and #MT.enemies > 0 then fire, why = true, "on trial"
                    elseif near > 0 and boss then fire, why = true, "a boss is in range"
                    elseif near >= crowd then fire, why = true, near .. " enemies in range"
                    elseif near >= 3 and held >= hold * 0.5 then fire, why = true, string.format("%d enemies in range after %ds", near, math.floor(held))
                    elseif near >= 1 and held >= hold then fire, why = true, string.format("held %ds for a crowd, firing on %d", math.floor(held), near) end
                end
                if fire then
                    -- in its own thread: a slow answer must never hold up buying
                    MT.activeBusy = true
                    MT.readySince[m] = nil
                    task.spawn(function()
                        local ok = SF.request("active", "use_active_attack", m)
                        if ok then
                            MT.casts = MT.casts or {}
                            MT.casts[st.id.Value] = (MT.casts[st.id.Value] or 0) + 1
                            SF.status("Abilities", string.format("%s used its ability — %s", UNIT.name(st.id.Value), why))
                            SF.log(2, "ABILITY", UNIT.name(st.id.Value) .. ": " .. why)
                            -- how far a buffer's buff really climbs, for the record: one line a match, at the end (MT.buffSeen)
                            if info.ally then
                                task.delay(2, function()
                                    if not SF.alive then return end
                                    local seen = MT.buffSeen[st.id.Value] or { casts = 0, levels = {} }
                                    MT.buffSeen[st.id.Value] = seen
                                    seen.casts = seen.casts + 1
                                    if #seen.levels < 12 then table.insert(seen.levels, math.floor(MT.buffLevel(info.ally.types) * 100 + 0.5)) end
                                end)
                            end
                            -- the stacking test: did the buff on your units go up?
                            if test then
                                task.wait(2)
                                local after = MT.buffLevel(test.types)
                                local stacks = after > test.before + 0.05
                                B.stack[test.key] = { stacks = stacks, cap = stacks and 1 or nil, before = test.before, after = after, at = os.time() }
                                SF.log(1, "ABILITY", string.format("%s's buff %s: +%d%% → +%d%% with a second copy", UNIT.name(st.id.Value),
                                    stacks and "adds up (chaining it from now on)" or "doesn't add up (copies take turns)", math.floor(test.before * 100 + 0.5), math.floor(after * 100 + 0.5)))
                                SF.saveSoon()
                            end
                        end
                        MT.activeBusy = false
                    end)
                    return
                end
            end
        end
    end
end
-- --- targeting by role ----------------------------------------------
-- crowd control (slow / stun / freeze / knockback) and area attackers hold the front ("first"), where the
-- whole team can hit; heavy single-target hitters take the boss ("strongest") while one is alive
MT.prioAt = setmetatable({}, { __mode = "k" })
function MT.targeting()
    -- takedown training: the trainee hits the newest enemy in its range ("last"), one your other units haven't
    -- killed yet ("first" chases the enemy your strongest unit is already finishing)
    for _, m in ipairs(MT.trainee and MT.mine or {}) do
        local st = m._stats
        local pr = st:FindFirstChild("priority")
        if pr and st:FindFirstChild("uuid") and st.uuid.Value == MT.trainee and pr.Value ~= "last" and U.now() - (MT.prioAt[m] or 0) > 8 then
            MT.prioAt[m] = U.now()
            if SF.request("prio", "change_priority", m, "last") then SF.log(2, "TARGET", UNIT.name(st.id.Value) .. " → last (takedown training)") end
            return
        end
    end
    -- the guides' targeting for units that have a tip (C.TIPS: Chuuni on "strongest" keeps its mark on the boss)
    for _, m in ipairs(CFG.community and MT.mine or {}) do
        local st = m._stats
        local tip = C.TIPS[st.id.Value]
        local pr = st:FindFirstChild("priority")
        if tip and tip.target and pr and pr.Value ~= tip.target and U.now() - (MT.prioAt[m] or 0) > 8 then
            MT.prioAt[m] = U.now()
            if SF.request("prio", "change_priority", m, tip.target) then SF.log(2, "TARGET", UNIT.name(st.id.Value) .. " → " .. tip.target .. " (" .. tip.why .. ")") end
            return
        end
    end
    -- a flyer on the road: the units that can hit flyers go for them first (the game's "flying" priority)
    local flyers = false
    for _, e in ipairs(MT.enemies or {}) do if e.fly then flyers = true; break end end
    for _, m in ipairs(flyers and MT.mine or {}) do
        local st = m._stats
        local pr = st:FindFirstChild("priority")
        -- (a unit with a tip keeps it: Chuuni flipped between "strongest" and "flying" every 9 s all through a lost room, and each flip made the others wait)
        local tipped = CFG.community and C.TIPS[st.id.Value] and C.TIPS[st.id.Value].target
        if pr and pr.Value ~= "flying" and not tipped and MT.canAir(m) and not UNIT.isFarm(st.id.Value) and not UNIT.allyBuff(st.id.Value) and U.now() - (MT.prioAt[m] or 0) > 8 then
            local okV, valid = pcall(C.USC.get_valid_priorities, m)
            if okV and type(valid) == "table" and valid.flying then
                MT.prioAt[m] = U.now()
                if SF.request("prio", "change_priority", m, "flying") then SF.log(2, "TARGET", UNIT.name(st.id.Value) .. " → flying (a flyer is on the road)") end
                return
            end
        end
    end
    if not CFG.smartTarget then return end
    local bossAlive = false
    for _, e in ipairs(MT.enemies) do if e.boss then bossAlive = true; break end end
    for _, m in ipairs(MT.mine) do
        local st = m._stats
        local id = st.id.Value
        local pr = st:FindFirstChild("priority")
        local trainee = MT.trainee and st:FindFirstChild("uuid") and st.uuid.Value == MT.trainee
        local tipped = CFG.community and C.TIPS[id] and C.TIPS[id].target
        local antiAir = flyers and MT.canAir(m)
        if pr and not trainee and not tipped and not antiAir and not UNIT.isFarm(id) and not UNIT.allyBuff(id) then
            local atk = st:FindFirstChild("primary_attack") and st.primary_attack.Value or nil
            local info = UNIT.attackInfo(atk, st.range.Value)
            local heavy = info.n <= 1.4 and info.slow == 0 and info.stun == 0
            local want = (heavy and bossAlive) and "strongest" or "first"
            if pr.Value ~= want and U.now() - (MT.prioAt[m] or 0) > 8 then
                local okV, valid = pcall(C.USC.get_valid_priorities, m)
                if okV and type(valid) == "table" and valid[want] then
                    MT.prioAt[m] = U.now()
                    local ok = SF.request("prio", "change_priority", m, want)
                    if ok then
                        SF.status("Targeting", string.format("%s → %s (%s)", UNIT.name(id), want, want == "strongest" and "boss on the road" or (heavy and "no boss now" or "holds the front")))
                        SF.log(2, "TARGET", UNIT.name(id) .. " → " .. want)
                    end
                    return
                end
            end
        end
    end
end
-- --- roguelike picks (Fool's Hunt) -------------------------------
-- a Summer Hunt card: every card is worth what it pays (HUNT.cardGems) plus what it does to your strength (MT.rogueEffect, HUNT.weatherStrength). A card that weakens you is only on offer while your strength
-- stays above the floor (HUNT.floor) and nothing is pressing the defense, since a lost run loses the win's rewards. Everything offered goes to a file, because what a card pays is only known from real runs
function MT.huntChoose(opts, wave)
    MT.fhP = MT.fhP or 1
    local pmin = HUNT.floor()
    local pressed = (MT.pressure or 0) >= CFG.safeReach or (MT.depth and MT.depth.leak)
    local here = HUNT.weatherStrength(HUNT.weatherNow())
    local best, bestScore, bestP, bestG
    local offered = {}
    for i, o in pairs(opts) do
        local p, fx = 1, {}
        for _, ef in pairs(type(o) == "table" and o.effects or {}) do
            if type(ef) == "table" then
                local f = MT.rogueEffect(ef)
                p = p * f
                table.insert(fx, MT.effectText(ef))
            end
        end
        if type(o) == "table" and o.weather then p = p * HUNT.weatherStrength(o.weather) / math.max(0.05, here) end
        local gems = type(o) == "table" and HUNT.cardGems(o, wave) or 0
        local allowed = p >= 1 or (MT.fhP * p >= pmin and not pressed)
        local sc = math.log(math.max(0.05, p)) * HUNT.STRENGTH_GEMS + (allowed and gems or -1000)
        if not bestScore or sc > bestScore then best, bestScore, bestP, bestG = i, sc, p, gems end
        table.insert(offered, string.format("%s) %s%s [%s] ×%.2f, %d gems: %s", tostring(i), tostring(type(o) == "table" and o.title or "?"), (type(o) == "table" and o.weather) and (" (" .. tostring(o.weather) .. ")") or "",
            tostring(type(o) == "table" and o.option_type or "?"), p, math.floor(gems + 0.5), table.concat(fx, " + ")))
    end
    return best, bestP, bestG, offered, pmin, pressed
end
function MT.huntPick(opts)
    local wave = MT.wave()
    local best, bestP, bestG, offered, pmin, pressed = MT.huntChoose(opts, wave)
    MT.fhP = MT.fhP * (bestP or 1)
    MT.rogueOptions = nil
    local okJ, raw = pcall(Http.JSONEncode, Http, HUNT.plain(opts))
    if okJ then HUNT.write("hunt_cards.txt", string.format("%s wave %d map %s weather %s: %s", os.date("%m-%d %H:%M"), wave, tostring(MT.ld.map), tostring(HUNT.weatherNow()), raw)) end
    local ok = SF.request("rogue", "select_roguelike_option", best)
    SF.log(1, "ROGUE", string.format("wave %d · picked %s (worth %d gems, strength now ×%.2f, floor ×%.2f%s) of: %s", wave, tostring(best), math.floor((bestG or 0) + 0.5), MT.fhP, pmin, pressed and ", under pressure" or "", table.concat(offered, " | ")))
    return ok
end
-- the record of a run, and what it paid: the first runs are how the real rewards get known
function MT.huntRecord(res, pearls, won, sec)
    local pmin = HUNT.floor()
    B.hunt.pmin = U.clamp(pmin + (won and -0.1 or 0.1), 0.4, 2)
    B.hunt.runs = B.hunt.runs or {}
    table.insert(B.hunt.runs, 1, { at = os.time(), wave = MT.wave(), won = won or nil, pearls = pearls, mult = MT.fhMult or 1, strength = MT.fhP or 1, floor = pmin, map = MT.ld.map, weather = HUNT.weatherNow(), sec = sec, picks = MT.fhPicks })
    while #B.hunt.runs > 20 do table.remove(B.hunt.runs) end
    local b = HUNT.board()
    SF.log(1, "HUNT", string.format("%s at wave %d in %.0f min: +%d Summer Pearls at ×%.2f · map %s, weather %s%s", won and "won" or "lost", MT.wave(), (tonumber(sec) or 0) / 60, pearls, MT.fhMult or 1, tostring(MT.ld.map), tostring(HUNT.weatherNow()),
        b and string.format(" · bingo %d of %d squares", b.squares, #b.board) or ""))
    -- (only the reward fields: never the whole table, which could carry the player's name)
    local keep = {}
    for _, k in ipairs({ "victory", "resource_reward", "gem_reward", "new_items", "new_units", "waves_completed", "first_completion_gems", "party_bonus" }) do if type(res) == "table" then keep[k] = res[k] end end
    -- (the names of the other fields too, without their contents: a reward could sit in one not listed here)
    local fields = {}
    for k in pairs(type(res) == "table" and res or {}) do table.insert(fields, tostring(k)) end
    table.sort(fields)
    local okJ, raw = pcall(Http.JSONEncode, Http, HUNT.plain(keep))
    if okJ then HUNT.write("hunt_results.txt", os.date("%m-%d %H:%M ") .. raw .. " · fields: " .. table.concat(fields, ", ")) end
end
function MT.pickRogue()
    local opts = MT.rogueOptions
    if opts and MT.hunt then return MT.huntPick(opts) end
    if not opts then
        local ok = SF.request("rogue", "select_roguelike_option", 1)
        return ok
    end
    -- each option changes your team's strength (MT.rogueEffect: a factor, ×1.12 for +12% damage, below 1 for what
    -- helps the enemies) and the event-coin multiplier (called candy_multiplier in every roguelike event:
    -- AprilCoins here). A multiplier is taken while your strength stays at or above the learned floor
    -- (B.fh.pmin: up after a lost run, down after a won one = the highest multiplier that still wins) and nothing
    -- is pressing the defense; otherwise the option that keeps you strongest
    MT.fhP = MT.fhP or 1
    local pmin = tonumber(B.fh.pmin) or 1
    local pressed = (MT.pressure or 0) >= CFG.safeReach or (MT.depth and MT.depth.leak)
    local best, bestScore, bestP
    for i, o in pairs(opts) do
        local p, coin = 1, 0
        for _, ef in pairs(type(o) == "table" and o.effects or {}) do
            if type(ef) == "table" then local f, c = MT.rogueEffect(ef); p = p * f; coin = coin + c end
        end
        local sc = math.log(math.max(0.05, p)) * 10
        if coin > 0 and MT.fhP * p >= pmin and not pressed then sc = sc + 100 * coin
        elseif coin > 0 then sc = sc - 50 + coin end
        if not bestScore or sc > bestScore then best, bestScore, bestP = i, sc, p end
    end
    MT.fhP = MT.fhP * (bestP or 1)
    -- what was offered, for the run record (which picks the deep runs had)
    local offered = {}
    for i, o in pairs(opts) do
        local fx = {}
        for _, ef in pairs(type(o) == "table" and o.effects or {}) do if type(ef) == "table" then table.insert(fx, MT.effectText(ef)) end end
        table.insert(offered, tostring(i) .. ") " .. table.concat(fx, " + "))
    end
    MT.rogueOptions = nil
    local ok = SF.request("rogue", "select_roguelike_option", best)
    SF.log(1, "ROGUE", string.format("wave %d · picked %s (score %.1f, strength now ×%.2f, floor ×%.2f) of: %s", MT.wave(), tostring(best), bestScore or 0,
        MT.fhP, pmin, table.concat(offered, " | ")))
    return ok
end
-- your current damage share of a damage type (what an enemy resistance to it costs you; 0.5 before anything fights)
function MT.rogueShare(dtype)
    if not dtype then return 0.5 end
    local plain = tostring(dtype):gsub("_damage$", "")
    local tot, hit = 0, 0
    for _, m in ipairs(MT.mine or {}) do
        local id = m._stats.id.Value
        if not UNIT.isFarm(id) then
            local ok, v = pcall(MT.liveDps, m, id)
            v = ok and v or 0
            local types = UNIT.types(id)
            tot = tot + v
            if types[plain] or types[plain .. "_damage"] then hit = hit + v end
        end
    end
    -- (few units down yet: the dealt team is random, so it's blended with an even split until about 4 are fighting)
    local n = 0
    for _, m in ipairs(MT.mine or {}) do if not UNIT.isFarm(m._stats.id.Value) then n = n + 1 end end
    local w = n / (n + 4)
    return w * (tot > 0 and hit / tot or 0.5) + (1 - w) * 0.5
end
-- how much the enemies resist a unit's damage now (the run's enemy_resistance_specific effects; 0 = none)
function MT.resistOf(id)
    local types = UNIT.types(id)
    local r = 0
    for dtype, a in pairs(MT.fhResist or {}) do
        local plain = tostring(dtype):gsub("_damage$", "")
        if types[plain] or types[plain .. "_damage"] then r = math.max(r, a / 100) end
    end
    return math.min(0.95, r)
end
-- what one roguelike effect does: a strength factor for your team, and the coin multiplier it adds
function MT.rogueEffect(ef)
    local t, a, stat = ef.type, tonumber(ef.amount) or 0, tostring(ef.stat or "")
    if t == "candy_multiplier" then return 1, math.abs(a) end
    if t == "stat_mul" or t == "stat_add" or t == "stat_attr_add" then
        if stat == "damage" then return math.max(0.3, 1 + a), 0 end
        if stat == "range" then return math.max(0.5, 1 + a / 2), 0 end
        if stat:find("cooldown") then return 1 / math.max(0.3, 1 + a), 0 end
        return 1, 0
    end
    if t == "stat_mul_real" then
        if stat == "damage" then return math.max(0.3, a), 0 end
        if stat == "range" then return math.max(0.5, 1 + (a - 1) / 2), 0 end
        if stat:find("cooldown") then return 1 / math.max(0.3, a), 0 end
        return 1, 0
    end
    if t == "boss_damage" then return 1 + a / 3, 0 end
    if t == "enemy_stat_mul" then return 1 / math.max(0.3, 1 + a), 0 end
    if t == "enemy_resistance_specific" then return math.max(0.2, 1 - MT.rogueShare(ef.damage_type) * (1 - 100 / (100 + a))), 0 end
    if t == "enemy_amp_specific" then return 1 + MT.rogueShare(ef.damage_type) * a, 0 end
    if t == "weather_flying_chance" then return math.max(0.5, 1 - a * 0.5), 0 end
    if t == "weather_soaring_share" then return math.max(0.5, 1 - a * 0.2), 0 end
    if t == "flying_damage" then return 1 + a * 0.1, 0 end
    if t == "burst_speed" then return 1 / math.max(0.3, 1 + a * 0.5), 0 end
    if t == "lightning_strikes" then return math.max(0.5, 1 - a * 0.1), 0 end
    if t == "enemy_speedup" then return 1 / math.max(0.3, 1 + a), 0 end
    if t == "enemy_regen" then return math.max(0.3, 1 - a * 20), 0 end
    if t == "enemy_shield" then return math.max(0.5, 1 - a * 0.03), 0 end
    if t == "enemy_bomb" then return 0.95, 0 end
    if t == "enemy_passive_chance" then return math.max(0.5, 1 - a), 0 end
    if t == "resource_gain" then return 1 + math.min(0.3, a / 40000), 0 end
    if t == "unit_cost" then return 1 / math.max(0.3, 1 + a / 2), 0 end
    if t == "new_path" then return 0.8, 0 end
    -- "Gain 2 random tier 1 curses": each curse about −20% (more for a higher tier) — a wave-22 loss showed how much
    -- they stack up (enemy resistance +125, speed +50%); blessings the other way
    if t == "random_effects" then
        local n = math.max(1, math.abs(a)) * math.max(1, math.abs(tonumber(ef.tier) or 1))
        return ef._type == "Good" and 1.1 ^ n or 0.8 ^ n, 0
    end
    return 1, 0
end
-- a roguelike effect in a few words: "candy_multiplier 0.3", "enemy_regen 0.005", "stat_mul.damage 0.2"
function MT.effectText(ef)
    return string.format("%s%s %s", tostring(ef.type), ef.stat and ("." .. tostring(ef.stat)) or "", tostring(ef.amount))
end
-- --- end of a run ------------------------------------------------
function MT.learn()
    -- measured damage share vs the share the formula predicts, per unit kind: capped nudge, rate decays
    local dealt, pred = {}, {}
    local sumD, sumP = 0, 0
    for _, m in ipairs(MT.mine) do
        local st = m._stats
        local id = st.id.Value
        local d = st:FindFirstChild("total_damage") and st.total_damage.Value or 0
        if not UNIT.isFarm(id) then
            dealt[id] = (dealt[id] or 0) + d
            pred[id] = (pred[id] or 0) + MT.liveDps(m, id) / math.max(0.5, UNIT.nudge(id))
            -- (Chuuni's marks tick into her total too, and the simulator plays them on their own)
            local mk = UNIT.passive(id).mark
            if mk then pred[id] = pred[id] + mk.dot * st.damage.Value end
            sumD = sumD + d
        end
    end
    for _, v in pairs(pred) do sumP = sumP + v end
    if sumD <= 0 or sumP <= 0 then return end
    -- (this match's own reading per unit goes in its brain hive record too: REPORT.match)
    MT.lastEff = {}
    for id, d in pairs(dealt) do
        local share, pshare = d / sumD, pred[id] / sumP
        if pshare > 0.02 then
            local l = B.learn[id] or { eff = 1, n = 0 }
            local rate = math.max(0.02, 0.25 * math.sqrt(30 / (30 + l.n)))
            local obs = U.clamp(share / pshare, 0.3, 3)
            MT.lastEff[id] = math.floor(obs * 1000 + 0.5) / 1000
            l.eff = l.eff + (obs - l.eff) * rate
            l.n = l.n + 1
            B.learn[id] = l
        end
    end
end
-- a mode that deals its own team (Fool's Hunt, _randomequippedmode): the game keeps dealing units into a hand
-- (session.override_equipped_units, the units themselves in collection.temporary_units); each dealt unit is placed
-- once and leaves the hand. The farm's team = the hand (to place) + the dealt units on the field (to upgrade)
function MT.randomTeam()
    local s = C.session()
    local tu = s and s.collection.temporary_units or {}
    local out, seen = {}, {}
    local function add(uuid, hand, slot)
        local u = uuid and tu[uuid]
        if u and C.Units[u.unit_id] and not seen[uuid] then
            seen[uuid] = true
            table.insert(out, { slot = slot or 99, uuid = uuid, u = u, id = u.unit_id, data = C.Units[u.unit_id], hand = hand })
        end
    end
    for slot, uuid in pairs(s and s.override_equipped_units or {}) do add(uuid, true, tonumber(slot)) end
    for _, m in ipairs(MT.mine or {}) do
        local st = m._stats
        add(st:FindFirstChild("uuid") and st.uuid.Value, false)
    end
    table.sort(out, function(a, b) return a.slot < b.slot end)
    return out
end
-- per-wave snapshot of a dealt-team run, to find what loses it: "wave:base%:alive:nearBase:teamDps:units:mult",
-- and at the first wave the base takes damage, which enemies were near it (MT.fhLeak)
function MT.fhSnap()
    local base, maxB = nil, nil
    pcall(function()
        for _, b in ipairs(workspace._BASES:GetDescendants()) do if b:IsA("Humanoid") then base, maxB = b.Health, b.MaxHealth; break end end
    end)
    local pct = base and maxB and maxB > 0 and math.floor(base / maxB * 100) or -1
    local near, ids, all = 0, {}, {}
    for _, e in ipairs(MT.enemies or {}) do
        if (e.prog or 0) > 0.8 then near = near + 1; ids[tostring(e.m)] = (ids[tostring(e.m)] or 0) + 1 end
        all[tostring(e.m)] = (all[tostring(e.m)] or 0) + 1
    end
    if not next(ids) then ids = all end -- (what reached the base may be gone already: then everything alive)
    local dps = 0
    for _, m in ipairs(MT.mine or {}) do local ok, v = pcall(MT.liveDps, m, m._stats.id.Value); if ok and v then dps = dps + v end end
    MT.fhWaves = MT.fhWaves or {}
    local fly = 0
    for _, e in ipairs(MT.enemies or {}) do if e.fly then fly = fly + 1 end end
    table.insert(MT.fhWaves, string.format("%d:%d:%d:%d:%s:%d:%.2f:%s:air%d%%:fly%d", MT.wave(), pct, #(MT.enemies or {}), near, U.fmt(dps), MT.fieldCount(),
        MT.fhMult or 1, U.fmt(MT.money()), math.floor(MT.airShare() * 100 + 0.5), fly))
    if pct >= 0 and MT.fhLastPct and pct < MT.fhLastPct and not MT.fhLeak then
        local l = {}
        for id, n in pairs(ids) do table.insert(l, UNIT.name(id) .. "×" .. n) end
        MT.fhLeak = string.format("wave %d: base %d%% → %d%%, near it: %s", MT.wave(), MT.fhLastPct, pct, #l > 0 and table.concat(l, ", ") or "nothing seen")
        SF.log(1, "MATCH", "first damage to the base — " .. MT.fhLeak)
    end
    MT.fhLastPct = pct
end
-- a dealt-team run's record (what the mode teaches): wave reached, coins, and each dealt unit's share of the
-- damage (the units that carry get placed and kept first next time: MT.carry)
function MT.fhRecord(coins, won)
    local dealt, total = {}, 0
    for _, m in ipairs(MT.mine or {}) do
        local st = m._stats
        local d = st:FindFirstChild("total_damage") and tonumber(st.total_damage.Value) or 0
        local id = st.id.Value
        if d > 0 then dealt[id] = (dealt[id] or 0) + d; total = total + d end
    end
    local top = {}
    for id, d in pairs(dealt) do
        local share = total > 0 and d / total or 0
        local u = B.fh.units[id] or { n = 0, share = 0 }
        u.share = (u.share * u.n + share) / (u.n + 1)
        u.n = u.n + 1
        B.fh.units[id] = u
        table.insert(top, { id = id, share = share })
    end
    table.sort(top, function(a, b) return a.share > b.share end)
    local names = {}
    for i = 1, math.min(4, #top) do table.insert(names, string.format("%s %d%%", UNIT.name(top[i].id), math.floor(top[i].share * 100 + 0.5))) end
    pcall(MT.fhSnap)
    -- the strength floor for coin multipliers: a lost run plays safer next time, a won one takes more
    local pmin = tonumber(B.fh.pmin) or 1
    B.fh.pmin = U.clamp(pmin * (won and 0.9 or 1.1), 0.5, 2.5)
    table.insert(B.fh.runs, 1, { at = os.time(), wave = MT.wave(), won = won or nil, coins = coins, top = names, mult = MT.fhMult or 1, discards = MT.discards,
        strength = MT.fhP, floor = pmin, effects = MT.fhEffects, picks = MT.fhPicks, leak = MT.fhLeak, waves = MT.fhWaves })
    while #B.fh.runs > 20 do table.remove(B.fh.runs) end
    SF.log(1, "RESULT", string.format("dealt team reached wave %d; most damage: %s", MT.wave(), table.concat(names, ", ")))
end
-- how much a dealt unit carried in past runs (its average damage share; 0 when unseen)
function MT.carry(id) local u = B.fh.units[id]; return u and u.n > 0 and u.share or 0 end
-- the Path tab's Fool's Hunt paragraph
function MT.fhText()
    local runs = B.fh.runs
    if #runs == 0 then return "No Fool's Hunt run recorded yet." end
    local w, c = 0, 0
    for _, r in ipairs(runs) do w = w + (r.wave or 0); c = c + (r.coins or 0) end
    local best = {}
    for id, u in pairs(B.fh.units) do if u.n >= 2 then table.insert(best, { id = id, share = u.share, n = u.n }) end end
    table.sort(best, function(a, b) return a.share > b.share end)
    local names = {}
    for i = 1, math.min(6, #best) do table.insert(names, string.format("%s %d%% (%d runs)", UNIT.name(best[i].id), math.floor(best[i].share * 100 + 0.5), best[i].n)) end
    local learned = 0
    for _ in pairs(B.unitData) do learned = learned + 1 end
    local wins = 0
    for _, r in ipairs(runs) do if r.won then wins = wins + 1 end end
    local r1 = runs[1]
    local mg, idol = B.fh.merge, B.fh.idol
    local extra = ""
    if mg and mg.n > 0 then extra = extra .. string.format("\nMerges cast: %d, each gave %.0f%% of what the game's description promises.", mg.n, mg.ratio / mg.n * 100) end
    if idol and idol.n > 0 then extra = extra .. string.format("\nIdol: each upgrade adds %.1f%% damage and makes upgrades %.1f%% cheaper (measured %d times).", idol.dmg / idol.n * 100, idol.cost / idol.n * 100, idol.n) end
    local cl, rt = B.fh.clone, B.fh.ritual
    if cl and cl.n > 0 then extra = extra .. string.format("\nClones: %d made, each with %.0f%% of the original's damage and %.0f%% of the yen in it.", cl.n, cl.ratio / cl.n * 100, cl.spent / cl.n * 100) end
    if rt and rt.n > 0 then extra = extra .. string.format("\nRitual: %d cast, the Divine General came out at %.1f× the sacrificed unit's damage.", rt.n, rt.ratio / rt.n) end
    local fm = B.fh.farmMerge
    if fm and fm.n > 0 then extra = extra .. string.format("\nFarm merges: %d tested, each kept %.0f%% of 1.5× the income it took in.", fm.n, fm.ratio / fm.n * 100) end
    return string.format("Fool's Hunt: %d runs recorded (%d won), wave %.0f and %d AprilCoins a run on average. Last run: wave %s, coin multiplier ×%.2f, team strength ×%.2f%s; most damage: %s.\n"
        .. "Coin-multiplier picks need team strength ×%.2f or more (it goes up after a lost run, down after a won one, until it wins with the highest multiplier).\n"
        .. "Dealt units that carry (average share of the damage): %s.\nHidden unit stats learned so far: %d units.%s",
        #runs, wins, w / #runs, math.floor(c / #runs + 0.5), tostring(r1.wave), tonumber(r1.mult) or 1, tonumber(r1.strength) or 1,
        r1.leak and (" · first base hit: " .. r1.leak) or "", table.concat(r1.top or {}, ", "),
        tonumber(B.fh.pmin) or 1, #names > 0 and table.concat(names, " · ") or "needs 2 runs with a unit", learned, extra)
end
-- a hand card's worth: its damage at level 0 (a buffer: the damage its buff adds), more for a unit that carried past
-- runs, less when the enemies resist its damage type (farm cards: 0, they're kept by their own rule)
-- a card's damage at level 0. A unit with no regular attack (Arlem: attack cooldown 0, its damage comes from its Titan
-- Shift ability — 41% of a run's damage) gets 0 from the formula and was never placed: it counts as this run's
-- typical card (the fishing bar's level), its past runs' share on top (MT.carry)
function MT.cardDps(e)
    local ok, v = pcall(UNIT.dps, e.u, 0, MT.mod)
    v = ok and tonumber(v) or 0
    if v > 0 or UNIT.isFarm(e.id) or UNIT.idol(e.id) or UNIT.allyBuff(e.id) then return v end
    local s = table.clone(MT.cardVals or {})
    if #s == 0 then return 1000 end
    table.sort(s)
    return s[math.max(1, math.ceil(#s * 0.6))]
end
function MT.cardValue(e)
    if UNIT.isFarm(e.id) then return 0 end
    if UNIT.idol(e.id) then return (MT.teamDps or 0) * MT.idolStep() * 3 end
    local v = UNIT.allyBuff(e.id) and MT.buffGain(e) or MT.cardDps(e)
    -- (a copy of a unit the farm grows by Merge is worth double: MT.mergeScan)
    return v * (1 + 2 * MT.carry(e.id)) * (1 - MT.resistOf(e.id)) * MT.airNeed(e.id) * (MT.mergeIds[e.id] and 2 or 1)
end
-- units that hit flyers (hill / hybrid units, anti-air attacks) hit the ground too, and flyers (from wave 10) ended
-- most lost runs (one put all 4 Random Buffs and its Clone and Merge plans on ground-only Tango and Sepsis and died
-- to Winged Demons at wave 17). So in a dealt-team run they count ×1.5 everywhere — placing, fishing, upgrades,
-- Random Buff, Clone, the Merge plan — and ×2.5 while under half your damage can hit flyers (the user's call:
-- "prioritize air or hybrid units"). Your own team's modes do the same (upgrades and new copies) once flyers come:
-- seen in this match, or a dungeon run that carries the Curse of Flight (+20% flyers)
function MT.flyMode()
    if MT.random or MT.flyerSeen then return true end
    if MT.kind == "dungeon" then
        if MT._curseFly == nil then
            local okI, items = pcall(DG.items, DG.data())
            MT._curseFly = okI and (items._curse_fly or 0) > 0 or false
        end
        return MT._curseFly
    end
    return false
end
-- the shields on the way this wave (hits an enemy's shield takes, on average) and the HP behind them
function MT.shieldNow()
    local w = MT.wave()
    if MT._shieldW ~= w then
        MT._shieldW, MT._shieldS, MT._shieldH = w, 0, 1
        local okW, list = pcall(SIM.wave, MT.info, math.max(1, w), true)
        if MT.info and okW and #list > 0 then
            local s, h = 0, 0
            for _, e in ipairs(list) do s, h = s + (e.sh or 0), h + e.hp end
            MT._shieldS, MT._shieldH = s / #list, h / #list
        end
    end
    return MT._shieldS, MT._shieldH
end
-- a unit's real damage against those shields (ECON.shieldDps), from its damage and cooldown at that level
function MT.shieldOf(dps, r)
    local S, H = MT.shieldNow()
    if S <= 0 or not r then return dps end
    local ai = UNIT.attackInfo(r.atk, r.range)
    return ECON.shieldDps(dps, tonumber(r.cd) or 2, ai.n, S, H, MT.info and MT.info.eff, ai.hits)
end
-- what a new copy is worth for the shield hits it lands (ECON.shieldWork): your hardest hitter, your hits a second so far
function MT.shieldWork(id, r)
    local S, H = MT.shieldNow()
    if S <= 0 or not r or not MT.info then return 0 end
    local heavy, rate = 0, 0
    for _, e in ipairs(MT.team or {}) do
        local r0 = UNIT.rows(e.id)
        r0 = r0 and r0[0]
        if r0 and not UNIT.isFarm(e.id) then
            heavy = math.max(heavy, UNIT.dps(e.u, 0, MT.mod) * (tonumber(r0.cd) or 2) / math.max(1, UNIT.attackInfo(r0.atk, r0.range).n))
        end
    end
    for _, m in ipairs(MT.mine or {}) do
        local mid = m._stats.id.Value
        local rows = UNIT.rows(mid)
        local rl = rows and rows[m._stats.upgrade and m._stats.upgrade.Value or 0]
        if rl and not UNIT.isFarm(mid) and not UNIT.allyBuff(mid) then
            local il = UNIT.attackInfo(rl.atk, rl.range)
            rate = rate + il.n * il.hits / math.max(0.3, tonumber(rl.cd) or 2)
        end
    end
    local okW, list = pcall(SIM.wave, MT.info, math.max(1, MT.wave()), true)
    local ai = UNIT.attackInfo(r.atk, r.range)
    return ECON.shieldWork(ai.n, tonumber(r.cd) or 2, rate, S, okW and #list or 1, MT.info.waveSec, heavy * (MT.info.eff or 1), H, ai.hits)
end
-- the same for the whole team: its damage so far, once the shields have taken their hits
function MT.teamShield()
    if MT._shieldAt and U.now() - MT._shieldAt < 2 then return MT._shieldTeam end
    local tot, left = 0, 0
    for _, m in ipairs(MT.mine or {}) do
        local id = m._stats.id.Value
        if not UNIT.isFarm(id) and m._stats:FindFirstChild("upgrade") then
            local rows = UNIT.rows(id)
            local okD, v = pcall(MT.liveDps, m, id)
            if okD and rows then
                tot = tot + v
                left = left + MT.shieldOf(v, rows[m._stats.upgrade.Value])
            end
        end
    end
    MT._shieldTeam, MT._shieldAt = tot > 0 and math.max(0.05, left / tot) or 1, U.now()
    return MT._shieldTeam
end
function MT.airLow()
    if not MT.flyMode() then return false end
    if HUB.every("airShare", 1) or not MT.airShareNow then MT.airShareNow = MT.airShare() end
    return MT.airShareNow < 0.5
end
function MT.airWeight(isAir)
    if not (isAir and MT.flyMode()) then return 1 end
    return MT.airLow() and 2.5 or 1.5
end
-- how much road a placed unit reaches, against your other attackers' average (×0.4 to ×1.6): a boss walks past a
-- short-range unit in a moment — Captain (God), range 10 at every level, was cloned, merged to 524k and Random-Buffed
-- on wave 30 and hit the boss twice (the user); the Merge carry, Random Buff, Clone and upgrades weigh it — and, in
-- every mode since v1.5, which upgrade the yen goes to
function MT.reach(m)
    if not MT.reachAt or U.now() - MT.reachAt > 5 then
        local sum, n = 0, 0
        for _, o in ipairs(MT.mine or {}) do
            local st = o._stats
            if not UNIT.isFarm(st.id.Value) and st:FindFirstChild("range") then sum, n = sum + MT.cover(o:GetPivot().Position, st.range.Value), n + 1 end
        end
        MT.reachAvg, MT.reachAt = n > 0 and sum / n or 0, U.now()
    end
    local st = m._stats
    if (MT.reachAvg or 0) <= 0 or not st:FindFirstChild("range") then return 1 end
    local c = MT.reachCache[m]
    if c and U.now() - c.t < 5 then return c.v end
    local v = U.clamp(MT.cover(m:GetPivot().Position, st.range.Value) / MT.reachAvg, 0.4, 1.6)
    MT.reachCache[m] = { v = v, t = U.now() }
    return v
end
MT.reachCache = setmetatable({}, { __mode = "k" })
-- a card that hits flyers only after some upgrades counts 40% of the extra weight
function MT.airNeed(id)
    local from = UNIT.airFrom(id)
    if from == 0 then return MT.airWeight(true) end
    if from then return 1 + (MT.airWeight(true) - 1) * 0.4 end
    return 1
end
-- a placed unit that will hit flyers from upgrade L gets more of the weight the closer it is: full on the upgrade
-- that unlocks it
function MT.airBoost(m)
    if MT.canAir(m) then return MT.airWeight(true) end
    local from = UNIT.airFrom(m._stats.id.Value)
    if not from then return 1 end
    return 1 + (MT.airWeight(true) - 1) * math.min(1, (m._stats.upgrade.Value + 1) / math.max(1, from))
end
-- card fishing: ✖ on a hand card is free and a new card fills the slot about 2 s later (tested), so weak cards
-- are discarded to fish for strong ones. Once 8 cards are seen, a unit card below the 60th percentile of this run's
-- cards goes (one every 5 s) — except up to 3 farm cards before wave 12 (the yen) and the card a full field saves for
MT.cardSeen, MT.cardVals = {}, {}
function MT.fish()
    if not MT.random then return end
    local hand = {}
    for _, e in ipairs(MT.team) do
        if e.hand then
            table.insert(hand, e)
            if not MT.cardSeen[e.uuid] then
                MT.cardSeen[e.uuid] = U.now() -- (when it was dealt: a card left unplaced for a minute is stale)
                if not UNIT.isFarm(e.id) and not UNIT.idol(e.id) then table.insert(MT.cardVals, MT.cardValue(e)) end
            end
        end
    end
    if #MT.cardVals < 8 or not HUB.every("fish", 5) then return end
    local sorted = table.clone(MT.cardVals)
    table.sort(sorted)
    local bar = sorted[math.max(1, math.ceil(#sorted * 0.6))]
    local farms = 0
    for _, m in ipairs(MT.mine or {}) do if UNIT.isFarm(m._stats.id.Value) then farms = farms + 1 end end
    -- (a field with free slots needs every unit it can get: until 16 of the 20 are taken only a near-worthless card
    -- goes — runs that discarded freely stalled at 6–11 units with yen unspent and 20+ enemies on the road)
    local thin = MT.fieldCount() < 16
    -- (one farm card waits in the hand at a time: a hand held Bulby and 2 C.E.O.s while the defense needed damage)
    local farmKept = false
    for _, e in ipairs(hand) do
        local keepFarm = UNIT.isFarm(e.id) and MT.wave() < 12 and farms < 3 and not farmKept
        if keepFarm then farmKept = true end
        local saving = MT.roomPlan and MT.roomPlan.name == UNIT.name(e.id)
        -- (kept too: an Idol, and a copy of a unit the farm grows by Merge — but never a card with no spot it fits:
        -- an Idol, radius 5, found none on a crowded map and sat in the hand from wave 14 to the end)
        local unplaceable = (MT.noSpot[e.uuid] or 0) >= 3
        local keep = not unplaceable and (keepFarm or saving or UNIT.idol(e.id) or MT.mergeIds[e.id])
        -- a card the economy left unplaced for over a minute is held to the full bar even on a thin field: six weak
        -- cards sat in the hand from wave 13 to 19 with 11 units placed, and no spell card could come in
        local stale = U.now() - (tonumber(MT.cardSeen[e.uuid]) or U.now()) > 60
        if unplaceable or (not keep and MT.cardValue(e) < bar * ((thin and not stale) and 0.25 or 1)) then
            if MT.discardCard(e) then
                SF.log(2, "PLACE", string.format("discarded %s (%s) for a new card", UNIT.name(e.id), unplaceable and "no spot it fits" or ("worth " .. U.fmt(MT.cardValue(e)) .. ", the bar is " .. U.fmt(bar))))
                MT.discards = (MT.discards or 0) + 1
            end
            return
        end
    end
end
-- ✖ on a hand unit card: the game's button sends the card's slot key ("1"–"6"), not its uuid — a uuid is ignored
-- without an error (one run counted 35 "discards" that did nothing and the hand clogged with 3 weak Captain Magmas).
-- True once the card has really left its slot (a new card fills it ~2 s later)
function MT.discardCard(e)
    local key = tostring(e.slot)
    local hand = C.session().override_equipped_units or {}
    if hand[key] ~= e.uuid then return false end
    if not SF.request("discard", "delete_ingame_temporary_unit", key) then return false end
    task.wait(0.3)
    local gone = (C.session().override_equipped_units or {})[key] ~= e.uuid
    if not gone and HUB.every("discardFail", 30) then SF.log(1, "PLACE", "the game didn't take the discard of " .. UNIT.name(e.id)) end
    return gone
end
-- a log line every 45 s in a dealt-team run, to catch what goes wrong while it plays: wave, field, yen, the hand
-- (unit cards with their worth, spells), the Merge plan and the economy's choice — flagged when the same unit cards
-- have sat in the hand for 90 s
function MT.watchLine()
    local s = C.session()
    local cards, sig = {}, {}
    for _, e in ipairs(MT.team or {}) do
        if e.hand then
            table.insert(cards, UNIT.name(e.id) .. " " .. U.fmt(MT.cardValue(e)))
            table.insert(sig, e.uuid)
        end
    end
    local spells = {}
    for _, sp in pairs((s and s.ingame_spells) or {}) do table.insert(spells, MT.SPELL_NAMES[sp] or tostring(sp)) end
    local key = table.concat(sig, ",")
    if key ~= MT.handKey then MT.handKey, MT.handSince = key, U.now() end
    local stuck = #sig > 0 and U.now() - MT.handSince >= 90
    SF.log(1, "WATCH", string.format("wave %d · %d/%d units · ¥%s · hand: %s%s · merge: %s%s · economy: %s%s",
        MT.wave(), MT.fieldCount(), MT.FIELD_MAX, U.fmt(MT.money()), #cards > 0 and table.concat(cards, ", ") or "no unit cards",
        #spells > 0 and (" + " .. table.concat(spells, ", ")) or "", tostring(ST.Merge or "-"), MT.cloneNote and (" · clone: " .. MT.cloneNote) or "",
        tostring(ST.Economy or "-"), stuck and " · HAND STUCK 90s+" or ""))
end
-- the field holds at most 20 units (the game: "Cannot place more than 20 units! Sell some weaker ones to make room")
MT.FIELD_MAX = 20
MT.SPELL_NAMES = { sell_refund = "Refund", sacrifice = "Merge", clone = "Clone", random_buff = "Random Buff", summon = "Astral Summon", gate = "Astral Gate", ritual = "Ritual" }
MT.SPELL_ORDER = { random_buff = 1, clone = 2, sacrifice = 3, ritual = 4, summon = 5, gate = 6 }
MT.buffCount = setmetatable({}, { __mode = "k" }) -- placed unit → Random Buffs it got
-- Astral Summon (¥10,000: one of your own equipped units into the slot) is worth it while your units' average damage
-- at level 0 (farms count 0; ×2 for the traits and upgrades it brings) beats what the same yen plus its placement
-- buys in the best upgrade now. Otherwise the card goes, and Astral Gate (which only makes Summons likelier) with it.
-- (Oct 30, wave 11: your units 3.8k, ¥10k in upgrades 17k → not worth it)
function MT.summonWorth()
    if MT.summonAvg == nil then
        local sum, n, cost = 0, 0, 0
        for _, e in ipairs(UNIT.equipped()) do
            local ok, d = pcall(UNIT.dps, e.u, 0, MT.mod)
            sum, n, cost = sum + ((not UNIT.isFarm(e.id) and ok and d) or 0), n + 1, cost + (e.data.cost or 0)
        end
        MT.summonAvg, MT.summonCost = n > 0 and sum / n or 0, n > 0 and cost / n or 0
    end
    local rate = MT.bestRate or 0
    return rate <= 0 or MT.summonAvg * 2 >= rate * (10000 + MT.summonCost)
end
-- Ritual (¥10,000, rare: "Sacrifices the selected Unit to summon Holy Warlord. Stats will depend on the selected
-- Unit"): untested, so the first two go on a mid unit (the 3rd strongest attacker outside the Merge plan) and get
-- measured (B.fh.ritual: Holy Warlord's damage ÷ the unit's). At 1.5× or more it goes on the strongest attacker
-- outside the plan; below that the card is discarded
function MT.hasGeneral()
    for _, m in ipairs(MT.mine or {}) do if m._stats.id.Value == "mahoraga" then return true end end
    return false
end
function MT.ritualWorth()
    local r = B.fh.ritual
    return r and r.n >= 2 and r.ratio / r.n or nil
end
function MT.ritualTarget()
    local plan = MT.mergePlan
    local list = {}
    for _, m in ipairs(MT.mine) do
        local id = m._stats.id.Value
        -- (and not a unit that hits flyers while few do: the first test would have taken Gravity (Sage))
        if not UNIT.isFarm(id) and not UNIT.allyBuff(id) and not UNIT.idol(id) and not (plan and plan.id == id) and not (MT.airLow() and MT.canAir(m)) then
            local okD, v = pcall(MT.liveDps, m, id)
            if okD and v and v > 0 then table.insert(list, { m = m, dps = v }) end
        end
    end
    if #list < 3 then return nil end
    table.sort(list, function(a, b) return a.dps > b.dps end)
    local worth = MT.ritualWorth()
    if not worth then return list[3].m, "a test: how strong the Divine General comes out of this unit" end
    if worth >= 1.5 then return list[1].m, string.format("the Divine General came out at %.1f× the unit's damage before", worth) end
    return nil
end
-- the Divine General (the Ritual's unit) asks for one of three adaptations every 50 takedowns (the user's guide
-- notes): Divine Wings first (it then hits flyers), then Adapted Slash, then Heavenly Force. The prompt's own buttons
-- are pressed (their click handlers fired), so the game sends whatever it sends for a real click
-- (the prompt: SpecialActiveControllers' copy of the "Mahoraga" controller — the one under a Configuration is the
-- hidden template; each option is a Frame with an ImageButton and a "Mode" label: "Divine Wings"…)
MT.ADAPT_ORDER = { "Divine Wings", "Adapted Slash", "Heavenly Force" }
function MT.adapt()
    if not getconnections then return end
    local general = false
    for _, m in ipairs(MT.mine or {}) do if m._stats.id.Value == "mahoraga" then general = true; break end end
    if not general then return end
    if not (MT.adaptPrompt and MT.adaptPrompt.Parent) then
        MT.adaptPrompt = nil
        local pg = LP:FindFirstChild("PlayerGui")
        for _, d in ipairs(pg and pg:GetDescendants() or {}) do
            if d.Name == "MahoragaAdaptationPrompt" and not d:FindFirstAncestorOfClass("Configuration") then MT.adaptPrompt = d; break end
        end
    end
    local p = MT.adaptPrompt
    if not (p and p:IsA("GuiObject") and p.Visible) then MT.adaptTries = 0; return end
    MT.adaptTries = (MT.adaptTries or 0) + 1
    if MT.adaptTries > 3 then return end -- (clicks that didn't take: no spamming)
    local options = {}
    for _, d in ipairs(p:GetDescendants()) do
        if d:IsA("TextLabel") and d.Name == "Mode" and d.Parent then options[d.Text] = d.Parent end
    end
    for _, name in ipairs(MT.ADAPT_ORDER) do
        local fr = options[name]
        local b = fr and (fr:IsA("GuiButton") and fr or fr:FindFirstChildWhichIsA("GuiButton", true))
        if b and fr.Visible then
            local fired = 0
            for _, sig in ipairs({ b.Activated, b.MouseButton1Click, b.MouseButton1Down }) do
                for _, c in ipairs(getconnections(sig)) do if pcall(function() c:Fire() end) then fired = fired + 1 end end
            end
            SF.log(1, "SPELL", string.format("Divine General adapts: %s (%d click handler%s, try %d)", name, fired, fired == 1 and "" or "s", MT.adaptTries))
            return
        end
    end
end
-- what a Clone or Ritual made: the new unit's damage, level and yen against the unit it came from (B.fh.clone: does
-- a clone carry a Merge's gain, and the yen a Refund would give back; B.fh.ritual: Holy Warlord ÷ the unit)
function MT.newUnitMeasure(spell, target, name, was, before)
    -- (looked for once a second for 10 s: the Divine General appears later than 2.5 s and the first Ritual went
    -- unmeasured)
    task.spawn(function()
        local new
        for _ = 1, 10 do
            task.wait(1)
            for _, m in ipairs(workspace._UNITS:GetChildren()) do
                local st = m:FindFirstChild("_stats")
                if not before[m] and st and st:FindFirstChild("player") and st.player.Value == LP and st:FindFirstChild("damage")
                    and (spell == "ritual" or st.id.Value == was.id) then new = m; break end
            end
            if new then task.wait(1); break end
        end
        if not new then SF.log(2, "SPELL", (MT.SPELL_NAMES[spell] or spell) .. ": couldn't find the new unit to measure"); return end
        local st = new._stats
        local okD, dps = pcall(MT.liveDps, new, st.id.Value)
        dps = okD and tonumber(dps) or 0
        local spent = st:FindFirstChild("total_spent") and tonumber(st.total_spent.Value) or 0
        local r = B.fh[spell] or { n = 0, ratio = 0, spent = 0 }
        if was.dps > 0 then r.n, r.ratio, r.spent = r.n + 1, r.ratio + dps / was.dps, r.spent + (was.spent > 0 and spent / was.spent or 0) end
        B.fh[spell] = r
        SF.log(1, "SPELL", string.format("%s result: %s at level %s does %s damage a second (%s had %s at level %d) · ¥%s in it (%s had ¥%s) · %.0f studs away",
            MT.SPELL_NAMES[spell] or spell, UNIT.name(st.id.Value), tostring(st:FindFirstChild("upgrade") and st.upgrade.Value or "?"), U.fmt(dps), name, U.fmt(was.dps), was.lvl,
            U.fmt(spent), name, U.fmt(was.spent), (U.flat(new:GetPivot().Position) - U.flat(was.pos)).Magnitude))
    end)
end
function MT.fieldCount()
    local n = 0
    for _, m in ipairs(MT.mine or {}) do
        local d = C.Units[m._stats.id.Value]
        if d and (tonumber(d.cost) or 0) > 0 then n = n + 1 end -- (summons a unit spawns don't count)
    end
    return n
end
-- a full field in a dealt-team mode: sell your weakest unit for a hand unit at least 2× stronger (a free Refund
-- spell when you have one; a farm counts as the pay it still has coming), else discard
-- the hand unit with the card's ✖ so a new card comes (delete_ingame_temporary_unit)
function MT.makeRoom()
    local s = C.session()
    if not (MT.random and s) or MT.spellBusy then return end
    -- spell cards share the hand's 6 slots with unit cards: one of each kind stays (two Merges while there's a Merge
    -- plan), the rest go with ✖ so new cards come — 3 Refunds held at once left 2 slots for units; a Ritual goes too
    -- once Holy Warlord measured under 1.5× (MT.ritualTarget)
    local held = {}
    for slot, spell in pairs(s.ingame_spells or {}) do
        held[spell] = (held[spell] or 0) + 1
        local worth = MT.ritualWorth()
        local keep = spell == "ritual" and ((worth and worth < 1.5) and 0 or 1) or (spell == "sacrifice" and MT.mergePlan) and 2 or 1
        if (spell == "summon" or spell == "gate") and not MT.summonWorth() then keep = 0 end
        -- only one Divine General at a time and it never dies (the user): with one on the field a Ritual is dead weight
        if spell == "ritual" and MT.hasGeneral() then keep = 0 end
        -- a Refund goes before wave 22 unless the field is nearly full: its main use (farms that won't pay back) comes
        -- late, and held from wave 7 it kept a slot from the rare Clone the Merge loop needs (match 7)
        if spell == "sell_refund" and MT.wave() < 22 and MT.fieldCount() < 18 then keep = 0 end
        if held[spell] > keep then
            if SF.request("discard", "delete_ingame_spell", slot) and (task.wait(0.3) and (C.session().ingame_spells or {})[slot] ~= spell) then
                local reason = keep > 0 and "one is enough in the hand" or spell == "ritual" and (MT.hasGeneral() and "a Divine General is already on the field" or "the Divine General came out too weak")
                    or spell == "sell_refund" and "Refund is for late waves" or "not worth its price now"
                SF.log(1, "SPELL", string.format("discarded %s (%s) for a new card", MT.SPELL_NAMES[spell] or tostring(spell), reason))
            end
            return
        end
    end
    if MT.fieldCount() < MT.FIELD_MAX or U.now() - (MT.roomSoldAt or -99) < 15 then return end
    local bestHand, bestDps
    for _, e in ipairs(MT.team) do
        -- (not a card with no spot it fits: a run sold Cursed Lord at wave 23 for an Idol that couldn't be placed)
        if e.hand and not UNIT.isFarm(e.id) and (MT.noSpot[e.uuid] or 0) < 3 then
            local v = MT.cardValue(e)
            if not bestDps or v > bestDps then bestHand, bestDps = e, v end
        end
    end
    -- a farm is worth the pay it still has coming, as damage at the best upgrade rate (it used to count as nothing
    -- once ¥10k piled up: a run sold 4 C.E.O.s with 10 waves of pay left for ~600-damage cards)
    local left = math.max(0, (MT.total or 30) - MT.wave())
    -- (never sold: unsellable units like the Idol, buffers, and the copies a Merge is planned with)
    local plan = MT.mergePlan
    local weak, weakDps
    -- a card with a big footprint (the Idol, radius 5) must have a spot before anything is sold for it: a full field
    -- never tries to place, so "no spot" was never learned and a run sold Iron Sentinel for an Idol that didn't fit
    if bestHand and (tonumber(bestHand.data.override_hitbox_radius) or 0) > 3 and not MT.bestSpot(bestHand, true, false) then
        MT.noSpot[bestHand.uuid] = 3
        bestHand = nil
    end
    local airLow = MT.airLow()
    for _, m in ipairs(MT.mine) do
        local id = m._stats.id.Value
        local d = C.Units[id]
        -- (and never a unit that hits flyers while few do)
        if d and (tonumber(d.cost) or 0) > 0 and not d.unsellable and not UNIT.allyBuff(id) and not UNIT.idol(id) and not (plan and plan.id == id)
            and not (airLow and MT.canAir(m)) then
            local v
            if UNIT.isFarm(id) then
                local pay = m._stats:FindFirstChild("farm_amount") and tonumber(m._stats.farm_amount.Value) or 0
                v = (MT.bestRate or 0) > 0 and pay * left * MT.bestRate or math.huge
            else local ok, x = pcall(MT.liveDps, m, id); v = ok and x or math.huge end
            if not weakDps or v < weakDps then weak, weakDps = m, v end
        end
    end
    MT.roomPlan = nil
    if bestHand and weak and bestDps > 2 * weakDps then
        local refund
        for slot, spell in pairs(s.ingame_spells or {}) do if spell == "sell_refund" then refund = slot end end
        -- what selling gives back (all of it with the Refund spell, about half otherwise) toward the new unit
        local spent = weak._stats:FindFirstChild("total_spent") and tonumber(weak._stats.total_spent.Value) or 0
        local need = (bestHand.data.cost or 0) - spent * (refund and 1 or 0.5)
        local name = UNIT.name(weak._stats.id.Value)
        if MT.money() >= need then
            local ok = refund and SF.request("spell", "use_ingame_spell", refund, weak) or (not refund and SF.request("sell", "sell_unit_ingame", weak))
            if ok then
                SF.log(1, "PLACE", string.format("made room: sold %s%s for %s (2× the damage or more)", name, refund and " (full refund)" or "", UNIT.name(bestHand.id)))
                -- the card goes down at once, and no other sale for 15 s: the economy chose an upgrade instead and the
                -- swap rule sold Hex, Hex and Captain (God) in 6 s for one Time Wizard that was never placed
                MT.roomSoldAt = U.now()
                task.wait(0.6)
                MT.scan()
                MT.place(bestHand, "the spot just made for it")
            end
        else
            -- worth it, not affordable yet: MT.econ saves for it (unless the defense is in danger)
            MT.roomPlan = { name = UNIT.name(bestHand.id), out = name, need = need }
        end
        return
    end
    -- nothing worth making room for: discard the weakest unit card (one every 20 s), a new card (maybe a spell)
    -- can come instead
    if not HUB.every("discard", 20) then return end
    local worst, worstV
    for _, e in ipairs(MT.team) do
        if e.hand and not UNIT.idol(e.id) and not MT.mergeIds[e.id] then
            local v = UNIT.isFarm(e.id) and 0 or MT.cardDps(e)
            if not worstV or v < worstV then worst, worstV = e, v end
        end
    end
    if worst and MT.discardCard(worst) then
        SF.log(2, "PLACE", "discarded " .. UNIT.name(worst.id) .. " from the hand (the field is full, it isn't worth a spot)")
    end
end
-- Refund (free: "Sells the selected Unit with a full refund") gives back everything a unit cost, upgrades included:
--   · a farm once what it still pays (its pay × waves left) is less than what it cost
--   · a weak attacker (from wave 10, ¥5,000+ in it) whose yen buys 3× its damage in the best upgrade on offer — the
--     merged unit's, when there is one — and whose own next upgrade is worth under a third of that (a fresh unit's
--     low damage only means it isn't upgraded yet)
-- never while the defense is in danger or MT.makeRoom saves for a swap, and never a Merge copy, an Idol, a buffer,
-- a unit on the last 20% of the road, or one that hits flyers while under 40% of the damage can (one every 20 s)
MT.upRate = setmetatable({}, { __mode = "k" }) -- placed unit → its next upgrade's damage per yen (MT.econ)
function MT.refund()
    local s = C.session()
    if not (MT.random and s) or MT.spellBusy or MT.roomPlan or not HUB.every("refund", 20) then return end
    local slot
    for k, spell in pairs(s.ingame_spells or {}) do if spell == "sell_refund" then slot = k end end
    if not slot then return end
    local danger = (MT.pressure or 0) >= math.min(CFG.dangerReach, ((MT.depth and MT.depth.units > 0 and MT.depth.covEnd) or 1) * 0.9)
    local rate = MT.bestRate or 0
    if danger or rate <= 0 then return end
    local wave = MT.wave()
    local left = math.max(0, (MT.total or 30) - wave)
    local plan = MT.mergePlan
    local airLow = MT.airLow()
    local best, bestNet, bestWhy
    for _, m in ipairs(MT.mine) do
        local st = m._stats
        local id = st.id.Value
        local d = C.Units[id]
        local spent = st:FindFirstChild("total_spent") and tonumber(st.total_spent.Value) or 0
        if d and not d.unsellable and spent > 0 and not UNIT.allyBuff(id) and not UNIT.idol(id) and not (plan and plan.id == id) then
            local net, why
            if UNIT.isFarm(id) then
                local pay = st:FindFirstChild("farm_amount") and tonumber(st.farm_amount.Value) or 0
                local still = pay * left
                if spent > still * 1.2 then
                    net = (spent - still) * rate
                    why = string.format("a farm that still pays ¥%s but gives back ¥%s now", U.fmt(still), U.fmt(spent))
                end
            elseif wave >= 10 and left > 2 and spent >= 5000 and (MT.upRate[m] or 0) < rate / 3 and MT.progressAt(m:GetPivot().Position) < 0.8 and not (airLow and MT.canAir(m)) then
                -- (not in the last 2 waves — upgrades bought with it have no time to pay off — and never a unit doing
                -- 10%+ of the team's damage: a ¥62.9k Switchblade with 18% of it was refunded on wave 30 and the run
                -- lost on that wave)
                local okD, live = pcall(MT.liveDps, m, id)
                live = okD and live or math.huge
                if spent * rate > 3 * live and live < 0.1 * (MT.teamDps or 0) then
                    net = spent * rate - live
                    why = string.format("its ¥%s buys over 3× its damage in upgrades", U.fmt(spent))
                end
            end
            if net and (not bestNet or net > bestNet) then best, bestNet, bestWhy = m, net, why end
        end
    end
    if not best then return end
    MT.spellBusy = true
    task.spawn(function()
        local name = UNIT.name(best._stats.id.Value)
        local ok = SF.request("spell", "use_ingame_spell", slot, best)
        task.wait(1.5)
        if ok and (C.session().ingame_spells or {})[slot] ~= "sell_refund" then
            MT.refunds = (MT.refunds or 0) + 1
            SF.log(1, "SPELL", string.format("Refund on %s — %s", name, bestWhy))
            SF.status("Abilities", "Refund on " .. name)
        else
            SF.backoff("spell", 15)
            SF.log(2, "SPELL", "Refund wasn't taken on " .. name)
        end
        MT.spellBusy = false
    end)
end
-- the last wave with only a boss or two left (the user's call: "move back units up to kill the boss, it has regen"). A
-- Curse of Regen boss heals 1% of its max HP a second (a final boss: 366k/s against about 390k of damage), so damage only
-- counts while it lands together: units waiting further down the road don't help now, and units it has walked past never
-- will. So: new units and upgrades go where the boss is (MT.focus: MT.focusSpot, MT.focusGain); an attacker it has
-- passed for good is sold right away (nothing lost, 25% back); and when the boss would reach the base alive at the rate
-- measured, the attacker it reaches last is moved up too, one every 8 s. Not in a dealt team (a sold card is gone)
function MT.bossStep()
    MT.focus = nil
    if MT.random or MT.infinite or not (MT.total and MT.wave() >= MT.total) then return end
    local list = MT.enemies or {}
    -- (once a match: the last wave's biggest enemy beside the boss the simulator plays, and whether it heals. Taken as the wave goes: by the time two are left the boss is often dead,
    -- and the line named a 7k leftover against a 1M boss. Room 18 on Oct 31 had 64M against the simulator's 43M; room 6 on Nov 1 was the same boss to the digit and healed nothing)
    for _, e in ipairs(list) do
        local h = e.m and e.m:FindFirstChildOfClass("Humanoid")
        if h and h.MaxHealth > ((MT.bossTop and MT.bossTop.hp) or 0) then
            local st = e.m:FindFirstChild("_stats")
            MT.bossTop = { hp = h.MaxHealth, id = st and st:FindFirstChild("id") and st.id.Value, regen = st and st:FindFirstChild("Regen") and st.Regen.Value }
        end
    end
    if #list <= 2 and MT.bossTop and not MT.bossSaid then
        MT.bossSaid = true
        pcall(function()
            local top = 0
            if MT.info then for _, x in ipairs((SIM.wave(MT.info, MT.total))) do if x.boss and x.hp > top then top = x.hp end end end
            SF.log(1, "MATCH", string.format("the boss: %s, %.3g HP, heals %s%% a second · the simulator plays one of %.3g HP", tostring(MT.bossTop.id), MT.bossTop.hp, tostring(MT.bossTop.regen), top))
        end)
    end
    if #list == 0 or #list > 2 then MT.focusTrack = nil; return end
    local boss, rear = nil, 1
    for _, e in ipairs(list) do
        if not boss or e.hp > boss.hp then boss = e end
        rear = math.min(rear, e.prog)
    end
    MT.focus = { pos = boss.pos, prog = boss.prog, fly = boss.fly, m = boss.m }
    local t = U.now()
    local tr = MT.focusTrack
    if not tr or tr.m ~= boss.m then MT.focusTrack = { m = boss.m, t = t, hp = boss.hp, prog = boss.prog }; return end
    if t - tr.t >= 10 then
        tr.net, tr.rate = (tr.hp - boss.hp) / (t - tr.t), (boss.prog - tr.prog) / (t - tr.t)
        tr.t, tr.hp, tr.prog = t, boss.hp, boss.prog
    end
    if not tr.rate or tr.rate <= 0 then return end
    local bp = U.flat(boss.pos)
    local passed, ahead, inRange, aheadAny = {}, {}, 0, 0
    for _, m in ipairs(MT.mine or {}) do
        local st = m._stats
        local id = st.id.Value
        local d = C.Units[id]
        if not UNIT.isFarm(id) and not UNIT.allyBuff(id) and d and not d.unsellable and st:FindFirstChild("range") then
            local p, r = U.flat(m:GetPivot().Position), st.range.Value
            local canHit = not boss.fly or MT.canAir(m)
            if (p - bp).Magnitude <= r and canHit then inRange = inRange + 1 end
            if not ((p - bp).Magnitude <= r and canHit) then
                local first
                for _, s in ipairs(MT.samples) do
                    if s.prog >= rear and (U.flat(s.pos) - p).Magnitude <= r and (not first or s.prog < first) then first = s.prog end
                end
                local spent = st:FindFirstChild("total_spent") and tonumber(st.total_spent.Value) or 0
                -- (one move a fight, passed or ahead: Illusionist was sold twice, the fresh copy's short range leaving it out of reach
                -- again; room 16 on Oct 31 sold Chuuni, Gene, Mochi and Elf Spirit over and over as the boss walked past each fresh copy,
                -- 75% of every placement lost, until nothing was hitting a boss that healed 4% a second)
                local moved = MT.focusMoved and MT.focusMoved[id]
                -- (a unit ahead of the boss gets it in the end, at full upgrades: only a cheap copy is worth moving up. Room 18 sold an Iron
                -- Sentinel with ¥18.8k on it "the boss wouldn't reach it for 88 s" and put a level-0 one down instead)
                local cheap = spent <= 2.5 * (tonumber(d.cost) or 0)
                if first and canHit then aheadAny = aheadAny + 1 end
                if not first or not canHit then if not moved then table.insert(passed, { m = m, id = id, spent = spent }) end
                elseif not moved and cheap then table.insert(ahead, { m = m, id = id, spent = spent, eta = (first - boss.prog) / tr.rate }) end
            end
        end
    end
    local left = (1 - boss.prog) / tr.rate
    MT.focusLeft, MT.focusInRange = left, inRange
    local behind = tr.net and (tr.net <= 0 or boss.hp / tr.net > left * 0.8)
    if behind and HUB.every("bossBehind", 30) then
        SF.log(1, "MATCH", string.format("boss: %s HP left, %s HP a second after its regen, at the base in %ds, %d units reach it: moving units up to it", U.fmt(boss.hp), U.fmt(tr.net), math.floor(left), inRange))
    end
    -- a certain loss costs a life for nothing (the user's rule): when every unit that can hit the boss is hitting it, it would still reach
    -- the base alive, and it would take the base down faster than they kill it, the farm goes back to the lobby before the base falls.
    -- The room is offered again, and the planner counts this team as lost here (B.dg.bail)
    -- (every unit hitting it, or under 15 s from the base: the kill zone's units are ahead of the boss until late. Room 12 left at 56 s with 4 of them on it and the rest still to come.
    -- And 3 bail-outs in a room at most: leaving costs no try, so a room the team can't beat would otherwise repeat for ever)
    local seed = tostring(B.dg.room and B.dg.room.seed)
    B.dg.bails = type(B.dg.bails) == "table" and B.dg.bails or {}
    if MT.kind == "dungeon" and not MT.bailed and CFG.bailOut ~= false and (aheadAny == 0 or left < 15) and tr.net and left > 4 and left < 60 and (tonumber(B.dg.bails[seed]) or 0) < 3 then
        local eh = boss.m and boss.m:FindFirstChildOfClass("Humanoid")
        local bossMax = eh and eh.MaxHealth or boss.hp
        local base = workspace:FindFirstChild("_BASES") and workspace._BASES:FindFirstChild("player")
        local fu = base and base:FindFirstChild("base") and base.base:FindFirstChild("fake_unit")
        local hum = fu and fu:FindFirstChildOfClass("Humanoid")
        local baseHp = hum and hum.Health or (MT.info and tonumber(MT.info.baseHp)) or 100
        local rel = (MT.info and tonumber(MT.info.baseRel)) or SIM.PRIOR.baseRel
        local arriving = boss.hp - math.max(0, tr.net) * left
        local baseTime = baseHp / math.max(1, rel * bossMax)
        local killTime = arriving / math.max(1, tr.net)
        if arriving > 0 and (tr.net <= 0 or killTime > baseTime * 1.3) then
            MT.bailed = true
            B.dg.bails[seed] = (tonumber(B.dg.bails[seed]) or 0) + 1
            B.dg.bail = { sig = MODE.teamSig(), at = os.time() }
            -- (the way it stood lost this fight, life or no life: the next try stands safer)
            pcall(MT.styleRecord, false)
            SF.log(1, "MATCH", string.format("bailing out: the boss would reach the base with %s HP, your units deal %s a second to it and the base would last %ds against it: back to the lobby to keep the life", U.fmt(arriving), U.fmt(tr.net), math.floor(baseTime)))
            SF.flush()
            SF.request("lobby", "teleport_back_to_lobby")
            return
        end
    end
    local pick, why
    -- a unit the boss has walked past deals nothing more (the user's point: "it's just sitting there"): sold, its money goes into
    -- upgrades on the units that still reach the boss (MT.econ buys no new unit then). With nothing in reach and under 30 s left, a
    -- new unit couldn't be upgraded in time, so what stands, stands
    if inRange == 0 and left < 30 then return end
    if passed[1] and HUB.every("bossSell", 2) then
        table.sort(passed, function(a, b) return a.spent < b.spent end)
        pick, why = passed[1], inRange > 0 and "the boss has walked past it: its money goes to the units that reach it" or "the boss has walked past it"
    elseif behind and ahead[1] and left >= 30 and HUB.every("bossSell", 8) then
        table.sort(ahead, function(a, b) return a.eta > b.eta end)
        -- (one the boss reaches within 15 s is as good as moved)
        if ahead[1].eta > 15 then pick, why = ahead[1], string.format("the boss wouldn't reach it for %ds", math.floor(ahead[1].eta)) end
    end
    if pick then
        local _, sold = SF.request("sell", "sell_unit_ingame", pick.m)
        if sold == true then
            MT.focusMoved = MT.focusMoved or {}
            MT.focusMoved[pick.id] = true
            SF.log(1, "PLACE", string.format("boss: sold %s, ¥%s spent on it, to move up: %s", UNIT.name(pick.id), U.fmt(pick.spent), why))
        end
    end
end
-- a spot that reaches the boss now and covers the most road it walks next (nil: none free in reach)
function MT.focusSpot(e)
    local f = MT.focus
    local range = UNIT.range(e.u, 0) * ((MT.info and MT.info.rangeScale) or 1)
    local at = U.flat(f.pos)
    local best, bestSc
    local checked = 0
    for _, pos in ipairs(MT.cands) do
        if (U.flat(pos) - at).Magnitude <= range then
            local p = MT.valid(pos, e.data)
            checked = checked + 1
            if checked % 40 == 0 then task.wait() end
            if p then
                local sc, q = 0, U.flat(p)
                for _, s in ipairs(MT.samples) do
                    if s.prog >= f.prog and (U.flat(s.pos) - q).Magnitude <= range then sc = sc + 1 end
                end
                if not bestSc or sc > bestSc then best, bestSc = p, sc end
            end
        end
    end
    return best, bestSc or 0
end
-- upgrades go to units that can hit the boss: one it reaches soon counts a little, the others hardly at all
function MT.focusGain(m)
    local f = MT.focus
    if not f then return 1 end
    local st = m._stats
    if not st:FindFirstChild("range") then return 1 end
    local p, r = U.flat(m:GetPivot().Position), st.range.Value
    if f.fly and not MT.canAir(m) then return 0.02 end
    if (p - U.flat(f.pos)).Magnitude <= r then return 1 end
    return (p - U.flat(f.pos)).Magnitude <= r * 1.5 and 0.3 or 0.02
end
-- the last wave: farms won't pay again (the run ends with it), so each one is cashed in — with a Refund card for
-- everything it cost (the most expensive first), else sold — and the economy puts the yen into damage (the user's tip).
-- Every mode with a last wave since v1.5 (not Infinite); a farm the game won't sell is tried twice, then left
MT.cashTried = setmetatable({}, { __mode = "k" })
function MT.lastWaveCash()
    if not (MT.total and MT.wave() >= MT.total and not MT.infinite) or MT.spellBusy then return end
    local s = C.session()
    local refund
    for slot, spell in pairs((s and s.ingame_spells) or {}) do if spell == "sell_refund" then refund = slot end end
    local farm, spent
    for _, m in ipairs(MT.mine) do
        local st = m._stats
        local d = C.Units[st.id.Value]
        if UNIT.isFarm(st.id.Value) and not (d and d.unsellable) and (MT.cashTried[m] or 0) < 2 then
            local sp = st:FindFirstChild("total_spent") and tonumber(st.total_spent.Value) or 0
            if not spent or sp > spent then farm, spent = m, sp end
        end
    end
    if not farm then return end
    MT.cashTried[farm] = (MT.cashTried[farm] or 0) + 1
    local name = UNIT.name(farm._stats.id.Value)
    if refund then
        MT.spellBusy = true
        local ok = SF.request("spell", "use_ingame_spell", refund, farm)
        MT.spellBusy = false
        if ok then SF.log(1, "SPELL", string.format("last wave: Refund on %s — ¥%s back (farms don't pay after this wave)", name, U.fmt(spent))) end
    else
        -- (the server answers true for a sale, nothing for a refusal: Infinite wouldn't sell a golden Bulby)
        local _, sold = SF.request("sell", "sell_unit_ingame", farm)
        if sold == true then
            SF.log(1, "PLACE", string.format("last wave: sold %s, ¥%s spent on it (farms don't pay after this wave: the yen goes into damage)", name, U.fmt(spent)))
        elseif MT.cashTried[farm] >= 2 then
            SF.log(1, "PLACE", string.format("last wave: the game won't sell %s here", name))
        end
    end
end
-- Merge (the game: "Merges all other SAME Units in the Unit's range and gains 1.5x their current DPS"): what it gains
-- stays through later upgrades, so it goes on a fresh copy (few upgrades) with a maxed copy in its range, and the
-- fresh copy then gets every upgrade on top of 1.5× the maxed one — repeated, a guide video (Mufoo, Fool's Hunt) went
-- from 400k to billions. MT.mergePlan: the strongest attacker with a second copy placed or in the hand —
-- {id, top = its highest copy, fresh = the lowest copy with others in its range, near = their damage, n, ready}.
-- The Merge waits until the top copy is maxed (or the defense is in danger, the run nearly over, the card held 5
-- waves, or there's no fresher copy); until then the fresh copy isn't upgraded and the top one is, first
MT.mergeIds = {}
function MT.mergeScan()
    MT.mergePlan, MT.mergeIds = nil, {}
    if not MT.random then return end
    local s = C.session()
    local card = false
    MT.cloneCard = false
    for _, spell in pairs((s and s.ingame_spells) or {}) do
        if spell == "sacrifice" then card = true elseif spell == "clone" then MT.cloneCard = true end
    end
    local byId = {}
    local noMerge = B.fh.noMerge or {}
    for _, m in ipairs(MT.mine or {}) do
        local st = m._stats
        local id = st.id.Value
        if not UNIT.isFarm(id) and not UNIT.allyBuff(id) and not UNIT.idol(id) and st:FindFirstChild("max_upgrade") and (noMerge[id] or 0) < 2 then
            local okD, v = pcall(MT.liveDps, m, id)
            byId[id] = byId[id] or {}
            table.insert(byId[id], { m = m, lvl = st.upgrade.Value, max = st.max_upgrade.Value, dps = okD and v or 0 })
        end
    end
    local inHand = {}
    for _, e in ipairs(MT.team or {}) do if e.hand then inHand[e.id] = true end end
    -- the 3 strongest attackers' cards are kept (fishing, making room) as Merge copies
    local tops = {}
    for id, list in pairs(byId) do
        -- strongest first (a merged copy is the strongest even at level 0)
        table.sort(list, function(a, b) if a.dps ~= b.dps then return a.dps > b.dps end return a.lvl > b.lvl end)
        table.insert(tops, { id = id, dps = list[1].dps * MT.airBoost(list[1].m) * MT.reach(list[1].m) }) -- (flyers: MT.airWeight; range: MT.reach)
    end
    table.sort(tops, function(a, b) return a.dps > b.dps end)
    for i = 1, math.min(3, #tops) do MT.mergeIds[tops[i].id] = true end
    local best
    for id, list in pairs(byId) do
        -- the fresh copy: the least upgraded (then weakest) one with another copy in its range; top: the strongest
        -- copy in that range
        local order = table.clone(list)
        table.sort(order, function(a, b) if a.lvl ~= b.lvl then return a.lvl < b.lvl end return a.dps < b.dps end)
        -- the copy already held fresh stays the fresh one (roles swapped mid-plan once, both got upgraded and the
        -- level-3 Sword Queen took in the level-1 one)
        for i, c in ipairs(order) do if c.m == MT.freshM and i > 1 then table.remove(order, i); table.insert(order, 1, c); break end end
        local fresh, near, n, top
        for _, c in ipairs(order) do
            local cp, r = U.flat(c.m:GetPivot().Position), c.m._stats.range.Value
            local d, k, t = 0, 0, nil
            for _, o in ipairs(list) do
                if o ~= c and (U.flat(o.m:GetPivot().Position) - cp).Magnitude <= r then
                    d, k = d + o.dps, k + 1
                    if not t or o.dps > t.dps then t = o end
                end
            end
            if k > 0 then fresh, near, n, top = c, d, k, t; break end
        end
        top = top or list[1]
        -- (only one of your 3 strongest attackers is worth growing: a run aimed it at a level-0 Captain Magma)
        -- (the unit already being grown counts double, so the plan doesn't hop between units as their damage moves)
        local score = top.dps * MT.airBoost(top.m) * MT.reach(top.m) * (id == MT.planId and 2 or 1)
        if (MT.mergeIds[id] or id == MT.planId) and (fresh or inHand[id]) and (not best or score > best.score) then
            best = { id = id, top = top, fresh = fresh, near = near or 0, n = n or 0, coming = inHand[id], score = score }
        end
    end
    MT.planId, MT.freshM = best and best.id, best and best.fresh and best.fresh.m
    -- (the 5-wave patience counts from when a fresh copy waits with the card in hand, not from the card's arrival:
    -- a card held since wave 1 merged a level-3 Tango the moment its fresh copy landed at wave 6)
    MT.mergeHeldAt = (card and best and best.fresh) and (MT.mergeHeldAt or MT.wave()) or nil
    if not best then return SF.status("Merge", "no second copy of a strong unit yet") end
    local wave, left = MT.wave(), (MT.total or 30) - MT.wave()
    local danger = (MT.pressure or 0) >= math.min(CFG.dangerReach, ((MT.depth and MT.depth.units > 0 and MT.depth.covEnd) or 1) * 0.9)
    local f = best.fresh
    -- waits for the top copy to max (the fresh copy is held at its level meanwhile), for a fresh copy from the hand,
    -- or for a Clone of the maxed top copy (one more copy to take in, MT.spells casts it first)
    local calm = not danger and left > 3
    best.waits = f and f.lvl <= best.top.lvl and best.top.lvl < best.top.max and calm or false
    local fromHand = (not f or f.lvl >= best.top.lvl) and best.coming and calm
    local cloneFirst = MT.cloneCard and best.top.lvl >= best.top.max and calm
    -- backwards (the copy taking the others in is the more upgraded one: only the fresh copy's range reached): worth a
    -- Merge card only when what it takes in is 30%+ of its own damage — a level-7 Switchblade took in a level-0 copy
    -- and gained nothing
    local inverted = f and f.lvl > best.top.lvl and best.near < 0.3 * f.dps
    best.ready = card and f ~= nil and not inverted and (not (best.waits or fromHand or cloneFirst) or wave - (MT.mergeHeldAt or wave) >= 5)
    -- the fresh copy stays un-upgraded while a Merge card is in hand, without one for 4 waves at most (a Rebel was
    -- held at level 0 from wave 7 to 14 for a Merge that never came, and the run died at 15)
    MT.holdNoCardAt = (best.waits and not card) and (MT.holdNoCardAt or wave) or nil
    best.hold = best.waits and (card or wave - (MT.holdNoCardAt or wave) < 4)
    MT.mergePlan = best
    SF.status("Merge", f and string.format("%s: merge %d cop%s into the one with %d upgrades %s", UNIT.name(best.id), best.n, best.n == 1 and "y" or "ies", f.lvl,
        best.ready and "now" or (card and "once the top copy is maxed" or "when a Merge card comes"))
        or string.format("%s: a second copy in the hand goes next to it", UNIT.name(best.id)))
end
-- the fresh copy of the plan isn't upgraded while it waits for the Merge
function MT.mergeHold(m)
    local p = MT.mergePlan
    return p and p.hold and p.fresh and p.fresh.m == m or false
end
-- the top copy's upgrades come first while a fresh copy waits: its damage counts 1.5× in the merge, then gets
-- the fresh copy's upgrades on top
function MT.mergeBoost(m)
    local p = MT.mergePlan
    if not (p and p.top.m == m and (p.fresh or p.coming)) then return 1 end
    return MT.mergeHeldAt and 2 or 1.3
end
-- where a hand copy of a Merge unit goes: next to the strongest copy placed
function MT.mergeSpot(e)
    if not (MT.random and MT.mergeIds[e.id]) then return nil end
    local best, bestDps
    for _, m in ipairs(MT.mine or {}) do
        if m._stats.id.Value == e.id then
            local okD, v = pcall(MT.liveDps, m, e.id)
            v = okD and v or 0
            if not bestDps or v > bestDps then best, bestDps = m, v end
        end
    end
    return best and best:GetPivot().Position
end
-- what a Merge really did: the merged unit's damage 2 s later vs its own + 1.5× the copies it took
-- (B.fh.merge: casts and their average real ÷ expected)
function MT.mergeMeasure(target)
    local b = MT.mergeBefore
    if not b then return end
    task.delay(2, function()
        if not (target and target.Parent) then return end
        local okD, after = pcall(MT.liveDps, target, target._stats.id.Value)
        if not okD then return end
        local expect = b.own + 1.5 * b.near
        local r = B.fh.merge or { n = 0, ratio = 0 }
        if expect > 0 then r.n, r.ratio = r.n + 1, r.ratio + after / expect end
        B.fh.merge = r
        -- a unit a Merge doesn't grow (Switchblade (Deception): 3 merges, damage unchanged each time) — 2 misses and
        -- it's left out of Merge plans (B.fh.noMerge); a working merge clears it
        local id = target._stats.id.Value
        B.fh.noMerge = B.fh.noMerge or {}
        local gain, want = after - b.own, 1.5 * b.near
        if want > 0 and gain < 0.1 * want then B.fh.noMerge[id] = (B.fh.noMerge[id] or 0) + 1
        elseif want > 0 and gain >= 0.5 * want then B.fh.noMerge[id] = nil end
        SF.log(1, "SPELL", string.format("Merge result: %s went from %s to %s damage a second at %d upgrades (its own + 1.5× the copies' %s = %s expected; the top copy had %d)",
            UNIT.name(target._stats.id.Value), U.fmt(b.own), U.fmt(after), b.lvl, U.fmt(b.near), U.fmt(expect), b.top))
    end)
end
-- Merge on farms (the user's idea): does a farm keep 1.5× the income of the copies it takes in, or only their damage
-- (0)? A pair's second copy goes inside the first one's reach, the first pair merges as a test (B.fh.farmMerge:
-- income after ÷ (own + 1.5 × theirs)); from 0.8 every farm pair merges, under 0.3 never again
-- (tested Oct 30: two maxed C.E.O.s at ¥2,500 a wave merged into one paying ¥2,500 — a farm keeps only its own
-- income, so one test settles it)
function MT.farmMergeOk()
    local r = B.fh.farmMerge
    if not (r and r.n > 0) then return true end
    return r.ratio / r.n >= 0.8
end
-- the lowest farm copy with another copy in its reach: target, the income it would take in, how many
function MT.farmMergePair()
    local byId = {}
    for _, m in ipairs(MT.mine or {}) do
        local id = m._stats.id.Value
        if UNIT.isFarm(id) and m._stats:FindFirstChild("farm_amount") then byId[id] = byId[id] or {}; table.insert(byId[id], m) end
    end
    for _, list in pairs(byId) do
        if #list >= 2 then
            table.sort(list, function(a, b) return a._stats.upgrade.Value < b._stats.upgrade.Value end)
            for _, c in ipairs(list) do
                local cp, r = U.flat(c:GetPivot().Position), c._stats.range.Value
                local inc, k = 0, 0
                for _, o in ipairs(list) do
                    if o ~= c and (U.flat(o:GetPivot().Position) - cp).Magnitude <= r then inc, k = inc + (tonumber(o._stats.farm_amount.Value) or 0), k + 1 end
                end
                if k > 0 then return c, inc, k end
            end
        end
    end
end
-- where a farm card goes when a copy of it is placed: inside that copy's reach (its live range)
function MT.farmMergeSpot(e)
    if not (MT.random and MT.farmMergeOk()) then return nil end
    for _, m in ipairs(MT.mine or {}) do
        if m._stats.id.Value == e.id then return m:GetPivot().Position, tonumber(m._stats.range.Value) or 0 end
    end
end
function MT.farmMergeMeasure(target)
    local b = MT.farmMergeBefore
    if not b then return end
    task.delay(2, function()
        if not (target and target.Parent) then return end
        local after = tonumber(target._stats.farm_amount.Value) or 0
        local expect = b.own + 1.5 * b.inc
        local r = B.fh.farmMerge or { n = 0, ratio = 0 }
        r.n, r.ratio = r.n + 1, r.ratio + (expect > 0 and after / expect or 0)
        B.fh.farmMerge = r
        SF.log(1, "SPELL", string.format("Farm merge result: %s pays ¥%s a wave now (it paid ¥%s and took in farms paying ¥%s; keeping 1.5× would make ¥%s)",
            UNIT.name(target._stats.id.Value), U.fmt(after), U.fmt(b.own), U.fmt(b.inc), U.fmt(expect)))
    end)
end
-- the Idol's effect per level: +5% damage and 5% cheaper upgrades until measured (MT.idolMeasure, B.fh.idol)
MT.IDOL_PRIOR = { dmg = 0.05, cost = 0.05 }
function MT.idolStep()
    local i = B.fh.idol
    local dmg, cost = MT.IDOL_PRIOR.dmg, MT.IDOL_PRIOR.cost
    if i and i.n > 0 then dmg, cost = i.dmg / i.n, i.cost / i.n end
    -- (cheaper upgrades count half as much as the same share of damage: they pay off over the rest of the run)
    return math.max(0, dmg) + math.max(0, cost) * 0.5
end
-- an Idol upgrade, measured on another unit: its damage and upgrade-cost multiplier just before and 2 s after
function MT.idolMeasure()
    local ref
    for _, m in ipairs(MT.mine) do
        local id = m._stats.id.Value
        local dv = m._stats:FindFirstChild("damage")
        if not UNIT.isFarm(id) and not UNIT.idol(id) and dv and dv.Value > 0 then ref = m; break end
    end
    if not ref then return end
    local st = ref._stats
    local function now()
        local okC, c = pcall(C.USC.calculate_upgrade_cost_multiplier, ref, C.session())
        local bd = st:FindFirstChild("buff_damage_multiplier") and tonumber(st.buff_damage_multiplier.Value) or 0
        return st.damage.Value * (1 + bd), okC and tonumber(c) or nil
    end
    local d0, c0 = now()
    local l0 = st.upgrade.Value
    -- (measured by hand Oct 30: placing gives every unit +5% damage and ×0.95 upgrade cost, each upgrade +~2% and
    -- another ×0.95 — a reading with no change at all was a missed update and once zeroed the Idol's worth)
    task.delay(3, function()
        if not ref.Parent or st.upgrade.Value ~= l0 then return end
        local d1, c1 = now()
        if not (c0 and c1 and c0 > 0 and d0 > 0) then return end
        if d1 == d0 and c1 == c0 then return SF.log(2, "UPGRADE", "Idol upgrade: no change seen yet, not counted") end
        local i = B.fh.idol or { n = 0, dmg = 0, cost = 0 }
        i.n, i.dmg, i.cost = i.n + 1, i.dmg + (d1 / d0 - 1), i.cost + (1 - c1 / c0)
        B.fh.idol = i
        SF.log(1, "UPGRADE", string.format("Idol upgrade measured on %s: %+.1f%% damage, upgrades %.1f%% cheaper", UNIT.name(st.id.Value), (d1 / d0 - 1) * 100, (1 - c1 / c0) * 100))
    end)
end
-- spell cards a dealt-team mode hands out (session.ingame_spells, Data.IngameSpells; use_ingame_spell(slot, unit)):
--   Random Buff (¥1,000, +100% attack or range for good) on your strongest damage dealer · Merge (¥1,000, above,
--   MT.mergePlan) · Clone (¥5,000) of the strongest and Astral Summon (¥10,000, a unit
--   from your own team) once the defense isn't in danger · Astral Gate (¥2,500, 3× Summon odds) with yen to spare.
--   Clone goes on the Merge unit's maxed copy (MT.mergeScan waits for it), Ritual is tested (MT.ritualTarget),
--   Refund: MT.refund and MT.makeRoom; extra copies of a spell are discarded (MT.makeRoom)
function MT.spells()
    local s = C.session()
    local list = s and s.ingame_spells
    if type(list) ~= "table" or MT.spellBusy then return end
    local money = MT.money()
    local danger = (MT.pressure or 0) >= math.min(CFG.dangerReach, ((MT.depth and MT.depth.units > 0 and MT.depth.covEnd) or 1) * 0.9)
    -- the strongest unit for Random Buff and Clone, units that hit flyers weighted (MT.airBoost: at 15% air share
    -- Gravity's 5.9k mattered more than Sword Queen's 29k)
    local best, bestDps, bestW
    for _, m in ipairs(MT.mine) do
        local id = m._stats.id.Value
        if not UNIT.isFarm(id) and not UNIT.allyBuff(id) and id ~= "mahoraga" then -- (not the Divine General)
            local ok, v = pcall(MT.liveDps, m, id)
            local w = ok and v and v * MT.airBoost(m) * MT.reach(m)
            if w and (not bestW or w > bestW) then best, bestDps, bestW = m, v, w end
        end
    end
    local plan = MT.mergePlan
    -- Clone goes before Merge (a clone of the maxed copy is one more for the Merge to take in)
    local order = {}
    for slot, spell in pairs(list) do table.insert(order, { slot = slot, spell = spell, rank = MT.SPELL_ORDER[spell] or 9 }) end
    table.sort(order, function(a, b) return a.rank < b.rank end)
    MT.spellWant = nil -- (a Clone or Merge worth saving for: MT.econ saves its price)
    MT.cloneNote = nil -- (what the Clone card waits for, in the WATCH line)
    for _, o in ipairs(order) do
        local slot, spell = o.slot, o.spell
        local target, why
        local general
        for _, m in ipairs(MT.mine) do if m._stats.id.Value == "mahoraga" then general = m end end
        local buffGeneral = general and (MT.buffCount[general] or 0) < 2
        if spell == "random_buff" and money >= 1000 and (buffGeneral or best) then
            -- the first two go on the Divine General when one is out (a guide's tip: +100% attack and +100% range
            -- make it a boss killer — its range is only 8.5), then the strongest unit
            if buffGeneral then target, why = general, "the Divine General (two buffs make it a boss killer; its range is only 8.5)"
            else target, why = best, "+100% attack or range on your strongest unit" end
        elseif spell == "sacrifice" and plan and plan.ready then
            if money >= 1000 then
                target, why = plan.fresh.m, string.format("the %d other cop%s in its range (it keeps 1.5× their damage through its own upgrades)", plan.n, plan.n == 1 and "y" or "ies")
                MT.mergeBefore = { own = plan.fresh.dps, near = plan.near, lvl = plan.fresh.lvl, top = plan.top.lvl }
            else MT.spellWant = MT.spellWant or { cost = 1000, why = "Merge on " .. UNIT.name(plan.id) } end
        elseif spell == "sacrifice" and money >= 1000 and not danger and not (plan and plan.fresh) and MT.farmMergeOk() and MT.farmMergePair() then
            -- (no attacker pair waits for this card: merge a farm pair — a test until B.fh.farmMerge says it pays)
            local t, inc, k = MT.farmMergePair()
            target = t
            why = string.format("the %d other %s in its reach (does a farm keep their income?)", k, UNIT.name(t._stats.id.Value))
            MT.farmMergeBefore = { own = tonumber(t._stats.farm_amount.Value) or 0, inc = inc }
        elseif spell == "clone" then
            -- (also with enemies near the base: a copy of the strongest unit is instant damage — the user cloned the
            -- strongest by hand at wave 18 while this rule held the card; in danger it goes on the strongest at once)
            -- the Merge unit's maxed copy (one more to take in); while it isn't maxed the card waits (5 waves at
            -- most); otherwise the strongest unit — a fresh copy of it starts the next Merge. Short of ¥5,000 the
            -- economy saves for it when the copy adds at least half what ¥5,000 buys in upgrades (a run held a
            -- Clone from wave 6 to 16 and never had ¥5,000: every yen went to upgrades)
            -- (it waits only while a placed pair waits for its top copy to max; a pair from the hand doesn't stop it)
            local waiting = not danger and plan and plan.fresh and plan.top.lvl < plan.top.max
            MT.cloneWaitAt = waiting and (MT.cloneWaitAt or MT.wave()) or nil
            local waitMax = waiting and MT.wave() - MT.cloneWaitAt < 5
            local t, w
            if not danger and plan and plan.fresh and plan.top.lvl >= plan.top.max then t, w = plan.top.m, "a maxed copy for the Merge to take in"
            elseif not waitMax and best then t, w = best, danger and "a copy of your strongest unit: instant damage with enemies near the base" or "a copy of your strongest unit (two copies make a Merge)" end
            if waitMax then MT.cloneNote = string.format("waits for %s to max (%d/%d, up to %d more waves)", UNIT.name(plan.id), plan.top.lvl, plan.top.max, 5 - (MT.wave() - MT.cloneWaitAt)) end
            if t and money >= 5000 then target, why = t, w
            elseif t then
                local okC, cd = pcall(MT.liveDps, t, t._stats.id.Value)
                cd = okC and tonumber(cd) or 0
                if cd >= (MT.bestRate or 0) * 5000 * 0.5 then
                    MT.spellWant = MT.spellWant or { cost = 5000, why = "Clone of " .. UNIT.name(t._stats.id.Value), rate = cd / 5000 }
                    MT.cloneNote = "saving for a copy of " .. UNIT.name(t._stats.id.Value)
                else MT.cloneNote = string.format("a copy of %s (%s dps) is worth less than ¥5k of upgrades (%s)", UNIT.name(t._stats.id.Value), U.fmt(cd), U.fmt((MT.bestRate or 0) * 5000)) end
            end
        elseif spell == "ritual" and not danger and MT.wave() >= 8 and not MT.hasGeneral() then
            -- (the economy saves its ¥10,000 like a Clone's: early versions threw Rituals away, later ones held them
            -- untested because every yen went to upgrades)
            local t, w = MT.ritualTarget()
            if t and money >= 10000 then target, why = t, w
            elseif t then MT.spellWant = MT.spellWant or { cost = 10000, why = "a Ritual (" .. w .. ")" } end
        elseif spell == "summon" and money >= 10000 and not danger and MT.summonWorth() then target, why = false, "a unit from your own team"
        elseif spell == "gate" and money >= 2500 and not danger and MT.summonWorth() then target, why = false, "3× the odds of Astral Summon" end
        if why then
            MT.spellBusy = true
            local before = {}
            for _, m in ipairs(workspace._UNITS:GetChildren()) do before[m] = true end
            local was
            if target then
                local st = target._stats
                local okW, dW = pcall(MT.liveDps, target, st.id.Value)
                was = { id = st.id.Value, pos = target:GetPivot().Position, dps = okW and tonumber(dW) or 0, lvl = st.upgrade.Value,
                    spent = st:FindFirstChild("total_spent") and tonumber(st.total_spent.Value) or 0 }
            end
            task.spawn(function()
                local ok
                if target then ok = SF.request("spell", "use_ingame_spell", slot, target) else ok = SF.request("spell", "use_ingame_spell", slot) end
                task.wait(1.5)
                local name = target and UNIT.name(target._stats.id.Value) or ""
                if ok and (C.session().ingame_spells or {})[slot] ~= spell then
                    SF.log(1, "SPELL", string.format("%s%s — %s", MT.SPELL_NAMES[spell] or tostring(spell), target and (" on " .. name) or "", why))
                    SF.status("Abilities", string.format("spell %s%s — %s", MT.SPELL_NAMES[spell] or tostring(spell), target and (" on " .. name) or "", why))
                    if spell == "sacrifice" then
                        if was and UNIT.isFarm(was.id) then pcall(MT.farmMergeMeasure, target) else pcall(MT.mergeMeasure, target) end
                    end
                    if spell == "random_buff" and target then MT.buffCount[target] = (MT.buffCount[target] or 0) + 1 end
                    if (spell == "clone" or spell == "ritual") and was then pcall(MT.newUnitMeasure, spell, target, name, was, before) end
                else
                    -- the game didn't take it: wait a bit before trying spells again
                    SF.backoff("spell", 15)
                    SF.log(2, "SPELL", tostring(spell) .. " wasn't taken" .. (target and (" on " .. name) or ""))
                end
                MT.spellBusy = false
            end)
            return
        end
    end
end
-- takedown training: the trainee's takedowns this match (the game counts them on each placed unit)
function MT.trainCount()
    local on = B.train.on
    if not (on and MT.trainee) then return end
    local n = 0
    for _, m in ipairs(MT.mine) do
        local st = m._stats
        local uuid = st:FindFirstChild("uuid") and st.uuid.Value
        local v = uuid == MT.trainee and st:FindFirstChild(on.what == "kills" and "kill_count" or "takedown_count")
        if v then n = n + (tonumber(v.Value) or 0) end
    end
    MT.trainTk = math.max(MT.trainTk or 0, n)
    SF.status("Training", string.format("%s: %d %s this match · %s/%s", UNIT.name(on.id), MT.trainTk, on.what, U.fmt(on.have + (on.got or 0) + MT.trainTk), U.fmt(on.need)))
end
function MT.trainDone(key, won)
    local on = B.train.on
    if not (on and MT.trainee) then return end
    MT.trainCount()
    local got = MT.trainTk or 0
    on.got = (on.got or 0) + got
    local est = B.trainSim[key] and tonumber(B.trainSim[key].tk)
    if not MT.joinedMid then
        local r = B.train.real[key] or { n = 0, sum = 0 }
        r.n, r.sum = r.n + 1, r.sum + got
        B.train.real[key] = r
        -- real vs simulated takedowns: corrects the sim's count for modes not trained in yet
        if est and est > 0 then
            local c = B.train.cal
            c.real, c.sim, c.n = (c.real or 0) + got, (c.sim or 0) + est, (c.n or 0) + 1
        end
    end
    table.insert(B.train.log, 1, { key = key, got = got, won = won, at = os.time() })
    while #B.train.log > 20 do table.remove(B.train.log) end
    SF.log(1, "TRAIN", string.format("%s: +%d %s this run (%s%s) · %s/%s", UNIT.name(on.id), got, on.what, won and "won" or "lost",
        est and string.format(", the simulator said ≈%d", est) or "", U.fmt(TRAIN.realHave(on)), U.fmt(on.need)))
    if not won then
        B.train.bad[key] = os.time() + 6 * 3600
        SF.log(1, "TRAIN", "the training team lost here: no training in this mode for 6 h")
    end
end
function MT.finish()
    if MT.finished then return end
    MT.finished = true
    -- the game's own result (settings shown on the results screen)
    local res
    local t0 = U.now()
    while U.now() - t0 < 8 do
        res = MT.result or (C.GUIS.results_ui and C.GUIS.results_ui.settings)
        if res then break end
        task.wait(0.25)
    end
    local won = res and res.victory or false
    -- Infinite always ends with the base falling: not a loss to rest the mode or stop training over; its result is
    -- the wave reached (what the ranking's daily gems and run length go by)
    local infWave = MT.infinite and MT.wave() or nil
    if infWave then won = true end
    local key = MT.key
    local rec = MODE.rec(key)
    -- (a run the farm ended itself says nothing about how far the team gets)
    if infWave and not MT.joinedMid and not MT.stopping then
        rec.waveSum, rec.waveN = (tonumber(rec.waveSum) or 0) + infWave, (tonumber(rec.waveN) or 0) + 1
        rec.waveBest = math.max(tonumber(rec.waveBest) or 0, infWave)
    end
    -- (the first Infinite runs log what the result carries, to learn where the daily gems show up)
    if infWave and (tonumber(B.infResults) or 0) < 3 and type(res) == "table" then
        B.infResults = (tonumber(B.infResults) or 0) + 1
        local f = {}
        for k, v in pairs(res) do table.insert(f, type(v) == "table" and (k .. "{…}") or (k .. "=" .. tostring(v))) end
        table.sort(f)
        SF.log(1, "MATCH", "Infinite result fields: " .. table.concat(f, ", "))
    end
    local sec = res and res.stats and tonumber(res.stats.time_taken) or (os.clock() - (MT.startClock or os.clock()))
    local gems = res and ((tonumber(res.gem_reward) or 0) + (tonumber(res.first_completion_gems) or 0)) or 0
    local coinName = C.GS.CURRENT_EVENT_RESOURCE or "AprilCoins"
    local coins = res and res.resource_reward and tonumber(res.resource_reward[coinName]) or 0
    -- a run the script joined mid-way is a bad sample (no placement from the start): logged, not counted
    if not MT.joinedMid then
        rec.runs = rec.runs + 1
        if won then rec.wins = rec.wins + 1; rec.streak = 0
        elseif MT.kind == "event" and coins > 0 then rec.streak = 0 -- paid per wave: not a run to rest the mode over
        else rec.streak = (rec.streak or 0) + 1 end
        rec.sec = rec.sec + sec
        rec.timed = (tonumber(rec.timed) or 0) + 1
    end
    if won then
        if MT.ld._gamemode == "story" or MT.kind == "raid" then B.cleared[MT.ld.id .. ":" .. tostring(MT.ld._difficulty or "Normal")] = os.time() end
        if key == "ch" and B.live.normal then B.live.normal.doneUuid = B.live.normal.uuid end
        if key == "dc" and B.live.daily then B.live.daily.doneUuid = B.live.daily.uuid end
    end
    for k, t in pairs(B.cleared) do if os.time() - t > 86400 then B.cleared[k] = nil end end
    rec.gems = rec.gems + gems
    rec.coins = rec.coins + coins
    rec.last = os.time()
    -- (a dungeon room gives 5 tries, and DG.enter decides whether the last one gets played)
    local restNow = (rec.streak or 0) >= CFG.restAfterLosses and MT.kind ~= "dungeon" and not MT.trialId and not (CFG.dailyLoop and key == "dc")
    if restNow then
        rec.restUntil = os.time() + 6 * 3600
        SF.log(1, "MODE", MT.label() .. ": lost " .. rec.streak .. " in a row — resting it for 6 h")
    end
    if not won and (key == "ch" or key == "dc") then
        local x = key == "ch" and B.live.normal or B.live.daily
        if x then x.lost = (x.lost or 0) + 1 end
    end
    B.totals.matches = (B.totals.matches or 0) + 1
    if not MT.joinedMid then
        if won then B.totals.wins = B.totals.wins + 1 else B.totals.losses = B.totals.losses + 1 end
    end
    B.totals.gems = (B.totals.gems or 0) + gems
    B.totals.coins = (B.totals.coins or 0) + coins
    local items = {}
    for _, it in pairs(res and res.new_items or {}) do
        local id = type(it) == "table" and (it.item_id or it.id) or tostring(it)
        items[id] = (items[id] or 0) + (type(it) == "table" and tonumber(it.amount) or 1)
    end
    local label = MT.label()
    if MT.kind == "dungeon" and not MT.joinedMid then
        local okD, eD = pcall(DG.roomDone, won)
        if not okD then SF.log(1, "ERROR", "dungeon: " .. tostring(eD)) end
    end
    -- (a trial run says nothing about how your team does here: no spot, way-to-stand, simulator or damage-share records from it)
    if not MT.joinedMid and not MT.random and not MT.stopping and not MT.trialId then pcall(MT.spotResult, won) end
    B.lastResult = { won = won, text = string.format("%s · %s · wave %s · %dm%02ds", label, won and "won" or "lost", tostring(res and res.stats and res.stats.waves_completed or MT.wave()), math.floor(sec / 60), math.floor(sec % 60)),
        gems = gems, coins = coins, items = items, at = os.time() }
    table.insert(B.history, 1, { key = key, won = won, sec = sec, gems = gems, coins = coins, at = os.time() })
    while #B.history > 30 do table.remove(B.history) end
    B.lastMatch = { label = label, spent = MT.spent, actions = #MT.actions, refusals = MT.refusals or 0, at = os.time() }
    -- (a trial's shares are the trial's: the unit on it got the yen, and that read as it being ×1.87 stronger than predicted)
    if not MT.trialId then pcall(MT.learn) end
    local okTr, eTr = pcall(MT.trainDone, key, won)
    if not okTr then SF.log(1, "ERROR", "training: " .. tostring(eTr)) end
    -- (a dealt team says nothing about how your own team does: no sim calibration from it; it's recorded instead)
    local okC, eC = true, nil
    -- (nor does a run the farm ended by selling its units: enemies walking through would read as a weak team)
    if MT.hunt then
        local okH, eH = pcall(MT.huntRecord, res, coins, won, sec)
        if not okH then SF.log(1, "ERROR", "hunt record: " .. tostring(eH)) end
    end
    if MT.random then pcall(MT.fhRecord, coins, won) elseif not MT.stopping and not MT.trialId then okC, eC = pcall(MT.calMerge, won) end
    if not okC then SF.log(1, "ERROR", "sim calibration: " .. tostring(eC)) end
    REPORT.record({ mode = key, won = won, sec = math.floor(sec), wave = MT.wave(), gems = gems, coins = coins, mid = MT.joinedMid or nil })
    SF.log(1, "RESULT", string.format("%s — %s, +%d gems%s, ¥%s spent, %d refused spots", label, infWave and ("reached wave " .. infWave) or (won and "WON" or "LOST"), gems, coins > 0 and (", +" .. coins .. " " .. coinName) or "", U.fmt(MT.spent), MT.refusals or 0))
    -- (a portal run the lobby measures: a lost one pays nothing, and that isn't what a portal pays — the first Shibuya Portal was lost at wave 8 and read as "0 a run")
    if B.watch and B.watch.key == key then B.watch.won = won and true or false; SF.saveNow() end
    -- the team that won here (SIM.plan plays it again where the simulator calls it a loss); a loss clears it. Infinite has no win, so it never keeps one
    pcall(function()
        local rec = MODE.rec(key)
        if won and not infWave then
            local list = {}
            for _, e in ipairs(UNIT.equipped()) do table.insert(list, e.uuid) end
            table.sort(list)
            local sig = table.concat(list, ",")
            -- (a win only takes the record from a stronger winning team when it's at least as strong: Gene (???) won a portal doing 0%, beside a team that had won it twice)
            local function strength(uuids)
                local s, sum = C.session(), 0
                for _, uuid in ipairs(uuids or {}) do
                    local u = s.collection:get_unit_by_uuid(uuid)
                    local okS, sc = pcall(UNIT.score, u or {})
                    sum = sum + (okS and sc or 0)
                end
                return sum
            end
            if #list > 0 then
                if rec.winSig == sig then rec.winTeamN = (tonumber(rec.winTeamN) or 0) + 1
                elseif not rec.winTeam or strength(list) >= strength(rec.winTeam) then rec.winTeam, rec.winSig, rec.winTeamN = list, sig, 1 end
            end
        elseif not won then
            rec.winTeam, rec.winSig, rec.winTeamN = nil, nil, nil
        end
    end)
    local okH, eH = pcall(REPORT.match, { key = key, won = won, sec = sec, gems = gems, coins = coins, items = items })
    if not okH then SF.log(1, "ERROR", "brain hive: " .. tostring(eH)) end
    -- the portal record, one line a run (AA_SmartFarm/portal_runs.txt): the user asked to watch ten portal matches, Nov 2
    if MT.kind == "portal" then
        pcall(function()
            local names = {}
            for _, e in ipairs(UNIT.equipped()) do table.insert(names, UNIT.name(e.id)) end
            local pr = MT.pred
            HUB.portalLine(string.format("%s · %s at wave %d of %d · predicted %s · team: %s · style %s · modifiers: %s · %s", os.date("%m-%d %H:%M"), won and "WON" or "LOST", MT.wave(), MT.total or 0,
                pr and ((pr.won and "a win at " or "a loss at ") .. tostring(pr.wave)) or "nothing", table.concat(names, ", "), tostring(MT.style), tostring(B.portalMods or "?"):sub(1, 300), tostring(MT.damageLine() or "")))
        end)
    end
    for id, seen in pairs(MT.buffSeen) do
        local top = 0
        for _, v in ipairs(seen.levels) do top = math.max(top, v) end
        SF.log(1, "BUFF", string.format("%s cast %d times: your units read %s%% after the casts (highest +%d%%)", UNIT.name(id), seen.casts, table.concat(seen.levels, ", "), top))
    end
    local okD, dealtLine = pcall(MT.damageLine)
    if okD and dealtLine then SF.log(1, "DAMAGE", dealtLine) end
    -- the Team tab learns who really carries, and what this run paid in XP (settled in the lobby, once the profile has it)
    if not MT.random then
        local okS, shares = pcall(MT.damageShares)
        if okS and shares and not MT.trialId then pcall(STR.learn, shares, MT.team) end
        B.lastRun = { key = key, at = os.time(), xp0 = MT.xp0 }
    end
    if MT.trialId then
        local okTd, eTd = pcall(MT.trialDone, won, sec)
        if not okTd then SF.log(1, "ERROR", "trial: " .. tostring(eTd)); B.trial = nil end
    end
    -- what next: the same ranking the lobby uses
    -- (a story win: the profile may not show the next act unlocked yet, and until it does Story Only has nothing on offer: it went to the lobby instead of pressing Next. A short look only:
    -- on Nov 1 it hadn't changed after 8 s on this screen, and the game's own Next doesn't need it)
    local nextAct
    if won and MT.ld._is_actual_storymode then
        local okN, nxt = pcall(C.PSC.get_next_story_level, MT.ld.id)
        if okN and nxt then
            nextAct = nxt
            local tw = U.now()
            while SF.alive and U.now() - tw < 2 do
                if MODE.open(nxt) then break end
                task.wait(0.5)
            end
        end
    end
    local top = nil
    pcall(function() top = MODE.pick() end)
    -- (a first clear next in line goes ahead of another first clear: no lobby trip)
    if top and top.kind == "story" and top.first and nextAct and top.level ~= nextAct and not B.nextMode then
        for _, m in ipairs(MODE.lastScored or {}) do
            if m.kind == "story" and m.first and m.level == nextAct and m.diff == MT.ld._difficulty and (m.baseScore or m.score or 0) >= (top.baseScore or top.score or 0) * MODE.CHAIN_MIN then top = m; break end
        end
    end
    -- (still locked here: with Story Only on, that act is all there is, and the game's own Next checks it. If it says no, the lobby takes over after 30 s)
    if not top and nextAct and CFG.onlyStory and (CFG.pickStory == "" or CFG.pickStory == "progress") and MT.ld._difficulty == "Normal" and not MODE.done((C.prof() or {}).level_data or {}, nextAct, "Normal") then
        local k = "st:" .. nextAct .. ":Normal"
        top = { key = k, kind = "story", first = true, level = nextAct, diff = "Normal", label = MODE.levelName(nextAct) .. " (Normal)", rec = MODE.rec(k) }
    end
    local vote, why = "lobby", "back to the lobby"
    local replayable = (MT.ld._gamemode == "story" or MT.ld._gamemode == "infinite" or (MT.kind == "event" and MT.ld._OVERRIDE_CAN_REPLAY)) and won
    if not CFG.play or not CFG.master then vote, why = "stay", "Auto Play is off"
    elseif top and top.key == key and replayable then vote, why = "replay", "replaying: still the best mode"
    elseif top and top.kind == "story" and MT.ld._is_actual_storymode and won then
        local okN, nxt = pcall(C.PSC.get_next_story_level, MT.ld.id)
        if okN and nxt == top.level and top.diff == MT.ld._difficulty then vote, why = "next_story", "next act: " .. top.label end
    end
    if vote ~= "replay" and vote ~= "next_story" and top then why = "lobby for: " .. top.label end
    -- takedown training: replay only the mode it was checked for, while the trainee still needs takedowns. A trainee with all it needs goes to the lobby, where it evolves. Next needs no
    -- lobby for the team: the next match sorts it out before its first wave (MT.startTeam)
    local on = B.train.on
    if on and MT.trainee and (vote == "replay" or vote == "next_story") and TRAIN.realHave(on) >= on.need then
        vote, why = "lobby", "lobby: " .. UNIT.name(on.id) .. " has its " .. tostring(on.what) .. ", your own team goes back in"
    end
    -- a dungeon room: the next room goes straight from this results screen while the dungeon is still first (the
    -- game takes any room on offer here, but in the lobby only the one it has selected)
    -- (a lost try always goes through the lobby: DG.planTeam looks again there. The room stays selected, so it's the same room again. It used to skip that with Auto-Equip Best
    -- Team off: 7 lost tries on Oct 31 without one look. A team with an empty slot goes through it too. A planned team doesn't need to: the next room starts with the team it wants)
    -- (a hold: back to the lobby, and nothing starts there until it's cleared)
    if B.holdLobby and vote ~= "stay" then vote, why = "lobby", "lobby: held there: " .. tostring(B.holdLobby.why) end
    -- (a trial's next unit goes on in the lobby, and after the last one so does your own team)
    if MT.trialId and vote ~= "stay" then vote, why = "lobby", B.trial and "lobby: the next trial run" or "lobby: your own team goes back in" end
    if B.buyStorage and vote ~= "stay" then vote, why = "lobby", "lobby: buying the unit storage you agreed" end
    if B.buyOnce and vote ~= "stay" then vote, why = "lobby", "lobby: buying the " .. tostring((C.Items[B.buyOnce.item] or {}).name or B.buyOnce.item) .. " you agreed" end
    -- (the Team tab can only work in the lobby: the run goes through it when there's something to do, and it finishes before the next room. Your call, Oct 31, and for the Next button Nov 1)
    local teamWork
    if ((MT.kind == "dungeon" and won) or vote == "next_story" or vote == "replay") and vote ~= "stay" then
        local okW, w = pcall(STR.hasWork)
        if okW then teamWork = w else SF.log(1, "ERROR", "team work: " .. tostring(w)) end
        if teamWork then vote, why = "lobby", "lobby: the Team tab can " .. tostring(teamWork) end
    end
    if MT.kind == "dungeon" and vote ~= "stay" and top and top.key == "dg" and won and #UNIT.equipped() >= 6 and not B.holdLobby and not B.buyStorage and not teamWork then
        B.pending = nil
        SF.saveNow()
        SF.status("Match", "next dungeon room")
        local okC, entered = pcall(DG.chain)
        if not okC then SF.log(1, "ERROR", "dungeon next room: " .. tostring(entered)) end
        if okC and entered then return end
        B.startTeam = nil
        vote, why = "lobby", "lobby: the next dungeon room didn't start from here"
    end
    B.pending = (vote == "replay" or vote == "next_story") and { key = top.key, kind = top.kind, level = top.level, diff = top.diff, label = top.label, at = os.time() } or nil
    -- (the next act's team, decided as it starts: the training team when the simulator says it still wins there, else your own)
    if vote == "next_story" then
        B.startTeam = { train = { key = top.key, kind = top.kind, first = top.first, level = top.level, diff = top.diff, label = top.label }, why = "next act: " .. tostring(top.label) }
    end
    SF.saveNow()
    SF.status("Match", why)
    SF.log(1, "MODE", why)
    if vote == "stay" then return end
    task.wait(2.5)
    if vote == "replay" or vote == "next_story" then
        local s2c = RS.endpoints.server_to_client
        local started, ready = false, false
        local c1 = s2c.match_rematch_started.OnClientEvent:Connect(function() started = true end)
        local c2 = s2c.match_rematch_ready.OnClientEvent:Connect(function() ready = true end)
        table.insert(SF.conns, c1)
        table.insert(SF.conns, c2)
        SF.request("vote", "set_game_finished_vote", vote)
        local t1 = U.now()
        while SF.alive and U.now() - t1 < 30 and not started do task.wait(0.25) end
        -- since the Summer update a replay can restart right here, with no teleport to bring in a fresh copy: the game's loading screen, then this file again, as after a teleport
        if started then
            local t2 = U.now()
            while SF.alive and U.now() - t2 < 60 and not ready do task.wait(0.25) end
            if SF.alive then
                SF.log(1, "MODE", string.format("the match restarted in place in %.0f s (%s)", U.now() - t1, vote))
                local okR, eR = pcall(SF.restart)
                if okR then return end
                SF.log(1, "ERROR", "couldn't start again in place: " .. tostring(eR))
            else return end
        end
    end
    if SF.alive then SF.request("lobby", "teleport_back_to_lobby") end
end
-- a team change inside the match, before its first wave: the user's find, Nov 1, "you can do at the start of the match if you don't skip". Tested that night: launched with Elyssia, swapped
-- before the first wave, and Windsong was the one on the field. The farm's start vote waits for this, and the team this match plays is read after it
function MT.startTeam()
    local want = B.startTeam
    if type(want) ~= "table" then return end
    B.startTeam = nil
    SF.saveSoon()
    SF.listenGame()
    -- (Next or the door didn't lead here: the plan was for another act or room)
    if want.train and want.train.key ~= MT.key then return end
    if want.seed and tostring(B.dg.room and B.dg.room.seed) ~= tostring(want.seed) then return end
    -- a team it must have (a dungeon room): no wave starts on the wrong one, and the lobby takes over. Leaving a room hasn't cost a try
    local function leave(whyNot)
        MT.noBuy = true
        B.pending = nil
        SF.log(1, "TEAM", string.format("%s: no wave started, back to the lobby (%s)", tostring(whyNot), tostring(want.why)))
        SF.saveNow()
        for _ = 1, 3 do
            SF.request("lobby", "teleport_back_to_lobby")
            local t1 = U.now()
            while SF.alive and U.now() - t1 < 5 do task.wait(0.5) end
        end
    end
    if workspace._DATA.GameStarted.Value then
        SF.log(1, "TEAM", "too late for a team change before the first wave: " .. tostring(want.why))
        if want.must and not TRAIN.same(TRAIN.team(), want.uuids) then leave("the first wave had already started") end
        return
    end
    local t0 = U.now()
    local before = TRAIN.team()
    local ok, e = pcall(function()
        if want.train then
            want.train.rec = MODE.rec(want.train.key)
            -- (a fresh search here too, shorter: the first wave is waiting)
            if CFG.autoTeam then HUB.teamFor(want.train, 10) end
            TRAIN.apply(want.train)
        elseif want.home then TRAIN.home()
        elseif want.own then HUB.restoreTeam()
        else HUB.equipTeam(want.uuids, tostring(want.why)) end
    end)
    local now = TRAIN.team()
    local changed = not TRAIN.same(before, now)
    local said = SF.gameSaid(t0)
    if changed or not ok or said then
        SF.log(1, "TEAM", string.format("team change before the first wave (%s): %s in %.1f s%s%s", tostring(want.why), changed and "the game took it" or "nothing changed", U.now() - t0,
            said and (" · the game said: " .. tostring(said)) or "", ok and "" or (" · error: " .. tostring(e))))
    end
    if want.must then
        if not ok or #now < 6 or not TRAIN.same(now, want.uuids) then
            leave(string.format("the team for this room didn't go on (%d of 6 units right)", (function() local n = 0; for _, u in ipairs(now) do if table.find(want.uuids, u) then n = n + 1 end end; return n end)()))
            return false
        end
        -- (the team is right: now the relics that suit it, as the lobby does before a room)
        local okRl, eRl = pcall(STR.relicsApply)
        if not okRl then SF.log(1, "ERROR", "relics: " .. tostring(eRl)) end
    end
    return changed
end
function MT.run()
    SF.status("Match", "loading the map")
    local t0 = U.now()
    while SF.alive and not (C.Loader.LevelData and workspace:FindFirstChild("_MAP_CONFIG") and workspace._MAP_CONFIG:FindFirstChild("MapLoaded") and workspace._MAP_CONFIG.MapLoaded.Value) do
        if U.now() - t0 > 60 then break end
        task.wait(0.5)
    end
    MT.ld = C.Loader.LevelData or {}
    MT.key, MT.kind = MODE.fromLevelData(MT.ld)
    MT.key = MT.key or "?"
    -- (a run of the map that drops portals, replayed in place with no lobby between: the run before is counted now, and this one from here — HUB.watchDone. Shibuya's first
    -- run dropped 2 portals on Nov 2 and was replayed at once, where the count waits for the lobby)
    if B.watch and B.watch.key == MT.key and os.time() - (tonumber(B.watch.at) or 0) > 120 then
        pcall(HUB.watchDone)
        for pid, pt in pairs(MODE.PORTALS) do
            if MT.key == "inf:" .. pt.from then B.watch = { key = MT.key, portal = pid, item = pt.item, have = ADV.have(pt.item), held = #MODE.portalsHeld(pid), used = false, at = os.time() } end
        end
    end
    MT.noSpot, MT.refusedRun, MT.unitRefusals = {}, {}, {}
    MT.style, MT.styleSig = nil, nil
    MT.refusals = 0
    MT.startClock = os.clock()
    MT.startT = U.now()
    MT.placeLog, MT.styleWhy = {}, nil
    MT.joinedMid = (workspace._DATA.GameStarted.Value and MT.wave() > 2) or workspace._DATA.GameFinished.Value
    -- the mode's weak / strong elements (daily challenge, contracts, level data)
    local mod = { weak = {}, strong = {} }
    for _, w in pairs(MT.ld._weak_against or MT.ld.weak_against or {}) do
        if type(w) == "table" then mod.weak[w.damage_type] = tonumber(w.amplification) or 1.5 else mod.weak[w] = 1.5 end
    end
    for _, s in pairs(MT.ld._strong_against or MT.ld.strong_against or {}) do mod.strong[type(s) == "table" and s.damage_type or s] = true end
    if MT.key == "dc" and B.live.daily and B.live.daily.mod then mod = B.live.daily.mod end
    MT.mod = (next(mod.weak) or next(mod.strong)) and mod or MODE.levelMod(MT.ld.id)
    if MT.mod and MT.mod.res then
        local said = {}
        for t, v in pairs(MT.mod.weak) do table.insert(said, string.format("%s ×%.1f", (t:gsub("_damage", "")), v)) end
        for t, v in pairs(MT.mod.res) do table.insert(said, string.format("%s ×%.2f", (t:gsub("_damage", "")), v)) end
        table.sort(said)
        SF.log(1, "MATCH", "this level's weak points, weighted by enemy HP: " .. table.concat(said, ", "))
    end
    MT.buildPath()
    MT.buildWaves()
    MT.setupChecks()
    MT.buildCandidates()
    -- a mode that deals its own team (Fool's Hunt) plays the dealt units, not yours (MT.randomTeam)
    MT.random = MT.ld._randomequippedmode ~= nil or C.session().override_equipped_units ~= nil
    MT.hunt = HUNT.is(MT.ld.id)
    if not MT.random then
        local okT, eT = pcall(MT.startTeam)
        if not okT then SF.log(1, "ERROR", "team change at the start: " .. tostring(eT)) end
    end
    MT.team = MT.random and MT.randomTeam() or UNIT.equipped()
    if MT.random then SF.log(1, "MATCH", "this mode deals its own team: " .. #MT.team .. " units in hand") end
    pcall(MT.watchHelpers)
    -- a trial run (MODE.trialRow): it stands where it covers most road, with no search for the rest of the team
    MT.trialId = nil
    do
        local tr = B.trial
        local want = type(tr) == "table" and type(tr.list) == "table" and tr.key == MT.key and not MT.joinedMid and tr.list[tonumber(tr.i) or 1]
        for _, e in ipairs(want and MT.team or {}) do if e.id == want then MT.trialId = want end end
        if MT.trialId then
            MT.style = "balanced"
            SF.log(1, "TRIAL", string.format("trial %d of %d: %s gets the yen, the rest of the team stands by", tonumber(tr.i) or 1, #tr.list, UNIT.name(want)))
        end
    end
    -- (your units' XP as the match starts: what the run paid shows in the lobby)
    MT.xp0 = {}
    for _, e in ipairs(MT.team) do if e.u and e.uuid then MT.xp0[e.uuid] = tonumber(e.u.xp) or 0 end end
    -- hidden unit stats: the game asks the server for them as the match starts (UNIT.capture keeps a copy)
    pcall(UNIT.capture)
    task.delay(15, function() local ok, e = pcall(UNIT.capture); if not ok then SF.log(1, "ERROR", "unit stats: " .. tostring(e)) end end)
    -- takedown training: the trainee the lobby swapped into this team
    MT.trainee, MT.trainTk = nil, 0
    for _, e in ipairs(MT.team) do if B.train.on and e.uuid == B.train.on.uuid then MT.trainee = e.uuid end end
    -- simulator: this mode's description, what to measure, the map's coverage, and a prediction to check later
    local chId = MT.ld._challenge or (MT.key == "dc" and B.live.daily and B.live.daily.challenge) or nil
    MT.calRun = { waveSec = {}, walk = {}, hp = {}, baseRel = {}, alive = {}, spawn = {}, spawnLast = {}, dpsAt = {}, dens = {},
        pay = {}, skip = {}, timer = {}, votes = {} }
    MT.track = setmetatable({}, { __mode = "k" })
    local okI, info = pcall(SIM.info, SIM.slim(MT.ld), MT.key, chId, MT.mod)
    MT.info = okI and info or nil
    if not okI then SF.log(1, "ERROR", "sim info: " .. tostring(info)) end
    -- a dungeon room: the run's items and curses count in the prediction and in what the room's HP is checked against
    if MT.info and MT.kind == "dungeon" then
        local okF, fx = pcall(DG.fx, DG.data())
        if okF then
            SIM.applyFx(MT.info, fx)
            local el = {}
            for k, v in pairs(MT.mod and MT.mod.weak or {}) do table.insert(el, string.format("%s ×%.2f", tostring(k):gsub("_damage", ""), v)) end
            SF.log(1, "DUNGEON", string.format("this room's effects: %s · the run's items and curses: %s", #el > 0 and table.concat(el, ", ") or "none", DG.fxText(fx)))
        end
    end
    -- the simulator picks each attacker's spot on this map before the first unit goes down (MT.econ waits for it; a
    -- dealt team has no fixed units, and Infinite has no last wave to play it out to)
    -- (what the simulator thinks the unit on trial does on its own, to hold its real damage against)
    if MT.info and MT.trialId then
        task.spawn(function()
            local solo = {}
            for _, e in ipairs(MT.team) do if e.id == MT.trialId or UNIT.isFarm(e.id) or UNIT.allyBuff(e.id) then table.insert(solo, e.u) end end
            local seen = {}
            local okS, r = pcall(SIM.run, MT.info, SIM.teamFrom(solo, MT.info.map), { hpMul = 1, dealt = seen })
            if okS and r then MT.trialSim = { won = r.won, wave = r.wave, dealt = (seen[UNIT.name(MT.trialId)] or 0) + (seen.drones or 0), lvl = r.levels and r.levels[MT.trialId] } end
        end)
    end
    if MT.info and CFG.simSpots and not MT.joinedMid and not MT.random and not MT.infinite and not MT.trialId then
        MT.planning = U.now()
        task.spawn(function()
            local okP, eP = pcall(MT.planSpots)
            MT.planning = nil
            if not okP then SF.log(1, "ERROR", "spot search: " .. tostring(eP)) end
        end)
    end
    -- wave pay, the moment a wave ends: real yen ÷ (listed yen × money scale), the farm units' pay taken out
    MT.lastRes = MT.money()
    table.insert(SF.conns, LP._stats.resource.Changed:Connect(function(v)
        v = tonumber(v) or 0
        local d = v - (MT.lastRes or v)
        MT.lastRes = v
        local r = MT.calRun
        if d <= 0 or not (r and MT.info) then return end
        local raw = SIM.waveYen(MT.info, MT.wave(), MT.info.payBase)
        local farm = MT.farmNow or 0
        if raw > 0 and d >= 0.5 * (raw + farm) then
            table.insert(r.pay, (d - farm) / raw)
            r.paidT = U.now()
        end
    end))
    task.spawn(function() local ok, e = pcall(MT.recordMap); if not ok then SF.log(1, "ERROR", "map record: " .. tostring(e)) end end)
    if MT.info and not MT.joinedMid and not MT.random then
        task.spawn(function()
            task.wait(5)
            local units = {}
            for _, e in ipairs(MT.team) do table.insert(units, e.u) end
            -- (with the spots the search chose, when it's done by now)
            local waited = U.now()
            while MT.planning and U.now() - waited < 20 do task.wait(0.5) end
            local ok, r = pcall(SIM.run, MT.info, SIM.teamFrom(units, MT.info.map), { hpMul = 1, train = MT.trainee, layout = MT.layoutSim })
            if ok then
                MT.pred = r
                SF.log(1, "SIM", MT.infinite and string.format("prediction for this run: the base falls at wave %d%s (%.0f min)", r.wave, r.won and "+" or "", r.t / 60)
                    or string.format("prediction for this run: %s at wave %d", r.won and "win" or "loss", r.wave))
            end
        end)
    end
    -- server events: the result, roguelike options
    local s2c = RS.endpoints.server_to_client
    table.insert(SF.conns, s2c.game_finished.OnClientEvent:Connect(function(settings) MT.result = settings end))
    table.insert(SF.conns, s2c.show_roguelike_options.OnClientEvent:Connect(function(_, opts) MT.rogueOptions = opts end))
    -- a roguelike vote's result: the coin multiplier now and every effect in play (the run record keeps them)
    if s2c:FindFirstChild("show_roguelike_vote_result") then
        table.insert(SF.conns, s2c.show_roguelike_vote_result.OnClientEvent:Connect(function(picked, info)
            if type(info) == "table" then
                MT.fhMult = 1 + (tonumber(info.candy_multiplier) or 0)
                local fx, res = {}, {}
                for _, ef in pairs(info.persistent_effects or {}) do
                    if type(ef) == "table" then
                        table.insert(fx, MT.effectText(ef) .. (ef.damage_type and (" " .. tostring(ef.damage_type)) or ""))
                        if ef.type == "enemy_resistance_specific" and ef.damage_type then
                            res[ef.damage_type] = (res[ef.damage_type] or 0) + (tonumber(ef.amount) or 0)
                        end
                    end
                end
                MT.fhEffects, MT.fhResist = fx, res
            end
            MT.fhPicks = MT.fhPicks or {}
            table.insert(MT.fhPicks, string.format("w%d %s", MT.wave(), tostring(type(picked) == "table" and (picked.title or picked.name) or picked)))
        end))
    end
    -- the skip vote opening: seconds into the wave, enemies alive, the wave all out yet (the sim's wave timing)
    if s2c:FindFirstChild("start_vote_wave_skip") then
        table.insert(SF.conns, s2c.start_vote_wave_skip.OnClientEvent:Connect(function()
            local r = MT.calRun
            if not (r and r.lastWT and MT.info) then return end
            local w = MT.wave()
            local n = #(SIM.wave(MT.info, w))
            table.insert(r.votes, { w = w, t = U.now() - r.lastWT, n = n, alive = #(MT.enemies or {}), out = (tonumber(r.spawn[tostring(w)]) or 0) >= n })
        end))
    end
    local label = MT.label()
    SF.log(1, "MATCH", string.format("%s · %d waves · %d road samples · %d spots to try%s", label, MT.total, #MT.samples, #MT.cands, MT.joinedMid and " · joined mid-way" or ""))
    SF.status("Match", label .. (B.pending and B.pending.key == MT.key and "" or " (not launched by the farm)"))
    local voted, lastWave, lastWaveAt = false, -1, U.now()
    while SF.alive do
        if CFG.master and CFG.battle then
            local ok, e = pcall(function()
                MT.scan()
                local okM, eM = pcall(MT.measure)
                if not okM and HUB.every("measErr", 30) then SF.log(1, "ERROR", "measure: " .. tostring(eM)) end
                if workspace._DATA.GameFinished.Value then MT.finish(); return end
                if CFG.autoStart and not voted and not MT.noBuy and not workspace._DATA.GameStarted.Value and (#MT.mine > 0 or U.now() - t0 > 6) then
                    voted = true
                    SF.request("vstart", "vote_start")
                end
                local rg = workspace._DATA:FindFirstChild("Roguelike")
                if rg and rg:FindFirstChild("WaitingForRoguelikeChoice") and rg.WaitingForRoguelikeChoice.Value and HUB.every("rogue", 3) then MT.pickRogue() end
                if not MT.infinite and HUB.every("lastCash", 2) then
                    local okL, eL = pcall(MT.lastWaveCash)
                    if not okL and HUB.every("lastCashErr", 30) then SF.log(1, "ERROR", "last-wave cash-in: " .. tostring(eL)) end
                end
                if MT.random and HUB.every("adapt", 2) then
                    local okA, eA = pcall(MT.adapt)
                    if not okA and HUB.every("adaptErr", 60) then SF.log(1, "ERROR", "adaptation: " .. tostring(eA)) end
                end
                if MT.random and HUB.every("watch", 45) then
                    local okW, eW = pcall(MT.watchLine)
                    if not okW and HUB.every("watchErr", 60) then SF.log(1, "ERROR", "watch line: " .. tostring(eW)) end
                end
                if MT.random and HUB.every("merge", 1) then
                    local okG, eG = pcall(MT.mergeScan)
                    if not okG and HUB.every("mergeErr", 30) then SF.log(1, "ERROR", "merge plan: " .. tostring(eG)) end
                end
                if HUB.every("bossStep", 1) then
                    local okB, eB = pcall(MT.bossStep)
                    if not okB and HUB.every("bossErr", 30) then SF.log(1, "ERROR", "boss step: " .. tostring(eB)) end
                end
                if not MT.stopping then MT.econ() end
                if HUB.every("act", 0.5) then MT.actives() end
                if HUB.every("prio", 2) then local okT, eT = pcall(MT.targeting); if not okT and HUB.every("prioErr", 30) then SF.log(1, "ERROR", "targeting: " .. tostring(eT)) end end
                if MT.trainee and HUB.every("train", 2) then pcall(MT.trainCount) end
                if MT.random and HUB.every("dealt", 2) then MT.team = MT.randomTeam() end
                -- (dealt units' hidden stats arrive as they're dealt, not only at the start)
                if MT.random and HUB.every("dealtStats", 30) then pcall(UNIT.capture) end
                if MT.random and HUB.every("room", 3) then
                    local okR, eR = pcall(MT.makeRoom)
                    if not okR and HUB.every("roomErr", 30) then SF.log(1, "ERROR", "make room: " .. tostring(eR)) end
                    local okD, eD = pcall(MT.refund)
                    if not okD and HUB.every("refundErr", 30) then SF.log(1, "ERROR", "refund: " .. tostring(eD)) end
                    local okF, eF = pcall(MT.fish)
                    if not okF and HUB.every("fishErr", 30) then SF.log(1, "ERROR", "card fishing: " .. tostring(eF)) end
                end
                if CFG.actives and HUB.every("spells", 1) then
                    local okS, eS = pcall(MT.spells)
                    if not okS and HUB.every("spellErr", 30) then SF.log(1, "ERROR", "spells: " .. tostring(eS)) end
                end
                -- watchdog: no wave change for 6 min → leave
                local w = MT.wave()
                if MT.random and w ~= MT.fhWaveSeen then MT.fhWaveSeen = w; pcall(MT.fhSnap) end
                if w ~= lastWave then lastWave, lastWaveAt = w, U.now(); if MT.infinite then pcall(MT.infWave, w) end end
                -- (not out of a fight on the last wave: a final boss took over 6 min, at half HP the watchdog walked out of
                -- the match and threw the room away. It still leaves after 30 min, or if nothing is alive to fight)
                -- (and not the moment the road empties: a boss reaching the base left none for a few seconds, and the farm
                -- walked out just before the game's own result, so a lost try was never counted)
                local alive = #(MT.enemies or {})
                if alive > 0 then MT.emptyAt = nil elseif not MT.emptyAt then MT.emptyAt = U.now() end
                local fighting = MT.total and w >= MT.total and (alive > 0 or U.now() - MT.emptyAt < 30)
                if workspace._DATA.GameStarted.Value and U.now() - lastWaveAt > (fighting and 1800 or 360) then
                    SF.log(1, "MATCH", string.format("no progress for %d min — back to the lobby", fighting and 30 or 6))
                    SF.flush() -- (the teleport kills the script: this line was lost when it mattered)
                    lastWaveAt = U.now()
                    SF.request("lobby", "teleport_back_to_lobby")
                end
            end)
            if not ok then SF.log(1, "ERROR", "match loop: " .. tostring(e)) task.wait(1) end
        end
        if MT.finished then break end
        task.wait(0.3)
    end
end

-- ============================================================
--  ANONYMOUS STATS (hive) — queued; sent only once a webhook is connected
-- ============================================================
function REPORT.record(r)
    r.v = VERSION
    r.at = os.time()
    table.insert(B.hiveQueue, r)
    while #B.hiveQueue > 50 do table.remove(B.hiveQueue, 1) end
    -- (not sent: the match records, REPORT.match, carry all of this and more)
end
-- the brain hive's match record (the user, Nov 2: "capture sims per match, place, smart placement, how long the match took, damage, if with other players in game, unit
-- data"). One line a match in AA_SmartFarm/hive/matches_N.jsonl (500 a file), kept on this PC: nothing here is sent anywhere. No player names: other players are a count
function REPORT.match(x)
    local others, otherUnits = #game:GetService("Players"):GetPlayers() - 1, 0
    for _, m in ipairs(workspace._UNITS:GetChildren()) do
        local st = m:FindFirstChild("_stats")
        local pl = st and st:FindFirstChild("player")
        local par = st and st:FindFirstChild("parent_unit")
        if pl and pl.Value ~= nil and pl.Value ~= LP and not (par and par.Value) then otherUnits = otherUnits + 1 end
    end
    -- the team: level, trait, relic, skin, copies that stood, top upgrade, damage, its summons' damage, takedowns of the copies still standing
    local by = {}
    local function get(id) by[id] = by[id] or { dealt = 0, copies = 0, top = 0 }; return by[id] end
    for _, o in pairs(MT.ownDealt or {}) do local t = get(o.id); t.dealt = t.dealt + (o.v or 0); t.copies = t.copies + 1; t.top = math.max(t.top, o.lvl or 0) end
    for _, h in pairs(MT.helperDealt or {}) do if h.owner then local t = get(h.owner); t.helpers = (t.helpers or 0) + (h.v or 0) end end
    for _, m in ipairs(MT.mine or {}) do
        local st = m:FindFirstChild("_stats")
        local tk = st and st:FindFirstChild("takedown_count")
        if st and st:FindFirstChild("id") and tk then local t = get(st.id.Value); t.tk = (t.tk or 0) + (tonumber(tk.Value) or 0) end
    end
    local team = {}
    for _, e in ipairs(MT.team or {}) do
        local t = by[e.id] or {}
        -- (eff: this match's damage share against the formula's, MT.learn: the hive's read on how far the simulator is off for a unit)
        table.insert(team, { id = e.id, lvl = STR.level(e.u), trait = (UNIT.trait(e.u)), relic = UNIT.relicName(e.u), skin = e.u.skin and e.u.skin._skin_id or nil,
            copies = t.copies or 0, top = t.top or 0, dealt = math.floor(t.dealt or 0), helpers = t.helpers and math.floor(t.helpers) or nil, tk = t.tk,
            eff = MT.lastEff and MT.lastEff[e.id] or nil })
    end
    -- each wave's start: real HP alive and team damage a second, beside the simulator's for this run (its prediction at the start)
    local waves = {}
    local r, pr = MT.calRun or {}, MT.pred or {}
    local function num(tb, w) return math.floor(tonumber(tb and (tb[w] or tb[tostring(w)])) or 0) end
    for w = 1, MT.wave() do table.insert(waves, { w, num(r.alive, w), num(r.dpsAt, w), num(pr.aliveAt, w), num(pr.dpsAt, w) }) end
    local plan = {}
    for id, list in pairs(MT.layout or {}) do if list[1] then plan[id] = { math.floor(list[1].X), math.floor(list[1].Z) } end end
    local sr = B.simRes[x.key] or {}
    local rec = {
        v = VERSION, at = os.time(), mode = x.key, kind = MT.kind, level = MT.ld.id, map = MT.ld.map, diff = MT.ld._difficulty,
        challenge = MT.ld._challenge or (MT.key == "dc" and B.live.daily and B.live.daily.challenge) or nil,
        portal = MT.kind == "portal" and B.portalMods or nil, weather = HUNT.is(MT.ld.id) and HUNT.weatherNow() or nil,
        players = others, otherUnits = otherUnits, joinedMid = MT.joinedMid or nil, lanes = MT.laneCount and MT.laneCount.n or 1,
        result = { won = x.won and true or false, wave = MT.wave(), total = MT.total, sec = math.floor(tonumber(x.sec) or 0), gems = x.gems, coins = x.coins, spent = math.floor(MT.spent or 0), refused = MT.refusals or 0,
            items = (type(x.items) == "table" and next(x.items)) and x.items or nil },
        sim = { pred = MT.pred and { won = MT.pred.won, wave = MT.pred.wave, min = math.floor((MT.pred.t or 0) / 6) / 10 } or nil, p = sr.p, margin = sr.playing or sr.margin,
            trust = sr.trust and sr.trust.ratio or nil, style = MT.style, why = MT.styleWhy, hpCal = MT.info and MT.info.cal and MT.info.cal.hpCal or nil, hpRun = MT.hpRun },
        team = team, placed = MT.placeLog, plan = plan, waves = waves, trainee = MT.trainee and B.train.on and B.train.on.id or nil,
        trial = MT.trialId,
        -- (switch abilities seen this match, MT.learnToggle: other players' farms learn them through the hive before they ever play the unit)
        toggles = (function()
            local t
            for id in pairs(MT.togglesSeen or {}) do
                local x = B.toggles[id]
                if x then t = t or {}; t[id] = { from = x.from, fill = math.floor((x.fill or 0) * 100 + 0.5) / 100, drain = math.floor((x.drain or 0) * 100 + 0.5) / 100 } end
            end
            return t
        end)(),
        -- (the unit in training's own count this match, MT.trainCount: what other players' farms read to pick where to train)
        traineeTk = MT.trainee and B.train.on and MT.trainTk or nil, trainWhat = MT.trainee and B.train.on and B.train.on.what or nil,
    }
    B.hiveN = (tonumber(B.hiveN) or 0) + 1
    local dir = C.FOLDER .. "/hive"
    pcall(makefolder, dir)
    local f = string.format("%s/matches_%d.jsonl", dir, math.floor((B.hiveN - 1) / 500) + 1)
    local line = U.json(rec) .. "\n"
    if appendfile and isfile and isfile(f) then pcall(appendfile, f, line)
    else local okR, old = pcall(readfile, f); pcall(writefile, f, (okR and old or "") .. line) end
    -- and to the Brain Hive's Discord channel, Candy Kingdom's webhook and bot (the user, Nov 2), as its own "🎌 AA" records the bot keeps apart. Settings → Share anonymous stats
    if CFG.shareStats and C.WEBHOOK_URL ~= "" then
        rec.id = B.anonId
        table.insert(B.aaHiveQ, REPORT.fit(rec))
        while #B.aaHiveQ > 30 do table.remove(B.aaHiveQ, 1) end
        task.spawn(function() pcall(REPORT.sendHive) end)
    end
    SF.saveSoon()
end
-- a match record in one Discord embed (4,096 characters): the per-wave rows thin out first, then the placements' reasons, then the placements
function REPORT.fit(rec)
    local j = U.json(rec)
    if #j <= 3900 then return j end
    for _, step in ipairs({ 2, 5, 10 }) do
        local thin = {}
        for i, wv in ipairs(rec.waves or {}) do if i % step == 0 or i == #rec.waves then table.insert(thin, wv) end end
        rec.waves = thin
        j = U.json(rec)
        if #j <= 3900 then return j end
    end
    for _, p in ipairs(rec.placed or {}) do p.why = nil end
    j = U.json(rec)
    if #j <= 3900 then return j end
    rec.placed, rec.plan = nil, nil
    return U.json(rec):sub(1, 3900)
end
function REPORT.postEmbed(title, description)
    local req = (syn and syn.request) or (http and http.request) or http_request or request
    if not req or C.WEBHOOK_URL == "" then return false end
    local ok, res = pcall(req, { Url = C.WEBHOOK_URL, Method = "POST", Headers = { ["Content-Type"] = "application/json" },
        Body = U.json({ username = "Smart Farm reports", allowed_mentions = { parse = {} }, embeds = { { title = title, description = description, color = 15418782 } } }) })
    local code = ok and type(res) == "table" and tonumber(res.StatusCode or res.Status) or nil
    return ok and (not code or code < 300)
end
-- one queued match record a call, oldest first; one that fails waits for the next try (the lobby tries every minute)
function REPORT.sendHive()
    if not (CFG.shareStats and C.WEBHOOK_URL ~= "") or #B.aaHiveQ == 0 or REPORT.sending then return end
    REPORT.sending = true
    local okP, sent = pcall(REPORT.postEmbed, string.format("🎌 AA · match · %s · v%s", tostring(B.anonId), VERSION), "```json\n" .. B.aaHiveQ[1] .. "\n```")
    REPORT.sending = nil
    if okP and sent then
        table.remove(B.aaHiveQ, 1)
        B.hiveSent = (tonumber(B.hiveSent) or 0) + 1
        SF.saveSoon()
    end
end
function REPORT.post(content)
    local req = (syn and syn.request) or (http and http.request) or http_request or request
    if not req then return false, "no http" end
    local ok, res = pcall(req, { Url = C.WEBHOOK_URL, Method = "POST", Headers = { ["Content-Type"] = "application/json" },
        Body = U.json({ content = content, allowed_mentions = { parse = {} } }) })
    return ok and res and (res.StatusCode == 200 or res.StatusCode == 204), res
end
function REPORT.flush()
    if C.WEBHOOK_URL == "" or not CFG.shareStats or #B.hiveQueue == 0 then return false, "not connected" end
    local ok = REPORT.post("📊 AA " .. U.json({ id = B.anonId, v = VERSION, runs = B.hiveQueue }))
    if ok then table.clear(B.hiveQueue); SF.saveSoon() end
    return ok
end
-- the brain hive read back (the user, Nov 2: "how will I be able to train units from the data I get from other people's units"). aa_combine.py on the bot's PC turns every farm's match
-- records into combined numbers (no ids or names) at C.HIVE_URL; this copy keeps the last one in AA_SmartFarm/hive_shared.json. Your own runs always come first: the hive only fills in
-- what you haven't measured yet. units[id].eff = how far the formula is off for a unit (UNIT.nudge), train[mode] = takedowns a run for a unit in training (TRAIN.perRun, TRAIN.bestInfinite),
-- under = units the simulator reads far too low (a trial run would show it), modes = everyone's runs, wins and waves
REPORT.HIVE_FILE = C.FOLDER .. "/hive_shared.json"
function REPORT.hive()
    if not CFG.useHive then return nil end
    if REPORT.shared == nil then
        local h = U.readJson(REPORT.HIVE_FILE)
        REPORT.shared = type(h) == "table" and type(h.units) == "table" and h or false
    end
    return REPORT.shared or nil
end
function REPORT.hiveUnit(id)
    local h = REPORT.hive()
    local u = h and h.units[id]
    if type(u) == "table" and (tonumber(u.eff) or 0) > 0 and ((tonumber(u.matches) or 0) >= 5 or (tonumber(u.players) or 0) >= 2) then return u end
end
-- takedowns a run there for a unit in training: that unit's own count when 3 runs have it, else any trainee's
function REPORT.hiveTrain(key, id)
    local h = REPORT.hive()
    local row = h and type(h.train) == "table" and h.train[key]
    if type(row) ~= "table" then return nil end
    local u = id and type(row.units) == "table" and row.units[id]
    if type(u) == "table" and (tonumber(u.runs) or 0) >= 3 then return tonumber(u.perRun) end
    if (tonumber(row.runs) or 0) >= 3 then return tonumber(row.perRun) end
end
-- a unit other players' farms have seen with a switch ability and a bar ({from, fill, drain, players}): this farm treats it as one before it ever plays it (UNIT.toggleOf)
function REPORT.hiveToggle(id)
    local h = REPORT.hive()
    local t = h and type(h.toggles) == "table" and h.toggles[id]
    return type(t) == "table" and t or nil
end
-- a hidden unit's real upgrade table, from a farm that played it (the game's own numbers: UNIT.field puts it after yours and before the community's)
function REPORT.hiveStat(id)
    local h = REPORT.hive()
    local t = h and type(h.stats) == "table" and h.stats[id]
    return type(t) == "table" and t or nil
end
-- how much tougher a mode's enemies really are than the formula, from every farm's runs there (3 at least): the simulator's start on a map this farm hasn't calibrated
function REPORT.hiveHp(key)
    local h = REPORT.hive()
    local m = h and type(h.maps) == "table" and h.maps[key]
    return type(m) == "table" and (tonumber(m.runs) or 0) >= 3 and tonumber(m.hpCal) or nil
end
-- what a level's runs really dropped, per run, by item (3 runs at least): {item = amount}
function REPORT.hiveDrops(levelId)
    local h = REPORT.hive()
    local d = levelId and h and type(h.drops) == "table" and h.drops[levelId]
    if type(d) ~= "table" or (tonumber(d.runs) or 0) < 3 or type(d.items) ~= "table" then return nil end
    return d.items
end
-- the hidden stats this farm learned in its matches (B.unitData: the game's own numbers, sent only in a match) go to the brain hive, one a minute, the ones it doesn't have
-- yet: every farm then knows a unit's real upgrades before it ever plays it (the user, Nov 2: "What one farm learns, every farm knows")
function REPORT.sendUnit()
    if not (CFG.shareStats and C.WEBHOOK_URL ~= "") or REPORT.sending then return end
    local h = REPORT.hive()
    local have = h and type(h.stats) == "table" and h.stats or {}
    for id, data in pairs(B.unitData) do
        if not B.unitSent[id] and not have[id] and type(data) == "table" and data.upgrade then
            local okJ, j = pcall(U.json, { id = id, data = data })
            if okJ and #j <= 3900 then
                REPORT.sending = true
                local okP, sent = pcall(REPORT.postEmbed, string.format("🎌 AA · unit · %s · v%s", tostring(B.anonId), VERSION), "```json\n" .. j .. "\n```")
                REPORT.sending = nil
                if okP and sent then B.unitSent[id] = os.time(); SF.saveSoon() end
            else
                B.unitSent[id] = -1 -- (too big for one post)
                SF.saveSoon()
            end
            return
        end
    end
end
function REPORT.hiveTrainRate(key)
    local h = REPORT.hive()
    local row = h and type(h.train) == "table" and h.train[key]
    return type(row) == "table" and (tonumber(row.runs) or 0) >= 3 and tonumber(row.perMin) or nil
end
-- the newest combined file (every 6 h from the lobby). Not published yet: nothing changes
function REPORT.hiveFetch()
    if not CFG.useHive then return end
    local okG, body = pcall(game.HttpGet, game, C.HIVE_URL .. "?t=" .. os.time())
    if not okG or type(body) ~= "string" or body:sub(1, 1) ~= "{" then return end
    local okD, h = pcall(Http.JSONDecode, Http, body)
    if not (okD and type(h) == "table" and tonumber(h.v) == 1 and type(h.units) == "table") then return end
    local old = REPORT.hive()
    if old and old.updated == h.updated then return end
    pcall(U.writeJson, REPORT.HIVE_FILE, h)
    REPORT.shared = h
    -- (what's worked out from it starts over: unit rows from the shared stats, who holds enemies, where items drop)
    table.clear(UNIT._rows)
    table.clear(SIM._holds)
    ADV._src = nil
    local n, t = 0, 0
    for _ in pairs(h.units) do n = n + 1 end
    for _ in pairs(type(h.train) == "table" and h.train or {}) do t = t + 1 end
    SF.log(1, "HIVE", string.format("learned from %d players' %d matches: readings for %d units, takedown rates on %d maps", tonumber(h.players) or 0, tonumber(h.matchRecords) or 0, n, t))
    -- units you own that the simulator reads far too low by everyone's runs: say so once (a trial run checks it)
    local mine = {}
    for _, id in ipairs(type(h.under) == "table" and h.under or {}) do
        if UNIT.owns(id) and not (B.learn[id] and (B.learn[id].n or 0) >= 3) then table.insert(mine, string.format("%s (×%.1f)", UNIT.name(id), tonumber(h.units[id] and h.units[id].eff) or 0)) end
    end
    if #mine > 0 then
        SF.log(1, "HIVE", "other players' runs say the simulator reads these of yours far too low: " .. table.concat(mine, ", ") .. ". A trial run would check them")
        if SF.notify then SF.notify("Brain Hive", "Units the simulator underrates: " .. table.concat(mine, ", "), "info") end
    end
end
function REPORT.hiveText()
    if not CFG.useHive then return "Off: the farm learns only from your own runs." end
    local h = REPORT.hive()
    if not h then return "Nothing shared yet. Once other players' farms send their matches, the farm reads what they learned here every 6 hours." end
    local used, t, stats, maps, drops, tog = 0, 0, 0, 0, 0, 0
    for id in pairs(h.units) do if REPORT.hiveUnit(id) and not (B.learn[id] and (B.learn[id].n or 0) >= 3) then used = used + 1 end end
    for _ in pairs(type(h.train) == "table" and h.train or {}) do t = t + 1 end
    for id in pairs(type(h.stats) == "table" and h.stats or {}) do if not B.unitData[id] then stats = stats + 1 end end
    for key in pairs(type(h.maps) == "table" and h.maps or {}) do if REPORT.hiveHp(key) and not (B.simCal[key] and B.simCal[key].hpCal) then maps = maps + 1 end end
    for id in pairs(type(h.drops) == "table" and h.drops or {}) do if REPORT.hiveDrops(id) then drops = drops + 1 end end
    for id in pairs(type(h.toggles) == "table" and h.toggles or {}) do if not B.toggles[id] then tog = tog + 1 end end
    local lines = { string.format("From %d players' %d matches, updated %s.", tonumber(h.players) or 0, tonumber(h.matchRecords) or 0, os.date("%b %d %H:%M", tonumber(h.updated) or 0)),
        string.format("What it fills in that your own runs haven't: %d units' readings, %d hidden units' real stats, %d switch abilities, how tough %d maps really are, what %d levels really drop, and takedown rates on %d maps.",
            used, stats, tog, maps, drops, t) }
    local names = {}
    for _, id in ipairs(type(h.under) == "table" and h.under or {}) do table.insert(names, UNIT.name(id) .. (UNIT.owns(id) and " (yours)" or "")) end
    if #names > 0 then table.insert(lines, "The simulator reads these far too low: " .. table.concat(names, ", ") .. ".") end
    return table.concat(lines, "\n")
end
function REPORT.suggest(text)
    text = tostring(text or ""):sub(1, 500):gsub("https?://%S+", "[link]"):gsub("@", "(at)")
    if text:gsub("%s", "") == "" then return false, "empty" end
    if C.WEBHOOK_URL == "" then return false, "suggestions aren't connected yet" end
    if os.time() - (B.lastSuggest or 0) < 600 then return false, "one suggestion per 10 minutes" end
    local ok = REPORT.postEmbed(string.format("🎌 AA · suggestion · %s · v%s", tostring(B.anonId), VERSION), text)
    if ok then B.lastSuggest = os.time() end
    return ok, ok and nil or "send failed"
end

-- ============================================================
--  GUI (NexusLib)
-- ============================================================
function GUI.load()
    local function try(src, from)
        if type(src) ~= "string" or #src == 0 then return nil end
        local fn, err = loadstring(src)
        if not fn then warn("[AA] NexusLib (" .. from .. ") compile error: " .. tostring(err)) return nil end
        local ok, lib = pcall(fn)
        if ok and type(lib) == "table" and type(lib.Window) == "function" then return lib end
        return nil
    end
    local okR, src = pcall(function() return isfile("NexusLib.lua") and readfile("NexusLib.lua") or nil end)
    local lib = okR and try(src, "file")
    if lib then return lib end
    local ok, s = pcall(function() return game:HttpGet(C.NEXUS_URL) end)
    return ok and try(s, "url") or nil
end
GUI.SYSTEMS = { "Mode", "Match", "Economy", "Placement", "Upgrade", "Abilities", "Merge", "Targeting", "Rewards", "Gold Shop", "Summon", "Evolve", "Training", "Codes" }
GUI.lists, GUI.listSig = {}, {}
function GUI.bannerOptions()
    local out = { { text = "Pick a banner", value = "" } }
    local ids = {}
    for id, b in pairs(C.Banners or {}) do if type(b) == "table" and b.active then table.insert(ids, id) end end
    table.sort(ids)
    for _, id in ipairs(ids) do
        local bc = HUB.bannerCost(id)
        table.insert(out, { text = string.format("%s (%s)", HUB.BANNER_NAME[id] or id, bc and bc.name or "?"), value = id })
    end
    return out
end
-- Banner Snipe's list: featured now, then featured before, then every other Mythic a banner can give (not an evolved form, not limited or banner-hidden; _rateup_banner_only units, which
-- only drop while featured, like Griffin, Cherub and Faker, are what a snipe is for), units you don't have first. Your pick stays on the list
function GUI.snipeOptions()
    local out = { { text = "Pick a unit", value = "" } }
    local S = B.snipe or {}
    if not GUI.evolvedIds then
        GUI.evolvedIds = {}
        for _, d in pairs(C.Units) do
            if type(d) == "table" and type(d.evolve) == "table" and d.evolve.evolve_unit then GUI.evolvedIds[d.evolve.evolve_unit] = true end
        end
    end
    local rows, have = {}, {}
    local function add(id, tail, rank)
        if have[id] or not C.Units[id] then return end
        have[id] = true
        local owned = HUB.snipeHas(id)
        table.insert(rows, { id = id, text = UNIT.name(id) .. tail .. (owned and " · owned" or ""), key = rank * 10 + (owned and 0 or 5), name = UNIT.name(id) })
    end
    if CFG.snipeUnit ~= "" then add(CFG.snipeUnit, "", 9) end
    for bid, ids in pairs(S.feat or {}) do
        for _, id in ipairs(ids) do add(id, " · featured on " .. (HUB.BANNER_NAME[bid] or bid), 3) end
    end
    for id, s in pairs(S.seen or {}) do
        if type(s) == "table" then add(id, string.format(" · seen on %s %s", HUB.BANNER_NAME[s.banner] or tostring(s.banner), os.date("%b %d", tonumber(s.at) or os.time())), 2) end
    end
    for id, d in pairs(C.Units) do
        if type(id) == "string" and type(d) == "table" and d.rarity == "Mythic" and not d.hide_from_banner and not d.limited
            and not GUI.evolvedIds[id] and not id:find(":") then
            add(id, "", 1)
        end
    end
    table.sort(rows, function(a, b) if a.key ~= b.key then return a.key > b.key end; return a.name < b.name end)
    for _, r in ipairs(rows) do table.insert(out, { text = r.text, value = r.id }) end
    return out
end
-- your units for the Lobby tab: your team, then locked units, then Secrets and Mythics, highest level first (at most 60).
-- suffix(unit) adds to the name; false leaves the unit out
function GUI.unitOptions(selected, suffix)
    local out = { { text = "Pick a unit", value = "" } }
    local s = C.session()
    if not s then return out end
    local team = {}
    for _, e in ipairs(UNIT.equipped()) do team[e.uuid] = true end
    local rows = {}
    for uuid, u in pairs(s.profile_data.collection.owned_units) do
        local d = C.Units[u.unit_id]
        if d and (team[uuid] or u._locked or d.rarity == "Secret" or d.rarity == "Mythic" or uuid == selected) then
            local okL, lvl = pcall(C.USC.calculate_level, u.unit_id, u.xp)
            lvl = okL and tonumber(lvl) or 0
            table.insert(rows, { uuid = uuid, u = u, lvl = lvl, team = team[uuid], key = (team[uuid] and 4000 or 0) + (u._locked and 2000 or 0) + (d.rarity == "Secret" and 1000 or 0) + lvl })
        end
    end
    table.sort(rows, function(a, b) if a.key ~= b.key then return a.key > b.key end; return a.uuid < b.uuid end)
    for _, r in ipairs(rows) do
        local okT, tail = true, ""
        if suffix then okT, tail = pcall(suffix, r.u) end
        if okT and (tail ~= false or r.uuid == selected) and (#out <= 60 or r.uuid == selected) then
            table.insert(out, { text = string.format("%s · lvl %d%s%s", UNIT.name(r.u.unit_id), r.lvl, r.team and " · team" or "", type(tail) == "string" and tail or ""), value = r.uuid })
        end
    end
    return out
end
-- the units you own that can still evolve: your best copy of each (your pick stays on the list)
-- the Goals tab's Focus picker: Smart Play, the strongest, then anything else that can still evolve. A focus is CFG.evolveUnit + CFG.autoEvolve
function GUI.focusNow() return (CFG.autoEvolve and CFG.evolveUnit ~= "") and CFG.evolveUnit or "" end
function GUI.focusOptions()
    local out = { { text = "🤖 Smart Play (the farm chooses)", value = "" } }
    local have = {}
    local s0 = C.session()
    for _, g in ipairs(B.goalsTop or {}) do
        have[g.from] = true
        local u = s0 and s0.collection:get_unit_by_uuid(g.uuid)
        local okL, lvl = pcall(C.USC.calculate_level, g.from, u and u.xp or 0)
        table.insert(out, { text = string.format("%s → %s · lvl %d%s", UNIT.name(g.from), UNIT.name(g.to), okL and tonumber(lvl) or 0, g.ready and " · ready" or ""), value = g.uuid })
    end
    local s = C.session()
    if s then
        for _, o in ipairs(GUI.evolveOptions(GUI.focusNow())) do
            local u = o.value ~= "" and s.collection:get_unit_by_uuid(o.value)
            if u and not have[u.unit_id] then table.insert(out, o) end
        end
    end
    return out
end
function HUB.setFocus(uuid)
    CFG.evolveUnit = uuid or ""
    CFG.autoEvolve = CFG.evolveUnit ~= ""
    CFG.focusNext = ""
    HUB.pickNote.autoEvolve = nil
    HUB.last.goals, HUB.last.trainScan, TRAIN._at, MODE.lastScored = nil, nil, nil, nil
    -- (its items and takedowns come first from now on, and XP food counts it in: without this the core only changes once a week)
    local okR, eR = pcall(ADV.refresh)
    if not okR then SF.log(1, "ERROR", "focus goals: " .. tostring(eR)) end
    local okC, eC = pcall(STR.core, true)
    if not okC then SF.log(1, "ERROR", "focus core: " .. tostring(eC)) end
    SF.saveSoon()
end
-- what the Focus paragraph says
function HUB.focusText()
    if GUI.focusNow() ~= "" then return "Your focus. " .. HUB.evolveText() .. (CFG.focusNext ~= "" and ("\nNext up: " .. UNIT.name(CFG.focusNext) .. ", once this one has evolved.") or "") end
    local on = B.train.on
    local t = on or TRAIN.target()
    if t then return string.format("Smart Play is working on %s → %s (%s %s/%s)", UNIT.name(t.id), UNIT.name(t.to), tostring(t.what), U.fmt((tonumber(t.have) or 0) + (tonumber(t.got) or 0)), U.fmt(tonumber(t.need) or 0)) end
    local g = (B.goals or {})[1]
    if g then return "Smart Play is working on " .. UNIT.name(g.from) .. " → " .. UNIT.name(g.to) end
    return "Smart Play: goals are worked out in the lobby"
end
function GUI.evolveOptions(selected)
    local out = { { text = "Pick a unit", value = "" } }
    local s = C.session()
    if not s then return out end
    local team = {}
    for _, e in ipairs(UNIT.equipped()) do team[e.uuid] = true end
    local best = {}
    for uuid, u in pairs(s.profile_data.collection.owned_units) do
        local d = C.Units[u.unit_id]
        if d and d.evolve and d.evolve.evolve_unit and not d.evolve.hide_from_ui and C.Units[d.evolve.evolve_unit] then
            local key = (uuid == selected and 1e9 or 0) + (team[uuid] and 1e6 or 0) + (tonumber(u.xp) or 0)
            if not best[u.unit_id] or key > best[u.unit_id].key then best[u.unit_id] = { uuid = uuid, id = u.unit_id, to = d.evolve.evolve_unit, key = key } end
        end
    end
    local rows = {}
    for _, r in pairs(best) do table.insert(rows, r) end
    table.sort(rows, function(a, b) if a.key ~= b.key then return a.key > b.key end; return a.uuid < b.uuid end)
    for _, r in ipairs(rows) do
        local u = s.collection:get_unit_by_uuid(r.uuid)
        local okL, lvl = pcall(C.USC.calculate_level, r.id, u and u.xp or 0)
        table.insert(out, { text = string.format("%s → %s · lvl %d%s", UNIT.name(r.id), UNIT.name(r.to), okL and tonumber(lvl) or 0, team[r.uuid] and " · team" or ""), value = r.uuid })
    end
    return out
end
-- the Home tab's picks: one level of a kind, or the farm's own choice. Only what's open to you is listed (your pick stays on the list)
function GUI.modeOptions(kind)
    local out = {}
    local key = ({ raid = "pickRaid", story = "pickStory", legend = "pickLegend", infinite = "pickInfinite", portal = "pickPortal" })[kind]
    local function addW(order, fn)
        for _, w in ipairs(U.list(order)) do
            local wd = C.Worlds[w]
            for _, a in ipairs(U.list(wd and wd.levels)) do if MODE.open(a.id) then fn(a.id, wd) end end
        end
    end
    if kind == "story" then
        out = { { text = "🤖 Smart: first clears, then farm runs", value = "" }, { text = "📈 Progress: the next map you haven't beaten", value = "progress" } }
        addW(C.WLO.WORLD_ORDER, function(id, wd)
            if not wd.legend_stage and not wd.raid_world then
                for _, diff in ipairs({ "Normal", "Hard" }) do
                    if MODE.diffOpen(id, diff) then table.insert(out, { text = MODE.levelName(id) .. " (" .. diff .. ")", value = "st:" .. id .. ":" .. diff }) end
                end
            end
        end)
    elseif kind == "legend" then
        out = { { text = "🤖 Smart: when it drops what a goal needs", value = "" }, { text = "📈 Progress: the next legend stage you haven't beaten", value = "progress" } }
        addW(C.WLO.LEGEND_WORLD_ORDER, function(id) table.insert(out, { text = MODE.levelName(id), value = "st:" .. id .. ":Hard" }) end)
    elseif kind == "raid" then
        out = { { text = "🤖 Smart: the raid worth the most", value = "" } }
        addW(C.WLO.RAID_WORLD_ORDER, function(id) table.insert(out, { text = MODE.levelName(id), value = "rd:" .. id }) end)
    elseif kind == "infinite" then
        out = { { text = "🤖 Smart: daily gems and takedowns", value = "" } }
        for _, id in ipairs(MODE.infIds()) do if MODE.open(id) then table.insert(out, { text = MODE.levelName(id), value = "inf:" .. id }) end end
    elseif kind == "portal" then
        -- (the kinds you hold first)
        out = { { text = "🤖 Smart: portals whose map drops what your evolutions need", value = "smart" } }
        local rest = {}
        for _, k in ipairs(MODE.portalKinds()) do
            local n = #MODE.portalsHeld(k.pid)
            local o = { text = string.format("%s (%s)%s", k.name, tostring(k.rarity or "?"), n > 0 and (" · you hold " .. n) or ""), value = k.pid }
            table.insert(n > 0 and out or rest, o)
        end
        for _, o in ipairs(rest) do table.insert(out, o) end
    end
    local cur = key and CFG[key] or ""
    local found = false
    for _, o in ipairs(out) do if o.value == cur then found = true end end
    if not found then table.insert(out, { text = "your pick (not open right now)", value = cur }) end
    return out
end
-- this script's own look, on its own copy of the library: other scripts keep theirs
GUI.TITLE = "ANIME ADVENTURES"
function GUI.theme(Lib)
    local c = Lib.Colors
    if type(c) ~= "table" then return end
    local rgb = Color3.fromRGB
    c.bg, c.panel, c.card, c.border = rgb(10, 12, 22), rgb(15, 18, 32), rgb(22, 26, 44), rgb(46, 54, 88)
    c.accent, c.accentD, c.accentBg = rgb(56, 199, 255), rgb(34, 130, 210), rgb(18, 40, 66)
    c.text, c.sub, c.purple = rgb(238, 242, 252), rgb(166, 178, 208), rgb(186, 150, 255)
end
-- what colours alone can't do: a slow glow around the window, the title and the section headers in the same neon
GUI.ON_TOP = 2147483647
-- all four corners round (the user saw only the top right): the side rail and the status bar are square panels, and a window's clipping only cuts a rectangle, so they poked past its curve. They go
-- see-through, and the rail's colour moves into the window's own background, which is the part that follows the curve
function GUI.roundCorners(Win)
    local main = Win._main
    local rail, bar
    for _, f in ipairs(main:GetChildren()) do
        if f:IsA("Frame") then
            if f.Size.X.Scale == 0 and f.Size.Y.Scale == 1 and f.Position.X.Offset == 0 then rail = f end
            if f.Size.X.Scale == 1 and f.Size.Y.Scale == 0 and f.Position.Y.Scale == 1 then bar = f end
        end
    end
    if not (rail and bar and main.Size.X.Offset > 0) then return end
    local edge = rail.Size.X.Offset / main.Size.X.Offset
    local back = main.BackgroundColor3
    local g = Instance.new("UIGradient")
    g.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, rail.BackgroundColor3), ColorSequenceKeypoint.new(edge, rail.BackgroundColor3), ColorSequenceKeypoint.new(edge + 0.0005, back), ColorSequenceKeypoint.new(1, back) })
    main.BackgroundColor3 = Color3.new(1, 1, 1)
    g.Parent = main
    rail.BackgroundTransparency, bar.BackgroundTransparency = 1, 1
end
function GUI.polish(Win)
    -- always on top of the game's own screens, the window and its round button (they share this one; the game's highest is its transition screen, at 9998. The user's call, Nov 1)
    Win._screen.DisplayOrder = GUI.ON_TOP
    GUI.roundCorners(Win)
    local main = Win._main
    local rgb = Color3.fromRGB
    local white = rgb(255, 255, 255)
    local seq = ColorSequence.new({ ColorSequenceKeypoint.new(0, rgb(56, 199, 255)), ColorSequenceKeypoint.new(0.5, rgb(139, 92, 246)), ColorSequenceKeypoint.new(1, rgb(236, 72, 153)) })
    local stroke = main:FindFirstChildOfClass("UIStroke")
    if stroke then
        stroke.Color, stroke.Thickness, stroke.Transparency = white, 2, 0
        local g = Instance.new("UIGradient")
        g.Color = seq
        g.Parent = stroke
        task.spawn(function()
            while SF.alive and main.Parent do
                if main.Visible then g.Rotation = (g.Rotation + 2) % 360 end
                task.wait(0.06)
            end
        end)
    end
    for _, d in ipairs(main:GetDescendants()) do
        if d:IsA("TextLabel") and d.Text == GUI.TITLE then
            d.TextColor3, d.TextSize = white, 15
            local g = Instance.new("UIGradient")
            g.Color = seq
            g.Parent = d
        end
    end
    local accent = (GUI.COL and GUI.COL.accent) or rgb(56, 199, 255)
    for _, td in pairs(Win._tabs or {}) do
        for _, f in ipairs(td.page:GetChildren()) do
            if f:IsA("Frame") and f.Size.Y.Offset == 16 then
                for _, kid in ipairs(f:GetChildren()) do
                    if kid:IsA("Frame") then
                        local lbl = kid:FindFirstChildOfClass("TextLabel")
                        if lbl then
                            lbl.TextColor3, lbl.TextSize = accent, 10
                        else
                            kid.BackgroundColor3 = accent
                            local g = Instance.new("UIGradient")
                            g.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.25), NumberSequenceKeypoint.new(1, 1) })
                            g.Parent = kid
                        end
                    end
                end
            end
        end
    end
end
-- a place between the library's widgets for a card of our own: an emptied section line keeps its spot in the tab's order
function GUI.slot(T)
    local f = T:Section("")
    f:ClearAllChildren()
    f.Size = UDim2.new(1, -10, 0, 0)
    f.AutomaticSize = Enum.AutomaticSize.Y
