GUI.RARITY_COL = { Secret = Color3.fromRGB(255, 99, 146), Mythic = Color3.fromRGB(250, 204, 21), Legendary = Color3.fromRGB(251, 146, 60), Epic = Color3.fromRGB(192, 132, 252), Rare = Color3.fromRGB(96, 165, 250) }
-- the Fuse tab's limit-break picker: units that can still be limit broken, your team first, then the ones at their level cap, then the strongest (at most 60)
function GUI.lbTargetOptions()
    local out = { { text = "Pick a unit", value = "" } }
    local s = C.session()
    if not s then return out end
    local team = {}
    for _, e in ipairs(UNIT.equipped()) do team[e.uuid] = true end
    local rows = {}
    for uuid, u0 in pairs(s.profile_data.collection.owned_units) do
        local u = s.collection:get_unit_by_uuid(uuid) or u0
        local d = C.Units[u.unit_id]
        if d and (d.rarity == "Mythic" or d.rarity == "Secret" or team[uuid] or uuid == CFG.fuseUnit) then
            local okM, max = pcall(C.USC.get_max_limit_break, u)
            local cur = u.further_modifiers and u.further_modifiers.limit_break and tonumber(u.further_modifiers.limit_break.current_limit_break) or 0
            if (okM and (tonumber(max) or 0) > cur) or uuid == CFG.fuseUnit then
                local okS, sc = pcall(UNIT.score, u)
                local lvl, cap = STR.level(u), STR.cap(u)
                table.insert(rows, { uuid = uuid, id = u.unit_id, lvl = lvl, cap = cap, team = team[uuid], sc = okS and sc or 0,
                    key = (uuid == CFG.fuseUnit and 4 or 0) + (team[uuid] and 2 or 0) + (lvl >= cap and 1 or 0) })
            end
        end
    end
    table.sort(rows, function(a, b) if a.key ~= b.key then return a.key > b.key end; if a.sc ~= b.sc then return a.sc > b.sc end; return a.uuid < b.uuid end)
    for i, r in ipairs(rows) do
        if i > 60 then break end
        table.insert(out, { text = string.format("%s · Lv %d/%d%s%s", UNIT.name(r.id), r.lvl, r.cap, r.team and " · team" or "", r.lvl >= r.cap and " · at cap" or ""), value = r.uuid })
    end
    return out
end
-- the fodder table: every unit the game would take, with what it is and what it's worth, ticked by a click. Ticks are CFG.fuseFodder (HUB.fuseInto uses them)
