    GUI.core = T:KeyValue({ "1", "2", "3", "4", "5", "6", "7", "8" }, 230)
    T:Button("🔁", "Pick The Core Units Again", "Your team, your picks, then the attackers the planner used most this week", function()
        local ok, e = pcall(STR.core, true)
        if ok then HUB.last.teamPlan = nil; notify("Team", "Core units picked again") else notify("Team", "Couldn't pick: " .. tostring(e), "error") end
    end)
    T:Section("Levels")
    UI.teamXp = T:Toggle("Level Up With XP Food", "Feeds food to the core unit it helps most, never past its level cap", CFG.teamXp, function(on) setCfg("teamXp", on); HUB.last.teamPlan = nil end)
    UI.teamBuyXp = T:Toggle("Buy XP Food", "The most XP per gold first, only while your units can still take it", CFG.teamBuyXp, function(on) setCfg("teamBuyXp", on) end)
    sld(T, "Gold To Keep", "XP food never takes your gold below this", "xpGoldFloor", { min = 0, max = 2000000, step = 10000, format = big })
    T:Section("Gear")
    UI.teamRelics = T:Toggle("Smart Relics", "Moves relics to where they add the most damage for the team that's playing", CFG.teamRelics, function(on) setCfg("teamRelics", on); HUB.last.teamPlan = nil end)
    UI.teamFuse = T:Toggle("Limit Break Core Units", "Once a core unit is capped and you hold a Divine Wish, by the farm's safe fodder rule. Lists the units it uses for 30 s first. To choose yourself, use the Fuse tab", CFG.teamFuse, function(on) setCfg("teamFuse", on); setCfg("fuseArmSig", ""); HUB.last.teamPlan = nil end)
    T:Section("Advanced")
    UI.strDry = T:Toggle("Dry Run", "Only says what it would do, and spends nothing", CFG.strDry, function(on) setCfg("strDry", on); HUB.last.teamPlan = nil end)
    sld(T, "Gems Per 1% Team Damage", "Higher: it plays XP-rich modes and the Daily Challenge sooner", "strengthValue", { min = 0, max = 2000, step = 50, format = int })

    -- ── Summon: your banner picks ─────────────────────────────────────────────────────────
    T = Win:Tab("🎰", "Summon")
    intro(T, "Summons you choose. Each stays off until you switch it on, and never goes below the Keep lines you set.")
    T:Section("Banner Snipe")
    LIVE.snipe = T:Paragraph("…")
    do
        GUI.lists.snipeUnit = GUI.snipeOptions
        local opts, idx = GUI.snipeOptions(), 1
        for i, o in ipairs(opts) do if o.value == CFG.snipeUnit then idx = i end end
        UI.snipeUnitPick = T:Dropdown("Unit To Snipe", "Featured units first, then every Mythic a banner can give", opts, idx, function(_, v)
            setCfg("snipeUnit", v)
            HUB.last.snipe = nil
        end)
    end
    UI.snipeOn = T:Toggle("Banner Snipe", "Pulls your pick on whichever banner features it, until it drops or a Keep line below. Checks again when the banners turn over, even from a match", CFG.snipeOn, function(on)
        setCfg("snipeOn", on); HUB.last.snipe = nil
    end)
    sld(T, "Gems To Keep", "Banner Snipe never takes your gems below this", "snipeGemFloor", { min = 0, max = 300000, step = 1000, format = big })
