    sld(T, "Safe Road", "Farming is allowed while enemies die before this share of the road", "safeReach", { min = 0.15, max = 0.8, step = 0.05, format = pct })
    sld(T, "Safe Kill Time", "...and while your units would clear the field in this long", "clearSec", { min = 5, max = 60, step = 5, format = function(v) return math.floor(v) .. "s" end })
    sld(T, "Danger Road", "Past this share of the road: damage only, and buy right away", "dangerReach", { min = 0.4, max = 0.95, step = 0.05, format = pct })
    sld(T, "Save Threshold", "Buys now if it's worth this share of the best option, instead of saving", "saveRatio", { min = 0, max = 1, step = 0.05, format = pct })
    T:Button("🧮", "Reset Unit Learning", "Forget measured unit damage", function() table.clear(B.learn); SF.saveNow(); notify("Battle", "learning reset", "success") end)

    -- ── Activity: what it has been doing ──────────────────────────────────────────────────
    T = Win:Tab("📜", "Activity")
    intro(T, "What it has been doing, and where your gold, gems and coins went.")
    T:Section("What each part is doing")
    GUI.systems = T:KeyValue(GUI.SYSTEMS, 84)
    T:Section("Where your gold, gems and coins went")
    LIVE.spend = T:Paragraph("…")
    LIVE.lastMatch = T:Label("…")
    T:Section("Log")
    LIVE.log = T:Paragraph("...")
    LIVE.totals = T:Label("...")
    UI.logLevel = T:Dropdown("Log Level", "Quiet · Normal · Verbose", { "Quiet", "Normal", "Verbose" }, (CFG.logLevel or 1) + 1, function(_, _, i) setCfg("logLevel", math.clamp((tonumber(i) or 2) - 1, 0, 2)) end)
    tog(T, "Print To Console", "Mirrors log lines to the executor console", "logConsole")

    -- ── Settings ──────────────────────────────────────────────────────────────────────────
    T = Win:Tab("⚙️", "Settings")
    intro(T, "Everything else. Settings save by themselves.")
    T:Section("General")
    tog(T, "Anti-AFK", "Sends an input when Roblox flags you idle", "antiAfk")
    tog(T, "Auto Rewards", "Daily login, finished quests, battle pass, milestones", "rewards")
    tog(T, "Redeem Codes", "Promo codes from the guides, at most once a day", "codes")
    tog(T, "Community Tips", "Tier ratings for units the game hides, banner picks, buff chaining", "community")
    T:Section("Gold shop")
    tog(T, "Star Fruits For Gold", "Buys evolve material from the daily gold shop", "goldShop")
    sld(T, "Gold Floor", "Star Fruits never take your gold below this", "goldFloor", { min = 0, max = 2000000, step = 50000, format = big })
    T:Section("Brain Hive: learning together")
    LIVE.hive = T:Paragraph("…")
    UI.useHive = T:Toggle("Learn From Other Players", "Unit readings and training maps from everyone's runs, for what your own runs haven't measured yet", CFG.useHive, function(on)
        setCfg("useHive", on); REPORT.shared = nil; HUB.last.hiveGet = nil
    end)
    if C.WEBHOOK_URL ~= "" then
        UI.shareStats = T:Toggle("Share My Matches", "Anonymous match records, so unit readings and training maps improve for everyone", CFG.shareStats, function(on)
            if on ~= CFG.shareStats then CFG.shareChosen = true end
            setCfg("shareStats", on)
        end)
        T:Paragraph("What is sent: a random id made on this PC (not your name or user id), the script version, and per match the mode and map, "
            .. "win or loss, wave and run time, gems and coins earned, your team (unit kinds, levels, traits, relics, damage, takedowns), "
            .. "where units were placed, and what the simulator expected. No names and no user ids.")
    else
        T:Paragraph("This version sends nothing anywhere: no stats, no suggestions. Everything it learns stays in the AA_SmartFarm folder on your PC.")
    end
    T:Section("Controls")
    T:Button("💾", "Save Settings", "Write " .. C.SETTINGS, function() SF.saveNow(); notify("Saved", "settings written", "success") end)
    T:Button("❌", "Unload", "Stop and remove the window", Color3.fromRGB(239, 68, 68), function() SF.unload() end)

    -- ── Updates ───────────────────────────────────────────────────────────────────────────
    T = Win:Tab("📰", "Updates")
    -- the suggestion box only shows once the script has somewhere to send it
    if C.WEBHOOK_URL ~= "" then
        T:Section("💡 Suggest something for the farm")
        local idea = ""
        local ideaBox = T:Input("Your idea", "Sent anonymously (no Roblox name) · one every 10 min · 500 characters", "e.g. farm the Cursed Womb with my keys…", "", function(text) idea = tostring(text or "") end)
        T:Button("📨", "Send Suggestion", "Goes straight to the script author", function()
            local okG, got = pcall(function() return ideaBox._isProxy and ideaBox:Get() or ideaBox.Get() end)
            if okG and type(got) == "string" and got ~= "" then idea = got end
            task.spawn(function()
                local ok, err = REPORT.suggest(idea)
                notify("Suggestion", ok and "sent — thank you!" or ("not sent: " .. tostring(err)), ok and "success" or "warning")
            end)
        end)
    end
    local TAG_COLOR = { NEW = Color3.fromRGB(74, 222, 128), IMPROVED = Color3.fromRGB(96, 165, 250), FIX = Color3.fromRGB(251, 191, 36) }
    for _, e in ipairs(CHANGELOG) do
        T:Section(string.format("v%s · %s · %s", e.v, e.title, e.date))
        for _, it in ipairs(e.items) do
            T:StatusCard({ icon = it[1], title = it[2], text = it[3], tag = it[4], tagColor = TAG_COLOR[it[4]], color = TAG_COLOR[it[4]] })
        end
    end

    Win:Status(CFG.master and "▶ Farming" or "⏸ Paused")
    -- (the look is a nicety: it never gets in the way of the window)
    local okP, eP = pcall(GUI.polish, Win)
    if not okP then SF.log(1, "ERROR", "window polish: " .. tostring(eP)) end
    if CFG.seenVersion ~= VERSION then
        local first = CFG.seenVersion == nil
        CFG.seenVersion = VERSION
        SF.saveSoon()
        task.delay(first and 8 or 5, function()
            pcall(function() Win:Notify("Updated to v" .. VERSION, CHANGELOG[1].title, 10, "default") end)
        end)
    end
end
GUI.ICONS = { daily = "📅", challenge = "🏆", story = "⚔️", raid = "👹", event = "🃏", infinite = "♾️", dungeon = "🏰" }
-- a brain key ("dc", "ch", "dg", "st:<level>:<diff>", "rd:<level>", "ev:<level>") as a readable name
function GUI.keyName(key)
    if key == "dc" then return "📅 Daily Challenge" end
    if key == "ch" then return "🏆 Challenge" end
    if key == "dg" then return "🏰 Dungeon" end
    local kind, id, diff = tostring(key):match("^(%a+):([^:]+):?(%a*)$")
    if not id then return tostring(key) end
    return (({ st = "⚔️ ", rd = "👹 ", ev = "🃏 ", inf = "♾️ " })[kind] or "") .. MODE.levelName(id) .. ((diff and diff ~= "") and (" " .. diff) or "")
end
function GUI.plainMode(m)
    return string.format("%s · %.0f%% win · ≈%.0f gems/min", m.label, (m.p or 0) * 100, m.score or 0)
end
-- the Up next card. During a first clear the ranking still lists the act being played, since it isn't beaten yet: what comes next is the act after it on Story Only, or else the next best
-- mode, once this one is won
function GUI.upNext(top, second)
    if not top then return "deciding…", "" end
    if SF.where == "match" and top.kind == "story" and top.first and top.key == MT.key then
        local after = "once this act is won. If it's lost, this act again"
        local okN, nxt = pcall(C.PSC.get_next_story_level, top.level)
        if CFG.onlyStory and okN and nxt then return MODE.levelName(nxt) .. " (" .. tostring(top.diff) .. ")", "The next act, " .. after end
        if second then return GUI.plainMode(second), "The next best mode, " .. after end
    end
    return GUI.plainMode(top), top.why or ""
end
function GUI.update()
    local COL = GUI.COL or {}
    local p = C.prof() or {}
    -- Now
    if GUI.nowCard then
        local o
        if not CFG.master then
            o = { icon = "⏸", title = "Paused", text = "Turn Smart Farm on to resume", sub = "", tag = "", progress = false, color = COL.sub }
        elseif SF.where == "match" and MT.ld then
            local label = MODE.levelName(MT.ld.id or "?") .. (MT.ld._difficulty and (" (" .. MT.ld._difficulty .. ")") or "")
            local pr = MT.pressure or 0
            local why = (B.pending and B.pending.key == MT.key and B.pending.label) and "launched by the farm" or "playing this match"
            -- safe / danger against how far your units reach (the same rule the buying uses)
            local d = MT.depth or {}
            local cov = (d.units or 0) > 0 and U.clamp(d.covEnd or 0.6, 0.1, 1) or 0.6
            local danger = d.leak or pr >= math.min(CFG.dangerReach, cov * 0.9)
            local pressured = pr >= math.min(CFG.safeReach, cov * 0.75)
            o = { icon = GUI.ICONS[MT.kind or ""] or "⚔️", title = label, text = tostring(ST.Economy or why),
                sub = string.format("Wave %d/%d · ¥%s · %d enemies · front at %d%% of the road, your units reach %d%% · kills all in %s", MT.wave(), MT.total or 0, U.fmt(MT.money()),
                    #(MT.enemies or {}), math.floor(pr * 100), math.floor(((d.units or 0) > 0 and d.covEnd or 0) * 100),
                    (MT.clearSec or 0) >= 999 and "never" or (math.floor(MT.clearSec or 0) .. "s")),
                tag = d.leak and "LEAK" or (danger and "DANGER" or (pressured and "PRESSURE" or "SAFE")),
                tagColor = danger and COL.red or (pressured and COL.orange or COL.green),
                progress = (MT.total or 0) > 0 and MT.wave() / MT.total or false, color = COL.accent }
        else
            o = { icon = "🏰", title = "In the lobby", text = tostring(ST.Mode or "planning the next run"), sub = tostring(ST.Rewards or ""), tag = "", progress = false, color = COL.accent }
        end
        pcall(GUI.nowCard.Set, o)
        pcall(function() GUI.Win:Status((o.icon or "") .. " " .. tostring(o.title), o.tagColor or o.color) end)
    end
    if GUI.nextCard then
        local top = MODE.lastScored and MODE.lastScored[1]
        if not top and U.now() - (GUI.pickAt or 0) > 15 then GUI.pickAt = U.now(); pcall(MODE.pick); top = MODE.lastScored and MODE.lastScored[1] end
        local lr = B.lastResult
        local got = {}
        if lr then
            if (lr.gems or 0) > 0 then table.insert(got, lr.gems .. " gems") end
            if (lr.coins or 0) > 0 then table.insert(got, lr.coins .. " " .. MODE.coinName()) end
            for k, n in pairs(lr.items or {}) do table.insert(got, string.format("%s×%s", (C.Items[k] and C.Items[k].name) or k, tostring(n))) end
        end
        local upTitle, upText = GUI.upNext(top, MODE.lastScored and MODE.lastScored[2])
        pcall(GUI.nextCard.Set, { icon = "⏭", title = "Up next: " .. upTitle, text = upText,
            sub = lr and ("Last run: " .. lr.text .. (#got > 0 and (" · " .. table.concat(got, ", ")) or "")) or "",
            tag = lr and (lr.won and "WON" or "LOST") or "", tagColor = lr and (lr.won and COL.green or COL.red) or nil })
    end
    if GUI.goals then
        local g = GUI.goals
        pcall(g.Set, "Gems", U.fmt(p.gem_amount), string.format("gold %s", U.fmt(p.gold_amount)), nil, nil)
        local d = B.live.daily
        local dDone = d and d.uuid and (d.uuid == p.last_completed_daily_challenge_uuid or d.uuid == d.doneUuid)
        pcall(g.Set, "Daily Challenge", dDone and "done ✓" or (d and "ready" or "…"), d and string.format("worth ≈%s gems", U.fmt(d.value or 0)) or "", dDone and COL.green or COL.gold, nil)
        local n = B.live.normal
        local nDone = n and n.uuid and (n.uuid == p.last_completed_challenge_uuid or n.uuid == n.doneUuid)
        local mins = n and n.expires and math.max(0, math.floor((n.expires - os.time()) / 60)) or 0
        pcall(g.Set, "Challenge", nDone and "done ✓" or (n and "open" or "…"), n and string.format("new one in %d min", mins) or "", nDone and COL.green or COL.gold, nil)
        local firsts = 0
        for _, m in ipairs(MODE.lastScored or {}) do if m.first then firsts = firsts + 1 end end
        pcall(g.Set, "First Clears Left", tostring(firsts), "acts you can clear for 60 gems now", firsts > 0 and COL.purple or COL.green, nil)
        pcall(g.Set, "Summer Pearls", U.fmt(p.resources and p.resources.SummerPearls or 0), "a Sunny Star costs 150", nil, nil)
        pcall(g.Set, "Record", string.format("%d W · %d L", B.totals.wins or 0, B.totals.losses or 0), string.format("+%s gems by the farm", U.fmt(B.totals.gems or 0)), nil, nil)
    end
    if GUI.systems then
        for _, k in ipairs(GUI.SYSTEMS) do
            local v = ST[k]
            local s = tostring(v or "—")
            pcall(GUI.systems.Set, k, s, (s:find("refused") or s:find("error")) and COL.red or (v and COL.text or COL.sub))
        end
    end
    if GUI.rank then
        local list = MODE.lastScored or {}
        for i = 1, 6 do
            local m = list[i]
            if m then pcall(GUI.rank.Set, "#" .. i, GUI.plainMode(m) .. "\n" .. (m.why or ""), i == 1 and COL.green or COL.text)
            else pcall(GUI.rank.Set, "#" .. i, i == 1 and "no ranking yet" or "", COL.sub, i == 1 and "#1" or "") end
        end
    end
    if GUI.records then
        local rows = {}
        for key, r in pairs(B.modes) do if r.runs > 0 then table.insert(rows, { key = key, r = r }) end end
        table.sort(rows, function(a, b) return (a.r.last or 0) > (b.r.last or 0) end)
        for i = 1, 8 do
            local e = rows[i]
            if e then
                local name = e.key == "dc" and "📅 Daily Challenge" or e.key == "ch" and "🏆 Challenge" or MODE.levelName((e.key:match("^%a+:([^:]+)") or e.key)) .. (e.key:match(":(%a+)$") and (" " .. e.key:match(":(%a+)$")) or "")
                pcall(GUI.records.Set, tostring(i), string.format("%d/%d won · %.1f min avg · %d gems", e.r.wins, e.r.runs, e.r.sec / math.max(1, e.r.runs) / 60, e.r.gems), nil, name)
            else
                pcall(GUI.records.Set, tostring(i), "", nil, i == 1 and "no runs yet" or "")
            end
        end
    end
    if GUI.team then
        local team = UNIT.equipped()
        for i = 1, 6 do
            local e = team[i]
            if e then
                local tr, tier = UNIT.trait(e.u)
                local trName = tr and (C.traitInfo(tr) or {}).name or "no trait"
                local relic = UNIT.relicName(e.u)
                local txt
                if UNIT.isFarm(e.id) then
                    txt = string.format("farm unit · ¥%s a wave at full upgrade · %s%s", U.fmt(UNIT.farm(e.u, UNIT.rows(e.id).max)), trName, tier and tier ~= "1" and (" " .. tier) or "")
                else
                    local types, base = UNIT.types(e.id)
                    local el = {}
                    for t in pairs(types) do if t ~= base then table.insert(el, (t:gsub("_damage", ""))) end end
                    txt = string.format("score %s · %s · up to %d on the field · %s%s%s", U.fmt(UNIT.score(e.u, MT.mod)), trName .. (tier and tier ~= "1" and (" " .. tier) or ""),
                        UNIT.cap(e.u), base, #el > 0 and ("+" .. table.concat(el, "/")) or "", relic and (" · relic: " .. relic) or "")
                end
                pcall(GUI.team.Set, tostring(i), txt, nil, UNIT.name(e.id))
            else
                pcall(GUI.team.Set, tostring(i), "", nil, "")
            end
        end
    end
    if GUI.sim then
        local top = MODE.lastScored and MODE.lastScored[1]
        local sr = top and B.simRes[top.key]
        pcall(GUI.sim.Set, "Next mode", top and (top.label .. ": " .. (sr and (sr.playing or sr.margin) or (sr and sr.none and "can't simulate this one yet") or "not simulated yet")) or "—")
        local key, plan
        for k, v in pairs(B.simTeam) do if not plan or (v.at or 0) > (plan.at or 0) then key, plan = k, v end end
        local yr = plan and B.simRes[key]
        -- (in a run: its own prediction, made on the real map and weather, beside the wave it's really on. Cards can move a Hunt past it)
        local pr = SF.where == "match" and MT.pred
        pcall(GUI.sim.Set, "Your team", pr and string.format("this run: %s wave %d · now wave %d", MT.infinite and (pr.won and "lasts past" or "the base falls at") or (pr.won and "a win at" or "a loss at"), pr.wave, MT.wave())
            or plan and string.format("%s: %s%s", plan.label or key, yr and yr.margin or (plan.cur.won and "wins" or ("reaches wave " .. tostring(plan.cur.wave))), plan.better and " (before the best team went in)" or "") or "the planner runs in the lobby")
        pcall(GUI.sim.Set, "Best team", plan and (table.concat(plan.names or {}, ", ") .. (plan.better and (" → " .. (plan.won and "wins" or ("reaches wave " .. tostring(plan.wave)))) or " (your team is already the best the sim found)")) or "—")
        local evo = {}
        for _, e in ipairs(B.simEvo or {}) do
            table.insert(evo, string.format("%s → %s: %s%s", e.from, e.to, e.gain, e.ready and " · ready" or (e.missing and (" · needs " .. e.missing) or "")))
        end
        pcall(GUI.sim.Set, "Evolutions", #evo > 0 and table.concat(evo, "\n") or "none ready (planner runs in the lobby)")
        local acc = {}
        for k, c in pairs(B.simCal) do
            local lp = c.lastPred
            if lp then table.insert(acc, string.format("%s: predicted %s (wave %d) · real %s (wave %d)", GUI.keyName(k), lp.won and "win" or "loss", lp.wave or 0, lp.realWon and "win" or "loss", lp.realWave or 0)) end
        end
        pcall(GUI.sim.Set, "Accuracy", #acc > 0 and table.concat(acc, "\n") or "no predicted run yet")
    end
    if GUI.path then
        -- (long runs of Next never see the lobby: the list keeps up from here)
        if SF.where == "match" and HUB.every("goalsMatch", 300) then task.spawn(function() pcall(ADV.refresh) end) end
        local focus = GUI.focusNow()
        local smart = focus == "" and ((B.train.on and B.train.on.uuid) or ((B.goals or {})[1] and B.goals[1].uuid)) or nil
        for i = 1, 11 do
            local g = (B.goalsTop or {})[i]
            if g then
                local tag = g.uuid == focus and "🎯 Your focus · " or (g.uuid == smart and "🤖 Smart Play's pick · " or "")
                pcall(GUI.path.Set, tostring(i), tag .. tostring(g.text), g.uuid == focus and COL.gold or (g.ready and not g.hidden and COL.green or (g.intoTeam and COL.purple or ((g.unknown or g.hidden) and COL.sub or COL.text))), UNIT.name(g.to))
            else
                pcall(GUI.path.Set, tostring(i), i == 1 and "goals are worked out in the lobby" or "", COL.sub, i == 1 and "—" or "")
            end
        end
        -- (the picker keeps up with the list, and with a pick made in the Lobby tab)
        if GUI.UI.focusPick and HUB.every("focusList", 3) then
            local opts, sig = GUI.focusOptions(), { focus }
            for _, o in ipairs(opts) do table.insert(sig, tostring(o.text) .. "=" .. tostring(o.value)) end
            sig = table.concat(sig, "|")
            if GUI.focusSig and GUI.focusSig ~= sig then pcall(GUI.UI.focusPick.Refresh, opts, focus) end
            GUI.focusSig = sig
        end
        local ready = {}
        for _, g in ipairs(B.goals) do if g.ready then table.insert(ready, UNIT.name(g.from) .. " → " .. UNIT.name(g.to)) end end
        if GUI.readyLabel then pcall(GUI.readyLabel.Set, #ready > 0 and ("Ready: " .. table.concat(ready, " · ")) or "Nothing ready yet — the farm is collecting the items") end
    end
    local LIVEp = GUI.LIVE
    -- the simple tabs
    if LIVEp.only and HUB.every("onlyText", 2) then
        local top = MODE.lastScored and MODE.lastScored[1]
        local skipped = {}
        for _, why in pairs(MODE.skipped) do table.insert(skipped, "Skipped: " .. why) end
        table.sort(skipped)
        pcall(LIVEp.only.Set, (not MODE.onlyOn() and "Nothing is on Only this, so it plays whatever pays best among the kinds that are On."
            or string.format("Only %s: %s", MODE.onlyText(), top and ("next is " .. top.label)
                or ((CFG.onlyDungeons and (MODE.rec("dg").restUntil or 0) > os.time()) and ("the dungeon is on hold until " .. os.date("%H:%M", MODE.rec("dg").restUntil))
                or "none can be played right now, so it waits (no raid tries left, no new challenge yet, no keys...)")))
            .. (#skipped > 0 and ("\n" .. table.concat(skipped, "\n")) or ""))
    end
    if LIVEp.summonPick and HUB.every("summonText", 3) then pcall(function() LIVEp.summonPick.Set(HUB.summonText()) end) end
    if LIVEp.snipe and HUB.every("snipeText", 5) then pcall(function() LIVEp.snipe.Set(HUB.snipeText()) end) end
    if LIVEp.hive and HUB.every("hiveText", 15) then pcall(function() LIVEp.hive.Set(REPORT.hiveText()) end) end
    -- the Home tab's view of every part, and the Fuse tab's limit break: its card and the fodder table (rebuilt when the units in it change, or at once after a new pick)
    if GUI.homeKv and HUB.every("homeRows", 3) then
        local okH, rows = pcall(GUI.homeRows)
        for _, k in ipairs(GUI.HOME_KEYS) do pcall(GUI.homeKv.Set, k, okH and rows[k] or "…", (okH and tostring(rows[k]):sub(1, 3) == "off") and COL.sub or COL.text) end
    end
    if GUI.lbCard and HUB.every("lbCard", 3) then
        local okL, st = pcall(GUI.lbStatus)
        if okL then pcall(GUI.lbCard.Set, st) end
    end
    -- (in a match only once: your units don't change there, and it goes through all of them)
    if GUI.fodder and (GUI.fodderSig == nil or (SF.where == "lobby" and HUB.every("fodderRows", 15))) then
        local s = C.session()
        local u = s and CFG.fuseUnit ~= "" and s.collection:get_unit_by_uuid(CFG.fuseUnit) or nil
        local okR, rows = pcall(HUB.fodderRows, u)
        rows = okR and rows or {}
        local sig = { tostring(CFG.fuseUnit) }
        for _, r in ipairs(rows) do table.insert(sig, r.uuid .. ":" .. r.pts .. ":" .. #r.flags .. (r.safe and "s" or "")) end
        sig = table.concat(sig, ",")
        if GUI.fodderSig ~= sig then
            GUI.fodderSig = sig
            pcall(GUI.fodder.Refresh, rows, u and "Nothing the game would take for this unit. Locked and equipped units never show." or "Pick a unit to limit break above, and the units it could use show here.")
        else
            pcall(GUI.fodder.summary)
        end
    end
    if LIVEp.hunt and HUB.every("huntText", 5) then pcall(function() LIVEp.hunt.Set(HUNT.text()) end) end
    if LIVEp.skins and HUB.every("skinText", 8) then pcall(function() LIVEp.skins.Set(HUNT.skinText()) end) end
    if LIVEp.fusePick and HUB.every("fuseText", 8) then pcall(function() LIVEp.fusePick.Set(HUB.fuseText()) end) end
    if LIVEp.fuseXpPick and HUB.every("fuseXpText", 8) then pcall(function() LIVEp.fuseXpPick.Set(HUB.fuseXpText()) end) end
    if LIVEp.focus and HUB.every("focusText", 3) then pcall(function() LIVEp.focus.Set(HUB.focusText()) end) end
    -- the Team tab
    if LIVEp.teamNext and HUB.every("teamText", 3) then pcall(function() LIVEp.teamNext.Set(STR.text()) end) end
    if GUI.core and HUB.every("coreRows", 8) then
        local okR, rows = pcall(STR.rows)
        for i = 1, 8 do
            local r = okR and rows[i]
            if r then pcall(GUI.core.Set, tostring(i), r.text, r.text:find("next:") and COL.text or COL.green, r.name)
            else pcall(GUI.core.Set, tostring(i), "", nil, i == 1 and (okR and "no core units yet" or ("error: " .. tostring(rows))) or "") end
        end
    end
    -- the unit lists, when your units changed (a summon, an evolve, a lock, a reroll)
    if SF.where == "lobby" and HUB.every("pickLists", 30) then
        for key, list in pairs(GUI.lists) do
            local okL, opts = pcall(list)
            if okL then
                local sig = {}
                for _, o in ipairs(opts) do table.insert(sig, o.text) end
                sig = table.concat(sig, "|")
                if GUI.listSig[key] and GUI.listSig[key] ~= sig then pcall(GUI.UI[key .. "Pick"].Refresh, opts, CFG[key]) end
                GUI.listSig[key] = sig
            end
        end
    end
    if LIVEp.train then pcall(LIVEp.train.Set, TRAIN.text()) end
    if LIVEp.community and HUB.every("communityText", 30) then pcall(LIVEp.community.Set, ADV.communityText()) end
    if LIVEp.goal and HUB.every("goalText", 5) then pcall(LIVEp.goal.Set, ADV.goalText()) end
    if LIVEp.fh and HUB.every("fhText", 10) then pcall(LIVEp.fh.Set, MT.fhText()) end
    if LIVEp.dungeon and HUB.every("dgText", 5) then pcall(LIVEp.dungeon.Set, DG.text()) end
    if LIVEp.lb then pcall(LIVEp.lb.Set, ADV.lbText()) end
    if GUI.econCard and SF.where == "match" then
        pcall(GUI.econCard.Set, { icon = "💰", title = string.format("¥%s now · farm ¥%s a wave", U.fmt(MT.money()), U.fmt(MT.farmNow or 0)),
            text = tostring(ST.Economy or ""), sub = string.format("coming yen ≈%s · still to buy ≈%s", U.fmt(MT.future or 0), U.fmt(MT.wantLeft or 0)) })
    end
    local LIVE = GUI.LIVE
    if LIVE.spend then pcall(LIVE.spend.Set, SPEND.text()) end
    if LIVE.lastMatch then
        local lm = B.lastMatch
        pcall(LIVE.lastMatch.Set, lm and string.format("Last match (%s): ¥%s spent on %d buys · %d refused spots", lm.label, U.fmt(lm.spent), lm.actions or 0, lm.refusals or 0) or "no match yet")
    end
    if LIVE.log then pcall(LIVE.log.Set, table.concat({ table.unpack(LOG.lines, math.max(1, #LOG.lines - 14)) }, "\n")) end
    if LIVE.totals then pcall(LIVE.totals.Set, string.format("matches %d · wins %d · losses %d · gems %s · event coins %s", B.totals.matches or 0, B.totals.wins or 0, B.totals.losses or 0, U.fmt(B.totals.gems or 0), U.fmt(B.totals.coins or 0))) end
end
function GUI.loop()
    while SF.alive do
        pcall(GUI.update)
        task.wait(1)
    end
end

-- ============================================================
--  START / UNLOAD / HOT RELOAD
-- ============================================================
table.insert(SF.conns, LP.Idled:Connect(function()
    if not CFG.antiAfk then return end
    pcall(function()
        local vu = game:GetService("VirtualUser")
        vu:CaptureController(); vu:ClickButton2(Vector2.new())
    end)
end))
function SF.cleanup()
    for _, c in ipairs(SF.conns) do pcall(function() c:Disconnect() end) end
    pcall(function() GUI.Win:Destroy() end)
    pcall(function() if MT.probe then MT.probe:Destroy() end end)
    pcall(function() if MT.bounds then MT.bounds:Destroy() end end)
end
function SF.unload()
    SF.alive = false
    SF.saveNow()
    pcall(HUB.quietFx, true)
    SF.cleanup()
    _G.AA_SF = nil
end
-- this copy out, this file in: what a teleport does, for a match that restarts without one
function SF.restart()
    local f, e = loadstring(readfile(C.SELF), "=AA_SmartFarm")
    assert(f, e)
    SF.unload()
    f()
end
-- an older copy (e.g. from a hot reload) stops itself as soon as a newer one owns _G.AA_SF
task.spawn(function()
    while SF.alive do
        task.wait(1)
        if _G.AA_SF ~= SF then SF.alive = false; SF.cleanup() end
    end
end)
-- keep running across lobby <-> match teleports: local copy first (your own edits), else the public repo
pcall(function()
    if queue_on_teleport and not _G.AA_SF_QUEUED then
        _G.AA_SF_QUEUED = true
        queue_on_teleport("task.wait(0.5) local s if isfile and isfile('" .. C.SELF .. "') then s=readfile('" .. C.SELF .. "') end "
            .. "if not s then local ok,r=pcall(game.HttpGet,game,'" .. C.SELF_URL .. "') if ok then s=r end end "
            .. "if s then loadstring(s,'=AA_SmartFarm')() end")
    end
end)

SF.C, SF.B, SF.CFG, SF.MT, SF.HUB, SF.ST, SF.UNIT, SF.MODE = C, B, CFG, MT, HUB, ST, UNIT, MODE -- for live inspection
SF.SIM, SF.ECON, SF.GUI, SF.TRAIN, SF.ADV, SF.DG, SF.STR, SF.HUNT = SIM, ECON, GUI, TRAIN, ADV, DG, STR, HUNT
SF.version = VERSION
task.spawn(GUI.build)
task.spawn(function() task.wait(2); GUI.loop() end)
SF.log(1, "INFO", "Smart Farm v" .. VERSION .. " started in the " .. SF.where .. " (copy " .. SF.loadId .. ")")
print("[AA SF] v" .. VERSION .. " loaded in the " .. SF.where .. " · copy " .. SF.loadId)
SF.status("Mode", "starting in the " .. SF.where)
task.spawn(function()
    pcall(HUB.quietFx)
    local ok, e = pcall(SF.where == "match" and MT.run or HUB.run)
    if not ok then SF.log(0, "FATAL", tostring(e)); warn("[AA] " .. tostring(e)) end
end)
